COPLAS_PIEZA(3, [["carrizo_salta-n3062-01",3,"Yo no soy cantor de fama,\nTampoco de abreviatura,\nHombres no me han hecho nada,\n¿Qué vas a hacer criatura?",3,1,0,51,"",0,4,"ua",17,0,-1,0,589,589,"3062","",0,"","","",2,0,0,[],""],["carrizo_salta-n3063-01",3,"Yo no soy cantor de fama,\nTampoco m'h'i ponderar,\nPero si hay quien me lo cante,\nCon gusto le hi contestar.",3,1,0,51,"",0,4,"a",21,0,-1,0,589,589,"3063","",0,"","","",2,0,0,[],""],["carrizo_salta-n3064-01",3,"Yo no soy cantor letrado,\nY si me pongo a cantar,\nMe vuelvo viejo cantando,\nSin tener cuando acabar.",3,1,0,51,"",0,4,"a",21,0,-1,0,590,590,"3064","",0,"","","",2,0,0,[],""],["carrizo_salta-n3065-01",3,"Yo no soy cantor letrao,\nNi cantor de contrapunto,\nCuando yo quiero cantar,\nAunque vengan todos juntos.",3,1,0,51,"",0,4,"uo",-1,0,-1,0,590,590,"3065","",0,"","","",3,0,0,[],""],["carrizo_salta-n3066-01",3,"Yo no soy cantor letrao,\nNi menos soy vencedor,\nPara cantar contrapunto,\nMe considero el mejor.",3,1,0,51,"",0,4,"o",72,0,-1,0,590,590,"3066","",0,"","","",3,0,0,[],""],["carrizo_salta-n3067-01",3,"Yo quisiera ser cebada,\nCortadita en media caña,\n¿Quién había i contrapuntiar,\nCon semejante canalla?",3,1,0,51,"",0,4,"aa",-1,0,-1,0,590,590,"3067","",0,"","","",1,0,0,[],""],["carrizo_salta-n3068-01",3,"Yo soy fulano de tal,\nDel puesto \"El Garrapatal\",\nQuien quiera cantar conmigo,\nPrimero se ha de ensayar.",3,1,0,51,"",0,4,"a",-1,0,-1,0,590,590,"3068","",0,"","","",4,0,0,[],""],["carrizo_salta-n3071-01",3,"A Cupido lo han muerto,\nTras la cocina,\n¡Quién lo mete a Cupido,\nEobar comida!",3,1,0,52,"",6,4,"ia",-1,0,-1,0,592,592,"3071","",0,"","","",2,0,0,[],""],["carrizo_salta-n3072-01",3,"Acuso mi padre santo,\nQue me quise santiguar,\nCon la saliva del loro\nY el zumo del pedernal.",3,1,0,52,"",0,4,"a",-1,0,-1,0,592,592,"3072","",0,"","","",7,0,0,[],""],["carrizo_salta-n3073-01",3,"Acuso mi padre santo,\nQue yo era muy ratero;\nAl ministro de la iglesia,\nLo dejaba sin sombrero.",3,1,0,52,"",0,4,"eo",38,0,-1,0,592,592,"3073","",0,"","","",7,0,0,[],""],["carrizo_salta-n3074-01",3,"¿A dónde han visto poner\nLa calandria tres güevitos,\nA un sastre ser zapatero,\nY yucas comer maicito?",3,1,0,52,"",0,4,"io",-1,0,-1,0,592,592,"3074","",0,"","","",1,0,0,[],""],["carrizo_salta-n3075-01",3,"A esa vieja que vino\nDe \"Los Mogotes\",\nLe han nacío zapallitos\nEn el cogote.",3,1,0,52,"",6,4,"oe",-1,0,-1,0,592,592,"3075","",0,"","","",1,0,0,[],""],["carrizo_salta-n3076-01",3,"Agora sí ya no pito,\nPorque no tengo tabaco.\n¡Padre mío, San Antonio!\n¿Por qué me tenis tan flaco?",3,1,0,52,"",0,4,"ao",423,0,-1,0,592,592,"3076","",0,"","","",1,0,0,[],""],["carrizo_salta-n3078-01",3,"Aguila que vas volando\nPor l'orilla de aquel río,\nEse mozo está cantando\nComo canta el perro mío.",3,1,0,52,"",1,4,"io",3,0,-1,0,592,592,"3078","",0,"","","",10,0,0,[],""],["carrizo_salta-n3079-01",3,"Aguila saquen tus ojos,\nCaranchos el corazón,\nLos cuervos en el ocote,\nTe canten \"kyrie eleisón\".",3,1,0,52,"",0,4,"o",31,0,-1,0,592,592,"3079","",0,"","","",1,0,0,[],""],["carrizo_salta-n3079-a-01",3,"Aguilas saquen tus ojos,\nY cuervos el corazón,\nLas hormigas en el c...\nTe canten \"kyrie eleisón\".",3,1,0,52,"",0,4,"o",31,0,-1,0,592,592,"3079-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3080-01",3,"Ah, mi querido fulano,\nCarita de mula flaca,\nCanillitas de avestruz,\nManitos de paliar aca.",3,1,0,52,"",0,4,"aa",457,0,-1,0,592,592,"3080","",0,"","","",3,0,0,[],""],["carrizo_salta-n3081-01",3,"Al alto cielo subí,\nA preguntarle al fiscal\nSi querer una mujer\nEra causa criminal.",3,1,0,52,"",0,4,"a",1,0,-1,0,592,592,"3081","",0,"","","",6,0,0,[],""],["carrizo_salta-n3082-01",3,"A la mujer del amigo,\nSe la debe enamorar,\nPorque ayudarle a querer\nEs obra de caridad.",3,1,0,52,"",0,4,"a",-1,0,-1,0,593,593,"3082","",0,"","","",1,0,0,[],""],["carrizo_salta-n3088-01",3,"Albricias para los viejos,\nQue ya van a remozar,\nVivirán años perdidos,\nVolverán a enamorar.",3,1,0,52,"",0,4,"a",21,0,-1,0,593,593,"3088","",0,"","","",1,0,0,[],""],["carrizo_salta-n3089-01",3,"Al cabo de tanto andar,\nHi visto lo qu'hi querido,\nHi visto mujer casada,\nSargentiando a su marido.",3,1,0,52,"",0,4,"io",101,0,-1,0,593,593,"3089","",0,"","","",4,0,0,[],""],["carrizo_salta-n3089-a-01",3,"Tanto vivir en el mundo,\nHi visto lo qu'hi querido,\nHi visto mujer casada,\nDormir con otro marido.",3,1,0,52,"",0,4,"io",101,0,-1,0,593,593,"3089-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3090-01",3,"¡Alcalde, corregidor!\nQue prendes a los ladrones,\n¿Cómo no prendes mujeres\nQue roban los corazones?",3,1,0,52,"",0,4,"oe",34,0,-1,0,593,593,"3090","",0,"","","",1,0,0,[],""],["carrizo_salta-n3090-a-01",3,"¡Alcaldes, corregidores!\nQue los prenden a los hombres,\n¿Por qué no prenden mujeres\nCuando roban corazones?",3,1,0,52,"",0,4,"oe",-1,0,-1,0,593,593,"3090-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3091-01",3,"Alfalfa quisiera ser\nSegada con una ichuna,\nPa no volverme a meter\nCon los collas de la Puna.",3,1,0,52,"",1,4,"ua",56,0,-1,0,593,593,"3091","",0,"","","",1,0,0,[],""],["carrizo_salta-n3092-01",3,"Almorzando de mañana,\nY comiendo a medio día,\nMerendando por la noche,\nComo quiera paso el día.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,593,593,"3092","",0,"","","",1,0,0,[],""],["carrizo_salta-n3093-01",3,"Alojita de algarroba,\nDe la vainita amarilla.\nColada en la media sucia,\nGuardada en la bacinilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,593,593,"3093","",0,"","","",2,0,0,[],""],["carrizo_salta-n3094-01",3,"Al olor de la sardina,\nEl pájaro viejo vuela,\nComo no puede gozarla,\nCon el olor se consuela.",3,1,0,52,"",0,4,"ea",167,0,-1,0,594,594,"3094","",0,"","","",1,0,0,[],""],["carrizo_salta-n3095-01",3,"Al'orilla del arroyo,\nCantando está un tero-tero,\nNo canta porque tiene hambre,\nSino por cuidar sus güevos.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,594,594,"3095","",0,"","","",1,0,0,[],""],["carrizo_salta-n3096-01",3,"Al pasar frente a tu puerta,\nTe tiraron un confite,\nY por agacharte a alzarlo,\nSe te reventó el upi..",3,1,0,52,"",5,4,"ui",-1,0,-1,0,594,594,"3096","",0,"","","",1,0,0,[],""],["carrizo_salta-n3097-01",3,"Al pasar por el puente,\nDe calicanto,\nDivisé a mi mujer,\nLe largué el llanto.",3,1,0,52,"",6,4,"ao",30,0,-1,0,594,594,"3097","",0,"","","",9,0,0,[],""],["carrizo_salta-n3098-01",3,"Al pasar por el puente\nDe Santa Elena,\nMe agarraron los gauchos\nDe la melena.",3,1,0,52,"",6,4,"ea",59,0,-1,0,594,594,"3098","",0,"","","",9,0,0,[],""],["carrizo_salta-n3099-01",3,"Al pasar un chaguaral,\nSe me espinaron las patas,\nMe agarré de las coro...\nMe picó una garrapata.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,594,594,"3099","",0,"","","",1,0,0,[],""],["carrizo_salta-n3100-01",3,"Al sapo le di un fusil,\nPor mocito tirador,\nPa que lo mate al zancudo,\nQue andaba de saltiador.",3,1,0,52,"",0,4,"o",72,0,-1,0,594,594,"3100","",0,"","","",1,0,0,[],""],["carrizo_salta-n3101-01",3,"Allá arriba no sé dónde,\nEn casa número tanto,\nSe vende no sé qué cosa,\nY vale yo no sé cuánto.",3,1,0,52,"",0,4,"ao",30,0,-1,0,594,594,"3101","",0,"","","",4,0,0,[],""],["carrizo_salta-n3102-01",3,"Allacito no sé dónde,\nMe convidan a cenar\nUna mazamorra cruda,\nCon las chancuas por volar.",3,1,0,52,"",0,4,"a",21,0,-1,0,594,594,"3102","",0,"","","",1,0,0,[],""],["carrizo_salta-n3103-01",3,"Amalhayas Dios me diera\nUn castigo muy grandote,\nUna tormenta de queso,\nY una creciente de arrope.",3,1,0,52,"",0,4,"oe",-1,0,-1,0,594,594,"3103","",0,"","","",3,0,0,[],""],["carrizo_salta-n3104-01",3,"Amalhayas Dios quisiera,\nQue se muera mi mujer,\nLos caranchos ya están flacos,\nYa no tienen qué comer.",3,1,0,52,"",0,4,"e",20,0,-1,0,594,594,"3104","",0,"","","",3,0,0,[],""],["carrizo_salta-n3105-01",3,"Amalhayas Dios quisiera,\nY me mandara un castigo,\nLa mujer que me aborrezca,\nViniera a dormir conmigo.",3,1,0,52,"",0,4,"io",106,0,-1,0,594,594,"3105","",0,"","","",3,0,0,[],""],["carrizo_salta-n3106-01",3,"Amalhayas Dios quisiera,\nY me mandara un castigo,\nVeinte cargas de aguardiente,\nCuarenta cargas de vino.",3,1,0,52,"",0,4,"io",-1,0,-1,0,594,594,"3106","",0,"","","",3,0,0,[],""],["carrizo_salta-n3107-01",3,"Amalhayas fuera cierto,\nMe mirase esa mujer,\nToda la noche anduviera,\nPegadito a la pared.",3,1,0,52,"",0,4,"e",-1,0,-1,0,594,594,"3107","",0,"","","",1,0,0,[],""],["carrizo_salta-n3108-01",3,"Amalhayas quién se viera\nComo están las quesadillas,\nPoniendo dulce en el medio,\nUno abajo y otro arriba.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,595,595,"3108","",0,"","","",8,0,0,[],""],["carrizo_salta-n3109-01",3,"Amarillas son las liendres,\nDel cuello de tu cotón,\nPobrecitos de los piojos,\nQue mueren sin confesión.",3,1,0,52,"",0,4,"o",31,0,-1,0,595,595,"3109","",0,"","","",2,0,0,[],""],["carrizo_salta-n3110-01",3,"A mi compadrito\nLe quisiera dar,\nSapos estrellados,\nCon unto sin sal.",3,1,0,52,"",0,4,"a",-1,0,-1,0,595,595,"3110","",0,"","","",1,0,0,[],""],["carrizo_salta-n3111-01",3,"A mi don fulano,\nLe quisiera dar,\nMate con bombilla,\nYerba del corral.",3,1,0,52,"",0,4,"a",-1,0,-1,0,595,595,"3111","",0,"","","",1,0,0,[],""],["carrizo_salta-n3112-01",3,"A mí me dicen el osco,\nA mi mujer l'oscarrona,\nA mis hijos los osquitos,\nA mi suegra, osca rabona.",3,1,0,52,"",0,4,"oa",7,0,-1,0,595,595,"3112","",0,"","","",1,0,0,[],""],["carrizo_salta-n3113-01",3,"A mí me dicen el negro,\nPorque quise una donosa,\n¡Cómo no se han de enojar\nPorque quiero buena cosa!",3,1,0,52,"",0,4,"oa",63,0,-1,0,595,595,"3113","",0,"","","",2,0,0,[],""],["carrizo_salta-n3114-01",3,"A mí me dicen el rubio,\nPorque yo quise una rubia,\nA quién no le va a gustar\nBañarse en agua de lluvia.",3,1,0,52,"",0,4,"ua",458,0,-1,0,595,595,"3114","",0,"","","",1,0,0,[],""],["carrizo_salta-n3115-01",3,"A mí me dicen el tonto,\nA mi mujer la tontona,\nA mis hijos los tontitos,\nY a mi suegra, tontarrona.",3,1,0,52,"",0,4,"oa",7,0,-1,0,595,595,"3115","",0,"","","",4,0,0,[],""],["carrizo_salta-n3116-01",3,"A mí me dicen el tonto,\nPorque me falta un sentido,\nMás tarde no anden diciendo,\nEl tanto nos ha j o d...",3,1,0,52,"",5,4,"",-1,0,-1,0,595,595,"3116","",0,"","","",4,0,0,[],""],["carrizo_salta-n3116-02",3,"A mí me dicen el tonto,\nSoy tonto pero alvertido,\nDespués no vaya a decir,\nEl tonto ya me ha j o d...",3,1,0,52,"",5,4,"",-1,0,-1,0,595,595,"3116","",0,"","","",4,0,0,[],""],["carrizo_salta-n3117-01",3,"A mí me dicen las viejas,\nPícaro y escandaloso;\nY les respondo y les digo:\n—Pícaro, pero buenmozo.",3,1,0,52,"",0,4,"oo",156,0,-1,0,595,595,"3117","",0,"","","",1,0,0,[],""],["carrizo_salta-n3118-01",3,"A mí me dicen pichana,\nPrimo hermano de la escoba,\nLa primer mujer que tuve\nLa cambié por algarroba.",3,1,0,52,"",0,4,"oa",298,0,-1,0,595,595,"3118","",0,"","","",1,0,0,[],""],["carrizo_salta-n3119-01",3,"A mí me gusta comer\nQuesitos de zarzo ajeno,\nComerme todo lo bueno,\nDejar el cinchón pal dueño.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,595,595,"3119","",0,"","","",1,0,0,[],""],["carrizo_salta-n3120-01",3,"A mí me han dao de receta,\nLa florcita del desdén,\nCuando quiera, quiera a vieja,\nQue las viejas pagan bien.",3,1,0,52,"",0,4,"e",242,0,-1,0,595,595,"3120","",0,"","","",1,0,0,[],""],["carrizo_salta-n3121-01",3,"A mí me llaman \"El negro\",\nY yo negro quiero ser,\nPorque yo he visto una rubia\nPor un negro padecer.",3,1,0,52,"",0,4,"e",20,0,-1,0,596,596,"3121","",0,"","","",1,0,0,[],""],["carrizo_salta-n3122-01",3,"A mí me llaman \"El tonto\"\nPorque quise una soltera;\n¿A quién no le va a gustar\nComerse una papa entera?",3,1,0,52,"",0,4,"ea",44,0,-1,0,596,596,"3122","",0,"","","",8,0,0,[],""],["carrizo_salta-n3123-01",3,"A mí me llaman \"El zonzo\"\nPorque afilo una casada,\n¿A quién no le va a gustar\nComer una papa asada?",3,1,0,52,"",0,4,"aa",49,0,-1,0,596,596,"3123","",0,"","","",1,0,0,[],""],["carrizo_salta-n3124-01",3,"A mí me toca la ronda,\nY yo la ignoro sabiendo,\nA mí no me vence el sueño,\nToda la noche durmiendo.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,596,596,"3124","",0,"","","",1,0,0,[],""],["carrizo_salta-n3125-01",3,"A mi mula nada le hace,\nNi la calor ni la escarcha,\nPorque es hija del rigor,\nSin las espuelas no marcha.",3,1,0,52,"",0,4,"aa",459,0,-1,0,596,596,"3125","",0,"","","",1,0,0,[],""],["carrizo_salta-n3126-01",3,"Amorcito de afición,\nPerfumado con jazmín,\nSi me quiere yo te doy\nLo que guardas para mí.",3,1,0,52,"",0,4,"i",-1,0,-1,0,596,596,"3126","",0,"","","",1,0,0,[],""],["carrizo_salta-n3127-01",3,"Anda, dile a mi comadre,\nQue me preste el mancarrón,\nPara mandar a la banda\nPor un poco i chicharrón.",3,1,0,52,"",0,4,"o",31,0,-1,0,596,596,"3127","",0,"","","",3,0,0,[],""],["carrizo_salta-n3128-01",3,"Anda, dile a mi comadre\nQue me preste su bozal,\nPa embolazar una pulga\nQue me ha venido a picar.",3,1,0,52,"",0,4,"a",-1,0,-1,0,596,596,"3128","",0,"","","",3,0,0,[],""],["carrizo_salta-n3129-01",3,"Anda, dile a mi comadre\nQue me preste su caballo,\nPa traer un poco de anco,\nEntreverao con zapallo.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,596,596,"3129","",0,"","","",3,0,0,[],""],["carrizo_salta-n3130-01",3,"Andando por los caminos,\nMe decía un elefante:\n—Yo no entiendo logaritmos\nNi pa atrás ni pa adelante.",3,1,0,52,"",0,4,"ae",47,0,-1,0,596,596,"3130","",0,"","","",1,0,0,[],""],["carrizo_salta-n3131-01",3,"Andá y vení volando,\n¡Madrina Juana!\nPollera de abanico,\nCuerpo de iguana.",3,1,0,52,"",6,4,"aa",4,0,-1,0,596,596,"3131","",0,"","","",1,0,0,[],""],["carrizo_salta-n3132-01",3,"¿Ande han visto un moribundo\nCon el cigarro en la boca,\nPreguntándole a las almas\nSi en el cielo venden coca?",3,1,0,52,"",0,4,"oa",178,0,-1,0,596,596,"3132","",0,"","","",1,0,0,[],""],["carrizo_salta-n3133-01",3,"¡Anima que andas penando,\nPor arriba de los montes!\n¿Qué, no te hincan las espinas,\nQue no ponís guardamontes?",3,1,0,52,"",0,4,"oe",460,0,-1,0,596,596,"3133","",0,"","","",1,0,0,[],""],["carrizo_salta-n3134-01",3,"Anoche me enamoré\nDe una muchacha bonita,\nY esta mañana la vi,\nEra tuerta la maldita.",3,1,0,52,"",0,4,"ia",50,0,-1,0,596,596,"3134","",0,"","","",3,0,0,[],""],["carrizo_salta-n3135-01",3,"Anoche me fuí a gatiar,\nMe senté en un chañar solo,\nCasi me moría de susto\nOyendo gritar al zorro.",3,1,0,52,"",0,4,"oo",-1,0,-1,0,597,597,"3135","",0,"","","",1,0,0,[],""],["carrizo_salta-n3136-01",3,"Antes cuando era chiquito,\nCuando chiquito solía,\nLa cara llena i ceniza,\nDe moscas no parecía.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,597,597,"3136","",0,"","","",12,0,0,[],""],["carrizo_salta-n3137-01",3,"Antes cuando era chiquito,\nEntonces cuando era guagua,\nDe canillas de zancudos,\nHacía chifles pa alzar agua.",3,1,0,52,"",0,4,"aa",383,0,-1,0,597,597,"3137","",0,"","","",12,0,0,[],""],["carrizo_salta-n3137-a-01",3,"Señores, les contaré,\nLo que hice cuando era guagua,\nDe la canilla un zancudo,\nHacía chifles pa alzar agua.",3,1,0,52,"",0,4,"aa",383,0,-1,0,597,597,"3137-a","",0,"","","",6,0,0,[],""],["carrizo_salta-n3138-01",3,"Antes cuando era chiquito,\nEra pelao, sin camisa,\nDaba vueltas junto al fuego,\nOmbligo lleno i ceniza.",3,1,0,52,"",0,4,"ia",420,0,-1,0,597,597,"3138","",0,"","","",12,0,0,[],""],["carrizo_salta-n3138-a-01",3,"Antes cuando era chiquito,\nLo pasaba sin camisa,\nEchadito en las conchanas,\nEl pupo lleno i ceniza.",3,1,0,52,"",0,4,"ia",420,0,-1,0,597,597,"3138-a","",0,"","","",12,0,0,[],""],["carrizo_salta-n3139-01",3,"Antes cuando era chiquito\nLo pasaba en la basura;\nLa faldita llena i tierra,\nSin tener quién me sacuda.",3,1,0,52,"",0,4,"ua",-1,0,-1,0,597,597,"3139","",0,"","","",12,0,0,[],""],["carrizo_salta-n3140-01",3,"Antes cuando era chiquito\nMe sabían dar pan y quiso,\nAhora que ya soy grande\nYa no me dan nada de eso.",3,1,0,52,"",5,4,"eo",-1,0,-1,0,597,597,"3140","",0,"","","",12,0,0,[],""],["carrizo_salta-n3141-01",3,"Antes cuando te quería,\nTodo mi gusto era verte,\nAhora que no te quiero,\nNada se me da el perderte.",3,1,0,52,"",0,4,"ee",134,0,-1,0,597,597,"3141","",0,"","","",7,0,0,[],""],["carrizo_salta-n3142-01",3,"Antes cuando yo era mozo,\nY solterito vivía;\nDaba vuelta una camisa,\nY los gorditas mordían.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,597,597,"3142","",0,"","","",4,0,0,[],""],["carrizo_salta-n3143-01",3,"Antes, antiguamente,\nSe usaba el pupo en la frente,\nAhora con tanta mudanza,\nSe lo ha bajado a la panza.",3,1,0,52,"",5,4,"aa",163,0,-1,0,597,597,"3143","",0,"","","",1,0,0,[],""],["carrizo_salta-n3144-01",3,"Antinoche fuí a gatiar,\nAdonde andaba queriendo,\nY fuí y la encontré con otro,\nMe puse las botas viendo.",3,1,0,52,"",3,4,"eo",52,0,-1,0,597,597,"3144","",0,"","","",1,0,0,[],""],["carrizo_salta-n3145-01",3,"Antinoche soñé un sueño,\nAnoche volví a soñar,\nQue en la casa de mi suegra\nEntró el diablo a bellaquiar.",3,1,0,52,"",0,4,"a",21,0,-1,0,597,597,"3145","",0,"","","",2,0,0,[],""],["carrizo_salta-n3146-01",3,"Antenoche soñó un sueño,\nSoñé que te estaba alzando,\nNagua, pollera y camisa,\nDigo, que estaba lavando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,597,597,"3146","",0,"","","",1,0,0,[],""],["carrizo_salta-n3147-01",3,"Aquel que en el prado vistes,\nLlamastes pata de mulo,\nDale besos en el c u..\nY esos son los versos tristes.",3,1,0,52,"",5,4,"ie",91,0,-1,0,598,598,"3147","",0,"","","",1,0,0,[],""],["carrizo_salta-n3148-01",3,"Aquí está, tu cama, chola,\nSi venís sola;\nSi venís acompañada\nNo t'hi convidar con nada.",3,1,0,52,"",3,4,"aa",49,0,-1,0,598,598,"3148","",0,"","","",1,0,0,[],""],["carrizo_salta-n3149-01",3,"Arrimate a la ventana,\nPreguntá quién ha murío,\nDe allá te han de contestar:\n¡La pu.. que te ha parío!",3,1,0,52,"",0,4,"io",3,0,-1,0,598,598,"3149","",0,"","","",2,0,0,[],""],["carrizo_salta-n3150-01",3,"Arrimesén, compañeros,\nLes convidaré tortilla,\nCon harina de cebada,\nCon chicharrón de ladilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,598,598,"3150","",0,"","","",3,0,0,[],""],["carrizo_salta-n3151-01",3,"Arrimesén, compañeros,\nLes convidaré tortilla,\nCon semita y chicharrón\nUntadita en mantequilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,598,598,"3151","",0,"","","",3,0,0,[],""],["carrizo_salta-n3151-a-01",3,"Arrimesén, compañeros,\nLes convidaré tortilla,\nLa harina de cebadilla\nY la grasa de gallina.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,598,598,"3151-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n3152-01",3,"Así me gusta un tirano,\nQue abra la boca y no grite,\nQue se le rompa el u p...\nComo tormenta i verano.",3,1,0,52,"",5,4,"ao",81,0,-1,0,598,598,"3152","",0,"","","",1,0,0,[],""],["carrizo_salta-n3153-01",3,"Así nomás son las viejas,\nCuando tienen que cuidar,\nPrenden una vela grande,\nSe ponen a cabeciar.",3,1,0,52,"",0,4,"a",21,0,-1,0,598,598,"3153","",0,"","","",1,0,0,[],""],["carrizo_salta-n3154-01",3,"A una niña en un baile,\nUn carpintero,\nCreyendo que era tabla,\nLe hizo un aujero.",3,1,0,52,"",6,4,"eo",38,0,-1,0,598,598,"3154","",0,"","","",1,0,0,[],""],["carrizo_salta-n3155-01",3,"Aunque tener muchos hijos,\nEs de gente de ruin laya,\nMe contentaré con pocos,\nA los doce, punto y raya.",3,1,0,52,"",0,4,"aa",404,0,-1,0,598,598,"3155","",0,"","","",1,0,0,[],""],["carrizo_salta-n3156-01",3,"Ayer tarde en medio el monte,\nTopé un carancho volando,\nTraía un turco entre las garras,\nQue se pelaba gritando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,598,598,"3156","",0,"","","",2,0,0,[],""],["carrizo_salta-n3157-01",3,"Ayer tarde pasó un coche,\nCon un gallo de ladero,\nCon un zorrino en las varas\nY un sapo de cadenero.",3,1,0,52,"",0,4,"eo",38,0,-1,0,598,598,"3157","",0,"","","",1,0,0,[],""],["carrizo_salta-n3158-01",3,"Ayer tarde salí al campo,\nCasi me moría de susto,\nHi visto un animal fiero,\nColudo y parecía yuto.",3,1,0,52,"",3,4,"uo",-1,0,-1,0,599,599,"3158","",0,"","","",3,0,0,[],""],["carrizo_salta-n3159-01",3,"Ayer tarde te mandé\nCuatro choclos en costal,\nNo te quise mandar más,\nTemiendo que te haga mal.",3,1,0,52,"",0,4,"a",-1,0,-1,0,599,599,"3159","",0,"","","",2,0,0,[],""],["carrizo_salta-n3160-01",3,"Ayer tarde te mandé,\nTres costillas de una iguana,\nSi no fueras comilón,\nTe duraría una semana.",3,1,0,52,"",0,4,"aa",4,0,-1,0,599,599,"3160","",0,"","","",2,0,0,[],""],["carrizo_salta-n3161-01",3,"¡Ahijuna, juna junando,\nDijo la perdiz volando!\n¿Pa qué me has hecho probar,\nSi no me has de seguir dando?",3,1,0,52,"",0,4,"ao",33,0,-1,0,599,599,"3161","",0,"","","",1,0,0,[],""],["carrizo_salta-n3162-01",3,"¡Ahijuna p u.. el zancudo,\nSe había vuelto labrador!\nCon una yunta i conejos\nY un sapo de melgiador.",3,1,0,52,"",0,4,"o",72,0,-1,0,599,599,"3162","",0,"","","",1,0,0,[],""],["carrizo_salta-n3163-01",3,"¡Ay, mi querida fulana!\nLe haré una pregunta zorra:\n¿Con cuántos granos de maiz\nSe cocina mazamorra?",3,1,0,52,"",0,4,"oa",461,0,-1,0,599,599,"3163","",0,"","","",9,0,0,[],""],["carrizo_salta-n3164-01",3,"¡Ay, qué diabla es la tortuga!\nMeterse de panadera,\nLa chuña soba la masa\nY la rana hace salmuera.",3,1,0,52,"",0,4,"ea",44,0,-1,0,599,599,"3164","",0,"","","",1,0,0,[],""],["carrizo_salta-n3165-01",3,"Bajo de mi cama tengo,\nUna planta de jarilla,\nLa que quiera estar conmigo\nQue se lave las canillas.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,599,599,"3165","",0,"","","",1,0,0,[],""],["carrizo_salta-n3166-01",3,"Bajo de un sauce llorón\nEstaba un sapo desnudo,\nPoniéndose las espuelas\nPa jinetiar un peludo.",3,1,0,52,"",0,4,"uo",191,0,-1,0,599,599,"3166","",0,"","","",2,0,0,[],""],["carrizo_salta-n3167-01",3,"Bajo un árbol solitario,\nMe puse a considerar,\n¡Qué trite se pone un hombre\nCuando no puede engañar!",3,1,0,52,"",0,4,"a",21,0,-1,0,599,599,"3167","",0,"","","",1,0,0,[],""],["carrizo_salta-n3168-01",3,"¡Bien haiga el cielo!\nNo quiere llover,\nPorque tata cura\nYa tiene mujer.",3,1,0,52,"",6,4,"e",20,0,-1,0,599,599,"3168","",0,"","","",1,0,0,[],""],["carrizo_salta-n3169-01",3,"¡Bien haiga la niña linda!\nSi su madre me la diera,\nPara dormir esta noche,\nMañana la devolviera.",3,1,0,52,"",0,4,"ea",44,0,-1,0,599,599,"3169","",0,"","","",1,0,0,[],""],["carrizo_salta-n3170-01",3,"¡Buenos días, si es de día!\nSeñores, ¿cómo les va?\nYo, bueno, para servirlos,\nSin ninguna novedad.",3,1,0,52,"",0,4,"a",-1,0,-1,0,599,599,"3170","",0,"","","",1,0,0,[],""],["carrizo_salta-n3170-01-e2",3,"¡Caballero de fulano!\nCaballero de su casa,\nEn el seno guarda el charqui\nY en la bragueta la grasa.",3,1,0,52,"",0,4,"aa",123,0,-1,0,599,599,"3170","",0,"","","",36,0,0,[],""],["carrizo_salta-n3171-01",3,"¡Caballero de fulano!\n¡Caballero de su casa!\nEn el seno guarda el charqui,\nEn las verijas la grasa.",3,1,0,52,"",0,4,"aa",123,0,-1,0,600,600,"3171","",0,"","","",36,0,0,[],""],["carrizo_salta-n3172-01",3,"¡Caballero de fulano!\nComo usted no hay ningún otro,\nAhora que es mancarrón,\n¿Cómo sería cuando potro?",3,1,0,52,"",0,4,"oo",275,0,-1,0,600,600,"3172","",0,"","","",36,0,0,[],""],["carrizo_salta-n3173-01",3,"¡Caballero de fulano!\n¿Por qué está tan cabizbajo?\nParece carnero viejo,\nQue se viene cuesta abajo.",3,1,0,52,"",0,4,"ao",168,0,-1,0,600,600,"3173","",0,"","","",36,0,0,[],""],["carrizo_salta-n3175-01",3,"¡Caballero de fulano!\nUd. que ha leído cartilla,\nAhora yo lo dedico,\nDe la cusca, la presilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,600,600,"3175","",0,"","","",36,0,0,[],""],["carrizo_salta-n3176-01",3,"¡Caballero de fulano!\nUsted que entiende de letras,\nYo le vengo a preguntar:\n¿Para el amor hay receta?",3,1,0,52,"",0,4,"ea",-1,0,-1,0,600,600,"3176","",0,"","","",36,0,0,[],""],["carrizo_salta-n3177-01",3,"¡Caballero de fulano!\nUsted que entiende el asunto,\nYo le quiero preguntar:\n¿Cómo se para un dijunto?",3,1,0,52,"",0,4,"uo",36,0,-1,0,600,600,"3177","",0,"","","",36,0,0,[],""],["carrizo_salta-n3178-01",3,"Cada vez que te veo\nSe me enderieza,\nLa copa del sombrero,\nEn la cabeza.",3,1,0,52,"",6,4,"ea",108,0,-1,0,600,600,"3178","",0,"","","",6,0,0,[],""],["carrizo_salta-n3179-01",3,"Camino de Santiago,\nVan cuatro frailes,\nTodos llevan alforjas,\nChicas y grandes.",3,1,0,52,"",6,4,"ae",-1,0,-1,0,600,600,"3179","",0,"","","",2,0,0,[],""],["carrizo_salta-n3180-01",3,"¡Caramba mi estomaguito!\nQue lo tengo algo abultao,\nHi comío cuatro quirquinchos\nY dos zapallos asaos.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,600,600,"3180","",0,"","","",1,0,0,[],""],["carrizo_salta-n3181-01",3,"¡Caramba que soy dichoso!\nPa querer mujer casada,\nPor mirar a su marido,\nNo tengo lugar pa nada.",3,1,0,52,"",0,4,"aa",49,0,-1,0,600,600,"3181","",0,"","","",1,0,0,[],""],["carrizo_salta-n3183-01",3,"Ciento cincuenta pesos,\nMe han ofrecido,\nPara ponerle el gorro\nA mi marido.",3,1,0,52,"",6,4,"io",101,0,-1,0,600,600,"3183","",0,"","","",4,0,0,[],""],["carrizo_salta-n3183-a-01",3,"Ciento cincuenta pesos\nNo hi de perder,\nCuernos a mi marido\nLe hi de poner.",3,1,0,52,"",6,4,"e",20,0,-1,0,600,600,"3183-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n3184-01",3,"Cinco, más cinco, son diez,\nLo mismo dijo Don Pancho,\nPeguelé un azote al chancho,\nY verá cómo hace pie.",3,1,0,52,"",5,4,"e",-1,0,-1,0,601,601,"3184","",0,"","","",1,0,0,[],""],["carrizo_salta-n3185-01",3,"Cinco nombres con efe,\nTiene mi dama:\nEs fea, fría, flaca,\nFrágil y falsa.",3,1,0,52,"",6,4,"aa",-1,0,-1,0,601,601,"3185","",0,"","","",2,0,0,[],""],["carrizo_salta-n3186-01",3,"Comiendo se mata el hambre,\nBebiendo se va la sed,\nY enseñando la moneda,\nSe conquista la mujer.",3,1,0,52,"",0,4,"e",-1,0,-1,0,601,601,"3186","",0,"","","",1,0,0,[],""],["carrizo_salta-n3187-01",3,"Como lo tienen las mudas,\nLo tienen las entendidas,\nY nosotros los muchachos\nVamos buscando esa herida.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,601,601,"3187","",0,"","","",1,0,0,[],""],["carrizo_salta-n3188-01",3,"Con buenos modales,\nCon buenas palabras,\nEs como entrar al chiquero\nY predicarle a las cabras.",3,1,0,52,"",0,4,"aa",462,0,-1,0,601,601,"3188","",0,"","","",1,0,0,[],""],["carrizo_salta-n3189-01",3,"Con cáscara de novillo,\nY con garrote de tala,\nLa mujer se vuelve buena,\nPor más endiablada y mala.",3,1,0,52,"",0,4,"aa",330,0,-1,0,601,601,"3189","",0,"","","",1,0,0,[],""],["carrizo_salta-n3190-01",3,"Con el cigarro encendido,\nY el beso de una mujer,\nSoy capaz de mantenerme\nCinco meses sin comer.",3,1,0,52,"",0,4,"e",20,0,-1,0,601,601,"3190","",0,"","","",1,0,0,[],""],["carrizo_salta-n3191-01",3,"Con la grande, compañero,\nPorque la chica es cobarde,\nLa chica quiere por paga,\nLa grande quiere de balde.",3,1,0,52,"",0,4,"ae",-1,0,-1,0,601,601,"3191","",0,"","","",1,0,0,[],""],["carrizo_salta-n3192-01",3,"Con su permiso, señores,\nYo les contaré, primero,\nQue en el pago donde vivo\nHay un burro con sombrero.",3,1,0,52,"",0,4,"eo",38,0,-1,0,601,601,"3192","",0,"","","",7,0,0,[],""],["carrizo_salta-n3193-01",3,"Con sus permisos, señores,\nLes contaré una mentira,\nEn el cerrito de Colte\nSe ha despeñao una hormiga.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,601,601,"3193","",0,"","","",5,0,0,[],""],["carrizo_salta-n3194-01",3,"Con una bella mujer,\nVeinte años me conchabé,\nY durante mi conchabo,\nDoce hijos le trabajé.",3,1,0,52,"",0,4,"e",77,0,-1,0,602,602,"3194","",0,"","","",1,0,0,[],""],["carrizo_salta-n3195-01",3,"Con Ud., querido amigo,\nPaso momentos de gozo,\nDios nunca ha de permitir\nQue Ud. se vuelva potroso.",3,1,0,52,"",0,4,"oo",160,0,-1,0,602,602,"3195","",0,"","","",1,0,0,[],""],["carrizo_salta-n3196-01",3,"Con viuda no me casara,\nNunca, por ningún asunto,\nPor no ponerle la mano\nDonde la puso el difunto.",3,1,0,52,"",0,4,"uo",36,0,-1,0,602,602,"3196","",0,"","","",2,0,0,[],""],["carrizo_salta-n3197-01",3,"Corrió un sapo una carrera\nCon una tortuga vieja,\nChicotearon treinta cuadras,\nGanó el sapo por l'oreja.",3,1,0,52,"",0,4,"ea",165,0,-1,0,602,602,"3197","",0,"","","",1,0,0,[],""],["carrizo_salta-n3198-01",3,"¿Cuál de los gustos es\nEl más chiquito?\n—El de rascarse el cu..\nCon un palito.",3,1,0,52,"",6,4,"io",119,0,-1,0,602,602,"3198","",0,"","","",1,0,0,[],""],["carrizo_salta-n3199-01",3,"Cuando el rico con el pobre,\nEstán en la pulpería,\nLa del pobre es borrachera,\nLa del rico es alegría.",3,1,0,52,"",0,4,"ia",0,0,-1,0,602,602,"3199","",0,"","","",1,0,0,[],""],["carrizo_salta-n3200-01",3,"Cuando eso vido el zancudo,\nSalió refalando el saco,\n¡Salga el que quiera peliarme!\nQue ande me paro me empaco.",3,1,0,52,"",0,4,"ao",423,0,-1,0,602,602,"3200","",0,"","","",1,0,0,[],""],["carrizo_salta-n3201-01",3,"Cuando estaba por morir,\nUn desgraciado pilpinto,\nPara hacer el testamento\nVino de juez un quirquincho.",3,1,0,52,"",0,4,"io",-1,0,-1,0,602,602,"3201","",0,"","","",1,0,0,[],""],["carrizo_salta-n3202-01",3,"Cuando la suerte se inclina,\nEs al cuete hacerse a un lao,\n¡Ándate pa la cocina,\nRevolvelo al estofao!",3,1,0,52,"",1,4,"ao",98,0,-1,0,602,602,"3202","",0,"","","",1,0,0,[],""],["carrizo_salta-n3203-01",3,"¿Cuándo llegaré a ser viejo\nPara ser bien distinguido?\nEntonces dirán las mozas:\n¡Salí, viejo, olor a chivo!",3,1,0,52,"",0,4,"io",-1,0,-1,0,602,602,"3203","",0,"","","",1,0,0,[],""],["carrizo_salta-n3205-01",3,"Cuando me fui para arriba\nLlevé un mosquito de arriero,\nUn champi de capataz\nY un piojo de remeserc.",3,1,0,52,"",5,4,"e",-1,0,-1,0,602,602,"3205","",0,"","","",3,0,0,[],""],["carrizo_salta-n3206-01",3,"Cuando me parió mi madre,\nMe parió en un alto verde,\nVino la partera y dijo:\n—Si éste vive ha i ser alegre.",3,1,0,52,"",0,4,"ee",-1,0,-1,0,602,602,"3206","",0,"","","",8,0,0,[],""],["carrizo_salta-n3206-a-01",3,"Cuando me parió mi madre,\nMe parió en un paño verde,\nEnton's dijo la partera:\n—Esta moza ha i ser alegre.",3,1,0,52,"",0,4,"ee",-1,0,-1,0,602,602,"3206-a","",0,"","","",8,0,0,[],""],["carrizo_salta-n3207-01",3,"Cuando mi suegra murió,\nYo l'enterré en la cocina,\nY de pena que me dió,\nMe puse a bailar encima.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,603,603,"3207","",0,"","","",1,0,0,[],""],["carrizo_salta-n3208-01",3,"Cuando nace una mujer,\nEl diablo no se retira.\nPorque el mandinga les da,\nUna ración de mentira.",3,1,0,52,"",0,4,"ia",372,0,-1,0,603,603,"3208","",0,"","","",1,0,0,[],""],["carrizo_salta-n3209-01",3,"Cuando pasé por tu casa,\nEstaba un cuero colgado,\nYo le dije: ¡Buenas tardes!\nY el cuero quedó callado.",3,1,0,52,"",0,4,"ao",14,0,-1,0,603,603,"3209","",0,"","","",6,0,0,[],""],["carrizo_salta-n3210-01",3,"Cuando pasé por tu casa,\nTe vi lavando los platos,\nY en medio del agua sucia,\nAllí vide tu retrato.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,603,603,"3210","",0,"","","",6,0,0,[],""],["carrizo_salta-n3211-01",3,"Cuando recién me casé,\nMe gustaba gobernar.\nYo también quería saber\n¿De ánde viene y p'ande va?",3,1,0,52,"",0,4,"a",-1,0,-1,0,603,603,"3211","",0,"","","",1,0,0,[],""],["carrizo_salta-n3212-01",3,"Cuando salgo a la calle,\nGrita mamita:\n—Allá va mi muchacho,\n¡Cüidao, chinitas!",3,1,0,52,"",6,4,"ia",-1,0,-1,0,603,603,"3212","",0,"","","",1,0,0,[],""],["carrizo_salta-n3213-01",3,"Cuando salí de mi pago,\nSalí aprendiendo a domar;\nChica era \"La Pampa Grande\"\nPa poderme jinetiar.",3,1,0,52,"",0,4,"a",21,0,-1,0,603,603,"3213","",0,"","","",4,0,0,[],""],["carrizo_salta-n3214-01",3,"Cuando se muera este negro,\nYa no ha de haber gente fiera,\nPorque los negros parecen\nComo brevas en l'higuera.",3,1,0,52,"",0,4,"ea",44,0,-1,0,603,603,"3214","",0,"","","",1,0,0,[],""],["carrizo_salta-n3214-a-01",3,"Cuando se muera fulano,\nYa no ha de haber gente fiera,\nDejará de negreriar,\nComo brevas en la higuera.",3,1,0,52,"",0,4,"ea",44,0,-1,0,603,603,"3214-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n3215-01",3,"Cuando se va entrando el sol,\nSe alegra mi corazón,\nViendo la cama tendida,\nY el tulpo con chicharrón.",3,1,0,52,"",0,4,"o",31,0,-1,0,603,603,"3215","",0,"","","",1,0,0,[],""],["carrizo_salta-n3216-01",3,"Cuando te miré de lejos,\nParecías un lucero,\nAhora que te veo cerca,\n¡Jesús qué animal tan fiero!",3,1,0,52,"",0,4,"eo",38,0,-1,0,604,604,"3216","",0,"","","",1,0,0,[],""],["carrizo_salta-n3217-01",3,"Cuando te parió tu madre,\nTe parió en un cuarto oscuro,\nY te sacaron los diablos\nCon un cencerro en el c u..",3,1,0,52,"",5,4,"u",-1,0,-1,0,604,604,"3217","",0,"","","",7,0,0,[],""],["carrizo_salta-n3218-01",3,"Cuando te parió tu madre,\nTe parió sobre una jerga,\nPor eso todos te dicen:\nChiquitito y pura ver..",3,1,0,52,"",5,4,"e",-1,0,-1,0,604,604,"3218","",0,"","","",7,0,0,[],""],["carrizo_salta-n3219-01",3,"Cuando te parió tu madre,\nTe parió sobre una silla,\nDe ahí te sacaron los perros,\nCreyendo que eras morcilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,604,604,"3219","",0,"","","",7,0,0,[],""],["carrizo_salta-n3220-01",3,"Cuando te parió tu madre,\nTe parió sobre un batión,\nDe ahí te sacaron los gatos,\nCreyendo que eras ratón.",3,1,0,52,"",0,4,"o",31,0,-1,0,604,604,"3220","",0,"","","",7,0,0,[],""],["carrizo_salta-n3221-01",3,"Cuando te parió tu madre,\nTe parió tras de un lagar,\nPor eso todos te dicen:\n—Escupidera i c a g...",3,1,0,52,"",5,4,"",-1,0,-1,0,604,604,"3221","",0,"","","",7,0,0,[],""],["carrizo_salta-n3221-02",3,"Usted nació de su madre,\nNació debajo un talar,\nPor eso muchos le dicen:\n—Bacinilla de cag..",3,1,0,52,"",0,4,"a",-1,0,-1,0,604,604,"3221","",0,"","","",1,0,0,[],""],["carrizo_salta-n3222-01",3,"Cuando te parió tu madre,\nTe parió tras de un tizón,\nPor eso todos te dicen:\n—Hijo de burro rabón.",3,1,0,52,"",0,4,"o",31,0,-1,0,604,604,"3222","",0,"","","",7,0,0,[],""],["carrizo_salta-n3223-01",3,"Cuando vine de Santiago,\nMe vine encima una cabra,\nAl pasar un barrialito\nSe tiró un p... esta diabla.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,604,604,"3223","",0,"","","",1,0,0,[],""],["carrizo_salta-n3224-01",3,"Cuatro frailes franciscanos,\nCuatro del Carmen,\nCuatro de las Victorias,\nSon doce frailes.",3,1,0,52,"",6,4,"ae",-1,0,-1,0,604,604,"3224","",0,"","","",1,0,0,[],""],["carrizo_salta-n3225-01",3,"¿Cuyas son esas gallinas\nQue las quieren cocinar?\n¿Serán tuyas, serán mías?\n¿Serán de la vecindad?",3,1,0,52,"",0,4,"a",-1,0,-1,0,604,604,"3225","",0,"","","",1,0,0,[],""],["carrizo_salta-n3226-01",3,"¡Chacarera, chacarera!\n¡Chacarera de la luna!\n¿Cómo no cuidas tus chacras\nEn la cañada de alguna?",3,1,0,52,"",0,4,"ua",56,0,-1,0,604,604,"3226","",0,"","","",13,0,0,[],""],["carrizo_salta-n3227-01",3,"¡Chacarera, chacarera!\n¡Chacarera de los bajos!\nYo soy dueño de dormir\nPanza arriba o panza abajo.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,604,604,"3227","",0,"","","",13,0,0,[],""],["carrizo_salta-n3228-01",3,"¡Chacarera, chacarera!\n¡Chacarera de Tastil!\nEn mi casa todos paren,\nYo también quiero parir.",3,1,0,52,"",0,4,"i",-1,0,-1,0,604,604,"3228","",0,"","","",13,0,0,[],""],["carrizo_salta-n3229-01",3,"¡Chacarera de los altos!\n¡Chacarera de los bajos!\nTodas las mujeres tienen\nComo taco de guanaco.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,605,605,"3229","",0,"","","",1,0,0,[],""],["carrizo_salta-n3230-01",3,"Chiquitito soy, señores,\n¿Quién me dará de mamar!\nUna que no tenga leche,\nGolpiando l'hi de sacar.",3,1,0,52,"",0,4,"a",21,0,-1,0,605,605,"3230","",0,"","","",2,0,0,[],""],["carrizo_salta-n3231-01",3,"¡Chuy, chuy, chuy!\nQue me hace frío,\nPorque estoy como chumuco\nDesplumao, en medio el río.",3,1,0,52,"",3,4,"io",3,0,-1,0,605,605,"3231","",0,"","","",1,0,0,[],""],["carrizo_salta-n3232-01",3,"¡Dame un besito, vidita,\nQue me voy a confesar,\nY si el cura me regaña,\nYo te lo volveré a dar!",3,1,0,52,"",0,4,"a",21,0,-1,0,605,605,"3232","",0,"","","",1,0,0,[],""],["carrizo_salta-n3233-01",3,"Debajo de un atamiski,\nSe lamentaba un icancho,\nY en sus suspiros decía:\n—¡Mi vida es vida de chancho!",3,1,0,52,"",0,4,"ao",380,0,-1,0,605,605,"3233","",0,"","","",1,0,0,[],""],["carrizo_salta-n3234-01",3,"De Bolivia m'hi venío,\nDispensando ganar plata,\nResulta que me ha salío,\nEl tiro por la culata.",3,1,0,52,"",1,4,"aa",74,0,-1,0,605,605,"3234","",0,"","","",1,0,0,[],""],["carrizo_salta-n3235-01",3,"¿De dónde sale ese mozo,\nTan chiquito y tan panzón?\n—Hijo es de mi yegua vieja,\nNieto de mi mancarrón.",3,1,0,52,"",0,4,"o",31,0,-1,0,605,605,"3235","",0,"","","",1,0,0,[],""],["carrizo_salta-n3236-01",3,"Dejala que no malicie,\nTapala que vaporice,\nCortale la cola al pila,\nPasale por las narices.",3,1,0,52,"",0,4,"ie",-1,0,-1,0,605,605,"3236","",0,"","","",1,0,0,[],""],["carrizo_salta-n3237-01",3,"De lao de arriba hi venío,\nEn un caballo tordillo,\nPrendidito del apero,\nLos dientes como quesillo.",3,1,0,52,"",0,4,"io",228,0,-1,0,605,605,"3237","",0,"","","",2,0,0,[],""],["carrizo_salta-n3238-01",3,"De las novias que tengo,\nMás quiero a Carmen,\nPorque es la que me quiere,\nPara matarme.",3,1,0,52,"",6,4,"ae",-1,0,-1,0,605,605,"3238","",0,"","","",1,0,0,[],""],["carrizo_salta-n3239-01",3,"De la rodilla pa arriba,\nDe la cintura pa abajo,\nCuando dos se quieren bien,\nNo pasan ningún trabajo.",3,1,0,52,"",0,4,"ao",168,0,-1,0,605,605,"3239","",0,"","","",1,0,0,[],""],["carrizo_salta-n3240-01",3,"De los caballos que tengo,\nEl mejor es el gatiao,\nQue a fuerza de espuela y chirlo.\nA un quirquincho lo ha pasao.",3,1,0,52,"",0,4,"ao",98,0,-1,0,605,605,"3240","",0,"","","",2,0,0,[],""],["carrizo_salta-n3241-01",3,"De los caballos que tengo,\nMejor es mi zaino potro,\nPara mudaciar un pié,\nLe pide licencia al otro.",3,1,0,52,"",0,4,"oo",275,0,-1,0,606,606,"3241","",0,"","","",2,0,0,[],""],["carrizo_salta-n3242-01",3,"De los huevos de charata,\nNunca se ha sacado gallos,\nAquel que siembra esperanzas,\nSólo recoge zapallos.",3,1,0,52,"",0,4,"ao",334,0,-1,0,606,606,"3242","",0,"","","",1,0,0,[],""],["carrizo_salta-n3243-01",3,"De mi pago m'hi venío,\nEn busca de mi mestiza,\nAquí la vengo a encontrar,\nRevolcada en la ceniza.",3,1,0,52,"",0,4,"ia",420,0,-1,0,606,606,"3243","",0,"","","",2,0,0,[],""],["carrizo_salta-n3244-01",3,"De mis tiempos cuando mozo,\nSólo me acuerdo de un susto,\nCuando se me quebró el catre,\nEn lo mejor de mis gustos.",3,1,0,52,"",0,4,"uo",-1,0,-1,0,606,606,"3244","",0,"","","",1,0,0,[],""],["carrizo_salta-n3245-01",3,"De mi tierra m'hi venío,\nArrastrando muchas cosas,\nSólo por venirte a ver,\nCara de cuzca babosa.",3,1,0,52,"",0,4,"oa",-1,0,-1,0,606,606,"3245","",0,"","","",2,0,0,[],""],["carrizo_salta-n3246-01",3,"¡De qué le sirve al cura\nLa librería!\nSi en visitar muchachas,\nSe le va el día.",3,1,0,52,"",6,4,"ia",0,0,-1,0,606,606,"3246","",0,"","","",3,0,0,[],""],["carrizo_salta-n3247-01",3,"Desde abajo m'hi venío,\nPor el alto i Tolombón.\nCon una pulga en la cincha,\nY un sapo de redomón",3,1,0,52,"",0,4,"o",31,0,-1,0,606,606,"3247","",0,"","","",11,0,0,[],""],["carrizo_salta-n3248-01",3,"Desde arriba m'hi venío,\nArrastrando mi picote,\nSólo por venirte a ver,\nBragueta con chilicotes.",3,1,0,52,"",0,4,"oe",-1,0,-1,0,606,606,"3248","",0,"","","",17,0,0,[],""],["carrizo_salta-n3249-01",3,"Desde arriba m'hi venío,\nArrastrando mi capote.\nSólo por venirte a ver,\nCarita de pericote.",3,1,0,52,"",0,4,"oe",292,0,-1,0,606,606,"3249","",0,"","","",17,0,0,[],""],["carrizo_salta-n3250-01",3,"Desde arriba m'hi venío,\nEscribiendo en los quebrachos,\nY poniendo este letrero:\n—Freno quieren los muchachos.",3,1,0,52,"",0,4,"ao",463,0,-1,0,606,606,"3250","",0,"","","",17,0,0,[],""],["carrizo_salta-n3251-01",3,"Desde que te conocí,\nPrenda mía, estoy quedando,\nComo el gallo de Morón,\nSin plumas y cacariando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,606,606,"3251","",0,"","","",11,0,0,[],""],["carrizo_salta-n3252-01",3,"Desde mi pago hi venío,\nArrastrando mi chicote.\nSólo por venirte a ver,\nCarachento en el ocote.",3,1,0,52,"",0,4,"oe",292,0,-1,0,606,606,"3252","",0,"","","",6,0,0,[],""],["carrizo_salta-n3253-01",3,"De todos los colores,\nMe gusta el lacre,\nDespués de puesto el gorro,\nNo hay quien lo saque.",3,1,0,52,"",6,4,"ae",-1,0,-1,0,607,607,"3253","",0,"","","",5,0,0,[],""],["carrizo_salta-n3253-02",3,"No hay quien lo saque, sí,\n¡Divino hechizo!\nAlcanzame el pañuelo,\nPor el cañizo.",3,1,0,52,"",6,4,"io",95,0,-1,0,607,607,"3253","",0,"","","",1,0,0,[],""],["carrizo_salta-n3254-01",3,"De vicio venís moniando,\nDiciendo me has de engañar,\n¡Venga tu dueño y te diga:\n—Así te quise pillar!",3,1,0,52,"",0,4,"a",21,0,-1,0,607,607,"3254","",0,"","","",4,0,0,[],""],["carrizo_salta-n3254-a-01",3,"De vicio venís moniando.\nDiciendo me has de engañar,\nLuego me queda el decir,\n¡Así te quise pillar!",3,1,0,52,"",0,4,"a",21,0,-1,0,607,607,"3254-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n3255-01",3,"¿Diande ha salido, señores,\nEste cantar quitifliti?\n¿Por qué no viene a cantar,\nEn la puerta del u p i...?",3,1,0,52,"",5,4,"i",-1,0,-1,0,607,607,"3255","",0,"","","",1,0,0,[],""],["carrizo_salta-n3256-01",3,"¿Diande ha venido este joven?\nDebe ser dueño de estancia,\nParece una chuña flaca\nQue no tiene ni sustancia.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,607,607,"3256","",0,"","","",1,0,0,[],""],["carrizo_salta-n3257-01",3,"Dice mi mama, señora,\nQue tenga unas buenas tardes,\nY por qué no echa los perros,\nAl burro de su compadre.",3,1,0,52,"",0,4,"ae",-1,0,-1,0,607,607,"3257","",0,"","","",1,0,0,[],""],["carrizo_salta-n3258-01",3,"Dicen que los gavilanes,\nSe comen la carne cruda,\nYo también había i comer,\nSi la tuviera segura.",3,1,0,52,"",0,4,"ua",-1,0,-1,0,607,607,"3258","",0,"","","",2,0,0,[],""],["carrizo_salta-n3259-01",3,"Dicen que no caben,\nDos en una mano,\nHagamos la prueba,\nCon un tucumano.",3,1,0,52,"",0,4,"ao",81,0,-1,0,607,607,"3259","",0,"","","",5,0,0,[],""],["carrizo_salta-n3260-01",3,"Dicen que tengo una china,\nQue es más fiera que un sopapo,\nCon los ojos como sapo,\nApretao por una tina.",3,1,0,52,"",11,4,"ia",11,0,-1,0,607,607,"3260","",0,"","","",1,0,0,[],""],["carrizo_salta-n3261-01",3,"Dicen que la Virgen Mária,\nEstá arriba los arbóles,\nEspantando los pajáros,\nQue no coman los mistoles.",3,1,0,52,"",0,4,"oe",27,0,-1,0,607,607,"3261","",0,"","","",1,0,0,[],""],["carrizo_salta-n3262-01",3,"Dicen que las salteñitas,\nPiden antes de morir,\nQue les canten un tonito,\nCon bombo y con violín.",3,1,0,52,"",0,4,"i",-1,0,-1,0,607,607,"3262","",0,"","","",1,0,0,[],""],["carrizo_salta-n3263-01",3,"Dice que no me quiere,\nLa cabezona,\nPorque le ha metío cuentos,\nEl catre i lona.",3,1,0,52,"",6,4,"oa",7,0,-1,0,607,607,"3263","",0,"","","",2,0,0,[],""],["carrizo_salta-n3263-02",3,"Dice que no me quiere,\nLa pelo de oro,\nPorque le ha metió cuentos,\nLa pico i loro.",3,1,0,52,"",6,4,"oo",85,0,-1,0,607,607,"3263","",0,"","","",2,0,0,[],""],["carrizo_salta-n3264-01",3,"Dices que no me quieres,\nPorque no tengo\nUn besito en la boca,\nMe está saliendo.",3,1,0,52,"",6,4,"eo",-1,0,-1,0,607,607,"3264","",0,"","","",15,0,0,[],""],["carrizo_salta-n3265-01",3,"Digamelé a mi comadre.\nQue tenga muy buenos días,\nY si no ha visto pasar,\nUna gallina con cría.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,607,607,"3265","",0,"","","",1,0,0,[],""],["carrizo_salta-n3266-01",3,"Dios que es todo un caballero,\nQueriendo probar fortuna,\nHizo la tierra y la luna,\nY el parque \"Tres de Febrero\".",3,1,0,52,"",11,4,"eo",38,0,-1,0,608,608,"3266","",0,"","","",1,0,0,[],""],["carrizo_salta-n3267-01",3,"Diz que viene el Carnaval,\nPor allá por Cajoncillos,\nTrayendo negocio fuerte,\nDe un lao pierdo el calzoncillo.",3,1,0,52,"",0,4,"io",-1,0,-1,0,608,608,"3267","",0,"","","",1,0,0,[],""],["carrizo_salta-n3268-01",3,"¿Dónde me han visto una vieja,\nQue se vino de Ranchillos?\nTrayendo vino mi vaina,\nPero se olvidó el cuchillo.",3,1,0,52,"",0,4,"io",-1,0,-1,0,608,608,"3268","",0,"","","",1,0,0,[],""],["carrizo_salta-n3269-01",3,"¡Doña Petrona!\n¡Cuídese un poco!\nPara que no le toquen\nEl amor propio.",3,1,0,52,"",6,4,"oo",-1,0,-1,0,608,608,"3269","",0,"","","",1,0,0,[],""],["carrizo_salta-n3270-01",3,"Dos camisitas tengo,\nPara salir a moniar,\nUna que me han ofrecido,\nY otra que me están por dar.",3,1,0,52,"",0,4,"a",21,0,-1,0,608,608,"3270","",0,"","","",1,0,0,[],""],["carrizo_salta-n3271-01",3,"Duerman los que tengan sueño,\nYo los velaré cantando,\nDurmiendo toda la noche,\nToda la noche roncando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,608,608,"3271","",0,"","","",1,0,0,[],""],["carrizo_salta-n3272-01",3,"El buey trabaja con l'asta,\nLa mula con la costilla,\nLa mujer con la cadera,\nY el hombre con la rodilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,608,608,"3272","",0,"","","",1,0,0,[],""],["carrizo_salta-n3273-01",3,"El conejo es regador,\nEl quirquincho el arador,\nLa gallina semillera,\nY el añasco ramiador.",3,1,0,52,"",0,4,"o",72,0,-1,0,608,608,"3273","",0,"","","",3,0,0,[],""],["carrizo_salta-n3273-01-e2",3,"El conejo es regador,\nEl zorro es el rayador,\nLa gallina es semillera,\nEl zorrino es ramiador.",3,1,0,52,"",0,4,"o",72,0,-1,0,608,608,"3273","",0,"","","",3,0,0,[],""],["carrizo_salta-n3274-01",3,"El corazón de una prenda,\nDicen que lo tengo yo,\nEl corazón sin el cuerpo,\n¿Para qué lo quiero yo?",3,1,0,52,"",0,4,"o",-1,0,-1,0,608,608,"3274","",0,"","","",1,0,0,[],""],["carrizo_salta-n3275-01",3,"El corazón se me alegra,\nCuando pienso en matrimonio,\nY sólo pienso en la suegra,\nQue puede ser un demonio.",3,1,0,52,"",1,4,"oo",169,0,-1,0,608,608,"3275","",0,"","","",1,0,0,[],""],["carrizo_salta-n3276-01",3,"El cuervo es un buen campero,\nEl zorro buen remecero,\n¡A la güella! dice el toro,\nApuresén compañeros.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,608,608,"3276","",0,"","","",2,0,0,[],""],["carrizo_salta-n3277-01",3,"El cuervo es un buen campero,\nEl zorro buen remesero,\nSale al campo, pega un grito,\nLe contesta el compañero.",3,1,0,52,"",0,4,"eo",38,0,-1,0,608,608,"3277","",0,"","","",2,0,0,[],""],["carrizo_salta-n3278-01",3,"El cura dijo ¡aleluya!\nPor comerse la gallina,\nEl sacristán dijo ¡amén!\nPor ayudarle a comer.",3,1,0,52,"",5,4,"e",-1,0,-1,0,608,608,"3278","",0,"","","",1,0,0,[],""],["carrizo_salta-n3279-01",3,"El diablo de puca - puca,\nSe metió de sembrador,\nCon una yunta i ratones,\nY un sapo de melguiador.",3,1,0,52,"",0,4,"o",72,0,-1,0,609,609,"3279","",0,"","","",1,0,0,[],""],["carrizo_salta-n3280-01",3,"El día en que yo nací,\nNací entre pañales verdes,\nY me dijo la partera:\n—Este mozo ha i ser alegre.",3,1,0,52,"",0,4,"ee",-1,0,-1,0,609,609,"3280","",0,"","","",3,0,0,[],""],["carrizo_salta-n3281-01",3,"El gato de mi casa,\nDice ¡miau, miau!\nSale la gata y dice:\n—Ya te has quemao.",3,1,0,52,"",6,4,"ao",-1,0,-1,0,609,609,"3281","",0,"","","",2,0,0,[],""],["carrizo_salta-n3282-01",3,"El gato de mi casa,\nEs muy decente,\nTiene la boca chica,\nMaimanta dientes.",3,1,0,52,"",6,4,"ee",-1,0,-1,0,609,609,"3282","",0,"","","",2,0,0,[],""],["carrizo_salta-n3283-01",3,"El hombre que llega a viejo,\nEnamorao y celoso,\nBien se le puede llamar:\n—La carabina de Ambrosio.",3,1,0,52,"",0,4,"oo",-1,0,-1,0,609,609,"3283","",0,"","","",3,0,0,[],""],["carrizo_salta-n3283-a-01",3,"Hombre feo y sin dinero,\nEnamorao y celoso,\nEsto se llama en mi tierra:\n—La carabina de Ambrosio.",3,1,0,52,"",0,4,"oo",-1,0,-1,0,609,609,"3283-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n3284-01",3,"El hombre que anda queriendo,\nSe pasa de centinela,\nSe le derraman las babas,\nSin que le duelan las muelas.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,609,609,"3284","",0,"","","",1,0,0,[],""],["carrizo_salta-n3285-01",3,"El mozo que a mí me quiera,\nMe ha de querer a mí sola,\nY si tiene amor con otra,\nLe ataré un cuero en la cola.",3,1,0,52,"",0,4,"oa",-1,0,-1,0,609,609,"3285","",0,"","","",1,0,0,[],""],["carrizo_salta-n3286-01",3,"El quirquincho y el zorrino,\nSe pusieron a bailar,\nEl quirquincho a escobillar,\nY el zorrino a zapatiar.",3,1,0,52,"",0,4,"a",21,0,-1,0,610,610,"3286","",0,"","","",1,0,0,[],""],["carrizo_salta-n3287-01",3,"El sombrero de castor,\nCon botines y polainas,\nCon la sangre de cordero\nSe hace una linda chanfaina.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,610,610,"3287","",0,"","","",1,0,0,[],""],["carrizo_salta-n3288-01",3,"El sordo le dice al ciego:\n—Mira la araña que vá.\nResponde el ciego y le dice:\n—Oye los pasos que da.",3,1,0,52,"",0,4,"a",9,0,-1,0,610,610,"3288","",0,"","","",1,0,0,[],""],["carrizo_salta-n3289-01",3,"El zorro con el quirquincho,\nCorrieron una carrera,\nEl zorro en un avestruz,\nEl quirquincho en una perra.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,610,610,"3289","",0,"","","",1,0,0,[],""],["carrizo_salta-n3290-01",3,"El zorro se fué con lazo,\nY el zorrino con bozal,\nEl sapo los atajó,\nLa rana les echó un pial.",3,1,0,52,"",0,4,"a",1,0,-1,0,610,610,"3290","",0,"","","",1,0,0,[],""],["carrizo_salta-n3291-01",3,"Enamoré una mujer,\nPicadita de viruelas,\nYo l'enamoré jugando,\nY ella me quiso de veras.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,610,610,"3291","",0,"","","",1,0,0,[],""],["carrizo_salta-n3293-01",3,"En el cerrito de Colte,\nSe ha despeñado una hormiga,\nSe ha falseado la rodilla,\nSe ha quebrado la canilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,610,610,"3293","",0,"","","",1,0,0,[],""],["carrizo_salta-n3294-01",3,"En el fondo de la mar,\nSuspiraba un suruví,\nY en el suspiro pedía:\nPa tu u p... un real de ají.",3,1,0,52,"",0,4,"i",23,0,-1,0,610,610,"3294","",0,"","","",9,0,0,[],""],["carrizo_salta-n3295-01",3,"En el pueblo de Cerrillos,\nSe ha formado un batallón,\nDe puras niñas bonitas,\nLa geta como acordión.",3,1,0,52,"",0,4,"o",31,0,-1,0,610,610,"3295","",0,"","","",1,0,0,[],""],["carrizo_salta-n3296-01",3,"En este correo pasado,\nLlegó carta de Milán,\nDiz que el cura está preñado,\nY ha parido el sacristán",3,1,0,52,"",1,4,"a",147,0,-1,0,610,610,"3296","",0,"","","",1,0,0,[],""],["carrizo_salta-n3297-01",3,"En este lugar sagrado,\nDonde acude tanta gente,\nHace más fuerza el más cobarde,\nY se ca.. el más valiente.",3,1,0,52,"",0,4,"ee",15,0,-1,0,610,610,"3297","",0,"","","",1,0,0,[],""],["carrizo_salta-n3298-01",3,"En este tiempo estoy viejo,\nAndoy las canas voltiando,\n¡Pobrecitos mis hijitos,\nCana por cana juntando!",3,1,0,52,"",0,4,"ao",33,0,-1,0,611,611,"3298","",0,"","","",1,0,0,[],""],["carrizo_salta-n3299-01",3,"En la Bajada el Desprecio,\nSe ha despeñado un cordero,\nHabía sido desgraciado,\nPorque había nacido overo.",3,1,0,52,"",0,4,"eo",38,0,-1,0,611,611,"3299","",0,"","","",1,0,0,[],""],["carrizo_salta-n3300-01",3,"En la cara tengo pecas,\nSoy picada de viruela,\nFiera sin comparación,\nMala traza sin agüela.",3,1,0,52,"",0,4,"ea",167,0,-1,0,611,611,"3300","",0,"","","",3,0,0,[],""],["carrizo_salta-n3301-01",3,"En la cara traigo pecas.\nY un lunar en el bigote,\nEn la barba pelos blancos,\nY una pulga en el cogote.",3,1,0,52,"",0,4,"oe",292,0,-1,0,611,611,"3301","",0,"","","",1,0,0,[],""],["carrizo_salta-n3302-01",3,"En la Costa del Pasaje,\nHa pasado una avería,\nAhí le golpiaron los cueros,\nA una prima hermana mía.",3,1,0,52,"",0,4,"ia",0,0,-1,0,611,611,"3302","",0,"","","",1,0,0,[],""],["carrizo_salta-n3303-01",3,"En la falda de aquel cerro,\nEstá una hormiga con cría,\nPidiendo misericordia,\nA Dios y a Santa Lucía.",3,1,0,52,"",0,4,"ia",0,0,-1,0,611,611,"3303","",0,"","","",54,0,0,[],""],["carrizo_salta-n3304-01",3,"En la falda de aquel cerro,\nLindo juegan las tamberas,\nEn la falda la camisa,\nLos piojos juegan carrera.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,611,611,"3304","",0,"","","",54,0,0,[],""],["carrizo_salta-n3305-01",3,"En la falda de aquel cerro,\nMaté un ratón de un guantón,\nLa carne pa mi patrón,\nY el cuero pa mi cotón.",3,1,0,52,"",0,4,"o",31,0,-1,0,611,611,"3305","",0,"","","",54,0,0,[],""],["carrizo_salta-n3306-01",3,"En la falda de aquel cerro,\nSuspiraba una corzuela,\nY en el suspiro decía,\nAndá cantale a tu agüela.",3,1,0,52,"",0,4,"ea",167,0,-1,0,611,611,"3306","",0,"","","",54,0,0,[],""],["carrizo_salta-n3308-01",3,"En la falda de aquel cerro,\nTengo una planta i charcoma,\nPa esconder a mi vidita,\nCabeza i yegua chascona.",3,1,0,52,"",0,4,"oa",-1,0,-1,0,611,611,"3308","",0,"","","",54,0,0,[],""],["carrizo_salta-n3309-01",3,"En la falda de aquel cerro,\nTengo una planta i jarilla,\nLa mujer que a mí me quiera,\nSe ha de lavar las canillas.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,611,611,"3309","",0,"","","",54,0,0,[],""],["carrizo_salta-n3310-01",3,"En la falda de aquel cerro,\nTengo una vaina de plata,\nPor esa, llama a tu mama,\nPor la mañana, tu tata",3,1,0,52,"",0,4,"aa",-1,0,-1,0,612,612,"3310","",0,"","","",54,0,0,[],""],["carrizo_salta-n3311-01",3,"En la falda de aquel cerro,\nTengo un caballo matac,\nLos perros me lo comieron,\nCreyendo charqui mojao.",3,1,0,52,"",5,4,"ao",-1,0,-1,0,612,612,"3311","",0,"","","",54,0,0,[],""],["carrizo_salta-n3311-a-01",3,"En la falda de aquel cerro,\nTengo un caballo matao,\nPara darle a mi vidita,\nDiciendo charqui mojao",3,1,0,52,"",0,4,"ao",98,0,-1,0,612,612,"3311-a","",0,"","","",54,0,0,[],""],["carrizo_salta-n3312-01",3,"En la falda de aquel cerro,\nTengo un jabón oloroso.\nPara lavarte la cara,\nPorque estás muy lagañoso.",3,1,0,52,"",0,4,"oo",160,0,-1,0,612,612,"3312","",0,"","","",54,0,0,[],""],["carrizo_salta-n3313-01",3,"En la falda de aquel cerro,\nUn caranche está escarbando,\nLlega el chimango y le dice:\n¡Caranche! ¿qué estás robando?",3,1,0,52,"",0,4,"ao",33,0,-1,0,612,612,"3313","",0,"","","",54,0,0,[],""],["carrizo_salta-n3314-01",3,"En la falda de aquel cerro,\nUn zorro estaba cag...,\nPara Vd. mi don Fulano,\nPara Vd. le estoy cantando.",3,1,0,52,"",5,4,"ao",-1,0,-1,0,612,612,"3314","",0,"","","",54,0,0,[],""],["carrizo_salta-n3315-01",3,"En la falda de aquel cerro,\nYo tengo una chancha loca,\nLas veces que ella se c a g...\nEs pa tu boca.",3,1,0,52,"",3,4,"oa",178,0,-1,0,612,612,"3315","",0,"","","",54,0,0,[],""],["carrizo_salta-n3316-01",3,"En la falda de aquel cerro,\nYo tengo una vaca overa,\nCuando quiero tomar té,\nNo encuentro la coladera.",3,1,0,52,"",0,4,"ea",44,0,-1,0,612,612,"3316","",0,"","","",54,0,0,[],""],["carrizo_salta-n3317-01",3,"En la orilla del río,\nTopé una chuña,\nEstriberos de plata,\nPoncho i vicuña.",3,1,0,52,"",6,4,"ua",456,0,-1,0,612,612,"3317","",0,"","","",3,0,0,[],""],["carrizo_salta-n3318-01",3,"En la patria soy nacido,\nPor la patria hi de morir,\nEn la cama de mi suegra,\nAbrazado hi de dormir.",3,1,0,52,"",0,4,"i",157,0,-1,0,612,612,"3318","",0,"","","",1,0,0,[],""],["carrizo_salta-n3319-01",3,"En la plaza de Santiago,\nOí cantar un quitilipe,\nLos santiagueños creyeron,\nQue cantaba San Felipe,",3,1,0,52,"",0,4,"ie",464,0,-1,0,612,612,"3319","",0,"","","",4,0,0,[],""],["carrizo_salta-n3319-a-01",3,"En la playa de Santiago,\nRebuznaba un quitilipi.\nLos santiagueños decían:\n¡Nuestro padre, San Felipe!",3,1,0,52,"",5,4,"ie",-1,0,-1,0,612,612,"3319-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n3320-01",3,"En la playa de Santiago,\nRebuznaba un burro pardo;\nLos santiagueños decían:\n¡Nuestro padre, San Bernardo!",3,1,0,52,"",0,4,"ao",210,0,-1,0,612,612,"3320","",0,"","","",2,0,0,[],""],["carrizo_salta-n3321-01",3,"En la provincia i Santiago,\nCasi me morí de risa,\nToditos los santiagueños,\nEspulgaban la camisa.",3,1,0,52,"",0,4,"ia",68,0,-1,0,612,612,"3321","",0,"","","",2,0,0,[],""],["carrizo_salta-n3322-01",3,"En la provincia i Santiago,\nHubo una revolución,\nPorque pusieron patente,\nA la algarroba y mistol",3,1,0,52,"",0,4,"o",-1,0,-1,0,613,613,"3322","",0,"","","",2,0,0,[],""],["carrizo_salta-n3323-01",3,"En la puerta el infierno,\nVive mi suegra;\nPorque no tengo un burro,\nNo voy a verla.",3,1,0,52,"",6,4,"ea",-1,0,-1,0,613,613,"3323","",0,"","","",1,0,0,[],""],["carrizo_salta-n3324-01",3,"En la puerta de mi casa.\nPlanté de tuitos tamaños,\nEl que siembra una esperanza,\nNunca cosecha zapallos.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,613,613,"3324","",0,"","","",24,0,0,[],""],["carrizo_salta-n3325-01",3,"En la puerta de mi casa,\nTengo una planta de ají,\nPara comer con iguana,\nCuando se me antoje a mí.",3,1,0,52,"",0,4,"i",23,0,-1,0,613,613,"3325","",0,"","","",24,0,0,[],""],["carrizo_salta-n3326-01",3,"En la rama de un olivo,\nEstaba un sapo sentao,\nCon un cigarro en la boca\nFirmando un certificao.",3,1,0,52,"",0,4,"ao",98,0,-1,0,613,613,"3326","",0,"","","",3,0,0,[],""],["carrizo_salta-n3327-01",3,"En las calles de Tarija,\nCasi me morí de risa,\nViendo peliar dos gallegos,\nCon corbata y sin camisa.",3,1,0,52,"",0,4,"ia",68,0,-1,0,613,613,"3327","",0,"","","",1,0,0,[],""],["carrizo_salta-n3328-01",3,"En una peña terrible,\nSe descubrió una vertiente,\nY en una montaña espesa,\nSe mantiene una serpiente.",3,1,0,52,"",0,4,"ee",15,0,-1,0,613,613,"3328","",0,"","","",1,0,0,[],""],["carrizo_salta-n3329-01",3,"Es la mujer soltera,\nSuave y prolija,\nPero apenas casada,\nPapel de lija.",3,1,0,52,"",6,4,"ia",219,0,-1,0,613,613,"3329","",0,"","","",1,0,0,[],""],["carrizo_salta-n3330-01",3,"Esta noche va a llover,\nSegún anuncia la luna,\nUna tormenta de truenos,\nEn la cañada de alguna.",3,1,0,52,"",0,4,"ua",56,0,-1,0,613,613,"3330","",0,"","","",6,0,0,[],""],["carrizo_salta-n3331-01",3,"Es tanta la complacencia,\nQue recibo de tu agrado,\nQue cuando te veo me ca...\nEn vuestra augusta presencia.",3,1,0,52,"",5,4,"ea",46,0,-1,0,613,613,"3331","",0,"","","",1,0,0,[],""],["carrizo_salta-n3332-01",3,"Es tanto lo que te quiero,\nY con tanto disimulo,\nQue lloro por la nariz,\nY suspiro por el c u...",3,1,0,52,"",5,4,"u",-1,0,-1,0,613,613,"3332","",0,"","","",26,0,0,[],""],["carrizo_salta-n3333-01",3,"Este año pa carnaval,\nVoy hacer una avería,\nVoy a carniar un zancudo,\nPa poner carnicería.",3,1,0,52,"",0,4,"ia",0,0,-1,0,613,613,"3333","",0,"","","",22,0,0,[],""],["carrizo_salta-n3334-01",3,"Este es el remate,\nDe Gaspar Medrano,\n¡Qué le importa a un argentino,\nQue se joda un boliviano!",3,1,0,52,"",0,4,"ao",81,0,-1,0,613,613,"3334","",0,"","","",4,0,0,[],""],["carrizo_salta-n3335-01",3,"Esto de amar niñas bellas,\nEs ayunar al traspaso,\nYo con mi negra lo paso,\nQue tiene lo mismo que ellas.",3,1,0,52,"",11,4,"ea",89,0,-1,0,613,613,"3335","",0,"","","",1,0,0,[],""],["carrizo_salta-n3336-01",3,"Flores me dan de comer,\nFlores me dan de beber,\nFlores a la media noche,\nFlores al amanecer.",3,1,0,52,"",0,4,"e",20,0,-1,0,614,614,"3336","",0,"","","",1,0,0,[],""],["carrizo_salta-n3337-01",3,"¡Fulanita, soy fulano!\nFulano de corta fama,\nDe balde me hago el chiquillo,\nPara llegar a tu cama.",3,1,0,52,"",0,4,"aa",90,0,-1,0,614,614,"3337","",0,"","","",1,0,0,[],""],["carrizo_salta-n3338-01",3,"Genitivo cuyuque,\nDativo cuique,\nAquel que no te entienda,\nQue te lo explique.",3,1,0,52,"",6,4,"ie",311,0,-1,0,614,614,"3338","",0,"","","",1,0,0,[],""],["carrizo_salta-n3339-01",3,"Hace decir mi abuelita.\nQue le preste su corral.\nPara encerrar un zancudo,\nQue se la ha ido con bozal.",3,1,0,52,"",0,4,"a",1,0,-1,0,614,614,"3339","",0,"","","",1,0,0,[],""],["carrizo_salta-n3340-01",3,"Hace decir mi mamita,\nQue le preste un maniador,\nPa maniar un suricito,\nQue ha salido patiador.",3,1,0,52,"",0,4,"o",72,0,-1,0,614,614,"3340","",0,"","","",1,0,0,[],""],["carrizo_salta-n3341-01",3,"Hace rato que t' hi visto,\nLa camisa coloriando;\nAquí me vas a avisar,\n¡Con quién has andao peliando!",3,1,0,52,"",0,4,"ao",33,0,-1,0,614,614,"3341","",0,"","","",1,0,0,[],""],["carrizo_salta-n3342-01",3,"Hace tiempo que no como,\nMe tiene abatido el hambre,\nMe pongo en las piernas plomo,\nPorque no me lleve el aire.",3,1,0,52,"",0,4,"ae",-1,0,-1,0,614,614,"3342","",0,"","","",1,0,0,[],""],["carrizo_salta-n3343-01",3,"¿Han visto bailar un piojo\nSobre un adobe?\nEn caso de batalla,\n¡Pela el revólver!",3,1,0,52,"",6,4,"oe",-1,0,-1,0,614,614,"3343","",0,"","","",1,0,0,[],""],["carrizo_salta-n3344-01",3,"Hasta jeringa tiene,\nQuien tiene suegra,\nY si tiene cuñada,\nJeringa y media.",3,1,0,52,"",6,4,"ea",-1,0,-1,0,614,614,"3344","",0,"","","",1,0,0,[],""],["carrizo_salta-n3345-01",3,"Hay conchas que son de concha,\nY conchas que son de piedra,\nPero Vd. don Escolástico,\nHabía sio concha de mi er...",3,1,0,52,"",5,4,"e",-1,0,-1,0,614,614,"3345","",0,"","","",1,0,0,[],""],["carrizo_salta-n3346-01",3,"Inocente, sin saber,\nMe metí en un chaguaral,\nPor atrás de un hosco yuto,\nOrejano de señal.",3,1,0,52,"",0,4,"a",1,0,-1,0,614,614,"3346","",0,"","","",1,0,0,[],""],["carrizo_salta-n3347-01",3,"¡Jesús, qué algarabía!\n¡Jesús, qué tanto alboroto!\n¡Quién la mete a mi María,\nComerse tanto poroto!",3,1,0,52,"",1,4,"oo",465,0,-1,0,614,614,"3347","",0,"","","",1,0,0,[],""],["carrizo_salta-n3348-01",3,"Justo me debe unos pesos,\nY a Justo le debo yo,\nJusto me ajusta su cuenta,\nY a Justo le ajusto yo.",3,1,0,52,"",0,4,"o",-1,0,-1,0,614,614,"3348","",0,"","","",1,0,0,[],""],["carrizo_salta-n3349-01",3,"La araña diz que se ha muerto,\nEstando urdiendo su tela,\nAhora l'estamos velando;\nPoniendo las cuatro velas.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,614,614,"3349","",0,"","","",1,0,0,[],""],["carrizo_salta-n3350-01",3,"La calandria está preñada,\nDicen que va a parir tres:\nUn sastre, un zapatero,\nY un cirujano francés,",3,1,0,52,"",0,4,"e",218,0,-1,0,614,614,"3350","",0,"","","",1,0,0,[],""],["carrizo_salta-n3351-01",3,"La desgracia de los negros,\nNo es tener la piel oscura,\nLa desgracia de los negros,\nEs querer a mujer rubia.",3,1,0,52,"",0,4,"ua",-1,0,-1,0,614,614,"3351","",0,"","","",1,0,0,[],""],["carrizo_salta-n3366-01",3,"La vieja de mi suegra;\nMe dió unas medias;\nCada vez que peliamos.\nMe da con ellas.",3,1,0,52,"",6,4,"ea",-1,0,-1,0,616,616,"3366","",0,"","","",9,0,0,[],""],["carrizo_salta-n3367-01",3,"La vieja es buena comida,\nSabiéndola sazonar,\nUna vez probé una vieja,\n¡Puta que me hizo gustar!",3,1,0,52,"",0,4,"a",21,0,-1,0,616,616,"3367","",0,"","","",1,0,0,[],""],["carrizo_salta-n3368-01",3,"La vieja que tiene una hija,\nY se casa ligero,\nSe queda la pobre vieja,\nComo palo i gallinero.",3,1,0,52,"",0,4,"eo",38,0,-1,0,616,616,"3368","",0,"","","",1,0,0,[],""],["carrizo_salta-n3369-01",3,"¡Levantate, bandolera!\nTomá un traguito sabroso,\nHecho con agua del pozo,\nY alcohol de la cafetera",3,1,0,52,"",3,4,"ea",44,0,-1,0,616,616,"3369","",0,"","","",1,0,0,[],""],["carrizo_salta-n3370-01",3,"¡Linda, linda la chinita!\nConchabelá, mi mamita,\nSi no sirve pa cabrera,\nSerá para ovejerita.",3,1,0,52,"",0,4,"ia",50,0,-1,0,616,616,"3370","",0,"","","",1,0,0,[],""],["carrizo_salta-n3371-01",3,"Los cuervos en el ocot...\nTe canten \"Kirieeleisón\"\nY los perros de tu casa.\nTe saquen en procesión.",3,1,0,52,"",0,4,"o",31,0,-1,0,616,616,"3371","",0,"","","",1,0,0,[],""],["carrizo_salta-n3372-01",3,"Los dientes de mi vidita,\nMe tienen cautivo y preso,\n¡En mi vida he visto yo,\nCadenas hechas de güeso!",3,1,0,52,"",0,4,"eo",48,0,-1,0,616,616,"3372","",0,"","","",1,0,0,[],""],["carrizo_salta-n3373-01",3,"Los enemigos del alma.\nHan de saber que son tres:\nSantiagueños, tucumanos\nY cordobeses después.",3,1,0,52,"",0,4,"e",218,0,-1,0,616,616,"3373","",0,"","","",8,0,0,[],""],["carrizo_salta-n3374-01",3,"Los frailes y las mujeres\nSon las cosas que más brillan,\nLos frailes por la sotana,\nLas mujeres por la liga.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,616,616,"3374","",0,"","","",1,0,0,[],""],["carrizo_salta-n3375-01",3,"Los gallos van galliniando,\nLas gallinas cacariando.\nLos pollos hachando leña,\nLas gallinas cocinando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,616,616,"3375","",0,"","","",1,0,0,[],""],["carrizo_salta-n3376-01",3,"Los hombres cren y pretenden,\nSer una cosa precisa,\n¡Y nos hacen tanta falta!\nComo los perros en misa.",3,1,0,52,"",0,4,"ia",68,0,-1,0,616,616,"3376","",0,"","","",1,0,0,[],""],["carrizo_salta-n3377-01",3,"Los paisanos de mi pago,\nTienen mala la mirada.\nParecen carneros viejos,\nEn medio de la majada",3,1,0,52,"",0,4,"aa",49,0,-1,0,616,616,"3377","",0,"","","",1,0,0,[],""],["carrizo_salta-n3378-01",3,"Los sapos en la laguna,\nCelebran el temporal;\nLos chiquitos dicen: tunga,\nY los grandes :tungará.",3,1,0,52,"",0,4,"a",-1,0,-1,0,617,617,"3378","",0,"","","",6,0,0,[],""],["carrizo_salta-n3378-a-01",3,"Los sapos en la laguna\nHuyen de la tempestad;\nLos chiquitos dicen: tunga,\nY los grandes: tungará.",3,1,0,52,"",0,4,"a",-1,0,-1,0,617,617,"3378-a","",0,"","","",6,0,0,[],""],["carrizo_salta-n3379-01",3,"¡Madre mía del Rosario!\n¿Cómo vas a permitir,\nQue se me críe la barriga,\nComo tinaja i teñir?",3,1,0,52,"",0,4,"i",157,0,-1,0,617,617,"3379","",0,"","","",5,0,0,[],""],["carrizo_salta-n3380-01",3,"¡Madre mía del Rosario!\n¿Por qué me tenís tan flaco,\nEl cogote como suri,\nVerijas como guanaco?",3,1,0,52,"",0,4,"ao",423,0,-1,0,617,617,"3380","",0,"","","",5,0,0,[],""],["carrizo_salta-n3380-a-01",3,"¡Madre mía del Rosario!\n¿Por qué me tenís tan flaco,\nLas costillas de zancuda,\nEl cogote de guanaco?",3,1,0,52,"",0,4,"ao",423,0,-1,0,617,617,"3380-a","",0,"","","",5,0,0,[],""],["carrizo_salta-n3382-01",3,"Me avisas cuando te mueras,\nPara morirme primero:\nSi no te acompaño al cielo,\nMe iré derecho al infierno.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,617,617,"3382","",0,"","","",1,0,0,[],""],["carrizo_salta-n3383-01",3,"Me besaste a los cinco años,\nY me besaste a los diez.\nAhora que tengo quince,\nYa no me besáis, ¿por qué?",3,1,0,52,"",0,4,"e",-1,0,-1,0,617,617,"3383","",0,"","","",1,0,0,[],""],["carrizo_salta-n3384-01",3,"Media luna, luna entera.\nLuna traigo de bandera;\n¡Banderita colorada!\nChurcalista en mi tonada.",3,1,0,52,"",5,4,"aa",49,0,-1,0,617,617,"3384","",0,"","","",3,0,0,[],""],["carrizo_salta-n3385-01",3,"Me gusta la cinta negra,\nPorque es firme su color;\nMás me gustan sus narices,\nPa perlas de un prendedor.",3,1,0,52,"",0,4,"o",72,0,-1,0,617,617,"3385","",0,"","","",1,0,0,[],""],["carrizo_salta-n3386-01",3,"Me gusta ver a mi negra,\nCuando va para el mercado,\nParece gatito alegre,\nSaltando por los tejados.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,617,617,"3386","",0,"","","",1,0,0,[],""],["carrizo_salta-n3387-01",3,"Me gusta ver a mi negro,\nCuando se pone corbata,\nParece mosca en la leche,\nQue se ha perdido en la nata.",3,1,0,52,"",0,4,"aa",74,0,-1,0,617,617,"3387","",0,"","","",1,0,0,[],""],["carrizo_salta-n3388-01",3,"Me ha mandado mi mamita,\nQue le dé las buenas noches;\nY si no ha visto pasar,\nUna lagartija en coche",3,1,0,52,"",0,4,"oe",-1,0,-1,0,617,617,"3388","",0,"","","",1,0,0,[],""],["carrizo_salta-n3389-01",3,"Me has dicho lo que has querido,\nY te has quedado muy fresco,\nNarices de casa i sapo,\nTraza de caranchi chueco.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,617,617,"3389","",0,"","","",1,0,0,[],""],["carrizo_salta-n3390-01",3,"Me has dicho tonto,\nNada me importa;\nSi yo soy tonto,\nVos sos retonta.",3,1,0,52,"",6,4,"oa",-1,0,-1,0,617,617,"3390","",0,"","","",1,0,0,[],""],["carrizo_salta-n3391-01",3,"Metalé calor y frío,\nQue las penas son de amor,\nYa la gata está pariendo,\nY el gato está con dolor",3,1,0,52,"",0,4,"o",72,0,-1,0,617,617,"3391","",0,"","","",1,0,0,[],""],["carrizo_salta-n3392-01",3,"Mi abuela murió de vieja,\nBueno, me estaba criando,\nNo sé por qué habré salido,\nBoca dura y c u... blando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,618,618,"3392","",0,"","","",1,0,0,[],""],["carrizo_salta-n3393-01",3,"Mi caballo y mi mujer.\nSe fueron a Embarcación,\nMi caballo volvió sano.\nMi mujer con sarampión.",3,1,0,52,"",0,4,"o",31,0,-1,0,618,618,"3393","",0,"","","",3,0,0,[],""],["carrizo_salta-n3394-01",3,"Mi caballo y mi mujer,\nSe me murieron a un tiempo,\nMi mujer, Dios la perdone,\nMi caballo es lo que siento.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,618,618,"3394","",0,"machado_venezuela","","",3,0,0,[],""],["carrizo_salta-n3395-01",3,"Mi camisa me ha cobrado,\nLos años que me ha servido,\nYo también le hi de hacer cargo,\nLos piojos que me ha comido.",3,1,0,52,"",0,4,"io",101,0,-1,0,618,618,"3395","",0,"","","",1,0,0,[],""],["carrizo_salta-n3396-01",3,"Mi madre me dijo a mí,\nQue no quiera al hombre tuerto,\nPorque cuando está durmiendo,\nParece que está despierto.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,618,618,"3396","",0,"","","",1,0,0,[],""],["carrizo_salta-n3397-01",3,"Mi madre me dió una soba,\nPorque le pedí marido,\n¡Mamita, demé otra soba,\nY demé lo que le pido!",3,1,0,52,"",1,4,"io",101,0,-1,0,618,618,"3397","",0,"","","",1,0,0,[],""],["carrizo_salta-n3398-01",3,"Mi madre me echó a la escuela,\nPara que aprenda el \"Bendito\",\nCon el palillo y la caja,\nYo nombre al Padre y al Hijo.",3,1,0,52,"",0,4,"io",-1,0,-1,0,618,618,"3398","",0,"","","",1,0,0,[],""],["carrizo_salta-n3399-01",3,"Mi madre me quiere mucho,\nMe ha criao muy regalón,\nNo me hace faltar el güeso,\nNi el plato con chicharrón.",3,1,0,52,"",0,4,"o",31,0,-1,0,618,618,"3399","",0,"","","",1,0,0,[],""],["carrizo_salta-n3400-01",3,"Mi madre se llama Pascua,\nMi tatita Navidad,\nYo me llamo Todos Santos,\nMi apellido es Carnaval.",3,1,0,52,"",0,4,"a",-1,0,-1,0,618,618,"3400","",0,"","","",1,0,0,[],""],["carrizo_salta-n3401-01",3,"Mi mama me dió una soba,\nPorque robé una cabrilla,\n¡Mamita, demé otra soba!\nLe vua traer la cuadrilla.",3,1,0,52,"",1,4,"ia",162,0,-1,0,618,618,"3401","",0,"","","",1,0,0,[],""],["carrizo_salta-n3402-01",3,"Mi mujer, con el demonio,\nApostaron un doblón,\nSobre cuál era más fiero,\nY mi mujer le ganó.",3,1,0,52,"",0,4,"o",-1,0,-1,0,618,618,"3402","",0,"","","",1,0,0,[],""],["carrizo_salta-n3403-01",3,"Mis ojos están con sueño,\nCon ganitas de dormir,\nEl uno ya se ha cerrado,\nEl otro no puedo abrir.",3,1,0,52,"",0,4,"i",157,0,-1,0,618,618,"3403","",0,"","","",1,0,0,[],""],["carrizo_salta-n3404-01",3,"Mi sombrero me ha cobrado,\nEl tiempo que me ha servido,\nYo también le hi de hacer cargo,\nEl sudor que me ha bebido.",3,1,0,52,"",0,4,"io",101,0,-1,0,618,618,"3404","",0,"","","",1,0,0,[],""],["carrizo_salta-n3405-01",3,"Mi suegra me quiere mucho,\nY me dice que soy guapo,\nMe hace fregar las cucharas,\nY me hace lavar los platos.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,618,618,"3405","",0,"","","",6,0,0,[],""],["carrizo_salta-n3406-01",3,"Mi padre se llama Santo,\nY mi madre, Santidad,\nA mí me dicen: Santito,\n¡Miren, qué casualidad!",3,1,0,52,"",0,4,"a",16,0,-1,0,619,619,"3406","",0,"","","",1,0,0,[],""],["carrizo_salta-n3407-01",3,"Mi poncho no tiene fleco,\nNi botones mi chaleco,\nY mi sombrerito viejo,\nYa no tiene barbiquejo.",3,1,0,52,"",0,4,"eo",264,0,-1,0,619,619,"3407","",0,"","","",1,0,0,[],""],["carrizo_salta-n3408-01",3,"¡Miren qué diablo el iquincho!\nAlita tan overita,\nSi la encuentra a ulunchita,\nLe pega una volcadita.",3,1,0,52,"",0,4,"ia",50,0,-1,0,619,619,"3408","",0,"","","",1,0,0,[],""],["carrizo_salta-n3409-01",3,"¡Miren qué diablo es el sapo!\nDe meterse de aguacil,\nCada año pa carnaval,\nAnda hombriando su fusil.",3,1,0,52,"",0,4,"i",290,0,-1,0,619,619,"3409","",0,"","","",1,0,0,[],""],["carrizo_salta-n3410-01",3,"¡Miren qué laya y mosquito!\nMeterse de comerciante,\nCuando el piojo va de arriero,\nLa pulga va de ayudante.",3,1,0,52,"",0,4,"ae",47,0,-1,0,619,619,"3410","",0,"","","",1,0,0,[],""],["carrizo_salta-n3410-02",3,"¡Miren qué traza i zancudo!\nSe ha metido a comerciante,\nCon una pulga de arriera,\nY una liendre de ayudante.",3,1,0,52,"",0,4,"ae",47,0,-1,0,619,619,"3410","",0,"","","",1,0,0,[],""],["carrizo_salta-n3411-01",3,"Mucho me gusta el máiz chulpi,\nMás me gusta el maiz morocho,\n¡De vicio venís pintando,\nCara de carnero mocho!",3,1,0,52,"",0,4,"oo",424,0,-1,0,619,619,"3411","",0,"","","",1,0,0,[],""],["carrizo_salta-n3412-01",3,"Muchos pericotitos,\nHay en tu cuarto,\n¡Dejá la puerta abierta,\nPa que entre el gato!",3,1,0,52,"",6,4,"ao",-1,0,-1,0,619,619,"3412","",0,"","","",1,0,0,[],""],["carrizo_salta-n3412-02",3,"Adentro de tu cuarto,\nHay ratoncitos,\nDeja la puerta abierta!\nMe haré el gatito.",3,1,0,52,"",6,4,"io",-1,0,-1,0,619,619,"3412","",0,"","","",1,0,0,[],""],["carrizo_salta-n3413-01",3,"Nadie ha visto lo qui hi visto,\nLo qui hi visto esta mañana;\nUn pajarillo en la torre,\nRepicando las campanas.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,619,619,"3413","",0,"","","",1,0,0,[],""],["carrizo_salta-n3413-a-01",3,"Muy cierto me había salido,\nEl sueño de esta mañana;\nUn pajarito en la torre,\nRepicando las campanas.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,619,619,"3413-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3414-01",3,"Nadie quiere a mi suegra,\nY yo la quiero,\nPara llevarla al monte,\nSacarle el cuero.",3,1,0,52,"",6,4,"eo",38,0,-1,0,619,619,"3414","",0,"","","",1,0,0,[],""],["carrizo_salta-n3415-01",3,"Negro, para hacer el cuento,\nFiero, para reparón,\nMezquino, pa pedigüeño,\nTramposo, pa cobrador.",3,1,0,52,"",0,4,"o",-1,0,-1,0,620,620,"3415","",0,"","","",1,0,0,[],""],["carrizo_salta-n3416-01",3,"No me gustan las lindas,\nNi las bizarras,\nMe gustan las boconas,\nPara besarlas.",3,1,0,52,"",6,4,"aa",-1,0,-1,0,620,620,"3416","",0,"","","",1,0,0,[],""],["carrizo_salta-n3417-01",3,"No me importa que otros gocen,\nLo que a mí ni falta me haga,\nMe gusta encontrarme a tiempo,\nY pegar mi cuchariada.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,620,620,"3417","",0,"","","",1,0,0,[],""],["carrizo_salta-n3418-01",3,"No quieren cantar conmigo,\nSolito me daré maña,\nNo saben que se han perdido,\nUna tortilla tamaña.",3,1,0,52,"",0,4,"aa",213,0,-1,0,620,620,"3418","",0,"","","",1,0,0,[],""],["carrizo_salta-n3419-01",3,"No quise topar al tigre,\nPorque fué muy overito,\nY topándolo de frente,\nMe hinqué y le recé el bendito.",3,1,0,52,"",0,4,"io",119,0,-1,0,620,620,"3419","",0,"","","",1,0,0,[],""],["carrizo_salta-n3420-01",3,"No sé cómo estoy pasando,\nLa vida desesperada;\n¿Será por que no me dan,\nUn pedacito i cuajada?",3,1,0,52,"",0,4,"aa",49,0,-1,0,620,620,"3420","",0,"","","",1,0,0,[],""],["carrizo_salta-n3421-01",3,"No se triunfa con paradas,\nSabe decir mi patrón,\nSi quieren un rico bollo,\nEchelén buen chicharrón.",3,1,0,52,"",0,4,"o",31,0,-1,0,620,620,"3421","",0,"","","",1,0,0,[],""],["carrizo_salta-n3422-01",3,"Nosotros no somos léidos,\nNi sabimos escribir,\nMeto la pluma al tintero,\nY no sé que vua decir.",3,1,0,52,"",0,4,"i",157,0,-1,0,620,620,"3422","",0,"","","",1,0,0,[],""],["carrizo_salta-n3423-01",3,"No soy águila ni halcón,\nNi cuervo para volar;\nCuando dicen citación,\nSoy capaz de disparar.",3,1,0,52,"",1,4,"a",21,0,-1,0,620,620,"3423","",0,"","","",1,0,0,[],""],["carrizo_salta-n3424-01",3,"No tapes con la pintura,\nLos colores de tu cara,\nQue sólo en las casas viejas,\nSe revoca la fachada.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,620,620,"3424","",0,"palau_cantares","","",2,0,0,[],""],["carrizo_salta-n3425-01",3,"¡No te casís con viuda!\nQue es desacierto;\nDebajo de la almohada,\nSuspira el muerto.",3,1,0,52,"",6,4,"eo",88,0,-1,0,620,620,"3425","",0,"","","",1,0,0,[],""],["carrizo_salta-n3426-01",3,"¡Nuestra Madre del Rosario!\nSalva nuestras sementeras,\nNuestras vacas y terneros,\nY a todos del Comisario.",3,1,0,52,"",5,4,"ao",25,0,-1,0,620,620,"3426","",0,"","","",1,0,0,[],""],["carrizo_salta-n3427-01",3,"¡Oigamé, mi fulanita!\n¡Digamé, cómo se llama!\nPara poderla nombrar,\nCuando yo vaya a su cama.",3,1,0,52,"",0,4,"aa",90,0,-1,0,620,620,"3427","",0,"","","",1,0,0,[],""],["carrizo_salta-n3428-01",3,"¡Oiga, mi querido amigo!\n¿Por qué está tan tiple, tiple,\nComo si hubiera comido\nAlgún caldito de upite?",3,1,0,52,"",0,4,"ie",-1,0,-1,0,620,620,"3428","",0,"","","",1,0,0,[],""],["carrizo_salta-n3429-01",3,"Oigalón a ese mocito,\nSombrerito lapa-lapa,\n¿Qué hará que no se recoge,\nLas chinches de su solapa",3,1,0,52,"",0,4,"aa",297,0,-1,0,621,621,"3429","",0,"","","",1,0,0,[],""],["carrizo_salta-n3430-01",3,"Para el año m' h' i casar,\nPa tener a quien tener,\nA trompadas y a patadas,\nY a garrotazos también.",3,1,0,52,"",0,4,"e",-1,0,-1,0,621,621,"3430","",0,"","","",1,0,0,[],""],["carrizo_salta-n3431-01",3,"Pensando en que me dejas,\nLloro tanto y tan de veras,\nQue la gente de mi casa,\nSe imagina que hay gotera.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,621,621,"3431","",0,"","","",1,0,0,[],""],["carrizo_salta-n3432-01",3,"¡Planta de ají!\nFlor de romero,\n¿Dónde estará mi negra,\nÑatas de hornero?",3,1,0,52,"",6,4,"eo",38,0,-1,0,621,621,"3432","",0,"","","",3,0,0,[],""],["carrizo_salta-n3433-01",3,"¡Planta de ají!\nFlor de tomate,\nEl que no tiene yerba,\nNo toma mate.",3,1,0,52,"",6,4,"ae",384,0,-1,0,621,621,"3433","",0,"","","",3,0,0,[],""],["carrizo_salta-n3434-01",3,"Por cuidado que tenga,\nLa lavandera,\nSiempre sale mojada,\nLa delantera.",3,1,0,52,"",6,4,"ea",44,0,-1,0,621,621,"3434","",0,"","","",1,0,0,[],""],["carrizo_salta-n3435-01",3,"Por el ojo de una aguja,\nPasó un avestruz corriendo,\nY si no me quieren creer,\nUn ciego lo estuvo viendo.",3,1,0,52,"",0,4,"eo",52,0,-1,0,621,621,"3435","",0,"","","",2,0,0,[],""],["carrizo_salta-n3436-01",3,"Por esta calle me voy,\nPor la otra me doy vuelta,\n¡Vidita, si me querís,\nDejame la puerta abierta!",3,1,0,52,"",0,4,"ea",-1,0,-1,0,621,621,"3436","",0,"","","",8,0,0,[],""],["carrizo_salta-n3437-01",3,"Por la falda de aquel cerro,\nBajó un chancho con cencerro,\nTirando p e d... calientes,\nPara vos y tus parientes.",3,1,0,52,"",5,4,"ee",252,0,-1,0,621,621,"3437","",0,"","","",5,0,0,[],""],["carrizo_salta-n3438-01",3,"Por la falda de aquel cerro,\nBajó un sapo de rodilla,\nPeinándose los bigotes,\nY haciéndose la patilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,621,621,"3438","",0,"","","",5,0,0,[],""],["carrizo_salta-n3439-01",3,"Por la falda de aquel cerro,\nCorre el perro una corzuela,\nLa corzuela va llorando,\nPor la leche de su agüela.",3,1,0,52,"",0,4,"ea",167,0,-1,0,621,621,"3439","",0,"","","",5,0,0,[],""],["carrizo_salta-n3439-a-01",3,"Por la falda de aquel cerro,\nCorrió el perro una corzuela,\nY la corzuela lloraba,\nPor la leche de su agüela.",3,1,0,52,"",0,4,"ea",167,0,-1,0,621,621,"3439-a","",0,"","","",5,0,0,[],""],["carrizo_salta-n3440-01",3,"Por la falda de la loma,\nVan dos por la cerrazón;\nUna pulga aparejada,\nY un piojo con jaquimón.",3,1,0,52,"",0,4,"o",31,0,-1,0,621,621,"3440","",0,"","","",1,0,0,[],""],["carrizo_salta-n3441-01",3,"Por la punta de los piés,\nMe sé poner los calzones,\nAbriendo los ojalillos,\nPara meter los botones.",3,1,0,52,"",0,4,"oe",34,0,-1,0,621,621,"3441","",0,"","","",1,0,0,[],""],["carrizo_salta-n3442-01",3,"Por la soga sale el balde,\nY en el balde viene 'l agua,\nSi yo no tengo camisa,\nMi mujer no tiene nagua.",3,1,0,52,"",0,4,"aa",383,0,-1,0,621,621,"3442","",0,"","","",1,0,0,[],""],["carrizo_salta-n3443-01",3,"¿Qué andas haciendo, gato,\nPor la cocina?\n—En busca de cebolla\nPa l' comida.",3,1,0,52,"",6,4,"ia",-1,0,-1,0,621,621,"3443","",0,"","","",1,0,0,[],""],["carrizo_salta-n3444-01",3,"¡Qué buenita que es mi suegra!\nComo ella no hi de tener,\nNo me deja estar un rato,\nA solas con mi mujer.",3,1,0,52,"",0,4,"e",20,0,-1,0,622,622,"3444","",0,"","","",1,0,0,[],""],["carrizo_salta-n3445-01",3,"¡Qué desgraciada es la pulga,\nQue muere sin confesión!\nAmarillas son las crías,\nDel cuello de mi cotón.",3,1,0,52,"",0,4,"o",31,0,-1,0,622,622,"3445","",0,"","","",1,0,0,[],""],["carrizo_salta-n3445-a-01",3,"¡Qué dichosas son las liendres!\nQue relumbran con el sol,\n¡Qué desgraciados los piojos!\nQue mueren sin confesión.",3,1,0,52,"",0,4,"o",-1,0,-1,0,622,622,"3445-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3446-01",3,"¿Qué haremos, compañerito?\nNo hay carne para mañana,\n—Mataremos un zancudo,\nPesaremos en romana.",3,1,0,52,"",0,4,"aa",4,0,-1,0,622,622,"3446","",0,"","","",1,0,0,[],""],["carrizo_salta-n3447-01",3,"¡Qué lindo es ver a las viejas\nCorrer por tras el amor!\nLas polleritas volando,\nLa simba como asador.",3,1,0,52,"",0,4,"o",72,0,-1,0,622,622,"3447","",0,"","","",1,0,0,[],""],["carrizo_salta-n3448-01",3,"¿Qué me dices, colla pobre,\nLa casa llena de estacas?\nComís vacas despeñadas,\nY las que mueren de flacas.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,622,622,"3448","",0,"","","",1,0,0,[],""],["carrizo_salta-n3449-01",3,"¡Qué me importa a mí de Urquiza,\nQue gobierne el Entre Ríos!\nEl gobierna lo que es suyo,\nYo gobierno lo que es mío.",3,1,0,52,"",0,4,"io",-1,0,-1,0,622,622,"3449","",0,"","","",1,0,0,[],""],["carrizo_salta-n3450-01",3,"¿Qué querís que te traiga,\nDe Cafayate?\n—Una gallina clueca\nY un gualacate.",3,1,0,52,"",6,4,"ae",384,0,-1,0,622,622,"3450","",0,"","","",3,0,0,[],""],["carrizo_salta-n3451-01",3,"¿Qué queris que te traiga\nDe la ensenada?\n—Una chuña pelada,\nPara ensalada.",3,1,0,52,"",6,4,"aa",49,0,-1,0,622,622,"3451","",0,"","","",3,0,0,[],""],["carrizo_salta-n3452-01",3,"¿Qué quieres que te traiga\nDe Los Cardones?\n—Un pelloncito i lana,\nPa mis calzones.",3,1,0,52,"",6,4,"oe",34,0,-1,0,622,622,"3452","",0,"","","",9,0,0,[],""],["carrizo_salta-n3453-01",3,"¿Qué queris que te traiga\nDe l' otra banda?\n—Un pajarito verde,\nDe cola larga.",3,1,0,52,"",6,4,"aa",-1,0,-1,0,622,622,"3453","",0,"","","",3,0,0,[],""],["carrizo_salta-n3455-01",3,"¡Quién la vido!\n¡Y quién la vé!\nParece puchito i vela,\nPegadito en la pared.",3,1,0,52,"",3,4,"e",-1,0,-1,0,623,623,"3455","",0,"","","",1,0,0,[],""],["carrizo_salta-n3456-01",3,"¿Quién lo conoció a Anastacio,\nCon camisa de batista,\nPantalón de casimir,\nY botines y levita?",3,1,0,52,"",0,4,"ia",-1,0,-1,0,623,623,"3456","",0,"","","",1,0,0,[],""],["carrizo_salta-n3457-01",3,"¿Quién será aquel jovencito,\nCarita de hoja i parral?\nComo quiera se parece\nTranquera de mi corral.",3,1,0,52,"",0,4,"a",1,0,-1,0,623,623,"3457","",0,"","","",1,0,0,[],""],["carrizo_salta-n3458-01",3,"¡Quién tuviera la suerte\nQue tiene el gallo!\nEn la mitá del giro,\nMonta a caballo.",3,1,0,52,"",6,4,"ao",102,0,-1,0,623,623,"3458","",0,"","","",1,0,0,[],""],["carrizo_salta-n3459-01",3,"Quisiera estar en tu cuarto,\nY la puerta se cerrara,\nQue la llave se perdiera,\nY el herrero reventara.",3,1,0,52,"",0,4,"aa",57,0,-1,0,623,623,"3459","",0,"","","",1,0,0,[],""],["carrizo_salta-n3460-01",3,"Quisiera hacerme chicharra,\nCorta vida y larga fama,\nDe balde me hago el chiquito,\nPara llegar a tu cama.",3,1,0,52,"",0,4,"aa",90,0,-1,0,623,623,"3460","",0,"","","",1,0,0,[],""],["carrizo_salta-n3461-01",3,"Remedio pa los callos,\nEs la ceniza,\nY el beso de una vieja\nGorda y petiza.",3,1,0,52,"",6,4,"ia",420,0,-1,0,623,623,"3461","",0,"","","",1,0,0,[],""],["carrizo_salta-n3462-01",3,"San Juan de Buenaventura,\nNunca se puso calzones,\nPor milagro qu ese puso,\nLe llegó hasta los talones.",3,1,0,52,"",0,4,"oe",34,0,-1,0,623,623,"3462","",0,"","","",1,0,0,[],""],["carrizo_salta-n3463-01",3,"Se cayó una lagartija,\nDe arriba de una pared,\nVino el lagarto y le dijo:\n¿En qué te has golpiao, mujer?",3,1,0,52,"",0,4,"e",-1,0,-1,0,623,623,"3463","",0,"","","",1,0,0,[],""],["carrizo_salta-n3463-a-01",3,"Yo vide una lagartija,\nPegada en una pared:\nVino el lagarto y le dijo:\n¿Qué estás haciendo mujer?",3,1,0,52,"",0,4,"e",-1,0,-1,0,623,623,"3463-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3464-01",3,"¡Señora: dice mamita,\nQue tenga unos buenos días,\nQue le mande la gallina,\nQue le robó el otro día!",3,1,0,52,"",0,4,"ia",-1,0,-1,0,623,623,"3464","",0,"","","",1,0,0,[],""],["carrizo_salta-n3465-01",3,"¡Señora, doña fulana,\nColorada y desteñida!\nBusque paja y haga nido,\nQue su dueño ya ha venido.",3,1,0,52,"",5,4,"io",101,0,-1,0,623,623,"3465","",0,"","","",22,0,0,[],""],["carrizo_salta-n3466-01",3,"¡Señora, doña fulana!\n¿Por qué se muestra tirana?\nSi esta noche a media noche,\nSe le han de pasar las ganas.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,623,623,"3466","",0,"","","",22,0,0,[],""],["carrizo_salta-n3467-01",3,"¡Señora, doña Micáila!\nVerde cogollo de hinojo,\nYa sé que Vd. anda diciendo,\nQue don Micáilo anda flojo.",3,1,0,52,"",0,4,"oo",400,0,-1,0,623,623,"3467","",0,"","","",1,0,0,[],""],["carrizo_salta-n3468-01",3,"¡Señores, les contaré!\nDe una gallina que tengo,\nCuando se pone a güeviar,\nEl gallo se pone rengo.",3,1,0,52,"",0,4,"eo",124,0,-1,0,623,623,"3468","",0,"","","",6,0,0,[],""],["carrizo_salta-n3469-01",3,"¡Señores, les contaré!\nHi visto un sapo con lana,\nLa rana lo trasquiló,\nHizo felpa y sobrecama.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,623,623,"3469","",0,"","","",6,0,0,[],""],["carrizo_salta-n3470-01",3,"¡Señores, les contaré!\nLos golpes de la fortuna:\nDiez, nueve, ocho, siete seis,\nCinco, cuatro, tres, dos, una.",3,1,0,52,"",0,4,"ua",56,0,-1,0,624,624,"3470","",0,"","","",6,0,0,[],""],["carrizo_salta-n3471-01",3,"¡Señor, fulano de tal!\nEsto va de una pasada,\nSi se pone tras de mí,\nOlerá a gallina asada.",3,1,0,52,"",0,4,"aa",49,0,-1,0,624,624,"3471","",0,"","","",3,0,0,[],""],["carrizo_salta-n3472-01",3,"Se pusieron a jugar,\nEn una noche de luna,\nUn gato con una rata,\nY un perro con una chuña.",3,1,0,52,"",0,4,"ua",-1,0,-1,0,624,624,"3472","",0,"","","",1,0,0,[],""],["carrizo_salta-n3473-01",3,"Si es que está enojada,\nHagamé el favor,\nPrestemé su boca,\nPara soplad r.",3,1,0,52,"",6,4,"",-1,0,-1,0,624,624,"3473","",0,"","","",1,0,0,[],""],["carrizo_salta-n3475-01",3,"Si me querís, mi vidita,\nVamonós pa lejas tierras,\nEn un caballo de palo,\nY vasos de cal y piedra.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,624,624,"3475","",0,"","","",1,0,0,[],""],["carrizo_salta-n3476-01",3,"Si porque te quiero,\nMetís alboroto,\nMetete en un cuerno,\nTapate con otro.",3,1,0,52,"",0,4,"oo",-1,0,-1,0,624,624,"3476","",0,"","","",2,0,0,[],""],["carrizo_salta-n3477-01",3,"Si querís que yo te quiera,\nEnseñame tus miradas,\nLlamame todas las noches,\nMandame a la madrugada.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,624,624,"3477","",0,"","","",3,0,0,[],""],["carrizo_salta-n3478-01",3,"Si querís sanar de amores,\nBuscá flores con matices,\nAlzale la cola al pila,\nY plantalo en las narices.",3,1,0,52,"",0,4,"ie",113,0,-1,0,624,624,"3478","",0,"","","",1,0,0,[],""],["carrizo_salta-n3479-01",3,"Si querís ser domador,\nAndá comprá un par de espuelas,\nSi caballo no tenís,\nAndá domala a tu agüela.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,624,624,"3479","",0,"","","",1,0,0,[],""],["carrizo_salta-n3480-01",3,"Si quieren saber, señores,\n¿Cómo me paso la vida?\n—Con la carne del mosquito,\nY la leche de la hormiga.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,624,624,"3480","",0,"","","",11,0,0,[],""],["carrizo_salta-n3481-01",3,"Si quieres aborrecer,\nA aquella que estás amando,\nFiguratelá c...ndo,\nArriba de una pared.",3,1,0,52,"",5,4,"e",-1,0,-1,0,624,624,"3481","",0,"","","",2,0,0,[],""],["carrizo_salta-n3482-01",3,"Si se ofreciera el venderme,\nPor mí ¿quién daría un cuartillo?\nSoy gordo, ñato y pansón,\nInútil, flojo y sencillo.",3,1,0,52,"",0,4,"io",228,0,-1,0,624,624,"3482","",0,"","","",1,0,0,[],""],["carrizo_salta-n3483-01",3,"Si tu casa se quemara,\nY en tu c u... un hormiguero,\n¿A cuál atenderías más,\nA tu casa o a tu aujero?",3,1,0,52,"",0,4,"eo",38,0,-1,0,624,624,"3483","",0,"","","",1,0,0,[],""],["carrizo_salta-n3484-01",3,"Si tú fueras vigilante,\nYo no sería tu pitito,\nPorque no sería tan zonza,\nPara darte mi aujerito.",3,1,0,52,"",0,4,"io",119,0,-1,0,625,625,"3484","",0,"","","",1,0,0,[],""],["carrizo_salta-n3485-01",3,"Si tu madre no me quiere,\nQue me eche esta maldición:\nQue se le pierda la hija,\nY que me la encuentre yo.",3,1,0,52,"",0,4,"o",-1,0,-1,0,625,625,"3485","",0,"","","",5,0,0,[],""],["carrizo_salta-n3486-01",3,"Si Vd. fuera mi vizcacha,\nY yo fuera vizcachón,\nEn el aujero estaría,\nHaciendo: ¡piscón, piscón!",3,1,0,52,"",0,4,"o",31,0,-1,0,625,625,"3486","",0,"","","",1,0,0,[],""],["carrizo_salta-n3487-01",3,"Si yo fuera tu curita,\nY vos fueras mi beata,\nToda la noche anduviera,\nComo gato con la gata.",3,1,0,52,"",0,4,"aa",74,0,-1,0,625,625,"3487","",0,"","","",1,0,0,[],""],["carrizo_salta-n3488-01",3,"Si yo las quiero a las viejas,\nSólo yo sabré por qué,\nEllas no me morderán,\nPor que no tienen con qué.",3,1,0,52,"",0,4,"e",-1,0,-1,0,625,625,"3488","",0,"","","",1,0,0,[],""],["carrizo_salta-n3489-01",3,"Si yo me volviera zorra,\nMe remontaría a los cerros,\nY si me agarran los perros,\n¡Más vale que no me corran!",3,1,0,52,"",5,4,"oa",-1,0,-1,0,625,625,"3489","",0,"","","",1,0,0,[],""],["carrizo_salta-n3490-01",3,"Soy Antonino Reinaga,\nPadre de l' ociosidad,\nSólo pa empinar el codo,\nDios me ha dado habilidad.",3,1,0,52,"",0,4,"a",16,0,-1,0,625,625,"3490","",0,"","","",1,0,0,[],""],["carrizo_salta-n3491-01",3,"Soy como piedra de río,\nNo siento calor ni frío,\nDentro el agua estoy sudando,\nJunto al fuego me hace frío.",3,1,0,52,"",0,4,"io",-1,0,-1,0,625,625,"3491","",0,"","","",1,0,0,[],""],["carrizo_salta-n3492-01",3,"Soy pobre como una rata;\nPero, cuando tenga plata,\nPa mi pago hi de apuntar,\nAunque sea con una pata.",3,1,0,52,"",0,4,"aa",74,0,-1,0,625,625,"3492","",0,"","","",1,0,0,[],""],["carrizo_salta-n3493-01",3,"Soy un gauchito rodante,\nComo bola sin manija;\n¡Vieja fiera, renegona,\nCobradora, demé su hija!",3,1,0,52,"",0,4,"ia",219,0,-1,0,625,625,"3493","",0,"","","",1,0,0,[],""],["carrizo_salta-n3494-01",3,"Su amor me tiene, señora,\nMás amarillo que el güevo,\nY con las tripas silbando,\nComo zorro mistolero.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,625,625,"3494","",0,"","","",1,0,0,[],""],["carrizo_salta-n3495-01",3,"Tanto servir a la patria,\nPreguntemén qué hi sacao,\nLos calzones de picote,\nHasta el pelo me han cortao.",3,1,0,52,"",0,4,"ao",98,0,-1,0,625,625,"3495","",0,"","","",1,0,0,[],""],["carrizo_salta-n3496-01",3,"Tarde hi llegado a tu casa,\nY me distes de cenar,\nUn locro i trigo mal hecho,\nEl afrecho por volar.",3,1,0,52,"",0,4,"a",21,0,-1,0,626,626,"3496","",0,"","","",1,0,0,[],""],["carrizo_salta-n3497-01",3,"Te acordarás, mi vidita,\nDe la noche el ventarrón.\nNo me dejaron dormir,\nLas pulgas de tu colchón.",3,1,0,52,"",0,4,"o",31,0,-1,0,626,626,"3497","",0,"","","",1,0,0,[],""],["carrizo_salta-n3498-01",3,"Te acordarás, vida mía,\nLa noche de la nevada,\nAmanecieron blanquiando,\nLos piojos en tu frazada.",3,1,0,52,"",0,4,"aa",49,0,-1,0,626,626,"3498","",0,"","","",2,0,0,[],""],["carrizo_salta-n3498-a-01",3,"¿Te acuerdas, vidita mía,\nLa noche de la nevada?\nNo me dejaban dormir,\nLos piojos de tu frazada.",3,1,0,52,"",0,4,"aa",49,0,-1,0,626,626,"3498-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n3499-01",3,"Te cayiste en medio el cerco,\nTe saqué con mi palito;\n¿Quiéres burlarte de mí?\n¡Miren, qué traza i diablito!",3,1,0,52,"",0,4,"io",119,0,-1,0,626,626,"3499","",0,"","","",1,0,0,[],""],["carrizo_salta-n3500-01",3,"Te digo con incultura,\nAunque a la verdad no acierto,\nQue teniendo un ojo tuerto,\n¿Cómo te llamas ventura?",3,1,0,52,"",11,4,"ua",17,0,-1,0,626,626,"3500","",0,"","","",1,0,0,[],""],["carrizo_salta-n3501-01",3,"Tengo mi caballo bueno,\nUn caballito rosillo,\nDe buen pecho y de buena anca,\nEl lomo como cuchillo.",3,1,0,52,"",0,4,"io",228,0,-1,0,626,626,"3501","",0,"","","",1,0,0,[],""],["carrizo_salta-n3502-01",3,"Tengo mi buena montura,\nPara salir a moniar,\nCon los estribos de palo,\nY correas de torzal.",3,1,0,52,"",0,4,"a",-1,0,-1,0,626,626,"3502","",0,"","","",2,0,0,[],""],["carrizo_salta-n3503-01",3,"Tengo mi buena montura,\nPara salir a moniar,\nL'echo quince días al agua,\nTuavía no puedo ensillar.",3,1,0,52,"",0,4,"a",21,0,-1,0,626,626,"3503","",0,"","","",2,0,0,[],""],["carrizo_salta-n3504-01",3,"Tengo mi caballo lindo,\nPara salir a moniar,\nEn cada casa que llego,\nNo se para por lomiar.",3,1,0,52,"",0,4,"a",21,0,-1,0,626,626,"3504","",0,"","","",2,0,0,[],""],["carrizo_salta-n3505-01",3,"Tengo mi caballo lindo,\nPara salir a moniar,\nSe mantiene con los soles,\nToma agua cuando le dan.",3,1,0,52,"",0,4,"a",-1,0,-1,0,626,626,"3505","",0,"","","",2,0,0,[],""],["carrizo_salta-n3506-01",3,"Tengo mi lindo pellón,\nPara salir a lucir,\nLa mitad de cuero i chancho,\n¡Como quiera se ha i fruncir!",3,1,0,52,"",0,4,"i",157,0,-1,0,626,626,"3506","",0,"","","",1,0,0,[],""],["carrizo_salta-n3507-01",3,"Tengo una cajita buena,\nRetobada con un trapo,\nAritos de cortadera,\nChirlera de cola i sapo.",3,1,0,52,"",0,4,"ao",466,0,-1,0,626,626,"3507","",0,"","","",1,0,0,[],""],["carrizo_salta-n3508-01",3,"Tenía mi buena camisa,\nDe la tienda \"El Pensamiento\",\nCaminaba con cuidado,\nQue no me la rompa el viento.",3,1,0,52,"",0,4,"eo",94,0,-1,0,626,626,"3508","",0,"","","",1,0,0,[],""],["carrizo_salta-n3509-01",3,"Tenía mi buen caballito,\nPara salir a moniar,\nCuando llegaba a una casa,\nPrincipiaba a saludar.",3,1,0,52,"",0,4,"a",21,0,-1,0,627,627,"3509","",0,"","","",1,0,0,[],""],["carrizo_salta-n3510-01",3,"Tenía mis buenos calzones,\nCosidos con desimulo,\nCaminaba para atrás,\nPara no mostrar el c u...",3,1,0,52,"",5,4,"u",-1,0,-1,0,627,627,"3510","",0,"","","",1,0,0,[],""],["carrizo_salta-n3511-01",3,"Tenía mis buenos estribos,\nPara salir a moniar,\nDe costillitas de potro;\nAsí nomás, sin doblar.",3,1,0,52,"",0,4,"a",21,0,-1,0,627,627,"3511","",0,"","","",1,0,0,[],""],["carrizo_salta-n3512-01",3,"Tenía unos calzones lindos,\nDe tejido que no había,\nCuántas veces me agachaba,\nTodito me parecía.",3,1,0,52,"",0,4,"ia",0,0,-1,0,627,627,"3512","",0,"","","",1,0,0,[],""],["carrizo_salta-n3513-01",3,"Tienes el cabello negro,\nY muy negras tus pestañas;\nY negras tienes las manos,\nPorque nunca te las lavas.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,627,627,"3513","",0,"","","",1,0,0,[],""],["carrizo_salta-n3514-01",3,"¡Tirame a matar!\n¡Tirame a matar!\nCon pistola i caña,\nBalas de chañar.",3,1,0,52,"",0,4,"a",21,0,-1,0,627,627,"3514","",0,"","","",1,0,0,[],""],["carrizo_salta-n3515-01",3,"Toda mujer que quiera,\nVivir a gusto,\nBusque un marido zonzo,\nY un gaucho chusco.",3,1,0,52,"",6,4,"uo",-1,0,-1,0,627,627,"3515","",0,"","","",1,0,0,[],""],["carrizo_salta-n3516-01",3,"Todas las mujeres tienen\nEn la camisa,\nMañana San Gregorio,\nDía de misa.",3,1,0,52,"",6,4,"ia",68,0,-1,0,627,627,"3516","",0,"","","",11,0,0,[],""],["carrizo_salta-n3517-01",3,"Todos los miches de casa,\nSon ligeros pa cazar,\nBien entran a la cocina,\nYa comienzan a saltar.",3,1,0,52,"",0,4,"a",21,0,-1,0,627,627,"3517","",0,"","","",1,0,0,[],""],["carrizo_salta-n3518-01",3,"Todos me dicen: ¡casate!\n¡Casate con la hija el juez!\n—¿Para qué me vua a casar?\n¿Pa que me jodan después?",3,1,0,52,"",0,4,"e",218,0,-1,0,627,627,"3518","",0,"","","",4,0,0,[],""],["carrizo_salta-n3519-01",3,"Todos me dicen: ¡casate!\nYo les digo: no conviene;\nSi es que el cura quiere plata,\n¿Por qué no trabaja y tiene?",3,1,0,52,"",0,4,"ee",70,0,-1,0,627,627,"3519","",0,"","","",4,0,0,[],""],["carrizo_salta-n3520-01",3,"Todos me dicen: ¡casate!\nYo no me quiero casar,\nPa que no me anden tomando,\nComo potro del bozal.",3,1,0,52,"",0,4,"a",-1,0,-1,0,627,627,"3520","",0,"","","",4,0,0,[],""],["carrizo_salta-n3521-01",3,"Todos me dicen: ¡casate!\nYo no me quiero casar,\nPor más cuidados que tenga,\nTodas me han de sargentiar.",3,1,0,52,"",0,4,"a",21,0,-1,0,627,627,"3521","",0,"","","",4,0,0,[],""],["carrizo_salta-n3522-01",3,"¡Tomá esta silla, sentate!\nY me dirás lo que quieras,\nBien puede ser que me cuentes,\nCómo es la flor de la higuera.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,627,627,"3522","",0,"","","",1,0,0,[],""],["carrizo_salta-n3523-01",3,"Tras la puerta de mi casa,\nTengo una planta de arroz,\nPa que coma mi pollito,\nLa bostita para vos.",3,1,0,52,"",0,4,"o",87,0,-1,0,628,628,"3523","",0,"","","",1,0,0,[],""],["carrizo_salta-n3525-01",3,"Una breva se cayó,\nY me pegó en el ombligo,\nSi me pega más abajo,\nSe junta breva con higo.",3,1,0,52,"",0,4,"io",106,0,-1,0,628,628,"3525","",0,"","","",1,0,0,[],""],["carrizo_salta-n3526-01",3,"Una chancha muy coqueta,\nSe casó con el zorrino,\nY sirvieron de padrinos,\nLa paloma y el zorzal.",3,1,0,52,"",5,4,"a",-1,0,-1,0,628,628,"3526","",0,"","","",1,0,0,[],""],["carrizo_salta-n3527-01",3,"Una chinita me dijo,\nQue yo no le daba nada.\n¿No recuerda que le daba,\nPalizas por la mañana?",3,1,0,52,"",0,4,"aa",-1,0,-1,0,628,628,"3527","",0,"","","",2,0,0,[],""],["carrizo_salta-n3529-01",3,"Una gallina clueca,\nSe fué pa Lima,\nCon 25 pollos\nY un gallo encima.",3,1,0,52,"",3,4,"ia",302,0,-1,0,628,628,"3529","",0,"","","",3,0,0,[],""],["carrizo_salta-n3530-01",3,"Una lechuza me asusta,\nY un zorro me pega el grito.\nSale una vieja gritando:\n—¡Me roban el espirito!",3,1,0,52,"",0,4,"io",119,0,-1,0,628,628,"3530","",0,"","","",1,0,0,[],""],["carrizo_salta-n3531-01",3,"Una monja se tiró un p...\nDetrás del altar mayor,\nY el cura las disparadas,\nCreyendo que era temblor.",3,1,0,52,"",0,4,"o",72,0,-1,0,628,628,"3531","",0,"","","",1,0,0,[],""],["carrizo_salta-n3532-01",3,"Una mujer fué la causa,\nDe la perdición primera,\nNo hay perdición en el mundo,\nQue por mujeres no venga.",3,1,0,52,"",0,4,"ea",-1,0,-1,0,628,628,"3532","",0,"rm_t4, palau_cantares, lafuente_madrid","","",5,0,0,[],""],["carrizo_salta-n3533-01",3,"Una mujer me contaba,\nDiciendo que me quería,\nMe pedía una muda i ropa,\nY un par de pesos al día.",3,1,0,52,"",0,4,"ia",0,0,-1,0,629,629,"3533","",0,"","","",2,0,0,[],""],["carrizo_salta-n3534-01",3,"Una negra lloró un día,\nPorque el negro le pegaba,\nY si el negro no lo hacía,\nLa negra se le enojaba.",3,1,0,52,"",1,4,"aa",28,0,-1,0,629,629,"3534","",0,"","","",1,0,0,[],""],["carrizo_salta-n3535-01",3,"Una negrita llorando,\nQuería volverme loco,\nCon lágrimas me engañaba,\nY su llanto era por otro.",3,1,0,52,"",0,4,"oo",-1,0,-1,0,629,629,"3535","",0,"","","",1,0,0,[],""],["carrizo_salta-n3536-01",3,"Una niña en un baile,\nCarne vendía,\n¿Dónde se ha visto en un baile,\nCarnicería?",3,1,0,52,"",6,4,"ia",0,0,-1,0,629,629,"3536","",0,"","","",6,0,0,[],""],["carrizo_salta-n3537-01",3,"Una pulga con botines,\nY un piojo de botas fuertes,\nA una pobrecita liendre,\nLa han sentenciado de muerte.",3,1,0,52,"",0,4,"ee",-1,0,-1,0,629,629,"3537","",0,"","","",1,0,0,[],""],["carrizo_salta-n3538-01",3,"Una pulga saltando,\nPartió un adobe,\nSalió el piojo enojado,\nCon el revólver.",3,1,0,52,"",6,4,"oe",-1,0,-1,0,629,629,"3538","",0,"","","",2,0,0,[],""],["carrizo_salta-n3539-01",3,"Una rubia se casó,\nCon un negro colorín,\nY los hijitos salieron,\nDel color del aserrín.",3,1,0,52,"",0,4,"i",211,0,-1,0,629,629,"3539","",0,"","","",1,0,0,[],""],["carrizo_salta-n3540-01",3,"Unas dos me andan queriendo,\nY yo ando como ladilla;\nUnita es de lao de abajo,\nLa otrita es de lao de arriba.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,629,629,"3540","",0,"","","",1,0,0,[],""],["carrizo_salta-n3541-01",3,"Una tarde a media tarde,\nA la voz de un tero-tero,\nCantaban un argumento,\nLa oveja con el carnero.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,629,629,"3541","",0,"","","",1,0,0,[],""],["carrizo_salta-n3542-01",3,"Una vez canté en mi casa,\nY mi voz llegaba al mar;\nSe aficionó una sirena,\nY me tuve que callar.",3,1,0,52,"",0,4,"a",21,0,-1,0,629,629,"3542","",0,"","","",1,0,0,[],""],["carrizo_salta-n3543-01",3,"Una vez me fuí a gatiar,\nDirigido al Arbol Sólo,\nCasi me morí de susto,\nOyendo gritar un zorro.",3,1,0,52,"",0,4,"oo",-1,0,-1,0,629,629,"3543","",0,"","","",1,0,0,[],""],["carrizo_salta-n3544-01",3,"Una vez quise a una vieja,\nDespués me solía pesar,\nPor que delante la gente,\nMe sabía querer besar.",3,1,0,52,"",0,4,"a",21,0,-1,0,629,629,"3544","",0,"","","",1,0,0,[],""],["carrizo_salta-n3545-01",3,"Una vieja bailando,\n¡Miren qué vieja!\nMe estaba haciendo señas,\nCon las orejas.",3,1,0,52,"",6,4,"ea",-1,0,-1,0,630,630,"3545","",0,"","","",1,0,0,[],""],["carrizo_salta-n3546-01",3,"Una veija de cien años,\nY un viejo de ciento diez,\nLa vieja se cayó antarca,\nY el viejo de cuatro piés.",3,1,0,52,"",0,4,"e",218,0,-1,0,630,630,"3546","",0,"","","",1,0,0,[],""],["carrizo_salta-n3547-01",3,"Una vieja en la cocina,\nEnojada patió una olla,\nY lo pasó todo el día,\nRezongando como colla.",3,1,0,52,"",0,4,"oa",453,0,-1,0,630,630,"3547","",0,"","","",1,0,0,[],""],["carrizo_salta-n3548-01",3,"Una vieja lavaba un trapo,\nQue con guarapo, que con legía,\nY el trapo quedaba sucio,\n¿Con qué demonios lo ensuciaría?",3,1,0,52,"",3,4,"ia",0,0,-1,0,630,630,"3548","",0,"","","",1,0,0,[],""],["carrizo_salta-n3549-01",3,"Una vieja me dijo:\n—Cara i guanaco.\nYo le dije a la vieja:\n—Cara i sobaco.",3,1,0,52,"",6,4,"ao",423,0,-1,0,630,630,"3549","",0,"","","",1,0,0,[],""],["carrizo_salta-n3550-01",3,"Una vieja muy matera,\nUn día le faltó el mate,\nNo tenía yerba ni azúcar,\nLo puso al viejo en remate.",3,1,0,52,"",0,4,"ae",384,0,-1,0,630,630,"3550","",0,"","","",1,0,0,[],""],["carrizo_salta-n3551-01",3,"Una vieja muy vieja,\nDe un pantión viejo,\nSe me arrancó ensillada,\nCon aparejo.",3,1,0,52,"",6,4,"eo",264,0,-1,0,630,630,"3551","",0,"","","",2,0,0,[],""],["carrizo_salta-n3551-a-01",3,"La vieja me llevaba,\nTras de una tala,\nComo la vieja era mala,\nBellaquiaba y me voltiaba.",3,1,0,52,"",3,4,"aa",-1,0,-1,0,630,630,"3551-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3552-01",3,"Una vieja se tiró un p...\nDentro de una olla,\nSalieron los garbanzos:\n—¡Misericordia!",3,1,0,52,"",6,4,"oa",-1,0,-1,0,630,630,"3552","",0,"","","",1,0,0,[],""],["carrizo_salta-n3553-01",3,"Una vieja se comió\nCiento cincuenta tomates,\nA eso de la media noche,\nSe quebró el catre.",3,1,0,52,"",3,4,"ae",-1,0,-1,0,630,630,"3553","",0,"","","",2,0,0,[],""],["carrizo_salta-n3554-01",3,"Una vieja tuerta y renga,\nEnferma de nacimiento,\nTodavía tuvo coraje,\nDe hablarme de casamiento.",3,1,0,52,"",0,4,"eo",94,0,-1,0,630,630,"3554","",0,"","","",1,0,0,[],""],["carrizo_salta-n3555-01",3,"Una vieja tuvo una hija,\nYo la supe visitar;\nComo la vieja era mala,\nMe andaba por garrotiar.",3,1,0,52,"",0,4,"a",21,0,-1,0,630,630,"3555","",0,"","","",1,0,0,[],""],["carrizo_salta-n3556-01",3,"Una vieja y un candil,\nHacen falta en una casa,\nLa vieja para rezongos,\nY el candil pa freir grasa.",3,1,0,52,"",0,4,"aa",123,0,-1,0,631,631,"3556","",0,"","","",2,0,0,[],""],["carrizo_salta-n3557-01",3,"Una vieja y un viejo,\nTejen bayeta,\nY cuando el viejo afloja,\nLe vieja apreta.",3,1,0,52,"",6,4,"ea",200,0,-1,0,631,631,"3557","",0,"","","",4,0,0,[],""],["carrizo_salta-n3558-01",3,"Una vieja y un viejo,\nVienen de Europa,\nLa vieja le relincha,\nY el viejo trota.",3,1,0,52,"",6,4,"oa",-1,0,-1,0,631,631,"3558","",0,"","","",4,0,0,[],""],["carrizo_salta-n3559-01",3,"Una viejita lloraba,\nLa pérdida del marido,\nY debajo de la cama,\nTenía otro metido.",3,1,0,52,"",0,4,"io",101,0,-1,0,631,631,"3559","",0,"","","",1,0,0,[],""],["carrizo_salta-n3560-01",3,"Una vizcacha me asusta,\nUn zorro me pega el grito,\nY una lechuza contesta:\n¡Tara, t a r a! con su pico.",3,1,0,52,"",0,4,"io",-1,0,-1,0,631,631,"3560","",0,"","","",1,0,0,[],""],["carrizo_salta-n3561-01",3,"Un ciego estaba escribiendo,\nLo que un mudo le dictaba;\nComo la carta era urgente,\nUn sucho se la llevaba.",3,1,0,52,"",0,4,"aa",28,0,-1,0,631,631,"3561","",0,"","","",3,0,0,[],""],["carrizo_salta-n3562-01",3,"Un ciego sacó el reloj,\nPara ver qué horas tenía,\nEran las cuatro y decía:\nFaltan tres para las dos.",3,1,0,52,"",5,4,"o",-1,0,-1,0,631,631,"3562","",0,"","","",1,0,0,[],""],["carrizo_salta-n3563-01",3,"Un colla estaba muriendo,\nCon su acuyico en la boca,\nY preguntaba a la muerte,\nSi en el cielo vendían coca.",3,1,0,52,"",0,4,"oa",178,0,-1,0,631,631,"3563","",0,"","","",1,0,0,[],""],["carrizo_salta-n3564-01",3,"Un franciscano,\nMe mandó llamar,\nYo no se qué quiere,\nSu paternidad.",3,1,0,52,"",6,4,"a",-1,0,-1,0,631,631,"3564","",0,"","","",1,0,0,[],""],["carrizo_salta-n3565-01",3,"Un manco estaba escribiendo,\nLo que un mudo le dictaba,\nY un ciego estaba leyendo,\nMientras un sordo escuchaba.",3,1,0,52,"",1,4,"aa",28,0,-1,0,632,632,"3565","",0,"","","",1,0,0,[],""],["carrizo_salta-n3566-01",3,"Uno, dos, tres, cuatro, cinco,\nSeis, siete, ocho, nueve y diez.\nAsí los tengo contados,\nA los dedos de los piés.",3,1,0,52,"",0,4,"e",218,0,-1,0,632,632,"3566","",0,"","","",3,0,0,[],""],["carrizo_salta-n3567-01",3,"Uno, más uno y más uno,\nY más uno ya son cuatro,\nAsí contaba un paciente,\nTodos los pelos del gato.",3,1,0,52,"",0,4,"ao",-1,0,-1,0,632,632,"3567","",0,"","","",1,0,0,[],""],["carrizo_salta-n3568-01",3,"Un pato pelao volaba,\nEncima de una laguna;\nOtros patos se reían,\nDe verlo volar sin plumas.",3,1,0,52,"",0,4,"ua",-1,0,-1,0,632,632,"3568","",0,"","","",1,0,0,[],""],["carrizo_salta-n3568-a-01",3,"Yo vide volar un sapo,\nArriba de una laguna,\nY los patos se almiraron,\nDe verlo volar sin plumas.",3,1,0,52,"",0,4,"ua",-1,0,-1,0,632,632,"3568-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3569-01",3,"Un santiagueño se ha muerto,\nPor que le ha llegado 1' hora,\nCómo será i desgraciao\nQue ni la mama le llora.",3,1,0,52,"",0,4,"oa",107,0,-1,0,632,632,"3569","",0,"","","",1,0,0,[],""],["carrizo_salta-n3570-01",3,"Un sapo con una araña,\nTuvieron una cuestión.\nEl uno por vivaracho,\nEl otro por dormilón.",3,1,0,52,"",0,4,"o",31,0,-1,0,632,632,"3570","",0,"","","",1,0,0,[],""],["carrizo_salta-n3571-01",3,"Un sordo como tapia,\nMe dijo un día,\nQue todos le gritaban,\n¿Por qué sería?",3,1,0,52,"",6,4,"ia",0,0,-1,0,632,632,"3571","",0,"","","",1,0,0,[],""],["carrizo_salta-n3572-01",3,"Un tucumano se ha muerto,\nPor que le ha llegado el día,\nHaganlé la cruz bendita,\nCon cáscaras de sandías.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,632,632,"3572","",0,"","","",1,0,0,[],""],["carrizo_salta-n3573-01",3,"Un zapatero y un sastre\nY un oficial de barbero,\nSon tres personas distintas,\nY ninguno verdadero.",3,1,0,52,"",0,4,"eo",38,0,-1,0,632,632,"3573","",0,"palau_cantares, lafuente_madrid, fernan_caballero","","",9,0,0,[],""],["carrizo_salta-n3574-01",3,"Usted doña Pancha,\nCon tanto carnaval,\nSeguro que no plancha,\nNi está para lavar.",3,1,0,52,"",0,4,"a",-1,0,-1,0,632,632,"3574","",0,"","","",1,0,0,[],""],["carrizo_salta-n3575-01",3,"¡Válgame Dios de los cielos!\n¡Qué chango tan imprudente!\nPonerse a pedir besitos,\nDelante de tanta gente.",3,1,0,52,"",0,4,"ee",15,0,-1,0,633,633,"3575","",0,"","","",33,0,0,[],""],["carrizo_salta-n3575-a-01",3,"¡Válgame Dios de los cielos!\n¡Qué moza tan imprudente!\nQue se pone a presumir,\nDelante de tanta gente.",3,1,0,52,"",0,4,"ee",15,0,-1,0,633,633,"3575-a","",0,"","","",33,0,0,[],""],["carrizo_salta-n3576-01",3,"¡Vamos a la playa!\nQue hay mucho que ver,\nEstá un hombre alegre,\nJunto a su mujer.",3,1,0,52,"",0,4,"e",20,0,-1,0,633,633,"3576","",0,"","","",3,0,0,[],""],["carrizo_salta-n3577-01",3,"¡Vamos a al plaza!\nQue hay mucho que ver,\nCaballitos blancos,\nHechos de papel.",3,1,0,52,"",6,4,"e",-1,0,-1,0,633,633,"3577","",0,"","","",1,0,0,[],""],["carrizo_salta-n3578-01",3,"¡Vamos a la plaza!\nQue hay mucho que ver,\nUn colla borracho\nJunto a su mujer.",3,1,0,52,"",0,4,"e",20,0,-1,0,633,633,"3578","",0,"","","",1,0,0,[],""],["carrizo_salta-n3579-01",3,"¡Vamos, compañeros míos!\n¡Vamos al río a pescar!\nY si mojarras no hallamos,\nViejas duras mos de hallar.",3,1,0,52,"",0,4,"a",21,0,-1,0,633,633,"3579","",0,"","","",1,0,0,[],""],["carrizo_salta-n3580-01",3,"¡Vamos con este amasijo!\n¡Vamos con el nuevo afán!\nComo yo salve mi bollo\nAunque se queme mi pan.",3,1,0,52,"",0,4,"a",147,0,-1,0,633,633,"3580","",0,"","","",1,0,0,[],""],["carrizo_salta-n3581-01",3,"¡Vaya al infierno el amor!\n¡Y quién me enseñó a querer!\nAnoche besé una burra\nCreyendo que era mujer.",3,1,0,52,"",0,4,"e",20,0,-1,0,633,633,"3581","",0,"","","",1,0,0,[],""],["carrizo_salta-n3582-01",3,"Veinticinco caranchos,\nCincuenta jotes,\nTuvieron una disputa,\nPor un ocote.",3,1,0,52,"",6,4,"oe",-1,0,-1,0,633,633,"3582","",0,"","","",1,0,0,[],""],["carrizo_salta-n3583-01",3,"Vengan tres o cuatro manos,\nEn su mortero a moler,\nNo se desperdicia un grano\nEn el mortero de Ud.",3,1,0,52,"",5,4,"u",-1,0,-1,0,633,633,"3583","",0,"","","",1,0,0,[],""],["carrizo_salta-n3584-01",3,"¡Veni para acá vinito!\nConsuelo de mi tristeza,\nYo te mando a la barriga,\nVos te vas a la cabeza.",3,1,0,52,"",0,4,"ea",108,0,-1,0,633,633,"3584","",0,"","","",1,0,0,[],""],["carrizo_salta-n3585-01",3,"Vide correr un zancudo,\nPor el cerro i Tolombón,\nCon una pulga a la cincha,\nY un sapo de redomón.",3,1,0,52,"",0,4,"o",31,0,-1,0,633,633,"3585","",0,"","","",1,0,0,[],""],["carrizo_salta-n3586-01",3,"¡Vidita, si me querís!\nSilbame como perdiz,\nSi no podís con las patas,\nSiquiera con la nariz.",3,1,0,52,"",0,4,"i",335,0,-1,0,633,633,"3586","",0,"","","",10,0,0,[],""],["carrizo_salta-n3587-01",3,"¡Vidita, si me querís\nTe vua llevar a Chicuana!\nTe vua dar un compromiso\nDe una sortija de iguana.",3,1,0,52,"",0,4,"aa",4,0,-1,0,633,633,"3587","",0,"","","",10,0,0,[],""],["carrizo_salta-n3588-01",3,"¿Vos te has pensado Fidel,\nQue yo me quedaba lejos?\nYa te voy a mandar, viejo,\nA sacar leche a un conejo.",3,1,0,52,"",0,4,"eo",264,0,-1,0,634,634,"3588","",0,"","","",1,0,0,[],""],["carrizo_salta-n3589-01",3,"Voy a coquiar esta coca,\nVoy a bendecir mi boca,\nPorque los diablos son muchos,\nY l'agua bendita es poca.",3,1,0,52,"",0,4,"oa",178,0,-1,0,634,634,"3589","",0,"","","",1,0,0,[],""],["carrizo_salta-n3590-01",3,"Voy a fumar un cigarro,\nCon mi guayaca de sapo,\nAl que me pida un cigarro,\nLo doy vuelta de un sopapo.",3,1,0,52,"",1,4,"ao",-1,0,-1,0,634,634,"3590","",0,"","","",3,0,0,[],""],["carrizo_salta-n3591-01",3,"Voy a fumar un cigarro,\nPuchito de una mujer,\nA ver si puedo aguantar,\nQuince días sin comer.",3,1,0,52,"",0,4,"e",20,0,-1,0,634,634,"3591","",0,"","","",3,0,0,[],""],["carrizo_salta-n3592-01",3,"Voy a hacer un testamento,\nTengo muchos herederos,\nEl número de animales,\nEs un chivo y un carnero.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,634,634,"3592","",0,"","","",1,0,0,[],""],["carrizo_salta-n3593-01",3,"Voy a juntar mis trapitos,\nPara hacer un trapo grande,\nYa viene cerca el invierno,\nPa tener con qué taparme.",3,1,0,52,"",0,4,"ae",-1,0,-1,0,634,634,"3593","",0,"","","",1,0,0,[],""],["carrizo_salta-n3594-01",3,"Ya me voy a retirar,\nDe su sala y su cocina,\nYa no toriarán los perros,\nNi gritarán sus gallinas.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,634,634,"3594","",0,"","","",12,0,0,[],""],["carrizo_salta-n3595-01",3,"Ya me voy pa lao de abajo,\nA gozar de lo que es mío,\nA dormir en cama blanda,\nAunque me embrome de frío.",3,1,0,52,"",0,4,"io",3,0,-1,0,634,634,"3595","",0,"","","",3,0,0,[],""],["carrizo_salta-n3596-01",3,"Ya no sé que voy a hacer,\nCon esta vida que vivo,\nDisvariaba por casarme\nPa que otra tenga marido.",3,1,0,52,"",0,4,"io",-1,0,-1,0,634,634,"3596","",0,"","","",1,0,0,[],""],["carrizo_salta-n3597-01",3,"Ya se viene carnaval,\nEn un piojo redomón,\nUna pulga de baquiana,\nCon un sapo de peón.",3,1,0,52,"",0,4,"o",31,0,-1,0,634,634,"3597","",0,"","","",13,0,0,[],""],["carrizo_salta-n3598-01",3,"Ya viene blanquiando el día,\nTiremén con agua fría,\nY no con agua caliente,\nQue esa es mucha tiranía.",3,1,0,52,"",0,4,"ia",0,0,-1,0,634,634,"3598","",0,"","","",2,0,0,[],""],["carrizo_salta-n3599-01",3,"Yo desprecio cama blanda,\nPor dormir en pedregal,\nPorque soy de carne y güeso,\nComo cualquier animal.",3,1,0,52,"",0,4,"a",1,0,-1,0,634,634,"3599","",0,"","","",1,0,0,[],""],["carrizo_salta-n3600-01",3,"Yo les contaré una hazaña,\nTalvez no me quieran creer,\nUn día estando regando,\nCasi me morí de sed.",3,1,0,52,"",0,4,"e",-1,0,-1,0,635,635,"3600","",0,"","","",1,0,0,[],""],["carrizo_salta-n3601-01",3,"Yo me casé con Ud.\nPa dormir con pierna gorda,\nAhora salimos con que es,\nMás flaca que pata de olla.",3,1,0,52,"",0,4,"oa",-1,0,-1,0,635,635,"3601","",0,"","","",1,0,0,[],""],["carrizo_salta-n3602-01",3,"Yo me casé con usted,\nPa dormir en buena cama,\nY usted me sale diciendo,\nQue el colchón no tiene lana.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,635,635,"3602","",0,"","","",7,0,0,[],""],["carrizo_salta-n3603-01",3,"Yo me fuí pa Carnaval,\nA una casita sin gente,\nCon una caja rompida,\nY un bote sin aguardiente.",3,1,0,52,"",0,4,"ee",15,0,-1,0,635,635,"3603","",0,"","","",1,0,0,[],""],["carrizo_salta-n3605-01",3,"Yo me vine de mi tierra,\nSentadito en una silla,\nSólo por venirte a ver,\nCara de yegua tordilla.",3,1,0,52,"",0,4,"ia",162,0,-1,0,635,635,"3605","",0,"","","",2,0,0,[],""],["carrizo_salta-n3606-01",3,"Yo no andoy porque me quieras,\nNi andoy porque me quierás,\nAndoy porque andoy de vicio,\nAndoy porque andoy no más.",3,1,0,52,"",0,4,"a",51,0,-1,0,635,635,"3606","",0,"","","",1,0,0,[],""],["carrizo_salta-n3606-02",3,"Yo caséme con usted\nPor dormir en buena cama,\nY ahora sale diciendo\nQue el colchón no tiene lana.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,635,635,"3606","",0,"","","",1,0,0,[],""],["carrizo_salta-n3607-01",3,"Yo no me quiero casar,\nEstando ya el plazo encima,\nPara no vivir mañana,\nComo caschi en la cocina.",3,1,0,52,"",0,4,"ia",-1,0,-1,0,635,635,"3607","",0,"","","",4,0,0,[],""],["carrizo_salta-n3609-01",3,"Yo no me quiero casar,\nCasarse no es de rigor,\nA los casados les ponen,\nMás cuernos que a un palancón.",3,1,0,52,"",0,4,"o",-1,0,-1,0,635,635,"3609","",0,"","","",4,0,0,[],""],["carrizo_salta-n3609-a-01",3,"Yo no me quiero casar,\nQuiero quedar solterón,\nPorque los casados cargan,\nMás guampas que un palancón.",3,1,0,52,"",0,4,"o",31,0,-1,0,635,635,"3609-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n3610-01",3,"Yo no pretendo muchachas,\nPorque tengo mis razones,\nTanto caminar de balde,\nSe me han roto los calzones.",3,1,0,52,"",0,4,"oe",34,0,-1,0,635,635,"3610","",0,"","","",1,0,0,[],""],["carrizo_salta-n3611-01",3,"Yo no sé como camino,\nLo de atrás para adelante,\nTengo roto hasta los pies,\nDesnudo pero elegante.",3,1,0,52,"",0,4,"ae",47,0,-1,0,635,635,"3611","",0,"","","",1,0,0,[],""],["carrizo_salta-n3612-01",3,"Yo no sé que me ha pasado,\nEn la provincia de Salta,\nEn el cuerpo tengo lana,\nSólo las astas me faltan.",3,1,0,52,"",0,4,"aa",-1,0,-1,0,635,635,"3612","",0,"","","",1,0,0,[],""],["carrizo_salta-n3612-02",3,"Yo me casé con usted\nPor dormir en buena cama,\nY ahora me sale diciendo\nQue el colchón no tiene lana.",3,1,0,52,"",3,4,"aa",-1,0,-1,0,635,635,"3612","",0,"","","",7,0,0,[],""],["carrizo_salta-n3613-01",3,"Yo quería a una viudita,\nCreyéndola con caudal,\nResultó que la viudita,\nNo tenía más que el corral.",3,1,0,52,"",1,4,"a",1,0,-1,0,636,636,"3613","",0,"","","",1,0,0,[],""],["carrizo_salta-n3614-01",3,"Yo quise una blanca rubia,\nQue la estaban adorando,\nVino el diablo y la llevó,\nY a mi me pasó raspando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,636,636,"3614","",0,"","","",1,0,0,[],""],["carrizo_salta-n3615-01",3,"Yo soy ave de los campos,\nY a los aires me levanto,\nEn las solteras tropiezo,\nEn las casadas me espanto.",3,1,0,52,"",0,4,"ao",30,0,-1,0,636,636,"3615","",0,"","","",1,0,0,[],""],["carrizo_salta-n3616-01",3,"Yo soy como el matao viejo,\nQue me levantan coliando,\nPero puesto en media cancha,\nMe han de ganar chicotiando.",3,1,0,52,"",0,4,"ao",33,0,-1,0,636,636,"3616","",0,"","","",1,0,0,[],""],["carrizo_salta-n3617-01",3,"Yo soy como el pelicanto.\nA las nubes me levanto,\nA las chinitas las quiero,\nCon las viejas me hago el santo.",3,1,0,52,"",0,4,"ao",30,0,-1,0,636,636,"3617","",0,"","","",1,0,0,[],""],["carrizo_salta-n3618-01",3,"Yo soy como el pelicante,\nQue a las nubes me levanto,\nAunque soy fiero de cara,\nCon mis gracias los encanto.",3,1,0,52,"",0,4,"ao",30,0,-1,0,636,636,"3618","",0,"","","",1,0,0,[],""],["carrizo_salta-n3619-01",3,"Yo soy como el pericote,\nY a trechos como el ratón,\nComo yo tenga mujer,\nAunque no tenga calzón.",3,1,0,52,"",0,4,"o",31,0,-1,0,636,636,"3619","",0,"","","",1,0,0,[],""],["carrizo_salta-n3620-01",3,"Yo soy como el perro bueno,\nCuando comienzo a ladrar,\nCuando no puedo morder,\nSiquiera lo hi soliviar.",3,1,0,52,"",0,4,"a",21,0,-1,0,636,636,"3620","",0,"","","",1,0,0,[],""],["carrizo_salta-n3621-01",3,"Yo soy como el pobre zorro,\nQue anda de cerro en cerro,\nAl cabo de tanto andar\nMe han de hacer c a.. los perros.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,636,636,"3621","",0,"","","",1,0,0,[],""],["carrizo_salta-n3622-01",3,"Yo soy como el toro chico,\nQue ando de lejos, lejos,\nNo me arribo al rodeo grande,\nDe miedo del toro viejo.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,636,636,"3622","",0,"","","",1,0,0,[],""],["carrizo_salta-n3623-01",3,"Yo soy ese pobre mozo,\nPariente del moro-moro,\nSobrinito del puisquillo.\nAbuelito del güancotro.",3,1,0,52,"",0,4,"oo",-1,0,-1,0,636,636,"3623","",0,"","","",2,0,0,[],""],["carrizo_salta-n3624-01",3,"Yo soy la que canto fiero,\nDejar de cantar no puedo,\nPrimero suelto la voz,\nComo balido i ternero.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,636,636,"3624","",0,"","","",1,0,0,[],""],["carrizo_salta-n3625-01",3,"Yo también diré lo mismo,\nLo que dijo San Benito:\n—Aunque se muera la cabra,\nComo aparezca el chivito.",3,1,0,52,"",0,4,"io",119,0,-1,0,636,636,"3625","",0,"","","",3,0,0,[],""],["carrizo_salta-n3626-01",3,"Yo también era puestero,\nPuestero de \"El Gramillal\",\nArriaron toros y vacas,\nQuedé cuidando el corral.",3,1,0,52,"",0,4,"a",1,0,-1,0,636,636,"3626","",0,"","","",2,0,0,[],""],["carrizo_salta-n3628-01",3,"Yo también voy a decir,\nLo que dijo Salomón:\n—Toditos los negros tienen\nLa geta como un riñón.",3,1,0,52,"",0,4,"o",31,0,-1,0,637,637,"3628","",0,"","","",3,0,0,[],""],["carrizo_salta-n3629-01",3,"Yo tenía mi buen caballo,\nCaballito de moniar,\nAl llegar frente a una casa,\nLomiando me hacía bajar.",3,1,0,52,"",0,4,"a",21,0,-1,0,637,637,"3629","",0,"","","",1,0,0,[],""],["carrizo_salta-n3630-01",3,"Yo tenía una sirvienta,\nQue cocinaba en botella,\nDe verla que era tan guapa,\nCasi me dormí con ella.",3,1,0,52,"",0,4,"ea",6,0,-1,0,637,637,"3630","",0,"","","",2,0,0,[],""],["carrizo_salta-n3631-01",3,"Yo tenía una sirvienta,\nQue sabía soplar el fuego,\nCuando se acabó el respiro,\nLe daba con el sombrero.",3,1,0,52,"",0,4,"eo",-1,0,-1,0,637,637,"3631","",0,"","","",2,0,0,[],""],["carrizo_salta-n3632-01",3,"Yo transito por tu barrio,\nA deshora y al tranquito,\nPa que no diga la gente,\nQue por Tránsito, transito.",3,1,0,52,"",0,4,"io",119,0,-1,0,637,637,"3632","",0,"","","",1,0,0,[],""],["carrizo_salta-n3633-01",3,"Yo tuve una cuestión seria,\nCon una mujer casada,\nEn ausencia del marido,\nNo le perdía la pisada.",3,1,0,52,"",0,4,"aa",49,0,-1,0,637,637,"3633","",0,"","","",1,0,0,[],""],["carrizo_salta-n3634-01",3,"Yo tuve una águila negra,\nVolando se me la fué,\nMe llevó unas bolas nuevas,\nComo las que tiene Ud.",3,1,0,52,"",5,4,"u",-1,0,-1,0,637,637,"3634","",0,"","","",1,0,0,[],""],["carrizo_salta-n3635-01",3,"Yo tuve unos pantalones,\nDe una tela que no había,\nDel peso de los remiendos,\nNi las canillas movía.",3,1,0,52,"",0,4,"ia",0,0,-1,0,637,637,"3635","",0,"","","",1,0,0,[],""],["carrizo_salta-n3636-01",3,"Yo vide un árbol caído,\nY aunque creerlo sea trabajo,\nCon las raíces pa arriba\nY con las ramas pa abajo.",3,1,0,52,"",3,4,"ao",168,0,-1,0,637,637,"3636","",0,"","","",1,0,0,[],""],["carrizo_salta-n3637-01",3,"Yo vide volar un buey,\nNo sé si será verdad,\nY un chanco asaba batatas,\nEn lo profundo del mar.",3,1,0,52,"",0,4,"a",-1,0,-1,0,637,637,"3637","",0,"","","",1,0,0,[],""],["carrizo_salta-n3638-01",3,"Yo vide volar un monte,\nY una torre andar a gatas,\nEn lo profundo del mar,\nUn burro asando batatas.",3,1,0,52,"",0,4,"aa",328,0,-1,0,637,637,"3638","",0,"","","",1,0,0,[],""],["carrizo_salta-n3639-01",3,"Zapatitos blancos,\nTiene mi Pancha,\nYo no sé cómo mea\nQue no los mancha.",3,1,0,52,"",6,4,"aa",446,0,-1,0,637,637,"3639","",0,"","","",1,0,0,[],""],["carrizo_salta-n3640-01",3,"Abracé un campo por mejio,\nY le pegué un alarido,\nY se descolgó del cielo,\nTras de un trueno un refucilo.",3,1,0,53,"",0,4,"io",-1,0,-1,0,639,639,"3640","",0,"","","",1,0,0,[],""],["carrizo_salta-n3641-01",3,"A causa del tincunaco,\nY por las ollas,\nSe ven los artesanos,\nLlenos de ampollas.",3,1,0,53,"",6,4,"oa",467,0,-1,0,639,639,"3641","",0,"","","",1,0,0,[],""],["carrizo_salta-n3642-01",3,"A esta casita hi llegado,\nPero no me han convidado,\nYo soy un pobre mocito,\nMilagro no me han botado.",3,1,0,53,"",0,4,"ao",14,0,-1,0,639,639,"3642","",0,"","","",1,0,0,[],""],["carrizo_salta-n3643-01",3,"A estas horas hi llegado,\nSaludando atentamente,\nNo me pueden conocer\nTantos años viví ausente.",3,1,0,53,"",0,4,"ee",15,0,-1,0,639,639,"3643","",0,"","","",1,0,0,[],""],["carrizo_salta-n3644-01",3,"Agora en l'actualidad,\nEstá mal completamente,\nEn las pampas calicheras,\nSin trabajo tanta gente.",3,1,0,53,"",0,4,"ee",15,0,-1,0,639,639,"3644","",0,"","","",1,0,0,[],""],["carrizo_salta-n3645-01",3,"Ajustemén las caronas,\nNo me dejen resollar,\nDejemén el campo libre,\nY me verán retuzar.",3,1,0,53,"",0,4,"a",21,0,-1,0,639,639,"3645","",0,"","","",1,0,0,[],""],["carrizo_salta-n3646-01",3,"¡Alabao sea Dios! me llamo,\n¡Por siempre! es mi apelativo\n¿Cómo les va mis señores?\nYo, bueno, para servirles.",3,1,0,53,"",3,4,"ie",-1,0,-1,0,639,639,"3646","",0,"","","",1,0,0,[],""],["carrizo_salta-n3647-01",3,"¡Alabado sea! ¡por siempre!\nAsí le diré al llegar\nCon el sombrero en la mano,\nPara poder saludar.",3,1,0,53,"",0,4,"a",21,0,-1,0,639,639,"3647","",0,"","","",1,0,0,[],""],["carrizo_salta-n3648-01",3,"A las cuatro la mañana,\nCuando coloria la aurora,\nComienzan las tristes aves:\nUnas cantan, otras lloran.",3,1,0,53,"",0,4,"oa",-1,0,-1,0,639,639,"3648","",0,"","","",1,0,0,[],""],["carrizo_salta-n3649-01",3,"A las flores de otoño,\nLas lleva invierno,\nPorque los fríos queman,\nTodo árbol tierno.",3,1,0,53,"",6,4,"eo",225,0,-1,0,639,639,"3649","",0,"","","",1,0,0,[],""],["carrizo_salta-n3650-01",3,"A la virgen del Rosario,\nTambién le debo una luz,\nPara que llegue a mi casa,\nLe pido vida y salud.",3,1,0,53,"",0,4,"u",-1,0,-1,0,639,639,"3650","",0,"","","",3,0,0,[],""],["carrizo_salta-n3651-01",3,"Al caballo corredor,\nNo le falta la manquera,\nY al que canta regular,\nNo le falta la ronquera.",3,1,0,53,"",0,4,"ea",44,0,-1,0,639,639,"3651","",0,"","","",1,0,0,[],""],["carrizo_salta-n3652-01",3,"Al cabo de tanto andar,\nY de vencer imposibles,\nVine a sacar fortaleza,\nDel palo más inservible.",3,1,0,53,"",0,4,"ie",-1,0,-1,0,639,639,"3652","",0,"","","",4,0,0,[],""],["carrizo_salta-n3653-01",3,"Al llegar a alguna casa,\nComo estoy acostumbrado,\nSaludo al grande y al chico,\nPa que sepan qu'hi llegado.",3,1,0,53,"",0,4,"ao",14,0,-1,0,639,639,"3653","",0,"","","",1,0,0,[],""],["carrizo_salta-n3654-01",3,"Alzo mi copita al aire,\nMe acuerdo de Buenos Aires,\nLargo mi copita abajo,\nMe acuerdo de mis trabajos.",3,1,0,53,"",5,4,"ao",-1,0,-1,0,640,640,"3654","",0,"","","",1,0,0,[],""],["carrizo_salta-n3655-01",3,"Allá viene mi vidita,\nCaminando por \"La Costa\",\nCon la bandera en la mano,\nEspantando la langosta.",3,1,0,53,"",0,4,"oa",434,0,-1,0,640,640,"3655","",0,"","","",2,0,0,[],""],["carrizo_salta-n3656-01",3,"¡Amalhayas Dios me diera!\nUna mula y un burrito,\nPara pegar un galope,\nDe Umanao a Corralitos.",3,1,0,53,"",0,4,"io",-1,0,-1,0,640,640,"3656","",0,"","","",3,0,0,[],""],["carrizo_salta-n3657-01",3,"¡Amalhayas Dios me diera!\nUn caballo vaso blanco,\nPara pegar un galope\nDe Gualfín a Palo Blanco.",3,1,0,53,"",0,4,"ao",-1,0,-1,0,640,640,"3657","",0,"","","",3,0,0,[],""],["carrizo_salta-n3657-a-01",3,"¡Amalhayas quién tuviera!\nUn caballo cariblanco,\nPa pegar un galopito,\nDe Gualfín a Palo Blanco.",3,1,0,53,"",0,4,"ao",303,0,-1,0,640,640,"3657-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3658-01",3,"¡Amalhayas quién se viera!\nEn el alto i Cóndorhuasi\nDivisando buenas tierras:\nChañarpunco y Lorohuasi.",3,1,0,53,"",5,4,"ai",-1,0,-1,0,640,640,"3658","",0,"","","",8,0,0,[],""],["carrizo_salta-n3659-01",3,"¡Amalhayas quién se viera!\nEn el alto i Coripampa\nDivisando buenas tierras:\nGuachipas y Talapampa.",3,1,0,53,"",0,4,"aa",413,0,-1,0,640,640,"3659","",0,"","","",8,0,0,[],""],["carrizo_salta-n3660-01",3,"¡Amalhayas quién se viera!\nEn el alto i Pampayana,\nDivisando buenas tierras:\nCorral de Piedra y Anjuana.",3,1,0,53,"",0,4,"aa",4,0,-1,0,640,640,"3660","",0,"","","",8,0,0,[],""],["carrizo_salta-n3661-01",3,"¡Amalhayas quién se viera!\nEn Gualfín o Jasimana\nComiendo chivitos gordos\nCon vinito de Animana.",3,1,0,53,"",0,4,"aa",4,0,-1,0,640,640,"3661","",0,"","","",8,0,0,[],""],["carrizo_salta-n3662-01",3,"¡Amalhayas quién se viera!\nEn los altos de \"El Talar\",\nDivisando buenas tierras,\nCatamarca y Tucumán.",3,1,0,53,"",0,4,"a",-1,0,-1,0,640,640,"3662","",0,"","","",8,0,0,[],""],["carrizo_salta-n3663-01",3,"¡Amalhayas quién se viera!\nEn los altos de \"El Pelao\",\nDivisando buenas tierras,\nCafayate y Colalao.",3,1,0,53,"",0,4,"ao",98,0,-1,0,640,640,"3663","",0,"","","",8,0,0,[],""],["carrizo_salta-n3664-01",3,"¡Amalhayas quién se viera!\nEn los altos de Tafí,\nDivisando buenas tierras,\nColalao donde nací.",3,1,0,53,"",0,4,"i",23,0,-1,0,640,640,"3664","",0,"","","",8,0,0,[],""],["carrizo_salta-n3666-01",3,"¡Amalhayas un caballo!\nMarcado de \"Pozo Chico\"\nPara tirar un galope,\nA mi pago i \"Pasto Chico\".",3,1,0,53,"",0,4,"io",-1,0,-1,0,640,640,"3666","",0,"","","",2,0,0,[],""],["carrizo_salta-n3667-01",3,"¡Amalhayas un cantor!\nQue me cantara en voz alta,\nY me hiciera recordar,\nDe los gauchitos de Salta.",3,1,0,53,"",0,4,"aa",442,0,-1,0,640,640,"3667","",0,"","","",1,0,0,[],""],["carrizo_salta-n3668-01",3,"A mí me dicen pampeña,\nPorque en La Pampa nací,\nA mí me dicen Diguín\nPero no me llamo así.",3,1,0,53,"",0,4,"i",-1,0,-1,0,640,640,"3668","",0,"","","",1,0,0,[],""],["carrizo_salta-n3669-01",3,"A mí me gusta arar fuerte;\nCuando la yunta es pareja,\nAtarle una rama grande,\nY tirarle de l'oreja.",3,1,0,53,"",0,4,"ea",165,0,-1,0,641,641,"3669","",0,"","","",1,0,0,[],""],["carrizo_salta-n3670-01",3,"A mis pobres bueyecitos,\nYo no los voy a alquilar,\nNo los vayan a guasquiar\nEn la cuesta \"El Cebilar\".",3,1,0,53,"",0,4,"a",21,0,-1,0,641,641,"3670","",0,"","","",1,0,0,[],""],["carrizo_salta-n3671-01",3,"Ampascachi triste,\nLa Viña llorando,\nSólo en Puerta i Díaz,\nCantando y bailando.",3,1,0,53,"",0,4,"ao",33,0,-1,0,641,641,"3671","",0,"","","",1,0,0,[],""],["carrizo_salta-n3672-01",3,"Andando de forastero,\nYo sé cómo m'hi mañiar,\nHaciéndome el mosqui-muerto,\nLindamente lo hi pasar.",3,1,0,53,"",0,4,"a",21,0,-1,0,641,641,"3672","",0,"","","",1,0,0,[],""],["carrizo_salta-n3673-01",3,"¿Ande será Cafayate?\nVoy en mi mula rosada,\nTalvez será cordillera,\nLlevo mi buena frazada.",3,1,0,53,"",0,4,"aa",49,0,-1,0,641,641,"3673","",0,"","","",1,0,0,[],""],["carrizo_salta-n3674-01",3,"Antinoche te mandé,\nUna pata y media res,\nSi no fueran tus hermanos,\nTe duraría más de un mes.",3,1,0,53,"",0,4,"e",218,0,-1,0,641,641,"3674","",0,"","","",1,0,0,[],""],["carrizo_salta-n3675-01",3,"Apenitas voy saliendo,\nPor la cuesta \"El Cerro Bayo\",\nDivisando buenas tierras\nPucarilla y Guasamayo.",3,1,0,53,"",0,4,"ao",293,0,-1,0,641,641,"3675","",0,"","","",2,0,0,[],""],["carrizo_salta-n3676-01",3,"¡Apure compañero!\nQue soy de lejos,\nTengo que cortar pasto,\nPa mi conejo.",3,1,0,53,"",6,4,"eo",-1,0,-1,0,641,641,"3676","",0,"","","",1,0,0,[],""],["carrizo_salta-n3677-01",3,"Arriba de una alta peña,\nMe senté a considerar,\nLos mil trabajos que pasa,\nUn marino en alta mar.",3,1,0,53,"",0,4,"a",21,0,-1,0,641,641,"3677","",0,"","","",1,0,0,[],""],["carrizo_salta-n3679-01",3,"Atamiski es una planta,\nQue tiene una blanca flor,\nUnos buscan pa remedio,\nYo la busco pal amor.",3,1,0,53,"",0,4,"o",72,0,-1,0,641,641,"3679","",0,"","","",1,0,0,[],""],["carrizo_salta-n3680-01",3,"Aticen esos tizones\nQue dejen de estar humiando,\nSi por mí para la tropa,\nQue por mí siga marchando.",3,1,0,53,"",0,4,"ao",33,0,-1,0,641,641,"3680","",0,"","","",1,0,0,[],""],["carrizo_salta-n3681-01",3,"Aunque no alquile sus bueyes\nSeis cu... sé manejar,\nEn la Cuesta de las Conchas,\nAhí vamos a rebenquiar.",3,1,0,53,"",0,4,"a",21,0,-1,0,642,642,"3681","",0,"","","",1,0,0,[],""],["carrizo_salta-n3682-01",3,"Ayer dijo el capataz:\n—Ensillá ese redomón,\nSujetá bien de las riendas,\nQue es sillero del patrón.",3,1,0,53,"",0,4,"o",31,0,-1,0,642,642,"3682","",0,"","","",1,0,0,[],""],["carrizo_salta-n3683-01",3,"Ayer salí de mi casa,\nPa volver pasao mañana,\nSi mi viaje es con tardanza,\nVolveré a fin de semana.",3,1,0,53,"",0,4,"aa",-1,0,-1,0,642,642,"3683","",0,"","","",1,0,0,[],""],["carrizo_salta-n3684-01",3,"Ayer tarde salí al campo,\nA correr un mancarrón,\nLos gauchos se hacían pedazos,\nComo rancho en ventarrón.",3,1,0,53,"",0,4,"o",31,0,-1,0,642,642,"3684","",0,"","","",3,0,0,[],""],["carrizo_salta-n3685-01",3,"Ayer tarde salí al campo,\nA recorrer bien temprano,\nUn airecito corría,\nComo si fuera verano.",3,1,0,53,"",0,4,"ao",81,0,-1,0,642,642,"3685","",0,"","","",3,0,0,[],""],["carrizo_salta-n3686-01",3,"¡Ahijuna puta el quirquincho!\nPariente de la tortuga;\nCuando oye ruidito i gente,\nMete la cola y se arruga.",3,1,0,53,"",0,4,"ua",468,0,-1,0,642,642,"3686","",0,"","","",1,0,0,[],""],["carrizo_salta-n3687-01",3,"¡Ahijuay puta palomita!\nCon las alas overitas,\nQuisiera ser halconcito,\nPa hacerte una volcadita.",3,1,0,53,"",0,4,"ia",-1,0,-1,0,642,642,"3687","",0,"","","",1,0,0,[],""],["carrizo_salta-n3688-01",3,"¡Ahijuna, pucha, puchana!\nFlor de hormiga, miel de caña,\n¡Si esta penca diera tunas!\n¡Y este cardón pasacanas!",3,1,0,53,"",0,4,"aa",-1,0,-1,0,642,642,"3688","",0,"","","",1,0,0,[],""],["carrizo_salta-n3689-01",3,"Bala triste el corderillo\nHijo de la blanca oveja,\nEn el corral encerrao,\nMientras su mama se aleja.",3,1,0,53,"",0,4,"ea",165,0,-1,0,642,642,"3689","",0,"","","",1,0,0,[],""],["carrizo_salta-n3690-01",3,"¡Bien haiga mi semillita!\nQue yo la sembré en \"La Costa\",\nNo la pude cosechar,\nPor la maldita langosta.",3,1,0,53,"",0,4,"oa",434,0,-1,0,642,642,"3690","",0,"","","",1,0,0,[],""],["carrizo_salta-n3691-01",3,"Brilla en el cielo de Cachi\nLa estrellita de la tarde,\nQuiero subir a la cumbre,\nPara divisar \"El Valle\".",3,1,0,53,"",0,4,"ae",-1,0,-1,0,642,642,"3691","",0,"","","",1,0,0,[],""],["carrizo_salta-n3692-01",3,"Buenos Aires, buena tierra,\nSanta Fe para llorar,\nDe Los Llanos de La Rioja,\nNo me quisiera olvidar.",3,1,0,53,"",0,4,"a",21,0,-1,0,642,642,"3692","",0,"","","",2,0,0,[],""],["carrizo_salta-n3693-01",3,"Caballo quisiera ser,\nCaballito de carrera,\nPara pegar un galope,\nDe Tilcara a Guacalera.",3,1,0,53,"",0,4,"ea",44,0,-1,0,642,642,"3693","",0,"","","",1,0,0,[],""],["carrizo_salta-n3694-01",3,"Safayate buena tierra,\nAnimaná mejorcito,\nCuando riegan en San Carlos,\nCosechan en Corralitos.",3,1,0,53,"",0,4,"io",-1,0,-1,0,642,642,"3694","",0,"","","",1,0,0,[],""],["carrizo_salta-n3695-01",3,"Cafayate, buena tierra,\nComo ese pago no hay,\nDe las vainas de algarroba,\nSacan el lindo patay.",3,1,0,53,"",0,4,"a",469,0,-1,0,643,643,"3695","",0,"","","",2,0,0,[],""],["carrizo_salta-n3696-01",3,"Cafayate, buena tierra,\nTucumán, mucho mejor,\n¡Qué se quiere comparar\nLa urpila con el pichón!",3,1,0,53,"",0,4,"o",-1,0,-1,0,643,643,"3696","",0,"","","",2,0,0,[],""],["carrizo_salta-n3697-01",3,"Cafayate puro vino,\nY San Carlos mucho trigo,\nLos salteños son de plata,\nTucumanos de batata.",3,1,0,53,"",5,4,"aa",74,0,-1,0,643,643,"3697","",0,"","","",1,0,0,[],""],["carrizo_salta-n3698-01",3,"Carnero sale a los campos,\nEn busca de la majada,\nSi l'halla a la oveja sola,\nLe cantará una tonada.",3,1,0,53,"",0,4,"aa",49,0,-1,0,643,643,"3698","",0,"","","",1,0,0,[],""],["carrizo_salta-n3699-01",3,"¡Catalina, Catalina!\nLindo nombre de Aragón,\n¿Qué encargo me quiere hacer\nQue para España me voy?",3,1,0,53,"",0,4,"o",-1,0,-1,0,643,643,"3699","",0,"","","",2,0,0,[],""],["carrizo_salta-n3700-01",3,"Ciudadano soy, señores,\nCiudadano de \"El Salao\",\nMucho me gusta el mistol,\nPero que sea bien golpiao.",3,1,0,53,"",0,4,"ao",98,0,-1,0,643,643,"3700","",0,"","","",1,0,0,[],""],["carrizo_salta-n3701-01",3,"Corren las nubes del cielo,\nY nadie sabe por qué,\n¿Será por que ha i correr viento?\n¿Será por que va a llover?",3,1,0,53,"",0,4,"e",-1,0,-1,0,643,643,"3701","",0,"","","",1,0,0,[],""],["carrizo_salta-n3702-01",3,"Cuando el cigarro se acaba,\nEl patrón te vuelve a dar,\nPrimero apunta en el libro,\nPor sí se puede olvidar.",3,1,0,53,"",0,4,"a",21,0,-1,0,643,643,"3702","",0,"","","",1,0,0,[],""],["carrizo_salta-n3703-01",3,"Cuando el chancho se ha empacao,\nY está comiendo los perros,\nSe hacen astillas los gauchos,\nA ver cuál mata primero.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,643,643,"3703","",0,"","","",1,0,0,[],""],["carrizo_salta-n3704-01",3,"Cuando el pobre llega a tiempo,\nY los mates van cruzando,\nDan al pobre un mate chulla,\nCon los palitos nadando.",3,1,0,53,"",0,4,"ao",33,0,-1,0,643,643,"3704","",0,"","","",1,0,0,[],""],["carrizo_salta-n3705-01",3,"Cuando en los campos me hallaba,\nTrabajando de puestero,\nTerneritos enlazaba,\nPara echarlos al potrero.",3,1,0,53,"",1,4,"eo",38,0,-1,0,644,644,"3705","",0,"","","",1,0,0,[],""],["carrizo_salta-n3706-01",3,"Cuando está lloviendo mucho,\nHorrorizan las rodadas,\nSi no se cortan las riendas,\nPeligran las cabezadas.",3,1,0,53,"",0,4,"aa",282,0,-1,0,644,644,"3706","",0,"","","",1,0,0,[],""],["carrizo_salta-n3707-01",3,"Cuando están cebando mate,\nY yo me encuentro presente,\nO me dan un mate frío,\nO un chulla, amargo y caliente.",3,1,0,53,"",0,4,"ee",15,0,-1,0,644,644,"3707","",0,"","","",1,0,0,[],""],["carrizo_salta-n3708-01",3,"Cuando la tropa i carros\nViene llegando,\nYa salen los vallistos\nRemolineando.",3,1,0,53,"",6,4,"ao",33,0,-1,0,644,644,"3708","",0,"","","",1,0,0,[],""],["carrizo_salta-n3709-01",3,"Cuando me fui para Chile,\nMe enterraba la nevada,\nMis pobres ojos se helaban,\nY mi corazón lloraba.",3,1,0,53,"",0,4,"aa",-1,0,-1,0,644,644,"3709","",0,"","","",3,0,0,[],""],["carrizo_salta-n3710-01",3,"Cuando me fuí para Chile,\nY me topó el \"Viento blanco\",\nLloraban mis tristes ojos,\nLágrimas de amargo llanto.",3,1,0,53,"",0,4,"ao",-1,0,-1,0,644,644,"3710","",0,"","","",3,0,0,[],""],["carrizo_salta-n3711-01",3,"Cuando salgo de este pago,\nAlto mi lazo a los tientos,\nAlzo, mi vida, a las ancas,\nY me acuerdo de mis tiempos.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,644,644,"3711","",0,"","","",1,0,0,[],""],["carrizo_salta-n3711-a-01",3,"Cuando ensillo mi caballo,\nMe recuerdo de mis tiempos,\nAlzo mi gaucha a las ancas,\nY echo mi lazo a los tientos.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,644,644,"3711-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n3712-01",3,"Cuando salí de mi pago,\nBlanco era como almidón,\nAhora en lejanas tierras,\nSoy más negro que el carbón.",3,1,0,53,"",0,4,"o",31,0,-1,0,644,644,"3712","",0,"","","",4,0,0,[],""],["carrizo_salta-n3713-01",3,"Cuando salí de mi pago,\nSalí por unos poleares,\nA visitar los fragüenos,\nY a conocer los lugares.",3,1,0,53,"",0,4,"ae",164,0,-1,0,644,644,"3713","",0,"","","",4,0,0,[],""],["carrizo_salta-n3714-01",3,"Cuando un potrillo relincha,\nEs porque algo ha de desiar,\nSi no es la leche su madre,\nEs porque no sabe hablar.",3,1,0,53,"",0,4,"a",21,0,-1,0,644,644,"3714","",0,"","","",1,0,0,[],""],["carrizo_salta-n3716-01",3,"De abajo viene lloviendo,\nEl mundo se viene abriendo,\nLos pastos se van secando,\nAdelante floreciendo.",3,1,0,53,"",0,4,"eo",52,0,-1,0,645,645,"3716","",0,"","","",3,0,0,[],""],["carrizo_salta-n3717-01",3,"¿De ande salís, colla chuta,\nEn esta noche tan clara,\nA echar pelos a la leche\nY a ensuciarme la cuchara?",3,1,0,53,"",0,4,"aa",57,0,-1,0,645,645,"3717","",0,"","","",1,0,0,[],""],["carrizo_salta-n3718-01",3,"De Caracoles pa arriba,\nCaminando treinta leguas,\nAhí se separan las huellas:\nMejillones y Las Cuevas.",3,1,0,53,"",0,4,"ea",-1,0,-1,0,645,645,"3718","",0,"","","",2,0,0,[],""],["carrizo_salta-n3719-01",3,"Decía una boliviana,\nMirando un mocito rubio:\n— ¡Maimanta que ha i ser el mío!\nEse mocito es el tuyo.",3,1,0,53,"",0,4,"uo",-1,0,-1,0,645,645,"3719","",0,"","","",1,0,0,[],""],["carrizo_salta-n3720-01",3,"De la breva nace el higo,\nDe la cebadilla el trigo,\nDe la leche la cuajada,\nDe la cuajada el quesillo.",3,1,0,53,"",0,4,"io",-1,0,-1,0,645,645,"3720","",0,"","","",1,0,0,[],""],["carrizo_salta-n3720-a-01",3,"Después de la breva el higo,\nY con la cebada el trigo;\nDe la leche la cuajada,\nDe la cuajada, el quesillo.",3,1,0,53,"",0,4,"io",-1,0,-1,0,645,645,"3720-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3721-01",3,"De la noche a la mañana,\nCuando va saliendo el sol,\nLas tortolitas palomas,\nBuscan un nido de amor.",3,1,0,53,"",0,4,"o",-1,0,-1,0,645,645,"3721","",0,"","","",2,0,0,[],""],["carrizo_salta-n3722-01",3,"De mi casa para fuera,\nOí gritar a un perdido,\nEste había sido el Amor,\nCompañero y fiel amigo.",3,1,0,53,"",0,4,"io",-1,0,-1,0,645,645,"3722","",0,"","","",2,0,0,[],""],["carrizo_salta-n3723-01",3,"Dentre las aves del campo,\nMe gusta el pala-palita,\nTiene patita cholita,\nY la cabeza pilita.",3,1,0,53,"",0,4,"ia",50,0,-1,0,645,645,"3723","",0,"","","",1,0,0,[],""],["carrizo_salta-n3724-01",3,"De Rumiarco m' hi venío,\nEn mi caballo picazo,\nSombrero de sobrepelo,\nMi faja de cuenta i lazo.",3,1,0,53,"",0,4,"ao",43,0,-1,0,645,645,"3724","",0,"","","",1,0,0,[],""],["carrizo_salta-n3725-01",3,"De Salta vengo, señores,\nPor Zuviría y Chicuana,\nLos cotos me han convidado,\nQuesillo con lachiguana.",3,1,0,53,"",0,4,"aa",4,0,-1,0,646,646,"3725","",0,"","","",1,0,0,[],""],["carrizo_salta-n3725-a-01",3,"Desde mi pago hi venío,\nPasando para Chicuana,\nPorque allá me han convidao,\nQuesillo con lachiguana.",3,1,0,53,"",0,4,"aa",4,0,-1,0,646,646,"3725-a","",0,"","","",6,0,0,[],""],["carrizo_salta-n3726-01",3,"Desde abajo m'hi venío,\nArrastrando mi bajera,\nPor eso todos me dicen,\nMocito cara i cuajera.",3,1,0,53,"",0,4,"ea",44,0,-1,0,646,646,"3726","",0,"","","",11,0,0,[],""],["carrizo_salta-n3727-01",3,"Desde abajo m'hi venío,\nHilando finito el hilo,\nA mi vidita le dije:\nQue me aguarde en aquel filo.",3,1,0,53,"",0,4,"io",247,0,-1,0,646,646,"3727","",0,"","","",11,0,0,[],""],["carrizo_salta-n3728-01",3,"Desde abajo m'hi venío,\nCorriendo en un teatinal,\nEchandomé a las costillas,\nPor detrás del animal.",3,1,0,53,"",0,4,"a",1,0,-1,0,646,646,"3728","",0,"","","",11,0,0,[],""],["carrizo_salta-n3729-01",3,"Desde arriba m'hi venío,\nEn mi potro redomón,\nTraigo una pulga morada,\nDebajo del jaquimón.",3,1,0,53,"",0,4,"o",31,0,-1,0,646,646,"3729","",0,"","","",17,0,0,[],""],["carrizo_salta-n3730-01",3,"Desde arriba m'h'i venío,\nSolito y sin compañero,\nSólo con mi pobre poncho,\nY en el bolsillo el pañuelo.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,646,646,"3730","",0,"","","",1,0,0,[],""],["carrizo_salta-n3731-01",3,"Despacito por las piedras,\nPor lo llano al galopito,\nPero si te apuras mucho,\nNo andarás ni al trotecito.",3,1,0,53,"",0,4,"io",119,0,-1,0,646,646,"3731","",0,"","","",2,0,0,[],""],["carrizo_salta-n3732-01",3,"Después que pintan las uvas,\nViene el chañar madurando;\nY los zorros en las plantas,\nQue se las pelan gritando.",3,1,0,53,"",0,4,"ao",33,0,-1,0,646,646,"3732","",0,"","","",1,0,0,[],""],["carrizo_salta-n3733-01",3,"De toditos mis caballos,\nMejor es mi pierna blanca:\nPara pegar un galope,\nDesde aquí a la Salamanca.",3,1,0,53,"",0,4,"aa",75,0,-1,0,646,646,"3733","",0,"","","",3,0,0,[],""],["carrizo_salta-n3734-01",3,"De toditos mis caballos,\nEl mejorcito es mi blanco,\nDonde lo bota su dueño,\nMuerde el freno y busca el campo.",3,1,0,53,"",0,4,"ao",-1,0,-1,0,646,646,"3734","",0,"","","",3,0,0,[],""],["carrizo_salta-n3734-a-01",3,"De todos mis caballitos,\nMejor es mi pico blanco,\nCuando le ciño la cincha,\nMasca el freno y busca el campo.",3,1,0,53,"",0,4,"ao",-1,0,-1,0,646,646,"3734-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3735-01",3,"De toditos mis caballos,\nEl mejor es mi alazán,\nPara pegar un galope,\nDesde aquí hasta Tucumán.",3,1,0,53,"",0,4,"a",147,0,-1,0,646,646,"3735","",0,"","","",3,0,0,[],""],["carrizo_salta-n3736-01",3,"Dicen que el mundo es redondo,\nPero tiene cuatro cortes,\nTiene el naciente, el poniente,\nTiene el sur y tiene el norte.",3,1,0,53,"",0,4,"oe",-1,0,-1,0,646,646,"3736","",0,"","","",1,0,0,[],""],["carrizo_salta-n3737-01",3,"Dicen que en Guaitiquina,\nDe aquí a dos meses,\nVa empezar el trabajo,\n¿Qué te parece?",3,1,0,53,"",6,4,"ee",-1,0,-1,0,647,647,"3737","",0,"","","",1,0,0,[],""],["carrizo_salta-n3738-01",3,"Echen l'agua por la toma,\nRegaré mi sementera,\nNo digo toda la noche,\nSino un ratito siquiera.",3,1,0,53,"",0,4,"ea",44,0,-1,0,647,647,"3738","",0,"","","",1,0,0,[],""],["carrizo_salta-n3740-01",3,"El almidón es comida,\nEl almidón es mandioca,\nAnoche comí un poquito,\nToavía está dulce mi boca.",3,1,0,53,"",3,4,"oa",178,0,-1,0,647,647,"3740","",0,"","","",1,0,0,[],""],["carrizo_salta-n3741-01",3,"El árbol del monte sabe,\nEl tiempo en que reverdece,\nVuelven las aves al nido,\nTan luego que la hoja crece.",3,1,0,53,"",0,4,"ee",64,0,-1,0,647,647,"3741","",0,"","","",1,0,0,[],""],["carrizo_salta-n3742-01",3,"El caballo que yo tengo,\nCría es de un potro castaño,\nEn cada casa que llega,\nSaluda como cristiano.",3,1,0,53,"",0,4,"ao",-1,0,-1,0,647,647,"3742","",0,"","","",1,0,0,[],""],["carrizo_salta-n3743-01",3,"El gallo con la gallina,\nCastian dentro la cocina,\nLas cabras y las ovejas,\nCastian en la loma arriba.",3,1,0,53,"",0,4,"ia",-1,0,-1,0,647,647,"3743","",0,"","","",1,0,0,[],""],["carrizo_salta-n3744-01",3,"El hombre es como la bola,\nPa rodar como pelota,\nLe toca la mala suerte,\nDe una provincia para otra.",3,1,0,53,"",0,4,"oa",-1,0,-1,0,647,647,"3744","",0,"","","",1,0,0,[],""],["carrizo_salta-n3745-01",3,"El hombre que sale al campo,\nSale forrado de cueros,\nSi llega a empacar un tigre\nVuela a defender sus perros.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,647,647,"3745","",0,"","","",1,0,0,[],""],["carrizo_salta-n3746-01",3,"El oso es mal enemigo,\nCuando se llega a empacar,\n¡Pobrecito de aquel hombre,\nQue se ha dejado abrazar!",3,1,0,53,"",0,4,"a",21,0,-1,0,647,647,"3746","",0,"","","",1,0,0,[],""],["carrizo_salta-n3747-01",3,"El perro que olfatia al tigre,\nVa despacito y al trote,\nY el hombre que no es cobarde,\nVa secretiándolo al monte.",3,1,0,53,"",0,4,"oe",-1,0,-1,0,647,647,"3747","",0,"","","",1,0,0,[],""],["carrizo_salta-n3748-01",3,"El que quiera chupar caña,\nQue vaya al cañaveral,\nAllá tiene larga y corta,\nComo cañas de pescar.",3,1,0,53,"",0,4,"a",-1,0,-1,0,647,647,"3748","",0,"","","",1,0,0,[],""],["carrizo_salta-n3749-01",3,"El que salió de su casa,\nSólo la prisión merece,\nPara abajo es buena tierra,\nPero de agua se padece.",3,1,0,53,"",0,4,"ee",64,0,-1,0,648,648,"3749","",0,"","","",1,0,0,[],""],["carrizo_salta-n3750-01",3,"El que se va se consuela\nCon las leguas del camino,\nPorque va con la esperanza,\nDe llegar a su destino.",3,1,0,53,"",0,4,"io",199,0,-1,0,648,648,"3750","",0,"","","",1,0,0,[],""],["carrizo_salta-n3751-01",3,"El yesquero de pitar,\nMe han sentenciado quitar,\nY el eslabón de echar fuego,\nMe lo han de quitar más luego.",3,1,0,53,"",5,4,"eo",29,0,-1,0,648,648,"3751","",0,"","","",1,0,0,[],""],["carrizo_salta-n3752-01",3,"En el monte en que vivimos,\nEntre chanchos y leones,\nPara perseguir al tigre,\nSe necesitan varones.",3,1,0,53,"",0,4,"oe",34,0,-1,0,648,648,"3752","",0,"","","",1,0,0,[],""],["carrizo_salta-n3753-01",3,"Enero poco, Febrero loco,\nMarzo poquito poco.\nY lo que llueve en Abril,\nCabe entero en un barril.",3,1,0,53,"",3,4,"i",290,0,-1,0,648,648,"3753","",0,"","","",1,0,0,[],""],["carrizo_salta-n3754-01",3,"En la falda de aquel cerro,\nAnda un minero perdido,\nBuscando la mina rica,\nDel oro más encendido.",3,1,0,53,"",0,4,"io",101,0,-1,0,648,648,"3754","",0,"","","",54,0,0,[],""],["carrizo_salta-n3755-01",3,"En la falda de aquel cerro,\nTengo una flor por brotar,\nLa flor me viene diciendo:\n¡Agüita, me has de regar!",3,1,0,53,"",0,4,"a",21,0,-1,0,648,648,"3755","",0,"","","",54,0,0,[],""],["carrizo_salta-n3756-01",3,"En la falda de aquel cerro,\nYo corrí una vaca overa,\nAl ruido los guardamontes,\nSalí echando polvadera.",3,1,0,53,"",0,4,"ea",44,0,-1,0,648,648,"3756","",0,"","","",54,0,0,[],""],["carrizo_salta-n3758-01",3,"En la plaza venden sándias,\nEn el Cabildo melones,\nEn los bancos de la plaza,\nSe acuestan los dormilones.",3,1,0,53,"",0,4,"oe",34,0,-1,0,648,648,"3758","",0,"","","",1,0,0,[],""],["carrizo_salta-n3759-01",3,"En las peñas donde vivo,\nTengo un cuervo de campero,\nSe levanta y alza el vuelo,\nCuando se alzan mis terneros.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,648,648,"3759","",0,"","","",1,0,0,[],""],["carrizo_salta-n3760-01",3,"En San Carlos mucho trigo,\nEn \"Las Conchas\" almidón,\nCafayate y Tolombón,\nPrendas de mi corazón.",3,1,0,53,"",0,4,"o",31,0,-1,0,648,648,"3760","",0,"","","",1,0,0,[],""],["carrizo_salta-n3761-01",3,"En San Carlos ya no hay viñas,\nTodo el viento lo llevó;\nYa no quedó ni el recuerdo,\nDel San Carlos que pasó.",3,1,0,53,"",0,4,"o",2,0,-1,0,648,648,"3761","",0,"","","",1,0,0,[],""],["carrizo_salta-n3763-01",3,"En Tucumán venden sandías,\nEn Cafayate melones,\nEn Tolombón y San Carlos,\nCuentos y averiguaciones.",3,1,0,53,"",0,4,"oe",34,0,-1,0,649,649,"3763","",0,"","","",1,0,0,[],""],["carrizo_salta-n3764-01",3,"En una mula hi venío,\nAndando me tomó el sueño,\nY la mulita me dijo:\n—¡Amigo, saquemé el freno!",3,1,0,53,"",0,4,"eo",-1,0,-1,0,649,649,"3764","",0,"","","",1,0,0,[],""],["carrizo_salta-n3765-01",3,"Ese toro no es de aquí,\nHa i ser de los bañaderos,\nAhora voy a escuchar bien,\nA ver que tal el garguero.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,649,649,"3765","",0,"","","",4,0,0,[],""],["carrizo_salta-n3766-01",3,"Es la muerte de los piojos,\nLa muerte más diferente:\nUnos mueren en las uñas,\nOtros mueren en los dientes.",3,1,0,53,"",0,4,"ee",-1,0,-1,0,649,649,"3766","",0,"","","",1,0,0,[],""],["carrizo_salta-n3766-a-01",3,"Es la suerte de los piojos,\nUna suerte diferente;\nUnos mueren en las uñas,\nOtros mueren en los dientes.",3,1,0,53,"",0,4,"ee",-1,0,-1,0,649,649,"3766-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3767-01",3,"Este es el remate nuevo,\nEl remate del Queñual,\nAsí se canta y se baila,\nEl día de su señal.",3,1,0,53,"",0,4,"a",1,0,-1,0,649,649,"3767","",0,"","","",12,0,0,[],""],["carrizo_salta-n3768-01",3,"Este es el remate nuevo,\nSacao del cerro \"El Cajón\",\nAsí se canta y se baila,\nCelebrando este mojón.",3,1,0,53,"",0,4,"o",31,0,-1,0,650,650,"3768","",0,"","","",12,0,0,[],""],["carrizo_salta-n3769-01",3,"¡Estrella el amanacer!\n¡Estrellita de alegría!\n¿Cómo no me despertastes,\nAl venir clariando el día?",3,1,0,53,"",0,4,"ia",0,0,-1,0,650,650,"3769","",0,"","","",1,0,0,[],""],["carrizo_salta-n3769-a-01",3,"¡Lucero de la mañana!\nClaro como el mesmo día,\n¿Cómo no me recordaste\nAi primer clariar del día?",3,1,0,53,"",0,4,"ia",-1,0,-1,0,650,650,"3769-a","",0,"","","",22,0,0,[],""],["carrizo_salta-n3770-01",3,"Filo abajo,, filo arriba,\nEchaditos de barriga,\nRecogiendo las pepitas,\nComo si fueran hormigas.",3,1,0,53,"",0,4,"ia",-1,0,-1,0,650,650,"3770","",0,"","","",1,0,0,[],""],["carrizo_salta-n3771-01",3,"Hace decir mi tatita,\nQue tenga muy buenas tardes,\nSi no le vido pasar,\nUna res de buena carne.",3,1,0,53,"",0,4,"ae",-1,0,-1,0,651,651,"3771","",0,"","","",1,0,0,[],""],["carrizo_salta-n3772-01",3,"Hay lazos de cuatro tientos,\nMás fuertes que otros de seis,\nY no consiste en el uso,\nSino en saberlos hacer.",3,1,0,53,"",0,4,"e",-1,0,-1,0,651,651,"3772","",0,"","","",1,0,0,[],""],["carrizo_salta-n3773-01",3,"¡Hermanito de fulano!\n¿Te vas a \"La Ovejería\"?\nTe han de comer los caranches,\nQuedarás la güesería.",3,1,0,53,"",0,4,"ia",0,0,-1,0,651,651,"3773","",0,"","","",1,0,0,[],""],["carrizo_salta-n3774-01",3,"Juahijuna mi tata viejo,\nSe le quebró la picana,\nFué costiando por el monte,\nY se quedó en la cañada.",3,1,0,53,"",0,4,"aa",-1,0,-1,0,651,651,"3774","",0,"","","",1,0,0,[],""],["carrizo_salta-n3775-01",3,"La cabrilla voltia el pelo,\nLa oveja voltia la lana,\nEl peje dentro de l'agua,\nAl año voltia la escama.",3,1,0,53,"",0,4,"aa",-1,0,-1,0,652,652,"3775","",0,"","","",2,0,0,[],""],["carrizo_salta-n3776-01",3,"La chala con el tabaco,\nSer compañeros prometen,\nPara llegar a una casa,\nEl cigarro es alcahuete.",3,1,0,53,"",0,4,"ee",-1,0,-1,0,652,652,"3776","",0,"","","",1,0,0,[],""],["carrizo_salta-n3777-01",3,"La gente de esta jarana,\nJunto a la vieja carreta,\n¡Jarana, jara, jarana,\nBuenos mates con galleta!",3,1,0,53,"",1,4,"ea",200,0,-1,0,652,652,"3777","",0,"","","",1,0,0,[],""],["carrizo_salta-n3778-01",3,"La mujer que quiere a un colla,\nYa sabrá lo que le toca,\nUn pedacito de yista,\nY un atadito de coca.",3,1,0,53,"",0,4,"oa",178,0,-1,0,652,652,"3778","",0,"","","",1,0,0,[],""],["carrizo_salta-n3779-01",3,"Larguen l'agua por la acequia,\nQue se riegue el melonar,\nAunque no sepa comer,\nSiquiera pa convidar.",3,1,0,53,"",0,4,"a",21,0,-1,0,652,652,"3779","",0,"","","",1,0,0,[],""],["carrizo_salta-n3780-01",3,"Las campanas de mi pueblo,\nSí que me quieren de veras,\nCantaron cuando nací,\nLlorarán cuando me muera.",3,1,0,53,"",0,4,"ea",-1,0,-1,0,652,652,"3780","",0,"","","",2,0,0,[],""],["carrizo_salta-n3781-01",3,"Las nubes están cargadas,\nAgua Dios quiere llover,\nMañana por los caminos\nAgua turbia ha de correr.",3,1,0,53,"",0,4,"e",20,0,-1,0,652,652,"3781","",0,"","","",2,0,0,[],""],["carrizo_salta-n3782-01",3,"La vaca viene balando,\nPor medio de aquellas peñas,\nViene pasando cañadas,\nViene buscando la senda.",3,1,0,53,"",0,4,"ea",-1,0,-1,0,652,652,"3782","",0,"","","",1,0,0,[],""],["carrizo_salta-n3783-01",3,"La vida del militar,\nEs una vida privada,\nNo come ni duerme a gusto,\nY vive a la disparada.",3,1,0,53,"",0,4,"aa",49,0,-1,0,652,652,"3783","",0,"","","",1,0,0,[],""],["carrizo_salta-n3784-01",3,"¡Madrecita \"lachiguana\",\nPariente del \"moro-moro\",\nSobrinita de la \"bala\",\nPrima hermana del \"guancoiro\"!",3,1,0,53,"",0,4,"oo",-1,0,-1,0,652,652,"3784","",0,"","","",2,0,0,[],""],["carrizo_salta-n3785-01",3,"Mama se llama Apacheta,\nY mi padre Cerro Negro,\nYo me llamo Cachi-pampa,\nMi apellido es Hervidero.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,652,652,"3785","",0,"","","",2,0,0,[],""],["carrizo_salta-n3785-a-01",3,"Yo me llamo Cachipampa,\nMi apellido es Hervidero,\nMi madre es el Cerro Overo,\nY mi padre el Cerro Negro.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,652,652,"3785-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3786-01",3,"Me gustan dos buenos bueyes,\nDe voltero y de madrino,\nPara ponerles la rastra,\nY mostrarles el camino.",3,1,0,53,"",0,4,"io",199,0,-1,0,653,653,"3786","",0,"","","",1,0,0,[],""],["carrizo_salta-n3786-a-01",3,"Me gusta una yunta i bueyes,\nUn voltero y un madrino,\nAmarrarles un buen palo,\nY mostrarles el camino.",3,1,0,53,"",0,4,"io",199,0,-1,0,653,653,"3786-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3786-b-01",3,"Cuando un buey le salga bueno,\nDe voltero y de madrino,\nAtelé una rama grande,\nY no le limpie el camino.",3,1,0,53,"",0,4,"io",199,0,-1,0,653,653,"3786-b","",0,"","","",1,0,0,[],""],["carrizo_salta-n3787-01",3,"Metamos mano a la obra,\nQue se siga trabajando,\nPor un ratito de empeño,\nTodo el día mañeriando.",3,1,0,53,"",0,4,"ao",33,0,-1,0,653,653,"3787","",0,"","","",1,0,0,[],""],["carrizo_salta-n3788-01",3,"Mis alforjas rotas,\nMi faja pitada,\nMi camisa chiche,\nMi coca mascada.",3,1,0,53,"",0,4,"aa",49,0,-1,0,653,653,"3788","",0,"","","",1,0,0,[],""],["carrizo_salta-n3789-01",3,"Mucho me gusta correr,\nUn novillo bagualón,\nPara dentrarme en el monte,\nDarle guasca al mancarrón.",3,1,0,53,"",0,4,"o",31,0,-1,0,653,653,"3789","",0,"","","",1,0,0,[],""],["carrizo_salta-n3790-01",3,"Nada traigo en las alforjas,\nY nada en el corazón,\nLa mula viene liviana,\nY liviano vengo yo.",3,1,0,53,"",0,4,"o",-1,0,-1,0,653,653,"3790","",0,"","","",1,0,0,[],""],["carrizo_salta-n3791-01",3,"No hay árbol como l'higuera,\nQue da dos frutos al año,\nPrimero da ricas brevas,\nDespués los higos tamaños.",3,1,0,53,"",0,4,"ao",-1,0,-1,0,653,653,"3791","",0,"","","",1,0,0,[],""],["carrizo_salta-n3792-01",3,"No hay otra vida más triste,\nQue la vida del carrero,\nCon el cabresto en la mano,\nSofrenando al cadenero.",3,1,0,53,"",0,4,"eo",38,0,-1,0,653,653,"3792","",0,"","","",1,0,0,[],""],["carrizo_salta-n3793-01",3,"No hay planta como la parra,\nQue nos dé lo suficiente,\nDe la pasa se hace arrope,\nY del arrope aguardiente.",3,1,0,53,"",0,4,"ee",15,0,-1,0,653,653,"3793","",0,"","","",3,0,0,[],""],["carrizo_salta-n3793-a-01",3,"No hay planta como la parra,\nQue da fruto suficiente,\nPrimero: pasas y arrope,\nDespués vino y aguardiente.",3,1,0,53,"",0,4,"ee",15,0,-1,0,653,653,"3793-a","",0,"","","",3,0,0,[],""],["carrizo_salta-n3795-01",3,"¡Palo i nogal!\n¡Palo i chalchal!\nDe día en la collera,\nDe noche al corral.",3,1,0,53,"",6,4,"a",1,0,-1,0,653,653,"3795","",0,"","","",1,0,0,[],""],["carrizo_salta-n3796-01",3,"Para fumar un cigarro,\nTres cosas has de tener,\nEl tabaco y el papel,\nY el fuego con qué prender.",3,1,0,53,"",0,4,"e",-1,0,-1,0,653,653,"3796","",0,"","","",1,0,0,[],""],["carrizo_salta-n3797-01",3,"¿Para qué quiero este toro,\nSi no me ha de dar producto?\n¿Para qué quiero tener\nEn mi tropa un toro bruto?",3,1,0,53,"",0,4,"uo",-1,0,-1,0,654,654,"3797","",0,"","","",1,0,0,[],""],["carrizo_salta-n3798-01",3,"Pa traer un toro malo,\nY echarlo en las invernadas,\nLo ato a la cincha el caballo,\nCon la cabeza tapada.",3,1,0,53,"",0,4,"aa",-1,0,-1,0,654,654,"3798","",0,"","","",2,0,0,[],""],["carrizo_salta-n3799-01",3,"Parece mentira, niña,\nNiña, parece mentira,\nCuando se empaca el varero,\nEi cadenero se estira.",3,1,0,53,"",0,4,"ia",372,0,-1,0,654,654,"3799","",0,"","","",1,0,0,[],""],["carrizo_salta-n3800-01",3,"¡Pobrecito mi caballo!\nHa gastado su herradura,\nComo quiera pasaré,\nPollerudo como cura.",3,1,0,53,"",0,4,"ua",17,0,-1,0,654,654,"3800","",0,"","","",1,0,0,[],""],["carrizo_salta-n3802-01",3,"¿Qué haremos, compañeritos,\nParados en esta esquina?\nVamonós a trabajar,\nA la línia el Guaitiquina.",3,1,0,53,"",0,4,"ia",11,0,-1,0,654,654,"3802","",0,"","","",2,0,0,[],""],["carrizo_salta-n3803-01",3,"¿Qué haremos con tanto toro?\nDe tantos vua capar uno,\nPorque en medio de la tropa,\nQuiero tener un toruno.",3,1,0,53,"",0,4,"uo",230,0,-1,0,654,654,"3803","",0,"","","",1,0,0,[],""],["carrizo_salta-n3804-01",3,"¡Qué lindo para el verano,\nCuando principia a llover!\nTodos los árboles secos,\nVuelven a reverdecer.",3,1,0,53,"",0,4,"e",20,0,-1,0,654,654,"3804","",0,"","","",1,0,0,[],""],["carrizo_salta-n3805-01",3,"¡Qué lindo pelian los toros!\nCuando están en el mogote,\nCuando el uno le aventaja,\nL'otro le baja el cogote.",3,1,0,53,"",0,4,"oe",292,0,-1,0,654,654,"3805","",0,"","","",1,0,0,[],""],["carrizo_salta-n3806-01",3,"Quisiera ser como el toro,\nPara estar en mi rodeo,\nBajar de Ruiz de los Llanos,\nEntre vacas y terneros.",3,1,0,53,"",0,4,"eo",-1,0,-1,0,654,654,"3806","",0,"","","",1,0,0,[],""],["carrizo_salta-n3807-01",3,"¡Río de Guachipas!\n¡Cuan crecido vas!\nTiróte una piedra,\nVuélvome p'atrás.",3,1,0,53,"",0,4,"a",51,0,-1,0,654,654,"3807","",0,"","","",1,0,0,[],""],["carrizo_salta-n3808-01",3,"Salteñitos pura plata,\nCafayate puro vino,\nAmblayistos pura paja,\nColaleños pura añapa.",3,1,0,53,"",5,4,"aa",-1,0,-1,0,654,654,"3808","",0,"","","",1,0,0,[],""],["carrizo_salta-n3809-01",3,"San Carlos es buena tierra,\nEl Carmen para llorar,\nDe Animaná y Cafayate,\nNo me quisiera olvidar.",3,1,0,53,"",0,4,"a",21,0,-1,0,655,655,"3809","",0,"","","",1,0,0,[],""],["carrizo_salta-n3811-01",3,"Sé boliar en campo abierto,\nSé cuidar un parejero,\nSé desollar una res,\nSin pegarle un tajo al cuero.",3,1,0,53,"",0,4,"eo",38,0,-1,0,655,655,"3811","",0,"","","",1,0,0,[],""],["carrizo_salta-n3812-01",3,"¡Se ha perdido un chanbao!\nDijo un vallisto,\nBuscaron por todas partes,\nNadie lo ha visto.",3,1,0,53,"",6,4,"io",273,0,-1,0,655,655,"3812","",0,"","","",1,0,0,[],""],["carrizo_salta-n3813-01",3,"Si esta casa fuera cárcel,\nYo no tendría mucha pena,\nSiendo las cumbreras grillos,\nLas costaneras cadenas.",3,1,0,53,"",0,4,"ea",-1,0,-1,0,655,655,"3813","",0,"","","",1,0,0,[],""],["carrizo_salta-n3814-01",3,"Sólo dos noches y un día,\nEstuve en \"La Cordillera\",\nLloraba a cada momento,\nPidiendo que me volvieran.",3,1,0,53,"",0,4,"ea",-1,0,-1,0,655,655,"3814","",0,"","","",1,0,0,[],""],["carrizo_salta-n3815-01",3,"Soy de Rumiarco,\nSoy rumiarqueña,\nTraigo una rosa,\nCatamarqueña.",3,1,0,53,"",6,4,"ea",291,0,-1,0,655,655,"3815","",0,"","","",1,0,0,[],""],["carrizo_salta-n3816-01",3,"Soy de Salta, soy salteño,\nSoy de Jujuy, soy jujeño,\nAhora que estoy en \"La Isla\",\nSoy de \"La Isla\"; soy isleño.",3,1,0,53,"",0,4,"eo",138,0,-1,0,655,655,"3816","",0,"","","",1,0,0,[],""],["carrizo_salta-n3817-01",3,"Soy ese pobre muchacho,\nQue ha nacido en \"El Potrero\",\nSombrero i lana de oveja,\nY pantalones de cuero.",3,1,0,53,"",0,4,"eo",38,0,-1,0,655,655,"3817","",0,"","","",1,0,0,[],""],["carrizo_salta-n3818-01",3,"Subió la cuesta,\nMiró la pampa,\nY de Tres Cruces,\nSe fué a Abra - Pampa.",3,1,0,53,"",6,4,"aa",-1,0,-1,0,655,655,"3818","",0,"","","",1,0,0,[],""],["carrizo_salta-n3819-01",3,"Taco bola en el árbol,\nDulce lindo azucarao,\nY picando fuerte el sol,\nComeremos bolanchao.",3,1,0,53,"",0,4,"ao",98,0,-1,0,655,655,"3819","",0,"","","",1,0,0,[],""],["carrizo_salta-n3820-01",3,"Tené presente, vidita,\nY la razón me has de dar,\nQue el potro cuando es más bravo,\nSale de mejor andar.",3,1,0,53,"",0,4,"a",21,0,-1,0,655,655,"3820","",0,"","","",1,0,0,[],""],["carrizo_salta-n3821-01",3,"Tengo mi lindo caballo,\nMi lazo y mis nazarenas,\nTambién tengo un arriador\n¡De aquellos que quitan penas!",3,1,0,53,"",0,4,"ea",62,0,-1,0,656,656,"3821","",0,"","","",1,0,0,[],""],["carrizo_salta-n3822-01",3,"Tengo una mula ligera,\nComo el caballo mejor,\nDicen que salen así,\nCuando es overo el hechor.",3,1,0,53,"",0,4,"o",72,0,-1,0,656,656,"3822","",0,"","","",1,0,0,[],""],["carrizo_salta-n3824-01",3,"Tonada cafayateña,\nCantorcito tolombeño,\nLa coplita es fronteriza,\nY el rematador pomeño.",3,1,0,53,"",0,4,"eo",138,0,-1,0,656,656,"3824","",0,"","","",1,0,0,[],""],["carrizo_salta-n3825-01",3,"Tres patadas pegó macho,\nEn el pueblo i Cafayate,\nArrastraba al \"malacara\",\nAlma negra el \"gualacate\".",3,1,0,53,"",0,4,"ae",384,0,-1,0,656,656,"3825","",0,"","","",1,0,0,[],""],["carrizo_salta-n3826-01",3,"Unos corren la vaca,\nOtros la enlazan,\nUnos sacan el sebo,\nOtros la grasa.",3,1,0,53,"",6,4,"aa",-1,0,-1,0,656,656,"3826","",0,"","","",1,0,0,[],""],["carrizo_salta-n3827-01",3,"Vamos a Lima,\nAllá es mejor,\nNo hay Juez de Letras,\nNi Corregidor.",3,1,0,53,"",6,4,"o",72,0,-1,0,656,656,"3827","",0,"","","",1,0,0,[],""],["carrizo_salta-n3828-01",3,"¡Vidita de mi vida!\nSoy de Navarro,\nYo no pico en carreta,\nPico en un carro.",3,1,0,53,"",6,4,"ao",392,0,-1,0,656,656,"3828","",0,"","","",2,0,0,[],""],["carrizo_salta-n3829-01",3,"Voy a pitar un cigarro,\nDe mi chala y mi tabaco,\nNadie me hay privar mis gustos,\nAunque pite cada rato.",3,1,0,53,"",0,4,"ao",-1,0,-1,0,656,656,"3829","",0,"","","",2,0,0,[],""],["carrizo_salta-n3830-01",3,"Ya comienza el carpintero,\nCon el compás y la sierra,\nAcaba con las astillas,\nPrincipia con la madera.",3,1,0,53,"",0,4,"ea",-1,0,-1,0,656,656,"3830","",0,"","","",1,0,0,[],""],["carrizo_salta-n3831-01",3,"Ya me voy pa Cafayate\nRumbiando por la ladera,\nMi mulita rebuznando,\nDe miedo la tembladera.",3,1,0,53,"",0,4,"ea",44,0,-1,0,656,656,"3831","",0,"","","",1,0,0,[],""],["carrizo_salta-n3832-01",3,"Ya mi hi aburrió en \"La Viña\",\nYa me voy para Chicuana,\nAquí los cotos son chicos,\nY allá como lachiguana.",3,1,0,53,"",0,4,"aa",4,0,-1,0,656,656,"3832","",0,"","","",1,0,0,[],""],["carrizo_salta-n3833-01",3,"Ya sale la luna hermosa,\nCon sus colores de plata,\nCon su madejita i seda,\nDando vueltas se desata.",3,1,0,53,"",0,4,"aa",74,0,-1,0,656,656,"3833","",0,"","","",3,0,0,[],""],["carrizo_salta-n3835-01",3,"Ya se viene la nevada,\nTodito viene blanquiando,\nA donde se va asentando,\nEl frío me va quemando.",3,1,0,53,"",0,4,"ao",33,0,-1,0,657,657,"3835","",0,"","","",2,0,0,[],""],["carrizo_salta-n3836-01",3,"Ya se viene la tormenta,\nPor \"La Falda de Zorrilla\",\n¡Saquen la Virgen María,\nSalgan todos de rodilla!",3,1,0,53,"",0,4,"ia",-1,0,-1,0,657,657,"3836","",0,"","","",1,0,0,[],""],["carrizo_salta-n3837-01",3,"Ya se vienen los cantores,\nA cantar en esta pampa,\nY diz que vienen viniendo,\nPor Guachipa y Talapampa.",3,1,0,53,"",0,4,"aa",413,0,-1,0,657,657,"3837","",0,"","","",1,0,0,[],""],["carrizo_salta-n3839-01",3,"Yo me llamo Manuelito,\nMi apellido es José Juan,\nSoy nacido en Buenos Aires,\nEducado en Tucumán.",3,1,0,53,"",0,4,"a",147,0,-1,0,657,657,"3839","",0,"","","",1,0,0,[],""],["carrizo_salta-n3840-01",3,"Yo no soy de estos pagos,\nSoy de Guachipas,\nDonde muquian los mudos,\nY hacen la chicha.",3,1,0,53,"",6,4,"ia",-1,0,-1,0,657,657,"3840","",0,"","","",1,0,0,[],""],["carrizo_salta-n3841-01",3,"Yo sé tirar la semilla,\nSé manejar el arao,\nVd. no me ha de enseñar,\nA recoger lo sembrao.",3,1,0,53,"",0,4,"ao",98,0,-1,0,657,657,"3841","",0,"","","",1,0,0,[],""],["carrizo_salta-n3842-01",3,"Yo soy como buey tropero,\nPa subir en cuesta arriba,\nSe han de cortar las coyundas,\nO hi de quedar de barriga.",3,1,0,53,"",0,4,"ia",-1,0,-1,0,658,658,"3842","",0,"","","",3,0,0,[],""],["carrizo_salta-n3843-01",3,"Yo soy como buey tropero,\nQue marcha en huella profunda,\nCuando me sacan el yugo,\nVuelvo a lamer la coyunda.",3,1,0,53,"",0,4,"ua",326,0,-1,0,658,658,"3843","",0,"","","",3,0,0,[],""],["carrizo_salta-n3844-01",3,"Yo soy como el temporal,\nQue salgo de otro lugar,\nAyer pasé \"La Frontera \",\nDejándoles la humedad.",3,1,0,53,"",0,4,"a",-1,0,-1,0,658,658,"3844","",0,"","","",3,0,0,[],""],["carrizo_salta-n3845-01",3,"Yo vine de Alejandría,\nDe la salamanca i Londres,\nMe encontré con varios hombres,\nDiestros en hechicerías.",3,1,0,53,"BRINDIS (1)",5,4,"ia",-1,0,-1,0,658,658,"3845","",0,"","","",1,0,0,[],""],["carrizo_salta-n3846-01",3,"Adán ha sido de barro,\nEva fué de su costilla,\nDios los ha echao en el mundo,\nPa que los doscitos vivan.",3,1,0,54,"",0,4,"ia",-1,0,-1,0,660,660,"3846","",0,"","","",1,0,0,[],""],["carrizo_salta-n3847-01",3,"A esa repuesta que ha dado,\nEsta pregunta le haré,\nCuando Cristo vino al mundo,\n¿Quién bajó junto con El?",3,1,0,54,"",0,4,"e",-1,0,-1,0,660,660,"3847","",0,"","","",1,0,0,[],""],["carrizo_salta-n3848-01",3,"Al niño recién nacido,\nTodos le ofrecen un don,\nYo soy pobre, nada tengo,\nLe ofrezco mi corazón.",3,1,0,54,"",0,4,"o",31,0,-1,0,660,660,"3848","",0,"","","",2,0,0,[],""],["carrizo_salta-n3849-01",3,"Al pié de esta cruz bendita,\nLe juro a mi Soberano,\nRenunciar malas costumbres,\nY todo placer mundano.",3,1,0,54,"",0,4,"ao",81,0,-1,0,660,660,"3849","",0,"","","",1,0,0,[],""],["carrizo_salta-n3850-01",3,"Al ver que se han unido,\nDos corazones,\nDesde el cielo les caen,\nLas bendiciones.",3,1,0,54,"",6,4,"oe",34,0,-1,0,660,660,"3850","",0,"","","",1,0,0,[],""],["carrizo_salta-n3852-01",3,"¿Cuál es el hilo tan largo,\nQue al cielo pueda llegar?\n—Es el alma del cristiano,\nCuando acaba de expirar.",3,1,0,54,"",0,4,"a",21,0,-1,0,660,660,"3852","",0,"","","",1,0,0,[],""],["carrizo_salta-n3852-a-01",3,"¿Cuál es la soga más alta,\nQue al cielo puede llegar?\n—Es el alma del cristiano\nQue Dios la manda llamar.",3,1,0,54,"",0,4,"a",21,0,-1,0,660,660,"3852-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3853-01",3,"¿Cuándo bajará mi Dios?\n¿Cuándo bajará juzgando\nA los buenos perdonando,\nY a los malos castigando?",3,1,0,54,"",0,4,"ao",33,0,-1,0,660,660,"3853","",0,"","","",1,0,0,[],""],["carrizo_salta-n3854-01",3,"En el cielo hay un naranjo,\nCubierto de azahares blancos,\nPara que el Niño recoja,\n¡Gloria a Dios, gloria a los santos!",3,1,0,54,"",0,4,"ao",-1,0,-1,0,660,660,"3854","",0,"","","",1,0,0,[],""],["carrizo_salta-n3855-01",3,"En la falda está llorando,\nUna ovejita y su cría,\nPor que Jesucristo ha muerto,\nHijo de Santa María.",3,1,0,54,"",0,4,"ia",0,0,-1,0,660,660,"3855","",0,"","","",1,0,0,[],""],["carrizo_salta-n3856-01",3,"En vano es que llore el ángel,\nCuando el alma está perdida.\nEl que no nace pal cielo,\nEn vano es que espie pa arriba.",3,1,0,54,"",0,4,"ia",-1,0,-1,0,660,660,"3856","",0,"","","",1,0,0,[],""],["carrizo_salta-n3857-01",3,"Hoy Miércoles de Ceniza,\nLloraremus, lloraremus,\nCuando venga la Cuaresma,\nRezaremus, rezaremus.",3,1,0,54,"",0,4,"eu",470,0,-1,0,660,660,"3857","",0,"","","",1,0,0,[],""],["carrizo_salta-n3858-01",3,"Los astros del firmamento,\nResplandecen en el cielo,\nDios hizo tanto portento,\nY alumbran el mundo entero.",3,1,0,54,"",0,4,"eo",-1,0,-1,0,661,661,"3858","",0,"","","",3,0,0,[],""],["carrizo_salta-n3861-01",3,"No hay hombre como Dios,\nNi mujer como María,\nNi ángel como San Gabriel,\nNi luz como la del día.",3,1,0,54,"",0,4,"ia",0,0,-1,0,661,661,"3861","",0,"","","",1,0,0,[],""],["carrizo_salta-n3862-01",3,"¡Señora Santa Ana!\nTocá tu campana,\n¡Señor San Joaquín!\nTocá tu violón.",3,1,0,54,"",5,4,"o",-1,0,-1,0,661,661,"3862","",0,"","","",9,0,0,[],""],["carrizo_salta-n3863-01",3,"Yo tiré una piedra al agua,\nSe abrió y se volvió a cerrar,\nAsí concibió María.\nDoncella volvió a quedar.",3,1,0,54,"",0,4,"a",21,0,-1,0,661,661,"3863","",0,"","","",1,0,0,[],""],["carrizo_salta-n3864-01",3,"¡Ah, mundo, que das y quitas,\nLos gustos a cada cual!\n¡Así como das y quitas\nDieras para no quitar!'",3,1,0,55,"",5,4,"",-1,0,-1,0,663,663,"3864","",0,"","","",1,0,0,[],""],["carrizo_salta-n3864-02",3,"El mundo con ser el mundo,\nFacilita a cada cual,\nAsí como da y nos quita,\nPudiera dar sin quitar.",3,1,0,55,"",0,4,"a",-1,0,-1,0,663,663,"3864","",0,"","","",1,0,0,[],""],["carrizo_salta-n3864-03",3,"El tiempo nos da y nos quita,\nLos gustos a cada cuál,\nAsí como da y nos quita,\nPudiera dar sin quitar.",3,1,0,55,"",0,4,"a",-1,0,-1,0,663,663,"3864","",0,"","","",1,0,0,[],""],["carrizo_salta-n3866-01",3,"Al pié de un árbol sin fruta,\nMe puse a considerar,\nLo poco que vale un hombre;\nCuando no tiene qué dar.",3,1,0,55,"",0,4,"a",21,0,-1,0,663,663,"3866","",0,"","","",1,0,0,[],""],["carrizo_salta-n3867-01",3,"Al pobre ya no lo quieren,\nAl viejo no lo saludan,\nCuando lo topan por ahí,\nHasta la cara le mudan.",3,1,0,55,"",0,4,"ua",472,0,-1,0,663,663,"3867","",0,"","","",1,0,0,[],""],["carrizo_salta-n3868-01",3,"Allá voy a ver si puedo,\nVoy dudando si podré;\nSi yo hago mal y prosigo,\nEs porfiar contra la ley.",3,1,0,55,"",0,4,"e",-1,0,-1,0,663,663,"3868","",0,"","","",1,0,0,[],""],["carrizo_salta-n3869-01",3,"¡Amigos y camaradas,\nTodos los que están presente!\nNo quieran mujer casada,\nCuando el marido esté ausente.",3,1,0,55,"",0,4,"ee",15,0,-1,0,663,663,"3869","",0,"","","",1,0,0,[],""],["carrizo_salta-n3870-01",3,"A mí me dicen: ¡cásate!\nYo les digo: ¡bravas penas!\nDejan de cuidar sus vidas,\nPor cuidar vidas ajenas.",3,1,0,55,"",0,4,"ea",62,0,-1,0,663,663,"3870","",0,"","","",2,0,0,[],""],["carrizo_salta-n3871-01",3,"A mí nada se me da,\nDe nada tengo cuidado,\nTengo un amor a mi gusto,\n¡Gracias a Dios, El me ha dado!",3,1,0,55,"",0,4,"ao",14,0,-1,0,663,663,"3871","",0,"","","",3,0,0,[],""],["carrizo_salta-n3872-01",3,"¡Andá corré por el mundo,\nQue el mundo te ha i dar el pago,\nQue también el mundo arregla,\nLo que está mal arreglado!",3,1,0,55,"",0,4,"ao",-1,0,-1,0,663,663,"3872","",0,"","","",1,0,0,[],""],["carrizo_salta-n3872-a-01",3,"¡Echate, mujer, al mundo,\nQue el mundo te dará el pago;\nEl mundo sabe arreglar,\nLo que está mal arreglado!",3,1,0,55,"",0,4,"ao",-1,0,-1,0,663,663,"3872-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n3873-01",3,"Ande quiera soy formal,\nY respeto al más cobarde,\nPorque cuando la chispa arde,\nPriende tuito el pajonal.",3,1,0,55,"",11,4,"a",1,0,-1,0,664,664,"3873","",0,"","","",1,0,0,[],""],["carrizo_salta-n3874-01",3,"Antes cuando yo era mozo,\nEra celoso y bellaco,\nAhora que ya soy viejo,\nTodo lo miro y me agacho.",3,1,0,55,"",0,4,"ao",-1,0,-1,0,664,664,"3874","",0,"","","",4,0,0,[],""],["carrizo_salta-n3875-01",3,"Apostaron a perder,\nDiez pesos contra quinientos,\nA que ni el cura no sabe,\nLa ley de los mandamientos.",3,1,0,55,"",0,4,"eo",234,0,-1,0,664,664,"3875","",0,"","","",1,0,0,[],""],["carrizo_salta-n3875-02",3,"Aquel que más alto sube,\nMás alto porrazo dá,\nPor eso yo me subí,\nA una altura regular.",3,1,0,55,"",0,4,"a",-1,0,-1,0,664,664,"3875","",0,"","","",6,0,0,[],""],["carrizo_salta-n3878-01",3,"Aquí me pongo a decir,\nBajo de esta verde planta:\n¡Hay parados que se caen,\nY cáidos que se levantan!",3,1,0,55,"",0,4,"aa",-1,0,-1,0,664,664,"3878","",0,"","","",1,0,0,[],""],["carrizo_salta-n3879-01",3,"¡Arroyo, no corras tanto!\nMira que no eres eterno,\nQue te quitará el verano,\nLo que te ha dado el invierno.",3,1,0,55,"",0,4,"eo",225,0,-1,0,664,664,"3879","",0,"","","",1,0,0,[],""],["carrizo_salta-n3880-01",3,"Así suceden las cosas,\nCuando no vale un testigo,\nAquel de menos delito,\nSe lleva el mayor castigo.",3,1,0,55,"",0,4,"io",-1,0,-1,0,664,664,"3880","",0,"","","",1,0,0,[],""],["carrizo_salta-n3881-01",3,"Aunque se pierda el sombrero,\nComo quede la toquilla,\nTodos somos pa morir,\nNinguno para semilla.",3,1,0,55,"",0,4,"ia",162,0,-1,0,664,664,"3881","",0,"","","",1,0,0,[],""],["carrizo_salta-n3882-01",3,"Ayer me miré en la cumbre,\nHoy en un guaico profundo,\nSólo por considerar\nLas mudanzas que da el mundo.",3,1,0,55,"",0,4,"uo",179,0,-1,0,664,664,"3882","",0,"","","",1,0,0,[],""],["carrizo_salta-n3883-01",3,"Ayer me ví en alta cumbre,\nHoy día en lo más profundo,\nYo quisiera conocer,\nToda la gente del mundo.",3,1,0,55,"",0,4,"uo",179,0,-1,0,665,665,"3883","",0,"","","",1,0,0,[],""],["carrizo_salta-n3884-01",3,"Ayer me ví en las alturas,\nHoy en los bajos profundos,\nAsí padecen los hombres,\nQue no saben que es el mundo.",3,1,0,55,"",0,4,"uo",-1,0,-1,0,665,665,"3884","",0,"","","",1,0,0,[],""],["carrizo_salta-n3885-01",3,"¡Ay, hijo, si te has casado,\nHas de respetar a Dios!\nQue la vida del casado\nNo dura un año ni dos.",3,1,0,55,"",1,4,"o",87,0,-1,0,665,665,"3885","",0,"","","",1,0,0,[],""],["carrizo_salta-n3886-01",3,"¡Ahijuay, puta lo que somos!\nPal año lo que seremos,\nAlgunos talvez vivamos,\nOtros talvez moriremos.",3,1,0,55,"",0,4,"eo",127,0,-1,0,665,665,"3886","",0,"","","",1,0,0,[],""],["carrizo_salta-n3887-01",3,"¡Ahijuna, puta, desgracia!\nDijo la necesidad,\n¡Demasiado es uno solo,\nPara arruinar un lugar!",3,1,0,55,"",0,4,"a",-1,0,-1,0,665,665,"3887","",0,"","","",1,0,0,[],""],["carrizo_salta-n3888-01",3,"Bajo de un coposo pino,\nOí cantar a la selva:\n—Hoja que la lleva el viento,\nEs imposible que vuelva.",3,1,0,55,"",0,4,"ea",381,0,-1,0,665,665,"3888","",0,"","","",3,0,0,[],""],["carrizo_salta-n3889-01",3,"¡Bien haiga quien dijo amor!\nNo te supo poner nombre,\nMás vale le hubiera puesto:\n\"La perdición de los hombres\".",3,1,0,55,"",0,4,"oe",-1,0,-1,0,665,665,"3889","",0,"","","",1,0,0,[],""],["carrizo_salta-n3890-01",3,"Caudales grandes se acaban,\nDe la noche a la mañana,\nEl río más caudaloso,\nSuele quedarse en la nada.",3,1,0,55,"",0,4,"aa",-1,0,-1,0,665,665,"3890","",0,"","","",2,0,0,[],""],["carrizo_salta-n3891-01",3,"Caudales grandes se acaban,\nSegún la administración,\nPero les queda la fama,\nQue en un tiempo han sido Don.",3,1,0,55,"",0,4,"o",31,0,-1,0,665,665,"3891","",0,"","","",2,0,0,[],""],["carrizo_salta-n3892-01",3,"¿Cómo quieres que haga dulce,\nLa azúcar con el ají?\n¿Qué pones espanto de otras\nCuando todas son así?",3,1,0,55,"",0,4,"i",23,0,-1,0,665,665,"3892","",0,"","","",1,0,0,[],""],["carrizo_salta-n3893-01",3,"Como se alegra una parra,\nCuando la van a podar,\nAsí se alegra una niña,\nCuando se quiere casar.",3,1,0,55,"",0,4,"a",21,0,-1,0,665,665,"3893","",0,"","","",1,0,0,[],""],["carrizo_salta-n3894-01",3,"Cuando el padre le da al hijo,\nRíe el padre y ríe el hijo,\nCuando el hijo le da al padre,\nLlora el padre y llora el hijo.",3,1,0,55,"",0,4,"io",-1,0,-1,0,665,665,"3894","",0,"","","",1,0,0,[],""],["carrizo_salta-n3895-01",3,"Cuando la fortuna empieza,\nA dar golpes con un hombre,\nNo hay cosa que el hombre intente,\nQue la fortuna no estorbe.",3,1,0,55,"",0,4,"oe",-1,0,-1,0,665,665,"3895","",0,"","","",2,0,0,[],""],["carrizo_salta-n3896-01",3,"Cuando la mujer es buena,\nNo hay plata con qué pagarle,\nPero cuando sale mala,\nNo hay palo con qué pegarle.",3,1,0,55,"",0,4,"ae",473,0,-1,0,665,665,"3896","",0,"","","",1,0,0,[],""],["carrizo_salta-n3897-01",3,"Cuando me ven buenas prendas,\nToditos me dan la mano,\nCuando se acaban las prendas,\nNo hay parientes, no hay hermanos.",3,1,0,55,"",0,4,"ao",-1,0,-1,0,666,666,"3897","",0,"","","",1,0,0,[],""],["carrizo_salta-n3897-a-01",3,"Cuando ven un divertido,\nTodos le han de dar la mano,\nSi se acaba el interés,\nYa no hay pariente ni hermano.",3,1,0,55,"",0,4,"ao",81,0,-1,0,666,666,"3897-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3898-01",3,"Cuando recién te casís,\nHalagos has de tener,\nSiguiendo más adelante,\nSólo tormento has de ver.",3,1,0,55,"",0,4,"e",20,0,-1,0,666,666,"3898","",0,"","","",1,0,0,[],""],["carrizo_salta-n3899-01",3,"Cuando tengas un amigo,\nNo le entreguís la confianza,\nPorque el amigo ha de ser,\nLa causa de tu desgracia.",3,1,0,55,"",0,4,"aa",-1,0,-1,0,666,666,"3899","",0,"","","",1,0,0,[],""],["carrizo_salta-n3900-01",3,"Cuando una brasa se apaga,\nCon facilidad se enciende,\nTodas las cosas del mundo,\nEn el ejercicio pende.",3,1,0,55,"",0,4,"ee",233,0,-1,0,666,666,"3900","",0,"","","",1,0,0,[],""],["carrizo_salta-n3901-01",3,"Cuatro puertas tiene abiertas,\nEl que no tiene dinero,\nEl hospital y la cárcel,\nLa iglesia y el cementerio.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,666,666,"3901","",0,"","","",1,0,0,[],""],["carrizo_salta-n3902-01",3,"Debajo de siete cielos,\nNacen los cuatro elementos,\nPrimero, el sol y la luna,\nSegundo, el agua y el viento.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,666,666,"3902","",0,"","","",1,0,0,[],""],["carrizo_salta-n3903-01",3,"Dejelá correr al agua,\nDejelá que se represe,\nQue el pobre dentro los ricos,\nSólo desprecios merece.",3,1,0,55,"",0,4,"ee",64,0,-1,0,666,666,"3903","",0,"","","",1,0,0,[],""],["carrizo_salta-n3904-01",3,"Deje la flor ande nace,\nDejelá en su lugar,\nY cuando llegue el invierno,\nElla se ha i desengañar.",3,1,0,55,"",0,4,"a",21,0,-1,0,666,666,"3904","",0,"","","",1,0,0,[],""],["carrizo_salta-n3905-01",3,"Dejenló al triste llorar,\nY al tonto cuidar lo ajeno,\nQue el triste se ha i consolar,\nY el tonto ha i quedar de dueño.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,666,666,"3905","",0,"","","",1,0,0,[],""],["carrizo_salta-n3906-01",3,"Del novillo se hace el buey,\nDe los fieles el cristiano,\nAsí debimos vivir,\nEntre amigos, como hermanos.",3,1,0,55,"",0,4,"ao",-1,0,-1,0,666,666,"3906","",0,"","","",1,0,0,[],""],["carrizo_salta-n3907-01",3,"Del uno al otro hemisferio,\nEn la vida transitoria,\nCada hombre es un misterio,\nCada mujer una historia.",3,1,0,55,"",1,4,"oa",126,0,-1,0,666,666,"3907","",0,"","","",1,0,0,[],""],["carrizo_salta-n3908-01",3,"De mi pecho sale el llanto,\nDe mi garganta un coral,\nYo no les creo a los hombres,\nAunque los vea llorar.",3,1,0,55,"",0,4,"a",-1,0,-1,0,666,666,"3908","",0,"","","",1,0,0,[],""],["carrizo_salta-n3909-01",3,"¿De qué le sirve al molino,\nQue muela con tanto afán?\nEl solito hace l'harina,\nY otros se comen el pan.",3,1,0,55,"",0,4,"a",147,0,-1,0,666,666,"3909","",0,"","","",1,0,0,[],""],["carrizo_salta-n3910-01",3,"¡Desgraciada la mujer,\nQue se casa sin saber,\nCon hombre que no conoce,\nY no lo ha visto nacer!",3,1,0,55,"",0,4,"e",20,0,-1,0,667,667,"3910","",0,"","","",3,0,0,[],""],["carrizo_salta-n3910-a-01",3,"¡Pobrecito de aquel hombre!\nQue se casa sin saber,\nCon mujer que no conoce,\nY no la ha visto nacer.",3,1,0,55,"",0,4,"e",20,0,-1,0,667,667,"3910-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3911-01",3,"¡De vicio te has de afanar,\nBuscar la plata y el oro,\nSi al verdadero tesoro,\nNo lo procuras buscar.",3,1,0,55,"",11,4,"a",21,0,-1,0,667,667,"3911","",0,"","","",1,0,0,[],""],["carrizo_salta-n3912-01",3,"De viento colao,\nDe caldo recalentao,\nDe mulato acaballerao,\n¡Líbranos, Señor!",3,1,0,55,"",5,4,"o",-1,0,-1,0,667,667,"3912","",0,"","","",2,0,0,[],""],["carrizo_salta-n3912-a-01",3,"De viento colao,\nDe pastel guardao,\nY de indio acaballerao,\n¡Líbranos, Señor!",3,1,0,55,"",5,4,"o",-1,0,-1,0,667,667,"3912-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n3913-01",3,"Dicen las viejas brujas,\nNo creas en sueños.\nPero también me dicen,\n¡Guardate de ellos!",3,1,0,55,"",6,4,"eo",-1,0,-1,0,667,667,"3913","",0,"","","",1,0,0,[],""],["carrizo_salta-n3914-01",3,"Dicen los sabios profundos,\nQue el querer es borrachera,\nQue nos entra por los ojos,\nY nos corre por las venas.",3,1,0,55,"",0,4,"ea",-1,0,-1,0,667,667,"3914","",0,"","","",1,0,0,[],""],["carrizo_salta-n3915-01",3,"Dicen que el amor,\nEs una calavera,\nPrecipita el cuerpo,\nSin que el alma quiera.",3,1,0,55,"",0,4,"ea",44,0,-1,0,667,667,"3915","",0,"","","",1,0,0,[],""],["carrizo_salta-n3916-01",3,"Dicen que el más duro acero,\nSe derrite con la fragua,\nPara quitar un intento,\nSe ha de firmar dentro l'agua.",3,1,0,55,"",0,4,"aa",383,0,-1,0,667,667,"3916","",0,"","","",1,0,0,[],""],["carrizo_salta-n3917-01",3,"Diz que el mundo es una bola,\nPero tiene cuatro esquinas,\nCuando el hombre llega a pobre,\nA todo se determina.",3,1,0,55,"",0,4,"ia",-1,0,-1,0,667,667,"3917","",0,"","","",1,0,0,[],""],["carrizo_salta-n3918-01",3,"Dos amantes se despiden,\nAl pié de una verde oliva,\nComo la oliva es amarga,\nAmarga es la despedida.",3,1,0,55,"",0,4,"ia",-1,0,-1,0,667,667,"3918","",0,"palau_cantares","","",2,0,0,[],""],["carrizo_salta-n3919-01",3,"Echale llaves al pecho,\nY aldabas al corazón,\nSi dejáis la puerta abierta,\nNo es la culpa del ladrón.",3,1,0,55,"",0,4,"o",31,0,-1,0,667,667,"3919","",0,"","","",1,0,0,[],""],["carrizo_salta-n3920-01",3,"¡Echate, mujer al mundo!\nNada tienes que perder,\nAunque te gocen los hombres,\nSiempre mujer has de ser.",3,1,0,55,"",0,4,"e",20,0,-1,0,667,667,"3920","",0,"","","",2,0,0,[],""],["carrizo_salta-n3921-01",3,"El camino de la vida,\nEstá lleno de pedrones;\nPara adelantar un paso,\nHay que pegar trompezones.",3,1,0,55,"",0,4,"oe",34,0,-1,0,667,667,"3921","",0,"","","",2,0,0,[],""],["carrizo_salta-n3922-01",3,"El cazador que cazando,\nNinguna paloma lleva,\nNo pisando en falsas ramas,\nMejor es que a casa vuelva.",3,1,0,55,"",0,4,"ea",-1,0,-1,0,668,668,"3922","",0,"","","",1,0,0,[],""],["carrizo_salta-n3923-01",3,"El cielo es una naranja,\nLos astros son las tajadas,\nEl mundo se hizo de un soplo,\nDe un momento a otro se acaba.",3,1,0,55,"",0,4,"aa",-1,0,-1,0,668,668,"3923","",0,"","","",1,0,0,[],""],["carrizo_salta-n3924-01",3,"El día me ofrece luces,\nLa noche la oscuridad,\nLa vida me ofrece engaños,\nLa muerte una eternidad.",3,1,0,55,"",0,4,"a",16,0,-1,0,668,668,"3924","",0,"","","",1,0,0,[],""],["carrizo_salta-n3925-01",3,"El hombre ciego al nacer,\nProcura a tientas andar,\nY afanoso por correr,\nEmpieza por tropezar.",3,1,0,55,"",1,4,"a",21,0,-1,0,668,668,"3925","",0,"","","",1,0,0,[],""],["carrizo_salta-n3926-01",3,"El hombre no sabe nada,\nSi se ha entregao ciegamente,\nA vivir acomodando,\nA otro capricho su suerte.",3,1,0,55,"",0,4,"ee",-1,0,-1,0,668,668,"3926","",0,"","","",1,0,0,[],""],["carrizo_salta-n3927-01",3,"El hombre que es precavido,\nCuando el peligro es mayor,\nSuele andar con alvertencia,\nPa defenderse mejor.",3,1,0,55,"",0,4,"o",72,0,-1,0,668,668,"3927","",0,"","","",1,0,0,[],""],["carrizo_salta-n3928-01",3,"El hombre que quiere a dos,\nNo alcanza ni pa camisa,\nDebajo de esa pantalla,\nEl que no muere, agoniza.",3,1,0,55,"",0,4,"ia",420,0,-1,0,668,668,"3928","",0,"","","",2,0,0,[],""],["carrizo_salta-n3929-01",3,"El hombre que no se aflige,\nCuando llora una mujer,\nNo ha conocido a su madre,\nNi sabe lo que es querer.",3,1,0,55,"",0,4,"e",20,0,-1,0,668,668,"3929","",0,"","","",2,0,0,[],""],["carrizo_salta-n3930-01",3,"El molinero, el molino,\nMuele el maíz con tanta dicha,\nEl es el que hace l'harina,\nY otros se toman la chicha.",3,1,0,55,"",0,4,"ia",-1,0,-1,0,668,668,"3930","",0,"","","",1,0,0,[],""],["carrizo_salta-n3931-01",3,"El mundo es como una bola,\nRueda como una pelota,\nSi aquí le han pagado mal,\nCambie esta tierra por otra.",3,1,0,55,"",0,4,"oa",-1,0,-1,0,668,668,"3931","",0,"","","",1,0,0,[],""],["carrizo_salta-n3932-01",3,"El mundo está transtornado,\nSegún lo compriendo yo,\nYa no es lo que antes ha sido,\nHoy somos, mañana no.",3,1,0,55,"",0,4,"o",2,0,-1,0,668,668,"3932","",0,"","","",1,0,0,[],""],["carrizo_salta-n3933-01",3,"El que espera desespera,\nEl que no espera no alcanza,\nPor eso es bueno esperar,\nPara tener esperanza.",3,1,0,55,"",0,4,"aa",163,0,-1,0,668,668,"3933","",0,"","","",1,0,0,[],""],["carrizo_salta-n3935-01",3,"El que nace desgraciado,\nDesde chiquito padece,\nLa suerte no es para todos,\nSino pa'l que la merece.",3,1,0,55,"",0,4,"ee",64,0,-1,0,668,668,"3935","",0,"","","",1,0,0,[],""],["carrizo_salta-n3936-01",3,"El que se casa se j o...\nDe su libertad carece,\nY aún cuando su mal le pese,\nBajo el yugo permanece.",3,1,0,55,"",3,4,"ee",64,0,-1,0,669,669,"3936","",0,"","","",1,0,0,[],""],["carrizo_salta-n3937-01",3,"El que se quiera casar,\nAbra los ojos primero,\nEl que se casa se j o...\nPorque es un mal sin remedio.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,669,669,"3937","",0,"","","",1,0,0,[],""],["carrizo_salta-n3938-01",3,"El rico le dice al pobre:\n—Calavera y chupador,\nEl rico toma en la mesa,\nEl pobre en el mostrador.",3,1,0,55,"",0,4,"o",72,0,-1,0,669,669,"3938","",0,"","","",1,0,0,[],""],["carrizo_salta-n3939-01",3,"El vivir enamorado,\nY no ser correspondido,\nEs vivir siempre aburrido,\nY de todos despreciado.",3,1,0,55,"",11,4,"ao",14,0,-1,0,669,669,"3939","",0,"","","",1,0,0,[],""],["carrizo_salta-n3940-01",3,"En cuestiones del amor,\nEl que hace parada pierde,\nViento que zumba está fuera,\nPero que ladra no muerde.",3,1,0,55,"",0,4,"ee",154,0,-1,0,669,669,"3940","",0,"","","",1,0,0,[],""],["carrizo_salta-n3941-01",3,"En el alma hay dos vacíos,\nQue no se pueden llenar:\nEl de la fé que se pierde,\nY el del amor que se va.",3,1,0,55,"",0,4,"a",-1,0,-1,0,669,669,"3941","",0,"huambachano","","",2,0,0,[],""],["carrizo_salta-n3942-01",3,"En este mundo mezquino,\nNada tiene duración,\nSi es desparejo el camino,\nCualquiera da un tropezón.",3,1,0,55,"",1,4,"o",31,0,-1,0,669,669,"3942","",0,"","","",1,0,0,[],""],["carrizo_salta-n3943-01",3,"En la mar está tronando,\nY en la Cordillera llueve,\nSin la voluntad de Dios,\nNinguna paja se mueve.",3,1,0,55,"",0,4,"ee",474,0,-1,0,669,669,"3943","",0,"","","",2,0,0,[],""],["carrizo_salta-n3944-01",3,"En las toscas, es divino,\nMirar las olas quebrarse,\n¡Cómo al fin viene a estrellarse,\nEl hombre con su destino!",3,1,0,55,"",11,4,"io",199,0,-1,0,669,669,"3944","",0,"","","",1,0,0,[],""],["carrizo_salta-n3945-01",3,"En vano te quejas ya,\nMejor será persuadirse,\nLo que remedio no tiene,\nEs locura confundirse.",3,1,0,55,"",0,4,"ie",475,0,-1,0,669,669,"3945","",0,"","","",1,0,0,[],""],["carrizo_salta-n3946-01",3,"Es de porvenir incierto,\nCriar palomas de Castilla,\nEl día menos pensado,\nViene el halcón y las pilla.",3,1,0,55,"",0,4,"ia",162,0,-1,0,669,669,"3946","",0,"","","",1,0,0,[],""],["carrizo_salta-n3947-01",3,"Es el árbol del amor,\nEl que produce congojas,\nEl tiempo seca las flores,\nY el viento lleva las hojas.",3,1,0,55,"",0,4,"oa",364,0,-1,0,669,669,"3947","",0,"","","",1,0,0,[],""],["carrizo_salta-n3948-01",3,"Es nuestra naturaleza,\nDe tan dura condición,\nHay que sufrir la desgracia,\nPara sentir el dolor.",3,1,0,55,"",0,4,"o",-1,0,-1,0,669,669,"3948","",0,"","","",1,0,0,[],""],["carrizo_salta-n3949-01",3,"Hasta dentro de la iglesia,\nTenemos un desengaño,\nPor interés del dinero,\nHacen a un moro, cristiano.",3,1,0,55,"",0,4,"ao",-1,0,-1,0,669,669,"3949","",0,"","","",1,0,0,[],""],["carrizo_salta-n3950-01",3,"Hasta la luna padece,\nCon tener la noche clara,\nAsí padece un amante,\nCuando la suerte se acaba.",3,1,0,55,"",0,4,"aa",-1,0,-1,0,670,670,"3950","",0,"","","",1,0,0,[],""],["carrizo_salta-n3951-01",3,"Hay días que tengo pena,\nNi llorando me consuelo;\nNada se me da del mundo,\nCuando del cielo me acuerdo.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,670,670,"3951","",0,"","","",1,0,0,[],""],["carrizo_salta-n3951-a-01",3,"Nada se me da del mundo,\nCuando del cielo me acuerdo,\nHay días que tengo penas,\nY con llorar me consuelo.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,670,670,"3951-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n3952-01",3,"Hay lenguas como el cuchillo,\nQue lastiman y no cortan,\nQue hablan de vidas ajenas,\nPregunten, ¿qué les importa?",3,1,0,55,"",0,4,"oa",-1,0,-1,0,670,670,"3952","",0,"","","",1,0,0,[],""],["carrizo_salta-n3952-02",3,"Hay lenguas como navajas,\nFilosas pero no cortan,\nSe ponen a averiguar\nCosas que no les importa.",3,1,0,55,"",0,4,"oa",-1,0,-1,0,670,670,"3952","",0,"","","",1,0,0,[],""],["carrizo_salta-n3953-01",3,"Hay unos palos dichosos,\nY otros hay que no lo son;\nUnos sirven para santos,\nOtros para hacer carbón.",3,1,0,55,"",0,4,"o",31,0,-1,0,670,670,"3953","",0,"","","",1,0,0,[],""],["carrizo_salta-n3954-01",3,"He visto en raso llover,\nDe claro ponerse oscuro;\nVide acabarse un querer,\nCuando estaba más seguro.",3,1,0,55,"",1,4,"uo",248,0,-1,0,670,670,"3954","",0,"","","",1,0,0,[],""],["carrizo_salta-n3955-01",3,"Hombre con hombre se entienden,\nMujer con hombre también,\nPero mujer con mujer,\nNo se pueden entender.",3,1,0,55,"",0,4,"e",20,0,-1,0,670,670,"3955","",0,"","","",1,0,0,[],""],["carrizo_salta-n3956-01",3,"¡Inocente corderito!\nTu dicha es dicha completa,\n¡Inocente y chiquitito,\nComo flor en la maceta!",3,1,0,55,"",1,4,"ea",200,0,-1,0,670,670,"3956","",0,"","","",1,0,0,[],""],["carrizo_salta-n3957-01",3,"La casa se quema,\nY sale el humo,\n¿Ande han visto quemarse\nAl disimulo?",3,1,0,55,"",6,4,"uo",-1,0,-1,0,670,670,"3957","",0,"","","",1,0,0,[],""],["carrizo_salta-n3958-01",3,"La pena es un lazo fuerte,\nQue sirve en dos ocasiones;\nPara estrechar los afectos,\nPara unir dos corazones.",3,1,0,55,"",0,4,"oe",34,0,-1,0,670,670,"3958","",0,"","","",1,0,0,[],""],["carrizo_salta-n3959-01",3,"¡La razón vence al poder!\n¡En otro tiempo sería!\nAhora vence la fuerza,\nLas razones ¿qué se harían?",3,1,0,55,"",0,4,"ia",-1,0,-1,0,670,670,"3959","",0,"","","",1,0,0,[],""],["carrizo_salta-n3960-01",3,"Las estrellitas del cielo,\nNadie las puede contar,\nTan sólo Aquel, que las puso,\nCada una en su lugar.",3,1,0,55,"",0,4,"a",21,0,-1,0,671,671,"3960","",0,"","","",25,0,0,[],""],["carrizo_salta-n3961-01",3,"Las nubes están cargadas,\nViene el viento y las combate,\nLos unos calientan l'agua,\nY los otros toman mate.",3,1,0,55,"",0,4,"ae",384,0,-1,0,671,671,"3961","",0,"","","",2,0,0,[],""],["carrizo_salta-n3962-01",3,"Las rosas y las mujeres,\nSon dos cosas parecidas,\nEn la mujer el engaño,\nY en la rosa las espinas.",3,1,0,55,"",0,4,"ia",-1,0,-1,0,671,671,"3962","",0,"","","",1,0,0,[],""],["carrizo_salta-n3963-01",3,"La suerte es un patrimonio,\nQue Dios a todos ha dado,\nUnos desechan la suerte,\nY otros son aprovechados.",3,1,0,55,"",0,4,"ao",-1,0,-1,0,671,671,"3963","",0,"","","",1,0,0,[],""],["carrizo_salta-n3965-01",3,"¡Malhaya la plata en riales!\n¡Cómo no sería de a peso!\nEl pobre no goza nada,\nSi goza, goza desprecios.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,671,671,"3965","",0,"","","",1,0,0,[],""],["carrizo_salta-n3966-01",3,"¡Mentira es aquel que dice,\nQue el que miente no hace hazaña!\nMintiendo con buen discurso,\nConserva una amistad clara.",3,1,0,55,"",0,4,"aa",-1,0,-1,0,671,671,"3966","",0,"","","",1,0,0,[],""],["carrizo_salta-n3967-01",3,"Molino viejo,\nNo muele trigo.\nMujer casada,\nNo tiene amigo.",3,1,0,55,"",6,4,"io",106,0,-1,0,671,671,"3967","",0,"","","",1,0,0,[],""],["carrizo_salta-n3968-01",3,"Nada importan las riquezas,\nY nada importa el saber;\nLa muerte todo lo acaba,\nSe acaba el amor también.",3,1,0,55,"",0,4,"e",-1,0,-1,0,671,671,"3968","",0,"","","",1,0,0,[],""],["carrizo_salta-n3969-01",3,"Ni dormido tendrás vos,\nTranquilo tu pensamiento.\nEl que vive mal con Dios,\nTiene que vivir despierto.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,671,671,"3969","",0,"","","",1,0,0,[],""],["carrizo_salta-n3971-01",3,"No hay desgracia en la vida,\nComo nacer sin fortuna;\nTiene su sangre manchada,\nY oscurecida su cuna.",3,1,0,55,"",0,4,"ua",56,0,-1,0,671,671,"3971","",0,"","","",2,0,0,[],""],["carrizo_salta-n3972-01",3,"No sólo el que debe muertes,\nAnda la soga arrastrando.\nTambién el que no las debe,\nPor horas anda aguardando.",3,1,0,55,"",0,4,"ao",33,0,-1,0,672,672,"3972","",0,"","","",2,0,0,[],""],["carrizo_salta-n3973-01",3,"¡No te subas tan arriba!\n¡No te subas a los montes!\nCuando más alto te subas,\nMás fuerte ha de ser el golpe.",3,1,0,55,"",0,4,"oe",-1,0,-1,0,672,672,"3973","",0,"","","",1,0,0,[],""],["carrizo_salta-n3974-01",3,"Para el rico, para el pobre,\nHa nacío cualquier mujer,\nEl pobre con su porfía,\nEl rico con su poder.",3,1,0,55,"",0,4,"e",20,0,-1,0,672,672,"3974","",0,"","","",1,0,0,[],""],["carrizo_salta-n3975-01",3,"Para pesar los amigos,\nNo hay en el mundo balanza.\nSi Vd. tiene algún amigo,\nNo le dé mucha confianza.",3,1,0,55,"",0,4,"aa",163,0,-1,0,672,672,"3975","",0,"","","",1,0,0,[],""],["carrizo_salta-n3976-01",3,"Para ser buen amador,\nSe ha de amar hasta la muerte.\nPero el que ama de esta suerte,\nMiente como adulador.",3,1,0,55,"",11,4,"o",72,0,-1,0,672,672,"3976","",0,"","","",1,0,0,[],""],["carrizo_salta-n3977-01",3,"Para un jazmín, una rosa,\nPara una rosa, un jazmín,\n¡Toda mujer es celosa!\n¡Que me lo digan a mí!",3,1,0,55,"",0,4,"i",-1,0,-1,0,672,672,"3977","",0,"","","",1,0,0,[],""],["carrizo_salta-n3978-01",3,"Para volar nace el ave,\nPara perfumar la flor,\nPara morir nace el hombre,\nPara amar el corazón.",3,1,0,55,"",0,4,"o",-1,0,-1,0,672,672,"3978","",0,"palau_cantares, suspiros_amor","","",3,0,0,[],""],["carrizo_salta-n3979-01",3,"Paso a paso iremos lejos,\nSi Dios nos presta la vida,\nCon el tiempo se recogen\nTodas las cosas perdidas.",3,1,0,55,"",0,4,"ia",-1,0,-1,0,672,672,"3979","",0,"","","",1,0,0,[],""],["carrizo_salta-n3980-01",3,"Polvareda de un sereno,\nGranizo de una calor,\n¿Ande han visto, compañeros,\nDe una vileza, valor?",3,1,0,55,"",0,4,"o",72,0,-1,0,672,672,"3980","",0,"","","",1,0,0,[],""],["carrizo_salta-n3981-01",3,"Por encima de las aguas,\nVí una esperanza flotando,\nLa corriente la llevaba,\nAl pozo del desengaño.",3,1,0,55,"",0,4,"ao",-1,0,-1,0,672,672,"3981","",0,"","","",3,0,0,[],""],["carrizo_salta-n3981-a-01",3,"Por encima de las aguas,\nVí una esperanza flotando,\nY ví que la echaba a fondo,\nEl peso de un desengaño.",3,1,0,55,"",0,4,"ao",-1,0,-1,0,672,672,"3981-a","",0,"palau_cantares","","",3,0,0,[],""],["carrizo_salta-n3982-01",3,"Pregunto al más entendido,\nAl más sabio de talento:\nSi el querido con el tiempo,\nNo es el más aborrecido.",3,1,0,55,"",5,4,"io",101,0,-1,0,672,672,"3982","",0,"","","",1,0,0,[],""],["carrizo_salta-n3983-01",3,"Primero, antes que la lengua,\nDientes y muelas están,\nPor que lo que has de decir,\nPrimero lo has de mascar.",3,1,0,55,"",0,4,"a",-1,0,-1,0,672,672,"3983","",0,"","","",1,0,0,[],""],["carrizo_salta-n3984-01",3,"Prisionero soy de Amor,\nY lo seré mientras viva,\nQue el prisionero de Amor,\nPrimero muere que olvida.",3,1,0,55,"",0,4,"ia",-1,0,-1,0,672,672,"3984","",0,"rm_t2","","",2,0,0,[],""],["carrizo_salta-n3985-01",3,"Prometer tanto es simpleza,\nCuando el amor es fingido;\nMañana se olvidará,\nLo que ayer ha prometido.",3,1,0,55,"",0,4,"io",101,0,-1,0,672,672,"3985","",0,"","","",1,0,0,[],""],["carrizo_salta-n3986-01",3,"¿Qué le importa al envidioso,\nQue cuida lo que no es de él?\n¿Por qué vuelan las abejas,\nPara que otros coman miel?",3,1,0,55,"",0,4,"e",32,0,-1,0,672,672,"3986","",0,"","","",1,0,0,[],""],["carrizo_salta-n3987-01",3,"Quién por su patria querida,\nEn una marcial función,\nArriesga y pierde la vida,\nEstá muy puesto en razón.",3,1,0,55,"",1,4,"o",31,0,-1,0,673,673,"3987","",0,"","","",1,0,0,[],""],["carrizo_salta-n3988-01",3,"Señorita Serafina,\nPara usted son estos cobres;\nComo campanas de palo,\nSon las razones del pobre.",3,1,0,55,"",0,4,"oe",-1,0,-1,0,673,673,"3988","",0,"","","",1,0,0,[],""],["carrizo_salta-n3989-01",3,"Si el tirano es muy tirano,\nY hace su ruin tiranía,\nSe ha de acordar en un tiempo,\nEn el plato en que comía.",3,1,0,55,"",0,4,"ia",0,0,-1,0,673,673,"3989","",0,"","","",1,0,0,[],""],["carrizo_salta-n3990-01",3,"Si mis finezas no bastan,\nSi es que ellas no han de poder\nRendir una voluntad,\n¡Qué gran locura es querer!",3,1,0,55,"",0,4,"e",20,0,-1,0,673,673,"3990","",0,"","","",1,0,0,[],""],["carrizo_salta-n3991-01",3,"Si puedes ten caridad,\nGuardad tu salud con freno,\nToma con serenidad,\nTodo por su lado bueno.",3,1,0,55,"",1,4,"eo",76,0,-1,0,673,673,"3991","",0,"","","",1,0,0,[],""],["carrizo_salta-n3992-01",3,"Si te han visto buenas prendas,\nTodos te han de dar la mano,\nSi se te acaban las prendas,\nNo hay amigo, no hay hermano.",3,1,0,55,"",1,4,"ao",81,0,-1,0,673,673,"3992","",0,"","","",1,0,0,[],""],["carrizo_salta-n3993-01",3,"Si Vd. llega a alguna casa,\nPor conocencia que tenga,\nLuego dirán los vecinos:\n—Ese de balde no llega.",3,1,0,55,"",0,4,"ea",-1,0,-1,0,673,673,"3993","",0,"","","",1,0,0,[],""],["carrizo_salta-n3994-01",3,"Si Vd. se llega a una casa,\nPor que le habrán convidado,\nLuego dirán los vecinos:\n—Ya viene como casado.",3,1,0,55,"",0,4,"ao",14,0,-1,0,673,673,"3994","",0,"","","",1,0,0,[],""],["carrizo_salta-n3995-01",3,"Si Vd. tiene algún amigo,\nQuiéralo con mucho aprecio,\nPero no le comunique,\nLos secretos de su pecho.",3,1,0,55,"",0,4,"eo",-1,0,-1,0,673,673,"3995","",0,"","","",1,0,0,[],""],["carrizo_salta-n3996-01",3,"Si yo me caso con rica,\nMe dirán interesado,\nY si me caso con pobre,\nSeré un triste enamorado.",3,1,0,55,"",0,4,"ao",14,0,-1,0,673,673,"3996","",0,"","","",1,0,0,[],""],["carrizo_salta-n3997-01",3,"Tengo seguro el morir,\nSin saber cómo ni cuando,\nSi hi de morir de repente,\nO m' hi morir esperando.",3,1,0,55,"",0,4,"ao",33,0,-1,0,673,673,"3997","",0,"","","",1,0,0,[],""],["carrizo_salta-n3998-01",3,"Tiempo y tierra en derredor,\nAmor que espera se va,\nEl tiempo vence al amor,\nPorque así mandao está.",3,1,0,55,"",1,4,"a",9,0,-1,0,673,673,"3998","",0,"","","",1,0,0,[],""],["carrizo_salta-n3999-01",3,"Todos los que tengan penas,\nNo se igualarán conmigo,\nPor que yo vivo tranquilo,\nCon mi mayor enemigo.",3,1,0,55,"",0,4,"io",-1,0,-1,0,673,673,"3999","",0,"","","",1,0,0,[],""],["carrizo_salta-n4000-01",3,"Todo puede suceder,\nConforme puede no puede,\nPor que en varias ocasiones,\nTruena, se limpia y no llueve.",3,1,0,55,"",0,4,"ee",-1,0,-1,0,673,673,"4000","",0,"","","",1,0,0,[],""],["carrizo_salta-n4001-01",3,"Todos vamos corriendo\nNuestro destino,\nComo corren las aguas\nPor el camino.",3,1,0,55,"",6,4,"io",199,0,-1,0,674,674,"4001","",0,"","","",1,0,0,[],""],["carrizo_salta-n4002-01",3,"Trabajo había sio regar,\nCuando el terreno es ladera,\nY fiero había sio querer,\nCuando la prenda es ajena.",3,1,0,55,"",0,4,"ea",-1,0,-1,0,674,674,"4002","",0,"","","",1,0,0,[],""],["carrizo_salta-n4003-01",3,"Una casa sin mujer,\nEs gente sin capitán,\nSin mujeres, el placer,\nEs como mesa sin pan.",3,1,0,55,"",1,4,"a",147,0,-1,0,674,674,"4003","",0,"","","",1,0,0,[],""],["carrizo_salta-n4004-01",3,"Un padre que niega al hijo,\nPor una deuda de herencia,\n¡Jamás descansará su alma,\nSin descargar su conciencia!",3,1,0,55,"",0,4,"ea",46,0,-1,0,674,674,"4004","",0,"","","",1,0,0,[],""],["carrizo_salta-n4005-01",3,"Un rosal cría una rosa,\nUna maceta un clavel,\nUna madre cría una hija,\nY no sabe para quién.",3,1,0,55,"",0,4,"e",-1,0,-1,0,674,674,"4005","",0,"","","",8,0,0,[],""],["carrizo_salta-n4006-01",3,"Vienen los meses, los años,\nCon sus mentidas holganzas,\nComprando los desengaños,\nPagando con esperanzas.",3,1,0,55,"",1,4,"aa",110,0,-1,0,674,674,"4006","",0,"","","",1,0,0,[],""],["carrizo_salta-n4007-01",3,"Yo juré no querer nunca,\nA mujer de corta edad,\nPor que carece de juicio,\nY le falta voluntad.",3,1,0,55,"",0,4,"a",16,0,-1,0,674,674,"4007","",0,"","","",1,0,0,[],""],["carrizo_salta-n4008-01",3,"Yo no le temo a la muerte,\nNi al rayo, ni a la centella,\nPorque me sabrá librar\nSanta Bárbara Doncella.",3,1,0,55,"",0,4,"ea",6,0,-1,0,674,674,"4008","",0,"","","",12,0,0,[],""],["carrizo_salta-n4009-01",3,"Yo no sé por qué este mundo,\nDe cualquier cosa se espanta,\nSabiendo que la pobreza,\nArruina la mejor plata.",3,1,0,55,"",0,4,"aa",-1,0,-1,0,674,674,"4009","",0,"","","",2,0,0,[],""],["carrizo_salta-n4009-a-01",3,"Yo no sé por qué este mundo,\nDe cualquier cosa se espanta,\nYa sabís que la desgracia,\nArruina la mejor planta.",3,1,0,55,"",0,4,"aa",-1,0,-1,0,674,674,"4009-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n4010-01",3,"Yo no sé por qué los hombres,\nCuando llegan al poder,\nLes gusta encender el fuego,\nRetirarse, y verlo arder.",3,1,0,55,"",0,4,"e",20,0,-1,0,674,674,"4010","",0,"","","",1,0,0,[],""],["carrizo_salta-n4011-01",3,"Yo nunca espero justicia,\nPorque no tengo ni un cobre,\nComo campana de palo,\nSon las razones de un pobre.",3,1,0,55,"",0,4,"oe",410,0,-1,0,674,674,"4011","",0,"","","",1,0,0,[],""],["carrizo_salta-n4012-01",3,"Yo soy como el cuervo negro,\nQue se anda de cumbre en cumbre,\nMocito que tiene dueña,\nNo hay quién no le saque herrumbre.",3,1,0,55,"",0,4,"ue",181,0,-1,0,674,674,"4012","",0,"","","",2,0,0,[],""],["carrizo_salta-n4013-01",3,"Yo también diré lo mismo,\nComo dice un artesano,\nPrimero se ha de perder,\nPara servir de baquiano.",3,1,0,55,"",0,4,"ao",81,0,-1,0,674,674,"4013","",0,"","","",3,0,0,[],""],["carrizo_salta-n4014-01",3,"Yo también hi de decir,\nComo dijo el padre Peña,\nCuando ven un árbol cáido,\nTodos quieren sacar leña.",3,1,0,55,"",0,4,"ea",291,0,-1,0,674,674,"4014","",0,"","","",1,0,0,[],""],["carrizo_salta-n4015-01",3,"¡Adelante, adelante!\nBravo argentino,\nNo le tema a las balas,\nSino al destino.",3,1,0,56,"",6,4,"io",199,0,-1,0,676,676,"4015","",0,"","","",1,0,0,[],""],["carrizo_salta-n4016-01",3,"¡A la carga, a la carga!\nDijo Centeno,\nHagamos un tirito,\nNos retiremos.",3,1,0,56,"",6,4,"eo",-1,0,-1,0,676,676,"4016","",0,"","","",4,0,0,[],""],["carrizo_salta-n4017-01",3,"¡A la carga, a la carga!\nDijo Lizondo,\nVamonos los Varelas,\nDe dos en fondo.",3,1,0,56,"",6,4,"oo",450,0,-1,0,676,676,"4017","",0,"","","",4,0,0,[],""],["carrizo_salta-n4018-01",3,"¡A la carga, a la carga!\nDijo Varela,\nDispararon los cotos,\nLa polvareda.",3,1,0,56,"",6,4,"ea",-1,0,-1,0,676,676,"4018","",0,"","","",4,0,0,[],""],["carrizo_salta-n4018-a-01",3,"¡A la carga, a la carga!\nDijo Varela,\nYa se van los jujeños,\nLa polvadera.",3,1,0,56,"",6,4,"ea",-1,0,-1,0,676,676,"4018-a","",0,"","","",4,0,0,[],""],["carrizo_salta-n4019-01",3,"Al dentrar al río Arias,\nDijo Varela,\nTodos los de a caballo,\nEchen pié a tierra.",3,1,0,56,"",6,4,"ea",-1,0,-1,0,676,676,"4019","",0,"","","",1,0,0,[],""],["carrizo_salta-n4020-01",3,"Allá viene San Martín,\nCon su espada y su cuchillo,\nLes dice a los enemigos,\n¡Vengan los tigres conmigo!",3,1,0,56,"",0,4,"io",-1,0,-1,0,676,676,"4020","",0,"","","",2,0,0,[],""],["carrizo_salta-n4021-01",3,"Allá viene San Martín,\nCon toditos sus soldados,\nSabliando va al enemigo,\nCon su brazo levantado.",3,1,0,56,"",0,4,"ao",-1,0,-1,0,676,676,"4021","",0,"","","",2,0,0,[],""],["carrizo_salta-n4022-01",3,"Antinoche en la calle,\nLos radicales,\nDaban sus alaridos,\nComo animales.",3,1,0,56,"",6,4,"ae",26,0,-1,0,676,676,"4022","",0,"","","",1,0,0,[],""],["carrizo_salta-n4022-02",3,"Como animales, sí,\n¿Qué se pensaban,\nQue con palabras falsas\nAcobardaban?",3,1,0,56,"",6,4,"aa",-1,0,-1,0,676,676,"4022","",0,"","","",1,0,0,[],""],["carrizo_salta-n4023-01",3,"¿A quién querís más?\n¿A quién querís más?\n¿A ciego Ibazeta\nO al sordo Solá?",3,1,0,56,"",0,4,"a",-1,0,-1,0,676,676,"4023","",0,"","","",1,0,0,[],""],["carrizo_salta-n4025-01",3,"¡Brazo a la lanza!\n¡Ojo al cañón!\nQue si hay tardanza,\nNo hay salvación.",3,1,0,56,"",6,4,"o",31,0,-1,0,677,677,"4025","",0,"","","",1,0,0,[],""],["carrizo_salta-n4026-01",3,"¡Cabalero de fulano!\nValeroso americano,\nEspada de la justicia,\nY puñal contra el tirano.",3,1,0,56,"",0,4,"ao",81,0,-1,0,677,677,"4026","",0,"","","",2,0,0,[],""],["carrizo_salta-n4027-01",3,"Campos al frente,\nNo hay que temer,\nBravos salteños\nHan de vencer.",3,1,0,56,"",6,4,"e",20,0,-1,0,677,677,"4027","",0,"","","",1,0,0,[],""],["carrizo_salta-n4028-01",3,"De bajo un cerco\nSale un ratón.\n¡Viva la patria!\n¡Muera Cantón!",3,1,0,56,"",6,4,"o",31,0,-1,0,677,677,"4028","",0,"","","",1,0,0,[],""],["carrizo_salta-n4029-01",3,"De Chile salió Varela,\nY vino a su patria hermosa,\nAquí ha de morir peliando\nPor Vicente Peñaloza.",3,1,0,56,"",0,4,"oa",195,0,-1,0,677,677,"4029","",0,"","","",1,0,0,[],""],["carrizo_salta-n4030-01",3,"Del río Arias más allá,\nDe Arenales más acá,\nEntre sombras señoriales\nMe mandaste asesinar.",3,1,0,56,"",0,4,"a",-1,0,-1,0,677,677,"4030","",0,"","","",1,0,0,[],""],["carrizo_salta-n4031-01",3,"Desde Guachipas\nAl Cebilar,\nCausa el gobierno,\nNo hay gusto cabal.",3,1,0,56,"",6,4,"a",-1,0,-1,0,677,677,"4031","",0,"","","",1,0,0,[],""],["carrizo_salta-n4032-01",3,"Dice don Franciso Acuña\nQue está con mucho temor,\nCuando encuentre a la patrulla,\nDa parte al Gobernador.",3,1,0,56,"",0,4,"o",72,0,-1,0,677,677,"4032","",0,"","","",1,0,0,[],""],["carrizo_salta-n4033-01",3,"Dicen que los chilenos\nSon muy valientes,\nCuando están con el corvo\nY el aguardiente.",3,1,0,56,"",6,4,"ee",-1,0,-1,0,677,677,"4033","",0,"","","",1,0,0,[],""],["carrizo_salta-n4034-01",3,"Digan todos a una voz\nCon la más dulce alegría:\n¡Viva nuestro coronel\nJosé Antonio C h a v a r r í a!",3,1,0,56,"",5,4,"a",-1,0,-1,0,677,677,"4034","",0,"","","",1,0,0,[],""],["carrizo_salta-n4035-01",3,"Doña Victoria Romero,\nSi usted quiere que le cuente,\nSe vino de Tucumán\nCon una herida en la frente.",3,1,0,56,"",0,4,"ee",15,0,-1,0,677,677,"4035","",0,"","","",1,0,0,[],""],["carrizo_salta-n4036-01",3,"¡Echen pie a tierra, che!\nDijo Elizondo.\n¡Por derecha e izquierda,\nDe cuatro en fondo!",3,1,0,56,"",6,4,"oo",450,0,-1,0,677,677,"4036","",0,"","","",1,0,0,[],""],["carrizo_salta-n4038-01",3,"El mundo se va a perder,\nLa culpa tiene el dinero.\n¡Arriba los paraguay os!\n¡Abajo los brasileros!",3,1,0,56,"",0,4,"eo",-1,0,-1,0,677,677,"4038","",0,"","","",1,0,0,[],""],["carrizo_salta-n4040-01",3,"Este baile es de Camacho,\nDe Camacho el General;\nDel ilustre Presidente\nDel Partido Liberal.",3,1,0,56,"",0,4,"a",1,0,-1,0,678,678,"4040","",0,"","","",1,0,0,[],""],["carrizo_salta-n4041-01",3,"Isidoro Vence,\n¡Mulato insolente!\nSólo en Cochabamba\nLlegó a presidente.",3,1,0,56,"",0,4,"ee",15,0,-1,0,678,678,"4041","",0,"","","",1,0,0,[],""],["carrizo_salta-n4042-01",3,"La bandera de sangre,\n¡Triste divisa!\nSe deshizo en \"Caseros\".\n¡Que viva Urquiza!",3,1,0,56,"",6,4,"ia",420,0,-1,0,678,678,"4042","",0,"","","",1,0,0,[],""],["carrizo_salta-n4043-01",3,"La espada del gaucho Rozas\nLa han traído del Japón,\nPara defender con ella\nLa Santa Federación.",3,1,0,56,"",0,4,"o",31,0,-1,0,678,678,"4043","",0,"","","",1,0,0,[],""],["carrizo_salta-n4044-01",3,"Los argentinos\nJuegan aición,\nLos brasileros\nJuegan traición.",3,1,0,56,"",6,4,"o",31,0,-1,0,678,678,"4044","",0,"","","",1,0,0,[],""],["carrizo_salta-n4045-01",3,"Los ranchos de paja,\n¡Fuera el bulevar!\nManda el Intendente\nZenón Santillán.",3,1,0,56,"",0,4,"a",-1,0,-1,0,678,678,"4045","",0,"","","",1,0,0,[],""],["carrizo_salta-n4046-01",3,"¡Muera don Felipe López,\nY el señor don Peque Frías!\nPorque supieron vender\nAl capitán Angel Díaz.",3,1,0,56,"",0,4,"ia",476,0,-1,0,678,678,"4046","",0,"","","",1,0,0,[],""],["carrizo_salta-n4047-01",3,"No me importan los desaires\nCon que me trata la suerte,\nSoy nacido en Humahuaca,\nArgentino hasta la muerte.",3,1,0,56,"",0,4,"ee",134,0,-1,0,678,678,"4047","",0,"","","",1,0,0,[],""],["carrizo_salta-n4048-01",3,"No soy \"provincial\",\nNi soy \"radical\",\nQue ganen o pierdan\nPal pobre es igual.",3,1,0,56,"",0,4,"a",1,0,-1,0,678,678,"4048","",0,"","","",1,0,0,[],""],["carrizo_salta-n4049-01",3,"No te vaya a suceder\nLo que a Roca Presidente,\nQue por andar compadriando\nLe hicieron sonar la frente.",3,1,0,56,"",0,4,"ee",15,0,-1,0,678,678,"4049","",0,"","","",4,0,0,[],""],["carrizo_salta-n4050-01",3,"Rota la levita,\nRoto el pantalón,\nRota la casaca\nDe Leguizamón.",3,1,0,56,"",0,4,"o",31,0,-1,0,679,679,"4050","",0,"","","",1,0,0,[],""],["carrizo_salta-n4052-01",3,"¡Señor don Leguizamón!\nNo tenga miedo a las balas,\nRipitipi y Benedito\nLe han de guardar las espaldas.",3,1,0,56,"",0,4,"aa",-1,0,-1,0,679,679,"4052","",0,"","","",1,0,0,[],""],["carrizo_salta-n4053-01",3,"Si Dios me presta la vida,\nY el Arcángel San Gabriel,\nVoy a buscar a Lavalle\nPara juntarme con él.",3,1,0,56,"",0,4,"e",32,0,-1,0,679,679,"4053","",0,"","","",4,0,0,[],""],["carrizo_salta-n4054-01",3,"Terminaré dando un ¡viva!\nVictoriando al que ha venido,\nDando un viva al candidato\nPor el triunfo que ha obtenido.",3,1,0,56,"",0,4,"io",101,0,-1,0,679,679,"4054","",0,"","","",1,0,0,[],""],["carrizo_salta-n4055-01",3,"¡Toma, niña, esta naranja!\nEn cambio de tu limón,\nEn el letrerito dice:\n¡Viva la Federación!",3,1,0,56,"",0,4,"o",31,0,-1,0,679,679,"4055","",0,"","","",4,0,0,[],""],["carrizo_salta-n4163-01",3,"¡Flor de chañar!\n¡Flor de chañar!\n¿Por qué me tiene\nHaciendo penar?",3,1,0,57,"",6,4,"a",21,0,-1,0,685,685,"4163","",0,"","","",3,0,0,[],""],["carrizo_salta-n4255-01",3,"En el Cerro Overo,\n¡Ay, vidalita!\nTengo un alfombrao,\nPara que en él bailen,\n¡Ay, vidalita!\nLos enamoraos.",3,1,0,58,"",9,6,"ao",-1,0,-1,0,690,690,"4255","",0,"","","",1,0,0,[],""],["carrizo_salta-n4256-01",3,"Palomita blanca,\n¡Vidalita!\nVuélvete a tu nido,\nY hallarás la sangre,\n¡Vidalita!\nDe mi pecho herido.",3,1,0,58,"",9,6,"io",101,0,-1,0,690,690,"4256","",0,"","","",12,0,0,[],""],["carrizo_salta-n4257-01",3,"Yo daría mi vida,\n¡Vidalita!\nYo daría mi calma,\nYo daría mi encanto,\n¡Vidalita!\nSi tuviera tu alma.",3,1,0,58,"",9,6,"aa",125,0,-1,0,690,690,"4257","",0,"","","",1,0,0,[],""],["carrizo_salta-n4258-01",3,"Yo tengo mi caña,\n¡Ay, vidalita!\nNo la hi de moler,\nPorque tu trapiche,\n¡Ay, vidalita!\nL'echará a perder.",3,1,0,58,"",9,6,"e",20,0,-1,0,690,690,"4258","",0,"","","",1,0,0,[],""],["carrizo_salta-n4259-01",3,"Alto en altero,\nGran caballero,\nCapa rosada,\nSombrero negro.",3,1,0,59,"",6,4,"eo",-1,0,-1,0,692,692,"4259","",0,"","","",2,0,0,[],""],["carrizo_salta-n4260-01",3,"Alto en altero,\nGran caballero,\nMuchos aposentos,\nY sin ningún aujero.",3,1,0,59,"",3,4,"eo",-1,0,-1,0,692,692,"4260","",0,"","","",2,0,0,[],""],["carrizo_salta-n4260-02",3,"Largo, larguero,\nMartín Caballero,\nCalzas coloradas,\nY penacho negro.",3,1,0,59,"",6,4,"eo",-1,0,-1,0,692,692,"4260","",0,"","","",3,0,0,[],""],["carrizo_salta-n4261-01",3,"Amalás con ugalmente,\nAdiviná cuando y cómo,\nPero evitando prudente,\nDel hastío hasta el asomo.",3,1,0,59,"",1,4,"oo",349,0,-1,0,692,692,"4261","",0,"","","",1,0,0,[],""],["carrizo_salta-p0692-01",3,"Largo, larguero,\nMartín Caballero,\nManta de grana,\nY sombrero negro.",3,1,0,59,"",6,4,"eo",-1,0,-1,0,692,692,"","",0,"","","",3,0,0,[],""],["carrizo_salta-n4263-01",3,"Antes fuí hija,\nAhora soy madre,\nCrío hijo ajeno,\nMarido de mi madre.",3,1,0,59,"",3,4,"ae",-1,0,-1,0,693,693,"4263","",0,"","","",1,0,0,[],""],["carrizo_salta-n4264-01",3,"Antes que el mundo sea mundo,\nYo ya había sabido andar,\nSin tener piés ni cabeza,\n¿Cómo sabría caminar?",3,1,0,59,"",0,4,"a",21,0,-1,0,693,693,"4264","",0,"","","",1,0,0,[],""],["carrizo_salta-n4266-01",3,"Cimiento sobre cimiento,\nY sobre el cimiento un poste;\nSobre el poste está un molino,\nY sobre el molino un monte.",3,1,0,59,"",0,4,"oe",-1,0,-1,0,693,693,"4266","",0,"","","",1,0,0,[],""],["carrizo_salta-n4267-01",3,"¿Cómo cortan sin tijera?\n¿Cómo cosen sin costura?\n¿Cómo entierran a los muertos,\nSin cavar la sepultura?",3,1,0,59,"",0,4,"ua",17,0,-1,0,694,694,"4267","",0,"","","",1,0,0,[],""],["carrizo_salta-n4268-01",3,"¿Cómo puede un ser cristiano,\nSin negar la ley de Dios,\nCasarse con hija y madre,\nSiendo huérfanas las dos?",3,1,0,59,"",0,4,"o",87,0,-1,0,694,694,"4268","",0,"","","",1,0,0,[],""],["carrizo_salta-n4269-01",3,"Con el mayor rendimiento,\nY la mejor cortesía,\nDígame, ¿cómo se bierden,\nTres Domingos en un día?",3,1,0,59,"",0,4,"ia",0,0,-1,0,694,694,"4269","",0,"","","",2,0,0,[],""],["carrizo_salta-n4270-01",3,"¿Cuál es el bichito aquel,\nQue tiene tetas y vuela?\nJamás lo adivinará,\nNi tu mama, ni tu agüela.",3,1,0,59,"",0,4,"ea",167,0,-1,0,694,694,"4270","",0,"","","",1,0,0,[],""],["carrizo_salta-n4271-01",3,"Cuando me siento me estiro,\nCuando me paro me encojo,\nEntro al fuego y no me quemo,\nEntro al agua y no me mojo.",3,1,0,59,"",0,4,"oo",400,0,-1,0,694,694,"4271","",0,"","","",1,0,0,[],""],["carrizo_salta-n4272-01",3,"Cuando mi padre nació,\nYa cuanta yo había nacido,\nPara bautizar mi abuela,\nYo me paré de padrino.",3,1,0,59,"",0,4,"io",-1,0,-1,0,694,694,"4272","",0,"","","",1,0,0,[],""],["carrizo_salta-n4273-01",3,"Debajo una tolafía,\nCinco vidas me acompañan,\nLas cinco lloran conmigo,\nSólo una me convertía.",3,1,0,59,"",5,4,"ia",0,0,-1,0,694,694,"4273","",0,"","","",1,0,0,[],""],["carrizo_salta-n4274-01",3,"De las preguntas que l'hice,\nNo me contestó ninguna:\n¿Cuál es el ave que vuela,\nMás alto, sin tener plumas?",3,1,0,59,"",0,4,"ua",-1,0,-1,0,694,694,"4274","",0,"","","",1,0,0,[],""],["carrizo_salta-n4275-01",3,"De mañanita estoy mozo,\nA las doce caducando,\nLuego que llega la tarde,\nDe canas estoy blanquiando.",3,1,0,59,"",0,4,"ao",33,0,-1,0,695,695,"4275","",0,"","","",1,0,0,[],""],["carrizo_salta-n4276-01",3,"De nada sirvo de día,\nDe noche sirvo bastante,\nComo siempre doy trabajo,\nMe cortan a cada instante.",3,1,0,59,"",0,4,"ae",47,0,-1,0,695,695,"4276","",0,"","","",1,0,0,[],""],["carrizo_salta-n4277-01",3,"Dos hombres en un borrico,\nLos dos marchan a la par,\nEl uno hace doce leguas,\nEl otro hace una nomás.",3,1,0,59,"",0,4,"a",-1,0,-1,0,695,695,"4277","",0,"","","",1,0,0,[],""],["carrizo_salta-n4279-01",3,"Ella que llega,\nYo que le tiendo,\nElla que se echa,\nYo que le prendo.",3,1,0,59,"",6,4,"eo",52,0,-1,0,695,695,"4279","",0,"","","",1,0,0,[],""],["carrizo_salta-n4280-01",3,"El tín que le suena,\nEl don que le da;\nA su peludito,\n¿Por cuánto lo da?",3,1,0,59,"",0,4,"a",-1,0,-1,0,695,695,"4280","",0,"","","",1,0,0,[],""],["carrizo_salta-n4281-01",3,"En alto vivo y me muero,\nY moros veo venir,\nTengo corona de rey,\nPero yo no puedo huir.",3,1,0,59,"",0,4,"i",157,0,-1,0,695,695,"4281","",0,"","","",1,0,0,[],""],["carrizo_salta-n4282-01",3,"En el aire se ha formado,\nUna casa sin cimiento,\nNo es hechura de los hombres,\nSino del entendimiento.",3,1,0,59,"",0,4,"eo",94,0,-1,0,695,695,"4282","",0,"","","",2,0,0,[],""],["carrizo_salta-n4283-01",3,"En el aire se ha formado,\nUna casa sin cimiento,\nUn corral sin bramadero,\nY una vaca sin ternero.",3,1,0,59,"",0,4,"eo",38,0,-1,0,695,695,"4283","",0,"","","",2,0,0,[],""],["carrizo_salta-n4284-01",3,"Enferma estoy en la cama,\nEnferma sin tener males,\nMuerta estoy y tengo vida,\nRica, sin tener caudales.",3,1,0,59,"",0,4,"ae",26,0,-1,0,696,696,"4284","",0,"","","",1,0,0,[],""],["carrizo_salta-n4285-01",3,"En verde prado nací,\nCubierto de verdes ramas,\nY hoy me veo cautivo,\nEn los brazos de una dama.",3,1,0,59,"",0,4,"aa",-1,0,-1,0,696,696,"4285","",0,"","","",1,0,0,[],""],["carrizo_salta-n4286-01",3,"Estaba un hombre sentado,\nCon la dama en las rodillas,\nEn la parte delicada,\nLe estaba haciendo tosquillas.",3,1,0,59,"",0,4,"ia",294,0,-1,0,696,696,"4286","",0,"","","",1,0,0,[],""],["carrizo_salta-n4287-01",3,"Fuí al mercado,,\nCompré una doncella,\nVolví a mi casa,\nLloré con ella.",3,1,0,59,"",6,4,"ea",6,0,-1,0,696,696,"4287","",0,"","","",1,0,0,[],""],["carrizo_salta-n4287-a-01",3,"Fuí pa'l mercado,\nCompré una bella,\nVolví a mi casa,\nLloré con ella.",3,1,0,59,"",6,4,"ea",6,0,-1,0,696,696,"4287-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n4288-01",3,"Fuí pal mercado,\nCompré una moza,\nLe alcé el vestido,\nToqué la cosa.",3,1,0,59,"",6,4,"oa",63,0,-1,0,696,696,"4288","",0,"","","",1,0,0,[],""],["carrizo_salta-n4289-01",3,"Gallinas con tantos pollos,\nPollos con tantas gallinas,\nMadres con tantos hijitos,\nHijos con tanta familia.",3,1,0,59,"",0,4,"ia",-1,0,-1,0,696,696,"4289","",0,"","","",1,0,0,[],""],["carrizo_salta-n4290-01",3,"Hojas tengo sin ser árbol,\nSoy como el cielo también,\nPues en mi seno se sientan,\nLos santos que hay en aquél.",3,1,0,59,"",0,4,"e",-1,0,-1,0,696,696,"4290","",0,"","","",1,0,0,[],""],["carrizo_salta-n4291-01",3,"Mama panzona,\nTata barbudo,\nMeten y sacan,\nHijo menudo.",3,1,0,59,"",6,4,"uo",191,0,-1,0,696,696,"4291","",0,"","","",1,0,0,[],""],["carrizo_salta-n4293-01",3,"Por el aire va volando,\nSin plumas, sin corazón,\nAl vivo le da sustento,\nAl muerto consolación.",3,1,0,59,"",0,4,"o",31,0,-1,0,696,696,"4293","",0,"","","",2,0,0,[],""],["carrizo_salta-n4294-01",3,"¡Sacalo, marido!\nQue lo quiero ver,\n¡Qué lindo lo tienes,\nVolvelo a meter.",3,1,0,59,"",0,4,"e",20,0,-1,0,697,697,"4294","",0,"","","",1,0,0,[],""],["carrizo_salta-n4295-01",3,"Soy enteramente humilde,\nY no sé peliar con nadie,\nPero asusto al más valiente,\nAunque ni pienso pegarle.",3,1,0,59,"",0,4,"ae",-1,0,-1,0,697,697,"4295","",0,"","","",1,0,0,[],""],["carrizo_salta-n4296-01",3,"Soy la redondez del mundo,\nSin mí no puede haber Dios,\nPapas y cardenales, sí,\nPero pontífices, no.",3,1,0,59,"",0,4,"o",-1,0,-1,0,697,697,"4296","",0,"","","",3,0,0,[],""],["carrizo_salta-n4297-01",3,"Soy un señor encumbrado,\nAndo mejor que el reloj,\nMe levanto muy temprano,\nY me acuesto a la oración.",3,1,0,59,"",0,4,"o",-1,0,-1,0,697,697,"4297","",0,"","","",2,0,0,[],""],["carrizo_salta-n4298-01",3,"Tengo nombre de animal,\nY siempre vivo caliente,\nSirviendo a la mejor gente,\nY me dan el peor lugar.",3,1,0,59,"",5,4,"a",-1,0,-1,0,697,697,"4298","",0,"","","",1,0,0,[],""],["carrizo_salta-n4300-01",3,"Tronco de higuera,\nFlor de zapallo,\nTonta babosa,\nCara i caballo.",3,1,0,59,"",6,4,"ao",102,0,-1,0,697,697,"4300","",0,"","","",1,0,0,[],""],["carrizo_salta-n4301-01",3,"Una dama muy pelada,\nDe una palidez mortal,\nQue se alegra y se reanima,\nCuando la van a quemar.",3,1,0,59,"",3,4,"a",-1,0,-1,0,697,697,"4301","",0,"","","",1,0,0,[],""],["carrizo_salta-n4302-01",3,"Una llave tengo oculta,\nPara que mi pecho abroche.\n¿Es posible que se pierdan\nDos días en una noche?",3,1,0,59,"",0,4,"oe",337,0,-1,0,697,697,"4302","",0,"","","",1,0,0,[],""],["carrizo_salta-n4303-01",3,"Un hombre mató a su hermano,\nCuya madre no nació,\nY en el seno de su abuela,\nYa muerto, lo sepultó.",3,1,0,59,"",0,4,"o",2,0,-1,0,697,697,"4303","",0,"","","",1,0,0,[],""],["carrizo_salta-n4305-01",3,"Vestido verde,\nBata morada,\nDebajo de ella,\nEstá la bolada.",3,1,0,59,"",6,4,"aa",49,0,-1,0,698,698,"4305","",0,"","","",1,0,0,[],""],["carrizo_salta-n4306-01",3,"Vos tenís hondo,\nYo tengo largo,\nMovete un poco,\nHagamos algo.",3,1,0,59,"",6,4,"ao",-1,0,-1,0,698,698,"4306","",0,"","","",1,0,0,[],""],["carrizo_salta-n4307-01",3,"Ya que esa pregunta me hace,\nAhora me ha de avisar:\n¿Cuál es el ave del campo,\nQue vuela y da de mamar?",3,1,0,59,"",0,4,"a",21,0,-1,0,698,698,"4307","",0,"","","",3,0,0,[],""],["carrizo_salta-n4308-01",3,"Yo soy fresco, yo soy cálido,\nSoy de mucha calidad,\nY también soy un remedio,\nPara mujeres curar.",3,1,0,59,"",0,4,"a",-1,0,-1,0,698,698,"4308","",0,"","","",1,0,0,[],""],["carrizo_salta-n4309-01",3,"Yo soy oro, yo soy plata,\nY soy cobre y soy estaño,\nSoy moro, soy bautizado,\nSoy infiel y soy cristiano.",3,1,0,59,"",0,4,"ao",-1,0,-1,0,698,698,"4309","",0,"","","",1,0,0,[],""],["carrizo_salta-n4310-01",3,"Yo soy un cuerpo sin alma,\nSin güesos ni coyontura,\nQue se corta sin tijeras,\nY se cose sin costuras.",3,1,0,59,"",0,4,"ua",-1,0,-1,0,698,698,"4310","",0,"","","",1,0,0,[],""],["carrizo_salta-n4311-01",3,"Amapuni, amapuni,\nPalomaitaca,\nSuma pahuana chini\nAma paitaca.",3,1,0,60,"",6,4,"aa",457,0,-1,0,700,700,"4311","",0,"","","",1,0,0,[],""],["carrizo_salta-n4312-01",3,"Ccaina tusucu takico,\nLlagtai manta llocercane,\nCunan cairruna llastampi,\nTusuiraico huacashane.",3,1,0,60,"",0,4,"ae",489,0,-1,0,700,700,"4312","",0,"","","",1,0,0,[],""],["carrizo_salta-n4313-01",3,"Cunan mariripusag,\nYntiyai cunan la dota,\nSuerti casting cotemusag,\nMuerte casting quedacusag.",3,1,0,61,"",5,4,"a",490,0,-1,0,700,700,"4313","",0,"","","",1,0,0,[],""],["carrizo_salta-n4314-01",3,"Cunan ripusaj nerkane,\nMana yata ripunicho,\nCcaiacha tutai papusaj,\nAntes que amanezca el día.",3,1,0,61,"",5,4,"ia",-1,0,-1,0,700,700,"4314","",0,"","","",1,0,0,[],""],["carrizo_salta-n4316-01",3,"Chaina nispa jiña nispa,\nSoncoita nanachihuanke,\nMana muaike nishaspe,\nSin razón huaca chihuanke.",3,1,0,61,"",0,4,"ae",-1,0,-1,0,701,701,"4316","",0,"","","",1,0,0,[],""],["carrizo_salta-n4317-01",3,"Loritupis ccaiman,\nKakapis causaiman,\nA donde está mi dueña,\nKomería chayaima.",3,1,0,61,"",0,4,"aa",-1,0,-1,0,701,701,"4317","",0,"","","",1,0,0,[],""],["carrizo_salta-n4319-01",3,"Muñinga, muñinga,\nÑocca munacaita,\nUnos lloran penas,\nY otros apagaita.",3,1,0,61,"",0,4,"aa",491,0,-1,0,701,701,"4319","",0,"","","",1,0,0,[],""],["carrizo_salta-n4321-01",3,"Pachamama, Santa Tierra,\nCaita coscaiki,\nSanta hojata,\nAmas apihuaiahu,\nCaita hojaricuspa,\nLicorta, cigarros tapi cogeaíki.",3,1,0,61,"",9,6,"ii",-1,0,-1,0,702,702,"4321","",0,"","","",1,0,0,[],""],["carrizo_salta-n4322-01",3,"Ripuy, ripuy si atiguashan,\nPero mana ripuy inanchu,\nNi aunque sonccoi pismunasho,\nMana gustuta coimanchu.",3,1,0,61,"",0,4,"au",492,0,-1,0,702,702,"4322","",0,"","","",1,0,0,[],""],["carrizo_salta-n4323-01",3,"Si dije que te quería,\nEra por entretenerte,\nKichunkitoy atatai,\nMi bien, ¿por qué me dijiste?",3,1,0,61,"",5,4,"ie",-1,0,-1,0,702,702,"4323","",0,"","","",3,0,0,[],""],["carrizo_salta-n4324-01",3,"Si parinachu ccaiman,\nPatata pahuaiman,\nÁ donde esté mi dueña,\nPucaya chayaiman.",3,1,0,61,"",0,4,"aa",493,0,-1,0,702,702,"4324","",0,"","","",1,0,0,[],""],["carrizo_salta-n4325-01",3,"Uiscachita caiman,\nCerrupi causaiman,\nIrituta micus,\nChirita pasaiman.",3,1,0,61,"",0,4,"aa",493,0,-1,0,702,702,"4325","",0,"","","",1,0,0,[],""],["carrizo_salta-n4326-01",3,"Uiscachita ccaiman,\nKakapi causaiman,\nSoltera pasajten,\nChupaiman caschaiman.",3,1,0,61,"",0,4,"aa",493,0,-1,0,702,702,"4326","",0,"","","",1,0,0,[],""],["carrizo_salta-n4327-01",3,"Acuchis potrero ucuma,\nTacota palla puskaiki,\nPolleraiki yikiskuccpti,\nNoccami cirapusaiki.",3,1,0,62,"",0,4,"ai",494,0,-1,0,703,703,"4327","",0,"","","",1,0,0,[],""],["carrizo_salta-n4327-a-01",3,"Acuichis potrero cunan,\nTacota chocapuscaiki,\nPolleraiki yikicupti,\nNoccaya cirapuskaiki,",3,1,0,62,"",0,4,"ai",494,0,-1,0,703,703,"4327-a","",0,"","","",1,0,0,[],""],["carrizo_salta-n4328-01",3,"Alalita mamitilla,\nLachiguana mihuachia,\nAnimal tan ponzoñoso,\nUicita tapunkichia.",3,1,0,62,"",5,4,"ia",-1,0,-1,0,703,703,"4328","",0,"","","",2,0,0,[],""],["carrizo_salta-n4328-a-01",3,"Alalíta mamitilla,\nUala puca mihuachia,\nAnimal tan ponzoñoso,\nHuipaita mipunkichia.",3,1,0,62,"",5,4,"ia",-1,0,-1,0,703,703,"4328-a","",0,"","","",2,0,0,[],""],["carrizo_salta-n4329-01",3,"Caraipuca nisacara,\nNocca comisario cani,\nHualuta huaillajsacara,\nLibretata sorconampa.",3,1,0,62,"",5,4,"aa",-1,0,-1,0,703,703,"4329","",0,"","","",1,0,0,[],""],["carrizo_salta-n4333-01",3,"Tantas y cuantas veces,\nMi pensamiento,\nSale en busca de alivio,\nY halla un tormento.",3,1,0,63,"",6,4,"eo",94,0,-1,0,705,705,"4333","",0,"","","",1,0,0,[],""],["carrizo_salta-n4333-02",3,"Y halla un tormento, sí,\nTú lo decías,\nQue sólo con la muerte,\nMe olvidarías.",3,1,0,63,"",6,4,"ia",214,0,-1,0,705,705,"4333","",0,"","","",1,0,0,[],""],["carrizo_salta-n4334-01",3,"Si me muero enterradme,\nJunto a tu cama;\nQue me sirvan de luces,\nTus ojos, mi alma.",3,1,0,63,"",6,4,"aa",-1,0,-1,0,705,705,"4334","",0,"","","",1,0,0,[],""],["carrizo_salta-n4334-02",3,"Tus ojos, mi alma, sí,\nCorriendo dile,\nA la vidita mía,\nQue no me olvide.",3,1,0,63,"",6,4,"ie",-1,0,-1,0,705,705,"4334","",0,"","","",1,0,0,[],""],["carrizo_salta-n4335-01",3,"Como la mariposa,\nNegra es mi suerte;\nAquello que más amo,\nMe da la muerte.",3,1,0,63,"",6,4,"ee",134,0,-1,0,705,705,"4335","",0,"","","",6,0,0,[],""],["carrizo_salta-n4335-02",3,"Me da la muerte, sí,\nAsí te digo,\nQue no te has de ir con otro,\nSino conmigo.",3,1,0,63,"",6,4,"io",106,0,-1,0,705,705,"4335","",0,"","","",2,0,0,[],""],["carrizo_salta-n4336-01",3,"Varias contradicciones,\nTiene mi suerte,\nPues lo que tanto adoro,\nMe da la muerte.",3,1,0,63,"",6,4,"ee",134,0,-1,0,705,705,"4336","",0,"","","",1,0,0,[],""],["carrizo_salta-n4336-02",3,"Me da la muerte, sí,\nAsí decía,\nUn enfermo de amores,\nQue se moría.",3,1,0,63,"",6,4,"ia",0,0,-1,0,705,705,"4336","",0,"","","",2,0,0,[],""],["carrizo_salta-n4337-01",3,"Si te manda tu madre,\nCerrar la puerta,\nHacé sonar la llave,\nDejala abierta.",3,1,0,63,"",6,4,"ea",267,0,-1,0,705,705,"4337","",0,"","","",1,0,0,[],""],["carrizo_salta-n4337-02",3,"Dejala abierta, sí,\nPrenda querida;\nQue algún día he de ser tuyo,\nToda la vida.",3,1,0,63,"",6,4,"ia",37,0,-1,0,705,705,"4337","",0,"","","",1,0,0,[],""],["carrizo_salta-n4338-01",3,"Cinta negra en el pelo,\nTe has amarrado;\nAntes que yo me muera,\nTe has enlutado.",3,1,0,63,"",6,4,"ao",14,0,-1,0,705,705,"4338","",0,"","","",7,0,0,[],""],["carrizo_salta-n4338-02",3,"Te has enlutado, sí,\nPrenda adorada;\nPropiedad de mujeres,\nLlorar por nada.",3,1,0,63,"",6,4,"aa",49,0,-1,0,705,705,"4338","",0,"","","",1,0,0,[],""],["carrizo_salta-n4339-01",3,"De terciopelo negro,\nTraigo cortinas;\nPara enlutar mi cama,\nSi tú me olvidas.",3,1,0,63,"",6,4,"ia",-1,0,-1,0,705,705,"4339","",0,"","","",7,0,0,[],""],["carrizo_salta-n4339-02",3,"Si tú me olvidas, sí,\nPonete al frente,\nQue aunque no seas mi dueña,\nMe gusta el verte.",3,1,0,63,"",6,4,"ee",-1,0,-1,0,705,705,"4339","",0,"","","",1,0,0,[],""],["carrizo_salta-n4340-01",3,"El pasar por tu casa,\nMe gusta tanto;\nCuando el altar me gusta,\n¿Qué será el santo?",3,1,0,63,"",6,4,"ao",30,0,-1,0,705,705,"4340","",0,"","","",1,0,0,[],""],["carrizo_salta-n4340-02",3,"Qué será el santo, sí,\nCielo querido,\nRamillete de flores,\nJardín florido.",3,1,0,63,"",6,4,"io",101,0,-1,0,705,705,"4340","",0,"","","",1,0,0,[],""],["carrizo_salta-n4341-01",3,"Dime, ¿qué significa,\nCuando te pones,\nEn la puerta y me miras,\nLuego te escondes?",3,1,0,63,"",6,4,"oe",-1,0,-1,0,706,706,"4341","",0,"","","",2,0,0,[],""],["carrizo_salta-n4341-02",3,"Luego te escondes, sí,\nRico tesoro,\nY tal vez tú no sepas,\nCuanto te adoro.",3,1,0,63,"",6,4,"oo",85,0,-1,0,706,706,"4341","",0,"","","",1,0,0,[],""],["carrizo_salta-n4342-01",3,"Ojos negros y pardos,\nSon muy comunes;\nPor eso yo me muero,\nPor los azules.",3,1,0,63,"",6,4,"ue",-1,0,-1,0,706,706,"4342","",0,"","","",4,0,0,[],""],["carrizo_salta-n4342-02",3,"Por los azules, sí,\nPerla y topacio,\nComo lucero brillas,\nEn el espacio.",3,1,0,63,"",6,4,"ao",440,0,-1,0,706,706,"4342","",0,"","","",1,0,0,[],""],["carrizo_salta-n4343-01",3,"¡Tienes unos ojitos!\n¡Y unas pestañas!\nY una lengua embustera,\nCon que me engañas.",3,1,0,63,"",6,4,"aa",42,0,-1,0,706,706,"4343","",0,"","","",20,0,0,[],""],["carrizo_salta-n4343-02",3,"Con que me engañas, sí,\nAgua y arena;\nDonde no hay morenitas,\nNo hay cosa buena.",3,1,0,63,"",6,4,"ea",59,0,-1,0,706,706,"4343","",0,"","","",1,0,0,[],""],["carrizo_salta-n4344-01",3,"Prestadme tus ojitos,\nTendré dos pares;\nQue con los míos no puedo\nLlorar mis males.",3,1,0,63,"",6,4,"ae",-1,0,-1,0,706,706,"4344","",0,"","","",1,0,0,[],""],["carrizo_salta-n4344-02",3,"Llorar mis males, sí,\n¡Ay, que me fundo!\nComo soy inocente,\nNo sé que es mundo.",3,1,0,63,"",6,4,"uo",179,0,-1,0,706,706,"4344","",0,"","","",1,0,0,[],""],["carrizo_salta-n4345-01",3,"De Buenos Aires vengo,\nSoy coracero,\nTraigo espaldas de bronce,\nPecho de acero.",3,1,0,63,"",6,4,"eo",38,0,-1,0,706,706,"4345","",0,"","","",1,0,0,[],""],["carrizo_salta-n4345-02",3,"Pecho de acero, sí,\nNo hallo que hacerme,\nSi me boto a los montes,\nTemo perderme.",3,1,0,63,"",6,4,"ee",245,0,-1,0,706,706,"4345","",0,"","","",1,0,0,[],""],["carrizo_salta-n4346-01",3,"Dicen que las heladas,\nSecan los yuyos,\nAsí me van secando,\nAmores tuyos.",3,1,0,63,"",6,4,"uo",495,0,-1,0,706,706,"4346","",0,"","","",2,0,0,[],""],["carrizo_salta-n4346-02",3,"Amores tuyos, sí,\nDime ¿hasta cuándo\nHas de tenerme, negra,\nCalaveriando?",3,1,0,63,"",6,4,"ao",33,0,-1,0,706,706,"4346","",0,"","","",1,0,0,[],""],["carrizo_salta-n4347-01",3,"El amor y los campos,\nSon dos iguales;\nTambién el amor tiene\nSus sequedades.",3,1,0,63,"",6,4,"ae",-1,0,-1,0,706,706,"4347","",0,"","","",2,0,0,[],""],["carrizo_salta-n4347-02",3,"Sus sequedades, sí,\nEsto es muy cierto,\nComo sacarse un ojo,\nQuedarse tuerto.",3,1,0,63,"",6,4,"eo",88,0,-1,0,706,706,"4347","",0,"","","",2,0,0,[],""],["carrizo_salta-n4348-01",3,"Como pasa el invierno,\nPasa el verano;\nPasan mis ilusiones,\nAño por año.",3,1,0,63,"",6,4,"ao",-1,0,-1,0,706,706,"4348","",0,"","","",1,0,0,[],""],["carrizo_salta-n4348-02",3,"Año por año, sí,\nPrenda tirana;\nMe tienes engañando,\nTarde y mañana.",3,1,0,63,"",6,4,"aa",4,0,-1,0,706,706,"4348","",0,"","","",1,0,0,[],""],["carrizo_salta-n4349-01",3,"No me digas amante,\nDecime dueño;\nTratadme como a tuyo,\nNo como ajeno.",3,1,0,63,"",6,4,"eo",-1,0,-1,0,706,706,"4349","",0,"","","",1,0,0,[],""],["carrizo_salta-n4349-02",3,"No como ajeno, sí,\nDueña de mi alma;\n¿Cuándo hallaré en tus brazos,\nLa dulce calma?",3,1,0,63,"",6,4,"aa",125,0,-1,0,706,706,"4349","",0,"","","",1,0,0,[],""],["carrizo_salta-n4350-01",3,"¡Vidita de mi vida!\nNo he merecido,\nQue me hagas un cariño,\nDe tu motivo.",3,1,0,63,"",6,4,"io",-1,0,-1,0,706,706,"4350","",0,"","","",2,0,0,[],""],["carrizo_salta-n4350-02",3,"De tu motivo, sí,\nMuy desgraciado,\nPues sin causa ninguna,\nMe has olvidado.",3,1,0,63,"",6,4,"ao",14,0,-1,0,706,706,"4350","",0,"","","",1,0,0,[],""],["carrizo_salta-n4351-01",3,"Dices que no me quieres,\nYa me has querido;\nVáyase lo ganado,\nPor lo perdido.",3,1,0,63,"",6,4,"io",101,0,-1,0,707,707,"4351","",0,"","","",15,0,0,[],""],["carrizo_salta-n4351-02",3,"Por lo perdido, sí,\n¡Miren qué chiste!\nQue porque tú me olvides,\nMe ponga triste.",3,1,0,63,"",6,4,"ie",-1,0,-1,0,707,707,"4351","",0,"","","",1,0,0,[],""],["carrizo_salta-n4352-01",3,"Si me dieras un dentro,\nPor tu ventana,\nDe rodillas me fuera,\nHasta tu cama.",3,1,0,63,"",6,4,"aa",-1,0,-1,0,707,707,"4352","",0,"","","",1,0,0,[],""],["carrizo_salta-n4352-02",3,"Hasta tu cama, sí,\nJazmín dorado,\n¿Por qué me tienes, mi alma,\nTan olvidado?",3,1,0,63,"",6,4,"ao",14,0,-1,0,707,707,"4352","",0,"","","",1,0,0,[],""],["carrizo_salta-n4353-01",3,"¡Vámonos, vida mía,\nDonde llorastes!\nA recoger las perlas,\nQue derramastes.",3,1,0,63,"",6,4,"ae",142,0,-1,0,707,707,"4353","",0,"","","",2,0,0,[],""],["carrizo_salta-n4353-02",3,"Que derramastes, sí,\nTriste es mi suerte,\nAntes que tú me olvides,\nDadme la muerte.",3,1,0,63,"",6,4,"ee",134,0,-1,0,707,707,"4353","",0,"","","",1,0,0,[],""],["carrizo_salta-n4354-01",3,"¡Vámonos, vida mía,\nVámonos dónde!\nDonde la luna nace,\nY el sol se esconde.",3,1,0,63,"",6,4,"oe",260,0,-1,0,707,707,"4354","",0,"","","",2,0,0,[],""],["carrizo_salta-n4354-02",3,"Y el sol se esconde, sí,\n¡Vida de mi alma!\nAllí estaremos juntos,\nEn paz y en calma.",3,1,0,63,"",6,4,"aa",125,0,-1,0,707,707,"4354","",0,"","","",1,0,0,[],""],["carrizo_salta-n4355-01",3,"Quisiera ser arito,\nDe tus orejas,\nPara de cuando en cuando,\nDarte mis quejas.",3,1,0,63,"",6,4,"ea",496,0,-1,0,707,707,"4355","",0,"","","",1,0,0,[],""],["carrizo_salta-n4355-02",3,"Darte ms quejas, sí,\nTe amo y te adoro,\nY has de ser tú la llave,\nDe mi tesoro.",3,1,0,63,"",6,4,"oo",85,0,-1,0,707,707,"4355","",0,"","","",1,0,0,[],""],["carrizo_salta-n4356-01",3,"Ofrecele a esa niña,\nUnos zarcillos,\nDel orito más fino,\nDe Chañarcillos.",3,1,0,63,"",6,4,"io",-1,0,-1,0,707,707,"4356","",0,"","","",1,0,0,[],""],["carrizo_salta-n4356-02",3,"De Chañarcillos, sí,\nNo me desaires,\nZapatito de raso,\nBotín de baile.",3,1,0,63,"",6,4,"ae",-1,0,-1,0,707,707,"4356","",0,"","","",1,0,0,[],""],["carrizo_salta-n4357-01",3,"Si de cristales fueran,\nLos corazones,\n¡Qué de claro se vieran!\nLas intenciones.",3,1,0,63,"",6,4,"oe",34,0,-1,0,707,707,"4357","",0,"","","",3,0,0,[],""],["carrizo_salta-n4357-02",3,"Las intenciones, sí,\nEs cosa rara,\nQue siendo tú la nieve,\nYo me deshaga.",3,1,0,63,"",6,4,"aa",-1,0,-1,0,707,707,"4357","",0,"","","",1,0,0,[],""],["carrizo_salta-n4358-01",3,"Tomá este puñalito,\nAbrime el pecho,\nY verás tu retrato,\nSi está bien hecho.",3,1,0,63,"",6,4,"eo",60,0,-1,0,707,707,"4358","",0,"","","",3,0,0,[],""],["carrizo_salta-n4358-02",3,"Si está bien hecho, sí,\nAbrilo, abrilo,\nNo te demores, mi alma,\nEn descubrirlo.",3,1,0,63,"",6,4,"io",-1,0,-1,0,707,707,"4358","",0,"","","",1,0,0,[],""],["carrizo_salta-n4359-01",3,"Antenoche y anoche,\nY esta mañana;\nMe corrieron los perros,\nDe mama Juana.",3,1,0,63,"",6,4,"aa",4,0,-1,0,707,707,"4359","",0,"","","",2,0,0,[],""],["carrizo_salta-n4359-02",3,"De mama Juana, sí,\nTriste me alejo;\nCasi, por estos pagos,\nPierdo el pellejo.",3,1,0,63,"",6,4,"eo",264,0,-1,0,707,707,"4359","",0,"","","",1,0,0,[],""],["carrizo_salta-n4361-01",3,"Anda, dile a tu madre,\nQue te empapele,\nQue el galán que te quizo,\nYa no te quiere.",3,1,0,63,"",6,4,"ee",-1,0,-1,0,708,708,"4361","",0,"","","",1,0,0,[],""],["carrizo_salta-n4361-02",3,"Ya no te quiere, sí,\nBella sirena,\nCorazón en tormento,\nLleno de pena.",3,1,0,63,"",6,4,"ea",59,0,-1,0,708,708,"4361","",0,"","","",1,0,0,[],""],["carrizo_salta-n4362-01",3,"De los arrepentidos,\nYo soy el uno,\nDe todo me arrepiento,\nMenos del mundo.",3,1,0,63,"",6,4,"uo",-1,0,-1,0,708,708,"4362","",0,"barcenas_marinera, huambachano","","",3,0,0,[],""],["carrizo_salta-n4362-02",3,"Menos del mundo, sí,\nEsto es muy justo,\nQue te he de amar, mi vida,\nCon todo gusto.",3,1,0,63,"",6,4,"uo",497,0,-1,0,708,708,"4362","",0,"","","",1,0,0,[],""],["carrizo_salta-n4363-01",3,"Todos viven amando,\nYo sólo muero,\nAl ver que todos aman,\nLo que yo quiero.",3,1,0,63,"",6,4,"eo",38,0,-1,0,708,708,"4363","",0,"","","",2,0,0,[],""],["carrizo_salta-n4363-02",3,"Lo que yo quiero, sí,\nLloré muy triste,\nLamentando mi suerte,\nPorque te fuistes.",3,1,0,63,"",6,4,"ie",-1,0,-1,0,708,708,"4363","",0,"","","",1,0,0,[],""],["carrizo_salta-n4364-01",3,"¿Para qué me dijistes,\nQue me querías,\nQue sólo con la muerte\nMe olvidarías?",3,1,0,63,"",6,4,"ia",214,0,-1,0,708,708,"4364","",0,"","","",2,0,0,[],""],["carrizo_salta-n4364-02",3,"Me olvidarías, sí,\nLloré, lloraba,\nCon un dolor profundo,\nPorque te amaba.",3,1,0,63,"",6,4,"aa",28,0,-1,0,708,708,"4364","",0,"","","",2,0,0,[],""],["carrizo_salta-n4365-01",3,"Todas las buenasmozas,\nSon perseguidas,\nComo arbolito nuevo,\nDe las hormigas.",3,1,0,63,"",6,4,"ia",-1,0,-1,0,708,708,"4365","",0,"","","",1,0,0,[],""],["carrizo_salta-n4365-02",3,"De las hormigas, sí,\nTú me condenas;\nEl que en de veras ama,\nTiene sus penas.",3,1,0,63,"",6,4,"ea",62,0,-1,0,708,708,"4365","",0,"","","",1,0,0,[],""],["carrizo_salta-n4366-01",3,"La mujer chiquitita,\nCorre peligro,\nComo quirquincho bola,\nJunto al camino.",3,1,0,63,"",6,4,"io",-1,0,-1,0,708,708,"4366","",0,"","","",3,0,0,[],""],["carrizo_salta-n4366-02",3,"Junto al camino, sí,\nTriste llorando,\nYo te daré el consuelo,\nDe cuando en cuando.",3,1,0,63,"",6,4,"ao",33,0,-1,0,708,708,"4366","",0,"","","",2,0,0,[],""],["carrizo_salta-n4367-01",3,"Arbolito, arbolito,\nDe verdes hojas,\n¡Qué bonito te pones,\nCuando te enojas!",3,1,0,63,"",6,4,"oa",364,0,-1,0,708,708,"4367","",0,"","","",3,0,0,[],""],["carrizo_salta-n4367-02",3,"Cuando te enojas, sí,\nDale que dale,\nCuando más chicharrones,\nMás grasa sale.",3,1,0,63,"",6,4,"ae",202,0,-1,0,708,708,"4367","",0,"","","",1,0,0,[],""],["carrizo_salta-n4368-01",3,"No me tires al ala,\nCarabinero,\nQue soy águila nueva,\nQue recién vuelo.",3,1,0,63,"",6,4,"eo",-1,0,-1,0,708,708,"4368","",0,"","","",2,0,0,[],""],["carrizo_salta-n4368-02",3,"Que recién vuelo, sí,\n¡Mundo engañoso!\nMás vale caer en gracia,\nQue ser gracioso.",3,1,0,63,"",6,4,"oo",160,0,-1,0,708,708,"4368","",0,"","","",1,0,0,[],""],["carrizo_salta-n4371-01",3,"Del ciento de suspiros,\nQue el amor tiene;\nYo tengo suspirados,\nNoventa y nueve.",3,1,0,63,"",6,4,"ee",-1,0,-1,0,709,709,"4371","",0,"","","",1,0,0,[],""],["carrizo_salta-n4371-02",3,"Noventa y nueve, sí,\nNo te lo niego,\nQue por tu amor estoy,\nYa medio ciego.",3,1,0,63,"",6,4,"eo",29,0,-1,0,709,709,"4371","",0,"","","",1,0,0,[],""],["carrizo_salta-n4372-01",3,"De tus hermosos ojos,\nNo tengo quejas;\nEllos quieren mirarme,\nTú no los dejas.",3,1,0,63,"",6,4,"ea",496,0,-1,0,709,709,"4372","",0,"","","",5,0,0,[],""],["carrizo_salta-n4372-02",3,"Tú no los dejas, sí,\n¡Vidita mía!\n¿Por qué me tratas, cielo,\nCon tiranía?",3,1,0,63,"",6,4,"ia",0,0,-1,0,709,709,"4372","",0,"","","",1,0,0,[],""],["palau_cantares-00002",4,"Del África vino un mágico\ná preguntar el por qué\nhabía tanto perlático;\nyo al punto le contesté:\nTu padre fué catredático.",4,0,-1,-1,"",7,5,"ao",498,0,-1,0,17,17,"","",1,"","","",1,0,0,[],""],["palau_cantares-00003a",4,"¡Oh loca esperanza vana,\ncuántos siglos ha que voy\nengañando el día de hoy\nesperando el de mañana!",4,0,-1,-1,"",11,4,"aa",4,0,-1,0,18,18,"","",1,"","","",1,0,0,[],""],["palau_cantares-00003b",4,"En el campo me metí\ná lidiar con mi deseo:\nconmigo mismo peleo.\nDefiéndame Dios de mí.",4,0,-1,-1,"",11,4,"i",23,0,-1,0,18,18,"","",1,"","","",1,0,0,[],""],["palau_cantares-00003c",4,"Por entre casos injustos\nme han traído mis engaños\ndonde son los daños daños\ny los gustos no son gustos.",4,0,-1,-1,"",11,4,"uo",363,0,-1,0,18,18,"","",1,"","","",1,0,0,[],""],["palau_cantares-00004",4,"En tanto que el amor dura,\ntoda locura es fineza;\nluego que el olvido empieza,\ntoda fineza es locura:",4,0,-1,-1,"",11,4,"ua",17,0,-1,0,18,18,"","",1,"","","",1,0,0,[],""],["palau_cantares-00005",4,"Pide, si quieres, mi vida,\nmas no me pidas mi honor,\nque es patrimonio del alma\ny el alma sólo es de Dios:",4,0,-1,-1,"",0,4,"o",-1,0,-1,0,18,18,"","",1,"","","",1,0,0,[],""],["palau_cantares-00006",4,"Ven hermosa serrana,\nven á mi selva,\nque el sol por esos campos\ntu rostro quema:\nven y no tardes,\nque aquí hay fuentes y sombras\ny amor y amante:",4,0,-1,-1,"",4,7,"ae",-1,0,-1,0,18,18,"","",1,"","","",1,0,0,[],""],["palau_cantares-00008r1",4,"Camino de Castilla\nya no va nadie,\nsi no es polvo y arena\nque lleva el aire,",4,0,-1,-1,"",6,4,"ae",-1,0,-1,0,22,22,"","",1,"","","",1,0,0,[],""],["palau_cantares-00009",4,"Mi pañuelo y tu pañuelo\nson cortados de una pieza;\ntú lo llevas en el cuello,\nyo lo llevo en la cabeza,",4,0,-1,-1,"",0,4,"ea",108,0,-1,0,22,22,"","",1,"","","",1,0,0,[],""],["palau_cantares-00010",4,"Para que no escale el cielo\nun divé me tiene preso:\nme ha dado el mundo por jaula\ny la mar por bebedero.",4,0,-1,-1,"",0,4,"eo",-1,0,-1,0,23,23,"","",1,"","","",1,0,0,[],""],["palau_cantares-00011",4,"¿Sabes á quién te pareces?\n¿Sabes á quién te das aire?\nAl sol cuando está más alto\ny á la luna cuando sale.",4,0,-1,64,"PIROPOS Y F L O R E S",0,4,"ae",-1,0,-1,0,27,27,"","",1,"","","",3,0,0,[],""],["palau_cantares-00011-e2",4,"Soñé y vi que eras un ángel\nque del cielo te escapabas,\ny Dios quiso detenerte\ny se quedó con las alas.",4,0,-1,64,"PIROPOS Y F L O R E S",0,4,"aa",-1,0,-1,0,27,27,"","",1,"","","",1,0,0,[],""],["palau_cantares-00012",4,"Eres la flor de las flores,\neres rosa entre las rosas,\neres la que estimo y amo,\neres tú la más hermosa.",4,0,-1,64,"",0,4,"oa",-1,0,-1,0,27,27,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00013",4,"No sé como no florece\nla escalera de tu casa,\nsubiéndola quien la sube,\nbajándola quien la baja.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,27,27,"","",1,"","","",3,0,0,[],""],["palau_cantares-00014",4,"Eres más apetecible\nque el fresco de la mañana,\ny más hermosa y más bella\nque rosa de abril temprana.",4,0,-1,64,"",0,4,"aa",4,0,-1,0,27,27,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00015",4,"Pequeñita y redondita\ncomo grano de cebada;\nlo que tienes de pequeña\nlo tienes de resalada.",4,0,-1,64,"",0,4,"aa",49,0,-1,0,27,27,"","",1,"","","",1,0,0,[],""],["palau_cantares-00016",4,"Al verte las flores lloran\ncuando entras en tu jardín,\nporque las flores quisieran\ntodas parecerse á ti.",4,0,-1,64,"",0,4,"i",-1,0,-1,0,27,27,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00017",4,"Tú eres el clavel de abril\ny la rosita de mayo,\nla hermosa luna de enero,\nque me tienes hechizado.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,27,27,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00018",4,"A tu puerta llamo puerta,\ny á tu ventana ventana,\ná tu madre jardinera,\ny á ti rosita encarnada.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,27,27,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00019",4,"Eres una clavellina\nrodeada de claveles:\ncomo eres tan peregrina,\nhechizadito me tienes.",4,0,-1,64,"",0,4,"ee",-1,0,-1,0,27,27,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00020",4,"Cuando va mi niña á misa\nla iglesia se resplandece,\nhasta la hierba que pisa,\nsi está seca, reverdece.",4,0,-1,64,"",1,4,"ee",64,0,-1,0,27,27,"","",1,"","","",2,0,0,[],""],["palau_cantares-00021",4,"Un pajarillo alegre\npicó en tu boca,\npensando que tus labios\neran dos rosas.",4,0,-1,64,"",6,4,"oa",-1,0,-1,0,28,28,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00022",4,"¿Para qué vas por lumbre\nla calle arriba,\nsi sale de tu cara\nla llama viva?",4,0,-1,64,"",6,4,"ia",53,0,-1,0,28,28,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00023",4,"Capitanes de guerra\nson tus dos labios,\ny tus dientes en fila\nson los soldados.",4,0,-1,64,"",6,4,"ao",-1,0,-1,0,28,28,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-00024",4,"Niña que vas á lavar\nal río del Manzanares,\n¿para qué quieres jabón\nsi tus manos son cristales?",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,28,28,"","",1,"","","",2,0,0,[],""],["palau_cantares-00025",4,"Sin duda que tu padre\nfué confitero,\ny te hizo los labios\nde caramelo.",4,0,-1,64,"",6,4,"eo",-1,0,-1,0,28,28,"","",1,"rm_t2, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00026",4,"Es tu pecho una alcobita\nhecha con tanto primor,\nque me parece á la vista\nde la gloria el resplandor.",4,0,-1,64,"",0,4,"o",72,0,-1,0,28,28,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00027",4,"Tienes una boquita\ntan embustera,\nque á batalla de besos\nme la comiera.",4,0,-1,64,"",6,4,"ea",44,0,-1,0,28,28,"","",1,"","","",4,0,0,[],""],["palau_cantares-00028",4,"Son tus manos palmas reales,\ntus dedos diez azucenas,\ntus labios finos corales,\ntus dientes menudas perlas.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,28,28,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00029",4,"Bendita sea tu casa\ny el albañil que la hizo,\nque por dentro está la gloria\ny por fuera el paraíso.",4,0,-1,64,"",0,4,"io",92,0,-1,0,28,28,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00030",4,"¡Ay, qué dedos para anillos,\nqué pecho para un diamante,\nqué orejas para zarcillos,\nqué niña para un amante!",4,0,-1,64,"",1,4,"ae",47,0,-1,0,28,28,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00031",4,"Eres tú la que le quitas\nel color á la manzana,\ny la blancura á la nieve,\ny la frescura á las aguas.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,28,28,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00032",4,"¡Qué manitas para guantes,\npara sortijas qué dedos,\nqué cuello para collares,\nqué boquita para un beso!",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,28,28,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00033",4,"El día que tú naciste\nnacieron todas las flores,\ny en la pila del bautismo\ncantaban los ruiseñores.",4,0,-1,64,"",0,4,"oe",5,0,-1,0,28,28,"","",1,"lafuente_madrid","","",16,0,0,[],""],["palau_cantares-00034",4,"Eres hermosa y robas\nlos corazones:\n¿dónde pondré yo el mío,\nque no lo robes?",4,0,-1,64,"",6,4,"oe",-1,0,-1,0,28,28,"","",1,"rm_t2, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00035",4,"Tus cabellos son tales,\nhermosa niña,\nque me matan de amores,\ny al sol de envidia.",4,0,-1,64,"",6,4,"ia",-1,0,-1,0,28,28,"","",1,"","","",2,0,0,[],""],["palau_cantares-00037",4,"La nieve por tu cara\npasó diciendo:\ncomo aquí no hago falta,\nno me detengo.",4,0,-1,64,"",6,4,"eo",-1,0,-1,0,28,28,"","",1,"","","",3,0,0,[],""],["palau_cantares-00038",4,"Eres hermosa en extremo,\ntu color no tiene igual,\ntu cuerpo se gallardea\ncomo barquilla en el mar.",4,0,-1,64,"",0,4,"a",-1,0,-1,0,28,28,"","",1,"","","",7,0,0,[],""],["palau_cantares-00039",4,"Es tu cara una rosa\nque colorea,\ny tu cintura el tallo\nque la menea.",4,0,-1,64,"",6,4,"ea",54,0,-1,0,28,28,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00040",4,"Tienes la cara pecosa\ncomo huevo de perdiz;\nen cada peca una rosa,\ny en medio una flor de lis.",4,0,-1,64,"",1,4,"i",58,0,-1,0,28,28,"","",1,"","","",3,0,0,[],""],["palau_cantares-00041",4,"Tienes pecas en la cara;\npero no te dé cuidado,\nque mejor parece el cielo\ncuando está más estrellado.",4,0,-1,64,"",0,4,"ao",14,0,-1,0,29,29,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00042",4,"Las rosas y los claveles\nse dieron una batalla,\ny los claveles ganaron,\nporque reinan en tu cara.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,29,29,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00043",4,"Tienes en tu cara pecas,\ny en tu garganta lunares,\ny en tu pecho más virtudes\nque rosas en los rosales.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,29,29,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00043-e2",4,"Tiene la prenda que adoro\nun lunar en un carrillo,\ny en el otro lado tiene\nla estrella del cielo empíreo.",4,0,-1,64,"",0,4,"io",-1,0,-1,0,29,29,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00043-e3",4,"¿Con qué te lavas la cara,\nojitos de palomita?\n¿Con qué te lavas la cara,\nque la tienes tan bonita?",4,0,-1,64,"",1,4,"ia",50,0,-1,0,29,29,"","",1,"rm_t2, lafuente_madrid","","",9,0,0,[],""],["palau_cantares-00043-e4",4,"- ¿Con qué te lavas la cara,\nque tan colorada estás?\n- Me lavo con agua clara,\ny Dios pone lo demás.",4,0,-1,64,"",1,4,"a",51,0,-1,0,29,29,"","",1,"rm_t2, lafuente_madrid","","",9,0,0,[],""],["palau_cantares-00043-e5",4,"Parece mi morena,\ncuando va á misa,\npajarita de nieve,\nque anda y no pisa.",4,0,-1,64,"",6,4,"ia",68,0,-1,0,29,29,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00043-e6",4,"Tienes el rostro serio\ny el mirar grave,\ny en el andar sereno\npareces nave.",4,0,-1,64,"",6,4,"ae",69,0,-1,0,29,29,"","",1,"","","",2,0,0,[],""],["palau_cantares-00043-e7",4,"Prende, cuando se peina\nmi dueño hermoso,\nen agujas de plata\ncabellos de oro.",4,0,-1,64,"",6,4,"oo",-1,0,-1,0,29,29,"","",1,"","","",1,0,0,[],""],["palau_cantares-00044",4,"Cuando voy al Pirineo\ny paso por su espesura,\ny veo la blanca nieve,\nme acuerdo de tu hermosura.",4,0,-1,64,"",0,4,"ua",17,0,-1,0,29,29,"","",1,"","","",1,0,0,[],""],["palau_cantares-00045",4,"Entre la nieve y la grana\nse formaron tus mejillas,\ny como la nieve es blanca,\nlo encarnado es lo que brilla.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,29,29,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00046",4,"Mira si he corrido tierras,\nque he estado en Benamejí;\nno he visto cara más bella\nque la de este serafín.",4,0,-1,64,"",0,4,"i",-1,0,-1,0,29,29,"","",1,"lafuente_madrid","","",15,0,0,[],""],["palau_cantares-00047",4,"Muchas veces estoy viendo\nlas rosas de tu ventana,\ny muchas veces me engaño,\ncreyendo que son tu cara.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,29,29,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00048",4,"Tienes en tu cara pecas,\ny en tus carrillos colores,\ny en tu cuello gargantillas,\ny en tu corazón amores.",4,0,-1,64,"",0,4,"oe",5,0,-1,0,29,29,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00049",4,"Hoyos tienes en la cara\nde viruelas que te han dado,\nen cada hoyo una rosa\ny un clavel disciplinado.",4,0,-1,64,"",0,4,"ao",14,0,-1,0,30,30,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00050",4,"Tienes el pelo rubito\nde perlas claveteado;\nasí me tiene á mí\nel corazón traspasado.",4,0,-1,64,"",0,4,"ao",14,0,-1,0,30,30,"","",1,"","","",3,0,0,[],""],["palau_cantares-00051",4,"Dame una clavellina\nde tus claveles,\ndámela tan hermosa\ncomo tú eres.",4,0,-1,64,"",6,4,"ee",-1,0,-1,0,30,30,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00052",4,"Con esos rizos hermosos\nque te cuelgan por la cara,\npareces la Magdalena,\ncuando por el mundo andaba.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,30,30,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00053",4,"Del donaire de Filis\ny el garabato\ndos mil corazoncillos\nestán colgando.",4,0,-1,64,"",6,4,"ao",-1,0,-1,0,30,30,"","",1,"","","",1,0,0,[],""],["palau_cantares-00054",4,"Los cabellos de mi rubia\nse los ha robado al sol;\ná mí me ha robado el alma,\nla vida y el corazón.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,30,30,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00055",4,"Mariquita María,\nla de mi barrio,\nhasta el agua bendita\ntoma con garbo.",4,0,-1,64,"",6,4,"ao",-1,0,-1,0,30,30,"","",1,"rm_t2, fernan_caballero","","",12,0,0,[],""],["palau_cantares-00056",4,"Esos rizos que te adornan\nesa peregrina cara\nson flechas con que me has hecho\nherida que nunca sana.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,30,30,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00057",4,"Así como corre el agua\npor debajo de la adelfa,\nasí corre por tu cara\nla gracia de Dios, morena.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,30,30,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00058",4,"Con ese pelito rubio\ny esa cara tan divina\nes usted la encantadora\nde toda la estudiantina.",4,0,-1,64,"",0,4,"ia",11,0,-1,0,30,30,"","",1,"","","",4,0,0,[],""],["palau_cantares-00059",4,"En enero no hay claveles,\nporque los marchita el hielo;\nen tu cara los hay siempre,\nporque lo permite el cielo.",4,0,-1,64,"",0,4,"eo",10,0,-1,0,30,30,"","",1,"rm_t2, carrizo_salta, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00060",4,"Rubita, sol de los soles,\ntu cara es una custodia,\ny tu pecho la escalera\npara subir á la gloria.",4,0,-1,64,"",0,4,"oa",-1,0,-1,0,30,30,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00061",4,"De tu cara sale el sol,\nde tu garganta la luna:\nmorenas he visto yo,\npero como tú ninguna.",4,0,-1,64,"",0,4,"ua",56,0,-1,0,30,30,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00062",4,"Eres como el trigo rubio\nescogido grano á grano;\neres tú la más hermosa\nque mis ojos han mirado.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,30,30,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00063",4,"Con lo blanco de tu cuello,\nsalada, me cautivaste;\nátame con tu cabello\nhasta que venga el rescate.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,30,30,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00064",4,"Vivan los cabellos rubios,\nvivan los rubios rubiales,\ny vivan los de mi niña\nque son rubios naturales.",4,0,-1,64,"",0,4,"ae",26,0,-1,0,30,30,"","",1,"","","",2,0,0,[],""],["palau_cantares-00065",4,"Quítate esta mantellina,\nque te quiero ver el pelo;\nque para ver una imagen\nantes se descorre el velo.",4,0,-1,64,"",0,4,"eo",10,0,-1,0,30,30,"","",1,"","","",1,0,0,[],""],["palau_cantares-00066",4,"Eres más rubia que el sol\ny más blanca que la nieve;\neres rosa alejandrina,\nque todo el año florece.",4,0,-1,64,"",0,4,"ee",-1,0,-1,0,30,30,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00067",4,"Eres rubia como el sol,\ny en tus cabellos hay fuego\nque abrasa los corazones\naunque parezcan de hielo.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,30,30,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00068",4,"Los cabellos de las rubias\ndicen que tienen veneno:\nhe de casarme con una,\naunque me mate con ellos.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,30,30,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00069",4,"De tu pelito, rubita,\ncorté, rubita, un cabello,\né hice una cadenita,\nrubita, y me la eché al cuello.",4,0,-1,64,"",1,4,"eo",12,0,-1,0,31,31,"","",1,"","","",3,0,0,[],""],["palau_cantares-00070",4,"Puede una mujer morena,\ncon una mirada que eche,\nponer á un hombre en la cama\ny en un hospital diez meses.",4,0,-1,64,"",0,4,"ee",-1,0,-1,0,31,31,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00071",4,"Del cabello más sutil\nque tienes en tu trenzado\nhe de hacer una cadena\npara traerte á mi lado.",4,0,-1,64,"",0,4,"ao",14,0,-1,0,31,31,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00072",4,"Vivan los aires morenos,\nvivan los morenos aires,\nvivan los de mi morena,\nque son como los de nadie.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00073",4,"Dicen que la reina inglesa\ntiene los cabellos rubios;\ny yo te digo: princesa,\nningunos como los tuyos.",4,0,-1,64,"",0,4,"uo",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00074",4,"Sosas eran en lo antiguo\ntodas las aguas del mar,\npero escupió mi morena,\ny se volvieron salás.",4,0,-1,64,"",0,4,"a",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00075",4,"Las estrellas y luceros\nque salen por el oriente\nlos tengo comparaditos\ncon los rizos de tu frente.",4,0,-1,64,"",0,4,"ee",15,0,-1,0,31,31,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00076",4,"El que muere sin probar\nel querer de una morena,\nse va de este mundo al otro\nsin saber lo que es canela.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,31,31,"","",1,"","","",1,0,0,[],""],["palau_cantares-00077",4,"Bendita sea la madre\nque te parió en este mundo,\npara encanto de los hombres,\ncon ese pelito rubio.",4,0,-1,64,"",0,4,"uo",-1,0,-1,0,31,31,"","",1,"","","",5,0,0,[],""],["palau_cantares-00078",4,"Viva todo lo moreno,\nlo moreno amorenado;\nlo moreno de tu cara\nes lo que más me ha gustado.",4,0,-1,64,"",0,4,"ao",14,0,-1,0,31,31,"","",1,"","","",5,0,0,[],""],["palau_cantares-00079",4,"Con ese pelito rubio\nque te cuelga por la frente\npareces campana de oro\nque va llamando á la gente.",4,0,-1,64,"",0,4,"ee",15,0,-1,0,31,31,"","",1,"","","",4,0,0,[],""],["palau_cantares-00080",4,"De los tres colores, madre,\nlo moreno es lo bonito;\nmorenos fueron los clavos\nque le pusieron á Cristo.",4,0,-1,64,"",0,4,"io",-1,0,-1,0,31,31,"","",1,"","","",1,0,0,[],""],["palau_cantares-00081",4,"El que quisiere á una rubia\nha de dormir al sereno,\nque no se gana una rubia\ncon las manos en el seno.",4,0,-1,64,"",1,4,"eo",76,0,-1,0,31,31,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00082",4,"Yo soy blanco, y te diré\nla causa de estar moreno:\nestoy adorando á un sol\ny con sus rayos me quemo.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00083",4,"Unos dicen que lo blanco\ny otros dicen que lo negro;\notros que lo colorado,\nyo digo que lo moreno.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00084",4,"Todas las morenas son\ndulces como el caramelo,\ny yo, como soy goloso,\npor una morena muero.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,31,31,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00085",4,"En la soledad del campo\nme puse á considerar\nlos pesos duros que vale\nuna morena con sal.",4,0,-1,64,"",0,4,"a",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00086",4,"Moreno pintan á Cristo,\nmorena á la Magdalena,\nmoreno es el bien que adoro,\n¡viva la gente morena!",4,0,-1,64,"",0,4,"ea",59,0,-1,0,31,31,"","",1,"frenk_t1, machado_venezuela, andina_t1, lafuente_madrid, fernan_caballero, huambachano","","",10,0,0,[],""],["palau_cantares-00087",4,"Una morena se vende:\ndicen los apreciadores\nque la sal de una morena\nno se paga con doblones",4,0,-1,64,"",0,4,"oe",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00088",4,"Moreno es el bien que adoro,\npor eso lo quiero tanto,\nporque la tierra morena\nse señorea en el campo.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,31,31,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00089",4,"Vale más lo moreno\nde mi morena\nque toda la blancura\nde la azucena.",4,0,-1,64,"",6,4,"ea",59,0,-1,0,32,32,"","",1,"rm_t2, carrizo_salta, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00090",4,"Morena tiene que ser\nla tierra para ser buena,\ny la mujer para el hombre\ntambién ha de ser morena.",4,0,-1,64,"",0,4,"ea",59,0,-1,0,32,32,"","",1,"rm_t2, carrizo_salta, murciano_antiguo","","",9,0,0,[],""],["palau_cantares-00091",4,"No importa, niña, que seas\nmorenita de color\nsi tienes en esa cara\ntoda la gracia de Dios.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,32,32,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00092",4,"Lo moreno lo hizo Dios,\nlo blanco lo hizo un platero:\ntome lo blanco el que quiera\nyo por lo moreno muero.",4,0,-1,64,"",0,4,"eo",38,0,-1,0,32,32,"","",1,"rm_t2","","",6,0,0,[],""],["palau_cantares-00093",4,"En pasando mi morena\ntropieza el que va detrás,\nque va llenando la calle\nde terroncitos de sal.",4,0,-1,64,"",0,4,"a",-1,0,-1,0,32,32,"","",1,"","","",2,0,0,[],""],["palau_cantares-00094",4,"Viva todo lo moreno,\nlo moreno de buen aire:\nlo digo porque me toca\nde lo morenito parte.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,32,32,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00095",4,"Morenita, morenita,\ndame de tu morenura:\nmás vale de ti la gracia\nque de muchas la hermosura",4,0,-1,64,"",0,4,"ua",17,0,-1,0,32,32,"","",1,"","","",2,0,0,[],""],["palau_cantares-00096",4,"Es mi amante morenito\ncomo el triguito tremés\nque hace el pan obscurito,\ngustosito de comer.",4,0,-1,64,"",0,4,"e",-1,0,-1,0,32,32,"","",1,"","","",2,0,0,[],""],["palau_cantares-00097a",4,"Viva todo lo moreno,\nlo moreno es lo mejor,\nque en el jardín de Cupido\nlo moreno es una flor.",4,0,-1,64,"",0,4,"o",72,0,-1,0,32,32,"","",1,"","","",5,0,0,[],""],["palau_cantares-00097b",4,"- Estrella, sol y luna,\nsal á la calle.\n- Lucero, no me deja\nsalir mi madre.",4,0,-1,64,"",6,4,"ae",-1,0,-1,0,32,32,"","",1,"","","",2,0,0,[],""],["palau_cantares-00097c",4,"Estrellas y luceros\nvan con la luna,\npero como tu cara'\nno va ninguna.",4,0,-1,64,"",6,4,"ua",56,0,-1,0,32,32,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00097d",4,"La luna por el cielo\nva serenita;\nasí va por la calle\nmi morenita.",4,0,-1,64,"",6,4,"ia",50,0,-1,0,32,32,"","",1,"rm_t2, carrizo_salta","","",3,0,0,[],""],["palau_cantares-00098",4,"Yo nací en Sierra Morena\ny á una morenita quiero:\nlo moreno es de mi gusto,\nyo por lo moreno muero",4,0,-1,64,"",0,4,"eo",38,0,-1,0,32,32,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00098-e2",4,"No te quiero por bonita,\nque bonita no lo eres;\nte quiero por morenita\ny por la gracia que tienes.",4,0,-1,64,"",0,4,"ee",-1,0,-1,0,32,32,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00098-e3",4,"Con la sal que derrama\nuna morena\nse mantiene una blanca\nsemana y media.\nViva el salero,\nviva la sal graciosa\nde lo moreno.",4,0,-1,64,"",4,7,"eo",-1,0,-1,0,32,32,"","",1,"","","",1,0,0,[],""],["palau_cantares-00099",4,"Morena es la cebada,\nmoreno el trigo,\nmoreno es el espejo\nen que me miro.",4,0,-1,64,"",6,4,"io",-1,0,-1,0,32,32,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00100",4,"Mi moreno es tan moreno\nque ya parece gitano,\npero tiene á puñadicos\nla sal molida en los labios.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,32,32,"","",1,"","","",2,0,0,[],""],["palau_cantares-00101",4,"Morena tiene que ser\nla tierra para claveles\ny la mujer para el hombre\nmorenita que si quieres.",4,0,-1,64,"",0,4,"ee",-1,0,-1,0,32,32,"","",1,"","","",9,0,0,[],""],["palau_cantares-00102",4,"Los ojos de mi morena\ntienen un mirar extraño,\nque matan en una hora\nmás que la muerte en un año.",4,0,-1,64,"",0,4,"ao",40,0,-1,0,32,32,"","",1,"rm_t2, fernan_caballero","","",23,0,0,[],""],["palau_cantares-00103",4,"A todos los ojos negros\nlos aprisionan mañana:\nbien puedes tú, que los tienes,\nechar empeño á la Sala.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,33,33,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00104",4,"Ojos como los tuyos\nno van al Prado,\nni tampoco salero\ntan resalado.",4,0,-1,64,"",6,4,"ao",14,0,-1,0,33,33,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00105",4,"Son tus ojos dos luceros,\ntu boca un clavel de mayo,\nson tus mejillas dos rosas:\nhazme dueño de ese ramo.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,33,33,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00106",4,"Que Amor busque tus ojos\nno es cosa extraña,\npues como ciego, busca\nlo que le falta.",4,0,-1,64,"",6,4,"aa",-1,0,-1,0,33,33,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00107",4,"Los ojos de mi morena\nson un tren de artillería,\nque nada dejan derecho\ncuando hacen la puntería.",4,0,-1,64,"",0,4,"ia",0,0,-1,0,33,33,"","",1,"rm_t2, lafuente_madrid","","",23,0,0,[],""],["palau_cantares-00108",4,"Tus ojos son ladrones\nque roban y hurtan;\ntus pestañas el monte\ndonde se ocultan.",4,0,-1,64,"",6,4,"ua",-1,0,-1,0,33,33,"","",1,"rm_t2, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00109",4,"Tus ojos tienen la culpa,\ncuando los flechas, indina,\nde que yo tenga este cuerpo\nlo mismo que jaletina.",4,0,-1,64,"",0,4,"ia",11,0,-1,0,33,33,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00110",4,"A tu cara la llaman\nSierra Morena,\ny á tus ojos ladrones\nque andan por ella.",4,0,-1,64,"",6,4,"ea",-1,0,-1,0,33,33,"","",1,"","","",1,0,0,[],""],["palau_cantares-00111",4,"Los ojos de mi morena\nme parecieron ayer\nese lucero que sale\ná eso del amanecer.",4,0,-1,64,"",0,4,"e",20,0,-1,0,33,33,"","",1,"rm_t2, lafuente_madrid","","",23,0,0,[],""],["palau_cantares-00112",4,"Con esos ojos gachones,\nserrana, con que me miras,\nel corazón me lo partes,\ny el alma me la lastimas.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,33,33,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00113a",4,"A la mar, por ser honda,\nse van los ríos,\ny detrás de tus ojos\nse van los míos.",4,0,-1,64,"",6,4,"io",135,0,-1,0,33,33,"","",1,"rm_t2, barcenas_marinera, huambachano","","",5,0,0,[],""],["palau_cantares-00113b",4,"Tienes unos ojillos\nmuy halagüeños,\nporque dan esperanzas\ny no tormentos.",4,0,-1,64,"",6,4,"eo",-1,0,-1,0,33,33,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00113c",4,"Amarillo es el oro,\nblanca la plata,\ny pardos son los ojos\nque á mí me matan.",4,0,-1,64,"",6,4,"aa",-1,0,-1,0,33,33,"","",1,"fernan_caballero","","",5,0,0,[],""],["palau_cantares-00113d",4,"Para pasear tu calle\nno necesito farol;\nson tus ojos dos luceros\nque relumbran más que el sol.",4,0,-1,64,"",0,4,"o",24,0,-1,0,33,33,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00113e",4,"Tus cejas son medias lunas,\ntus ojos son dos luceros,\nque alumbran de noche y día\nmucho más que los del cielo.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,33,33,"","",1,"","","",3,0,0,[],""],["palau_cantares-00114",4,"La luna en el Océano\ncon sus rayos argentinos\nno da tanta luz al mundo\ncomo tus ojos divinos.",4,0,-1,64,"",0,4,"io",206,0,-1,0,33,33,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00114-e2",4,"Son tus ojos dos luceros\npuestos en tan alta estima,\nque en sólo haberlos mirado\nse me ha turbado la vista.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,33,33,"","",1,"rm_t2, lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00114-e3",4,"A la Sala del crimen\nllevé tus ojos,\nporque son dos ladrones\nfacinerosos;\ny cuando entraron\nse ha quejado el Regente\nque le robaron.",4,0,-1,64,"",4,7,"ao",41,0,-1,0,33,33,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-00114-e4",4,"No hay ojos más hermosos\nque son los tuyos,\ny más cuando me miras\ncon disimulo;\ny si los pones\nun poquito adormidos,\n¡caramba, entonces!",4,0,-1,64,"",4,7,"oe",-1,0,-1,0,33,33,"","",1,"","","",3,0,0,[],""],["palau_cantares-00115",4,"Tienes ojos azules,\nojos de gloria,\ny los míos te piden\nmisericordia.",4,0,-1,64,"",6,4,"oa",-1,0,-1,0,34,34,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00116",4,"Tienes cierto no sé qué,\nque me haces perder el tino\ncon el mirar halagüeño\nde tus ojos peregrinos.",4,0,-1,64,"",0,4,"io",-1,0,-1,0,34,34,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00117",4,"Anoche soñaba yo\nque dos negros me mataban;\n¡y eran tus hermosos ojos,\nque enojados me miraban!",4,0,-1,64,"",0,4,"aa",39,0,-1,0,34,34,"","",1,"rm_t2, frenk_t2, lafuente_madrid, fernan_caballero","","",9,0,0,[],""],["palau_cantares-00118",4,"Son tus ojos dos cañones\ncargados de munición,\ny tus palabras son balas\nque pasan mi corazón.",4,0,-1,64,"",0,4,"o",31,0,-1,0,34,34,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00119",4,"A la salida de un carmen\nunos ojos negros vi;\nde quién eran, no lo sé;\nque me cautivaron, sí.",4,0,-1,64,"",0,4,"i",23,0,-1,0,34,34,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00120",4,"Son tus ojos dos señores\njueces de chancillería,\nlos que sentencian el pleito\ny á mí me quitan la vida.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,34,34,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00121",4,"Ojos morenos del alma,\napacibles y risueños,\ndesde el día en que los vi,\nme estoy muriendo por ellos.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,34,34,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00122",4,"Salga el sol, si ha de salir,\ny si no, que nunca salga,\nque para alumbrarme á mí\nla luz de tus ojos basta.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,34,34,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00123",4,"Ojos negros y risueños,\nboquita de serafín,\nestoy soñando contigo\ndesde el día en que te vi.",4,0,-1,64,"",0,4,"i",-1,0,-1,0,34,34,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00124",4,"Para todos en el mundo\nsale el sol por la mañana,\npara mí sale tan sólo\ncuando contemplo tu cara.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,34,34,"","",1,"","","",2,0,0,[],""],["palau_cantares-00125",4,"Toda mi vida en el mar,\nno me cautivaron moros,\ny una vez que entré en tu casa\nme cautivaron tus ojos.",4,0,-1,64,"",0,4,"oo",-1,0,-1,0,34,34,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00126",4,"Con las estrellas del Norte\nse guían los marineros;\nyo me guío con tus ojos,\nque parecen dos luceros.",4,0,-1,64,"",0,4,"eo",22,0,-1,0,34,34,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00127",4,"Tus ojos me cautivaron,\nblanca paloma sin hiel,\ntus ojos me cautivaron,\nque no los moros de Argel.",4,0,-1,64,"",1,4,"e",32,0,-1,0,34,34,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00128",4,"Ojos disimulados\nson los mejores,\nporque logran á tiempo\nlas ocasiones.",4,0,-1,64,"",6,4,"oe",-1,0,-1,0,34,34,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00129",4,"Tienes unos ojitos\nque me los clavas\nen el último centro\nde mis entrañas.",4,0,-1,64,"",6,4,"aa",-1,0,-1,0,34,34,"","",1,"","","",20,0,0,[],""],["palau_cantares-00130",4,"El que estrellas estudia\nve su destino;\ny yo estudio tus ojos\npor ver el mío.",4,0,-1,64,"",6,4,"io",-1,0,-1,0,34,34,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00131",4,"A esos ojillos negros\néchales llave,\nque me matas con ellos\ncuando los abres.",4,0,-1,64,"",6,4,"ae",-1,0,-1,0,34,34,"","",1,"","","",1,0,0,[],""],["palau_cantares-00132",4,"Las estrellas del cielo\nno están cabales,\nporque están en tu cara\nlas principales.",4,0,-1,64,"",6,4,"ae",26,0,-1,0,34,34,"","",1,"rm_t2","","",9,0,0,[],""],["palau_cantares-00133",4,"Los ojos y los labios\nde cierta niña\nson los depositarios\ndel alma mía.",4,0,-1,64,"",6,4,"ia",-1,0,-1,0,34,34,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00134",4,"Las estrellas del cielo\nson mil y siete,\ncon las dos de tu cara\nson mil y nueve.",4,0,-1,64,"",6,4,"ee",-1,0,-1,0,34,34,"","",1,"rm_t2, fernan_caballero","","",9,0,0,[],""],["palau_cantares-00135",4,"Envidia tengo á las flores\nque coronan tu azotea:\nantes que el aire las mueva,\nya tu aliento las orea.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,35,35,"","",1,"","","",1,0,0,[],""],["palau_cantares-00136",4,"Esos ojos gachones\ncon que me miras\ninfunden en mi pecho\ncierta fatiga.",4,0,-1,64,"",6,4,"ia",-1,0,-1,0,37,37,"","",1,"","","",1,0,0,[],""],["palau_cantares-00137",4,"Ojos negros son traidores,\nlos azules embusteros,\nlos ojos acastañados\nson fieles y duraderos.",4,0,-1,64,"",0,4,"eo",22,0,-1,0,37,37,"","",1,"","","",1,0,0,[],""],["palau_cantares-00138",4,"¿Qué tienen esos ojos,\ndime, alma mía,\nque no entiendo si matan\nó si dan vida?",4,0,-1,64,"",6,4,"ia",-1,0,-1,0,37,37,"","",1,"","","",1,0,0,[],""],["palau_cantares-00139",4,"Tienes unos ojitos\nadormilados,\nque es preciso quererlos\ná ojos cerrados.",4,0,-1,64,"",6,4,"ao",18,0,-1,0,37,37,"","",1,"rm_t2, fernan_caballero","","",20,0,0,[],""],["palau_cantares-00140",4,"Tienes unos ojillos\ntan rechuscones,\nque con una mirada\nmatas á un hombre.",4,0,-1,64,"",6,4,"oe",-1,0,-1,0,37,37,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00141",4,"Del cielo de tus ojos\ndí una caída,\nno puedo levantarme\nsi no me miras.\nMe he levantado,\nseñal de que tus ojos\nme habrán mirado.",4,0,-1,64,"",4,7,"ao",14,0,-1,0,37,37,"","",1,"","","",1,0,0,[],""],["palau_cantares-00142a",4,"Si por el mirar matas,\nniña, pregunto:\n¿dónde vas enterrando\ntanto difunto?",4,0,-1,64,"",6,4,"uo",36,0,-1,0,37,37,"","",1,"","","",1,0,0,[],""],["palau_cantares-00142b",4,"Tan cautivo me tienen\ntus dos luceros,\nque aunque busco el rescate\njamás lo encuentro.",4,0,-1,64,"",6,4,"eo",-1,0,-1,0,37,37,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00142c",4,"Manojos de alfileres\nson tus pestañas,\ncada vez que me miras\ntodo me clavas.",4,0,-1,64,"",6,4,"aa",-1,0,-1,0,37,37,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00142d",4,"Tus ojos no son ojos,\nque son saetas:\ncada vez que me miras\nme dejas muerta.",4,0,-1,64,"",6,4,"ea",-1,0,-1,0,37,37,"","",1,"","","",2,0,0,[],""],["palau_cantares-00142e",4,"Cuando Dios creó los cielos\nle sobraron dos estrellas\ny las puso en tu carita\npara alumbrarse con ellas.",4,0,-1,64,"",0,4,"ea",89,0,-1,0,37,37,"","",1,"","","",1,0,0,[],""],["palau_cantares-00142f",4,"Pequeñita es la boca,\nnegros los ojos,\nsuelto y airoso el talle\nde la que adoro.",4,0,-1,64,"",6,4,"oo",-1,0,-1,0,37,37,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00142g",4,"A tus ojos les llaman\nExtremadura,\nporque son extremados\nen hermosura.",4,0,-1,64,"",6,4,"ua",17,0,-1,0,37,37,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00143a",4,"Sólo tus bellos ojos\nhacer pudieron\nque algún día mis ojos\nquedasen ciegos;\npues ciego vivo,\nsé tú, dueño adorado,\nmi lazarillo.",4,0,-1,64,"",4,7,"io",-1,0,-1,0,37,37,"","",1,"preciso_coleccion","","",3,0,0,[],""],["palau_cantares-00143b",4,"Son tus ojos dos negros\ncon arco y flecha,\nque aun dormidos disparan\ny al pecho aciertan:\ndígalo el mío,\nque lo mismo fué verte\nque hallarse herido.",4,0,-1,64,"",4,7,"io",-1,0,-1,0,37,37,"","",1,"","","",3,0,0,[],""],["palau_cantares-00143c",4,"Tus ojos me han rendido,\nporque no puedo\nresistirme al influjo\nde dos luceros:\nsólo les pido\nque ya que son luceros,\nque sean fijos.",4,0,-1,64,"",4,7,"io",-1,0,-1,0,37,37,"","",1,"","","",1,0,0,[],""],["palau_cantares-00143d",4,"El objeto adorado\nde mis desvelos\nson tus ojos divinos,\nluz de los cielos;\ny brillan tanto,\nque me quitan la vista\nsin dar quebranto.",4,0,-1,64,"",4,7,"ao",30,0,-1,0,37,37,"","",1,"","","",2,0,0,[],""],["palau_cantares-00144",4,"Luego que vi tus ojos,\ndije á los míos:\nya tenemos al frente\nlos enemigos;\nrespondió el alma:\nya nos han sorprendido\nlas avanzadas.",4,0,-1,64,"",4,7,"aa",-1,0,-1,0,38,38,"","",1,"","","",1,0,0,[],""],["palau_cantares-00145",4,"La cosa que yo quiero\nmás que á mi vida\nson tus dos ojos negros\nque me asesinan:\nhe de mirarte,\ny con tal que me mires\naunque me mates.",4,0,-1,64,"",4,7,"ae",-1,0,-1,0,38,38,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00146",4,"En el anchuroso mar\nnavegando me perdí,\ny con la luz de tus ojos\nun puerto de España vi.",4,0,-1,64,"",0,4,"i",23,0,-1,0,38,38,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00147",4,"Es tu cara lo mismo\nque luna blanca,\ny tus ojos luceros\nque la acompañan.",4,0,-1,64,"",6,4,"aa",-1,0,-1,0,38,38,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00148",4,"Tienes unos ojos, niña,\nque si los dieras á censo,\nno faltara quien te diera\nun veinticinco por ciento.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,38,38,"","",1,"rm_t2, lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00149",4,"Yo no sé lo que tienes\nen tus ojuelos,\nque cuanto más los miro,\nmás gana tengo;\nporque al mirarlos\nbien sé yo lo que siento,\npero lo callo.",4,0,-1,64,"",4,7,"ao",-1,0,-1,0,38,38,"","",1,"","","",2,0,0,[],""],["palau_cantares-00150",4,"Tienes unos ojos, niña,\ntan hechos á la humildad,\nque cuando vas por la calle,\npareces la Soledad.",4,0,-1,64,"",0,4,"a",16,0,-1,0,38,38,"","",1,"rm_t2, lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00150-e2",4,"Todos los aragoneses\nhan salido de Aragón\nen busca de unos ladrones:\nmorena, tus ojos son.",4,0,-1,64,"",0,4,"o",31,0,-1,0,38,38,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00150-e3",4,"Tus ojos, bella paloma,\nllevan pleito con el sol;\nporque el sol es uno solo,\ntus ojos dos soles son.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,38,38,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00150-e4",4,"Tus ojos son de esmeralda\ny tu boca de carmín;\nson tus mejillas dos rosas\nque se comienzan á abrir.",4,0,-1,64,"",0,4,"i",-1,0,-1,0,38,38,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00150-e5",4,"Son tus ojos dos espejos;\nen ellos me miro yo.\n¡No los cierres, que me matas!\n¡No los cierres, ábrelos!",4,0,-1,64,"",5,4,"ao",-1,0,-1,0,38,38,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00150-e6",4,"Tienes unos ojitos\nde picaporte,\ncada vez que los cierras\nsiento yo un golpe.\nÉchales llave,\nporque me mortificas\ncuando los abres.",4,0,-1,64,"",4,7,"ae",-1,0,-1,0,38,38,"","",1,"","","",20,0,0,[],""],["palau_cantares-00151a",4,"Yo no sé lo que siento\ncuando te miro,\nque suspiro y no acierto\npor qué suspiro;\ny sólo siento\nque acá dentro del alma\nme dan tormento.",4,0,-1,64,"",4,7,"eo",94,0,-1,0,38,38,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00151b",4,"Corre al espejo, niña,\nmira tus ojos,\nque el sol de mediodía\nno es más hermoso.\nMucho lo siento,\npues de tus ojos nacen\nmis sufrimientos.",4,0,-1,64,"",4,7,"eo",-1,0,-1,0,38,38,"","",1,"","","",1,0,0,[],""],["palau_cantares-00151c",4,"Tienen tus dulces ojos\ntan bellas niñas,\nque sólo por mirarlas\nperdí las mías;\ny no pondero,\nque por haberlas visto\nquedé yo ciego.",4,0,-1,64,"",4,7,"eo",-1,0,-1,0,38,38,"","",1,"","","",2,0,0,[],""],["palau_cantares-00151d",4,"Tus ojos son dos tinteros;\ntu nariz, pluma cortada;\ntus dientes, letra menuda;\ntu boca, carta cerrada.",4,0,-1,64,"",0,4,"aa",49,0,-1,0,38,38,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00152",4,"Tienes unos ojos, niña,\nmás negros que el azabache,\ny una carita más blanca\nque la leche que mamaste.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,39,39,"","",1,"rm_t2, lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00153",4,"Los ojos de mi niña\nson de pan tierno,\ny los míos de hambre\nse están muriendo.",4,0,-1,64,"",6,4,"eo",-1,0,-1,0,39,39,"","",1,"rm_t2, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00154",4,"Unos ojos negros vi,\ny dije: ¡válgame el cielo!\n¡Tanto luto para mí!\nNo sé cómo no me muero.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,39,39,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00155",4,"Tienes unos ojitos\nde alcalde mayor,\nque sentencian á muerte\nsin apelación.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,39,39,"","",1,"rm_t2","","",20,0,0,[],""],["palau_cantares-00156",4,"Al campo de tu frente\nsalí á pasear,\nme prendieron dos negros\ndel mismo lugar;\nfueron dos negros...,\n¡ay Jesús!, niña mía,\ntus ojos fueron.",4,0,-1,64,"",4,7,"eo",-1,0,-1,0,39,39,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00157",4,"Unos ojillos negros\nme han cautivado.\n¡Quién dirá que morenos\ncautivan blancos!",4,0,-1,64,"",6,4,"ao",-1,0,-1,0,39,39,"","",1,"","","",2,0,0,[],""],["palau_cantares-00158a",4,"Ni son chicos, ni son grandes\nlos ojos de mi amadora;\nson como quesos de Flandes,\nque entran dos en cada arroba.",4,0,-1,64,"",0,4,"oa",-1,0,-1,0,39,39,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00158b",4,"Tienes ojos de paloma,\ncarita de leche y sangre,\ny los cabellitos rubios,\ncomo la Virgen del Carmen.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,39,39,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00158c",4,"Esos ojitos azules\nse los has robado al cielo,\ny al cielo le darás cuenta\ndel mal que hiciste con ellos.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,39,39,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00158d",4,"Los ojos de mi morena\nson lo mismo que mis males:\ngrandes como mis fatigas,\nnegros como mis pesares.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,39,39,"","",1,"lafuente_madrid","","",23,0,0,[],""],["palau_cantares-00159a",4,"Al mirarme tus ojos,\nbajo los míos,\nque tus ojos abrasan\nmás que el estío.",4,0,-1,64,"",6,4,"io",-1,0,-1,0,39,39,"","",1,"rm_t2, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00159b",4,"Si me miras, me matas;\nsi no, me muero:\nmírame, vida mía,\nque morir quiero.",4,0,-1,64,"",6,4,"eo",38,0,-1,0,39,39,"","",1,"rm_t2, carrizo_salta","","",3,0,0,[],""],["palau_cantares-00159c",4,"Dicen que espinan tus manos:\npara mí son amorosas,\nmás espinan los rosales\ny se les cortan las rosas.",4,0,-1,64,"",0,4,"oa",61,0,-1,0,39,39,"","",1,"","","",2,0,0,[],""],["palau_cantares-00159d",4,"De los juncos sale el agua,\nde los álamos el viento,\ny de ti, dama pulida,\nmemoria y entendimiento.",4,0,-1,64,"",0,4,"eo",94,0,-1,0,39,39,"","",1,"","","",4,0,0,[],""],["palau_cantares-00159e",4,"Mozuelas murmuradoras\nque todo lo murmuráis,\nno murmuréis de esta rosa,\nmirad que la deshojáis.",4,0,-1,64,"",0,4,"a",394,0,-1,0,39,39,"","",1,"","","",1,0,0,[],""],["palau_cantares-00160",4,"Por la Sierra Morena\nvienen bajando\nunos ojillos negros\nde contrabando.",4,0,-1,64,"",6,4,"ao",33,0,-1,0,39,39,"","",1,"","","",4,0,0,[],""],["palau_cantares-00162",4,"De tus hermosos ojos\nno tengo queja,\nque ellos quieren mirarme,\ntú no los dejas.",4,0,-1,64,"",6,4,"ea",-1,0,-1,0,39,39,"","",1,"","","",5,0,0,[],""],["palau_cantares-00163",4,"Mi amante viste á lo majo\ny en la cintura se pone\nuna fajita grosella\nque roba los corazones.",4,0,-1,64,"",0,4,"oe",-1,0,-1,0,39,39,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00164",4,"Que en el cielo hay ladrones\nno dude nadie,\nporque á mí me ha robado\nla vida un ángel.",4,0,-1,64,"",6,4,"ae",-1,0,-1,0,40,40,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00164-e10",4,"Salero, viva el salero,\nsalero, viva la sal,\nque tiene usted más salero\nque el salero universal.",4,0,-1,64,"",1,4,"a",1,0,-1,0,40,40,"","",1,"","","",6,0,0,[],""],["palau_cantares-00164-e2",4,"Aunque seas chiquitita,\ná mí no me da cuidado,\nporque el árbol chiquitito\ncría fruto regalado.",4,0,-1,64,"",0,4,"ao",14,0,-1,0,40,40,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00164-e3",4,"Aunque vives en rincón,\nno vives arrinconada,\nque en los rincones se crían\nlas mejores ensaladas.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,40,40,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00164-e4",4,"De dos hermanas que son\nno hay diferencia ninguna:\nes la una como el sol,\nla otra como la luna.",4,0,-1,64,"",0,4,"ua",56,0,-1,0,40,40,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00164-e5",4,"Señor alcalde mayor,\nno prenda usté á los ladrones,\nporque tiene usté una hija\nque roba los corazones.",4,0,-1,64,"",0,4,"oe",34,0,-1,0,40,40,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",8,0,0,[],""],["palau_cantares-00164-e6",4,"En la corte de Madrid,\nsalada, vi tu retrato;\nera un cuerpo tan gentil,\nque hiciera pecar á un santc,",4,0,-1,64,"",5,4,"a",-1,0,-1,0,40,40,"","",1,"","","",2,0,0,[],""],["palau_cantares-00164-e7",4,"En la mar se crían peces,\ny en la orilla caracoles,\ny en el jardín de mi dama\nclavellinas á montones,",4,0,-1,64,"",0,4,"oe",-1,0,-1,0,40,40,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00164-e8",4,"Eres paloma torcaz\ny tórtola en el arrullo,\npor dondequiera que vas\nno hay salero como el tuyo.",4,0,-1,64,"",1,4,"uo",78,0,-1,0,40,40,"","",1,"","","",2,0,0,[],""],["palau_cantares-00164-e9",4,"¡Salero, viva el salero,\ncarita de serafín!\n¡Cuántas horitas de sueño\ntengo perdidas por ti!",4,0,-1,64,"",0,4,"i",-1,0,-1,0,40,40,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00165",4,"Vivan las mozas juncales,\nque se pasean con rumbo,\nlas que quieren sus amantes\ncon el salero del mundo.",4,0,-1,64,"",0,4,"uo",-1,0,-1,0,40,40,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00165-e2",4,"Eres perla de las perlas,\nlucero de los luceros,\neres palma de las palmas,\nsalero de los saleros.",4,0,-1,64,"",0,4,"eo",22,0,-1,0,40,40,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00165-e3",4,"Tienes, niña, en tus labios\ndos clavelitos;\néchales agua fresca,\nque están marchitos;\npero si quieres,\nme darás la licencia\nde que los riegue.",4,0,-1,64,"",4,7,"ee",-1,0,-1,0,40,40,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00165-e4",4,"En tu abanico, niña,\nquiero pintarte,\npara que tu retrato\nte dé algún aire;\npues no hay pintor\nque dibuje con aire,\ngracia y primor.",4,0,-1,64,"",4,7,"o",72,0,-1,0,40,40,"","",1,"","","",2,0,0,[],""],["palau_cantares-00165-e5",4,"Tienes tal atractivo\ncon tu modestia,\nque todo el que te mira\nprendado queda;\ny así se advierte\nque cuantos te conocen\ntodos te quieren.",4,0,-1,64,"",4,7,"ee",-1,0,-1,0,40,40,"","",1,"","","",2,0,0,[],""],["palau_cantares-00165-e6",4,"El templo de tu imagen\ntantos veneran,\nque á competencia todos\nperfumes queman:\ncruzando mares\nllegan, pues, á rendirte\nsus estandartes.",4,0,-1,64,"",4,7,"ae",-1,0,-1,0,40,40,"","",1,"","","",1,0,0,[],""],["palau_cantares-00165-e7",4,"Más hermosa eres que el sol\ncuando sus rayos dispara,\nmás hermosa que la luna\ncuando va serena y clara.",4,0,-1,64,"",0,4,"aa",57,0,-1,0,40,40,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00165-e8",4,"El sol se quedó eclipsado,\nenternecido de amores;\ncuando el sol se ha enamorado,\nniña, ¿qué serán los hombres?",4,0,-1,64,"",0,4,"oe",-1,0,-1,0,40,40,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00166",4,"En la ciudad de Alicante,\nniña, me acordé de ti,\nque relumbraba una estrella\ny se parecía á ti.",4,0,-1,64,"",0,4,"i",-1,0,-1,0,41,41,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00167",4,"Eres Valle en lo bonita,\ny en lo garbosa Dolores,\ny en lo lozana y alegre\neres un ramo de flores.",4,0,-1,64,"",3,4,"oe",5,0,-1,0,41,41,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00168",4,"Las estrellas he contado,\ny la del Norte aparté,\ny por ser la más hermosa,\ncontigo la comparé.",4,0,-1,64,"",0,4,"e",77,0,-1,0,41,41,"","",1,"","","",5,0,0,[],""],["palau_cantares-00169",4,"De lo más alto del cielo\ncayeron nueve claveles,\ntres Anas y tres Marías,\ntres pulidas Isabeles.",4,0,-1,64,"",0,4,"ee",97,0,-1,0,41,41,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00170",4,"Eres hermana del sol,\nprima hermana de la luna,\nsobrina del alabastro,\ndel alba prima segunda.",4,0,-1,64,"",0,4,"ua",-1,0,-1,0,41,41,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00171",4,"De la raíz de la palma\nnacieron las Isabeles,\ndelgaditas de cintura,\ny de corazón alegres.",4,0,-1,64,"",0,4,"ee",-1,0,-1,0,41,41,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00172",4,"La luna clara salió,\ny viendo que le ganabas,\ntras un nublo se metió\ncorrida y avergonzada.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,41,41,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00173",4,"Cuando te pusieron Ana\nestaba borracho el cura,\nporque debieron ponerte\nramillete de hermosura.",4,0,-1,64,"",0,4,"ua",17,0,-1,0,41,41,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00174",4,"¡Qué linda moza te has hecho,\nqué alta y qué gallardona!\nEl mismo rey coronado\nse merece tu persona.",4,0,-1,64,"",0,4,"oa",7,0,-1,0,41,41,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00175",4,"Viva todo lo serrano,\nque por lo serrano muero,\nporque serranito soy\ny á una serrana camelo.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,41,41,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00176",4,"Eres reina y más que reina,\nen lo dicho me mantengo,\ndesde la punta del pie\ná la punta del cabello.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,41,41,"","",1,"","","",3,0,0,[],""],["palau_cantares-00177",4,"Vivan los cuerpos variles,\nviva la murmuración,\ny también digo que viva\ntu salero, Encarnación.",4,0,-1,64,"",0,4,"o",31,0,-1,0,41,41,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00178",4,"A la luz del cigarro\nte vi la cara,\nno he visto clavellina\nmás encarnada.",4,0,-1,64,"",6,4,"aa",-1,0,-1,0,41,41,"","",1,"rm_t2, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00179",4,"Tienes cuello de marfil,\ncinturita de campana;\ncatorce leguas de aquí\ntiene tu hermosura fama.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,41,41,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00180",4,"Viva el lujo y quien lo trujo,\ny también quien lo mantiene,\ny también digo que viva\nel salero y quien lo tiene.",4,0,-1,64,"",0,4,"ee",70,0,-1,0,41,41,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00181",4,"Dicen que la golondrina\ntiene la pechuga blanca,\ny mi serranilla tiene\nla pechuga y la garganta.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,41,41,"","",1,"rm_t2, lafuente_madrid, suspiros_amor","","",12,0,0,[],""],["palau_cantares-00182",4,"Cuando en ancas de mi potro\nyo te lleve á Gibraltar,\ndirán los mozos al verte:\n¡ay qué moza tan salá!",4,0,-1,64,"",0,4,"a",-1,0,-1,0,41,41,"","",1,"","","",2,0,0,[],""],["palau_cantares-00183",4,"Con la luz te he comparado,\n¡mira qué comparación!,\nque sin la luz no se puede\ndecir la misa mayor.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,41,41,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00184",4,"Para guisar esta liebre\nsólo me falta la sal:\nusted, que de sobra tiene,\n¿me la quiere usted prestar?",4,0,-1,64,"",0,4,"a",-1,0,-1,0,41,41,"","",1,"","","",3,0,0,[],""],["palau_cantares-00185",4,"Tan sólo en el mundo hay una\ncon quien poder compararte,\ny la encontré por fortuna\npintada en un estandarte.",4,0,-1,64,"",1,4,"ae",8,0,-1,0,41,41,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00186",4,"Una guinda partida\nson tus dos labios,\npintura más galana\nque hagan los sabios.",4,0,-1,64,"",6,4,"ao",45,0,-1,0,42,42,"","",1,"","","",1,0,0,[],""],["palau_cantares-00187",4,"Eres chiquita y bonita,\neres como yo te quiero,\npareces campanillita\nhecha á mano de un platero.",4,0,-1,64,"",1,4,"eo",38,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid","","",12,0,0,[],""],["palau_cantares-00188",4,"Con ese pie pulidito\ny ese modito de andar\ntiene usted más hombres muertos\nque arenas tiene la mar.",4,0,-1,64,"",0,4,"a",21,0,-1,0,42,42,"","",1,"","","",3,0,0,[],""],["palau_cantares-00189",4,"Échame, niña bonita,\nlágrimas en un pañuelo,\ny las llevaré á Granada\nque las engarce un platero.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00190",4,"Con ese delantal blanco\ny esas naguas de indianilla\nel corazón me has robado,\npícara retrecherilla.",4,0,-1,64,"",0,4,"ia",162,0,-1,0,42,42,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00191",4,"Tienes una boca, niña,\ncomo un capullo cerrado;\nde buena gana lo abriera\ncon el soplo de mis labios.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00192",4,"La campana de la Vela\nno tiene tanta balumba\ncomo tienes tú, morena,\ncon ese cuerpo sandunga.",4,0,-1,64,"",0,4,"ua",-1,0,-1,0,42,42,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00193",4,"Los dientes de tu boquita\nme tienen cautivo y preso;\nen mi vida he visto yo\ncadenas hechas de hueso.",4,0,-1,64,"",0,4,"eo",48,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid, suspiros_amor","","",6,0,0,[],""],["palau_cantares-00194",4,"Yo pensé que era la luna\nla que estaba en el balcón,\ny salió la capitana\nde Navarra y Aragón.",4,0,-1,64,"",0,4,"o",31,0,-1,0,42,42,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00195",4,"De todas las de tu calle\neres tú la más hermosa:\n¿cómo no pones bandera,\ncapitana generosa?",4,0,-1,64,"",0,4,"oa",63,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00196",4,"La luz del amanecer,\nal verte, se quedó tibia,\ny atrás se quiso volver\nporque le has causado envidia.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00197",4,"Quien te dió por nombre Paca\nno te supo poner nombre,\nque debió de haberte puesto\nla perdición de los hombres.",4,0,-1,64,"",0,4,"oe",-1,0,-1,0,42,42,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00198",4,"¿Cómo quieres que el sol salga,\nsi lo tienes en prisiones,\nhasta que tú te levantes\ny á la ventana te asomes?",4,0,-1,64,"",0,4,"oe",-1,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00199",4,"María sé que te llamas,\ny por apellido Luna:\nalúmbrame con tus rayos,\nporque está la noche obscura.",4,0,-1,64,"",0,4,"ua",-1,0,-1,0,42,42,"","",1,"","","",6,0,0,[],""],["palau_cantares-00200",4,"Por los colores de rosa\nque tienes cuando te veo,\npor lo mismo, niña hermosa,\nen el corazón te llevo.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,42,42,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00201",4,"Dolores, flor de las flores,\nmaravilla de las Indias,\ncara de quitapesares,\nramillete de celindas.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,42,42,"","",1,"","","",2,0,0,[],""],["palau_cantares-00202",4,"De la rama de un espino\nvi yo salir un clavel,\nporque le tocó mi niña\ncon la puntilla del pie.",4,0,-1,64,"",0,4,"e",-1,0,-1,0,42,42,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00203",4,"Hazme, María, una torta,\naunque sea de centeno,\nporque en siendo de tu mano,\nse volverá trigo bueno.",4,0,-1,64,"",0,4,"eo",76,0,-1,0,42,42,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00204",4,"Eres como la avellana,\nchiquita y llena de carne,\nchiquita y apañadita,\ncomo te quiere tu amante.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,42,42,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00205",4,"En el vasar hay un vaso,\ny en el vaso una bebida,\nen la bebida una rosa,\ny en la rosa una María.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,42,42,"","",1,"","","",1,0,0,[],""],["palau_cantares-00206",4,"Entre los árboles todos\nse señorea el laurel,\nentre las mujeres Ana,\ny entre flores el clavel.",4,0,-1,64,"",0,4,"e",32,0,-1,0,45,45,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00207",4,"Tengo yo comparado,\nniña, tu rostro\ncon la luna de enero\ny el sol de agosto.",4,0,-1,64,"",6,4,"oo",-1,0,-1,0,45,45,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00208",4,"Toda la calle Mayor\nhe venido preguntando\ndónde habita la hermosura,\ny aquí me han encaminado.",4,0,-1,64,"",3,4,"ao",-1,0,-1,0,45,45,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00209",4,"El día que tú naciste\n¡qué triste quedara el sol\nal ver que otro sol salía\ncon mucho más resplandor!",4,0,-1,64,"",0,4,"o",-1,0,-1,0,45,45,"","",1,"","","",16,0,0,[],""],["palau_cantares-00210",4,"Eres delgada de talle,\ncomo junco de ribera:\nde las niñas de tu calle\ntú te llevas la bandera.",4,0,-1,64,"",1,4,"ea",44,0,-1,0,45,45,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00211",4,"El naranjo de tu patio,\ncuando te acercas á él,\nse desprende de sus flores\ny te las echa á los pies.",4,0,-1,64,"",0,4,"e",-1,0,-1,0,45,45,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00212a",4,"Delgadita de cintura,\ncomo junco marinero,\nni eres alta, ni eres baja,\nque eres como yo te quiero.",4,0,-1,64,"",0,4,"eo",38,0,-1,0,45,45,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00212b",4,"Tienes una cinturita\nque parece contrabando:\nyo, como contrabandista,\npor ella vengo penando.",4,0,-1,64,"",0,4,"ao",33,0,-1,0,45,45,"","",1,"rm_t2, lafuente_madrid","","",14,0,0,[],""],["palau_cantares-00212c",4,"Tienes una cinturita\ntan delgada, que parece\nun clavel en la maceta,\nque con el aire se mece.",4,0,-1,64,"",0,4,"ee",64,0,-1,0,45,45,"","",1,"lafuente_madrid","","",14,0,0,[],""],["palau_cantares-00212d",4,"Eres hermosa y tienes\nmala fortuna;\n¡siempre va la desgracia\ncon la hermosura!",4,0,-1,64,"",6,4,"ua",-1,0,-1,0,45,45,"","",1,"","","",1,0,0,[],""],["palau_cantares-00212e",4,"Morenita agraciada,\nquítate el manto;\nno por ser agraciada\nte tapes tanto.",4,0,-1,64,"",6,4,"ao",30,0,-1,0,45,45,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00212f",4,"Con la luz te comparo,\n¡mira qué dicha!\nSin la luz no se puede\ncelebrar misa.",4,0,-1,64,"",6,4,"ia",-1,0,-1,0,45,45,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-00212g",4,"Con la luna de enero\nte he comparado,\nque es la luna más clara\nde todo el año.",4,0,-1,64,"",6,4,"ao",-1,0,-1,0,45,45,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00213a",4,"Tus colchones son jazmines,\ny tus sábanas mosquetas,\nazucena tu almohada,\ny tú rosa que te acuestas.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,45,45,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00213b",4,"Rosa, clavellina y dalia\nme has parecido al mirarte,\ny también me has parecido\nperla engastada en diamantes.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,45,45,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00213c",4,"Eres mosqueta olorosa,\neres el fresco jazmín,\neres la rosa fragante\nen la floresta de abril.",4,0,-1,64,"",0,4,"i",-1,0,-1,0,45,45,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00213d",4,"Eres el mejor clavel\nde las orillas del Darro,\nque se abrió con el rocío\nde las mañanas de mayo.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,45,45,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00213e",4,"Eres la palma gallarda\ny hermosísimo laurel,\neres azucena blanca\ny bellísimo clavel.",4,0,-1,64,"",0,4,"e",32,0,-1,0,45,45,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00213f",4,"Al pasar por tu puerta\nvi pelearse\ndos piedras, pretendiendo\nque las pisases;\nyo dije entonces:\nsi hacen esto las piedras,\n¿qué harán los hombres?",4,0,-1,64,"",4,7,"oe",-1,0,-1,0,45,45,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00214",4,"Esos zapatos blancos\nque llevas, Juana,\n¿cómo con ellos pisas\nque no los manchas?\nY ella responde:\nes porque voy pisando\nlos corazones.",4,0,-1,64,"",4,7,"oe",-1,0,-1,0,46,46,"","",1,"","","",2,0,0,[],""],["palau_cantares-00214-e2",4,"Ande usted, prenda morena,\ncabellos de soberana,\ncuerpecito malagueño,\ncintura de valenciana.",4,0,-1,64,"",0,4,"aa",4,0,-1,0,46,46,"","",1,"","","",1,0,0,[],""],["palau_cantares-00214-e3",4,"Ande usté, almacén de gracia,\ncuerpo de corregidora:\nsi yo fuera rey de Holanda,\nle pusiera una corona.",4,0,-1,64,"",0,4,"oa",-1,0,-1,0,46,46,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00214-e4",4,"Los ángeles te coronen,\ny te lleven á la gloria,\ny te pongan á los pies\nde la Divina Pastora.",4,0,-1,64,"",0,4,"oa",-1,0,-1,0,46,46,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00214-e5",4,"No te diré sol ni luna,\npero te diré diamante;\nque la luna crece y mengua,\ny en ti no cabe menguante.",4,0,-1,64,"",0,4,"ae",47,0,-1,0,46,46,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00214-e6",4,"Si la luna no menguara,\nte comparara con ella;\npero te compararé\ncon el sol y las estrellas.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,46,46,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00214-e7",4,"Enfrente del sol saliente\ntiene mi niña el balcón:\nsale el sol, sale mi niña,\nsalen mi niña y el sol.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,46,46,"","",1,"fernan_caballero","","",2,0,0,[],""],["palau_cantares-00214-e8",4,"El marco de tu ventana\ntodo está lleno de estrellas,\ny así que te asomas tú,\nsale el sol y se van ellas.",4,0,-1,64,"",0,4,"ea",89,0,-1,0,46,46,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00214-e9",4,"Sale el sol por la mañana\ny obscurece las estrellas;\ny tú obscureces al sol\ncuando sales á tu puerta.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,46,46,"","",1,"","","",5,0,0,[],""],["palau_cantares-00215a",4,"Serrana, tu perfección\nla dibujé con tal arte,\nque la luna se eclipsó\ny el sol se paró á mirarte.",4,0,-1,64,"",0,4,"ae",8,0,-1,0,46,46,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00215b",4,"Si quieres que salga el sol\ntres horas antes del día,\nvete á la plaza Mayor\ny pregunta por María.",4,0,-1,64,"",0,4,"ia",0,0,-1,0,46,46,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00215c",4,"Si te digo sol, te ofendo;\ny si luna, te maltrato;\ny si te digo lucero,\nme parece que te mato.",4,0,-1,64,"",0,4,"ao",19,0,-1,0,46,46,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00215d",4,"Te comparo con la luna,\ncon el sol y los luceros,\ny si no fuera pecado,\ncon la Reina de los cielos.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,46,46,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00215e",4,"Al sol de los siete soles\ny á la luna de Aragón\ncomparo yo tus colores\ncuando sales al balcón.",4,0,-1,64,"",0,4,"o",31,0,-1,0,46,46,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00215f",4,"Si el hoyo de tu barba\nfuera pilita,\nmás de cuatro tomaran\nagua bendita.",4,0,-1,64,"",6,4,"ia",50,0,-1,0,46,46,"","",1,"rm_t2, suspiros_amor","","",3,0,0,[],""],["palau_cantares-00215g",4,"Ese lunar que tienes\njunto á la boca,\nno se lo des á nadie,\nque á mí me toca.",4,0,-1,64,"",6,4,"oa",178,0,-1,0,46,46,"","",1,"","","",3,0,0,[],""],["palau_cantares-00215h",4,"De marfil torneado\ntienes el pecho,\ny con venas azules\nde trecho en trecho.",4,0,-1,64,"",6,4,"eo",60,0,-1,0,46,46,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00215i",4,"En el hoyo de tu barba\npuse una confitería,\nlos angelitos del cielo\npor caramelos venían.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,46,46,"","",1,"rm_t2","","",7,0,0,[],""],["palau_cantares-00215j",4,"El encarnado clavel\nviene publicando agravios,\nporque no le han hecho á él\nhermoso como tus labios.",4,0,-1,64,"",1,4,"ao",45,0,-1,0,46,46,"","",1,"","","",3,0,0,[],""],["palau_cantares-00216",4,"Del color y del brillo\nde los rubíes\ntienes, niña, los labios\ncuando te ríes.",4,0,-1,64,"",6,4,"ie",499,0,-1,0,47,47,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00217",4,"Desde que te vi, morena,\nal andar, tu lindo pie,\nme relamo yo la boca\ncomo si tuviera miel.",4,0,-1,64,"",0,4,"e",-1,0,-1,0,47,47,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00218",4,"A tus labios rosados,\ndivina diosa,\nvan á buscar almíbar\nlas mariposas.\nDame licencia\nde que gocen los míos\nla preferencia.",4,0,-1,64,"",4,7,"ea",46,0,-1,0,47,47,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00219",4,"Eres alta y delgada,\ncenceña y lisa,\neres como la vara\nde la Justicia.",4,0,-1,64,"",6,4,"ia",-1,0,-1,0,47,47,"","",1,"rm_t2, carrizo_salta","","",4,0,0,[],""],["palau_cantares-00220a",4,"Ole con ole, con ole,\nole con ole, salero,\nfatigas me dan de muerte\ncuando veo un cuerpo bueno.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,47,47,"","",1,"","","",7,0,0,[],""],["palau_cantares-00220b",4,"Ese garbo y hermosura\ny ese rostro tan salado\nlos comparo, vida mía,\ncon las rositas de mayo.",4,0,-1,64,"",0,4,"ao",-1,0,-1,0,47,47,"","",1,"","","",2,0,0,[],""],["palau_cantares-00220c",4,"Un pajarito de oro\npuesto en una verde rama,\nmira si será bonito;\npero tu cara le gana.",4,0,-1,64,"",0,4,"aa",-1,0,-1,0,47,47,"","",1,"","","",3,0,0,[],""],["palau_cantares-00220d",4,"En todo lo que el sol baña\ny las estrellas cobijan,\nno he visto cara más bella\nni imagen más peregrina.",4,0,-1,64,"",0,4,"ia",-1,0,-1,0,47,47,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00220e",4,"Tienes un hoyo en la barba\nque parece una cunita:\n¿quieres que me meta en él\ny me cantas la nanita?",4,0,-1,64,"",0,4,"ia",50,0,-1,0,47,47,"","",1,"","","",1,0,0,[],""],["palau_cantares-00221a",4,"Ya no se llaman dedos\nlos de tu mano,\nque se llaman claveles\nde cinco en ramo.",4,0,-1,64,"",6,4,"ao",-1,0,-1,0,47,47,"","",1,"","","",3,0,0,[],""],["palau_cantares-00221b",4,"Tiene la prenda que adoro\nun lunar en un carrillo,\nque me tiene prisionero\nsin haberme echado grillos",4,0,-1,64,"",0,4,"io",-1,0,-1,0,47,47,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00221c",4,"Eres la plata labrada,\neres del oro la espuma,\neres la rosa encarnada,\nen ti no hay falta ninguna.",4,0,-1,64,"",0,4,"ua",-1,0,-1,0,47,47,"","",1,"","","",2,0,0,[],""],["palau_cantares-00221d",4,"Eres como la verbena\nque sola en el campo nace,\neres como el caramelo\nque en la boca se deshace.",4,0,-1,64,"",0,4,"ae",84,0,-1,0,47,47,"","",1,"","","",3,0,0,[],""],["palau_cantares-00221e",4,"Siempreviva te diré\ny lirio del campo no,\nque los lirios se marchitan\ny las siemprevivas no.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,47,47,"","",1,"","","",2,0,0,[],""],["palau_cantares-00222",4,"La hermosura de los cielos\ncuando Dios la repartió,\nno andarías tú muy lejos\ncuando tanta te tocó.",4,0,-1,64,"",0,4,"o",2,0,-1,0,47,47,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00223",4,"No valen lo que tú vales\nla blanca flor del almendro,\nni las mañanas de mayo,\nni el prado de rosas lleno.",4,0,-1,64,"",0,4,"eo",-1,0,-1,0,47,47,"","",1,"huambachano","","",2,0,0,[],""],["palau_cantares-00224",4,"Eres paloma en lo blanco\ny tórtola en el arrullo;\nen el mundo no se encuentra\nsalero como ese tuyo.",4,0,-1,64,"",0,4,"uo",78,0,-1,0,47,47,"","",1,"","","",2,0,0,[],""],["palau_cantares-00225",4,"Cuando te pones, morena,\ná la puerta de tu calle,\npareces la palma verde\nque la bambolea el aire.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,47,47,"","",1,"","","",2,0,0,[],""],["palau_cantares-00227",4,"Su color te dió la rosa,\nel cielo su azul turquí,\nte dió su talle la palma\ny su blancura el jazmín.",4,0,-1,64,"",0,4,"i",-1,0,-1,0,48,48,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00228",4,"La iglesia se ilumina\ncuando tú entras,\ny se llena de flores\ndonde te sientas.\nYa te saliste\ny se quedó la iglesia\nsólita y triste.",4,0,-1,64,"",4,7,"ie",153,0,-1,0,48,48,"","",1,"","","",2,0,0,[],""],["palau_cantares-00229",4,"¿En qué jardín te has criado,\nbella maceta de flores,\nque no tienes quince años\ny cautivas á los hombres?",4,0,-1,64,"",0,4,"oe",-1,0,-1,0,48,48,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00230",4,"Es tanta la claridad\nque por tu ventana sale,\nque dice la vecindad:\nya da la luna en la calle.",4,0,-1,64,"",0,4,"ae",-1,0,-1,0,48,48,"","",1,"","","",3,0,0,[],""],["palau_cantares-00231",4,"Cuando el poderoso Dios\nbajó del cielo á la tierra,\ndejó aquí la semillita\npara que tú florecieras.",4,0,-1,64,"",0,4,"ea",-1,0,-1,0,48,48,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00232",4,"Las estrellitas del cielo\nestán quejosas de Dios,\nporque no las ha criado\ntan hermosas como vos.",4,0,-1,64,"",0,4,"o",87,0,-1,0,48,48,"","",1,"rm_t2","","",25,0,0,[],""],["palau_cantares-00234",4,"Eres águila real\nque en el pico llevas flores,\nen las alas azucenas\ny en el corazón amores.",4,0,-1,64,"",0,4,"oe",5,0,-1,0,48,48,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00235",4,"Quise retratarte,\npero puso Dios\nen ti más belleza\nque en mí discreción.",4,0,-1,64,"",0,4,"o",-1,0,-1,0,48,48,"","",1,"","","",1,0,0,[],""],["palau_cantares-00236",4,"Desde que te vi te amé,\nperdona si no fué antes:\nno tienes que perdonar,\nque ya te amaba endenantes.",4,0,-1,65,"",0,4,"ae",262,0,-1,0,49,49,"","",1,"","","",17,0,0,[],""],["palau_cantares-00236-e2",4,"Yo no sé lo que siento\ncuando te miro,\nque suspiro y no acierto\npor qué suspiro.",4,0,-1,65,"",6,4,"io",222,0,-1,0,49,49,"","",1,"","","",4,0,0,[],""],["palau_cantares-00236-e3",4,"Anda, vete de mi reja;\nanda, vete retirando,\nque mi reja no se ha hecho\nreja de confesonario.",4,0,-1,65,"",0,4,"ao",-1,0,-1,0,49,49,"","",1,"","","",1,0,0,[],""],["palau_cantares-00236-e4",4,"Aunque te vuelvas culebra\ny te vayas á la mar\ny te entierres en la arena,\ncontigo me he de casar.",4,0,-1,65,"",0,4,"a",21,0,-1,0,49,49,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00237a",4,"Desde que te vi, alma mía,\nprendadito me quedé,\ny más cuando me dijeron\nque eras firme en el querer.",4,0,-1,65,"",0,4,"e",-1,0,-1,0,49,49,"","",1,"","","",1,0,0,[],""],["palau_cantares-00237b",4,"Limosna á mi pecho\ndásela por Dios,\nque el pobrecito viene mal herido\ndel mal del amor.",4,0,-1,65,"",3,4,"o",-1,0,-1,0,49,49,"","",1,"","","",1,0,0,[],""],["palau_cantares-00238",4,"Acá dentro del pecho\ntengo un gusano\nque me roe, me roe,\nde cuando en cuando;\ny siento, siento\nque acá dentro del alma\nme da tormento.",4,0,-1,65,"",4,7,"eo",94,0,-1,0,49,49,"","",1,"","","",3,0,0,[],""],["palau_cantares-00239",4,"Mi corazón dice, dice\nque se muere, que se muere,\ny yo le digo, le digo\nque confiese, que confiese.",4,0,-1,65,"",0,4,"ee",-1,0,-1,0,49,49,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00240",4,"Mi corazón se abrasa,\nno sale humo;\nesto sí que es quemarse\ncon disimulo.",4,0,-1,65,"",6,4,"uo",-1,0,-1,0,49,49,"","",1,"","","",4,0,0,[],""],["palau_cantares-00241",4,"Si usted me quisiera á mí\ncomo yo la quiero á usted,\nnos llamaran á los dos\nlos amantes de Teruel.",4,0,-1,65,"",0,4,"e",-1,0,-1,0,49,49,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-00242",4,"Eres, niña chiquita,\nflor de la cera:\n¿cómo no he de quererte\nsi soy abeja?",4,0,-1,65,"",6,4,"ea",-1,0,-1,0,50,50,"","",1,"","","",2,0,0,[],""],["palau_cantares-00243",4,"Yo no pretendo, serrana,\nque me quieras á la fuerza;\npero sí quiero que mires\nlas penillas que me cuestas.",4,0,-1,65,"",0,4,"ea",-1,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00244",4,"Al demonio del infierno\nyo mi alma le daría,\npor hablar contigo á solas\nsiquiera una horita al día.",4,0,-1,65,"",0,4,"ia",0,0,-1,0,50,50,"","",1,"","","",1,0,0,[],""],["palau_cantares-00245",4,"Si me quieres, dímelo,\ny si no, dame veneno:\nno serás tú la primera\nque ha dado muerte á su dueño.",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,50,50,"","",1,"","","",17,0,0,[],""],["palau_cantares-00246",4,"Quisiera ser onza de oro,\nmi vida, y tener dos caras\npara parecerle bien\ná todo el que me mirara.",4,0,-1,65,"",0,4,"aa",-1,0,-1,0,50,50,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00247",4,"Quiéreme y adórame,\nque me aborrezcas no quiero,\ny si me has de aborrecer,\ndame la muerte primero.",4,0,-1,65,"",0,4,"eo",38,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00248",4,"Mañana á la misma hora\npásese usted por aquí,\nque á mí me cuesta vergüenza\ndecir tan pronto que sí.",4,0,-1,65,"",0,4,"i",23,0,-1,0,50,50,"","",1,"","","",2,0,0,[],""],["palau_cantares-00249",4,"Desde aquí te estoy mirando\ncara á cara y frente á frente,\n¡y no te puedo decir\nlo que este corazón siente!",4,0,-1,65,"",0,4,"ee",15,0,-1,0,50,50,"","",1,"lafuente_madrid","","",20,0,0,[],""],["palau_cantares-00250",4,"¡Válgame Dios' ¿No conoces\nque tengo en ti el amor puesto?\n¡Válgame Dios, y qué escaso\neres de conocimiento!",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,50,50,"","",1,"","","",4,0,0,[],""],["palau_cantares-00251",4,"Considera tú, por ti,\nmi alma cómo estaría:\nestando enfrente de ti,\nquise hablarte y no podía.",4,0,-1,65,"",1,4,"ia",0,0,-1,0,50,50,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00252",4,"Mucho tengo que decirte,\npero lo digo al silencio;\nmucho te digo callando,\nsi tienes entendimiento.",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00253",4,"Hermanita, tú solita\nreinas en mi corazón;\nsi yo en el tuyo reinara,\nmi dicha fuera mayor.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,50,50,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00254",4,"Muchos hay que te dirán:\nsalero, por ti me muero;\n¡y yo no te digo nada\ny soy el que más te quiero!",4,0,-1,65,"",0,4,"eo",38,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00255",4,"¡Válgame Dios de los cielos,\nqué penosillo es mi mal!\nTe estoy queriendo á montones,\ny tú no me quieres ná.",4,0,-1,65,"",0,4,"a",-1,0,-1,0,50,50,"","",1,"","","",33,0,0,[],""],["palau_cantares-00256a",4,"Como que sale de ti,\npregúntale si me quiere,\ny si te dice que no,\ndile qué motivos tiene.",4,0,-1,65,"",0,4,"ee",-1,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00256b",4,"A mi triste camarada\nquiérelo, que bien te quiere:\ndelante de mí ha jurado,\nserrana, que por ti muere.",4,0,-1,65,"",0,4,"ee",115,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00256c",4,"Ole con ole, con ole,\nole de ti para mí,\nquiéreme, chatita mía,\ncomo yo te quiero á ti.",4,0,-1,65,"",0,4,"i",23,0,-1,0,50,50,"","",1,"","","",7,0,0,[],""],["palau_cantares-00257a",4,"Desde aquella vez primera\nque en tu presencia me vi,\nel corazón, vida y alma\ná tu obediencia rendí.",4,0,-1,65,"",0,4,"i",23,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00257b",4,"Desde que te vi, rubita,\nese rostro tan sereno,\nlas alas del corazón\ná los pies se me cayeron.",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00257c",4,"Desde que te vi te amé,\ndesde que te amé me muero,\ny si me muero por ti,\ndichoso me considero.",4,0,-1,65,"",0,4,"eo",38,0,-1,0,50,50,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",17,0,0,[],""],["palau_cantares-00258",4,"Desde que te vi te amé,\npésame que ha sido tarde,\nque yo quisiera, bien mío,\ndesde que nací adorarte.",4,0,-1,65,"",0,4,"ae",-1,0,-1,0,51,51,"","",1,"rm_t2, lafuente_madrid, suspiros_amor","","",17,0,0,[],""],["palau_cantares-00259",4,"Ni tu padre, ni tu madre,\nni el Dios que á ti te crió,\ntienen de quererte tanto\ncomo te he querido yo.",4,0,-1,65,"",0,4,"o",2,0,-1,0,51,51,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00260a",4,"Verte, quererte y amarte,\ntodo ha sido de improviso;\ny no sé qué fué primero,\namarte ó haberte visto.",4,0,-1,65,"",0,4,"io",-1,0,-1,0,51,51,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00260b",4,"Hermosísima paloma,\ncara de cielo español,\ncon tu mirar retrechero\nme robas el corazón.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,51,51,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00260c",4,"Si tu madre no me quiere,\nle echaré una maldición:\nque se le pierda su hija\ny que me la encuentre yo.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,51,51,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00260d",4,"Entra corriendo y no temas,\nentra y díselo á mi madre,\nque no te dirá que no,\nque mi corazón lo sabe.",4,0,-1,65,"",0,4,"ae",-1,0,-1,0,51,51,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00260e",4,"A tu madre se lo dije,\ná tu padre no me atrevo:\nen sabiéndolo tu madre,\ntu padre lo sabrá luego.",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,51,51,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00261a",4,"¡Válgame Dios! ¿No conoces\nque tengo en ti mi amor puesto?\n¡Válgame Dios, y qué falto\neres de conocimiento!",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,51,51,"","",1,"","","",4,0,0,[],""],["palau_cantares-00261b",4,"Salero, que me miraste;\nsalero, que te miré;\nsalero, que me gustaste;\nsalero, que te gusté.",4,0,-1,65,"",1,4,"e",77,0,-1,0,51,51,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00262",4,"Dame, paloma, la mano,\nsubiré á tu palomar,\nque me han dicho que estás sola\ny te quiero acompañar.",4,0,-1,65,"",0,4,"a",21,0,-1,0,51,51,"","",1,"","","",1,0,0,[],""],["palau_cantares-00263",4,"El corazón te daré,\ntambién te daré la vida;\nel alma no te la doy,\nporque no es tuya ni mía.",4,0,-1,65,"",0,4,"ia",-1,0,-1,0,51,51,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00264",4,"A mi padre y á mi madre\nles quiero como es debido;\npero en tocando á mi amante,\npierdo los cinco sentidos.",4,0,-1,65,"",0,4,"io",-1,0,-1,0,51,51,"","",1,"","","",4,0,0,[],""],["palau_cantares-00265",4,"Te quiero más que á un divés,\nmás que á mi padre y mi madre,\ny si no fuera pecado,\nmás que á la Virgen del Carmen.",4,0,-1,65,"",0,4,"ae",-1,0,-1,0,51,51,"","",1,"","","",1,0,0,[],""],["palau_cantares-00266",4,"Si me mandaras morir,\nal momento me muriera.\n¿Qué me mandaras tú á mí,\nsalero, que yo no hiciera?",4,0,-1,65,"",0,4,"ea",44,0,-1,0,51,51,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00267",4,"De lo que viste la noche,\nviste la prenda que estimo;\nla noche viste de negro\ny mi prenda de lo mismo.",4,0,-1,65,"",0,4,"io",-1,0,-1,0,52,52,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00268",4,"Más te quiero enojada\nque placentera,\nque haces una enojada\nmuy hechicera.",4,0,-1,65,"",6,4,"ea",44,0,-1,0,52,52,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00270",4,"No tienes tú la culpa,\nni yo te culpo,\nde que Dios te haya hecho\ntan de mi gusto.",4,0,-1,65,"",6,4,"uo",-1,0,-1,0,52,52,"","",1,"rm_t2, barcenas_marinera","","",4,0,0,[],""],["palau_cantares-00271a",4,"Si tu madre te pregunta\nque si me quieres á mí,\ndi con la boca que no,\ncon el corazón que sí.",4,0,-1,65,"",0,4,"i",23,0,-1,0,52,52,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00271b",4,"Esos divinos ojos,\nniña morena,\n¿quieres que los juguemos\ná la rayuela?\nSi tú los pierdes,\nyo te daré los míos\nque por ti mueren.",4,0,-1,65,"",4,7,"ee",-1,0,-1,0,52,52,"","",1,"","","",1,0,0,[],""],["palau_cantares-00271d",4,"Ven acá, luz de mi cara;\nven aquí, prenda querida:\neres clavel encarnado,\npor ti perderé la vida.",4,0,-1,65,"",0,4,"ia",37,0,-1,0,52,52,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00271e",4,"Yo te quiero como á Dios,\ny de eso no hay que admirarse;\ná Dios como á Dios le quiero\ny á ti como fino amante.",4,0,-1,65,"",0,4,"ae",-1,0,-1,0,52,52,"","",1,"","","",2,0,0,[],""],["palau_cantares-00272a",4,"Todos los cuerpos chiquitos\nlos miro con afición,\nporque es chiquita la prenda\nque adora mi corazón.",4,0,-1,65,"",0,4,"o",31,0,-1,0,52,52,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00272b",4,"Digo que no hay en el mundo\nhombre que mi gusto tenga,\nque estoy queriendo á una niña\nmás chiquita que una almendra.",4,0,-1,65,"",0,4,"ea",-1,0,-1,0,52,52,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00272c",4,"Quisiera ser por un rato\nde tu zarcillo el arete,\npara decirte al oído\nlo que este corazón siente.",4,0,-1,65,"",0,4,"ee",-1,0,-1,0,52,52,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-00272d",4,"A la orilla del mar fui\ny me senté en la ribera,\ny empecé á considerar:\n¡si esta niña me quisiera!",4,0,-1,65,"",0,4,"ea",44,0,-1,0,52,52,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00272e",4,"María, no eres María,\nque eres ramo de virtud:\ná tu puerta hay un enfermo,\ndale por Dios la salud.",4,0,-1,65,"",0,4,"u",278,0,-1,0,52,52,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00273",4,"Si alguna vez se perdiere\nel retrato de tu cara,\nbúscalo y lo encontrarás\nen el fondo de mi alma.",4,0,-1,65,"",0,4,"aa",-1,0,-1,0,52,52,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00274",4,"Mariquita, tú solita\nreinas en mi corazón.\nSi yo reinara en el tuyo,\n¡qué dichoso fuera yo!",4,0,-1,65,"",0,4,"o",-1,0,-1,0,52,52,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00275",4,"Mal haya quien no te quiere,\nmal haya quien no te ama,\nmal haya quien no se fuere\ncontigo de buena gana.",4,0,-1,65,"",0,4,"aa",-1,0,-1,0,52,52,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00276",4,"Son tus labios dos cortinas\nde tafetán carmesí,\ny entre cortina y cortina\nestoy esperando el sí.",4,0,-1,65,"",3,4,"i",23,0,-1,0,52,52,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00277",4,"Es tanto lo que te quiero,\nque te quisiera llevar\nmetido en la faltriquera\ncomo pedazo de pan.",4,0,-1,65,"",0,4,"a",-1,0,-1,0,52,52,"","",1,"","","",26,0,0,[],""],["palau_cantares-00278",4,"Las estrellas y luceros\ntodos se rinden al día,\ny yo me rindo á tus plantas,\nmorena del alma mía.",4,0,-1,65,"",0,4,"ia",0,0,-1,0,52,52,"","",1,"rm_t2, lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00279",4,"Estudiante quise ser,\ny así que vi tu hermosura,\ná los infiernos tiré\ntintero, papel y pluma.",4,0,-1,65,"",0,4,"ua",-1,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00280",4,"Como soy forasterito,\ná todo el mundo pregunto:\n¿quién es esa morenita\nque está vestida de luto?",4,0,-1,65,"",0,4,"uo",-1,0,-1,0,53,53,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00281",4,"Cuando yo te vi venir,\nle dije á mi corazón:\n¡qué bonita piedrecita\npara dar un tropezón!",4,0,-1,65,"",0,4,"o",31,0,-1,0,53,53,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00282",4,"¡Tan chiquita y tienes luto!\nDime, ¿quién se te murió?\nSi se te ha muerto tu amante\nno llores, que aquí estoy yo.",4,0,-1,65,"",0,4,"o",2,0,-1,0,53,53,"","",1,"","","",3,0,0,[],""],["palau_cantares-00283",4,"Compañerilla del alma,\ncuando mis ojos te vieron,\nse me arrancó el corazón\nde fatigas que me dieron.",4,0,-1,65,"",0,4,"eo",105,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00284",4,"Morenita y enlutada,\n¡qué bien que te sienta el luto!\nNos casaremos los dos,\ny Dios perdone al difunto.",4,0,-1,65,"",0,4,"uo",-1,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00285",4,"Una mañanita, apenas\nsalió el sol por el oriente,\nme echastes una cadena\ncon los rizos de tu frente.",4,0,-1,65,"",0,4,"ee",15,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00286",4,"Gracias á Dios que he llegado\ná declarar mi pasión\ná una dama tan hermosa\ncomo los rayos del sol.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00287",4,"Desde que te vi, morena,\nen la calle de Mesones,\nme echastes una cadena\ncon veinticinco eslabones.",4,0,-1,65,"",1,4,"oe",34,0,-1,0,53,53,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00288",4,"Eres rosita en capullo,\nsin acabar de salir;\nsi todavía no amas,\námame primero á mí.",4,0,-1,65,"",0,4,"i",-1,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00289",4,"Dime, niña, dónde vives,\nque te quiero conocer,\ny si no tienes amante,\nyo te vengo á pretender.",4,0,-1,65,"",0,4,"e",20,0,-1,0,53,53,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00290",4,"¡Ay, qué ventana tan alta!\n¡Ay, qué balcón tan dorado!\n¡Ay, qué niña tan bonita!\n¿Quién será su enamorado?",4,0,-1,65,"",0,4,"ao",14,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00291",4,"El clavel que tú me diste\nel día de la Ascensión,\nno fué clavel, sino clavo\nque clavó mi corazón.",4,0,-1,65,"",0,4,"o",31,0,-1,0,53,53,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00292",4,"Ya no me alegran á mí\nlas rosas ni los jardines;\nlo que me alegra es tu cara:\ndime, niña, ¿dónde vives?",4,0,-1,65,"",0,4,"ie",-1,0,-1,0,53,53,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00293",4,"Al alto cielo subí\ná preguntar por tu nombre,\ny me dijo un serafín\nque te llamabas Dolores.",4,0,-1,65,"",0,4,"oe",-1,0,-1,0,53,53,"","",1,"","","",6,0,0,[],""],["palau_cantares-00294",4,"Por fuerza me has de querer,\npor justicia me has de amar,\ncariño me has de tener,\nó el diablo te ha de llevar.",4,0,-1,65,"",1,4,"a",21,0,-1,0,53,53,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00295",4,"María sé que te llamas,\ntu apellido no lo sé;\nsi por la calle te encuentro,\nMaría te llamaré.",4,0,-1,65,"",0,4,"e",77,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00296",4,"Toma, niña, esta naranja:\nte la doy porque te quiero;\nno la partas con cuchillo,\nque mi corazón va dentro.",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,53,53,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00297",4,"Pregunté si eres casada,\nque tu garbo me embelesa;\nel preguntar no es errar,\nsi la pregunta no es necia.",4,0,-1,65,"",0,4,"ea",-1,0,-1,0,53,53,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00298",4,"Dicen que lo azul es celos\ny lo encarnado alegría;\nvístete, niña, de verde,\nserás la esperanza mía.",4,0,-1,65,"",0,4,"ia",0,0,-1,0,53,53,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00299",4,"Determínate á quererme,\nno me seas temerosa;\nde los riesgos que vinieren\nte sacaré victoriosa.",4,0,-1,65,"",0,4,"oa",63,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00300",4,"Tú tienes mi corazón,\nel tuyo me lo has de dar,\nque el que roba corazones\ncon el suyo ha de pagar.",4,0,-1,65,"",0,4,"a",21,0,-1,0,54,54,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00301",4,"Palomita amartelada\ndel palomar de Cupido,\nno sientas levantar vuelo\ny vente á volar conmigo.",4,0,-1,65,"",0,4,"io",-1,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00302",4,"Si me quieres, dímelo,\ny si no, di que me vaya:\nno me tengas al sereno,\nque no soy cántaro de agua.",4,0,-1,65,"",0,4,"aa",-1,0,-1,0,54,54,"","",1,"rm_t2, navalmoral_mata","","",17,0,0,[],""],["palau_cantares-00303",4,"Ya se acabaron las chanzas\ny entra la formalidad;\nsi me quieres, yo te quiero,\nvamos á ver la verdad.",4,0,-1,65,"",0,4,"a",16,0,-1,0,54,54,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00304",4,"Yo me llamo si hay lugar,\npariente si hay ocasión,\nprimo hermano de si puedes,\naguardando el sí ó el no.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00305",4,"Hasta la última gota\nde sangre diera por ti\nsólo porque te mantengas\nsiempre diciendo que sí.",4,0,-1,65,"",0,4,"i",23,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00306",4,"Te diera, porque me dieras\nde tu linda boca el sí,\nlas alfombras de Turquía\ny el oro del Potosí.",4,0,-1,65,"",0,4,"i",23,0,-1,0,54,54,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00307",4,"Supongo que tú me quieres,\nsiempre constante serás:\n¡Dios nos libre de una vieja\nque nos comience á enredar!",4,0,-1,65,"",0,4,"a",-1,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00308",4,"Haré por ti una fineza,\nla que tú por mí no harás;\nquererte aunque no me quieras:\n¿qué más quieres?, ¿quieres más?",4,0,-1,65,"",0,4,"a",51,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00309",4,"Sólo te encargo que guardes\nel secreto hasta que quiera\ndarnos el cielo ocasión\nde lograr la dicha nuestra.",4,0,-1,65,"",0,4,"ea",-1,0,-1,0,54,54,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00310",4,"Si supiera que por flores\nte había de conseguir,\nte trajera yo más flores\nque tienen mayo y abril.",4,0,-1,65,"",0,4,"i",-1,0,-1,0,54,54,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00311",4,"Si viniera San Francisco\ná pedirme el corazón,\nal santo se lo negara\ny á una de su nombre no.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,54,54,"","",1,"","","",3,0,0,[],""],["palau_cantares-00312",4,"Si usted me quisiera á mí\ncomo yo la quiero á usted,\nnos llamaran á los dos\nla fundación del querer.",4,0,-1,65,"",0,4,"e",-1,0,-1,0,54,54,"","",1,"","","",3,0,0,[],""],["palau_cantares-00313",4,"Si san Rafael me diera\nlicencia para quererte,\ntoda mi vida estuviera\nvestida de azul celeste.",4,0,-1,65,"",0,4,"ee",-1,0,-1,0,54,54,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00314",4,"Socorro pide en el mar\nel marinero perdido,\ny yo que estoy en la tierra,\nSocorro, Socorro pido.",4,0,-1,65,"",0,4,"io",101,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00315",4,"Le dije: Jilguero mío,\n¿qué remedio me darás\npara una mujer que quiero\ny no la puedo olvidar?",4,0,-1,65,"",0,4,"a",-1,0,-1,0,54,54,"","",1,"","","",1,0,0,[],""],["palau_cantares-00316",4,"Tengo vergüenza y me callo,\ntengo amor y no lo digo;\nno sé cómo te dijera:\n¿te quieres casar conmigo?",4,0,-1,65,"",0,4,"io",106,0,-1,0,54,54,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["palau_cantares-00317",4,"El jilguero me responde:\nQuiérela tú con firmeza,\nporque al fin ella es mujer\ny ablandará su dureza.",4,0,-1,65,"",0,4,"ea",108,0,-1,0,54,54,"","",1,"","","",1,0,0,[],""],["palau_cantares-00318",4,"Estoy adorando á un sol\ny venerando á una imagen,\nno siento sino una cosa,\nque la quiero y no lo sabe.",4,0,-1,65,"",0,4,"ae",-1,0,-1,0,54,54,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00319",4,"Dos corazones heridos\nde la misma enfermedad,\nambos se quitan la vida\npor no decir la verdad.",4,0,-1,65,"",0,4,"a",16,0,-1,0,55,55,"","",1,"rm_t4","","",5,0,0,[],""],["palau_cantares-00320",4,"Tantas letras tiene el sí\ncomo letras tiene el no;\ncon el sí me das la vida,\ny la muerte con el no.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00321",4,"Las campanas de la iglesia\nestán doblando por mí:\ndime, niña, si me quieres;\nresucitaré por ti.",4,0,-1,65,"",0,4,"i",23,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00322",4,"Yo me muero no sé cómo,\ny mi mal es no sé qué;\nyo sanaré bien sé cuándo,\nsi me cura quien yo sé.",4,0,-1,65,"",0,4,"e",77,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00323",4,"Bien sabe Dios que te diera\npor ese color moreno\nlos ojitos de mi cara,\naunque me quedara ciego.",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00324",4,"Yo quisiera y no quisiera,\nque son cosas diferentes:\nquisiera que me quisieras\ny quisiera no quererte.",4,0,-1,65,"",0,4,"ee",-1,0,-1,0,55,55,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00325",4,"Si por hazañas de monta\nse pudiera á usted ganar,\ntomara yo por asalto\nel peñón de Gibraltar.",4,0,-1,65,"",0,4,"a",21,0,-1,0,55,55,"","",1,"","","",4,0,0,[],""],["palau_cantares-00326",4,"Una gotera continua\nablanda un duro peñón:\n¡y mis suspiros no pueden\nablandar tu corazón!",4,0,-1,65,"",0,4,"o",31,0,-1,0,55,55,"","",1,"rm_t2, carrizo_salta, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["palau_cantares-00327",4,"Serrana, tú eres la lima,\ny tu padre es el limón,\ny tu madre la naranja:\nla lima la quiero yo.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00328",4,"La pena de un ciego es grande,\nque no ve por dónde va;\npero más grande es la mía,\nque no sé tu voluntad.",4,0,-1,65,"",0,4,"a",-1,0,-1,0,55,55,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00329",4,"Por vida de las estrellas\nque están en el cielo azul,\nque te tengo de querer\naunque no me quieras tú.",4,0,-1,65,"",0,4,"u",-1,0,-1,0,55,55,"","",1,"","","",1,0,0,[],""],["palau_cantares-00330",4,"Las estrellitas del cielo\ncada cual tiene su nombre;\nla mía se llama Rita,\nla llamo y no me responde.",4,0,-1,65,"",0,4,"oe",-1,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",25,0,0,[],""],["palau_cantares-00331",4,"Desde que te vi te amé,\nporque amar y verte, cielo,\nbien pudieron ser dos cosas,\npero ninguna primero.",4,0,-1,65,"",0,4,"eo",-1,0,-1,0,55,55,"","",1,"","","",17,0,0,[],""],["palau_cantares-00332",4,"Contigo me dan matraca,\n¡ojalá fuera verdad!,\nque nunca los rayos caen\ndonde la tormenta está.",4,0,-1,65,"",0,4,"a",-1,0,-1,0,55,55,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00333",4,"Los pensamientos me animan\nde querer á esta serrana:\nsólo llegaré á sentir\nque me deje con la gana.",4,0,-1,65,"",0,4,"aa",4,0,-1,0,55,55,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00334",4,"Aunque me digas que no,\ná tu casa siempre acudo,\nque al cabo saca limosna\nel pobre que es importuno.",4,0,-1,65,"",0,4,"uo",-1,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00335",4,"Si me das un ramillete\ncompuesto con tu cariño,\nyo te daré el corazón,\nla prenda que más estimo.",4,0,-1,65,"",0,4,"io",-1,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00336",4,"Desde Madrid he venido,\npisando espinas y abrojos,\nsólo por llegar á verte,\nclavellina de mis ojos.",4,0,-1,65,"",0,4,"oo",99,0,-1,0,55,55,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00337",4,"Viendo que no me querías,\ná un arroyuelo bajé;\noí cantar á un jilguero,\ncon su voz me consolé.",4,0,-1,65,"",0,4,"e",77,0,-1,0,55,55,"","",1,"","","",3,0,0,[],""],["palau_cantares-00338",4,"Aquí me pongo á cantar\ná la sombra de la luna,\npor ver si puedo alcanzar\nde las dos hermanas una.",4,0,-1,65,"",1,4,"ua",56,0,-1,0,55,55,"","",1,"lafuente_madrid","","",18,0,0,[],""],["palau_cantares-00339",4,"La menor no tiene el tiempo,\nla mayor pasa la edad;\nla de en medio es la que quiero,\nsi su padre me la da.",4,0,-1,65,"",0,4,"a",-1,0,-1,0,56,56,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00340",4,"Palomita amartelada\ndentro de tu palomar,\npalomos de lejas tierras\nte vienen á visitar.",4,0,-1,65,"",0,4,"a",21,0,-1,0,56,56,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00341",4,"Te dije si me querías\ny me dijiste: veré.\nBastante tiempo has tenido\npara tomar parecer.",4,0,-1,65,"",0,4,"e",-1,0,-1,0,56,56,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00342",4,"Si duermo, sueño contigo;\nsi despierto, pienso en ti:\ndime, dime, compañero,\nqué es lo que te pasa á ti.",4,0,-1,65,"",0,4,"i",-1,0,-1,0,56,56,"","",1,"","","",1,0,0,[],""],["palau_cantares-00343",4,"Ya me despido, mi vida,\nde tu hermosura y belleza;\npara vivir ó morir,\nsólo aguardo tu respuesta.",4,0,-1,65,"",0,4,"ea",-1,0,-1,0,56,56,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00344",4,"Más te quieren mis ojos\ndisimulando,\nque otros dándote voces\ny alborotando.",4,0,-1,65,"",6,4,"ao",33,0,-1,0,56,56,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00345",4,"Tú eres el juez de mi causa,\ny yo soy el delincuente;\nacaba de sentenciar\nsi soy de vida ó de muerte.",4,0,-1,65,"",0,4,"ee",-1,0,-1,0,56,56,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00346",4,"Serrana, ¿quién te camela?\nDime la verdad, por Dios;\nsi no te camela nadie,\nquiero camelarte yo.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,56,56,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00347",4,"No te quiero dar el sí\nhasta ver cómo te portas,\nque no muy lejos de aquí\nme han dicho que tienes otra.",4,0,-1,65,"",0,4,"oa",-1,0,-1,0,56,56,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00348",4,"Si mi corazón te estorba,\nanda, y échalo á la calle,\nque se lo coman los perros,\nsi no lo recoge nadie.",4,0,-1,65,"",0,4,"ae",-1,0,-1,0,56,56,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00349",4,"Si supiera que era yo\nla causa de tu tristeza,\ndejaría padre y madre\ny te amara con firmeza.",4,0,-1,65,"",0,4,"ea",108,0,-1,0,56,56,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00350",4,"No me mires de reojo,\nque es mirada de traidor;\nmírame así, cara á cara,\nque es miradita de amor.",4,0,-1,65,"",0,4,"o",72,0,-1,0,56,56,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00351",4,"Si eres galán dulce y fino,\nsiempre firme en la pasión,\nyo hallaré en ti mi destino\ny te daré el corazón.",4,0,-1,65,"",1,4,"o",31,0,-1,0,56,56,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00352",4,"Mi corazón á tus pies\nlo ves, y no lo levantas:\n¡lástima de corazón,\nque no duerme ni descansa!",4,0,-1,65,"",0,4,"aa",-1,0,-1,0,56,56,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00353",4,"Amor, si tú fueras firme\ncomo la palma en verano,\nyo te entregara las llaves\nde mi pecho soberano.",4,0,-1,65,"",0,4,"ao",81,0,-1,0,56,56,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00354",4,"Tienes unos ojos, niña,\nenseñados á vivir:\ncariñosos para todos\ny tiranos para mí.",4,0,-1,65,"",0,4,"i",-1,0,-1,0,56,56,"","",1,"rm_t2, lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00355",4,"Si tu madre te regaña\nporque me piensas querer,\ndile que ya no me quieres,\ny con eso quedas bien.",4,0,-1,65,"",0,4,"e",-1,0,-1,0,56,56,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00356",4,"Te quiero más que á mi vida\ny más que á mi corazón,\ny si no fuera pecado\nte querría más que á Dios.",4,0,-1,65,"",0,4,"o",-1,0,-1,0,56,56,"","",1,"","","",8,0,0,[],""],["palau_cantares-00357a",4,"Ya viene marzo con flores\ny con sus rosas abril,\ny mayo con sus claveles\npara coronarte á ti.",4,0,-1,66,"",0,4,"i",-1,0,-1,0,57,57,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00357b",4,"Escúchame, compañera,\nque te lo quiero jurar:\nprimero que yo te olvide,\nla tierra me ha de tragar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,57,57,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00357c",4,"Cuando vayas á la iglesia\nponte un velito en la cara,\nque los santos, con ser santos,\nmiran dónde estás sentada.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,57,57,"","",1,"","","",2,0,0,[],""],["palau_cantares-00357d",4,"Cada vez que paso y veo\nque á la ventana no estás,\nvoy acortando los pasos\npor ver si te asomarás.",4,0,-1,66,"",0,4,"a",51,0,-1,0,57,57,"","",1,"","","",3,0,0,[],""],["palau_cantares-00358a",4,"En tu puerta puse un guindo,\nen tu ventana un cerezo:\npor cada guinda un abrazo,\npor cada cereza un beso.",4,0,-1,66,"",0,4,"eo",48,0,-1,0,57,57,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00358b",4,"Es tanto lo que te quiero,\nque te quisiera llevar\nen las ancas de mi mula\ncuando me vuelva al lugar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,57,57,"","",1,"","","",26,0,0,[],""],["palau_cantares-00359",4,"En tu puerta planté un pino\ny en tu ventana una parra\nporque los rayos del sol\nno te dieran en la cara.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,57,57,"","",1,"","","",2,0,0,[],""],["palau_cantares-00360",4,"Dame un poco de agua\nfría ó caliente,\nno por la sed que tengo,\nsino por verte.",4,0,-1,66,"",6,4,"ee",-1,0,-1,0,57,57,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00361",4,"En tu puerta sembré un guindo\ny en tu ventana un manzano\nsólo por verte coger\nlas ramitas con la mano.",4,0,-1,66,"",0,4,"ao",81,0,-1,0,57,57,"","",1,"","","",2,0,0,[],""],["palau_cantares-00362",4,"Aunque tú no me quieras,\ntengo el consuelo\nde saber que tú sabes\nque yo te quiero.",4,0,-1,66,"",6,4,"eo",-1,0,-1,0,57,57,"","",1,"rm_t2, carrizo_salta, fernan_caballero","","",7,0,0,[],""],["palau_cantares-00363",4,"Dame de tus entrañas\ntodo el cariño,\ny acaba de criarme,\nque soy muy niño;\ny en siendo hombre,\nyo te daré el cariño\nque corresponde.",4,0,-1,66,"",4,7,"oe",-1,0,-1,0,58,58,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00363-e10",4,"Hábito de Dolores\ntiene mi dama:\ncon los siete cuchillos\nme parte el alma.",4,0,-1,66,"",6,4,"aa",-1,0,-1,0,58,58,"","",1,"rm_t2, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00363-e2",4,"Es tanto lo que te quiero,\nserrana, que te matara\ny con sangre de mis venas\nluego te resucitara.",4,0,-1,66,"",0,4,"aa",57,0,-1,0,58,58,"","",1,"rm_t2, lafuente_madrid","","",26,0,0,[],""],["palau_cantares-00363-e3",4,"Dicen que no nos queremos\nporque no nos ven hablar:\ná tu corazón y al mío\nse lo pueden preguntar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,58,58,"","",1,"rm_t2, lafuente_madrid, murciano_antiguo, barcenas_marinera","","",11,0,0,[],""],["palau_cantares-00363-e4",4,"Eché un candado en mi pecho\ndesde que vi tu belleza\nporque ninguna entre en él\nsin que tú le des licencia.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,58,58,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00363-e6",4,"¿Para qué, ingrata, quieres\nsaber mis males?\nCon saber que te quiero.\ntodos los sabes.",4,0,-1,66,"",6,4,"ae",-1,0,-1,0,58,58,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00363-e7",4,"Hermosura del alma,\nvete auna aldea:\nya que yo no te hable,\nque no te vea.",4,0,-1,66,"",6,4,"ea",54,0,-1,0,58,58,"","",1,"","","",2,0,0,[],""],["palau_cantares-00363-e8",4,"Por Dios, si no me quieres,\nque no me mires:\nya que no me rescates,\nno me cautives.",4,0,-1,66,"",6,4,"ie",-1,0,-1,0,58,58,"","",1,"preciso_coleccion, huambachano","","",7,0,0,[],""],["palau_cantares-00363-e9",4,"Un limón me tiraste\ndesde la torre:\nen el alma me diste,\nsangre me corre.",4,0,-1,66,"",6,4,"oe",136,0,-1,0,58,58,"","",1,"","","",1,0,0,[],""],["palau_cantares-00364a",4,"Me han dicho que estás malita\ny á Dios le pido llorando\nque me quite la salud\ny á ti te la vaya dando.",4,0,-1,66,"",0,4,"ao",33,0,-1,0,58,58,"","",1,"","","",6,0,0,[],""],["palau_cantares-00364b",4,"Agua menudita llueve\ny correrán las canales:\nábreme la puerta, cielo,\nque soy aquel que tú sabes.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,58,58,"","",1,"","","",6,0,0,[],""],["palau_cantares-00364c",4,"Si se volvieran luceros\nlos besitos que te he dado,\npareciera tu carita\nun cielecito estrellado.",4,0,-1,66,"",0,4,"ao",14,0,-1,0,58,58,"","",1,"","","",1,0,0,[],""],["palau_cantares-00364d",4,"De terciopelo negro\ntengo cortinas\npara enlutar mi cuarto\nsi tú me olvidas.",4,0,-1,66,"",6,4,"ia",-1,0,-1,0,58,58,"","",1,"rm_t2","","",7,0,0,[],""],["palau_cantares-00364e",4,"Si sientes como siento,\nprenda querida,\nlos tormentos mayores\ntienes en vida.",4,0,-1,66,"",6,4,"ia",37,0,-1,0,58,58,"","",1,"","","",2,0,0,[],""],["palau_cantares-00364f",4,"Soy peñasco, soy risco,\nsoy dura piedra;\npara todos soy bronce,\npara ti cera.",4,0,-1,66,"",6,4,"ea",-1,0,-1,0,58,58,"","",1,"rm_t2, frenk_t1, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-00364g",4,"Sueño en ti, vida mía,\npero entre sueños\nsueño lo que quisiera\nno fuera sueño.",4,0,-1,66,"",6,4,"eo",-1,0,-1,0,58,58,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00364h",4,"De mi casita á la tuya,\nmorena, no hay más que un paso;\ndesde la tuya á la mía,\n¡ay qué camino tan largo!",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,58,58,"","",1,"","","",1,0,0,[],""],["palau_cantares-00364i",4,"El primer amor que tuve\nse me llevó el corazón:\nno hay amor como el primero,\nque se lleva lo mejor.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,58,58,"","",1,"rm_t4","","",6,0,0,[],""],["palau_cantares-00365",4,"¿Qué importa que los labios\namando callen,\ncuando amor por los ojos\nsabe explicarse?\nPorque, en amando,\ntienen lengua los ojos\nmás que los labios.",4,0,-1,66,"",4,7,"ao",-1,0,-1,0,59,59,"","",1,"","","",1,0,0,[],""],["palau_cantares-00365-e2",4,"Tus ojos y mis ojos\nmiran atentos,\ny callando se dicen\nsus pensamientos.\nCosa es bien rara\nque sin hablar se entiendan\nnuestras dos almas.",4,0,-1,66,"",4,7,"aa",-1,0,-1,0,59,59,"","",1,"","","",1,0,0,[],""],["palau_cantares-00365-e3",4,"Por Dios que disimules\nlo que me quieres,\nque tú no logras nada\ny á mí me pierdes;\nporque estas cosas,\nen ser comunes, pierden\nel ser preciosas.",4,0,-1,66,"",4,7,"oa",61,0,-1,0,59,59,"","",1,"rm_t2, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-00365-e4",4,"Mi corazón volando\nse entró en el tuyo;\nse quebraron las alas,\nsalir no pudo:\ny está contento,\ncomo que el pobrecito\nse halla en su centro.",4,0,-1,66,"",4,7,"eo",-1,0,-1,0,59,59,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00365-e5",4,"Bien sabe Dios que te diera\nlo que merecido tienes:\nuna corona imperial\nque coronara tus sienes.",4,0,-1,66,"",0,4,"ee",120,0,-1,0,59,59,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00365-e6",4,"Si sabes los mandamientos,\nel primero es el amar;\nes tanto lo que te quiero,\nque no te puedo olvidar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,59,59,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00366a",4,"Segundo, confirmación.\nTe ha confirmado el obispo,\ny cada vez que te veo,\nyo en tu querer me confirmo.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,59,59,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00366b",4,"El tercero, penitencia.\nY por ella el otro día\nme han mandado que te olvide,\ny no he podido cumplirla.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,59,59,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00366c",4,"El cuarto, la comunión.\nRecíbela con anhelo;\nsi estás en gracia de Dios,\nseguro tienes el cielo.",4,0,-1,66,"",0,4,"eo",10,0,-1,0,59,59,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00366d",4,"El quinto, la extremaunción.\nExtremo es lo que te quiero,\ny á la hora de mi muerte\nserás mi solo consuelo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,59,59,"","",1,"","","",1,0,0,[],""],["palau_cantares-00366e",4,"El sexto, el sacerdotal.\nSacerdote no he de ser;\nhasta la hora de la muerte\nseré firme en tu querer.",4,0,-1,66,"",0,4,"e",20,0,-1,0,59,59,"","",1,"","","",2,0,0,[],""],["palau_cantares-00366f",4,"El séptimo, matrimonio.\nEso vengo yo á buscar,\ny aunque tu padre no quiera,\ncontigo me he de casar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,59,59,"","",1,"","","",3,0,0,[],""],["palau_cantares-00366g",4,"Quiéreme poquito á poco,\nsalero, no te apresures,\nque este cariñito nuestro,\nsalero, quiero que dure.",4,0,-1,66,"",0,4,"ue",-1,0,-1,0,59,59,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00366h",4,"No me hables de comida,\nni me mientes el comer,\nque yo estoy alimentado\ntan sólo con tu querer.",4,0,-1,66,"",0,4,"e",20,0,-1,0,59,59,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00367",4,"Los sacramentos son siete,\ny te los vengo á explicar:\nescucha con atención,\nsi me quieres escuchar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,59,59,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00368",4,"Cuando me siento á la mesa,\nde pensar en ti no como:\ntus palabras me alimentan,\ntus labios me dan socorro.",4,0,-1,66,"",0,4,"oo",-1,0,-1,0,59,59,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00369",4,"De todos los sacramentos\nel primero es el bautismo.\nYa sé que estás bautizada,\npodrás casarte conmigo.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,59,59,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00370",4,"Con hablarte como y bebo,\ny sólo el verte me engorda,\ny el día que no te veo\nlas fatiguillas me ahogan.",4,0,-1,66,"",0,4,"oa",-1,0,-1,0,59,59,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00371",4,"Eres para mí el reposo,\neres para mí el recreo,\neres clavel oloroso,\neres el bien que poseo.",4,0,-1,66,"",1,4,"eo",66,0,-1,0,60,60,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00372",4,"En el cielo de tu casa\nte vi, salada, ayer tarde;\nbien puede llamarse cielo,\nporque en ella vive un ángel.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,60,60,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00373",4,"Por ti me muero de amor,\npor ti deliro y suspiro,\npor ti se abrasa mi pecho,\npor ti muero y por ti vivo.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,60,60,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00374",4,"No llores, ángel humano,\naunque veas que me muero;\nporque si te ven llorar,\npensarán que me condeno.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,60,60,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00375",4,"El sol me parece obscuro\ny obscura la luna clara,\nla música me entristece,\nsólo me alegra tu cara.",4,0,-1,66,"",0,4,"aa",57,0,-1,0,60,60,"","",1,"","","",1,0,0,[],""],["palau_cantares-00376",4,"Dije que no te quería\ny otra vez vuelvo á buscarte\ncon el corazón partido,\nllorando gotas de sangre.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,60,60,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00377",4,"Bien sabe Dios que te quiero\nsin interés ni maldad,\ny por tus buenas partidas\nte tengo de querer más.",4,0,-1,66,"",0,4,"a",-1,0,-1,0,60,60,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00379",4,"Si la sangre de mis venas\nla hubieras de menester,\nbien puedes contar con ella,\nque yo me la sacaré.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,60,60,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00380",4,"Cuando intenté el olvidarte,\nse me previno la muerte:\ncomo la vida es amable,\nvolví de nuevo á quererte.",4,0,-1,66,"",0,4,"ee",134,0,-1,0,60,60,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00381",4,"A la soda y la barrilla\nles gustan los saladares,\ny á ti te place vivir\norillita de los mares.",4,0,-1,66,"",0,4,"ae",164,0,-1,0,60,60,"","",1,"","","",1,0,0,[],""],["palau_cantares-00382",4,"Dime, niña, que me quieres,\nantes que de amor me muera,\nque en una palabra tuya\ncifrada está mi existencia.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,60,60,"","",1,"","","",1,0,0,[],""],["palau_cantares-00383",4,"Tus ojos y los míos\nse han enredado\ncomo las zarzamoras\npor los vallados.",4,0,-1,66,"",6,4,"ao",-1,0,-1,0,60,60,"","",1,"rm_t2, fernan_caballero","","",7,0,0,[],""],["palau_cantares-00384",4,"Cuando mi niña se pone\nla saya para ir á misa,\nsale el sol y se obscurece,\nsale la luna y se eclipsa.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,60,60,"","",1,"","","",3,0,0,[],""],["palau_cantares-00385",4,"Mal hizo en tenerte sola\nla bendita de tu madre;\nangelitos como tú\nse deben tener á pares.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,60,60,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00386",4,"A la flor de la violeta\nmezclada con el jazmín,\ná eso me huele tu cuerpo\ncuando estoy cerca de ti.",4,0,-1,66,"",0,4,"i",-1,0,-1,0,60,60,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00387",4,"¡Qué contentita estará\nla madre de esa doncella!\nEstando el cielo tan alto,\ntiene en su casa una estrella.",4,0,-1,66,"",0,4,"ea",6,0,-1,0,60,60,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00388",4,"Dicen que no nos queremos,\nporque no nos visitamos;\nlas visitas son de noche\npara los enamorados.",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,60,60,"","",1,"rm_t2, lafuente_madrid","","",11,0,0,[],""],["palau_cantares-00389",4,"Ayer tarde en el paseo,\nniña, de azul te vestiste;\nque también hay en la tierra\nángel que de azul se viste.",4,0,-1,66,"",0,4,"ie",153,0,-1,0,60,60,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00390",4,"Fuentecilla cristalina,\nagua y río caudaloso,\npara dos que bien se quieren,\nlargos caminos son cortos.",4,0,-1,66,"",0,4,"oo",-1,0,-1,0,60,60,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00391",4,"Debajo de tu ventana,\npor pintarte á ti, pinté\nuna rosa catalana\ny un clavel aragonés.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,61,61,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",29,0,0,[],""],["palau_cantares-00392",4,"Vuela, pensamiento mío,\nal lecho de mis amores,\ny la estancia de su dueño\nperfúmala con olores.",4,0,-1,66,"",0,4,"oe",5,0,-1,0,61,61,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00393a",4,"¡Qué linda clavellinera\nque estoy viendo desde aquí!\nComo soy forasterito,\n¿no hay un clavel para mí?",4,0,-1,66,"",0,4,"i",23,0,-1,0,61,61,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00393c",4,"Alcarraza de tu casa,\nchiquilla, quisiera ser\npara besarte en los labios\ncuando fueras á beber.",4,0,-1,66,"",0,4,"e",20,0,-1,0,61,61,"","",1,"","","",1,0,0,[],""],["palau_cantares-00393d",4,"No sé qué para mí tienes,\nque cada vez que te veo\nme quedo, como San Juan,\nseñalando con el dedo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,61,61,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00394a",4,"Si te ves aborrecida\ndel galán que te adoraba,\nvuelve, vuelve á mi querer,\novejita descarriada.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,61,61,"","",1,"","","",2,0,0,[],""],["palau_cantares-00394b",4,"Suspiros del corazón\nsalen de mi pecho ardiendo\ny se van á aposentar\ndonde está mi amor durmiendo.",4,0,-1,66,"",0,4,"eo",52,0,-1,0,61,61,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00394c",4,"De tu corazón al mío\nhay una larga cadena\ntoda llena de suspiros,\nde suspiros toda llena.",4,0,-1,66,"",0,4,"ea",59,0,-1,0,61,61,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00394d",4,"Suspiros, salid, salid,\ny trasminad las paredes,\ny mirad si está dormida\nla reina de las mujeres.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,61,61,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00395",4,"Clavellina colorada\nnacida en el mes de enero,\n¿quién ha visto cortar flores\nen el rigor del invierno?",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,61,61,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00396",4,"Si á media noche sintieres\nen tu cara un aire frío,\nno te muestres enojada,\nque son los suspiros míos.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,61,61,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00397",4,"Ojos de color de cielo,\nazules como los míos,\nno perdáis las esperanzas,\nque yo no las he perdido.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,61,61,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00398",4,"¿Qué tenías ayer tarde,\namante mío moreno,\nque tan aprisa llamabas\ná Jesús el Nazareno?",4,0,-1,66,"",0,4,"eo",76,0,-1,0,62,62,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00399",4,"A mí me llaman silencio,\ny el silencio es el que vale;\nanoche estuve en tu puerta\ny no me sintió tu madre.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,62,62,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00400",4,"Hermoso sol de los soles,\n¿en dónde estuviste ayer,\nque te buscaron mis ojos\ny no te pudieron ver?",4,0,-1,66,"",0,4,"e",20,0,-1,0,62,62,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00401",4,"Si en tu casa te regañan,\ndi á voces que no me quieres:\ncon esto quedarás bien,\ny háblame cuando pudieres.",4,0,-1,66,"",0,4,"ee",55,0,-1,0,62,62,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00402",4,"A San Nicolás me voy,\nde San Nicolás me vengo,\ná pedirle al santo mío\npor una novia que tengo.",4,0,-1,66,"",0,4,"eo",124,0,-1,0,62,62,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00403",4,"Aunque para mí no seas,\nsiempre te tendré afición,\nporque eres disimulada\ncuando llega la ocasión.",4,0,-1,66,"",0,4,"o",31,0,-1,0,62,62,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00404",4,"Fuí anoche á Capuchinos\ná rezarle á Cristo un credo;\npor decir: «Creo en Dios padre,»\ndije: «Creo en la que quiero.»",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,62,62,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00405",4,"Anoche me dió la una\nplaticando con mi amor;\nesta noche, si Dios quiere,\nme dan lo menos las dos.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,62,62,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00406",4,"El nombre de mi moreno\neso no lo diré yo,\nporque no quiero que sepan\ndonde tengo mi afición.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,62,62,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00407",4,"Me han quitado el ir á misa,\nme han quitado el confesar,\nme han quitado que te quiera:\n¿qué más me pueden quitar?",4,0,-1,66,"",0,4,"a",21,0,-1,0,62,62,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00408",4,"Enamoradita estoy,\npero no lo sabe nadie:\ntengo el amor forastero\ny no me ronda la calle.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,62,62,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00409",4,"Cuando te encuentro en la calle\nla sangre se me rebota,\ny se me quiere salir\nel corazón por la boca.",4,0,-1,66,"",0,4,"oa",-1,0,-1,0,62,62,"","",1,"rm_t2, lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00410",4,"Todos me dicen que tengo\nojitos de religiosa,\ny yo digo que los tengo\nde casada cariñosa.",4,0,-1,66,"",1,4,"oa",63,0,-1,0,62,62,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00411",4,"Cuando te encuentro en la calle\ny no me dices adiós,\nni las ánimas benditas\npenan tanto como yo.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,62,62,"","",1,"lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00412",4,"No soy bonita que asombre,\nni fea que cause miedo:\nsoy morenita con gracia,\ny así me quiere mi dueño.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,62,62,"","",1,"","","",3,0,0,[],""],["palau_cantares-00413",4,"A Jesús triste le rezo,\n¿y sabes lo que le pido?\nQue el día que tú te mueras\ntambién me muera contigo.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,62,62,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00414",4,"La pimienta es chica y pica\ny sazona los guisados,\ny tú, como pequeñita,\nhasta el alma me has picado.",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,62,62,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00415",4,"Dueño mío, si te vieres\nen la presencia de Dios,\nle pedirás que me muera,\nque sin ti no vivo yo.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,62,62,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00416",4,"Una rubia como tú\ny de tu propio salero\nme tiene robada el alma\ny el corazón prisionero.",4,0,-1,66,"",0,4,"eo",38,0,-1,0,62,62,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00417",4,"El día que tú naciste,\naquel día nací yo;\nel día que tú te mueras\nnos moriremos los dos.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,62,62,"","",1,"lafuente_madrid","","",16,0,0,[],""],["palau_cantares-00418",4,"Si con el mirar te ofendo\ny con el hablar te agravio,\nyo me vendaré los ojos\ny me coseré los labios.",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00419",4,"Como la campana tiene\nfundidos siete metales,\nasí tengo tu cariño\nen la masa de la sangre.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,63,63,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00420",4,"Si mi Soledad quisiera,\nle regalara un pañuelo\ncon cuatro borlitas de oro\ny mi corazón en medio.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,63,63,"","",1,"","","",2,0,0,[],""],["palau_cantares-00421",4,"En el mirar solamente\nconocerás que te quiero,\ny también conocerás\nque quiero hablarte y no puedo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00422",4,"Al verte llaman la muerte,\ny al no verte llaman vida:\nmás quiero morir y verte,\nque no verte y tener vida.",4,0,-1,66,"",1,4,"ia",-1,0,-1,0,63,63,"","",1,"","","",1,0,0,[],""],["palau_cantares-00423",4,"Tus ojitos y los míos\nse miran con afición\ny parece que se dicen\nlo que siente el corazón.",4,0,-1,66,"",0,4,"o",31,0,-1,0,63,63,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00424",4,"Por dondequiera que voy\nparece que te voy viendo,\ny es la sombra del querer\nque me viene persiguiendo.",4,0,-1,66,"",0,4,"eo",52,0,-1,0,63,63,"","",1,"","","",3,0,0,[],""],["palau_cantares-00425",4,"Si las piedras de tu calle\nse volvieran migueletes,\ntodos los atrepellara\nsólo por venir á verte.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,63,63,"","",1,"","","",6,0,0,[],""],["palau_cantares-00426",4,"Si yo abiyelara el mando\nque un divé le dió á la muerte,\nyo quitara de este mundo\ná quien me estorba quererte.",4,0,-1,66,"",0,4,"ee",134,0,-1,0,63,63,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00427",4,"Al que me estorba quererte\nen tu calle mataré;\nsi al salir ves una cruz,\nno preguntes por quién es.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00428",4,"Desde tu casa á la iglesia\nhe de plantar una parra\npara que vayas á misa\nsin darte el sol en la cara.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00429",4,"Salero, por tu salero\ná la mar me arrojaría;\npero por otro salero\nen mi casa me estaría",4,0,-1,66,"",1,4,"ia",0,0,-1,0,63,63,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00430",4,"Al pie de la hierbabuena\ncinco claveles te dí,\ny eran los cinco sentidos,\nserrana, que puse en ti.",4,0,-1,66,"",0,4,"i",23,0,-1,0,63,63,"","",1,"","","",1,0,0,[],""],["palau_cantares-00431",4,"Si mi madre fuera mora\ny me pariera en Argel,\nrenegara de Mahoma\nsólo por venirte á ver.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00432",4,"Yo no sé lo que me has dado\npara que tanto te quiera,\nque me has hecho que me olvide\nde mi familia y mi tierra.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,63,63,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00433",4,"Al león, con ser león,\ndicen que lo rinde el sueño;\ny yo, criatura humana,\nde pensar en ti no duermo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,63,63,"","",1,"","","",1,0,0,[],""],["palau_cantares-00434",4,"A esa niña de mis ojos\nno me la pongas delante,\nque como la quiero tanto,\nel corazón se me parte.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00435",4,"Si lo que de noche sueño,\nde día lo ejecutara,\ná la casa de los locos\nde seguro me llevaran.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00436",4,"Bendita sea la hora\nque te comencé á querer,\nbenditos tu padre y madre,\ny tú bendita también.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,63,63,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00437",4,"Ni comiendo, ni bebiendo,\nni andando, ni trabajando,\ntiene mi penita alivio,\nsino que te estoy mirando.",4,0,-1,66,"",0,4,"ao",33,0,-1,0,63,63,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00438",4,"Las fatigas de un enfermo\ncuando está para morir,\nson las que paso, bien mío,\ncuando me acuerdo de ti.",4,0,-1,66,"",0,4,"i",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00439",4,"Si con vender yo mis carnes\nle diera alivio á tus penas,\ná la voz de un pregonero\npor las calles las vendiera.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00440",4,"A los moros que te vayas\ná renegar de la fe,\ntengo de marchar contigo\ná renegar yo también.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00441",4,"Al que expiró en el madero\nle pido de corazón\nque no te cases con nadie\nhasta que me muera yo.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,64,64,"","",1,"","","",1,0,0,[],""],["palau_cantares-00442",4,"Más humilde que la tierra\nme parió mi madre á mí;\ndime, niña, quién te ofende,\nverás á un león reñir.",4,0,-1,66,"",0,4,"i",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00443",4,"Hasta que vea tu fin\nen lo que viene á parar,\nni le doy palabra á nadie,\nni menos me he de casar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,64,64,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00444",4,"Si supiera ó entendiera\nque el sol que sale te ofende,\ncon el sol me peleara\naunque el sol me diera muerte.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,64,64,"","",1,"lafuente_madrid, fernan_caballero","","",11,0,0,[],""],["palau_cantares-00445",4,"Tienes dos corazones,\nyo no lo dudo,\nporque tienes el mío\ndentro del tuyo.",4,0,-1,66,"",6,4,"uo",-1,0,-1,0,64,64,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00446",4,"¿Sabes á lo que me atrevo,\nmozuela, por tu querer?\nA meterme en los infiernos\ny hablar con el Lucifer.",4,0,-1,66,"",0,4,"e",20,0,-1,0,64,64,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00447",4,"Cada vez que te veo,\npara mí digo:\ná mi prójimo amo\ncomo á mí mismo.",4,0,-1,66,"",6,4,"io",-1,0,-1,0,64,64,"","",1,"rm_t2, fernan_caballero","","",6,0,0,[],""],["palau_cantares-00448",4,"Mándame, niña, que vaya\ná la gran Constantinopla,\ny verás cómo te traigo\ndel gran turco la corona.",4,0,-1,66,"",0,4,"oa",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00449",4,"Tengo yo mi corazón\ntan hechecito á mis mañas,\nque le digo «llora» y llora,\nque le digo «canta» y canta.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,64,64,"","",1,"","","",14,0,0,[],""],["palau_cantares-00450",4,"Se me oprime el corazón\nal ver tu vestido negro,\nque la sombra de tu pena\ná mí me da sentimiento.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,64,64,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00451",4,"Como carnerillo manso\nsales al campo á buscarme,\ny yo te estoy aguardando,\nsangrecilla de mi sangre.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00452",4,"¡Mal haya la ropa negra\ny el sastre que la cortó,\nque mi niña tiene luto\nsin haberme muerto yo!",4,0,-1,66,"",0,4,"o",2,0,-1,0,64,64,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00453",4,"Pide á Dios por mi salud,\nmorena, que si me muero,\nla casilla de los locos\nha de ser tu paradero.",4,0,-1,66,"",0,4,"eo",38,0,-1,0,64,64,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00454",4,"Dime por quién tienes luto\npara usarlo yo también,\nporque tú triste y yo alegre,\neso no parece bien.",4,0,-1,66,"",0,4,"e",242,0,-1,0,64,64,"","",1,"","","",3,0,0,[],""],["palau_cantares-00455",4,"Compañerita del alma,\narrímate á mi querer,\ncomo las salamanquesas\nse arriman á la pared.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",20,0,0,[],""],["palau_cantares-00456",4,"Cuando te veo con pena,\nen mí no cabe alegría,\npues como te quiero tanto,\nsiento la tuya y la mía.",4,0,-1,66,"",0,4,"ia",0,0,-1,0,64,64,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00457",4,"Mañana voy á cabildo\ná ver echar el sorteo,\ny si le toca á mi amante,\ndiré que por él me quedo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,64,64,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00458",4,"Debajo de tu ventana\nme quisieron dar la muerte,\nlucero de la mañana,\nsólo por venir á verte.",4,0,-1,66,"",1,4,"ee",134,0,-1,0,65,65,"","",1,"rm_t2, lafuente_madrid","","",29,0,0,[],""],["palau_cantares-00459",4,"Tengo yo mi corazón\nhechito cuatro pedazos;\npero me queda el consuelo\nque he de morir en tus brazos.",4,0,-1,66,"",0,4,"ao",132,0,-1,0,65,65,"","",1,"rm_t2, lafuente_madrid","","",14,0,0,[],""],["palau_cantares-00460",4,"Compañerita del alma,\nhazme con los ojos señas,\nque en algunas ocasiones\nlos ojos sirven de lengua.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,65,65,"","",1,"lafuente_madrid","","",20,0,0,[],""],["palau_cantares-00461",4,"¿Sabes por qué no me caso\nconsiderándote á ti?\nPorque en viéndome en tus brazos\npienso que me he de morir.",4,0,-1,66,"",0,4,"i",-1,0,-1,0,65,65,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00462",4,"Mi amante me dijo anoche\nque cantara y no llorara;\nque echara penas al aire,\npero que no lo olvidara.",4,0,-1,66,"",0,4,"aa",57,0,-1,0,65,65,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00462-e2",4,"Nadie de amor se burle,\ny en mí escarmiente,\nque amor también se burla\nde sus rebeldes;\ny yo confieso\nque desprecié sus grillos\ny ahora los beso.",4,0,-1,66,"",4,7,"eo",48,0,-1,0,65,65,"","",1,"","","",3,0,0,[],""],["palau_cantares-00462-e3",4,"El sol de tu belleza\ntodo ¡o alumbra,\nmenos á mi esperanza,\n' que deja á obscuras;\ny entre tinieblas,\nmi amor en tus desdenes\nsiempre tropieza.",4,0,-1,66,"",4,7,"ea",-1,0,-1,0,65,65,"","",1,"","","",1,0,0,[],""],["palau_cantares-00463a",4,"Mirando estoy desde aquí\nla que tiene que ser mía,\nla que tiene que juntar\nsu carita con la mía.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,65,65,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00463b",4,"Encimita de tu frente\nte lo tengo de escribir:\npondré una a y una m,\ny entre las dos una i.",4,0,-1,66,"",0,4,"i",-1,0,-1,0,65,65,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00463c",4,"¿Cuándo querrá Dios del cielo\nque yo te encuentre en la calle\ny te diga: Mira, oye,\ndónde pusiste la llave?",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,65,65,"","",1,"","","",11,0,0,[],""],["palau_cantares-00463d",4,"Si con hechizos pudiera\nesta noche hablar contigo,\nbien sabe Dios que lo hiciera\npor dar á mi pena alivio.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,65,65,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00464",4,"Si quieres venirte, vente;\nsi quieres estarte, estáte;\nnos quedaremos á solas,\nque tengo que platicarte.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,65,65,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00466",4,"Valientemente, muchacha,\nDios te dió sabiduría;\nuna palabra que hablas\nvale por doscientas mías.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,65,65,"","",1,"fernan_caballero","","",2,0,0,[],""],["palau_cantares-00468a",4,"¡Qué triste y qué pensativa\nestá la prenda que adoro!\n¿Qué cariñito le haré\npara quitarle el enojo?",4,0,-1,66,"",0,4,"oo",-1,0,-1,0,65,65,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00468b",4,"Mi morena se ha enojado\nporque no le dije adiós.\nAdiós, morena del alma;\ns, morenita, adiós.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,65,65,"","",1,"","","",4,0,0,[],""],["palau_cantares-00469",4,"Ese querer tuyo y mío\nparece que está de Dios;\ncuanto más nos lo murmuran,\nmás nos queremos los dos.",4,0,-1,66,"",0,4,"o",87,0,-1,0,65,65,"","",1,"","","",1,0,0,[],""],["palau_cantares-00470",4,"Mi amor me dice de usted,\ny yo lo mismo le digo,\ny en estando los dos solos,\nde tú por tú nos decimos.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,66,66,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00470-e2",4,"Ya no se estila decir:\n¡viva el oro, viva el oro!,\nque sólo se dice ahora:\n¡viva la prenda que adoro!",4,0,-1,66,"",0,4,"oo",85,0,-1,0,66,66,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00470-e3",4,"Viva Cádiz, viva el Puerto,\nviva quien sabe querer,\nviva quien pasa en el mundo\npenas por una mujer.",4,0,-1,66,"",0,4,"e",20,0,-1,0,66,66,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00470-e4",4,"He estado en el purgatorio\ny he visto todas las penas,\ny he visto que por querer\nningún alma se condena.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,66,66,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00470-e5",4,"Yo quiero bien, y no puedo\ndecir á quién quiero bien;\ntan sólo diré que quiero\nsólo por sólo querer.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,66,66,"","",1,"rm_t2, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-00470-e6",4,"Mis amores son del campo\ny no vienen al lugar;\nmis suspiros son correos,\nque unos vienen y otros van.",4,0,-1,66,"",0,4,"a",-1,0,-1,0,66,66,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00470-e7",4,"Del hueso de una aceituna\ntengo que hacer una nave\npara que vayan y vengan\nmis suspiros por el aire.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,66,66,"","",1,"rm_t3, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00470-e8",4,"Las estrellas he contado\npara ver la que me sigue:\ná mí me sigue una estrella\nchiquitita, pero firme.",4,0,-1,66,"",0,4,"ie",-1,0,-1,0,66,66,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00470-e9",4,"Tengo una puñaladita\nque me la dio una mujer;\nen toda mi vida he visto\npuñalada más cruel.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,66,66,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00471",4,"La dulce tiranía\nde la hermosura\nrinde, triunfa, avasalla,\nmas poco dura.\nY es la desgracia\nque pasa desde el trono\ná ser esclava.",4,0,-1,66,"",4,7,"aa",-1,0,-1,0,66,66,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-00471-e2",4,"Dicen que me has de matar\ncon un puñal valenciano:\nyo te perdono la muerte\nsi me matas con tu mano.",4,0,-1,66,"",0,4,"ao",81,0,-1,0,66,66,"","",1,"","","",3,0,0,[],""],["palau_cantares-00471-e3",4,"Te quiero más que á la sangre\nque me corre por las venas;\nel día que no te veo\nme ahoga la pena negra.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,66,66,"","",1,"","","",3,0,0,[],""],["palau_cantares-00471-e4",4,"No sé qué estrella es la tuya\nque domina sobre mí:\ná nadie me he sujetado\ny me sujeto ahora á ti.",4,0,-1,66,"",0,4,"i",23,0,-1,0,66,66,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00471-e5",4,"El día que me dijiste\nque era tuya el alma mía,\nlas lágrimas de los ojos\nde gozo se me caían.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,66,66,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00472",4,"Cuando me dijeron que era\ntrabajo en balde el quererte,\nme pareció que llegaba\nel tránsito de mi muerte.",4,0,-1,66,"",0,4,"ee",134,0,-1,0,66,66,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00472-e2",4,"Acuérdate que te di\nla llave de mi pechito:\nalgunos la pretendieron,\ny á ti te la di sólito.",4,0,-1,66,"",5,4,"oo",-1,0,-1,0,66,66,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00472-e3",4,"Si el rey, con ser rey, me diera\nescudo, cetro y corona,\nno lo apreciara yo tanto\ncomo aprecio tu persona.",4,0,-1,66,"",0,4,"oa",7,0,-1,0,66,66,"","",1,"","","",1,0,0,[],""],["palau_cantares-00472-e4",4,"Dentro de mi pecho tengo\nuna sala de cristal\ny una antesala de oro\ndonde habita esa deidad.",4,0,-1,66,"",0,4,"a",-1,0,-1,0,66,66,"","",1,"rm_t2, lafuente_madrid","","",32,0,0,[],""],["palau_cantares-00473",4,"Desde aquel feliz instante\nque alma y vida te rendí,\nhice voto de adorarte\ny no adorar más que á ti.",4,0,-1,66,"",0,4,"i",23,0,-1,0,67,67,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00474",4,"Por una Pepita muero,\nPepita y no de melón,\nque es Pepita que yo tengo\ndentro de mi corazón.",4,0,-1,66,"",0,4,"o",31,0,-1,0,67,67,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00475",4,"Aunque soy pequeñita\ncomo un tomillo,\nme pretende un muchacho\ncomo un castillo.",4,0,-1,66,"",6,4,"io",228,0,-1,0,67,67,"","",1,"","","",1,0,0,[],""],["palau_cantares-00476",4,"Cada vez que digo ramo\nse me alegra el corazón\nporque Ramona se llama\nla prenda que adoro yo.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,67,67,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00477",4,"Por tres cosas te he querido:\npor morena, por alegre\ny por los ojos dormidos\nque aprisionado me tienen.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,67,67,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00478",4,"No salga la luna,\nque no tiene á qué:\ncon los ojitos de mi compañera\nyo me alumbraré.",4,0,-1,66,"",3,4,"e",77,0,-1,0,67,67,"","",1,"","","",1,0,0,[],""],["palau_cantares-00479",4,"Mis padres dicen que quiera\ná una que tenga doblones;\nyo no quiero la moneda,\nque en ti he puesto mis amores.",4,0,-1,66,"",0,4,"oe",-1,0,-1,0,67,67,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00480",4,"San Antonio portugués,\ndevoto de lo perdido,\nmi amante se perdió anoche:\n¡buscádmelo, santo mío!",4,0,-1,66,"",0,4,"io",-1,0,-1,0,67,67,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00481",4,"Los mocitos de mi barrio\ndicen que no soy valiente;\ncontéstales tú, morena,\nque me he atrevido á quererte.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,67,67,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00482",4,"Gracias á Dios, madre mía,\nque ya pareció el perdido;\nnunca se puede perder\npájaro que tiene nido.",4,0,-1,66,"",0,4,"io",101,0,-1,0,67,67,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00483",4,"Entre Úbeda y Baeza\nhay un molino que muele\nazúcar, canela y clavo,\nlo que mi morena tiene.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,67,67,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00484",4,"¡Mira con qué disimulo\nte vas esa calle arriba,\nsin reparar que te dejas\ná una serrana cautiva!",4,0,-1,66,"",0,4,"ia",53,0,-1,0,67,67,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00485",4,"Si queréis saber, señores,\ncómo se llama mi majo,\nacordaos de aquel ángel\nque tiene al diablo debajo.",4,0,-1,66,"",0,4,"ao",168,0,-1,0,67,67,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-00486",4,"La noche que tronó tanto\nfuí á buscar á mi novia,\npor si se acababa el mundo,\nirme arrimando á la gloria.",4,0,-1,66,"",0,4,"oa",-1,0,-1,0,67,67,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00487",4,"Si queréis saber, señores,\nel nombre de mi querido,\nacordaos de aquel santo\nque lleva un ramo florido.",4,0,-1,66,"",0,4,"io",101,0,-1,0,67,67,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-00488",4,"Por el camino real\nva una doncellita triste\nen busca de sus amores:\nno hay mata que no registre.",4,0,-1,66,"",0,4,"ie",-1,0,-1,0,67,67,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00489",4,"Pepe quiero, Pepe adoro,\nPepe tengo en la memoria;\ncada vez que digo «¡Pepe!,»\nparece que digo «¡gloria!»",4,0,-1,66,"",0,4,"oa",126,0,-1,0,67,67,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00490",4,"Santa Teresita tiene\nla paloma en el oído,\ny yo quisiera tener\nde mi amante el apellido.",4,0,-1,66,"",0,4,"io",101,0,-1,0,67,67,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00491",4,"La cartilla del amor\nla pasé letra por letra,\ny así que llegué á la P,\nme quedé diciendo: ¡Pepa!",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,67,67,"","",1,"","","",5,0,0,[],""],["palau_cantares-00492",4,"A San José pido el ramo,\ná San Francisco el cordón,\ná Santa Rita la espina,\ny á mi amante el corazón.",4,0,-1,66,"",0,4,"o",31,0,-1,0,67,67,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00493",4,"Mi querer y tu querer\nson dos quereres en uno,\ny siempre estamos riñendo\npor si es mío ó por si es tuyo.",4,0,-1,66,"",0,4,"uo",-1,0,-1,0,68,68,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00494",4,"En los llanos de Motril\nme puse á echar un cigarro,\ny acordándome de ti,\nse me cayó de la mano.",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,68,68,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00495",4,"Siempre que te vas, me dices:\n«Adiós, hasta la primera.»\nComo no me dices cuándo,\nsiempre me dejas con pena.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,68,68,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00496",4,"Tus bellos ojos matan,\nroban, saltean,\ny con ser malhechores,\nno hay quien los prenda:\nporque, homicidas,\njamás rinden sus armas\ná la justicia.",4,0,-1,66,"",4,7,"ia",-1,0,-1,0,68,68,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00497",4,"Amor, no digas adiós\ncuando por la calle vas,\nque parece que me dices:\n¡adiós para nunca más!",4,0,-1,66,"",0,4,"a",51,0,-1,0,68,68,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00497-e2",4,"Morena, si bien me quieres,\nno se lo digas á nadie,\nponte la mano en el pecho,\ndile al corazón que calle.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,68,68,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00497-e3",4,"Pensando en ti me dormí,\nhermosura de los cielos,\ny al despertar me encontré\nsin mí, sin ti y sin consuelo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,68,68,"","",1,"","","",9,0,0,[],""],["palau_cantares-00497-e4",4,"De la uva sale el vino,\nde la aceituna el aceite,\ny de mi pechito sale\ncariño para quererte.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,68,68,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00497-e5",4,"Toma este puñal dorado\ny ábreme el pecho con él:\npor el color de la sangre\nverás si te quiero bien.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,68,68,"","",1,"","","",6,0,0,[],""],["palau_cantares-00497-e6",4,"Quitarme de que te quiera\nes quitarme la salud,\nporque á la chiticallando\nmi vida la tienes tú.",4,0,-1,66,"",0,4,"u",-1,0,-1,0,68,68,"","",1,"","","",3,0,0,[],""],["palau_cantares-00498a",4,"Si mirando risueña\ntus ojos matan,\n¿qué será, vida mía,\nmirando airada?\nSi vibran rayos\ntus dos ojos, serenos,\n¿qué harán nublados?",4,0,-1,66,"",4,7,"ao",-1,0,-1,0,68,68,"","",1,"","","",1,0,0,[],""],["palau_cantares-00498b",4,"Hasta el alma me ha llegado\nla raiz de tu querer:\nsi no es verdad lo que digo,\nmalapuñalá me den.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,68,68,"","",1,"","","",2,0,0,[],""],["palau_cantares-00498c",4,"Te quiero más que me quieres,\nmis obras te lo dirán;\ny si no, déjalo al tiempo,\nque es padre de la verdad.",4,0,-1,66,"",0,4,"a",-1,0,-1,0,68,68,"","",1,"rm_t2, lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00498d",4,"Te quiero más que me quieres,\nen eso no admitas duda;\nque una mujer arrestada\nno teme cosa ninguna.",4,0,-1,66,"",0,4,"ua",-1,0,-1,0,68,68,"","",1,"rm_t2, lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00499",4,"A la mar van á parar,\nMaría, todos los ríos,\ny allí se irán á juntar\ntus amores y los míos.",4,0,-1,66,"",1,4,"io",135,0,-1,0,68,68,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00500",4,"Te quiero sin que me quieras,\nque es verdadero querer;\nque querer porque nos quieran\nes querer por interés.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,68,68,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00501",4,"Me dices que no me quieres,\ny es mentira, que me engañas;\nque estoy leyendo en tus ojos\nlo que me quiere tu alma.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,68,68,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00502",4,"La fundación del querer\ná mí me pueden llamar,\nporque he sido en tus amores\nla piedra fundamental.",4,0,-1,66,"",0,4,"a",-1,0,-1,0,68,68,"","",1,"lafuente_madrid, preciso_coleccion","","",6,0,0,[],""],["palau_cantares-00503a",4,"Es tu pelo cadena\nde muchas almas,\ny cuanto más lo sueltas,\nmejor las atas;\ny como es de oro,\nla prisión no hace mella,\nporque da gozo.",4,0,-1,66,"",4,7,"oo",-1,0,-1,0,69,69,"","",1,"","","",2,0,0,[],""],["palau_cantares-00503b",4,"Dame, niña, tus ojos\npor esta noche,\nporque quiero con ellos\nmatar á un hombre:\ny no te admire\nque te pida unas armas\nque tanto rinden.",4,0,-1,66,"",4,7,"ie",-1,0,-1,0,69,69,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00503c",4,"Como tú me llevaras\nadonde fueras,\nen yendo yo contigo,\nmas que no vuelvas.",4,0,-1,66,"",6,4,"ea",-1,0,-1,0,69,69,"","",1,"preciso_coleccion","","",3,0,0,[],""],["palau_cantares-00503d",4,"Todas las enfermedades\nse me curan si me miras:\nsin duda tus ojos son\nbálsamo de mis heridas.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,69,69,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00503e",4,"Tendido sobre una estera,\nvestido con la mortaja,\nsi te viera entrar á ti,\nde fe que resucitaba.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,69,69,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00503f",4,"Es preciso que soñando\nte hable con el deseo:\nmis fatigas son tan grandes,\nque estoy durmiendo y te veo.",4,0,-1,66,"",0,4,"eo",66,0,-1,0,69,69,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00503g",4,"Todas las horas del día\nle estoy pidiendo á Jesús\nque por su pasión y muerte\nme lleve donde estás tú.",4,0,-1,66,"",0,4,"u",-1,0,-1,0,69,69,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00504a",4,"¡Qué triste que va la luna\ncuando no lleva lucero!\nAsí está mi corazón\nel día que no te veo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,69,69,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00504b",4,"Aquel lucero que sale\npor detrás de las cabrillas\nes el que á mí me acompaña\ncuando voy á verte, niña.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,69,69,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00504c",4,"Cuando por tu puerta paso\ny te veo en la ventana,\nse me alegra el corazón\npara toda la semana.",4,0,-1,66,"",0,4,"aa",4,0,-1,0,69,69,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00504d",4,"Si el amor en el mundo\nllega á perderse,\nse ha de hallar en mi pecho,\nque aquí está siempre;\npero está sólo\nempleado en la prenda\nque firme adoro.",4,0,-1,66,"",4,7,"oo",-1,0,-1,0,69,69,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00504e",4,"Échame una maldición,\nuna maldición gitana:\nque los ángeles me lleven\nen procesión á tu cama.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,69,69,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00504f",4,"Morena, morena eres,\nmal haya tu morenura,\nque me tienes en la cama\nsin frío v con calentura.",4,0,-1,66,"",0,4,"ua",17,0,-1,0,69,69,"","",1,"","","",3,0,0,[],""],["palau_cantares-00504g",4,"No desprecies lo moreno,\nque vale más que la plata,\nporque morenita es\nla prenda que á mí me mata.",4,0,-1,66,"",0,4,"aa",74,0,-1,0,69,69,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00505",4,"Tengo yo mi corazón\nmás negro que el terciopelo\nde ver que no puedo hablarte\ntodas las horas que quiero.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,69,69,"","",1,"rm_t2, lafuente_madrid","","",14,0,0,[],""],["palau_cantares-00506",4,"¡Válgame Dios, qué dolores,\nqué fatigas y qué penas\npasan á veces los hombres\npor una cara morena!",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,69,69,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00507",4,"Permita el cielo que un rayo...\nPero no..., ¡detente, lengua!,\nque no quiero que por mí\ndaño á mi amante le venga.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,69,69,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00508",4,"En el río la encontré,\nasentadita en la arena;\nella no me dijo nada;\nyo le dije: abur, morena.",4,0,-1,66,"",0,4,"ea",59,0,-1,0,69,69,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00509",4,"Mira si he corrido tierras,\nque he estado en la Gran Turquía:\nen ninguna parte vi\nmorena como la mía.",4,0,-1,66,"",0,4,"ia",0,0,-1,0,70,70,"","",1,"rm_t2, lafuente_madrid","","",15,0,0,[],""],["palau_cantares-00510",4,"Una mora me enamora,\ny no es mora de nación;\nes mora porque ella mora\ndentro de mi corazón.",4,0,-1,66,"",1,4,"o",31,0,-1,0,70,70,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00511",4,"Ay, que se me lleva el aire,\nay, que el aire se me lleva,\nay, que se me lleva el aire,\nel aire de mi morena.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,70,70,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00512",4,"Una morena me mata,\nuna rubia me hace el hoyo,\ny una muchacha de á quince\nme saca del purgatorio.",4,0,-1,66,"",0,4,"oo",-1,0,-1,0,70,70,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00513",4,"Tú encendistes el fuego\ndel pecho mío,\ny ahora vas á apagarle\ncon tus suspiros:\n¡válgame el cielo,\ny qué poco que entiendes\nde estos incendios!",4,0,-1,66,"",4,7,"eo",-1,0,-1,0,70,70,"","",1,"","","",2,0,0,[],""],["palau_cantares-00514",4,"Dichoso es aquel que tiene\namores en el lugar,\nque yo, que los tengo fuera,\nlos tengo que ir á buscar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,70,70,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00515",4,"Quiero que en mi sepulcro\nse pongan cirios,\nprendidos en el fuego\nde mis suspiros;\ny si se apagan,\nque acudan á mi pecho\ny hallarán llama.",4,0,-1,66,"",4,7,"aa",-1,0,-1,0,70,70,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00516a",4,"Si porque te quiero, quieres\nque yo la muerte reciba,\ncúmplase tu voluntad:\nmuera yo, porque otro viva.",4,0,-1,66,"",0,4,"ia",53,0,-1,0,70,70,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-00516b",4,"No me mates con cuchillo,\nque tiene el acero fuerte,\nmátame con un suspiro\ny te perdono la muerte.",4,0,-1,66,"",0,4,"ee",134,0,-1,0,70,70,"","",1,"frenk_t1","","",7,0,0,[],""],["palau_cantares-00517",4,"El alma me has robado,\ndame la tuya,\nque el ladrón es preciso\nque restituya.",4,0,-1,66,"",6,4,"ua",111,0,-1,0,70,70,"","",1,"preciso_coleccion","","",5,0,0,[],""],["palau_cantares-00518",4,"Para rey nació David,\npara sabio Salomón,\npara llorar Jeremías,\ny para quererte yo.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,70,70,"","",1,"machado_venezuela, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00519",4,"Amores, amores tengo,\nno los quisiera tener,\nque un hombre se pone tonto\nen queriendo á una mujer.",4,0,-1,66,"",0,4,"e",20,0,-1,0,70,70,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00520",4,"Todas las mañanas voy\ná la orillita del río\ná preguntar á sus aguas\nsi han visto al cariño mío.",4,0,-1,66,"",0,4,"io",3,0,-1,0,70,70,"","",1,"","","",12,0,0,[],""],["palau_cantares-00521",4,"Si supiera que en el mundo\nse vendían corazones,\npara mí comprara uno,\nporque el mío está en prisiones.",4,0,-1,66,"",0,4,"oe",34,0,-1,0,70,70,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00522",4,"María del alma mía,\nimán de mi corazón,\nserafín de mi albedrío\ny norte de mi pasión.",4,0,-1,66,"",0,4,"o",31,0,-1,0,70,70,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00523",4,"- Corazón enamorado,\ndime, ¿quién te enamoró?\n- Una niña de quince años\nque á dieciséis no llegó.",4,0,-1,66,"",0,4,"o",2,0,-1,0,70,70,"","",1,"","","",3,0,0,[],""],["palau_cantares-00524",4,"María, tu enamorado\nronda la calle á deshora,\ny de ver que tú no sales,\ngotitas de sangre llora.",4,0,-1,66,"",0,4,"oa",107,0,-1,0,70,70,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00525",4,"Una mora me enamora,\nuna blanca me da pena,\nuna descoloridita\nme tiene preso en cadena.",4,0,-1,66,"",0,4,"ea",59,0,-1,0,70,70,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00526",4,"Dame una rosa, María,\ny cógela con tu mano,\nporque me han dicho que tienes\nun rosalito temprano.",4,0,-1,66,"",0,4,"ao",81,0,-1,0,70,70,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00527",4,"Bien de mi vida, María,\nconsuelo de mi dolor,\nflor la más bella y más pura\nde un fragantísimo olor.",4,0,-1,66,"",0,4,"o",72,0,-1,0,71,71,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00527-e10",4,"Mucho quiero á San Francisco,\nporque tiene cinco llagas;\npero más te quiero á ti,\nporque Francisca te llamas.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,71,71,"","",1,"lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00527-e2",4,"La sirena de la mar\nembelesa á quien la oye;\ntambién me embelesa á mí,\nMaría, tu dulce nombre.",4,0,-1,66,"",0,4,"oe",-1,0,-1,0,71,71,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00527-e3",4,"Todas las aves del mundo\nnacieron para volar,\ny las manos de María\npara coser y bordar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,71,71,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00527-e4",4,"Hágame usté un San Joaquín\nque sea de plata fina,\nque la prenda que yo adoro\ntambién se llama Joaquina.",4,0,-1,66,"",3,4,"ia",11,0,-1,0,71,71,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00527-e5",4,"Tomaré una calavera\ny un Santo Cristo de estambre\ny me iré á hacer penitencia\ncon Mariquita del Carmen.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,71,71,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00527-e6",4,"San Antonio está en el cielo,\neso no lo ignoro yo,\ny también está en la tierra\nla Antonia que adoro yo.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,71,71,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00527-e7",4,"La estampa de San Antonio\nsiempre la llevo en el pecho:\ncuando me acuerdo de Antonio,\nsaco la estampa, y la beso.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,71,71,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00527-e8",4,"San Antonio lleva el niño,\nSanto Domingo la estrella,\ny San Juan lleva la palma:\nentiéndame quien me entienda.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,71,71,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00527-e9",4,"Por un Pepe diera un cuarto,\npor un Francisco un doblón,\ny por un Antonio diera\nalma, vida y corazón.",4,0,-1,66,"",0,4,"o",31,0,-1,0,71,71,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00528",4,"Pescador soy, señora,\nque en la ribera\ntiendo al amor las redes\npara que muera;\npero es el cuento\nque, trocadas las suertes,\ncaigo yo dentro.",4,0,-1,66,"",4,7,"eo",-1,0,-1,0,71,71,"","",1,"","","",1,0,0,[],""],["palau_cantares-00528-e2",4,"Vieron los ojos míos\ntu cara bella,\ny ahora la tal mirada\ncara me cuesta;\npues dijo el alma:\n¡qué cara tan divina!,\npero ¡qué cara!",4,0,-1,66,"",4,7,"aa",-1,0,-1,0,71,71,"","",1,"","","",1,0,0,[],""],["palau_cantares-00528-e3",4,"Si mil almas tuviera,\nte diera juntas:\ntoma, pues no las tengo,\nmil veces una:\nque si lo adviertes,\nes más que las mil juntas\nuna mil veces.",4,0,-1,66,"",4,7,"ee",-1,0,-1,0,71,71,"","",1,"","","",2,0,0,[],""],["palau_cantares-00528-e4",4,"Ya sabes que estoy á gusto\ncuando te tengo á mi vera;\nlas fatigas de Dios paso\ncuando te vas y me dejas.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,71,71,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00528-e5",4,"Siéntate á la vera mía,\nsiquiera por un minuto,\ny le darás á mi cuerpo\nese ratillo de gusto.",4,0,-1,66,"",0,4,"uo",-1,0,-1,0,71,71,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00528-e6",4,"Ya que no te puedo hablar\nponte donde yo te vea;\nle daré gusto á mis ojos,\nya que otra cosa no sea.",4,0,-1,66,"",0,4,"ea",54,0,-1,0,71,71,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00528-e7",4,"Vale más la bizarría\ndel galán que me enamora,\nque toda la Andalucía\ny la vega de Carmona.",4,0,-1,66,"",0,4,"oa",-1,0,-1,0,71,71,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00528-e8",4,"Muchos hay que no pueden\ndecir sus penas,\nporque al querer decirlas\nse ahogan con ellas:\ny así las mías\nno podrás comprenderlas,\nni yo decirlas.",4,0,-1,66,"",4,7,"ia",-1,0,-1,0,71,71,"","",1,"","","",3,0,0,[],""],["palau_cantares-00529a",4,"Cada vez que me miras\ny yo te miro,\nte digo con los ojos\nlo que no digo.\nComo no hallo\nque tú me correspondas,\nte miro y callo.",4,0,-1,66,"",4,7,"ao",102,0,-1,0,72,72,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00529b",4,"Con un sí de tus labios\nmi amor se paga:\nmira qué poco pido,\ndos letras, nada.\nSé compasiva,\nque con un sí tan sólo\nme das la vida.",4,0,-1,66,"",4,7,"ia",-1,0,-1,0,72,72,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00529c",4,"Toda mi vida estuviera\npreso en la cárcel de amor,\nsiendo tú la carcelera\ny yo el alguacil mayor.",4,0,-1,66,"",1,4,"o",72,0,-1,0,72,72,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00529d",4,"Si tu casa fuera cárcel,\ny tu cuarto calabozo,\ny tus brazos la cadena,\nyo prisionero gustoso.",4,0,-1,66,"",0,4,"oo",160,0,-1,0,72,72,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00530a",4,"Una paloma blanca\ncomo la nieve\nme ha picado en el alma,\nmucho me duele.",4,0,-1,66,"",6,4,"ee",-1,0,-1,0,72,72,"","",1,"","","",3,0,0,[],""],["palau_cantares-00530b",4,"Acá dentro del pecho\ntengo un gusano,\nque me roe, me roe\nde cuando en cuando.",4,0,-1,66,"",6,4,"ao",-1,0,-1,0,72,72,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00530c",4,"¿Para qué vas y vienes,\ndoctor confuso,\nsi el mal que á mí me aqueja\nno sale al pulso?",4,0,-1,66,"",6,4,"uo",-1,0,-1,0,72,72,"","",1,"rm_t3, fernan_caballero","","",7,0,0,[],""],["palau_cantares-00530d",4,"Sin vida tu amor me tiene,\nsin salud voy por la tierra:\ncuando la Muerte me busque,\nsin duda que no me encuentra.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,72,72,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00530e",4,"Por ti no tengo camisa,\npor ti no tengo capote,\npor ti no he cantado misa,\npor ti no soy sacerdote.",4,0,-1,66,"",1,4,"oe",292,0,-1,0,72,72,"","",1,"rm_t4, frenk_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00531",4,"Si tu casa fuera iglesia,\ny tu cuarto fuera altar,\ny tu cama sepultura,\nvivo me fuera á enterrar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,72,72,"","",1,"carrizo_salta, lafuente_madrid, ortiz_ecuador","","",4,0,0,[],""],["palau_cantares-00532",4,"Nacen en el campo flores,\nnace la perla en el mar,\ny tú naciste, bien mío,\npara hacerme á mí penar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,72,72,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00533",4,"¡Quién tuviera un cordón de oro\ntan largo como esta calle,\npara sacar á una niña\ndel dominio de su padre!",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,72,72,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00534",4,"Tengo pena si te veo,\ny si no te veo, doble;\nno tengo más alegría\nque cuando escucho tu nombre.",4,0,-1,66,"",0,4,"oe",-1,0,-1,0,72,72,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00535",4,"Envidia le tengo al oro\nque tienes en los zarcillos,\nporque siempre está tocando\nesos divinos carrillos.",4,0,-1,66,"",0,4,"io",161,0,-1,0,72,72,"","",1,"","","",3,0,0,[],""],["palau_cantares-00536",4,"Al peñón de la Gomera\ntu madre quiere llevarme\nporque te quiero de veras.\n¡Vaya unos motivos grandes!",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,72,72,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00537",4,"¡Ay, quién fuera clavo de oro\ndonde cuelgas el candil,\npara ver tus dos ojitos\ncuando te vas á dormir!",4,0,-1,66,"",0,4,"i",-1,0,-1,0,72,72,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00538",4,"Más veces de ti me acuerdo\nque hojas tienen los laureles,\ny botes un boticario,\ny un escribano papeles.",4,0,-1,66,"",0,4,"ee",97,0,-1,0,72,72,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00539",4,"Aunque tu padre te meta\ndebajo de los ladrillos,\nyo te tengo de sacar\ny me he de casar contigo.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,72,72,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00540",4,"Tengo una pesadumbre\nque al alma llega:\nviva quien me la ha dado,\naunque yo muera.",4,0,-1,66,"",6,4,"ea",-1,0,-1,0,72,72,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00541",4,"Todas las arañas negras\nque se salgan de sus nidos\ny piquen mi corazón,\nsi mi querer es fingido.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,73,73,"","",1,"","","",1,0,0,[],""],["palau_cantares-00542",4,"Átame con un cabello\ná los bancos de tu cama,\nque aunque el cabello se rompa,\nseguro está que me vaya.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,73,73,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00543",4,"Al principiar á amarte\nhice promesa\nde olvidar tus amores\ncuando fallezca.",4,0,-1,66,"",6,4,"ea",-1,0,-1,0,73,73,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00544",4,"Serrana, dile á tu madre\nque si te quiere vender,\nen la mano está el dinero\ny en la puerta el mercader.",4,0,-1,66,"",0,4,"e",20,0,-1,0,73,73,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00545",4,"Dos cosas en el mundo\nme harán perderte:\nsi vivo, un desengaño;\nsi no. la muerte.",4,0,-1,66,"",6,4,"ee",134,0,-1,0,73,73,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00546",4,"Aunque nos vayan celando\npor balcones y ventanas,\nlograremos nuestro intento;\nno tengas pena por nada.",4,0,-1,66,"",0,4,"aa",-1,0,-1,0,73,73,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00547",4,"No quisiera quererte\ncon tanto extremo,\ny aun me parece poco\nlo que te quiero.",4,0,-1,66,"",6,4,"eo",-1,0,-1,0,73,73,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00548",4,"Me dicen que si te quiero,\ny yo digo que ni verte:\nes menester disimulo\npor el hablar de las gentes.",4,0,-1,66,"",0,4,"ee",-1,0,-1,0,73,73,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00549",4,"Hágame usté unos zapatos\ncon el tacón que levante;\nque soy chiquita y no alcanzo\ná los brazos de mi amante.",4,0,-1,66,"",0,4,"ae",47,0,-1,0,73,73,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00550",4,"Más quisiera contigo\nvivir en guerra,\nque estar en paz con otra\nque me quisiera.",4,0,-1,66,"",6,4,"ea",-1,0,-1,0,73,73,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00551",4,"Envidia tengo á la tierra,\ny también á los gusanos\nque te tienen que comer\nese cuerpo tan gitano.",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,73,73,"","",1,"","","",6,0,0,[],""],["palau_cantares-00552",4,"La primera clavellina\nque eche mi clavellinero\nse la tengo que poner\ná mi amante en el sombrero.",4,0,-1,66,"",0,4,"eo",38,0,-1,0,73,73,"","",1,"","","",3,0,0,[],""],["palau_cantares-00553",4,"Quisiera ser poderoso\ny mantenerte en el aire,\ny ya que yo no te gozo,\nque no te gozara nadie.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,73,73,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00554",4,"Ojos de blanca paloma,\nserafín idolatrado,\nbenditas tus perfecciones,\nque me tienen hechizado.",4,0,-1,66,"",0,4,"ao",14,0,-1,0,73,73,"","",1,"","","",3,0,0,[],""],["palau_cantares-00555",4,"Si yo fuera basilisco,\ncon la vista te matara,\ny te sacara del mundo\nporque nadie te gozara.",4,0,-1,66,"",0,4,"aa",57,0,-1,0,73,73,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00556",4,"Eres el sol que yo adoro\ny la luna que venero,\neres cadena de amor\nque me tiene prisionero.",4,0,-1,66,"",0,4,"eo",38,0,-1,0,73,73,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00557",4,"Cuatro esquinas tiene el horno,\ncuatro la panadería,\ncuatro pilares la cama\ndonde duerme el alma mía.",4,0,-1,66,"",0,4,"ia",0,0,-1,0,73,73,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00558",4,"Las estrellas en el cielo\nestán alumbrando á Dios,\ny tú, como eres mi estrella,\nalumbras mi corazón.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,73,73,"","",1,"lafuente_madrid","","",18,0,0,[],""],["palau_cantares-00559",4,"Las cortinas de tu cama\nson de seda y algodón,\ny entre cortina y cortina\ndescansa mi corazón.",4,0,-1,66,"",3,4,"o",31,0,-1,0,73,73,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00560",4,"Toma esa rosa encarnada,\nábrela, que está en capullo,\ny verás mi corazón\nabrazado con el tuyo.",4,0,-1,66,"",0,4,"uo",78,0,-1,0,73,73,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00561",4,"Debajo de tu ventana\nme puse á atar una liga:\nquien bien ata, mal desata;\nquien bien quiere, tarde olvida.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",29,0,0,[],""],["palau_cantares-00562",4,"Si las estrellas del cielo\ntodas se volvieran lanzas\npunta abajo para el suelo,\nno pierdo las esperanzas.",4,0,-1,66,"",1,4,"aa",110,0,-1,0,74,74,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00563",4,"Tengo yo una prima hermana\ny la quiero tanto y cuanto,\nque la he de llevar á Roma\nque la vea el Padre Santo.",4,0,-1,66,"",0,4,"ao",30,0,-1,0,74,74,"","",1,"","","",3,0,0,[],""],["palau_cantares-00564",4,"Ya te he dicho que no vayas\ná misa donde voy yo:\nni tú rezas, ni yo rezo,\nni estamos con devoción.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00565",4,"Sobre gusto no hay disgusto:\nyo quiero á aquel caballero\nque está vestido de luto;\nque á mí me gusta lo negro.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00566",4,"En mi alma manda Dios,\nen mi persona mis padres,\npero en cuanto á mi gustito,\nen ese no manda nadie.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00567a",4,"Todos me dicen que adoro\nun clavel de mal color:\ndiga el mundo lo que quiera,\ná mí me parece un sol.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00567b",4,"Todo el mundo me da vaya\nporque quiero á un hombre chico;\nyo digo que por el aire\nse compran los abanicos.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,74,74,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00567c",4,"Dicen que mi amante es feo:\npara mí es el sol dorado;\nen estando yo gustosa,\ntodo el mundo está pagado.",4,0,-1,66,"",0,4,"ao",14,0,-1,0,74,74,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00567d",4,"Cuando yo estaba en prisiones,\nen lo que me divertía\nera en escribir tu nombre\nen los ladrillos que había.",4,0,-1,66,"",0,4,"ia",0,0,-1,0,74,74,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00568a",4,"Mi padre y mi madre son\ndueños de lo que yo gano,\npero de mi personita\nyo soy el único amo.",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00568b",4,"En el alma te tengo\ntan á lo vivo,\nque despierto soñando\nsiempre contigo;\ny en despertando,\nme digo yo á mí mismo:\nvamos soñando.",4,0,-1,66,"",4,7,"ao",33,0,-1,0,74,74,"","",1,"rm_t2, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00568c",4,"Tu padre y tu madre dicen\nque no los dejo dormir;\ndentro de la casa tienen\nla que no me deja á mí.",4,0,-1,66,"",0,4,"i",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00569",4,"Cuando voy á la besana,\nllevo los bueyes arando,\ncon la mano en la mancera,\ny en ti, serrana, pensando.",4,0,-1,66,"",0,4,"ao",33,0,-1,0,74,74,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00570",4,"Estoy durmiendo y soñando\nque estás á la vera mía;\ndespierto, y me hallo sin ti:\nvuelvo á la misma fatiga.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,74,74,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00571",4,"Al que se muere lo entierran,\ndice un antiguo refrán;\ná mí, que por ti me muero,\n¿no me vendrán á enterrar?",4,0,-1,66,"",0,4,"a",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00572",4,"Jamás pensé, vida mía,\nquererte como te quiero;\ncuando me voy á acostar,\nno puedo cuajar el sueño.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,74,74,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00573",4,"Aunque padezca fatigas\ny sienta mi corazón,\nmás quiero en ti la esperanza\nque en otra la posesión.",4,0,-1,66,"",0,4,"o",31,0,-1,0,74,74,"","",1,"lafuente_madrid, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-00574",4,"Las campanas de maitines\ntodas las noches las cuento,\ny pensando en tu querer\npierdo las horas del sueño.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,74,74,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00575a",4,"¿Hasta cuándo, dueño mío,\nme tengo de estar así,\nlas horitas de la noche\npasándolas sin dormir?",4,0,-1,66,"",0,4,"i",-1,0,-1,0,77,77,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00575b",4,"Te quiero más que al vivir,\nmás que á la tierra y al cielo,\nmás que á mi padre y mi madre,\ny más quererte no puedo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,77,77,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00575c",4,"Ni tu padre, ni tu madre,\n'ni los que vayan naciendo\nte pueden á ti querer _\ncomo yo te estoy queriendo.",4,0,-1,66,"",0,4,"eo",52,0,-1,0,77,77,"","",1,"rm_t2, lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00575d",4,"Ayer en misa mayor\nhice un pecado mortal:\npuse los ojos en ti\ny los quité del altar.",4,0,-1,66,"",0,4,"a",-1,0,-1,0,77,77,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00575e",4,"Soñé que me querías\nla otra mañana,\ny soñé al mismo tiempo\nque lo soñaba;\nque para un triste\naun las dichas soñadas\nson imposibles.",4,0,-1,66,"",4,7,"ie",-1,0,-1,0,77,77,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-00575f",4,"Cuando paso por tu puerta,\nsi estás solilla, te hablo;\nsi acompañadita estás,\nagacho la vista y callo.",4,0,-1,66,"",0,4,"ao",-1,0,-1,0,77,77,"","",1,"","","",17,0,0,[],""],["palau_cantares-00575g",4,"Baja, niña, al cuarto bajo,\nhablaremos por la reja\ndos palabritas de amor,\nsin que lo sepa la vieja.",4,0,-1,66,"",0,4,"ea",165,0,-1,0,77,77,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00576",4,"Cuando te veo venir\nhasta el alma se me alegra;\nno te salgo á recibir\npor causa de malas lenguas.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,77,77,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00576-e2",4,"Amor mío, ven temprano,\nno me vengas á deshora,\nque la vecina de enfrente\nes algo murmuradora.",4,0,-1,66,"",0,4,"oa",107,0,-1,0,77,77,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00576-e3",4,"Ahí tienes mi corazón,\nábrelo con esa llave,\ny verás como allí dentro\nsola tu persona cabe.",4,0,-1,66,"",0,4,"ae",131,0,-1,0,77,77,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00576-e4",4,"En mi casa me dicen\nque si te quiero;\nyo digo que ni verte...\n¡cuando no puedo!",4,0,-1,66,"",6,4,"eo",-1,0,-1,0,77,77,"","",1,"rm_t2","","",11,0,0,[],""],["palau_cantares-00576-e5",4,"Al cavar mi sepultura,\nhallarán mi corazón\ncon cien cadenas atado\ncomo si fuera un ladrón.",4,0,-1,66,"",0,4,"o",31,0,-1,0,77,77,"","",1,"carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00576-e6",4,"Como triste mariposa\ncamino de noche y día\nhasta que los cielos quieran\nque te publiquen por mía.",4,0,-1,66,"",0,4,"ia",0,0,-1,0,77,77,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00576-e7",4,"La luna se ha parado\nen su carrera,\nadmirada de verte\ntan hechicera.",4,0,-1,66,"",6,4,"ea",44,0,-1,0,77,77,"","",1,"","","",2,0,0,[],""],["palau_cantares-00576-e8",4,"Pasionera, pasionera,\ndisimula tu pasión,\ncomo yo la disimulo\ndentro de mi corazón.",4,0,-1,66,"",0,4,"o",31,0,-1,0,77,77,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00577",4,"Con mi puro y mi guitarra\nme tendrás todas las noches\nal frente de tu ventana\nantes que suenen las doce.",4,0,-1,66,"",0,4,"oe",-1,0,-1,0,77,77,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00578",4,"Mucho te quiero callando,\ny tu callar agradezco,\nque para un firme querer\nno hay cosa como el silencio.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,77,77,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00579",4,"Marinero, boga, boga,\ny que vuele la barquilla,\nque al otro lado del río\nme espera el bien de mi vida.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,77,77,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00580",4,"Cuando paso por tu puerta\ny me miras con desprecio,\nme dejas la sangre helada\ny el corazón sin consuelo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,77,77,"","",1,"rm_t3, lafuente_madrid","","",17,0,0,[],""],["palau_cantares-00581",4,"Ya sé que por mi querer\ntus padres te dan pesares;\nquédate con Dios, perlita,\nno quiero que tú lo pagues.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,78,78,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00581-e2",4,"Quisiera que Dios me diera\nun olvidar cariñoso,\nque te pudiera olvidar\ny tú quedaras gustoso.",4,0,-1,66,"",0,4,"oo",160,0,-1,0,78,78,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00582a",4,"Si me volviera paloma,\n¡qué gustosa que quedara!\nDentro de tu corazón,\nallí mi nido formara.",4,0,-1,66,"",0,4,"aa",57,0,-1,0,78,78,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00582b",4,"Tengo pleito con mi madre;\nsi no lo gano, me muero,\nporque quiere que me case\ncon uno que yo no quiero.",4,0,-1,66,"",0,4,"eo",38,0,-1,0,78,78,"","",1,"rm_t3, carrizo_salta, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00583",4,"Toma allá mi corazón,\néchalo en esa candela;\nmas no agarres las cenizas,\nque te has de quemar con ellas.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,78,78,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",7,0,0,[],""],["palau_cantares-00584",4,"El sentido se me pierde,\ncuando con ella platico,\nen ver que tengo una novia\ncantadora y con buen pico.",4,0,-1,66,"",0,4,"io",141,0,-1,0,78,78,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00585",4,"Ahí tienes mi corazón\nentre dos flechas metido,\ny para mayor dolor,\nentre cadenas y grillos.",4,0,-1,66,"",0,4,"io",-1,0,-1,0,78,78,"","",1,"rm_t2, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00586",4,"Yo no sabía querer,\ndueño de mi corazón,\ny contigo me enseñé:\nya te puedo dar lección.",4,0,-1,66,"",0,4,"o",31,0,-1,0,78,78,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00587",4,"¡Quién fuera fino coral,\nperla de tu gargantilla,\nde tu cintura clavete,\nde tu zapato la hebilla!",4,0,-1,66,"",0,4,"ia",162,0,-1,0,78,78,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00588",4,"Si se pudiera escribir\nlo que te quiero, morena,\nno habría papel bastante\nen el reino de Valencia.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,78,78,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00590a",4,"Si la mar fuera de tinta\ny de papel fuera el cielo,\nno te pudiera escribir\nlo mucho que yo te quiero.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,78,78,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-00590b",4,"Es tanto lo que te quiero,\ny lo que te quiero es tanto,\nque el día que no te veo\nno le rezo á ningún santo.",4,0,-1,66,"",0,4,"ao",30,0,-1,0,78,78,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",26,0,0,[],""],["palau_cantares-00592",4,"Aunque te subas al cielo\ny te sientes junto á Dios,\nno te han de querer los santos\ncomo á ti te quiero yo.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,78,78,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00593",4,"El retrato de mi amante\nlo llevo siempre en el pecho:\ncuando no está junto á mí,\nsaco el retrato y lo beso.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,78,78,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00594",4,"Aunque te subas al cielo\ny te escondas en las nubes,\nte tengo de conocer\npor el amor que te tuve.",4,0,-1,66,"",0,4,"ue",-1,0,-1,0,78,78,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-00595",4,"Con esa gorrita negra\nme pareces un ladrón,\nque aunque no robas á nadie,\nme robas el corazón.",4,0,-1,66,"",0,4,"o",31,0,-1,0,78,78,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00596",4,"Si te veo, me aturrullo,\ny si en la calle te encuentro,\nhace un movimiento el alma\npara salirse del cuerpo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,78,78,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00597",4,"Cuando te encuentro en la calle,\nel sentido se me quita\ny me agarro á las paredes\nhasta perderte de vista.",4,0,-1,66,"",0,4,"ia",-1,0,-1,0,79,79,"","",1,"lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00598",4,"Fatigas me dan de muerte\nen no viéndote en un día;\nsi no te viera en un año,\npienso que me moriría.",4,0,-1,66,"",0,4,"ia",0,0,-1,0,79,79,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00599",4,"Si me quieres ver morir\nsin calentura y sin mal,\nno tienes más que decir\nque me quieres olvidar.",4,0,-1,66,"",0,4,"a",-1,0,-1,0,79,79,"","",1,"rm_t2, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00600",4,"El día que no te veo,\ntengo yo mi corazón\ncomo un jardín sin recreo,\ncomo una flor sin olor.",4,0,-1,66,"",0,4,"o",-1,0,-1,0,79,79,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00601",4,"Anoche soñé un ensueño,\ny en el ensueño soñé\nque me habías olvidado.\n¡Si vieras cuánto lloré!",4,0,-1,66,"",0,4,"e",77,0,-1,0,79,79,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00602",4,"¡Válgame Dios, Padre Adán,\nlo que quiero á esta mujer!\nEl día que no la veo\nla retrato en la pared.",4,0,-1,66,"",0,4,"e",-1,0,-1,0,79,79,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00603",4,"Compañerita del alma,\nel sueño no me alimenta:\nduermo soñando contigo,\ny tu querer me despierta.",4,0,-1,66,"",0,4,"ea",-1,0,-1,0,79,79,"","",1,"lafuente_madrid","","",20,0,0,[],""],["palau_cantares-00604",4,"¡Si supieras cómo estoy\nel día que no te veo!\nNi mis ojos tienen luz,\nni mi corazón consuelo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,79,79,"","",1,"","","",1,0,0,[],""],["palau_cantares-00605",4,"Si en tu cara sintieres\nun aire frío,\nson suspiros del alma\nque yo te envío:\nporque en mi cuarto\nsuspirando y gimiendo\npaso los ratos.",4,0,-1,66,"",4,7,"ao",-1,0,-1,0,79,79,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00606",4,"Como barquillo en el mar,\nque va pegando vaivenes,\nse queda mi corazón\ncuando te vas y no vienes.",4,0,-1,66,"",0,4,"ee",120,0,-1,0,79,79,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00607a",4,"No quiero que te vayas,\nni que te quedes,\nni que me dejes sola,\nni que me lleves.\nQuiero tan sólo...,\npero no quiero nada,\nlo quiero todo.",4,0,-1,66,"",4,7,"oo",-1,0,-1,0,79,79,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00607b",4,"Por tus hermosos ojos\njuró la suerte\nque á unos daría vida\ny á otros la muerte;\n¡mas quién creyera\nque quien por ellos vive,\npor ellos muera!",4,0,-1,66,"",4,7,"ea",44,0,-1,0,79,79,"","",1,"","","",1,0,0,[],""],["palau_cantares-00607c",4,"Quisiera verte, bien mío,\ntreinta días cada mes,\nsiete días en semana,\ncada minuto una vez.",4,0,-1,66,"",0,4,"e",150,0,-1,0,79,79,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00608a",4,"Cuando paso y te miro\ná la ventana,\nme parece que asoma\nya la mañana.\nTe miro, y luego\ná la luz de tus ojos\nme quedo ciego.",4,0,-1,66,"",4,7,"eo",29,0,-1,0,79,79,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00608b",4,"Confesé con un fraile,\n¡qué bueno era!,\nme echó por penitencia\nque te quisiera;\ny yo te quise,\nporque las penitencias\ndeben cumplirse.",4,0,-1,66,"",4,7,"ie",-1,0,-1,0,79,79,"","",1,"","","",2,0,0,[],""],["palau_cantares-00608c",4,"El confesor me ha dicho\nque no te quiera,\ny yo le dije: «Padre,\n¡si usted la viera!.»\nDespués me ha dicho:\n«Haces bien en quererla,\nque ya la he visto.»",4,0,-1,66,"",4,7,"io",-1,0,-1,0,79,79,"","",1,"","","",4,0,0,[],""],["palau_cantares-00609a",4,"Si me acuesto, pienso en ti;\nsi me levanto, en ti pienso;\nte quisiera preguntar\nsi te pasa á ti lo mesmo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,80,80,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00609b",4,"Por tus quereres serrana,\nme voy quedando en la espina;\nestoy que me lleva el viento\nal revolver de una esquina.",4,0,-1,66,"",0,4,"ia",11,0,-1,0,80,80,"","",1,"","","",2,0,0,[],""],["palau_cantares-00609c",4,"Si me encuentras en la calle\nno me debes conocer,\nque estoy hecho un esqueleto\nde pensar en tu querer.",4,0,-1,66,"",0,4,"e",20,0,-1,0,80,80,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00610",4,"Así como el muchacho\nque cuando salta,\ncuanto más se retira,\nmejor avanza;\ndel mismo modo,\nsi me retiro, vuelvo\nmás animoso.",4,0,-1,66,"",4,7,"oo",-1,0,-1,0,80,80,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00610-e2",4,"La luna solitaria\nbrilla en el cielo,\ncomo de amor la llama\narde en mi pecho.\nLa diferencia\nes que la luna pasa\ny el amor queda.",4,0,-1,66,"",4,7,"ea",-1,0,-1,0,80,80,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00611",4,"Como el panal de la cera\ntengo yo mi propia carne,\nque me ha puesto tu querer\nque no me conoce nadie.",4,0,-1,66,"",0,4,"ae",-1,0,-1,0,80,80,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00613",4,"Suspiritos menuditos\nsalen de mi pecho triste,\ny se meten en el tuyo\ncomo granitos de alpiste.",4,0,-1,66,"",0,4,"ie",153,0,-1,0,80,80,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00614",4,"Permita Dios de los cielos\nque te vuelvas á acordar\nde la que te quiere tanto\ncomo los peces al mar.",4,0,-1,66,"",0,4,"a",21,0,-1,0,80,80,"","",1,"","","",6,0,0,[],""],["palau_cantares-00615a",4,"No me mires, que miran\nque nos miramos,\nmiremos la manera\nde no mirarnos;\nno nos miremos,\ny, cuando no nos miren,\nnos miraremos.",4,0,-1,66,"",4,7,"eo",127,0,-1,0,80,80,"","",1,"rm_t2, suspiros_amor","","",6,0,0,[],""],["palau_cantares-00615b",4,"Con los ojos del alma\nte estoy mirando,\ny con los de la cara\ndisimulando:\nque este es el modo\nde que nuestro cariño\nse oculte á todos.",4,0,-1,66,"",4,7,"oo",-1,0,-1,0,80,80,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00616a",4,"De los huesos de mi cuerpo\ntengo de hacer una cruz\ny me he de enclavar en ella\npidiendo por tu salud.",4,0,-1,66,"",0,4,"u",-1,0,-1,0,80,80,"","",1,"","","",1,0,0,[],""],["palau_cantares-00616b",4,"Me han dicho que estás malita,\nchiquilla, y que ya te has muerto:\nyo te resucitaré\ncon el calor de mi cuerpo.",4,0,-1,66,"",0,4,"eo",-1,0,-1,0,80,80,"","",1,"","","",6,0,0,[],""],["palau_cantares-00616c",4,"Alma y vida te rendí,\ny todo por adorarte:\n¿qué quieres pedirme á mí\nsi ya no tengo qué darte?",4,0,-1,66,"",1,4,"ae",8,0,-1,0,80,80,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-00617a",4,"Cuando sales á bailar\ncon ese garbo y salero,\nuna campana de plata\npareces de pie en el suelo.",4,0,-1,67,"CANTE Y B A I L E",0,4,"eo",-1,0,-1,0,81,81,"","",1,"rm_t4","","",5,0,0,[],""],["palau_cantares-00617b",4,"La madre que te parió\nbien podía parir otra:\nla una para el que canta,\nla otra para el que toca.",4,0,-1,67,"CANTE Y B A I L E",0,4,"oa",-1,0,-1,0,81,81,"","",1,"","","",6,0,0,[],""],["palau_cantares-00618",4,"El cantar es muy propio\nde los alegres,\ny el que canta tristezas\nya las divierte.",4,0,-1,67,"",6,4,"ee",-1,0,-1,0,81,81,"","",1,"","","",1,0,0,[],""],["palau_cantares-00619",4,"La blanca es rayo de luna\ny la morena de sol:\nquiero luz de noche y día\ny me quedo con las dos.",4,0,-1,67,"",0,4,"o",-1,0,-1,0,81,81,"","",1,"","","",1,0,0,[],""],["palau_cantares-00620",4,"Aunque canto á lo gitano,\nno soy gitanillo yo;\nmas de andar con los gitanos\nel canto se me pegó.",4,0,-1,67,"",0,4,"o",2,0,-1,0,81,81,"","",1,"","","",4,0,0,[],""],["palau_cantares-00621",4,"¿Cómo quieres que tenga\ngusto en el cante,\nsi la prenda que adoro\nno está delante?",4,0,-1,67,"",6,4,"ae",47,0,-1,0,81,81,"","",1,"rm_t3, fernan_caballero","","",14,0,0,[],""],["palau_cantares-00622",4,"En la montaña de Jaca\nme acordé de ti, salero,\nporque me faltó la sal\ncuando estaba de ranchero.",4,0,-1,67,"",0,4,"eo",38,0,-1,0,81,81,"","",1,"","","",2,0,0,[],""],["palau_cantares-00623",4,"Esta guitarra que toco\nme sirva de sepultura\nsi á otra quiero más que á ti,\ndespués de la Virgen pura.",4,0,-1,67,"",0,4,"ua",17,0,-1,0,81,81,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00624",4,"La guitarra es de caoba\ny las cuerdas de marfil:\nel que la toca es un ángel,\nla que baila un serafín.",4,0,-1,67,"",0,4,"i",-1,0,-1,0,81,81,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00625",4,"Quiero cantar ahora\nque tengo gana,\npor si acaso me toca\nllorar mañana.",4,0,-1,67,"",6,4,"aa",4,0,-1,0,81,81,"","",1,"rm_t4, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00626",4,"¡Atención, que ha salido\nla reina á bailar!\n¡Qué hermoso cuerpo tiene\nsu real majestad!",4,0,-1,67,"",0,4,"a",-1,0,-1,0,81,81,"","",1,"","","",1,0,0,[],""],["palau_cantares-00627a",4,"El mocito que baila\nbien puede decir\nque baila con la reina\nsin ir á Madrid.",4,0,-1,67,"",0,4,"i",-1,0,-1,0,82,82,"","",1,"","","",2,0,0,[],""],["palau_cantares-00627b",4,"Ya está puesta en el baile\nla que no quiere\nque le digan la reina\nde las mujeres;\ny yo le digo:\n«Reina de las mujeres,\nbaila conmigo.»",4,0,-1,67,"",4,7,"io",106,0,-1,0,82,82,"","",1,"","","",4,0,0,[],""],["palau_cantares-00628",4,"Señor bailadorcito,\nmire usté al hoyo,\nque la niña que baila\ntiene su novio;\nmire usté al suelo,\nque la niña que baila\nya tiene dueño.",4,0,-1,67,"",4,7,"eo",-1,0,-1,0,82,82,"","",1,"","","",2,0,0,[],""],["palau_cantares-00628-e2",4,"Esos dos que están bailando,\n¡qué parejitos que son!\nSi yo fuera padre cura,\nles diera la bendición.",4,0,-1,67,"",0,4,"o",31,0,-1,0,82,82,"","",1,"rm_t4, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00629",4,"Tienes un baile tan chulo\ny una vuelta tan galana,\nque dejas en ese suelo\npintadita una campana.",4,0,-1,67,"",0,4,"aa",4,0,-1,0,82,82,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00630",4,"Cuando vayas á la fiesta\ny te pongas á bailar,\nno me seas retrechera,\nque me harás prevaricar.",4,0,-1,67,"",0,4,"a",21,0,-1,0,82,82,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00631",4,"A la que está bailando\nechadle rosas,\nporque se lo merece\npor buena moza.",4,0,-1,67,"",6,4,"oa",-1,0,-1,0,82,82,"","",1,"","","",2,0,0,[],""],["palau_cantares-00632",4,"Cuando te veo bailar\ncon tanta gracia y salero,\ndigo: ¿Quién se llevará\nese cuerpo sandunguero?",4,0,-1,67,"",0,4,"eo",38,0,-1,0,82,82,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00633",4,"Zapatéate, serrana,\nhazte ese cuerpo pedazos;\nque si no tienes dinero,\nyo te mercaré zapatos.",4,0,-1,67,"",0,4,"ao",-1,0,-1,0,82,82,"","",1,"","","",1,0,0,[],""],["palau_cantares-00634",4,"Con ese andar tan ligero\ny ese modo de bailar\nhas revuelto á los mozuelos\nde todito este lugar.",4,0,-1,67,"",0,4,"a",21,0,-1,0,82,82,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00635",4,"Pulido bailadorcito,\nátate los alpargates,\nno vayas á tropezar\ny á esa niña me la mates.",4,0,-1,67,"",0,4,"ae",283,0,-1,0,82,82,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00636",4,"Cuando sales á bailar\ncon los brazos extendidos,\npareces águila real\ncuando sale de su nido.",4,0,-1,67,"",0,4,"io",-1,0,-1,0,82,82,"","",1,"rm_t4","","",5,0,0,[],""],["palau_cantares-00637",4,"Bailad, muchachas, bailad\ny romped muchos zapatos,\nque mañana os casaréis\ny lavaréis muchos trapos.",4,0,-1,67,"",0,4,"ao",-1,0,-1,0,82,82,"","",1,"","","",2,0,0,[],""],["palau_cantares-00638",4,"¡Válgame Dios, qué serena\nes usted para bailar!\nSi para todo es lo mismo,\n¡vaya una serenidad!",4,0,-1,67,"",0,4,"a",-1,0,-1,0,82,82,"","",1,"","","",2,0,0,[],""],["palau_cantares-00639",4,"La guitarra lo dice,\nyo no lo digo,\nlos dos que están bailando\nlo han entendido.",4,0,-1,67,"",6,4,"io",-1,0,-1,0,82,82,"","",1,"","","",2,0,0,[],""],["palau_cantares-00640",4,"Pulido bailadorcito,\nbaílala bien, que es mi hermana,\ny si no la bailas bien,\nsaldrá su hermano á bailarla.",4,0,-1,67,"",0,4,"aa",-1,0,-1,0,82,82,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00641",4,"Si no fuera mi prima\nla que bailara,\nno fuera mi boquita\nla que cantara.",4,0,-1,67,"",6,4,"aa",57,0,-1,0,82,82,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00642",4,"¿Qué tiene ese bailador\nque no menea los brazos\ny parece un avión\nque le han dado taramazo?",4,0,-1,67,"",0,4,"ao",-1,0,-1,0,82,82,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00643",4,"Esa señora que baila\nse parece á San Miguel,\ny el bailador que la baila\nal que está debajo de él.",4,0,-1,67,"",1,4,"e",32,0,-1,0,83,83,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00644",4,"La niña que está bailando\nparece un pimpollo de oro:\npregúntale, compañero,\nsi es casada ó tiene novio.",4,0,-1,67,"",0,4,"oo",-1,0,-1,0,83,83,"","",1,"lafuente_madrid, fernan_caballero","","",19,0,0,[],""],["palau_cantares-00645a",4,"La niña que está bailando\nme la comiera yo solo,\ny al bailador que la baila\nque se lo coman los lobos.",4,0,-1,67,"",0,4,"oo",-1,0,-1,0,83,83,"","",1,"rm_t4, lafuente_madrid","","",19,0,0,[],""],["palau_cantares-00645b",4,"La niña que está bailando\nparece una altramucera.\n¡Altramuces dulces, dulces!\nSerrana, ¡quién te comiera!",4,0,-1,67,"",0,4,"ea",44,0,-1,0,83,83,"","",1,"lafuente_madrid","","",19,0,0,[],""],["palau_cantares-00645c",4,"La niña que está bailando\nparece una clavellina,\ny el bailador que la baila\nparece un Juan de las Viñas.",4,0,-1,67,"",0,4,"ia",-1,0,-1,0,83,83,"","",1,"rm_t4, lafuente_madrid","","",19,0,0,[],""],["palau_cantares-00645d",4,"Dicen que la reina ha muerto:\ntodos dicen que es verdad,\ny yo digo que es mentira,\nporque ha salido á bailar.",4,0,-1,67,"",0,4,"a",-1,0,-1,0,83,83,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00645e",4,"La bailadora es la luna,\nel bailador es el sol;\ná los rayos de la luna\nme voy arrimando yo.",4,0,-1,67,"",0,4,"o",-1,0,-1,0,83,83,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00645f",4,"Ya salió mi niña al baile,\nya salió la resalada,\nya salió la que me tiene\ntodita el alma robada.",4,0,-1,67,"",0,4,"aa",49,0,-1,0,83,83,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00645g",4,"Entran en esta fiesta\ncuatro figuras:\nuno canta, dos bailan\ny otro murmura.",4,0,-1,67,"",6,4,"ua",-1,0,-1,0,83,83,"","",1,"","","",1,0,0,[],""],["palau_cantares-00645h",4,"Cuerpo bueno con sandunga,\nmenéate poco á poco,\nque los bienes de fortuna\ncuestan mucho y duran poco.",4,0,-1,67,"",0,4,"oo",-1,0,-1,0,83,83,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00645i",4,"Jaléate, cuerpo bueno,\nque te vas aniquilando\ncon la calor del invierno\ny los fríos del verano.",4,0,-1,67,"",0,4,"ao",-1,0,-1,0,83,83,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00646",4,"Un clavel y una rosa\nestán bailando;\nla rosa es encarnada\ny el clavel blanco:\nporque la rosa\ncuanto más encarnada,\nes más hermosa.",4,0,-1,67,"",4,7,"oa",63,0,-1,0,83,83,"","",1,"","","",2,0,0,[],""],["palau_cantares-00646-e2",4,"La dama que está bailando\nse parece á Santa Rita,\ny el galán que está cantando\nermitaño de su ermita.",4,0,-1,67,"",1,4,"ia",50,0,-1,0,83,83,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00647",4,"Tengo mi pecho de coplas\nque parece un avispero:\nse empujan unas á otras\npor ver cuál sale primero.",4,0,-1,67,"",0,4,"eo",38,0,-1,0,83,83,"","",1,"","","",2,0,0,[],""],["palau_cantares-00648",4,"Si quieres saber coplas,\nvente á mi pecho,\nque se ha vuelto poeta\nmi pensamiento.",4,0,-1,67,"",6,4,"eo",-1,0,-1,0,84,84,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00649",4,"Ya sé que estás en la cama;\nya sé que no duermes, no;\nya sé que estás escuchando\nlas coplas que canto yo.",4,0,-1,67,"",0,4,"o",2,0,-1,0,84,84,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00650",4,"Si estuviera cantando\nuna semana,\nuna copla dos veces\nno la cantara.",4,0,-1,67,"",6,4,"aa",-1,0,-1,0,84,84,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-00651",4,"Asómate á esa ventana,\nniña, si quieres oir\nlas coplas de un firme amante,\nque las canta un serafín.",4,0,-1,67,"",0,4,"i",-1,0,-1,0,84,84,"","",1,"rm_t2, lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00652",4,"La guitarra sin la prima\nes como un hijo sin madre:\ntodo el día se le va\nsuspirando y dando ayes.",4,0,-1,67,"",0,4,"ae",-1,0,-1,0,84,84,"","",1,"","","",2,0,0,[],""],["palau_cantares-00653",4,"Asómate á esa ventana,\nbella dama, y te veremos,\ny con la luz de tus ojos\nla vihuela templaremos.",4,0,-1,67,"",0,4,"eo",127,0,-1,0,84,84,"","",1,"lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00654",4,"La guitarra que toco\nno tiene prima,\nmas tiene los bordones\nde plata fina.",4,0,-1,67,"",6,4,"ia",-1,0,-1,0,84,84,"","",1,"","","",1,0,0,[],""],["palau_cantares-00655",4,"Asómate á esa ventana,\ncara de piñón de oro:\nquiero encender un cigarro\nen las niñas de tus ojos.",4,0,-1,67,"",0,4,"oo",-1,0,-1,0,84,84,"","",1,"lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00656",4,"¡Qué voces tan cariñosas\nson las que escucho cantar!\n¿Son los ángeles del cielo\nó las sirenas del mar?",4,0,-1,67,"",0,4,"a",21,0,-1,0,84,84,"","",1,"","","",1,0,0,[],""],["palau_cantares-00657",4,"Asómate á esa ventana,\nhermosísima diadema,\nque aunque está la noche obscura,\ntú de claridad la llenas.",4,0,-1,67,"",0,4,"ea",-1,0,-1,0,84,84,"","",1,"","","",50,0,0,[],""],["palau_cantares-00658",4,"La primera por el amo,\nla segunda por la dueña,\ntercera por la criada,\nque es la que á mí me da pena.",4,0,-1,67,"",0,4,"ea",-1,0,-1,0,84,84,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00659",4,"Canta tú y cantaré yo,\npajarito en verde rama;\ncanta tú y cantaré yo,\ncante quien amores ama.",4,0,-1,67,"",1,4,"aa",90,0,-1,0,84,84,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00660",4,"Aunque no canta, aquí viene,\nsalada, tu enamorado;\naunque no canta, aquí viene,\naquí le tengo á mi lado.",4,0,-1,67,"",1,4,"ao",14,0,-1,0,84,84,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00661",4,"Para cantar quiere gana,\npara bailar quiere brío,\npara tocar la guitarra\nquiere tener buen oído.",4,0,-1,67,"",0,4,"io",-1,0,-1,0,84,84,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00662",4,"Tengo que morir cantando,\nya que llorando nací;\nque las penas de este mundo\nno todas son para mí.",4,0,-1,67,"",0,4,"i",23,0,-1,0,84,84,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00663",4,"Las cuerdas de mi vihuela\nyo te diré cuántas son:\nprima, segunda, tercera,\ncuarta, quinta y el bordón.",4,0,-1,67,"",0,4,"o",31,0,-1,0,84,84,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00664a",4,"Si supiera que cantando\ndaba gusto á mi morena,\ntoda la noche cantara\ny á la mañana durmiera.",4,0,-1,67,"",0,4,"ea",-1,0,-1,0,84,84,"","",1,"rm_t2, lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00664b",4,"Despierta, calandria hermosa,\nque en tu puerta hay un jilguero,\nen tu garganta una rosa\ny en tu pecho un prisionero.",4,0,-1,67,"",1,4,"eo",38,0,-1,0,84,84,"","",1,"","","",3,0,0,[],""],["palau_cantares-00665a",4,"Si la gracia me ayudara\ncomo me ayuda el deseo,\ná todo el mundo agradara;\npero sin gracia no puedo.",4,0,-1,67,"",0,4,"eo",-1,0,-1,0,84,84,"","",1,"","","",3,0,0,[],""],["palau_cantares-00665b",4,"Seguidillas manchegas\nson las que canto,\nporque las de mi tierra\nno valen tanto.",4,0,-1,67,"",6,4,"ao",30,0,-1,0,84,84,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00666",4,"Ninguno, por cantar bien,\nhable mal de aquel que canta;\nunos cantan lo que saben,\ny otros saben lo que cantan.",4,0,-1,67,"",0,4,"aa",-1,0,-1,0,85,85,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00667",4,"Gracias á Dios que he llegado\ndonde no pensé llegar:\ná darte las buenas noches,\npaloma, en tu palomar.",4,0,-1,67,"",0,4,"a",21,0,-1,0,85,85,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00668",4,"Esta noche ha de llover,\nque esté raso, que esté nublo;\nhan de llover buenos palos\nen las costillas de alguno.",4,0,-1,67,"",0,4,"uo",-1,0,-1,0,85,85,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00669",4,"Gracias á Dios que he llegado\nal palacio donde habita\nesta paloma zurita,\ndesvelo de mi cuidado.",4,0,-1,67,"",11,4,"ao",14,0,-1,0,85,85,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00670",4,"Compañero, canta, canta,\ny no le temas á nadie,\nque en la punta de mi espada\ntraigo á la Virgen del Carmen.",4,0,-1,67,"",0,4,"ae",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00671",4,"Asómate á la ventana,\ná la que da sobre el río,\nmanojo de clavellinas\ncogidas con el rocío.",4,0,-1,67,"",0,4,"io",3,0,-1,0,85,85,"","",1,"","","",14,0,0,[],""],["palau_cantares-00672",4,"Canta, compañero, canta,\nno temas á los miñones;\nsi no tienes corazón,\nyo tengo corazón doble.",4,0,-1,67,"",0,4,"oe",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00673",4,"Asómate á esa ventana,\nsi te quieres asomar;\nten cuidado no te rompas\nese pecho de cristal.",4,0,-1,67,"",0,4,"a",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00674",4,"Canta, compañero, canta,\ny no le temas á nadie,\nporque nunca se han escrito\nvalentías de un cobarde.",4,0,-1,67,"",0,4,"ae",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00675",4,"Asómate á esa ventana,\nhermosura de la tierra,\ny verás en el instante\nal sol parar su carrera.",4,0,-1,67,"",0,4,"ea",-1,0,-1,0,85,85,"","",1,"rm_t2, lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00676",4,"El mozo que está cantando\nno tiene pelo de barba;\npero si se ofrece un lance,\ntiene pelos en el alma.",4,0,-1,67,"",0,4,"aa",-1,0,-1,0,85,85,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00677",4,"El galán que aquí cantare\ná la puerta de esta dama,\nalce un poquito la voz,\nporque está lejos la cama.",4,0,-1,67,"",0,4,"aa",90,0,-1,0,85,85,"","",1,"","","",2,0,0,[],""],["palau_cantares-00678",4,"Corre, que viene la ronda\ny comienza el tiroteo;\nyo no lo siento por mí,\nsino por mi compañero.",4,0,-1,67,"",0,4,"eo",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00679",4,"A mí me tocó la suerte,\ncomo mejor director,\nde venir á despertar\ndel barrio la mejor flor.",4,0,-1,67,"",0,4,"o",72,0,-1,0,85,85,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00680",4,"Cuatro chavales venimos,\ntodos sin pelo de barba;\ny si hay alguno valiente,\nque salga por la guitarra.",4,0,-1,67,"",0,4,"aa",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00681",4,"Si supiera, vida mía,\nque me estabas escuchando,\ntoda la noche estaría\ncomo un ruiseñor cantando.",4,0,-1,67,"",1,4,"ao",33,0,-1,0,85,85,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00682",4,"Voy á cantar las coplas\nque me han mandado,\nque no quiero que digan:\nmalo y rogado.",4,0,-1,67,"",6,4,"ao",14,0,-1,0,85,85,"","",1,"fernan_caballero","","",2,0,0,[],""],["palau_cantares-00683",4,"Coplillas y más coplillas,\ncoplillas he de cantar,\nporque tengo un arca llena\ny un costal por desatar.",4,0,-1,67,"",0,4,"a",21,0,-1,0,85,85,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00684",4,"Esta noche, si Dios quiere,\nyo me voy á divertir\ncon licencia del alcalde\ny de la guardia civil.",4,0,-1,67,"",0,4,"i",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00685",4,"En el campo nada importa\ncantar bien ó cantar mal;\nmas llegando donde hay gente,\ncantar bien ó no cantar.",4,0,-1,67,"",0,4,"a",-1,0,-1,0,85,85,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00686",4,"La luna para salir\nle pide al cielo licencia,\ny para cantar yo aquí\nla pido con reverencia.",4,0,-1,67,"",0,4,"ea",46,0,-1,0,86,86,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",14,0,0,[],""],["palau_cantares-00687",4,"Asómate á esa ventana,\nsi te quieres asomar,\nverás tu calle barrida\ncon la capa de un galán.",4,0,-1,67,"",0,4,"a",-1,0,-1,0,86,86,"","",1,"lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00688",4,"Á la puerta de mi novia\nmi compañero cantó;\ná la puerta de la suya\nes razón que cante yo.",4,0,-1,67,"",0,4,"o",2,0,-1,0,86,86,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00689",4,"Asómate á esa ventana,\ncara de limón florido,\ny échale una bendición\nal que ha de ser tu marido.",4,0,-1,67,"",0,4,"io",101,0,-1,0,86,86,"","",1,"lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00690",4,"Si quieres saber, hermosa,\nquién te ha venido á cantar,\nun mocito aragonés\nque te tiene voluntad.",4,0,-1,67,"",0,4,"a",-1,0,-1,0,86,86,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00691",4,"Asómate á ese balcón,\ny si no, á la ventanilla,\ny si no tienes ventana,\ná la puerta, vida mía.",4,0,-1,67,"",0,4,"ia",-1,0,-1,0,86,86,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00692",4,"Si tuviera el pecho claro,\nte cantara la rondeña;\npero como no lo tengo,\nte canto la malagueña.",4,0,-1,67,"",0,4,"ea",291,0,-1,0,86,86,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00693",4,"Yo no canto porque sé,\nni porque escuchen mi voz;\ncanto porque no se junte\nla pena con el dolor.",4,0,-1,67,"",0,4,"o",-1,0,-1,0,86,86,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00694",4,"Aquí me tienes penando,\ndueño de mi corazón,\npues vengo de contrabando\ny no puedo alzar la voz.",4,0,-1,67,"",0,4,"o",-1,0,-1,0,86,86,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00695",4,"No canto porque me escuchen,\nni tampoco porque sé:\ncanto porque soy mandado\ny es preciso obedecer.",4,0,-1,67,"",0,4,"e",-1,0,-1,0,86,86,"","",1,"carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00696",4,"Ahora sí que canto claro,\nque he tomado caramelo,\nque me lo dió una gitana\ncon muchísimo salero.",4,0,-1,67,"",0,4,"eo",-1,0,-1,0,86,86,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00697",4,"Por la calle abajo viene\nuna guitarra de plata,\ny la prima va diciendo:\n«Una morena me mata.»",4,0,-1,67,"",0,4,"aa",74,0,-1,0,86,86,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00698",4,"Asómate á esa ventana,\ncara de luna redonda,\nlucero de la mañana\ny espejo de quien te ronda.",4,0,-1,67,"",1,4,"oa",182,0,-1,0,86,86,"","",1,"lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00699",4,"La guitarra es de marfil,\nde oro las cuerdas y el puente,\ny el tañedor que la tañe,\nsalada, tu pretendiente.",4,0,-1,67,"",0,4,"ee",15,0,-1,0,86,86,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00700",4,"Asómate á esa ventana,\ncara de luna brillante,\nque aunque yo no te pretendo,\nconmigo viene tu amante.",4,0,-1,67,"",0,4,"ae",47,0,-1,0,86,86,"","",1,"rm_t2, lafuente_madrid","","",50,0,0,[],""],["palau_cantares-00701",4,"Dame de tu pelo rubio\ncuerdas para mi vihuela,\nque se me ha roto la prima,\ncuarta, segunda y tercera.",4,0,-1,67,"",0,4,"ea",-1,0,-1,0,86,86,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00702",4,"La luna se va, se va,\ndéjela usted que se vaya:\nla luna que á mí me alumbra\nestá en aquella ventana.",4,0,-1,67,"",0,4,"aa",-1,0,-1,0,86,86,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00703",4,"¿A qué vienen al baile\ntantos mirones?\nBailan mozas con mozas\npor falta de hombres.",4,0,-1,67,"",6,4,"oe",-1,0,-1,0,86,86,"","",1,"","","",1,0,0,[],""],["palau_cantares-00704",4,"Asómate á ese balcón,\nasómate, luz divina,\nverás con tu resplandor\ntu amante que está en la esquina.",4,0,-1,67,"",0,4,"ia",11,0,-1,0,86,86,"","",1,"rm_t2, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00705",4,"Con esta copla y otra\nse acaba el baile:\npor la puerta, señores,\nse va á la calle.",4,0,-1,67,"",6,4,"ae",-1,0,-1,0,86,86,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00706a",4,"Desde la Cruz de la Legua\nvolví la cara llorando.\n¡Adiós, Málaga la bella,\nqué lejos te vas quedando!",4,0,-1,68,"",0,4,"ao",33,0,-1,0,87,87,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00706b",4,"Adiós, quédate con Dios;\nadiós, que el cielo te guarde:\nuna estrella que te guíe\ny un ángel que te acompañe.",4,0,-1,68,"",0,4,"ae",-1,0,-1,0,87,87,"","",1,"","","",3,0,0,[],""],["palau_cantares-00707",4,"Gracias á Dios que he llegado\ná tu puerta, bella Aurora,\nque me parece que he echado\nen cada paso una hora.",4,0,-1,68,"",1,4,"oa",107,0,-1,0,87,87,"","",1,"","","",10,0,0,[],""],["palau_cantares-00708",4,"Dicen que nada cuesta\nla despedida.\nDile al que te lo ha dicho\nque se despida.",4,0,-1,68,"",6,4,"ia",37,0,-1,0,87,87,"","",1,"","","",1,0,0,[],""],["palau_cantares-00709",4,"Gracias á Dios que he llegado,\ngracias á Dios que llegué,\ngracias á Dios que he cantado,\ngracias á Dios que canté.",4,0,-1,68,"",1,4,"e",77,0,-1,0,87,87,"","",1,"","","",10,0,0,[],""],["palau_cantares-00710",4,"Quédate con Dios, salada;\nmucho me duele el dejarte;\npero también considero\nque siempre no puedo hablarte.",4,0,-1,68,"",0,4,"ae",8,0,-1,0,87,87,"","",1,"rm_t3, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00711",4,"Ya sé que estás en tu cama,\nya sé que no duermes, no;\nya sé que estás escuchando\nlas coplas que canto yo.",4,0,-1,68,"",0,4,"o",2,0,-1,0,87,87,"","",1,"","","",1,0,0,[],""],["palau_cantares-00712",4,"Dame un besito, y adiós,\nsalero, vete á la cama,\nque no quiero que por mí\npases frío en la ventana.",4,0,-1,68,"",0,4,"aa",-1,0,-1,0,87,87,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00713",4,"Ya sé que estás en camisa\ntras la ventana escuchando\ny en un papel escribiendo\nlas coplas que estoy cantando.",4,0,-1,68,"",0,4,"ao",33,0,-1,0,87,87,"","",1,"","","",3,0,0,[],""],["palau_cantares-00714",4,"Quédate con Dios, ventana,\ny dile á la que te cierra\nque si se acuerda de mí\ncomo yo me acuerdo de ella.",4,0,-1,68,"",0,4,"ea",-1,0,-1,0,87,87,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00715",4,"Despiértate, noble dama;\ndespiértate, hermosa niña:\nla dama que tiene amores\nno debe de estar dormida.",4,0,-1,68,"",0,4,"ia",-1,0,-1,0,87,87,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00716",4,"Niña, de ti me despido,\nque viene la luz del día\ny no quiero ver más sol\nque el que me quita la vida.",4,0,-1,68,"",0,4,"ia",-1,0,-1,0,87,87,"","",1,"","","",1,0,0,[],""],["palau_cantares-00718",4,"Despierta si estás dormida,\nvuélvete del otro lado,\ndale un beso á la almohada,\npiensa que á mí me lo has dado.",4,0,-1,68,"",0,4,"ao",14,0,-1,0,88,88,"","",1,"","","",5,0,0,[],""],["palau_cantares-00719",4,"Dios te dé muy buenas noches\nhermosísimo lucero,\nen teniéndolas tú buenas,\nyo muy felices las tengo.",4,0,-1,68,"",0,4,"eo",-1,0,-1,0,88,88,"","",1,"","","",4,0,0,[],""],["palau_cantares-00720",4,"Ya tú me habrás conocido\nen el eco de mi voz\ny dirás desde la cama:\nEse que canta es mi amor.",4,0,-1,68,"",0,4,"o",-1,0,-1,0,88,88,"","",1,"","","",1,0,0,[],""],["palau_cantares-00721",4,"Cansado de correr vengo\ncon la mano en la montera\npor ver si podía ser\nmi coplita la primera.",4,0,-1,68,"",0,4,"ea",44,0,-1,0,88,88,"","",1,"","","",1,0,0,[],""],["palau_cantares-00722",4,"No se asombre usted, señora:\nun soldado es el que canta,\ncon el pan de munición\ntiene seca la garganta.",4,0,-1,68,"",0,4,"aa",148,0,-1,0,88,88,"","",1,"","","",1,0,0,[],""],["palau_cantares-00723",4,"Aunque me voy, no me voy;\naunque me voy, no me ausento;\naunque me voy de palabra,\nno me voy de pensamiento.",4,0,-1,68,"",0,4,"eo",94,0,-1,0,88,88,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00724",4,"Gracias á Dios que he llegado\ná la luz de ese farol\npara quitarme una espina\nque traigo en el corazón.",4,0,-1,68,"",0,4,"o",-1,0,-1,0,88,88,"","",1,"","","",10,0,0,[],""],["palau_cantares-00725",4,"Me despido de tu puerta\ncomo el sol de las paredes,\nque por las tardes se va\ny por las mañanas vuelve.",4,0,-1,68,"",0,4,"ee",-1,0,-1,0,88,88,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00726",4,"Si supiera que cantando\nte había de divertir,\ntoda la noche cantara\naunque perdiera el dormir.",4,0,-1,68,"",0,4,"i",157,0,-1,0,88,88,"","",1,"rm_t2, carrizo_salta, fernan_caballero","","",10,0,0,[],""],["palau_cantares-00727",4,"Adiós, corazón amado;\nadiós, palma de hermosura;\nadiós, clavel; adiós, rosa;\nadiós, hermosa pintura.",4,0,-1,68,"",0,4,"ua",17,0,-1,0,88,88,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00728",4,"Despierta, doncella hermosa,\nde ese sueño tan profundo,\nque no es razón que tú duermas\ny yo pene por el mundo.",4,0,-1,68,"",0,4,"uo",179,0,-1,0,88,88,"","",1,"","","",1,0,0,[],""],["palau_cantares-00729",4,"Adiós, dueño de mi vida;\nadiós, hechizo del alma;\nadiós, norte de mi amor;\nadiós, mar de mi esperanza.",4,0,-1,68,"",0,4,"aa",-1,0,-1,0,88,88,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00730",4,"Quien la música ha traído\nno está aquí ni viene aquí,\npero está tan retirado\ncomo la ropa de mí.",4,0,-1,68,"",3,4,"i",23,0,-1,0,88,88,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00731",4,"Con esta copla, señores,\nde mi niña me despido;\nque mi madre ya dirá:\n¿Dónde estará ese perdido?",4,0,-1,68,"",0,4,"io",101,0,-1,0,88,88,"","",1,"lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00732",4,"La luna para salir\nle pide licencia al cielo,\ny para cantar aquí\nlicencia pido primero.",4,0,-1,68,"",0,4,"eo",-1,0,-1,0,88,88,"","",1,"","","",14,0,0,[],""],["palau_cantares-00733",4,"Señores, ustés perdonen\nde lo poco y mal cantado,\nque soy del oficio nuevo\ny no estoy examinado.",4,0,-1,68,"",0,4,"ao",14,0,-1,0,88,88,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00734",4,"Por ser la primera vez\nque á tu puerta, niña, canto,\nsea en el nombre de Dios\ny del Espíritu Santo.",4,0,-1,68,"",0,4,"ao",30,0,-1,0,88,88,"","",1,"","","",10,0,0,[],""],["palau_cantares-00735",4,"A la gente de esta casa\nDios les dé salud y vida,\ntrigo para todo el año:\n¡esta sí que es despedida!",4,0,-1,68,"",0,4,"ia",37,0,-1,0,88,88,"","",1,"","","",1,0,0,[],""],["palau_cantares-00736",4,"A tu puerta estamos cuatro,\ntodos cuatro te queremos;\nsal á la puerta y escoge\ny los demás nos iremos.",4,0,-1,68,"",0,4,"eo",127,0,-1,0,88,88,"","",1,"rm_t2","","",8,0,0,[],""],["palau_cantares-00737",4,"Del cielo bajará un ángel\ncon una cruz en la mano,\ná acompañar á esta niña,\nporque nosotros nos vamos.",4,0,-1,68,"",0,4,"ao",-1,0,-1,0,88,88,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00738",4,"Adiós, adiós, que me voy\ny no me quisiera ir;\ndame los brazos del alma,\nque me vengo á despedir.",4,0,-1,68,"",0,4,"i",157,0,-1,0,91,91,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00739",4,"¡Ay, mal haya mi fortuna\ny también mi mala suerte!,\nque el galán que yo idolatro\nquieren que de mí se ausente.",4,0,-1,68,"",0,4,"ee",-1,0,-1,0,91,91,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00740",4,"Tengo yo mi corazón\ncomo el de San Agustín,\nllorando gotas de sangre\nporque me aparto de ti.",4,0,-1,68,"",0,4,"i",-1,0,-1,0,91,91,"","",1,"","","",14,0,0,[],""],["palau_cantares-00741a",4,"Mi corazón pena y muere\nen diciendo que te vas;\npara que tanto no pene,\ndime cuándo volverás.",4,0,-1,68,"",0,4,"a",51,0,-1,0,91,91,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00741b",4,"Vámonos, compañeritos,\nque las cabrillas van altas,\ny la luz del día viene\ndescubriendo nuestras faltas.",4,0,-1,68,"",0,4,"aa",183,0,-1,0,91,91,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-00741c",4,"Adiós, dueño querido,\nprenda adorada,\nque aunque de ti me ausento,\nvas en el alma.",4,0,-1,68,"",6,4,"aa",-1,0,-1,0,91,91,"","",1,"","","",2,0,0,[],""],["palau_cantares-00741d",4,"Anda, vete, que es tarde,\nmoreno mío,\nya sabes con la pena\nque te lo digo.",4,0,-1,68,"",6,4,"io",-1,0,-1,0,91,91,"","",1,"","","",2,0,0,[],""],["palau_cantares-00741e",4,"En los clavos de tu puerta\nse queda mi corazón;\nlevántate tempranito,\nno te lo marchite el sol.",4,0,-1,68,"",0,4,"o",-1,0,-1,0,91,91,"","",1,"","","",1,0,0,[],""],["palau_cantares-00742",4,"Dos amantes se despiden\nal pie de una verde oliva;\ncomo la oliva es amarga,\namarga es la despedida.",4,0,-1,68,"",0,4,"ia",-1,0,-1,0,91,91,"","",1,"carrizo_salta","","",2,0,0,[],""],["palau_cantares-00742-e2",4,"Llorando me dejas\nal claro de luna:\npor dondequiera que el cielo te guíe\nDios te dé fortuna.",4,0,-1,68,"",3,4,"ua",56,0,-1,0,91,91,"","",1,"","","",1,0,0,[],""],["palau_cantares-00743",4,"La despedida te echo,\nno te la quisiera echar:\ncon lágrimas de mis ojos\nqueda regado el umbral.",4,0,-1,68,"",0,4,"a",-1,0,-1,0,91,91,"","",1,"rm_t2","","",5,0,0,[],""],["palau_cantares-00744",4,"Adiós, puente de Tudela,\nya se van los cazadores;\npor debajo pasa el agua,\npor encima mis amores.",4,0,-1,68,"",0,4,"oe",5,0,-1,0,91,91,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00745",4,"Lo último que se pierde\nes la esperanza,\ny este débil consuelo\ná mí me falta,\nporque me ausento\npara nunca más verte,\nquerido dueño.",4,0,-1,68,"",4,7,"eo",-1,0,-1,0,91,91,"","",1,"","","",1,0,0,[],""],["palau_cantares-00746",4,"Ya se van los quintos, madre,\npor la puerta de Alcalá;\nya se van, madre, los quintos:\n¡sabe Dios si volverán!",4,0,-1,68,"",0,4,"a",-1,0,-1,0,91,91,"","",1,"","","",8,0,0,[],""],["palau_cantares-00747",4,"La luna se va á poner,\nya hacen sombra los tejados:\n¿cómo me despediré\nde estos claveles dorados?",4,0,-1,68,"",0,4,"ao",18,0,-1,0,91,91,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00748",4,"Echemos la despedida\nal uso de mi lugar:\nmás vale poquito y bueno,\nque no mucho y enfadar.",4,0,-1,68,"",0,4,"a",21,0,-1,0,92,92,"","",1,"lafuente_madrid","","",18,0,0,[],""],["palau_cantares-00749",4,"De todas las despedidas\nes la mía la mejor,\nporque ninguno te ha dicho:\n«Queda con Dios, blanca flor.»",4,0,-1,68,"",0,4,"o",72,0,-1,0,92,92,"","",1,"","","",5,0,0,[],""],["palau_cantares-00750",4,"Echemos la despedida,\nechémosla muy corteses,\nque es hija de buenos padres\ny ella bien se lo merece.",4,0,-1,68,"",0,4,"ee",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",18,0,0,[],""],["palau_cantares-00751",4,"De todas las despedidas\nes la mía la más alta:\nadiós, clavel; adiós, rosa;\nadiós, mata de albahaca.",4,0,-1,68,"",0,4,"aa",-1,0,-1,0,92,92,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00752",4,"Te echaré la despedida\nde rositas y claveles,\ny un ramito de albahaca\npara que de mí te acuerdes.",4,0,-1,68,"",0,4,"ee",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00753",4,"Quédate con Dios, salada:\ntú te quedas, yo me voy;\nel aire que entre en tu cuarto\nson suspiros que yo doy.",4,0,-1,68,"",0,4,"o",112,0,-1,0,92,92,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00754",4,"Si tuviera una naranja,\ncontigo la partiría;\npero como no la tengo,\nte canto la despedida.",4,0,-1,68,"",0,4,"ia",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00755",4,"Nunca me digas adiós,\nque es una palabra triste:\ncorazones que se aman,\nnunca deben despedirse.",4,0,-1,68,"",0,4,"ie",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00756",4,"Ahí te va la despedida\ncon corona, ramo y palma;\nesta sí que es despedida\nde dos amantes del alma.",4,0,-1,68,"",1,4,"aa",125,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00757",4,"Adiós, mi adorado bien,\nno me olvides por tu vida,\nque yo no te olvidaré\nsi la muerte no me priva.",4,0,-1,68,"",0,4,"ia",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00758",4,"Mis amiguitos me dicen\nque no me sé despedir:\nadiós, clavel; adiós, rosa;\nadios, precioso jazmín.",4,0,-1,68,"",0,4,"i",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00759",4,"Adiós, mi estrella y mi gloria:\nno pongas en mi lugar\notro galán en memoria,\nni me llegues á olvidar.",4,0,-1,68,"",1,4,"a",21,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00760",4,"La despedida te doy,\nla despedida, y no puedo,\nque despedirme de ti\nes despedirme del cielo.",4,0,-1,68,"",0,4,"eo",-1,0,-1,0,92,92,"","",1,"","","",9,0,0,[],""],["palau_cantares-00761",4,"¡Cuántas veces, vida mía,\nte asomarás al balcón\ny te quitarás llorando\nde ver que no paso yo!",4,0,-1,68,"",0,4,"o",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00762",4,"Adiós, vida de mi vida;\nadiós, corazón amado;\nadiós, que me voy sin verte,\nporque la ausencia ha llegado.",4,0,-1,68,"",0,4,"ao",14,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00763",4,"Dicen que te vas mañana;\nno te vayas hasta el martes,\nque tiene mi corazón\nmuchos consejos que darte.",4,0,-1,68,"",0,4,"ae",-1,0,-1,0,92,92,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00764",4,"Adiós, adorada prenda,\nque me vengo á despedir\ny las piedras se quebrantan\nal ausentarme de ti.",4,0,-1,68,"",0,4,"i",-1,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00765",4,"El sábado es esperanza,\nel domingo es alegría;\nmas el lunes es tristeza,\npues se va la prenda mía.",4,0,-1,68,"",0,4,"ia",0,0,-1,0,92,92,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00766",4,"El que quiera ver dolores\nvaya á la orilla del mar\ny verá dos corazones\nque se quieren separar.",4,0,-1,68,"",0,4,"a",21,0,-1,0,92,92,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00767",4,"Dicen que te vas el lunes;\nvente á mi puerta á embarcar,\nmis brazos serán los remos\ny mis lágrimas el mar.",4,0,-1,68,"",0,4,"a",21,0,-1,0,92,92,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00768",4,"Dicen que te vas, te vas,\ny muy pronto, dueño mío;\nmira, no bebas el agua\nde la fuente del Olvido.",4,0,-1,68,"",0,4,"io",-1,0,-1,0,93,93,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00769",4,"Echemos la despedida\ncon un ramito de nueces,\nque la música no ha sido\ncomo tú te la mereces.",4,0,-1,68,"",0,4,"ee",196,0,-1,0,93,93,"","",1,"lafuente_madrid","","",18,0,0,[],""],["palau_cantares-00770",4,"No estaré jamás sin ti;\nque sólo podrá el rigor\nsepararte de mis ojos,\nmas no de mi corazón.",4,0,-1,68,"",0,4,"o",-1,0,-1,0,93,93,"","",1,"lafuente_madrid, preciso_coleccion","","",6,0,0,[],""],["palau_cantares-00771",4,"La despedida te doy,\nla despedida voy dando:\nesta sí que es despedida,\nque me despido cantando.",4,0,-1,68,"",0,4,"ao",33,0,-1,0,93,93,"","",1,"rm_t2, lafuente_madrid","","",9,0,0,[],""],["palau_cantares-00772",4,"Lucero de la mañana,\npréstame tu claridad\npara seguirle los pasos\ná mi amor, que se me va.",4,0,-1,68,"",0,4,"a",-1,0,-1,0,93,93,"","",1,"lafuente_madrid","","",22,0,0,[],""],["palau_cantares-00773",4,"Precipicio cauteloso,\nmañana voy de partida:\nsi la ausencia causa muerte,\n¡qué corta será mi vida!",4,0,-1,68,"",0,4,"ia",37,0,-1,0,93,93,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00774",4,"Echemos la despedida,\nechémosla con dolor:\nen los hierros de tu reja\nse queda mi corazón.",4,0,-1,68,"",0,4,"o",-1,0,-1,0,93,93,"","",1,"lafuente_madrid","","",18,0,0,[],""],["palau_cantares-00775",4,"Amor mío, si te vas,\nen tu ausencia yo me muero;\ncuando vuelvas me hallarás\nmuerto y sin tener consuelo.",4,0,-1,68,"",0,4,"eo",-1,0,-1,0,93,93,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00776",4,"Echemos la despedida\nal uso de caballeros,\ncon el sombrero en la mano:\nquede usted con Dios, salero.",4,0,-1,68,"",0,4,"eo",-1,0,-1,0,93,93,"","",1,"","","",18,0,0,[],""],["palau_cantares-00777",4,"Si de tu ausencia no muero,\ny con ella he de morir,\ndigan que soy en el mundo\nla mujer más infeliz.",4,0,-1,68,"",0,4,"i",-1,0,-1,0,93,93,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00778",4,"Echemos la despedida\nal uso de Barcelona:\nla madre que te parió\nmerece palma y corona.",4,0,-1,68,"",0,4,"oa",7,0,-1,0,93,93,"","",1,"lafuente_madrid","","",18,0,0,[],""],["palau_cantares-00779",4,"Si oyes que tocan á muerto,\nno preguntes quién murió;\nporque, ausente de tu vista,\n¿quién puede ser sino yo?",4,0,-1,68,"",0,4,"o",2,0,-1,0,93,93,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00780",4,"Te echaré la despedida,\ncomo hacen los carreteros,\ncon la zurriaga en la mano:\nquédate con Dios, salero.",4,0,-1,68,"",0,4,"eo",-1,0,-1,0,93,93,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00781",4,"Por en medio de esos mares\nme voy á buscar la vida;\nacuérdate, si no vuelvo,\nde quien tanto te quería.",4,0,-1,68,"",0,4,"ia",-1,0,-1,0,93,93,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00782-e2",4,"De una hierba me han hablado\nque cura males de ausencia:\nno quiero hierbas ni flores,\nque lo que quiero es que vuelvas.",4,0,-1,5,"",0,4,"ea",-1,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00782-e3",4,"Que me matas, que me matas,\nque me muero, que me muero,\ncon tu ausencia, con tu ausencia,\nsin remedio, sin remedio,",4,0,-1,5,"",0,4,"eo",-1,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00783",4,"Si supieras caminar,\ncorazón, te enviaría\ná que fueras á trocar\ntristezas por alegrías.",4,0,-1,5,"",0,4,"ia",-1,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00784",4,"Disputaban dos sabios\ncual es más muerte,\nsi ser aborrecido\nó estar ausente.",4,0,-1,5,"",6,4,"ee",-1,0,-1,0,95,95,"","",1,"","","",2,0,0,[],""],["palau_cantares-00785",4,"Un sabio, que de ausencia\npenaba, dijo:\n«No encuentro entre lo humano\nmayor martirio.»",4,0,-1,5,"",6,4,"io",-1,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00786",4,"El que se va se divierte\ncon las flores del camino:\ny el que queda va diciendo:\n«¿Dónde estará el peregrino?»",4,0,-1,5,"",0,4,"io",199,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00787",4,"Cuando se arranca una rama\nel tronco siente dolor,\nlas raíces lloran sangre,\nde luto viste la flor.",4,0,-1,5,"",0,4,"o",72,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00788",4,"La penilla de no verte\nme tiene sobre la arena:\ncuando no me he muerto yo,\nnadie se muere de pena.",4,0,-1,5,"",0,4,"ea",59,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00789",4,"En la ausencia se prueba\nlo que es cariño,\nque aunque un siglo se pase\ndura lo fino.",4,0,-1,5,"",6,4,"io",-1,0,-1,0,95,95,"","",1,"","","",1,0,0,[],""],["palau_cantares-00790",4,"Para el dolor de un ausente\nno hay alivio ni consuelo,\nporque tiene cerca el daño\ny muy lejos el remedio.",4,0,-1,5,"",0,4,"eo",-1,0,-1,0,95,95,"","",1,"","","",4,0,0,[],""],["palau_cantares-00791",4,"Dicen que el águila real\npasa volando los mares.\n¡Ay, quién pudiera volar\ncomo las águilas reales!",4,0,-1,5,"",0,4,"ae",-1,0,-1,0,95,95,"","",1,"rm_t3, machado_venezuela, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00792a",4,"Más siento la ausencia tuya\nque la muerte de mi padre:\npor mi padre no lloré,\npor ti mis ojos son mares.",4,0,-1,5,"",0,4,"ae",-1,0,-1,0,96,96,"","",1,"","","",2,0,0,[],""],["palau_cantares-00792b",4,"Pájaro que vas volando\npor cima de aquel convento,\ntoma, llévale estas letras\ná mi amor que está allí dentro.",4,0,-1,5,"",0,4,"eo",-1,0,-1,0,96,96,"","",1,"","","",6,0,0,[],""],["palau_cantares-00792c",4,"Tomé papel, tinta y pluma\npara escribirte amoroso,\ny en el primer renglón puse:\n«Vuela, papel venturoso.»",4,0,-1,5,"",0,4,"oo",160,0,-1,0,96,96,"","",1,"","","",1,0,0,[],""],["palau_cantares-00792d",4,"Vuela, papel venturoso,\nque á manos de un ángel vas:\nno digas que yo te envío,\nsino que solo tú vas.",4,0,-1,5,"",0,4,"a",-1,0,-1,0,96,96,"","",1,"","","",3,0,0,[],""],["palau_cantares-00792e",4,"Le agarré la mano\ny la llevé al muelle:\n¡que las olitas del mar la acompañen!,\n¡que Dios la consuele!",4,0,-1,5,"",3,4,"ee",-1,0,-1,0,96,96,"","",1,"","","",1,0,0,[],""],["palau_cantares-00792f",4,"Para placeres tu amor,\npara dichas tu presencia,\npara tormento tus celos\ny para muerte tu ausencia.",4,0,-1,5,"",0,4,"ea",46,0,-1,0,96,96,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00792g",4,"¡Quién estuviera tan alta\ncomo la estrella del Norte\npara ver lo que está haciendo\nmi morenito esta noche!",4,0,-1,5,"",0,4,"oe",-1,0,-1,0,96,96,"","",1,"","","",1,0,0,[],""],["palau_cantares-00792h",4,"Pensamiento que.vuelas\nmás que las aves\nllévale este suspiro\ná quien ya sabes:\nsé mensajero\ny dime si suspira\ntambién su pecho.",4,0,-1,5,"",4,7,"eo",-1,0,-1,0,96,96,"","",1,"","","",4,0,0,[],""],["palau_cantares-00792i",4,"Ausente estoy de tu vista,\nmis ojos ya no te ven,\nmi corazón se marchita\nde pensar en tu querer.",4,0,-1,5,"",0,4,"e",-1,0,-1,0,96,96,"","",1,"rm_t3","","",7,0,0,[],""],["palau_cantares-00793",4,"Ni veo, ni respiro,\nni oigo ni siento,\ncomo que está sin alma\ntodo mi cuerpo;\ny ello depende\nde ser la ausencia ensayo\npara la muerte.",4,0,-1,5,"",4,7,"ee",-1,0,-1,0,96,96,"","",1,"","","",2,0,0,[],""],["palau_cantares-00793-e2",4,"Sacan un pez del agua\ny al punto es muerto,\nporque lo han separado\nde su elemento:\nyo soy lo mismo\nasí que me separan\nde mi cariño.",4,0,-1,5,"",4,7,"io",-1,0,-1,0,96,96,"","",1,"","","",1,0,0,[],""],["palau_cantares-00793-e3",4,"¿Qué he de hacer sin tu vista,\ntriste y ausente,\nsi estaré todo el día\nsiente que siente,\ny hasta que muera\nestará el pecho mío\npena que pena?",4,0,-1,5,"",4,7,"ea",-1,0,-1,0,96,96,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00793-e4",4,"Aunque de ti me aparto,\nnunca me ausento,\npues llevo tu retrato\ndentro del pecho;\ny éste me alienta,\naliviando los males\nde larga ausencia.",4,0,-1,5,"",4,7,"ea",-1,0,-1,0,96,96,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00793-e5",4,"Aunque de ti me ausente,\nten entendido\nque te llevo en el pecho\nsiempre conmigo:\nque allá en su centro,\npor más que te retires,\nsiempre te encuentro.",4,0,-1,5,"",4,7,"eo",185,0,-1,0,96,96,"","",1,"","","",1,0,0,[],""],["palau_cantares-00793-e6",4,"Nunca de ti me acuerdo,\ndueño querido,\nporque aquel que se acuerda\nsupone olvido;\ny yo en mi mente\ntengo la imagen tuya\nsiempre presente.",4,0,-1,5,"",4,7,"ee",15,0,-1,0,96,96,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00794",4,"Camino de la Sierra\nvan mis suspiros,\nderribando carrascas,\nrobles y pinos.",4,0,-1,5,"",6,4,"io",-1,0,-1,0,97,97,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00794-e2",4,"Por papel van suspiros,\npor letras ansias,\npor sobrescrito penas,\npor firma el alma;\ny son los celos\nlos que llevan la carta,\npor más ligeros.",4,0,-1,5,"",4,7,"eo",-1,0,-1,0,97,97,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00795",4,"Por más firmeza que haya\nen nobles pechos,\nes la ausencia madrastra\nde los afectos:\nconque los míos\nlos veo en este lance\ncasi perdidos.",4,0,-1,5,"",4,7,"io",-1,0,-1,0,97,97,"","",1,"","","",2,0,0,[],""],["palau_cantares-00796a",4,"Una pena te envío,\ndueño adorado,\nque es la prenda que tengo\nmás á la mano;\ntantas me quedan,\nque el número compite\ncon las estrellas.",4,0,-1,5,"",4,7,"ea",-1,0,-1,0,97,97,"","",1,"","","",2,0,0,[],""],["palau_cantares-00796b",4,"No me mandes papeles,\nque no sé leer;\nmándame tu persona,\nque la quiero ver.",4,0,-1,5,"",0,4,"e",20,0,-1,0,97,97,"","",1,"rm_t3, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00796c",4,"¿Cómo quieres que tenga\ngusto sin verte,\nsi eres la que más quiero\ny estás ausente?",4,0,-1,5,"",6,4,"ee",-1,0,-1,0,97,97,"","",1,"rm_t3, preciso_coleccion","","",14,0,0,[],""],["palau_cantares-00796d",4,"A los santos les pido\nque en esta ausencia\ná ti te den constancia\ny á mí paciencia.",4,0,-1,5,"",6,4,"ea",46,0,-1,0,97,97,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00796e",4,"No siente el pecho mío\nmás alegría\nque el día que se acuerda\nde tu venida.",4,0,-1,5,"",6,4,"ia",-1,0,-1,0,97,97,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00796f",4,"La esperanza de verte\nme tiene viva,\nque si no, ya tuviera\nla tierra encima.",4,0,-1,5,"",6,4,"ia",-1,0,-1,0,97,97,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00797",4,"Si supiera la pena\nque era no verte,\nme hubiera resignado\ná no quererte.",4,0,-1,5,"",6,4,"ee",134,0,-1,0,97,97,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-00798",4,"Las estrellitas del cielo\nse visten de azul celeste,\ny yo me visto de negro\nporque mi amor está ausente.",4,0,-1,5,"",0,4,"ee",-1,0,-1,0,97,97,"","",1,"","","",25,0,0,[],""],["palau_cantares-00798-e2",4,"No supe qué era ausencia\nhasta no verte,\ny ahora digo que quiero\nmejor la muerte:\npues en muriendo\nse acabarán mis penas\ny sufrimientos.",4,0,-1,5,"",4,7,"eo",-1,0,-1,0,97,97,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00798-e3",4,"Ya no voy ni vengo al muelle,\nporque no tengo á quién ver;\nque un amante que tenía\ntendió la vela y se fué.",4,0,-1,5,"",0,4,"e",-1,0,-1,0,97,97,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00799",4,"Mal haya quien hizo el barco,\ny el que lo arrojó á la mar,\ny el que cortó la madera,\ny el que la mandó cortar.",4,0,-1,5,"",0,4,"a",21,0,-1,0,98,98,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00800",4,"¿Cómo ha de ser la memoria\nel correo en las ausencias,\nsi no lleva los recados\nni vuelve con las respuestas?",4,0,-1,5,"",0,4,"ea",-1,0,-1,0,98,98,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00801",4,"Triste está mi corazón\ny no sabe lo que tiene,\nque está muy lejos de aquí\nel que consolarlo puede.",4,0,-1,5,"",0,4,"ee",-1,0,-1,0,98,98,"","",1,"lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00802",4,"Lucero del mes de abril,\nestrella del mes de mayo,\ndi, ¿cómo te va sin mí,\npues yo sin ti no me hallo?",4,0,-1,5,"",0,4,"ao",102,0,-1,0,98,98,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00803",4,"Si mi corazón volara\ny fuera donde lo envío,\n¡qué bien recibido fuera,\nsi supieran que era mío!",4,0,-1,5,"",0,4,"io",3,0,-1,0,98,98,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00804",4,"Ausente del bien que adoro,\nsin esperanza de verle,\nno puede haber para mí\nmás consuelo que la muerte.",4,0,-1,5,"",0,4,"ee",-1,0,-1,0,98,98,"","",1,"lafuente_madrid, preciso_coleccion","","",10,0,0,[],""],["palau_cantares-00805",4,"Cuando suspiro ausente,\ncon tu memoria\nencuentran dulce calma\nmis penas todas.",4,0,-1,5,"",6,4,"oa",-1,0,-1,0,98,98,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00806",4,"Con la pena de no verte\nestoy viviendo en la tierra,\ny cuando yo no me he muerto,\nnadie se muere de pena.",4,0,-1,5,"",0,4,"ea",-1,0,-1,0,98,98,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00807",4,"Anoche fuí al correo,\nno tuve carta:\nse vistieron de luto\nmis esperanzas.",4,0,-1,5,"",6,4,"aa",-1,0,-1,0,98,98,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-00808",4,"Estrellita relumbrante,\n¿cuándo será tu venida,\nque yo te estoy aguardando\npara la Pascua florida?",4,0,-1,5,"",0,4,"ia",37,0,-1,0,98,98,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00809",4,"Cartas van, cartas vienen\npor el correo:\nnada me satisface\nsi no te veo.",4,0,-1,5,"",6,4,"eo",66,0,-1,0,98,98,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00810",4,"Con lo que me consuelo\ncuando estoy triste,\nes con ver el camino\npor donde fuiste.",4,0,-1,5,"",6,4,"ie",153,0,-1,0,98,98,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00811",4,"¡Ojalá no te hablara,\nnunca te viera,\nni gozara tu dulce\ncorrespondencia!\nQue es menos ansia\ncarecer de la dicha\nque abandonarla.",4,0,-1,5,"",4,7,"aa",-1,0,-1,0,98,98,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00812",4,"Si me muero en tu ausencia,\nserá preciso\nque los aires se partan\ná darte aviso:\nporque sin duda\nme servirá tu pecho\nde sepultura.",4,0,-1,5,"",4,7,"ua",-1,0,-1,0,98,98,"","",1,"","","",1,0,0,[],""],["palau_cantares-00813",4,"Nunca supe lo mucho\nque te quería\nhasta que dió la hora\nde la partida:\nporque se ignora\nel valor de los bienes\nmientras se gozan.",4,0,-1,5,"",4,7,"oa",-1,0,-1,0,98,98,"","",1,"","","",3,0,0,[],""],["palau_cantares-00814",4,"Ausente de tu vista,\nmucho más vivo,\nporque cada momento\nse me hace un siglo;\npero, mi dueño,\nmás que vivir ausente,\nmorirme quiero.",4,0,-1,5,"",4,7,"eo",-1,0,-1,0,98,98,"","",1,"rm_t3, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00815",4,"Si rigores de la ausencia\ntuvieran fuerza en tu pecho,\nni tú estuvieras sin mí,\nni yo estuviera con ellos.",4,0,-1,5,"",0,4,"eo",-1,0,-1,0,98,98,"","",1,"","","",1,0,0,[],""],["palau_cantares-00816",4,"Cuando salí de Marbella,\nhasta el caballo lloraba,\nque me dejé una doncella\nque al sol los rayos quitaba.",4,0,-1,5,"",1,4,"aa",28,0,-1,0,98,98,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00817",4,"El día que me aparté\nde tu presencia divina,\nmás lágrimas derramé\nque lleva el Guadalmedina.",4,0,-1,5,"",1,4,"ia",11,0,-1,0,101,101,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00818",4,"Ausente estoy de tu vista,\npero no del pensamiento,\nque con los ojos del alma\nte veo á cada momento.",4,0,-1,5,"",0,4,"eo",94,0,-1,0,101,101,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00819",4,"Mi amante cuando se fué\nme dijo que no llorara,\nque echara penas á un lado,\npero que no le olvidara.",4,0,-1,5,"",0,4,"aa",57,0,-1,0,101,101,"","",1,"","","",2,0,0,[],""],["palau_cantares-00820",4,"¿Qué importa que no te vea,\nsi yo tengo un gran alivio?\nYo tengo mi corazón\ntodas las horas contigo.",4,0,-1,5,"",0,4,"io",-1,0,-1,0,101,101,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00821a",4,"Ya tu dueño se ausentó,\nte ha dejado sin compaña;\nse ha llevado tus sentidos,\nlas tres potencias del alma",4,0,-1,5,"",0,4,"aa",-1,0,-1,0,101,101,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00821b",4,"Ojos que te vieron ir\npor aquellos olivares,\n¿cuándo te verán volver\npara alivio de mis males?",4,0,-1,5,"",0,4,"ae",-1,0,-1,0,101,101,"","",1,"rm_t3, lafuente_madrid","","",12,0,0,[],""],["palau_cantares-00821c",4,"En una cama de ausencia\ncayó mala mi esperanza;\nlágrimas, tened paciencia,\nque el tiempo todo lo alcanza.",4,0,-1,5,"",1,4,"aa",163,0,-1,0,101,101,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00821d",4,"Marinero, sube al palo\ny dile á mi compañera\nque si se acuerda de mí\ncomo yo me acuerdo de ella.",4,0,-1,5,"",0,4,"ea",-1,0,-1,0,101,101,"","",1,"rm_t3, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00821e",4,"Ausente del bien que adoro,\n¿qué dicha podré tener?\nEn mí no reina alegría\nhasta que lo vuelva á ver.",4,0,-1,5,"",0,4,"e",20,0,-1,0,101,101,"","",1,"rm_t3","","",10,0,0,[],""],["palau_cantares-00822",4,"Aún hay autores que dicen:\n«Ausencias causan olvido;»\nyo estoy ausente y no puedo\nolvidarte, dueño mío.",4,0,-1,5,"",0,4,"io",-1,0,-1,0,101,101,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00822-e2",4,"El día que te ausentaste\nle eché un candado á mi pecho\ny á mi corazón le dije:\n«Tú quedarás satisfecho.»",4,0,-1,5,"",0,4,"eo",60,0,-1,0,101,101,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00822-e3",4,"Hasta el muelle fui con ella,\nen el muelle la dejé;\n¡allí fueron los lamentos\ncuando de ella me aparté!",4,0,-1,5,"",0,4,"e",77,0,-1,0,101,101,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00822-e4",4,"Dame esa carta, serrana,\nque yo se la llevaré\nal amante de tu vida\ny en su mano la pondré.",4,0,-1,5,"",0,4,"e",77,0,-1,0,101,101,"","",1,"","","",2,0,0,[],""],["palau_cantares-00822-e5",4,"Pajarito que volando\ncruzas el aire ligero,\naquí te estoy aguardando;\nque has de ser el mensajero\nde un alma que está penando.",4,0,-1,5,"",7,5,"ao",33,0,-1,0,101,101,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00823",4,"Si por esos andurriales\nte encuentras á mi morena,\ndile que estoy trabajando\npara sacarla de penas.",4,0,-1,5,"",0,4,"ea",-1,0,-1,0,101,101,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00824",4,"Este papel con cuidado\nhas de llevar en el pico\ná mi dueño idolatrado;\ny advierte que te suplico\nque lo des disimulado.",4,0,-1,5,"",7,5,"ao",14,0,-1,0,101,101,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00825",4,"Se fué mi dueño querido\ny sólito me ha dejado,\ncomo pajarito triste\nde rama en rama volando.",4,0,-1,5,"",0,4,"ao",-1,0,-1,0,101,101,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00826",4,"Y si acaso te dijere:\n«¿Quién ha escrito estos renglones?,»\ndile que el amante suyo,\nque está metido en prisiones.",4,0,-1,5,"",0,4,"oe",34,0,-1,0,101,101,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00827",4,"Firme estoy en tu ausencia,\nfirme presente,\nfirme después de muerto,\ny firme siempre;\ny aunque me olvides,\nen todas ocasiones\nestoy yo firme.",4,0,-1,5,"",4,7,"ie",-1,0,-1,0,102,102,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00828",4,"Orillita de un sauce,\njunto á una fuente,\nsuspiraba un amante\nde verse ausente,\ny así decía:\n«¡Cuándo volveré á verte,\nbien de mi vida!»",4,0,-1,5,"",4,7,"ia",-1,0,-1,0,102,102,"","",1,"","","",1,0,0,[],""],["palau_cantares-00829",4,"Sólo llevo en mi ausencia\npor compañero\nel recuerdo terrible\ndel bien que pierdo.\n¡Qué feliz fuera,\nsi pasadas memorias\nborrar pudiera!",4,0,-1,5,"",4,7,"ea",44,0,-1,0,102,102,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00830",4,"Pajarillo amoroso,\nque estás llamando\ncon tus dulces gorjeos\ná mi cuidado,\npor Dios te pido\nque me digas si sabes\ndel dueño mío.",4,0,-1,5,"",4,7,"io",-1,0,-1,0,102,102,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00831",4,"¡Ay de aquel desterrado\nque sin delito\npadece en sus tormentos\ncruel martirio;\ny en tal ausencia\nsólo tiene el alivio\ncuando se queja!",4,0,-1,5,"",4,7,"ea",-1,0,-1,0,102,102,"","",1,"","","",1,0,0,[],""],["palau_cantares-00831-e2",4,"He recibido tu carta\ncon mucho gusto y placer;\nsi no me pongo en camino,\nno dudes que moriré.",4,0,-1,5,"",0,4,"e",-1,0,-1,0,102,102,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00831-e3",4,"Cuando á mis manos llegó\ntu carta, dueño querido,\ntodo el pesar que tenía\nse convirtió en regocijo.",4,0,-1,5,"",0,4,"io",-1,0,-1,0,102,102,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00831-e4",4,"Nunca supe lo mucho\nque te quería\nhasta sonar la hora\nde tu partida.\nPorque se ignora\nel valor de los bienes\nmientras se gozan.",4,0,-1,5,"",4,7,"oa",-1,0,-1,0,102,102,"","",1,"","","",3,0,0,[],""],["palau_cantares-00831-e5",4,"Pensativa en mi cuarto\nmil veces digo:\n«Ausente de quien amo,\n¿cómo es que vivo?»\nPorque conserva\nel amor esta vida\npara más penas.",4,0,-1,5,"",4,7,"ea",-1,0,-1,0,102,102,"","",1,"","","",2,0,0,[],""],["palau_cantares-00832a",4,"Dicen que la ausencia es\nsemejanza de la muerte,\ny yo digo que es mentira,\nporque te adoro sin verte.",4,0,-1,5,"",0,4,"ee",134,0,-1,0,102,102,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00832b",4,"Te la escribí con la pluma,\nte la noté con el alma,\nno preguntes de quién es,\nya sabes cómo se llama.",4,0,-1,5,"",0,4,"aa",-1,0,-1,0,102,102,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00832c",4,"¡Papelito venturoso,\nquién fuera dentro de ti\npara darle mil abrazos\nal ángel que te ha de abrir!",4,0,-1,5,"",0,4,"i",-1,0,-1,0,102,102,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-00832d",4,"Porque mi letra no ves,\npiensas que de ti me olvido;\ny en el fondo de mi pecho\ná cada instante te escribo.",4,0,-1,5,"",0,4,"io",-1,0,-1,0,102,102,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00832e",4,"Llorando te la escribí,\nllorando te la mandé;\nlas lágrimas de mis ojos\nno me la dejaron ver.",4,0,-1,5,"",0,4,"e",-1,0,-1,0,102,102,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00832f",4,"Una carta tengo escrita,\nno tengo quien se la lleve\nal amante de mi vida\ny en su mano se la entregue.",4,0,-1,5,"",0,4,"ee",77,0,-1,0,102,102,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00832g",4,"Suspiros que de mí salgan\ny otros que de ti saldrán,\nsi en el camino se encuentran,\n¡qué de cosas se dirán!",4,0,-1,5,"",0,4,"a",147,0,-1,0,102,102,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00833",4,"Se engaña aquel que dice\nque el que está ausente\nolvida lo pasado\npor lo presente.",4,0,-1,5,"",6,4,"ee",15,0,-1,0,103,103,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00834",4,"Si con el pensamiento\nse caminara,\nmás de cuatro ratitos\nte acompañara.",4,0,-1,5,"",6,4,"aa",57,0,-1,0,103,103,"","",1,"","","",1,0,0,[],""],["palau_cantares-00835",4,"¿Cuál de los dos amantes\ntendrá más pena?\n¿El que se ausenta libre\nó el que se queda?",4,0,-1,5,"",6,4,"ea",-1,0,-1,0,103,103,"","",1,"","","",2,0,0,[],""],["palau_cantares-00836",4,"El pañuelo rosado\nque tú me diste,\nlo desdoblo y lo beso\ncuando estoy triste.",4,0,-1,5,"",6,4,"ie",153,0,-1,0,103,103,"","",1,"","","",1,0,0,[],""],["palau_cantares-00837",4,"Se oyeran los suspiros\ndel que se ausenta,\nsi no hicieran más eco\nlos que están cerca.",4,0,-1,5,"",6,4,"ea",-1,0,-1,0,103,103,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00838",4,"No estaré jamás sin ti,\nque sólo podrá el rigor\nsepararme de tu vista,\nmas no de mi corazón.",4,0,-1,5,"",0,4,"o",-1,0,-1,0,103,103,"","",1,"","","",6,0,0,[],""],["palau_cantares-00839",4,"Amor, mientras caminares\ncaminarán mis suspiros:\ndondequiera que te pares\ntendrán mis penas alivio.",4,0,-1,5,"",0,4,"io",-1,0,-1,0,103,103,"","",1,"","","",2,0,0,[],""],["palau_cantares-00840",4,"Deseando estoy, madre,\nque llegue el viernes:\nes víspera del día\nque mi amor viene.",4,0,-1,5,"",6,4,"ee",-1,0,-1,0,103,103,"","",1,"","","",2,0,0,[],""],["palau_cantares-00841",4,"Cuando salí de Sevilla,\nvolví la cara llorando:\nAdiós, tierrecita mía,\n¡qué lejos te vas quedando!",4,0,-1,5,"",0,4,"ao",33,0,-1,0,103,103,"","",1,"","","",1,0,0,[],""],["palau_cantares-00842",4,"Mi amante está de camino,\nla Virgen vaya con él,\ny le guíe y le acompañe\nhasta que lé vuelva á ver.",4,0,-1,5,"",3,4,"e",-1,0,-1,0,103,103,"","",1,"","","",1,0,0,[],""],["palau_cantares-00843",4,"Me mandastes una carta\ncon una cintita azul;\nno quiero carta ni cinta,\nque quiero que vengas tú.",4,0,-1,5,"",0,4,"u",-1,0,-1,0,103,103,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00844",4,"Todas las mañanas\nme levanto y digo:\n«El lucerito que á mí me alumbraba\nya no está conmigo.»",4,0,-1,5,"",3,4,"io",106,0,-1,0,103,103,"","",1,"","","",2,0,0,[],""],["palau_cantares-00847",4,"Ya los ojitos me duelen\nde mirar tanto el camino\npor ver si veo venir\nel espejo en que me miro.",4,0,-1,5,"",0,4,"io",-1,0,-1,0,103,103,"","",1,"","","",2,0,0,[],""],["palau_cantares-00848",4,"Con la pena de no verte,\nno sé cómo tengo vida;\npero Dios, con su poder,\nme tiene fortalecida.",4,0,-1,5,"",0,4,"ia",37,0,-1,0,103,103,"","",1,"rm_t3","","",5,0,0,[],""],["palau_cantares-00851",4,"Cuando mi gitano\nse apartó de mí,\nde las fatiguitas que me dieron, madre,\nal suelo caí.",4,0,-1,5,"",3,4,"i",23,0,-1,0,103,103,"","",1,"","","",2,0,0,[],""],["palau_cantares-00852",4,"En la ventana me puse\nhasta verte transponer,\ny el pañuelo que me diste\nen lágrimas lo empapé.",4,0,-1,5,"",0,4,"e",-1,0,-1,0,103,103,"","",1,"","","",1,0,0,[],""],["palau_cantares-00853",4,"A la Dolorosa\nle ayuno los viernes\npara que me ponga, compañera mía,\nen donde te viere.",4,0,-1,5,"",3,4,"ee",-1,0,-1,0,104,104,"","",1,"","","",2,0,0,[],""],["palau_cantares-00854",4,"El día que yo me entere\nque el barco está en la bahía,\ntodas las penas que tengo\nse volverán alegrías.",4,0,-1,5,"",0,4,"ia",-1,0,-1,0,104,104,"","",1,"","","",1,0,0,[],""],["palau_cantares-00855",4,"Si supiera la estrella\nque te guiaba,\nla metiera en mi pecho,\nla venerara.",4,0,-1,5,"",6,4,"aa",-1,0,-1,0,104,104,"","",1,"","","",2,0,0,[],""],["palau_cantares-00856",4,"Válgame un divé, serrana,\nlo que me cuesta tu ausencia:\ndos años de enfermedad\ny tres de convalecencia.",4,0,-1,5,"",0,4,"ea",46,0,-1,0,104,104,"","",1,"","","",1,0,0,[],""],["palau_cantares-00857",4,"Cuatro son las heridas\nque me atormentan:\ntu hermosura, tu gracia,\nmi amor, tu ausencia;\nmira si puedo\nvivir con tanta herida\npor mucho tiempo.",4,0,-1,5,"",4,7,"eo",-1,0,-1,0,104,104,"","",1,"","","",2,0,0,[],""],["palau_cantares-00858",4,"El querer que te tengo\nparece sombra:\ncuanto más apartado,\nmás cuerpo toma.\nLa ausencia es aire\nque apaga el fuego chico\ny enciende el grande.",4,0,-1,5,"",4,7,"ae",-1,0,-1,0,104,104,"","",1,"","","",4,0,0,[],""],["palau_cantares-00859",4,"Soy castillo en lo alto,\npiedra en lo fuerte;\nsoy constante en amarte,\nfirme en quererte.\nSi tú me amas,\nsoy constante aunque el mundo\nsobre mí caiga.",4,0,-1,3,"",4,7,"aa",-1,0,-1,0,105,105,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00859-e2",4,"Diez años después de muerto,\nla tierra me preguntó\nsi te había ya olvidado\ny yo le dije que no.",4,0,-1,3,"",0,4,"o",2,0,-1,0,105,105,"","",1,"","","",3,0,0,[],""],["palau_cantares-00859-e3",4,"Todos los caracolillos\nque hay á la orilla del mar\nme aconsejan que te olvide\ny no te puedo olvidar.",4,0,-1,3,"",0,4,"a",21,0,-1,0,105,105,"","",1,"","","",1,0,0,[],""],["palau_cantares-00859-e4",4,"El confesor,me ha dicho\nque no te quiera,\ny yo le dije: «¡Padre,\nsi usted la viera!\nEs tan bonita,\nque á las ánimas muertas\nlas resucita.»",4,0,-1,3,"",4,7,"ia",50,0,-1,0,105,105,"","",1,"","","",4,0,0,[],""],["palau_cantares-00859-e5",4,"Entre Sevilla y Triana\nhay un río caudaloso;\nentre dos que bien se quieren\nno hay nada dificultoso.",4,0,-1,3,"",0,4,"oo",160,0,-1,0,105,105,"","",1,"","","",1,0,0,[],""],["palau_cantares-00860",4,"Fragua, yunque y martillo\nrompen los metales;\nel juramento que yo á ti te he hecho\nno lo rompe nadie.",4,0,-1,3,"",3,4,"ae",-1,0,-1,0,105,105,"","",1,"","","",1,0,0,[],""],["palau_cantares-00860-e2",4,"Firmo, confirmo y afirmo,\nfirmo y confirmo mi fe,\nfirmo que yo seré firme,\nfirmo que firme seré.",4,0,-1,3,"",0,4,"e",77,0,-1,0,105,105,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-00860-e3",4,"Más allá de la vida\nhe de quererte:\nque amor está en el alma\ny ésta no muere.",4,0,-1,3,"",6,4,"ee",-1,0,-1,0,105,105,"","",1,"","","",2,0,0,[],""],["palau_cantares-00860-e4",4,"Cuando se quiere de veras\nno se mira el qué dirán;\nquien tiene fe en el camino\nnunca vuelve el paso atrás.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,105,105,"","",1,"","","",3,0,0,[],""],["palau_cantares-00860-e5",4,"Me tiraste de la cuerda\npor ver si me blandeaba,\ny me encontraste más firme\nque el muro de la Giralda.",4,0,-1,3,"",0,4,"aa",-1,0,-1,0,105,105,"","",1,"","","",1,0,0,[],""],["palau_cantares-00861",4,"No tengas pena, morena,\nque primero ha de faltar\nel sol en Sierra Morena,\nque yo olvide tu amistad.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,106,106,"","",1,"","","",2,0,0,[],""],["palau_cantares-00861-e10",4,"Juramento tengo hecho\ncon el Señor de la Sangre\nde no olvidar tu querer\nhasta que el Señor lo mande.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,106,106,"","",1,"","","",2,0,0,[],""],["palau_cantares-00861-e3",4,"Deja que la gente diga,\ndeja que la gente hable;\nen queriéndonos los dos,\naunque no nos quiera nadie.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,106,106,"","",1,"","","",3,0,0,[],""],["palau_cantares-00861-e4",4,"Te he de seguir queriendo,\naunque me cueste\nmorir en un madero\npúblicamente;\nque no es afrenta\nmorir en un madero\npor la belleza.",4,0,-1,3,"",4,7,"ea",-1,0,-1,0,106,106,"","",1,"","","",2,0,0,[],""],["palau_cantares-00861-e5",4,"Este querer tuyo y mío,\nparece que está de Dios,\nmientras más nos lo critican,\nmás nos queremos los dos.",4,0,-1,3,"",0,4,"o",87,0,-1,0,106,106,"","",1,"rm_t2","","",4,0,0,[],""],["palau_cantares-00861-e6",4,"Déjales que digan, digan,\ny de mí formen historia,\nque el que se muere queriendo\nse va derecho á la gloria.",4,0,-1,3,"",0,4,"oa",126,0,-1,0,106,106,"","",1,"","","",1,0,0,[],""],["palau_cantares-00861-e7",4,"Todos me dicen que adoro\nun clavel de mal color;\ndiga el mundo lo que quiere,\ná mí me parece un sol.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,106,106,"","",1,"","","",4,0,0,[],""],["palau_cantares-00861-e8",4,"Aunque me ves encogida\ny que tengo pocos años,\nen tocando á la firmeza,\nni la cruz de San Fernando.",4,0,-1,3,"",0,4,"ao",-1,0,-1,0,106,106,"","",1,"rm_t2, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00861-e9",4,"Soy río que no se enturbia\naunque caiga una tormenta,\ny me mantengo más claro\nque los caños de la huerta.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,106,106,"","",1,"","","",1,0,0,[],""],["palau_cantares-00862a",4,"Al umbral de la puerta\nle he preguntado:\n«¿Mientras yo he estado ausente\nquién ha reinado?»\nMe ha respondido\nque, en ausencia y presencia,\nyo sólo he sido.",4,0,-1,3,"",4,7,"io",101,0,-1,0,106,106,"","",1,"","","",1,0,0,[],""],["palau_cantares-00862b",4,"Amor mío, no pierdas\nlas esperanzas,\nque en el pozo más hondo\nla soga alcanza.",4,0,-1,3,"",6,4,"aa",-1,0,-1,0,106,106,"","",1,"rm_t2, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00862c",4,"Las estrellas y luceros\nque asoman por el oriente\nno tienen tanta firmeza\ncomo yo para quererte.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,106,106,"","",1,"","","",10,0,0,[],""],["palau_cantares-00862d",4,"Yo me cojo á las raíces\nque están debajo de tierra,\ny á las ramas no me cojo\nporque el viento se las lleva.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,106,106,"","",1,"","","",1,0,0,[],""],["palau_cantares-00862e",4,"El querer es cuesta arriba\ny el olvidar cuesta abajo:\nquiero subir cuesta arriba\naunque me cueste trabajo.",4,0,-1,3,"",1,4,"ao",168,0,-1,0,106,106,"","",1,"","","",1,0,0,[],""],["palau_cantares-00862f",4,"A mi corazón le han dado\nhiel y vinagre á beber,\ny con gusto lo ha tomado\npor no dejar tu querer.",4,0,-1,3,"",1,4,"e",20,0,-1,0,106,106,"","",1,"","","",2,0,0,[],""],["palau_cantares-00862g",4,"Yo soy como aquel buen viejo\nque moritos cautivaron:\npor martirios que le dieron,\nnunca dejó su rosario.",4,0,-1,3,"",0,4,"ao",-1,0,-1,0,106,106,"","",1,"","","",1,0,0,[],""],["palau_cantares-00862j",4,"Primero que yo me aparte\ndel querer de los Manueles,\nhan de echar los olivitos\nracimos de uvas lairenes.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,106,106,"","",1,"","","",3,0,0,[],""],["palau_cantares-00863",4,"Si al pie de mi sepultura\nme vinieras á llorar,\nlas cenizas de mi cuerpo\nse habían de menear.",4,0,-1,3,"",0,4,"a",21,0,-1,0,107,107,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00864",4,"Estoy queriendo á un chaval\nque á mi padre no le gusta,\ny yo digo que el querer\ntiene licencia absoluta.",4,0,-1,3,"",0,4,"ua",-1,0,-1,0,107,107,"","",1,"","","",1,0,0,[],""],["palau_cantares-00865",4,"Échame una penitencia\nque yo la pueda cumplir;\npero que llegue á olvidarte,\nya no depende de mí.",4,0,-1,3,"",0,4,"i",-1,0,-1,0,107,107,"","",1,"","","",1,0,0,[],""],["palau_cantares-00865-e2",4,"Cuatro velas encendidas\ny un hábito franciscano\nnecesitaba mi cuerpo\npara olvidar á quien amo.",4,0,-1,3,"",0,4,"ao",-1,0,-1,0,107,107,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-00865-e3",4,"Yo le dije á un platero:\n«Hazme de plata\nuna mujer constante\nque no sea falsa.»\nY él me responde\nque de mujer constante\nno tiene molde.",4,0,-1,3,"",4,7,"oe",-1,0,-1,0,107,107,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00865-e4",4,"Las estrellitas del cielo\nse han de caer á millares,\nflamenca, porque te olvide,\ny esto no lo verá nadie.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,107,107,"","",1,"","","",25,0,0,[],""],["palau_cantares-00865-e5",4,"Aunque pase más fatigas\nque clavos tiene una puerta,\nyo te tengo de querer;\nque el mundo da muchas vueltas.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,107,107,"","",1,"","","",5,0,0,[],""],["palau_cantares-00865-e6",4,"Yo bien fuera constante,\npero me temo\nque me tengan por monstruo\nlos de mi sexo.",4,0,-1,3,"",6,4,"eo",-1,0,-1,0,107,107,"","",1,"","","",2,0,0,[],""],["palau_cantares-00866",4,"A las plantas de la Virgen\nquiero llegar á hacer voto\nde no olvidarte en la vida,\nni dejarte á ti por otro.",4,0,-1,3,"",0,4,"oo",-1,0,-1,0,107,107,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00867",4,"Ni mi padre, ni mi madre,\nni San Antonio bendito\nme pueden á mí quitar\nque yo te quiera un poquito.",4,0,-1,3,"",0,4,"io",119,0,-1,0,107,107,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00868",4,"Por darle gusto á mi madre\ny á mi corazón dolor,\ndije que no te quería,\nqueriéndote más que á Dios.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,107,107,"","",1,"","","",1,0,0,[],""],["palau_cantares-00869",4,"Todo aquel que venga y diga\nque te olvide, vida mía;\naquel será mi enemigo\nmientras me dure la vida.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,107,107,"","",1,"","","",1,0,0,[],""],["palau_cantares-00870",4,"Aunque en mil años no vuelvas,\nyo seré como la mimbre,\nque la bambolea el aire,\npero se mantiene firmé.",4,0,-1,3,"",5,4,"e",-1,0,-1,0,107,107,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00871",4,"El alma que tengo es tuya\nen una conformidad:\nque si presente te quiero,\nausente te quiero más.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,108,108,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00872",4,"Si por tu querer me expongo\ná riesgo de que me maten,\nvaya el mundo enhoramala,\nque yo no quiero olvidarte.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,108,108,"","",1,"","","",2,0,0,[],""],["palau_cantares-00873",4,"Más firme soy en quererte\nque las horas del reloj:\nel reloj muda las horas,\npero mi firmeza no.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,108,108,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00874",4,"Por tu querer quebranté\nlas leyes de la obediencia,\ny atrás no me he de volver,\nporque me llamo firmeza.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,108,108,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00875",4,"Los árboles de Aranjuez\nunidos de siete en siete\nno tienen tanta firmeza\ncomo yo para quererte.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,108,108,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00876",4,"Firma tú y firmaré yo,\ny se juntarán dos firmas;\nveremos cuál de los dos\ncon más firmeza camina.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,108,108,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00877",4,"Soy más firme que un navio\ncuando lo están carenando;\nmientras más golpes le dan,\nmás firme se va quedando.",4,0,-1,3,"",0,4,"ao",33,0,-1,0,108,108,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00878",4,"Aunque me ves niña, tengo\nlas palabritas muy firmes;\nsi tus promesas son falsas,\nlas mías nunca se rinden.",4,0,-1,3,"",0,4,"ie",-1,0,-1,0,108,108,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00879",4,"Seré para ti más firme\nque la Isla de León,\nque el año del terremoto\ntembló, pero no cayó.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,108,108,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00880",4,"Estrellas del alto cielo,\nbajad y firmad por mí;\nque cumpliré la palabra\nque al que está ausente le dí.",4,0,-1,3,"",0,4,"i",23,0,-1,0,108,108,"","",1,"lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["palau_cantares-00881",4,"Mi corazón en quererte\nes un monte de espesura;\nmientras más ramas le cortan,\ntiene la raíz más dura.",4,0,-1,3,"",0,4,"ua",17,0,-1,0,108,108,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00882",4,"Tú sola reinas en mí:\nte lo dije, y no receles,\nporque no ha de reinar nadie,\nbien mío, donde tú reines.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,108,108,"","",1,"","","",2,0,0,[],""],["palau_cantares-00883",4,"Cuanto más hondillo un pozo,\nmás fresquita sale el agua;\ncuanto más retiradito,\nmás firmes son mis palabras.",4,0,-1,3,"",0,4,"aa",-1,0,-1,0,108,108,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00884",4,"Soy prisionero de amor\ny lo seré mientras viva;\nque el prisionero de amor\nprimero muere que olvida.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,108,108,"","",1,"","","",1,0,0,[],""],["palau_cantares-00885",4,"¿Cómo quieres que te olvide\nsi has sido mi compañera\ny el amor echa raíces\ncomo la planta en la tierra?",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,108,108,"","",1,"rm_t2, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00886",4,"Desecha todo temor,\nvive alegre y placentero;\nque el que fué primer amor\nsiempre ha sido verdadero.",4,0,-1,3,"",1,4,"eo",38,0,-1,0,108,108,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00887",4,"Por aquellas estrellitas\nque están en el cielo azul,\nque te tengo de querer\naunque no me quieras tú.",4,0,-1,3,"",0,4,"u",-1,0,-1,0,108,108,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00888",4,"Tu querer y mi querer,\ntu pensamiento y el mío,\nson como el agua del río,\nque atrás no puede volver.",4,0,-1,3,"",11,4,"e",20,0,-1,0,108,108,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00889",4,"Se me puso en la cabeza\nque te había de querer,\naunque hubiera más contrarios\nque moros hay en Argel.",4,0,-1,3,"",0,4,"e",-1,0,-1,0,108,108,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00890",4,"Dame tu sangre, serrana,\nque yo te daré la mía\ny haremos una contrata\nque dure toda la vida.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,108,108,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00891",4,"Aunque toquen á rebato\nlas campanas del olvido,\nno podré apagar el fuego\nque esta gitana ha encendido.",4,0,-1,3,"",0,4,"io",101,0,-1,0,109,109,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00892",4,"Yo no sé lo que me has dado,\nque no te puedo olvidar;\nparece que me has tocado\ncon la piedrecita imán.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,109,109,"","",1,"","","",5,0,0,[],""],["palau_cantares-00893",4,"Con la sangre de mis venas\nte firmara una escritura\nde no dejar tu querer\nni en la misma sepultura.",4,0,-1,3,"",0,4,"ua",17,0,-1,0,109,109,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00894",4,"Mientras más ausente estoy,\nmás firme estoy en amar;\nla luz del cielo me falte\nsi yo te llego á olvidar.",4,0,-1,3,"",0,4,"a",21,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00895",4,"Yo no te puedo olvidar,\nporque es mi querer muy grande:\nyo te tengo á ti metida\nen la masa de la sangre.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00896",4,"Tan imposible lo hallo\nque tú puedas olvidarme,\ncomo escribir en el agua\ny echar una piedra sangre.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,109,109,"","",1,"lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00897",4,"Yo te quiero y te requiero\ny te tengo de querer\nhasta mudar el pellejo\ncomo San Bartolomé.",4,0,-1,3,"",0,4,"e",-1,0,-1,0,109,109,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00898",4,"Primero que yo te olvide,\n¡mira qué comparación!,\nha de calentar la luna\ny ha de refrescar el sol.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00899",4,"Yo te tengo de querer\naunque le pese á mi estrella,\naunque contra mí se opongan\naire, fuego, mar y tierra.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,109,109,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00900",4,"No pienses, dueño querido,\nque yo te podré olvidar;\nlo que en mi pecho se encierra\nmis obras te lo dirán.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00901",4,"Aunque las piedras den gritos,\ny el sol deje de correr,\ny el agua del mar se acabe,\nyo te tengo de querer.",4,0,-1,3,"",0,4,"e",20,0,-1,0,109,109,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00902",4,"Por darles gusto á mis padres\ny á mi corazón pesar,\ndije que no te quería,\n¡y no te puedo olvidar!",4,0,-1,3,"",0,4,"a",21,0,-1,0,109,109,"","",1,"","","",1,0,0,[],""],["palau_cantares-00903",4,"Mi fortuna ó mi desgracia\nhizo que te conociera\npara ser esclavo tuyo\ntodo el tiempo que viviera.",4,0,-1,3,"",0,4,"ea",44,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00904",4,"Me quieren quitar á mí\nel que yo tu cara vea:\npor cima de quien lo estorbe\nhe de hacer una vereda.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00905",4,"Si yo te faltara en algo\nde lo que te prometí,\nque me vuelva piedra mármol,\nmi cuerpo tenga mal fin.",4,0,-1,3,"",0,4,"i",-1,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00906",4,"Mi padre, porque te quiero,\nme castiga con rigor:\nmucho puede la obediencia,\npero más puede el amor..",4,0,-1,3,"",0,4,"o",72,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00907",4,"Tan imposible lo hallo\nel olvidar tu cariño\ncomo llegar á quitarle\ná San Antonio su Niño.",4,0,-1,3,"",0,4,"io",176,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00908",4,"Una palabra te he dado;\ny primero he de morir\ny faltarle al sol sus rayos\nque dejarla de cumplir.",4,0,-1,3,"",0,4,"i",157,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00909",4,"Permita Dios, si me olvidas,\nte trague la mar serena;\ny si yo te olvido á ti,\npase por la misma pena.",4,0,-1,3,"",0,4,"ea",59,0,-1,0,109,109,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00910",4,"Al pie de la sepultura,\nya para echarme ó no echarme,\nno pudo la ingrata muerte\nde tu querer apartarme.",4,0,-1,3,"",0,4,"ae",35,0,-1,0,109,109,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00911",4,"Diez años después de muerto\ny de gusanos comido,\nletreros tendrán mis huesos,\ndiciendo que te han querido.",4,0,-1,3,"",0,4,"io",101,0,-1,0,110,110,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00912",4,"Todo el mundo me aconseja\nque deje yo tu amistad;\ny yo les digo: - Señores,\n¿es envidia ó caridad?",4,0,-1,3,"",0,4,"a",16,0,-1,0,110,110,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00913",4,"Al pie del suplicio estuve\ncon la sentencia leída:\n¡si olvidaba tu querer,\nme perdonaban la vida!",4,0,-1,3,"",0,4,"ia",37,0,-1,0,110,110,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00914",4,"Aunque me dieran más palos\nque le dan al martinete,\nno te tengo de olvidar,\nporque es mi gusto quererte.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,110,110,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00915",4,"Y yo le dije al verdugo:\n- Compadre, aprieta muy firme,\nque olvidar á esa mujer\nes una cosa imposible.",4,0,-1,3,"",0,4,"ie",-1,0,-1,0,110,110,"","",1,"","","",2,0,0,[],""],["palau_cantares-00916",4,"Aunque pase más trabajos\nque arenas tienen los ríos\ny pinos tienen los montes,\nno te he de olvidar, bien mío.",4,0,-1,3,"",0,4,"io",-1,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00917",4,"Hasta la sepulturita\nte tengo de estar queriendo,\nporque has tenido conmigo\npartidas de caballero.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,110,110,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00918",4,"Aunque tu querer me mate,\nno he de dejar de quererte,\nque te quiero con el alma,\ny el alma nunca se muere.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00919",4,"Á la sepultura iremos,\ntú detrás y yo delante;\nyo no me aparto de ti\nhasta que Dios nos aparte.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,110,110,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00920",4,"Todo el mundo en contra mía,\nserrana, porque te quiero;\ntodo el mundo en contra mía,\ny yo contra el mundo entero.",4,0,-1,3,"",1,4,"eo",38,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00921",4,"Aunque me digan de ti\nlo que dicen del demonio,\nyo te tengo de querer,\ncarita de San Antonio.",4,0,-1,3,"",0,4,"oo",169,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00922",4,"Sentenciado estoy á muerte\nsi me ven hablar contigo;\n¡mira si te quiero bien\nque no le temo al castigo!",4,0,-1,3,"",0,4,"io",106,0,-1,0,110,110,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00923",4,"Me dicen que te despida,\nno soy de tal parecer;\nme daré muerte primero\nque tal cosa llegue á hacer.",4,0,-1,3,"",0,4,"e",20,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00924",4,"Si el querer bien es delito,\npadre mío, que me prendan\ny me lleven á la cárcel,\nque en mi querer no hay enmienda.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,110,110,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00925",4,"Consejillos que me daban\ny cuenta no me tenían,\npor un oído me entraban\ny por otro, me salían.",4,0,-1,3,"",1,4,"ia",500,0,-1,0,110,110,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00926",4,"Subí á la sala del Crimen\ny le dije al presidente:\n- Si el querer es un delito,\nque me sentencien á muerte.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,110,110,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00927",4,"Todos me dicen á mí\nque te olvide, que te olvide;\ny el olvidarte será\ntenerte el amor más firme.",4,0,-1,3,"",0,4,"ie",-1,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00928",4,"Porque te quiero me echan\ná la garganta un cordel\ny á los pies una cadena:\nahora te quiero más bien.",4,0,-1,3,"",0,4,"e",-1,0,-1,0,110,110,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00929",4,"Todos los santos del cielo,\nángeles y serafines,\nme aconsejan que te deje,\ny yo cada vez más firme.",4,0,-1,3,"",0,4,"ie",-1,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00930",4,"Aunque me vea en dos palos,\ny un Capuchino á los pies,\ny un dogal á la garganta,\nyo siempre te he de querer.",4,0,-1,3,"",0,4,"e",-1,0,-1,0,110,110,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00931",4,"Aunque me veas cadáver\ná la puerta de una ermita,\ná ti no te dé cuidado,\nque los muertos resucitan.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,111,111,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00932",4,"Hasta el confesor me ha dicho\nque te olvide, y digo yo\nque primero olvidaría\nla madre que me parió.",4,0,-1,3,"",0,4,"o",2,0,-1,0,111,111,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00933",4,"Aunque te vea difunta,\ncon cuatro velas ardiendo,\nhasta la sepulturita\nte tengo que estar queriendo.",4,0,-1,3,"",0,4,"eo",52,0,-1,0,111,111,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00934",4,"Los confesores me mandan\nque te olvide, Manolillo;\nlos confesores no saben\nlo que vale un buen cariño.",4,0,-1,3,"",0,4,"io",-1,0,-1,0,111,111,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00935",4,"Dicen que me han de matar\nsi me ven hablar contigo:\nya le pueden levantar\ná la escopeta el gatillo.",4,0,-1,3,"",0,4,"io",-1,0,-1,0,111,111,"","",1,"","","",20,0,0,[],""],["palau_cantares-00936",4,"Arrepentida me eché\ná los pies de un confesor;\nme dijo que te olvidara:\ncomo un insulto me dió.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,111,111,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00937",4,"Mi padre me tiene dicho\nque me tiene que sacar\nlos ojos con que te miro,\ny yo que te he de mirar.",4,0,-1,3,"",0,4,"a",21,0,-1,0,111,111,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00938",4,"El Padre Santo de Roma\nme dijo que te olvidara;\nyo le dije: - Padre mío,\naunque me recondenara.",4,0,-1,3,"",0,4,"aa",57,0,-1,0,111,111,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00939",4,"Ni tu padre, ni tu madre,\nni el que dispone en los cielos,\nme apartan de tu querer,\nmientras tú me estés queriendo.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,111,111,"","",1,"rm_t2, lafuente_madrid","","",10,0,0,[],""],["palau_cantares-00940",4,"- Hombre, olvida á esa mujer.\n- Padre mío, yo no puedo;\nechadme otra penitencia,\nque cumplir esa no quiero.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,111,111,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00941",4,"Aunque todos se opusieran,\ncontigo me he de casar;\nque más estimo mi gusto\nque cuanto me puedan dar.",4,0,-1,3,"",0,4,"a",21,0,-1,0,111,111,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00942",4,"El decirme que te olvide\nes predicar en desierto,\nmachacar en hierro frío\ny platicar con un muerto,",4,0,-1,3,"",0,4,"eo",88,0,-1,0,111,111,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00943",4,"Los confesores me dicen\nque te olvide, y no lo haré;\nlos confesores no saben\nlo que cuesta un buen querer.",4,0,-1,3,"",0,4,"e",-1,0,-1,0,111,111,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00944",4,"A los presidios de Orán\nme llevan porque te olvide:\naunque me lleven á Ceuta\nolvidarte es imposible.",4,0,-1,3,"",0,4,"ie",-1,0,-1,0,111,111,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00945",4,"Aunque me digan que eres\nmujer de mala conducta\ny de malos procederes,\nte quiero porque me gustas.",4,0,-1,3,"",0,4,"ua",-1,0,-1,0,111,111,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00946",4,"Corazón de filigrana\nembutido en fino acero,\n¿cómo quieres que te olvide\nsi has sido mi amor primero?",4,0,-1,3,"",0,4,"eo",38,0,-1,0,111,111,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00947",4,"Todo el mundo me lo dice\nque te deje, que te deje;\ny yo le respondo al mundo:\n- Con la muerte, con la muerte.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,111,111,"","",1,"","","",14,0,0,[],""],["palau_cantares-00948",4,"Tan imposible lo hallo\nque te deje de adorar\ncomo tomar un caballo\ny pasar con él la mar.",4,0,-1,3,"",1,4,"a",21,0,-1,0,111,111,"","",1,"lafuente_madrid","","",13,0,0,[],""],["palau_cantares-00949",4,"Me aconsejan que te olvide,\n¡mira qué barbaridad!\n¡Como no saben querer,\nno saben aconsejar!",4,0,-1,3,"",0,4,"a",-1,0,-1,0,111,111,"","",1,"rm_t2, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00950",4,"Agua me nieguen las fuentes,\nel cielo me desampare,\nlluevan las plagas de Egipto,\nserrana, si te olvidare.",4,0,-1,3,"",0,4,"ae",175,0,-1,0,111,111,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00951",4,"Los cuatro elementos juntos,\nagua, tierra, viento y fuego,\nno podrán hacer que olvide\nlo mucho que yo te quiero.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,112,112,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00952",4,"No pienses que por muerte\nhe de olvidarte,\nporque hasta mis cenizas\nhan de adorarte.",4,0,-1,3,"",6,4,"ae",8,0,-1,0,112,112,"","",1,"","","",1,0,0,[],""],["palau_cantares-00953",4,"Para olvidar tu querer,\nhe de ver yo dos señales:\nque se caigan las estrellas\ny que se sequen los mares.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,112,112,"","",1,"rm_t2, carrizo_salta, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00954",4,"En Dios y en ti pensaré\nsin que haya dificultad;\ná Dios le amaré por siempre,\ny á ti por siempre jamás.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,112,112,"","",1,"","","",2,0,0,[],""],["palau_cantares-00955",4,"Todo el tiempo de mi vida\namándote pasaré,\ny si me olvidas por otro,\nen ti y en Dios pensaré.",4,0,-1,3,"",0,4,"e",77,0,-1,0,112,112,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00956",4,"Para olvidarte yo á ti\nera preciso que hubiera\notra tierra y otro cielo\ny otro Dios que dispusiera.",4,0,-1,3,"",0,4,"ea",44,0,-1,0,112,112,"","",1,"","","",1,0,0,[],""],["palau_cantares-00957",4,"Con el abaniquito\nque te hace aire\nestás haciendo señas\ná quien ya sabes;\ncon ese tema,\nlo' que á ti te da aire\ná mí me quema.",4,0,-1,3,"",4,7,"ea",216,0,-1,0,113,113,"","",1,"","","",2,0,0,[],""],["palau_cantares-00957-e2",4,"«¡Yo te adoro!,» una noche\ndije dormido,\ny desperté celoso\nde haberme oído.",4,0,-1,3,"",6,4,"io",101,0,-1,0,113,113,"","",1,"","","",3,0,0,[],""],["palau_cantares-00957-e3",4,"Te entraste por los ojos\ncon tal estrago\nque, del amor herido,\nciego he quedado;\ny si algo veo,\nson las dichas en sombra,\nclaros los celos.",4,0,-1,3,"",4,7,"eo",-1,0,-1,0,113,113,"","",1,"","","",3,0,0,[],""],["palau_cantares-00957-e4",4,"Una peseta les mando\ná las ánimas benditas\nporque no ronde tu casa\naquel que te solicita.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,113,113,"","",1,"","","",1,0,0,[],""],["palau_cantares-00957-e5",4,"Dicen que los celos matan,\nyo digo que no es así;\nque si los celos mataran,\nme hubieran matado á mí.",4,0,-1,3,"",0,4,"i",23,0,-1,0,113,113,"","",1,"machado_venezuela, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00957-e6",4,"Desempedraré tu calle\ny la cubriré de arena,\npara mirar las pisadas\nde los que rondan tu reja.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,113,113,"","",1,"rm_t2, rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00958",4,"Tengo un clavel encarnado\ná la sombra y bajo llave,\npara que el sol no lo vea\ny con mirarlo lo aje.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,113,113,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00958-e2",4,"Si yo supiera las piedras\nque mi amor pisa en la calle,\nlas volviera del revés,\nque no las pisara nadie.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,113,113,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00958-e3",4,"No quiero que hables con nadie\nsino con el confesor,\ncon tu padre y con tu madre,\ncon tus hermanos y yo.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,113,113,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00958-e4",4,"Sé que finezas haces\ná otro sujeto;\nbien puedes, pues he sido\nyo tu maestro:\nno te equivoques,\ny, por costumbre, en ellas\ná mí me nombres..",4,0,-1,3,"",4,7,"oe",-1,0,-1,0,113,113,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00959",4,"El sarmiento en la lumbre\ny el que enamora,\npor un lado se encienden,\npor otro lloran;\ntú eres lo propio:\ncuando lloras por verme,\nte vas por otro.",4,0,-1,3,"",4,7,"oo",-1,0,-1,0,114,114,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00959-e3",4,"Yo pensé que de tu pecho\nyo solo tenía llave;\nmas he llegado á entender\nque todo el que quiere abre.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,114,114,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00959-e4",4,"Que un buen mozo te guste\nnadie lo extraña,\nque á mí una buena moza\ntambién me agrada;\npero me espanto\nde verte enamorada\nde un currutaco.",4,0,-1,3,"",4,7,"ao",-1,0,-1,0,114,114,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00959-e5",4,"En insufrible fuego\nde celos ardo;\npor eso determino\nmorir matando;\nporque me alivia\nver á la que me mata\ntambién herida.",4,0,-1,3,"",4,7,"ia",-1,0,-1,0,114,114,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00959-e6",4,"¿Para que me diste el sí,\ntraidora, teniendo dueño,\nsi sabes que no se logra\ncon gusto lo que es ajeno?",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,114,114,"","",1,"rm_t3, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00959-e7",4,"¿Para qué me andas diciendo\nque me quieres y me adoras,\nsi en volviendo las espaldas\nde cualquiera te enamoras?",4,0,-1,3,"",0,4,"oa",198,0,-1,0,114,114,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00959-e8",4,"Ingrata, mala mujer,\nde Dios te venga el castigo:\nsi te has de casar con otro,\n¿para qué tratas conmigo?",4,0,-1,3,"",0,4,"io",106,0,-1,0,114,114,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00960a",4,"Yo te quise, no pensando\nque me habías de olvidar;\ntú juegas con dos barajas\ny yo con una no más.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,114,114,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-00960b",4,"¿Cómo quieres que una luz\nalumbre á dos aposentos?\n¿Cómo quieres que yo quiera\ndos corazones á un tiempo?",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,114,114,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-00960c",4,"Esperando estoy las doce\npara salir disfrazada\npor ver si hallaré á mi amante\nhablando con otra dama.",4,0,-1,3,"",0,4,"aa",-1,0,-1,0,114,114,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00960d",4,"Porque te quiero, te celo;\nque si no, no te celara;\nque si yo no te quisiera,\naunque el diablo te llevara.",4,0,-1,3,"",0,4,"aa",57,0,-1,0,114,114,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00960e",4,"Tengo un vestido en el arca,\nque tiene cuatro colores:\nla ilusión y la esperanza,\nlos celos y los amores.",4,0,-1,3,"",0,4,"oe",5,0,-1,0,114,114,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00960f",4,"Mi amor es una viña\ndonde yo miro\npendientes de una cepa\nmuchos racimos.\nSepa mi amante\nque yo no quiero cepa\ntan abundante.",4,0,-1,3,"",4,7,"ae",47,0,-1,0,114,114,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00960g",4,"Es verdad, lo confieso,\npues lo preguntas,\nque tus falsas caricias\nya me disgustan:\nporque conozco\nque estos mismos halagos\nhaces á otros.",4,0,-1,3,"",4,7,"oo",-1,0,-1,0,114,114,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00960h",4,"Siempre que de tu vista\nme aparto, lloro,\ntemiendo que mis dichas\nlas logre otro:\nque en mis pesares,\nlas dichas son ligeras,\nlargos los males.",4,0,-1,3,"",4,7,"ae",-1,0,-1,0,114,114,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-00961",4,"La gloria de mirarte\nserá un infierno,\nsi se van tus miradas\nhacia otro dueño:\nque es muy amargo\nver en poder ajeno\nbienes logrados.",4,0,-1,3,"",4,7,"ao",-1,0,-1,0,115,115,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00962",4,"Si todo el mundo corrieras,\nfácil te será encontrar\notro amante á quien tú quieras,\nmas no que te quiera más.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,115,115,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00963a",4,"Dices que no la quieres\nni vas á verla;\npero la veredita\nno cría hierba.",4,0,-1,3,"",6,4,"ea",-1,0,-1,0,115,115,"","",1,"fernan_caballero","","",4,0,0,[],""],["palau_cantares-00963b",4,"Por esta calle, que es larga,\nme tengo que pasear\npor darle gusto á una dama,\ny á un majito en qué pensar.",4,0,-1,3,"",0,4,"a",21,0,-1,0,115,115,"","",1,"","","",3,0,0,[],""],["palau_cantares-00963c",4,"Si me quieres á mí solo,\nseré una muralla firme;\npero si quieres á otro,\nseré un rayo para irme.",4,0,-1,3,"",0,4,"ie",184,0,-1,0,115,115,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00963d",4,"Si es que piensas darme enojos\ncon esos amores nuevos,\naunque niña y criatura,\nno me acobardan los celos.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,115,115,"","",1,"","","",2,0,0,[],""],["palau_cantares-00963e",4,"Si usted me quiso de golpe,\nyo le quise de quedito;\nsi usted tiene su pichona,\nyo tengo mi pichoncito.",4,0,-1,3,"",0,4,"io",119,0,-1,0,115,115,"","",1,"","","",2,0,0,[],""],["palau_cantares-00963f",4,"Soy constante y soy mudable,\npero con tal distinción:\nconstante con quien me ama,\ny mudable con quien no.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,115,115,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00963g",4,"Si por beber de una fuente\nhas dejado secar otra,\nolvidar para querer,\nesa es ignorancia loca.",4,0,-1,3,"",0,4,"oa",-1,0,-1,0,115,115,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00963h",4,"Si por querer á un paisano\nolvidas á un militar,\nhazte cuenta que has cambiado\noro fino por metal.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,115,115,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-00964a",4,"Quítate de esa ventana,\nno me seas ventanera;\nque la cuba de buen vino\nno necesita bandera.",4,0,-1,3,"",0,4,"ea",44,0,-1,0,115,115,"","",1,"rm_t3, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00964b",4,"¿De qué te sirve llorar\ny dar vueltas como un loco,\nsi tú te mueres por ella\ny ella se muere por otro?",4,0,-1,3,"",0,4,"oo",-1,0,-1,0,115,115,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-00964c",4,"Un rayo caiga del cielo\ny me parta por mitad\nantes de verte, morena,\nen manos de otro galán.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,115,115,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00965",4,"Haré un hoyito en la arena\ny vivo me enterraré\npor no ver en mano ajena\nprenda que tanto adoré.",4,0,-1,3,"",1,4,"e",77,0,-1,0,116,116,"","",1,"andina_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00965-e2",4,"Dicen que te casas pronto,\ny yo pretendo saber\nel cómo, con quién y cuándo,\nel cuándo, cómo y con quién.",4,0,-1,3,"",0,4,"e",-1,0,-1,0,116,116,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00965-e3",4,"Mi marido es mi marido,\nque no es marido de nadie:\nla que quisiere, marido\nvaya á la guerra y lo gane.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,116,116,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00965-e4",4,"A servir al rey me voy\ncon intención de volver,\ny si te encuentro casada,\nde tu sangre he de beber.",4,0,-1,3,"",0,4,"e",20,0,-1,0,116,116,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00965-e5",4,"Debajo de tu ventana\ntengo un puñal escondido\npara clavarlo en tu pecho\nsi no te casas conmigo.",4,0,-1,3,"",0,4,"io",-1,0,-1,0,116,116,"","",1,"rm_t3, lafuente_madrid","","",29,0,0,[],""],["palau_cantares-00965-e6",4,"De tus finezas hice\nlos escalones\npara subir al trono\nde mis amores:\npoco han durado,\nque en batalla los celos\nme han destronado.",4,0,-1,3,"",4,7,"ao",14,0,-1,0,116,116,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-00965-e7",4,"Yo me embarqué en la nave\nde amor tirano;\ndesembarqué en el puerto\ndel desengaño;\ny estuve amante\nen el golfo de celos\npara anegarme.",4,0,-1,3,"",4,7,"ae",-1,0,-1,0,116,116,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00965-e8",4,"Tengo amor, tengo ausencia\ny tengo celos,\ntengo desconfianza,\npues no te tengo:\nsi te tuviera,\ncelos ni otros disgustos\nme compitieran.",4,0,-1,3,"",4,7,"ea",-1,0,-1,0,116,116,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00966a",4,"Más quiero un desengaño\nque me confunda,\nque no vivir penando\npor una duda:\npues mis recelos\nhacen de leves dudas\nmuy graves celos.",4,0,-1,3,"",4,7,"eo",192,0,-1,0,116,116,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00966b",4,"¿Para qué vienes á verme,\nsi tienes quien te lo estorbe?\nDale gusto á esa persona\ny ten partidas de hombre.",4,0,-1,3,"",0,4,"oe",-1,0,-1,0,116,116,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00966c",4,"De tres colores se viste,\nseñora, mi corazón:\nencarnado, azul y verde,\nque son tres flechas de amor.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,116,116,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00966d",4,"Encarnado, con que rabio\ncontra tan duro rigor\ndesde el punto, niña hermosa,\nque en ti puse mi afición.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,116,116,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00966e",4,"Azul, que me matan celos\ncuando me acuerdo de ti;\nte suplico, dueño amado,\ntengas compasión de mí.",4,0,-1,3,"",0,4,"i",23,0,-1,0,116,116,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00966f",4,"Y lo verde es esperanza,\nporque alcanzarte pretendo;\npues por ti, prenda del alma,\nno vivo sino muriendo.",4,0,-1,3,"",0,4,"eo",52,0,-1,0,116,116,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00966g",4,"- Diga usted, señor platero:\n¿cuánta plata es menester\npara engarzar unos celos\nque me ha dado una mujer?",4,0,-1,3,"",0,4,"e",20,0,-1,0,116,116,"","",1,"","","",2,0,0,[],""],["palau_cantares-00966h",4,"Y le responde el platero:\n- Si esa mujer fuera mía,\nyo le engarzara los celos\ncon palos y mala vida.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,116,116,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-00966i",4,"Bien pareces á todos,\nmas, sin dobleces,\nque á todos bien parezcas\nmal me parece:\n¡y á ti, bien mío,\nparecer bien á todos\nte ha parecido!",4,0,-1,3,"",4,7,"io",-1,0,-1,0,116,116,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00967",4,"Me dicen que á otro quieres,\npero lo dudo,\nque mujer tan amante\nfingir no pudo;\npero te advierto\nque deseo con ansia\nsaber si es cierto.",4,0,-1,3,"",4,7,"eo",88,0,-1,0,117,117,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00968",4,"Al sol es parecido\nquien celos tiene,\nque levanta vapores\nque lo obscurecen;\ny las tormentas\nse forman de las nubes\nde las sospechas.",4,0,-1,3,"",4,7,"ea",-1,0,-1,0,117,117,"","",1,"fernan_caballero","","",2,0,0,[],""],["palau_cantares-00969",4,"Más quisiera, bien mío,\nverte difunta,\nque no que otro mancebo\nte llame suya:\nque de ese modo,\nya que mía no fueras,\nno fueras de otro.",4,0,-1,3,"",4,7,"oo",-1,0,-1,0,117,117,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00970",4,"Al que fuere celoso\ncuando hay motivo,\nno le llamen celoso,\nsino advertido;\nporque los celos,\nen habiendo motivo,\ndejan de serlo.",4,0,-1,3,"",4,7,"eo",-1,0,-1,0,117,117,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00971",4,"Tú quieres á dos juntas\ny esto me agravia:\nquiéreme á mí solita\nó á mi contraria,\nporque más vale\nque haya una satisfecha,\nque dos con hambre.",4,0,-1,3,"",4,7,"ae",-1,0,-1,0,117,117,"","",1,"","","",2,0,0,[],""],["palau_cantares-00972",4,"El que ausente idolatra,\nsiempre los celos\nson los procuradores\nde sus desvelos:\ntodo le altera,\ny como todo es miedo,\ntodo es quimera.",4,0,-1,3,"",4,7,"ea",44,0,-1,0,117,117,"","",1,"","","",1,0,0,[],""],["palau_cantares-00973",4,"Yo pensé, dueño mío,\nque en tu oratorio\nno se daba más culto\nque á un santo solo;\npero reparo\nque tiene más santitos\nque el calendario.",4,0,-1,3,"",4,7,"ao",-1,0,-1,0,117,117,"","",1,"","","",2,0,0,[],""],["palau_cantares-00974",4,"Pasa el hombre celoso\nla vida inquieta\npor descubrir la causa\nde sus sospechas;\nmas no ve el necio\nque le mata este mismo\ndescubrimiento.",4,0,-1,3,"",4,7,"eo",-1,0,-1,0,117,117,"","",1,"","","",1,0,0,[],""],["palau_cantares-00975",4,"Mi amante es muy veleidoso\ny no le veo venir:\n¡si se estará divertiendo\ncon flores de otro jardín!",4,0,-1,3,"",0,4,"i",-1,0,-1,0,117,117,"","",1,"","","",1,0,0,[],""],["palau_cantares-00976",4,"Los celos sólo sirven\npara obligarnos\ná que el fuego soplemos\nmedio apagado:\nporque los celos\nel amor resucitan\naunque esté muerto.",4,0,-1,3,"",4,7,"eo",-1,0,-1,0,117,117,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00977a",4,"El día que yo te vea\nhablando con quien tú sabes\nte cayó la lotería\nde los números cabales.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,117,117,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00977b",4,"Los celos se parecen\ná la pimienta:\nsiendo poca, da gusto;\nsi mucha, quema;\ny el que es machaca\nmas bien atiza el fuego\nque no le apaga.",4,0,-1,3,"",4,7,"aa",-1,0,-1,0,117,117,"","",1,"","","",4,0,0,[],""],["palau_cantares-00978a",4,"Celos son unos recelos\nde la gente enamorada:\nsi son algo, no son celos;\nsi son celos, no son nada.",4,0,-1,3,"",1,4,"aa",49,0,-1,0,117,117,"","",1,"","","",3,0,0,[],""],["palau_cantares-00978b",4,"Tú no me pagas la casa,\ntú no me das de comer:\nme vienes pidiendo celos,\n¿á fundamento de qué?",4,0,-1,3,"",0,4,"e",-1,0,-1,0,117,117,"","",1,"","","",2,0,0,[],""],["palau_cantares-00979",4,"Los celos y las olas\ndel mar son unas,\nque parecen montañas\ny son espuma:\ny olas y celos\nse aplacan al instante\nque cambia el viento.",4,0,-1,3,"",4,7,"eo",-1,0,-1,0,118,118,"","",1,"","","",3,0,0,[],""],["palau_cantares-00980",4,"Yo estoy agonizando,\nyo estoy cadáver,\nque los pícaros celos\nmuerto me traen;\nporque los celos\nmatan al que no sabe\nvivir sin ellos.",4,0,-1,3,"",4,7,"eo",-1,0,-1,0,118,118,"","",1,"","","",1,0,0,[],""],["palau_cantares-00981",4,"El que sin causa cela\ntal vez consigue\nver que lo imaginado\nse verifique,\nporque fomenta\nla idea del agravio,\nque estaba muerta.",4,0,-1,3,"",4,7,"ea",-1,0,-1,0,118,118,"","",1,"","","",1,0,0,[],""],["palau_cantares-00982",4,"Cuando miras á otro\nme desbarato\nporque con las miradas\nse hacen los tratos,\ny yo quisiera\nque todas las miradas\npara mí fueran.",4,0,-1,3,"",4,7,"ea",-1,0,-1,0,118,118,"","",1,"","","",1,0,0,[],""],["palau_cantares-00983",4,"En los impertinentes\nsuelen los celos\npasar de imaginados\ná verdaderos:\ny así no dudo\nque las desconfianzas\nmaten á muchos.",4,0,-1,3,"",4,7,"uo",-1,0,-1,0,118,118,"","",1,"","","",2,0,0,[],""],["palau_cantares-00983-e2",4,"El marido á su esposa\nno pida celos,\nque tal vez obligada\nlos dará ciertos:\ncalle y observe,\ncastigando el delito\ncuando le encuentre.",4,0,-1,3,"",4,7,"ee",-1,0,-1,0,118,118,"","",1,"","","",1,0,0,[],""],["palau_cantares-00983-e3",4,"Mucho se para en tu puerta\nel sereno de tu calle,\nyo le diré que se vaya\ncon la música á otra parte.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,118,118,"","",1,"","","",3,0,0,[],""],["palau_cantares-00983-e4",4,"Los celos no son nada\nmás que sospechas;\nsi es algo, no son celos,\nson evidencias;\ny así el amante\nno confunda aprensiones\ncon realidades.",4,0,-1,3,"",4,7,"ae",-1,0,-1,0,118,118,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00983-e5",4,"«¿Qué son celos?,» pregunta\nun hombre sabio;\ny un rústico responde:\n«Ama, y sabráslo.»",4,0,-1,3,"",6,4,"ao",-1,0,-1,0,118,118,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-00984a",4,"Cuando pican los celos,\nclaro se infiere\nque tiene más cariño\nquien más los siente.",4,0,-1,3,"",6,4,"ee",-1,0,-1,0,118,118,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-00984b",4,"Te diviertes con quien quieres,\nluego vienes, me lo niegas,\ny quieres con tu saber\nhacer á la gente ciega.",4,0,-1,3,"",0,4,"ea",-1,0,-1,0,118,118,"","",1,"rm_t3, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00984c",4,"Si piensas que nada sé,\nte advierto que nada ignoro;\nque no das paso en la calle\nque no me lo cuenten todo.",4,0,-1,3,"",0,4,"oo",-1,0,-1,0,118,118,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00984d",4,"Yo sé los pasos que traes,\naunque me lo niegas siempre;\nándate en ese camino:\ncántaro que va á la fuente...",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,118,118,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-00984e",4,"Te quiero más que si fueras\nhijito de mis entrañas;\npero si quieres á otra,\n¿por qué no me desengañas?",4,0,-1,3,"",0,4,"aa",42,0,-1,0,118,118,"","",1,"","","",2,0,0,[],""],["palau_cantares-00984f",4,"Tú tienes amor con otra\ny quieres amor conmigo;\ntú quieres partir amor,\nyo no quiero amor partido.",4,0,-1,3,"",0,4,"io",-1,0,-1,0,118,118,"","",1,"rm_t3, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00984g",4,"Tú tienes amor con otra,\ny conmigo las chancitas;\nsi te quieres divertir,\ncompra un trompo y una guita.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,118,118,"","",1,"","","",5,0,0,[],""],["palau_cantares-00985",4,"El verme en paz contigo\nya lo deseo,\nporque es muy dura guerra\nla de los celos;\ny así el dejarte\nserá el tínico medio\nde hacer las paces.",4,0,-1,3,"",4,7,"ae",-1,0,-1,0,121,121,"","",1,"","","",2,0,0,[],""],["palau_cantares-00985-e2",4,"Por no sentir mi dama»\ntanto mi ausencia,\nbusca quien la consuele\nde su tristeza;\ny aunque me escribe,\nla que por mí se muere\ncon otros vive.",4,0,-1,3,"",4,7,"ie",190,0,-1,0,121,121,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00985-e3",4,"Al balcón de mis ansias\nsalgo, luz mía,\npero siempre te miro\npor celosía;\ny no es impropio,\npues el que tiene celos\nes todo ojos.",4,0,-1,3,"",4,7,"oo",-1,0,-1,0,121,121,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00985-e4",4,"Me preguntó un amigo\nlo que eran celos;\nno sabe el bien que tiene\ncon no saberlo.\nDe buena gana\ntrocara yo mi ciencia\npor su ignorancia.",4,0,-1,3,"",4,7,"aa",-1,0,-1,0,121,121,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00986a",4,"Ttí desprecias mis trapitos\ny te vas con los galones:\n¡un remiendo mal pegado\nse lleva las atenciones!",4,0,-1,3,"",0,4,"oe",34,0,-1,0,121,121,"","",1,"","","",1,0,0,[],""],["palau_cantares-00986b",4,"Si tuviera cristales\ntu pecho hermoso,\nno viviera este mío\ntan receloso.",4,0,-1,3,"",6,4,"oo",160,0,-1,0,121,121,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00986c",4,"Si quieres que yo te quiera,\nsahúmate con romero,\nque se te quite el olor\nde tus amores primeros",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,121,121,"","",1,"","","",23,0,0,[],""],["palau_cantares-00986d",4,"En amantes dolencias\nsuelen los celos\nser á veces sangrías\nhechas á tiempo.",4,0,-1,3,"",6,4,"eo",-1,0,-1,0,121,121,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-00986f",4,"Tengo celos del aire\nque da en tu cara;\nsi el aire fuese hombre,\nyo le matara.",4,0,-1,3,"",6,4,"aa",57,0,-1,0,121,121,"","",1,"","","",3,0,0,[],""],["palau_cantares-00986g",4,"Hasta al agua que bebes\nle tengo envidia;\nmira si tendré celos\nde quien te mira.",4,0,-1,3,"",6,4,"ia",-1,0,-1,0,121,121,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00987",4,"De que todos te quieran\nyo no me asusto,\nporque quiero que todos\ntengan mi gusto;\npero te aviso\nque no les correspondas,\nque no es preciso.",4,0,-1,3,"",4,7,"io",92,0,-1,0,121,121,"","",1,"","","",2,0,0,[],""],["palau_cantares-00988",4,"Considera por ti propia,\nsi tú me vieras á mí\nestar hablando con otra,\nqué gracia te hiciera á ti.",4,0,-1,3,"",0,4,"i",23,0,-1,0,121,121,"","",1,"","","",3,0,0,[],""],["palau_cantares-00989",4,"Plato de segunda mesa\nnunca en mi vida lo he sido;\nsi ahora quieres que lo sea,\nestás muy mal entendido.",4,0,-1,3,"",0,4,"io",101,0,-1,0,121,121,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00990",4,"En el cementerio entré\ndando voces como un loco,\ny hasta la muerte me dijo\nque tú querías á otro.",4,0,-1,3,"",0,4,"oo",-1,0,-1,0,121,121,"","",1,"","","",2,0,0,[],""],["palau_cantares-00991",4,"Cuando por tu puerta paso,\nel corazón se me enluta\nde ver que no hay más que un árbol\ny hay muchos para la fruta.",4,0,-1,3,"",0,4,"ua",197,0,-1,0,121,121,"","",1,"rm_t3, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00992",4,"Como pájaro humilde\nvengo á tu mano;\nme desprecias por otro\nque va volando.",4,0,-1,3,"",6,4,"ao",-1,0,-1,0,121,121,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00993a",4,"Me llaman el celoso,\n¡mira qué pena!:\nsoy labrador y quiero\nguardar mi hacienda.",4,0,-1,3,"",6,4,"ea",-1,0,-1,0,122,122,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-00993b",4,"Pajarito que lloras\ncon tus gorjeos\nporque en tu pecho sientes\nel mal de celos,\nno te sonrojes,\nque por los celos lloran\ntambién los hombres.",4,0,-1,3,"",4,7,"oe",-1,0,-1,0,122,122,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00993c",4,"Los ojos de mi morena,\nSanta Lucía, guardadlos;\ny si no son para mí,\nvenid, cuervos, y sacadlos.",4,0,-1,3,"",0,4,"ao",501,0,-1,0,122,122,"","",1,"","","",23,0,0,[],""],["palau_cantares-00993d",4,"Si supiera que algún guapo\npretendía tu salero,\nle daba más puñaladas\nque estrellitas tiene el cielo.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,122,122,"","",1,"","","",1,0,0,[],""],["palau_cantares-00993e",4,"Al amanecer del día\nme despido de tu calle;\nque la prenda que yo adoro\nno quiero que otro la guarde.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,122,122,"","",1,"","","",1,0,0,[],""],["palau_cantares-00993f",4,"Todo el mundo me lo dice,\ndigo que tiene razón:\nque hombre que trata con muchas\ná ninguna tiene amor.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,122,122,"","",1,"","","",14,0,0,[],""],["palau_cantares-00993g",4,"Todo el mundo me lo dice,\nyo acredito esta verdad:\nen estando un hombre ausente,\notro ocupa su lugar.",4,0,-1,3,"",0,4,"a",-1,0,-1,0,122,122,"","",1,"lafuente_madrid","","",14,0,0,[],""],["palau_cantares-00993h",4,"Causa de mi perdición,\nquiero apartarme de ti:\nla mujer que quiere á dos\nno puede tener buen fin.",4,0,-1,3,"",0,4,"i",-1,0,-1,0,122,122,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00993i",4,"Yo pensé que era á mí solo,\nserrana, á quien tú querías,\n¡y te diviertes con otro\ntodas las horas del día!",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,122,122,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00994",4,"En el jardín de mi reina\nera jardinero yo,\ny en tiempo de coger rosas\notro jardinero entró.",4,0,-1,3,"",0,4,"o",2,0,-1,0,122,122,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00994-e10",4,"Segunda amonestación,\npasarás por San Antonio\ny les dirás á los frailes\nque vengan á darme el óleo.",4,0,-1,3,"",0,4,"oo",-1,0,-1,0,122,122,"","",1,"","","",2,0,0,[],""],["palau_cantares-00994-e2",4,"Yo te quería á ti sola\ny tú querías á dos;\ntú querías repicar\ny andar en la procesión.",4,0,-1,3,"",0,4,"o",-1,0,-1,0,122,122,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00994-e3",4,"Si piensas tú que es ganancia,\nel tener á muchos ley,\nes tan sólo una ignorancia\nque las mujeres tenéis.",4,0,-1,3,"",0,4,"e",-1,0,-1,0,122,122,"","",1,"","","",1,0,0,[],""],["palau_cantares-00994-e4",4,"Como estás esta noche\ntan celosita,\npareces una rosa\ncon espinitas.",4,0,-1,3,"",6,4,"ia",-1,0,-1,0,122,122,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-00994-e5",4,"Te quiero, pero quiero\nque tú no quieras\ná quien te quiere y quiere\nque no me quieras.",4,0,-1,3,"",6,4,"ea",-1,0,-1,0,122,122,"","",1,"","","",2,0,0,[],""],["palau_cantares-00994-e6",4,"Dame, mi bien, pesares,\ndame desvelos,\ndame lo que quisieres,\nno me des celos.",4,0,-1,3,"",6,4,"eo",192,0,-1,0,122,122,"","",1,"","","",2,0,0,[],""],["palau_cantares-00994-e7",4,"No quiero pedir celos\ná mi morena,\nporque sintiera mucho\nque me los diera.",4,0,-1,3,"",6,4,"ea",-1,0,-1,0,122,122,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-00994-e8",4,"Me han dicho que tú te casas:\nasí lo dice la gente;\ny todo será en un día,\ntu casamiento y mi muerte.",4,0,-1,3,"",0,4,"ee",-1,0,-1,0,122,122,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-00994-e9",4,"Primera amonestación\nque en la iglesia se leyere\nserá el primer parasismo\nque á mi corazón le diere.",4,0,-1,3,"",0,4,"ee",115,0,-1,0,122,122,"","",1,"","","",5,0,0,[],""],["palau_cantares-00995",4,"Última amonestación,\nya me estaré yo muriendo,\ny tú estarás con tu novio\nechándole mil requiebros.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,123,123,"","",1,"","","",1,0,0,[],""],["palau_cantares-00996",4,"Si te veo hablar con otro,\nte lo juro por Jesús,\nque á la puerta de tu casa\ntiene de haber una cruz.",4,0,-1,3,"",0,4,"u",109,0,-1,0,123,123,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-00997",4,"Aquel día te pondrás\ntu gran vestido encarnado,\ny á mí me estarán poniendo\nun hábito franciscano.",4,0,-1,3,"",0,4,"ao",-1,0,-1,0,123,123,"","",1,"","","",1,0,0,[],""],["palau_cantares-00998",4,"Si la mujer que camelo,\notro me la camelara,\nsacara yo mi cuchillo\ny á los pies me lo dejara.",4,0,-1,3,"",0,4,"aa",57,0,-1,0,123,123,"","",1,"","","",3,0,0,[],""],["palau_cantares-00999",4,"Cuando á ti te estén poniendo\nla ropita del baúl,\ná mí me estarán poniendo\nlos pies en el ataúd.",4,0,-1,3,"",0,4,"u",-1,0,-1,0,123,123,"","",1,"","","",12,0,0,[],""],["palau_cantares-01000",4,"¿Para qué pides celos\ná tus cuidados,\nsi has de rabiar con ellos\nsi llego á darlos?",4,0,-1,3,"",6,4,"ao",-1,0,-1,0,123,123,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01001",4,"Cuando á ti te estén poniendo\nla sortija de brillantes,\ná mí me estarán poniendo\ncuatro velas por delante.",4,0,-1,3,"",0,4,"ae",-1,0,-1,0,123,123,"","",1,"","","",12,0,0,[],""],["palau_cantares-01002",4,"Días ha que lo verde\nme da inquietudes,\nporque mis esperanzas\nse han vuelto azules.",4,0,-1,3,"",6,4,"ue",-1,0,-1,0,123,123,"","",1,"rm_t2, rm_t3, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01003",4,"Te llevarán á la iglesia\nla madrina y el padrino,\ny á mí me estarán llevando\nen hombros de cuatro amigos.",4,0,-1,3,"",0,4,"io",-1,0,-1,0,123,123,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01004",4,"Si los hombres se calaran\ncomo se cala un melón,\nya le hubiera yo calado\ná mi amante el corazón.",4,0,-1,3,"",0,4,"o",31,0,-1,0,123,123,"","",1,"","","",5,0,0,[],""],["palau_cantares-01005",4,"Te llevarán á acostar\ncon alegría y contento,\ny á mí me estarán echando\nen la tierra con los muertos.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,123,123,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01007",4,"Cada vez que considero\nque te has casado por fin,\nllamo á la muerte y le digo:\n¿Cuándo has de venir por mí?",4,0,-1,3,"",0,4,"i",-1,0,-1,0,123,123,"","",1,"rm_t3, lafuente_madrid","","",14,0,0,[],""],["palau_cantares-01008",4,"Más quisiera verte, niña,\nembarcadita en el mar,\nque no pasar por tu puerta\ny verte con otro hablar.",4,0,-1,3,"",0,4,"a",21,0,-1,0,123,123,"","",1,"rm_t3","","",6,0,0,[],""],["palau_cantares-01009",4,"No quiero que á misa vayas,\nni á la ventana te asomes,\nni tomes agua bendita\ndonde la toman los hombres.",4,0,-1,3,"",0,4,"oe",-1,0,-1,0,123,123,"","",1,"machado_venezuela, lafuente_madrid, huambachano, tompkins_negros","","",7,0,0,[],""],["palau_cantares-01010",4,"Quisiera abrir en tu pecho\nuna pequeña ventana\npara ver tu corazón\ncon quién comunica y trata.",4,0,-1,3,"",0,4,"aa",-1,0,-1,0,123,123,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01011",4,"En sabiendo tú que estoy\nen tierra de Andalucía,\nel gachó que te camele\nbien puede buscar su vida.",4,0,-1,3,"",0,4,"ia",-1,0,-1,0,123,123,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01012",4,"No siento que en tu casa\nentre ó no entre,\n¡que se siente á tu lado\nsí que se siente!",4,0,-1,3,"",6,4,"ee",-1,0,-1,0,123,123,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01013",4,"Por pillar á uno en tu puerta\nando que bebo los vientos:\ncomo lo llegue á pillar,\ntienes en tu puerta un muerto.",4,0,-1,3,"",0,4,"eo",-1,0,-1,0,123,123,"","",1,"","","",1,0,0,[],""],["palau_cantares-01014",4,"Yo no sé lo que haga\ncon unos celos,\nque estoy ya para darlos\npor no tenerlos.",4,0,-1,3,"",6,4,"eo",-1,0,-1,0,123,123,"","",1,"","","",2,0,0,[],""],["palau_cantares-01015",4,"Yo te quiero y no quiero,\nque son dos cosas,\nyo te quiero, y no quiero\nque hables con otra.",4,0,-1,3,"",6,4,"oa",-1,0,-1,0,124,124,"","",1,"rm_t3","","",5,0,0,[],""],["palau_cantares-01016",4,"Si supiera ó entendiera\nque otro mozo te procura,\ndebajo de tu ventana\nle abriera su sepultura.",4,0,-1,3,"",0,4,"ua",17,0,-1,0,124,124,"","",1,"","","",11,0,0,[],""],["palau_cantares-01017",4,"Son los celos el tronco\nde la firmeza:\nno puede querer mucho\nquien poco cela.",4,0,-1,3,"",6,4,"ea",-1,0,-1,0,124,124,"","",1,"","","",1,0,0,[],""],["palau_cantares-01018",4,"La furia de un celoso,\ndice Cupido,\nno es aborrecimiento,\nsino cariño.",4,0,-1,3,"",6,4,"io",-1,0,-1,0,124,124,"","",1,"","","",1,0,0,[],""],["palau_cantares-01019a",4,"Todavía no soy tuya,\npicarillo, ¿y me amenazas?\nMira que tengo en mi huerto\nla flor de la calabaza.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,125,125,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01019b",4,"Ayer al entrar en misa\nte vi casada con otro:\n¡quiera Dios que á lo pasado\nno vuelvas nunca los ojos!",4,0,-1,69,"",0,4,"oo",-1,0,-1,0,125,125,"","",1,"","","",1,0,0,[],""],["palau_cantares-01020",4,"La maldición que te echo\ndesde hoy en adelante,\nes que el dinero te sobre,\npero que el gusto te falte.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,125,125,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01021",4,"En mi juventud jamás\npudo sujetarme el hierro,\nmas ahora me sujeta\nuna mujer con el dedo.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,125,125,"","",1,"","","",1,0,0,[],""],["palau_cantares-01022",4,"Por aquella cruz bendita\nque está en aquella pared,\nque te has de quedar en blanco\ncomo pliego de papel.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,125,125,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01023",4,"Si no me querías,\n¿por qué me llamabas?\nPara achicharrarme el corazoncito\nen vivitas llamas.",4,0,-1,69,"",3,4,"aa",-1,0,-1,0,125,125,"","",1,"","","",2,0,0,[],""],["palau_cantares-01024",4,"Mi corazón enfermó\nde la pena que le dieron;\nla pena y quien se la dió\nla penará en los infiernos.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,125,125,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01025",4,"Tú te fuiste por tu gusto,\nnadie te ha echado á la calle:\nahora para hablar conmigo\nnecesitas memoriales.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,125,125,"","",1,"","","",1,0,0,[],""],["palau_cantares-01026",4,"Cuando más firme te quiero,\ntú aborreciéndome vas;\nya que así me has olvidado,\ncomo pagas cobrarás.",4,0,-1,69,"",0,4,"a",51,0,-1,0,125,125,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01027",4,"Fundida como campana\nes menester que estuvieras\npara que sin recelarme\ná tus quereres volviera.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,125,125,"","",1,"","","",1,0,0,[],""],["palau_cantares-01028",4,"A la mar te pareces\nen enojarte,\nporque la mar se enoja\nsólo del aire.",4,0,-1,69,"",6,4,"ae",-1,0,-1,0,125,125,"","",1,"fernan_caballero","","",2,0,0,[],""],["palau_cantares-01029",4,"Yo ya te voy á dejar,\nporque no tengo qué darte:\nconsidera, compañera,\nsi mis fatigas son grandes.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,125,125,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01030",4,"Tienes una carita\nde San Antonio,\ny una condicioncita\ncomo un demonio.",4,0,-1,69,"",6,4,"oo",169,0,-1,0,125,125,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01031a",4,"Acuérdate, mi vida,\ncuando algún tiempo\nme dijiste llorando:\n- Por ti me muero.",4,0,-1,69,"",6,4,"eo",-1,0,-1,0,126,126,"","",1,"","","",2,0,0,[],""],["palau_cantares-01031b",4,"¡Válgame Dios, mi vida,\nqué ingrata que eres!\nMil finezas me has hecho,\ny una no quieres.",4,0,-1,69,"",6,4,"ee",55,0,-1,0,126,126,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01031c",4,"¿Qué te han hecho mis ojos,\nque no los miras\ncon aquel cariñito\nque tú solías?",4,0,-1,69,"",6,4,"ia",-1,0,-1,0,126,126,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01031d",4,"Anda y pregúntale á un sabio\ncuál de los dos perdió más:\ntú perdiste la vergüenza,\nyo perdí mi libertad.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,126,126,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01031e",4,"Tú me dices que soy loco,\nyo te confieso que sí;\nque si loco no estuviera,\n¿cómo te quisiera á ti?",4,0,-1,69,"",0,4,"i",23,0,-1,0,126,126,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01031f",4,"Ya no te quiero, no, no;\nya no te quiero, ni verte;\nque has de ser mi perdición\ny la causa de mi muerte.",4,0,-1,69,"",0,4,"ee",134,0,-1,0,126,126,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01031g",4,"Tu falsa correspondencia\npuso fin á mi alegría.\nEs verdad que no te quiero;\nno me hables más en tu vida.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,126,126,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01031h",4,"Porque sabes que te quiero,\ntú te haces de rogar:\ntanto tiras de la cuerda,\nque al fin se vendrá á quebrar.",4,0,-1,69,"",0,4,"a",21,0,-1,0,126,126,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01032a",4,"Confieso que eres linda,\nmas por lo mismo,\nporque el pero no falte,\nno tienes juicio;\ny así te advierto\nque, si eres más juiciosa,\nno tendrás pero.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,126,126,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01032b",4,"Tú me estás dando lugar\ná que eche la capa al toro\ny que tire de la manta\ny que se descubra todo.",4,0,-1,69,"",0,4,"oo",-1,0,-1,0,126,126,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01032c",4,"Tú pensabas engañarme\ncon palabras melositas;\npero me parió mi madre\nmás pícara que bonita.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,126,126,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01032d",4,"Esta gitana está loca,\nloca que la van á atar,\nque lo que sueña de noche\nquiere que salga verdad.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,126,126,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01032e",4,"Parece que jugamos\nal escondite:\nte busco y no te encuentro,\ncorazón triste.",4,0,-1,69,"",6,4,"ie",-1,0,-1,0,126,126,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01032f",4,"La desgracia me sigue,\nsegún voy viendo,\npues cuando yo te busco,\ntú vas huyendo.",4,0,-1,69,"",6,4,"eo",52,0,-1,0,126,126,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01032g",4,"Dime, ¿por qué motivo\nde mí te apartas?\nDímelo, dueño mío,\nporque me matas.",4,0,-1,69,"",6,4,"aa",-1,0,-1,0,126,126,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01033",4,"Si me quieres, dímelo,\ny si no, desengañarme:\ncomo se mudan los tiempos,\nse mudan las voluntades.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,126,126,"","",1,"lafuente_madrid","","",17,0,0,[],""],["palau_cantares-01034",4,"¿De qué sirve el cariño\nque yo te tengo,\nsi tú me pagas siempre\ncon mil desprecios?",4,0,-1,69,"",6,4,"eo",-1,0,-1,0,126,126,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01035",4,"Ven acá y haremos paces,\nque no es razón, vida mía,\nque entre dos finos amantes\nesté la amistad perdida.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,126,126,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01036",4,"Si con hambre castigas\ná quien te ama,\nadvierte que el desmayo\nquita la gana.",4,0,-1,69,"",6,4,"aa",-1,0,-1,0,126,126,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01037",4,"Tú me das esperanzas,\nmas no me dices\nel día que mis ansias\nserán felices.",4,0,-1,69,"",6,4,"ie",113,0,-1,0,127,127,"","",1,"rm_t2, carrizo_salta","","",4,0,0,[],""],["palau_cantares-01038",4,"Es preciso, compañera,\nque nuestro querer se acabe;\npongamos tierra por medio\npara que la gente no hable.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,127,127,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01039",4,"La cinta que me diste\npor esperanza,\ntan corta fué, mi dueño,\nque no me alcanza.",4,0,-1,69,"",6,4,"aa",163,0,-1,0,127,127,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01040",4,"De aquí tengo que ausentarme,\nmi querer está en peligro,\nraíces va ya criando\ncomo en el suelo el olivo.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,127,127,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01041",4,"No me trates de burlas,\nsino de veras,\npues aquéllas me enojan\ny éstas me alegran:\nque las mujeres,\nsi tratan de casarse,\nlas veras quieren.",4,0,-1,69,"",4,7,"ee",-1,0,-1,0,127,127,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01042",4,"He sabido ya quien eres,\nconque cesen mis pesares;\nde mi devoción no esperes\nmás incienso en tus altares.",4,0,-1,69,"",1,4,"ae",164,0,-1,0,127,127,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01043",4,"Si el hablar te costara\ntanto trabajo\ncomo el ser generosa,\nno hablaras tanto;\npero tú tratas\nde ser muy dadivosa\nsólo en palabras.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,127,127,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01044a",4,"La camisa de mi cuerpo\npídela y te la daré;\npero no por eso esperes\nque te vuelva mi querer.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,127,127,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01044b",4,"Ya no quiero querer más,\nquiero seguir tu opinión,\nque un querer con mucho extremo\nes causa de perdición.",4,0,-1,69,"",0,4,"o",31,0,-1,0,127,127,"","",1,"","","",3,0,0,[],""],["palau_cantares-01045",4,"Compañera de mi alma,\nalgún día querrá Dios\nque la fortuna se vuelva\ny pases por mi dolor.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,127,127,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01046",4,"Dicen que tú no me quieres\nporque me ves chiquitito:\npues mira, la gente compra\npor el aire el abanico.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,127,127,"","",1,"","","",11,0,0,[],""],["palau_cantares-01047",4,"Algún día llorarás\ncuando ya no haya remedio:\nme verás y te veré...,\npero no nos hablaremos.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,127,127,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01048",4,"¡Bien me dijeron á mí\nque tu querer era vano\ny que por fin pasaría\ncomo nube de verano!",4,0,-1,69,"",0,4,"ao",81,0,-1,0,127,127,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01049",4,"Ya sé yo que en este mundo\nde estorbo te estoy sirviendo:\nanda con Dios, compañera,\nque ya me echarás de menos.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,127,127,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01050",4,"¿Te acuerdas cuando pusiste\ntus manos sobre las mías,\ny llorando me dijiste\nque nunca me olvidarías?",4,0,-1,69,"",1,4,"ia",214,0,-1,0,127,127,"","",1,"","","",5,0,0,[],""],["palau_cantares-01051",4,"Déjala que vaya y venga\nal pilarillo por agua,\nque puede ser que algún día,\nen el pilarillo caiga.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,127,127,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01052",4,"¿Te acuerdas cuando dijiste\nen cierta conversación,\nque los montes se mudaban,\npero tu firmeza no?",4,0,-1,69,"",0,4,"o",-1,0,-1,0,127,127,"","",1,"","","",2,0,0,[],""],["palau_cantares-01053",4,"Échale tú á mi caballo\nhojitas de limón verde,\nque puede ser que algún día,\nserrana, de mí te acuerdes.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,127,127,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01054",4,"¿Te acuerdas que estando un día\nen mi pecho reclinado,\nde mi corazón sentiste\nlos golpes acompasados?",4,0,-1,69,"",0,4,"ao",-1,0,-1,0,127,127,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01055",4,"Un amor tenía yo\nque me decía, llorando,\nque nunca me olvidaría,\n¡y ya me estaba olvidando!",4,0,-1,69,"",0,4,"ao",33,0,-1,0,128,128,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01056",4,"Vamos á ajustar la cuenta\ndel tiempo que te he querido:\nme darás carta de pago\ny yo te daré recibo.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,128,128,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01057",4,"¿De qué te sirve tener\nesta cara tan hermosa,\nsi tiene tu corazón\nespinas como la rosa?",4,0,-1,69,"",0,4,"oa",63,0,-1,0,128,128,"","",1,"","","",7,0,0,[],""],["palau_cantares-01058",4,"No tienes que comparar\ntu voluntad con la mía,\nque es sin fin mi voluntad\ny la tuya duró un día.",4,0,-1,69,"",0,4,"ia",0,0,-1,0,128,128,"","",1,"","","",1,0,0,[],""],["palau_cantares-01059",4,"Acaba de quererme\ntarde ó temprano,\nno seas como el perro\ndel hortelano.",4,0,-1,69,"",6,4,"ao",81,0,-1,0,128,128,"","",1,"","","",2,0,0,[],""],["palau_cantares-01060",4,"Escribistes en la arena\ny firmastes en la mar;\nel viento fué tu correo:\n¡vaya una seguridad!",4,0,-1,69,"",0,4,"a",-1,0,-1,0,128,128,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01061",4,"Morena, tú me matas\ncon tus rigores;\nquieres que paguen justos\npor pecadores.",4,0,-1,69,"",6,4,"oe",5,0,-1,0,128,128,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01062",4,"Aquella firmeza tanta\ny aquel ponderar amor,\naquel no vivir sin verme,\n¡qué pronto se te acabó!",4,0,-1,69,"",0,4,"o",-1,0,-1,0,128,128,"","",1,"","","",2,0,0,[],""],["palau_cantares-01063",4,"Ó finges ó no finges,\ntirano dueño:\nsi finges, acabóse;\nsi no, acabemos.",4,0,-1,69,"",6,4,"eo",-1,0,-1,0,128,128,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01064",4,"Sólo porque te alivies\npienso ausentarme,\npues sin duda mi vista\ncausa tus males;\ny esto lo infiero\nde que á quejarte empiezas\nasí que llego.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,128,128,"","",1,"","","",1,0,0,[],""],["palau_cantares-01065a",4,"Una cición componen\ntu amor y el mío,\nyo con la calentura,\ntú con el frío.",4,0,-1,69,"",6,4,"io",3,0,-1,0,128,128,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01065b",4,"Camaradita del alma,\nusted no sabe querer:\nlas mujeres se manejan\ncon la puntilla del pie.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,128,128,"","",1,"","","",4,0,0,[],""],["palau_cantares-01066",4,"Se parece á los olmos\nel amor tuyo,\nque todo es hojarasca,\npero sin fruto;\ny yo no quiero\nárbol que no da fruto\npara mi huerto.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,128,128,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01067",4,"Con venderte no me pagas\nlo mucho que te he querido,\naunque tu cuerpo valiera\nvalor de treinta navios.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,128,128,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01068",4,"Siempre estás inventando\ndos mil embustes,\nmas fingir que me quieres\nno se te ocurre:\n¡buena desgracia\nno encontrar quien me quiera\nsiquiera en chanza!",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,128,128,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01069",4,"No quiero que me des gloria,\nporque no la he merecido;\nlo que quiero es que me pagues\nel tiempo que te he querido.",4,0,-1,69,"",0,4,"io",101,0,-1,0,128,128,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01070",4,"Si olvidarte fuera fácil,\nbien te olvidaría yo;\nmi corazón gozaría\nla libertad que perdió.",4,0,-1,69,"",0,4,"o",2,0,-1,0,128,128,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01071",4,"Pues los cariños te ofenden,\nle pido á Dios de los cielos\nque de aquel á quien estimas\ntengas que sufrir desprecios.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,129,129,"","",1,"rm_t3, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01072",4,"¡Malhaya el amor, mal haya,\ny quien del amor se fía,\nque puse yo mi querer\nen quien no lo merecía!",4,0,-1,69,"",0,4,"ia",0,0,-1,0,129,129,"","",1,"","","",1,0,0,[],""],["palau_cantares-01073",4,"Todo el mundo me lo dice,\nque yo me tengo la culpa\nde amar á quien no me ama,\nbuscar á quien no me busca.",4,0,-1,69,"",0,4,"ua",-1,0,-1,0,129,129,"","",1,"lafuente_madrid","","",14,0,0,[],""],["palau_cantares-01074",4,"Yo tuve un árbol sembrado\ny regado con querer,\ny á lo mejor se ha secado:\n¡mal haya quien quiere bien!",4,0,-1,69,"",0,4,"e",-1,0,-1,0,129,129,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01075",4,"Es el querer que me tienes\npiedra que cae de lo alto,\nque en una parte da el golpe\ny á mí viene de rechazo.",4,0,-1,69,"",0,4,"ao",-1,0,-1,0,129,129,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01075-e2",4,"El avefría en el campo\nclaramente dice: «Nieve;»\nyeso lo dice por ti,\nsabiendo que á nadie quieres.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,129,129,"","",1,"","","",2,0,0,[],""],["palau_cantares-01075-e3",4,"Esclavo de unos ojos\nfui largo tiempo:\npretendía favores,\nlogré desprecios;\ny en mi desgracia\nni aun me queda el alivio\nde la esperanza.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,129,129,"","",1,"","","",2,0,0,[],""],["palau_cantares-01075-e4",4,"Si yo me hubiera sabido\nque era tu pecho traidor,\nno me hubiera yo embarcado\nen tan mala embarcación.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,129,129,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01076a",4,"Una escopeta en que yo\ntenía mi confianza,\nal fin me dio gatillazo:\n¿qué será las que son falsas?",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,129,129,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01076b",4,"Tengo que hacer un castillo\nencima de un alfiler\ny ha de tener más firmeza\nque ha tenido tu querer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,129,129,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01076c",4,"De la torre de mis gustos\nen lo más alto me vi;\nfueron los cimientos falsos,\ny en lo profundo caí.",4,0,-1,69,"",0,4,"i",23,0,-1,0,129,129,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01077a",4,"Me dijiste que era fea;\nal espejo me miré:\nalgún salerillo tengo,\ná algún tonto engañaré.",4,0,-1,69,"",0,4,"e",77,0,-1,0,129,129,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01077b",4,"Arbolito, te secaste\nteniendo el agua en el pie,\nen el tronco la firmeza\ny en las ramas el querer.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,129,129,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01077c",4,"Cuando bien te parecí,\n¡con qué ojitos me miraste!\n¿Quién te ha hablado mal de mí\nque tan pronto me olvidaste?",4,0,-1,69,"",1,4,"ae",212,0,-1,0,129,129,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01078",4,"¡Mal haya este pecho tierno\nque tanto te ha idolatrado;\nmientras más enternecido,\nha sido más despreciado!",4,0,-1,69,"",0,4,"ao",14,0,-1,0,130,130,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01079",4,"Corazón, te lo decía\nque vivías engañado,\ny vives aborrecido\npudiendo ser estimado.",4,0,-1,69,"",0,4,"ao",14,0,-1,0,130,130,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01080",4,"Te fuiste y me abandonaste\ncuando yo más te quería:\nno hubieran hecho otro tanto\nlos moros de Berbería.",4,0,-1,69,"",0,4,"ia",0,0,-1,0,130,130,"","",1,"","","",1,0,0,[],""],["palau_cantares-01081",4,"Mi corazón tú lo tienes,\ndámelo si no te sirve;\nse lo daré á otra paloma\nque con su calor lo abrigue.",4,0,-1,69,"",0,4,"ie",-1,0,-1,0,130,130,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01082",4,"Dicen que ya no me quieres,\ntú me vendrás á buscar\ncomo el agua busca al río\ny el río busca á la mar.",4,0,-1,69,"",0,4,"a",21,0,-1,0,130,130,"","",1,"","","",9,0,0,[],""],["palau_cantares-01083",4,"Alza la voz, pregonero,\ny di lo que yo dijere:\n«¿Quién me compra un corazón\ndespreciado de mujeres?",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,130,130,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01084",4,"De enojada y quejosa\ntú punto haces;\nhe de hacer, si me apuras,\npunto y aparte:\nsufrir no puedo\nel paréntesis largo\nde tus desprecios.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,130,130,"","",1,"","","",2,0,0,[],""],["palau_cantares-01085",4,"»A la una y á las dos,\ná las tres, ¡que se remata!\n¿Quién me compra un corazón\ndespreciado de una ingrata?»",4,0,-1,69,"",0,4,"aa",74,0,-1,0,130,130,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01086",4,"Nuestro trato y cariño\nnadie lo entiende;\ntú eres galán fantasma,\nyo dama duende;\ny estos amores\nserán dentro de poco\nsecreto á voces.",4,0,-1,69,"",4,7,"oe",-1,0,-1,0,130,130,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01087a",4,"¡Ay de mí que te amo!,\n¡ay que te quiero!,\n¡ay que tú me aborreces!,\n¡ay que yo muero!\nReniego en vano\nde quien soy, de quien eres\ny de mi estado.",4,0,-1,69,"",4,7,"ao",-1,0,-1,0,130,130,"","",1,"preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01087b",4,"Yo me enamoré del aire,\ndel aire de una mujer;\ncomo la mujer es aire,\nen el aire me quedé.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,130,130,"","",1,"rm_t3, isaacs_colombia, lafuente_madrid, murciano_antiguo, fernan_caballero","","",9,0,0,[],""],["palau_cantares-01087c",4,"Corazoncito leal,\nbien te lo decía yo\nque te habían de olvidar,\ny tú decías que no.",4,0,-1,69,"",0,4,"o",2,0,-1,0,130,130,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01088a",4,"Tú te ves elevada\ny yo abatido,\nseñal que estuve en alto\ncuando he caído;\ny espero ver\ncómo después alguno\nte hace caer.",4,0,-1,69,"",4,7,"e",20,0,-1,0,130,130,"","",1,"","","",3,0,0,[],""],["palau_cantares-01088b",4,"En la escuela de amores\nsoy principiante;\ndame lecciones, niña,\npara no amarte:\npues te aseguro\nque, como salga de ésta,\nseré buen tuno.",4,0,-1,69,"",4,7,"uo",-1,0,-1,0,130,130,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01088c",4,"Yo no puedo negarte\nque te he querido:\nfué una pasión honesta\ny amor novicio:\nno he profesado,\nque es religión estrecha\nla del casado.",4,0,-1,69,"",4,7,"ao",14,0,-1,0,130,130,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01088d",4,"¿Para qué me dijiste\nrosa temprana,\nsi soy la más tardía\nque hay en la rama?",4,0,-1,69,"",6,4,"aa",-1,0,-1,0,130,130,"","",1,"rm_t3","","",10,0,0,[],""],["palau_cantares-01089",4,"Déjala que cante y ría\ny de mis penas se goce,\nque puede ser que algún día\nlágrimas de sangre llore.",4,0,-1,69,"",1,4,"oe",-1,0,-1,0,131,131,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01090",4,"Tu querer es como el toro,\nque adonde lo llaman va;\nel mío como la piedra,\ndonde la ponen se está.",4,0,-1,69,"",0,4,"a",9,0,-1,0,131,131,"","",1,"","","",3,0,0,[],""],["palau_cantares-01091",4,"Algún día tu caerás\nen aquel yerro que hiciste;\ncuando quieras no podrás\nrecobrar lo que perdiste.",4,0,-1,69,"",1,4,"ie",153,0,-1,0,131,131,"","",1,"carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01092",4,"Tu querer es como el charco,\nel mío como la fuente:\nsale el sol, se seca el charco\ny la fuente permanece.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,131,131,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01093",4,"Con el corazón partido\nllorando gotas de sangre,\ny arrastrando por los suelos,\nhas de venir á buscarme.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,131,131,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01094",4,"Tu querer lo he comparado\ncon los pesos de la carne,\nque aunque los den muy corridos,\nnunca resultan cabales.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,131,131,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01095",4,"Vestida de negro luto\nte he de encontrar en la calle,\ny me has de pedir por Dios,\ncompañera, que te hable.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,131,131,"","",1,"","","",2,0,0,[],""],["palau_cantares-01096",4,"Tu querer lo he comparado\ncon el correo de Vélez,\nque en cayendo cuatro gotas,\nse le mojan los papeles.",4,0,-1,69,"",0,4,"ee",97,0,-1,0,131,131,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01097",4,"De tu maldita lengua\nquiero un guisado,\nque tu lengua maldita\nme ha deshonrado.",4,0,-1,69,"",6,4,"ao",14,0,-1,0,131,131,"","",1,"","","",1,0,0,[],""],["palau_cantares-01098",4,"Te has vuelto en poco tiempo\ntan embustera,\nque aunque la verdad busques,\nya no la encuentras:\nque es delicada,\ny á quien no la respeta\nvuelve la cara.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,131,131,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01099a",4,"Es más grande mi querer\nque la voluntad de Dios;\nporque Dios no te perdona\nlo que te perdono yo.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,131,131,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01099b",4,"Toma el camino de Roma,\ncon el Padre Santo habla,\ny dile que te perdone\nque has querido á dos hermanas.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,131,131,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01100",4,"Favores y desprecios\nno los archivo,\nque los doy al instante\nque los recibo.\nDe esta manera\nle pago á cada uno\ncon su moneda.",4,0,-1,69,"",4,7,"ea",-1,0,-1,0,131,131,"","",1,"","","",2,0,0,[],""],["palau_cantares-01101",4,"Dios perdona á quien fué causa\nde mis trabajos perdidos,\ny advierte que con la vara\nque mida ha de ser medido.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,131,131,"","",1,"","","",1,0,0,[],""],["palau_cantares-01102",4,"En el jardín de tu pecho\njardinero soy de amor,\ny cuando yo le cultivo,\ntodo el fruto queda en flor.",4,0,-1,69,"",0,4,"o",72,0,-1,0,131,131,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01103",4,"Aunque en una cruz te pongas,\npara mí acabaste ya;\nporque quisistes á un tiempo\ncon dos barajas jugar.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,131,131,"","",1,"","","",7,0,0,[],""],["palau_cantares-01104",4,"Déjame, prenda, por Dios,\nplaticar aunque sea pobre;\nque un grillo vale dos cuartos,\ny con todo, se le oye.",4,0,-1,69,"",0,4,"oe",-1,0,-1,0,131,131,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01105",4,"Eres como la veleta\nque está encima de la torre:\nviene un viento y otro viento,\ny á todos les corresponde.",4,0,-1,69,"",0,4,"oe",-1,0,-1,0,131,131,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01106",4,"Corre, ve y dile á tu madre\nque no hable mal de mí,\nque pérdidas y ganancias\ntodas caerán sobre ti.",4,0,-1,69,"",0,4,"i",23,0,-1,0,131,131,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01107",4,"Contigo, siempre contigo,\ncontigo y hasta morir;\npero con tu madre no,\nporque ha hablado mal de mí.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01107-e2",4,"Me han dicho que andas haciendo\npesquisas de mi linaje;\n¡como si tú descendieras\nde algunos Abencerrajes!",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01107-e3",4,"Serás dueña de mi vida,\nsi sabes corresponder;\nsólo temo la mudanza,\nporque al fin eres mujer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,132,132,"","",1,"","","",2,0,0,[],""],["palau_cantares-01107-e4",4,"¿Cómo quieres que navegue\nun barco que está en la playa?\n¿Cómo quieres que yo quiera\nun cuerpo que está sin alma?",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,132,132,"","",1,"rm_t3, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01107-e5",4,"' Me solicitas cobarde,\nme amas y te retiras;\ntiras la piedra y escondes\nla mano con que la tiras.",4,0,-1,69,"",0,4,"ia",295,0,-1,0,132,132,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01107-e6",4,"Yo no te solicité;\nrecuerda que me buscaste,\nte marchaste por tu gusto,\ny volviste sin llamarte.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01107-e7",4,"Fuiste mi primer amor,\ntú me enseñaste á querer;\nno me enseñes á olvidar,\nque no lo quiero aprender.",4,0,-1,69,"",0,4,"e",20,0,-1,0,132,132,"","",1,"rm_t2, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01107-e8",4,"Como estoy ciego por ti,\nme estás poniendo con maña\ntus encantos por delante\npara que tropiece y caiga.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,132,132,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01107-e9",4,"Si río, me desprecias;\nsi lloro, cantas;\nsi canto, no me atiendes;\nsi te hablo, callas.\n¡Dolor funesto!,\n¡cada vez el cariño\nmuda de afectos!",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,132,132,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01108",4,"Yo vivo de lo que como,\ny bebo lo que me dan;\npero masco algunas cosas\nque no las puedo tragar.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,132,132,"","",1,"rm_t3, lafuente_madrid, leonesas_diez","","",5,0,0,[],""],["palau_cantares-01108-e10",4,"Los martirios que le dieron\nlos judíos á un divé,\nesos te mereces tú\nporque no sabes querer.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01108-e2",4,"De la retama la rama,\ndel saúco la corteza,\nno son cosas más amargas\nque amor donde no hay firmeza.",4,0,-1,69,"",0,4,"ea",108,0,-1,0,132,132,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01108-e3",4,"Entre todos sus vasallos\nno ha conocido el amor\nmujer más falsa que tú,\nni hombre más firme que yo.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,132,132,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01108-e4",4,"Eres una y eres dos,\neres tres y eres cuarenta,\neres iglesia mayor\ndonde todo el mundo entra.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01108-e5",4,"Porque te vi desde lejos,\npor eso te quiero tanto;\nhaces bien en no acercarte:\nde cerca pierde lo falso.",4,0,-1,69,"",0,4,"ao",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01108-e6",4,"Una serrana me ha dicho,\nde tu misma serranía,\nque ningún hombre pequeño\npuede hacer buenas partidas.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01108-e7",4,"A mí no me queman chispas\nde la más ardiente fragua,\nlas que me queman á mí\nson tus partidas serranas.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,132,132,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01108-e8",4,"Mientras más caricias me haces,\nmás en confusión me pones;\nporque tus caricias son\nvísperas de tus traiciones.",4,0,-1,69,"",0,4,"oe",34,0,-1,0,132,132,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01108-e9",4,"Por ser tú tan mirado\nquieren casarme:\n¡fuego de Dios en hombre\nque es tan cobarde!",4,0,-1,69,"",6,4,"ae",-1,0,-1,0,132,132,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01109a",4,"Quiera Dios que en donde pongas\ntodos tus cinco sentidos\nle paguen á tu querer\ncomo tú pagas al mío.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,133,133,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01109b",4,"¡A qué precio tan costoso\ndispones de mi amistad!\nSi una hora me das de gusto,\nme das ciento de pesar.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,133,133,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01110",4,"Ya conozco tus tramas\ny tus designios,\npues ya sabes, ingrata,\nque por el hilo...\nY no lo extrañes,\npues eres un ovillo\nde falsedades.",4,0,-1,69,"",4,7,"ae",-1,0,-1,0,133,133,"","",1,"","","",2,0,0,[],""],["palau_cantares-01111",4,"Compañerilla del alma,\nesta gitanilla perra\nme trae mortificado\nqueriendo que no la quiera.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,133,133,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-01111-e2",4,"Compañerita del alma,\nyo no sé por qué motivo\nlo hace tan malamente\nesta gitana conmigo.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,133,133,"","",1,"lafuente_madrid","","",20,0,0,[],""],["palau_cantares-01111-e3",4,"A ninguna en este mundo\nhe querido más que á ti;\nque tú no lo reconozcas,\nese es mi mayor sentir.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,133,133,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01111-e4",4,"Tu persona no es persona,\ntu persona es un castigo,\ntu persona no se enmienda,\nsi no se viene conmigo.",4,0,-1,69,"",0,4,"io",106,0,-1,0,133,133,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01111-e5",4,"Hasta al sabio Salomón\nyo le conté tus partidas,\ny me respondió llorando:\n«No paga ni con la vida.»",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,133,133,"","",1,"","","",1,0,0,[],""],["palau_cantares-01111-e6",4,"Como sé que te mudas\na todos aires,\nno suspiro, mi vida,\npor no mudarte:\nque aunque es muy leve,\nel aire de un suspiro\nmudarte puede.",4,0,-1,69,"",4,7,"ee",-1,0,-1,0,133,133,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01111-e7",4,"Aquellas palabritas\nque me dijiste,\nsi no fueran falaces,\nfueran felices;\ny de este modo\nlas creo yo tanto,\nque no soy tonto.",4,0,-1,69,"",4,7,"oo",-1,0,-1,0,133,133,"","",1,"","","",2,0,0,[],""],["palau_cantares-01112",4,"Todas mis esperanzas\nolas parecen,\nque montes aparentan\ny espumas.mueren;\ny tu inconstancia\nes también por las olas\nrepresentada.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,133,133,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01112-e2",4,"Amor mío, vienes tarde\ny luego te vas temprano.\n¿De qué me sirven á mí\nvisitas de cirujano?",4,0,-1,69,"",0,4,"ao",81,0,-1,0,133,133,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01112-e3",4,"Toda la noche al sereno\ncantando porque te asomes,\ny no he podido lograr\nque respondas á mis sones.",4,0,-1,69,"",0,4,"oe",-1,0,-1,0,133,133,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01112-e4",4,"Me dijiste: «Luego bajo,»\ny te fuistes á dormir:\nte esperé toda la noche,\ny no quisiste venir.",4,0,-1,69,"",0,4,"i",157,0,-1,0,133,133,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01112-e5",4,"Resaladita del alma,\nanoche en tu puerta estuve,\nestabas á la ventana\ny no me dijiste: «sube.»",4,0,-1,69,"",0,4,"ue",208,0,-1,0,133,133,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01112-e6",4,"¿Constante no te adoré?,\n¿y fino no te serví?,\n¿no hice cuanto fué tu gusto?\n¿Pues por qué me olvidas, di?",4,0,-1,69,"",0,4,"i",23,0,-1,0,133,133,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01112-e7",4,"Yo no sé por qué motivo\nme olvidas á sangre fría,\ncuando se le toma ley\ná un perrillo que se cría.",4,0,-1,69,"",0,4,"ia",0,0,-1,0,133,133,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01112-e8",4,"Camaradita del alma,\nusted no sabe querer:\npor una cosa tan leve\nno se olvida á una mujer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,133,133,"","",1,"","","",4,0,0,[],""],["palau_cantares-01113",4,"¡Al cabo de tanto tiempo\nque mi corazón te amó\nhas tenido atrevimiento\npara decirme que no!",4,0,-1,69,"",0,4,"o",2,0,-1,0,134,134,"","",1,"rm_t2","","",3,0,0,[],""],["palau_cantares-01114",4,"Otras veces mi capote\nandaba en el contrabando\narropándote de noche,\n¡y ahora me preguntas cuándo!",4,0,-1,69,"",3,4,"ao",33,0,-1,0,134,134,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01115",4,"¡Ay, por Dios, que eso es matarme,\neso es quitarme la vida,\neso es echarme á la calle\ncomo cosilla perdida!",4,0,-1,69,"",0,4,"ia",37,0,-1,0,134,134,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01116",4,"En mi vida solicito\nal que de mí se retira;\nque he tomado por venganza\nolvidar á quien me olvida.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,134,134,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01117",4,"El corazón tengo herido\nde una puñalada tuya,\nde ver que me has olvidado\nsin tener causa ninguna.",4,0,-1,69,"",0,4,"ua",-1,0,-1,0,134,134,"","",1,"rm_t3","","",6,0,0,[],""],["palau_cantares-01118",4,"Me quisistes y te quise,\nme olvidaste y te olvidé:\nlos dos tuvimos la culpa,\ntú primero y yo después.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,134,134,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01119",4,"Por haberte yo querido,\nquisiera que te casaras\ncon otra mejor que yo,\ny de mí no te acordaras.",4,0,-1,69,"",0,4,"aa",143,0,-1,0,134,134,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01120",4,"Por querer á un serafín,\nolvidé á un hermoso cielo:\ndos glorias no puede haber,\nvolvamos á lo primero.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,134,134,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01121",4,"Permita Dios que te vea\nen un calabozo obscuro,\ny que pase por mi mano\ntodo el alimento tuyo.",4,0,-1,69,"",0,4,"uo",-1,0,-1,0,134,134,"","",1,"","","",3,0,0,[],""],["palau_cantares-01122",4,"Anda con Dios, mala sangre;\nya se te ha cumplido el gusto\nde encontrarme por la calle\ntodo vestido de luto.",4,0,-1,69,"",0,4,"uo",-1,0,-1,0,134,134,"","",1,"","","",2,0,0,[],""],["palau_cantares-01123",4,"Aunque pase más fatigas\nque clavos tiene una puerta,\nanda con Dios, compañero,\nque el mundo da muchas vueltas.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,134,134,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01124",4,"Debajo de tu ventana\nhay un ramito de olivo,\nun manojito de esparto\ny un sarmiento florecido.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,134,134,"","",1,"","","",29,0,0,[],""],["palau_cantares-01125",4,"En el querer no hay venganza,\ny te has vengado de mí;\nsi no hay castigo en la tierra,\ndel cielo te ha de venir.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,134,134,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01126",4,"El esparto es que me aparto,\nel olivo que te olvido,\nel sarmiento me arrepiento\ndel tiempo que te he querido.",4,0,-1,69,"",0,4,"io",101,0,-1,0,134,134,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01127",4,"Quisiera que Dios me oyera,\ny que las piedras hablaran,\ny que el castigo viniera\ncomo yo lo deseara.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,134,134,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01128",4,"Allá va mi corazón\nmetido en un azafate:\nno me lo niegues, traidora,\nque algún día fuí tu amante.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,134,134,"","",1,"","","",4,0,0,[],""],["palau_cantares-01129",4,"Por quererte, mala hembra,\neché mi cuerpo á perder:\nel que en mala tierra siembra,\nmal fruto puede coger.",4,0,-1,69,"",1,4,"e",20,0,-1,0,134,134,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01130",4,"Si en el transcurso del tiempo\nen la calle me encontrares,\ná Dios le pido, alma mía,\nque te pares y me hables.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,134,134,"","",1,"","","",2,0,0,[],""],["palau_cantares-01131",4,"En los libros del olvido\nmanda mi Dios que te ponga,\nporque tu querer ha sido\ncomo cangilón de noria.",4,0,-1,69,"",0,4,"oa",-1,0,-1,0,134,134,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01132",4,"Aunque vayas y te bañes\nen el agua del romero,\nno se te quita la mancha\nde los amores primeros.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,134,134,"","",1,"","","",3,0,0,[],""],["palau_cantares-01133",4,"Anda, vete por el mundo,\nhombre que ya me dejaste;\nya no tienes qué pedirme,\nni yo tampoco qué darte.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,135,135,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01134",4,"Anda, vete, que no quiero\npasar por ti más fatigas;\nte portas como quien eres:\n¿qué más quieres que te diga?",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,135,135,"","",1,"rm_t3, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01135",4,"Yo te quiero, tú á mí no;\nyo te amo, tú me aborreces;\nyo te trato con cariño,\ny tú á mí con esquiveces.",4,0,-1,69,"",0,4,"ee",196,0,-1,0,135,135,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01136",4,"Si porque te ves querida\nme niegas la voluntad,\nyo he visto una casa nueva\nderribarla un vendaval.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,135,135,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01137",4,"Te quise porque te vi\ny te vi porque Dios quiso,\ny al ver cuán poco me quieres,\nme pesa de haberte visto.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,135,135,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01138",4,"Si porque te ves querida,\nhaces de mí lo que haces,\nmira que Dios no es tan viejo,\nque todos los años nace.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,135,135,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01139",4,"Mi vida la escribiré,\ny la llevaré á la imprenta,\ny á voces publicaré\nlo que tu querer me cuesta.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,135,135,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01140",4,"Con cuatro letras vivo,\ncon cinco muero,\ncon siete me cautivan,\ncon doce peno;\ny son la causa\namor, celos, finezas,\ndesconfianza.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,135,135,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01141a",4,"En el fuego en que me abraso\nte quisiera ver arder,\npara que sepas, ingrata,\nlo que cuesta un buen querer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,135,135,"","",1,"carrizo_salta, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01141b",4,"¡Ya no te acuerdas de mí,\ncorazón de piedra dura,\nsabiendo que yo por ti\npaso ratos de amargura!",4,0,-1,69,"",1,4,"ua",17,0,-1,0,135,135,"","",1,"rm_t3, carrizo_salta, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01142",4,"Tres prodigios muy raros\nadmiran todos:\ntu hermosura es el uno,\nmi amor el otro,\ny es el tercero,\nque tu nieve no pueda\ncalmar mi fuego.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,135,135,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01143",4,"Si fueras serrana pura\ny tuvieras buena sangre,\nte pusieras la mantilla\ny vinieras á buscarme.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,135,135,"","",1,"","","",2,0,0,[],""],["palau_cantares-01144",4,"Si quieres que te lo diga,\nte lo diré en dos razones:\neres hombre de dos caras\ny de malas condiciones.",4,0,-1,69,"",0,4,"oe",34,0,-1,0,135,135,"","",1,"rm_t3, carrizo_salta, lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01145",4,"Si de mi cuerpo sacaran\nla sangre por cuarterones,\nno lo sentiría tanto\ncomo siento tus razones.",4,0,-1,69,"",0,4,"oe",34,0,-1,0,135,135,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01146",4,"Aunque te pongas en cruz,\nno te tengo de creer,\nporque ya sé lo que valen\njuramentos de mujer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,135,135,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01147",4,"Yo no sé ya lo que hacerme\natento de tu querer,\nsi lo deje por la mano\nó si me pierda por él.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,135,135,"","",1,"","","",1,0,0,[],""],["palau_cantares-01148",4,"El querer que me tenías\nen una rama quedó;\nvino un fuerte remolino,\nrama y tronco se llevó.",4,0,-1,69,"",0,4,"o",2,0,-1,0,135,135,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01149",4,"Yo te iré sobrellevando\nhasta que no pueda más;\nque muchas gotas de cera\nhacen un cirio pascual.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,135,135,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01150",4,"Si me quieres escribir,\nyo te diré dónde vivo:\nen la calle de Firmeza,\ndonde tú nunca has vivido.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,135,135,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01151",4,"Ya yo no vivo en la calle\ndonde usted me conoció;\nahora vivo en la plazuela\ndel Desengaño mayor.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,136,136,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-01152",4,"Ya está el carro cargado\nde tus desprecios,\nmira no falte el eje\ndel sufrimiento.",4,0,-1,69,"",6,4,"eo",-1,0,-1,0,136,136,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01153",4,"Pareces una paloma\ncuando por la calle vas;\ncon el meneo que llevas,\n¡á cuántos engañarás!",4,0,-1,69,"",0,4,"a",51,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01154",4,"Ya me voy enfadando\nde tus quereres,\nque hay pocas ocasiones,\ny esas las pierdes.",4,0,-1,69,"",6,4,"ee",-1,0,-1,0,136,136,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01155",4,"Me quisiste, me amaste,\nme has olvidado,\ny hoy vienes á buscarme:\n¡mujer al cabo!",4,0,-1,69,"",6,4,"ao",-1,0,-1,0,136,136,"","",1,"","","",1,0,0,[],""],["palau_cantares-01156",4,"¿Para qué me dijiste:\n«Toma mi alma,»\nsi bebes en la fuente\nde la inconstancia?",4,0,-1,69,"",6,4,"aa",-1,0,-1,0,136,136,"","",1,"","","",10,0,0,[],""],["palau_cantares-01157",4,"Déjame pasar, que voy\npor agua á la mar serena\npara lavarme la cara,\nque dicen que soy morena.",4,0,-1,69,"",0,4,"ea",59,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01158",4,"Anoche estuve en tu puerta;\ntres golpes dí en el candado:\npara tener amor, niña,\ntienes el sueño pesado.",4,0,-1,69,"",0,4,"ao",14,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01159",4,"Si quieres que yo te diga\nla pura de la verdad,\nmucho tienes de bonita,\npero más de vanidad.",4,0,-1,69,"",0,4,"a",16,0,-1,0,136,136,"","",1,"rm_t3, carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01160",4,"Eres la madre del sueño,\nhermosísima María;\nsiempre que te vengo á ver,\nhe de encontrarte dormida.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01161",4,"Eres Ana y eres vana,\neres cardo, eres jazmín,\neres buena y eres mala,\neres diablo y serafín.",4,0,-1,69,"",0,4,"i",211,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01162",4,"Una vez que vengo á verte\nal cabo de la semana,\nte encuentro triste y llorosa\ny me pones mala cara.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01163",4,"Eres una alabanciosa\nque, cuando vas á comprar,\ntodo te cuesta más caro\ny dices que te lo dan.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01164",4,"Me consumo la vida\ncuando te miro,\npues te digo, y no entiendes\nlo que te digo.",4,0,-1,69,"",6,4,"io",-1,0,-1,0,136,136,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-01165",4,"Tú has hablado mal de mí,\nyo de ti no he dicho ná,\nque las campanillas suenan\nsegún tienen el metal.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,136,136,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01166",4,"El alma ya me duele\nde suplicarte\nque me des un remedio\npara olvidarte.",4,0,-1,69,"",6,4,"ae",8,0,-1,0,136,136,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01167",4,"Eres como la perdiz\nque por el pico se pierde,\nque te has dejado decir,\nsalada, que no me quieres.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01168",4,"Como ves que yo me esmero\nen adorarte y quererte,\npor eso, claro lucero,\nme pagas tan malamente.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,136,136,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01169",4,"Te quiero, y me aborreces\ncon tal porfía,\nque ni puedo ser de otra,\nni tú ser mía.",4,0,-1,69,"",6,4,"ia",0,0,-1,0,136,136,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01170",4,"Si el querer bien se pagara,\n¡cuánto me fueras debiendo!;\npero como no se paga,\nni me debes, ni te debo.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,136,136,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01171",4,"Como sabes, ángel bello,\nque yo me muero por ti,\ntienes el gusto cifrado\nen darme á mí qué sentir.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,139,139,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01172",4,"Toda la noche me tienes\nal sereno y al rocío,\ny luego por la mañana\nme preguntas si he dormido.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,139,139,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01173",4,"Cual nave combatida\nse halla mi pecho,\nnaufragando en las olas\nde tus desprecios,\ncon la esperanza\nque he de llegar al puerto\nde la bonanza.",4,0,-1,69,"",4,7,"aa",163,0,-1,0,139,139,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01174",4,"Si piensas que porque callo\ntus sinrazones no entiendo,\nadvierte que aquel que calla\nhablará en llegando el tiempo.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,139,139,"","",1,"rm_t3, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01175",4,"Quien hubiese encontrado\nuna esperanza,\npor Dios que me la vuelva,\nque me hace falta;\nmas... bien mirado,\nque se quede con ella\nquien la haya hallado.",4,0,-1,69,"",4,7,"ao",14,0,-1,0,139,139,"","",1,"","","",1,0,0,[],""],["palau_cantares-01176",4,"Sólo quiero me digas\nsi te ha quedado\nalgún triste recuerdo\nde lo pasado;\npero me temo\nque ya de tu memoria\nno serás dueño.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,139,139,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01177",4,"¿Cómo quieres que le diga\ná tu madre «madre mía,»\nni á tus hermanas «cuñadas,»\nsi tú no quieres ser mía?",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,139,139,"","",1,"","","",3,0,0,[],""],["palau_cantares-01178",4,"En tu corazoncito\nme diste un cuarto,\ny no pude barrerlo\npor tanto trasto.\nYo no lo quiero,\ná menos que no quites\ntrastos de en medio.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,139,139,"","",1,"","","",2,0,0,[],""],["palau_cantares-01179",4,"¿Cuándo querrá Dios del cielo\nque mis deseos se cumplan?\nSegún lo que yo voy viendo,\nserá tarde, mal ó nunca.",4,0,-1,69,"",0,4,"ua",-1,0,-1,0,139,139,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-01180",4,"Para que vuelva á quererte\ntú me tienes que traer\nescritos de puño y letra\nlos informes de un divé.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,139,139,"","",1,"","","",1,0,0,[],""],["palau_cantares-01181",4,"Cuando te llamo, no vienes;\ncuando vienes, no hay lugar;\nasí se nos pasa el tiempo,\nasí se nos pasará.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,139,139,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01182",4,"Mira que poquito á poco\nvas pagando lo que debes:\npor tus malitas partidas,\nnadie en el mundo te quiere.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,139,139,"","",1,"","","",2,0,0,[],""],["palau_cantares-01183",4,"Que sí, que no, que sería,\nque hoy, que mañana, que ayer,\nque ahora, que luego, que cuando...:\n¿quién diablos te ha de entender?",4,0,-1,69,"",0,4,"e",20,0,-1,0,139,139,"","",1,"carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01185",4,"Estoy predicando en ti\ncomo padre misionero,\ny no te puedo traer\ná camino verdadero.",4,0,-1,69,"",0,4,"eo",38,0,-1,0,139,139,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01186",4,"Anda con Dios, amor mío,\nque yo sembraré en mi huerto\nla semilla del olvido\ny la flor del escarmiento.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,139,139,"","",1,"","","",2,0,0,[],""],["palau_cantares-01187",4,"En el mundo no se ha visto\nmujer de mi caliá;\nque tengo el semblante alegre\ny la sangre achicharrá.",4,0,-1,69,"",0,4,"a",9,0,-1,0,139,139,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01188",4,"¿Cómo quieres que tenga\nfinos colores,\nsi me los van quitando\ntus sinrazones?",4,0,-1,69,"",6,4,"oe",-1,0,-1,0,139,139,"","",1,"","","",14,0,0,[],""],["palau_cantares-01189",4,"¡Mal haya la veleta\nque el aire mueve!\n¡Mal haya quien se fía\nde las mujeres!",4,0,-1,69,"",6,4,"ee",-1,0,-1,0,140,140,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01190",4,"Del jardín salen las rosas,\nde la marina los peces,\nde mi corazón traiciones\npara ti que las mereces.",4,0,-1,69,"",0,4,"ee",196,0,-1,0,140,140,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01191",4,"Es doctrina fingida\nde aquí adelante\nque una cosa produce\nsu semejante:\npues mi cariño\nen tu pecho produce\nsólo desvío.",4,0,-1,69,"",4,7,"io",-1,0,-1,0,140,140,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01192",4,"Dentro de mi pecho tengo\nuna mesa de cristal\ndonde juegan á los naipes\nmi amor y tu falsedad.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,140,140,"","",1,"rm_t3, lafuente_madrid","","",32,0,0,[],""],["palau_cantares-01193",4,"¡Ay de mí, que enojada\nte considero,\ncuando pensé que nunca\nse airaba el cielo!",4,0,-1,69,"",6,4,"eo",-1,0,-1,0,140,140,"","",1,"","","",2,0,0,[],""],["palau_cantares-01193-e2",4,"Bajo por la calle abajo,\npaso por tu puerta y digo:\n- Aquí vive la morena\nque algún tiempo me ha querido.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,140,140,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01193-e3",4,"Cada vez que paso y miro\ndonde mi amante vivió,\nme contento con la jaula,\nque el pájaro ya voló.",4,0,-1,69,"",0,4,"o",2,0,-1,0,140,140,"","",1,"lafuente_madrid","","",25,0,0,[],""],["palau_cantares-01193-e4",4,"Por agravios que me hagas\nde ti no me vengaré,\nporque te vale el sagrado\nde haberte querido bien.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,140,140,"","",1,"rm_t2, rm_t3, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-01193-e5",4,"Cuando te encuentro en la calle,\nse me alegra el corazón:\ndonde candela se hizo,\nsiempre ceniza quedó.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,140,140,"","",1,"lafuente_madrid","","",13,0,0,[],""],["palau_cantares-01193-e6",4,"Tienes de sol el rostro,\ncosa es segura;\npero tienes el alma\ncomo la luna:\ny es cosa clara\nque, siendo el sol muy fijo,\nla luna es varia.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,140,140,"","",1,"","","",2,0,0,[],""],["palau_cantares-01193-e7",4,"Desciendes de mala rama,\nno lo puedes remediar:\nlas mujeres y caballos\npor casta se han de buscar.",4,0,-1,69,"",0,4,"a",21,0,-1,0,140,140,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01194",4,"Tengo yo un cofrecito\ndonde ir echando\ntodas las pesadumbres\nque me vas dando;\npero algún día,\nsi rompo el cofrecito,\nserá la mía.",4,0,-1,69,"",4,7,"ia",0,0,-1,0,140,140,"","",1,"","","",5,0,0,[],""],["palau_cantares-01194-e2",4,"Tengo en el pecho escritas.\ntus falsedades,\ntengo de publicarlas\naunque te enfades;\npues no creyera\nque me hubieses vendido\nde esta manera.",4,0,-1,69,"",4,7,"ea",44,0,-1,0,140,140,"","",1,"","","",3,0,0,[],""],["palau_cantares-01194-e3",4,"Si me has dado calabazas,\nme las comí con vinagre;\npero los besos y abrazos,\nque te los quite tu padre.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,140,140,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01194-e4",4,"Te tengo comparadita\ncon las piedras de la calle,\nque las pisa todo el mundo\ny no se quejan de nadie.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,140,140,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01194-e5",4,"Tienes el amor puesto\ncon alfileres\ny tan pronto me dejas\ncomo me quieres.",4,0,-1,69,"",6,4,"ee",55,0,-1,0,140,140,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01194-e6",4,"Dicen que hay damas firmes.\nno sé cuál sea,\npues la que me ha tocado\nse bambolea.",4,0,-1,69,"",6,4,"ea",54,0,-1,0,140,140,"","",1,"","","",3,0,0,[],""],["palau_cantares-01194-e7",4,"De los hábitos de Judas\nhe de hacerte un delantal\npara que lleves delante\ninsignias de falsedad.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,140,140,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01195",4,"Con mucho gusto te miro,\ncon poco gusto me ves;\nmira, pues, si hay diferencia\nde tu amor á mi querer.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01196",4,"Puse al cielo una querella\ny respondieron los aires\nque mi querer no lo ponga\ndonde firmeza no halle.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01197",4,"Si tienes un corazón,\npara amarme, tan de hielo,\nacércate, ingrata, al mío\ny verás como es de fuego.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01198",4,"Yo no sé qué le dije,\nque ella lloraba:\npropiedad de mujeres,\nllorar por nada.",4,0,-1,69,"",6,4,"aa",-1,0,-1,0,141,141,"","",1,"","","",1,0,0,[],""],["palau_cantares-01199",4,"Mi corazón se derrite\nde pena y de sentimiento\nde ver que tú no me quieres\ntanto como yo te quiero.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,141,141,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01200",4,"Tienes nubes como el cielo,\nmareas como la mar,\nmudanzas como los vientos,\ny luego te ha de pesar.",4,0,-1,69,"",0,4,"a",21,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01201",4,"Ayer tarde me alargaste\npor la ventana un limón,\nlo partí, y estaba seco:\n¿está así tu corazón?",4,0,-1,69,"",0,4,"o",-1,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01202",4,"Deja las expresiones,\nmuda el concepto,\nno des satisfacciones\nantes de tiempo.\nMira y discurre:\nsatisfacción sin tiempo\nmalicia arguye.",4,0,-1,69,"",4,7,"ue",-1,0,-1,0,141,141,"","",1,"","","",2,0,0,[],""],["palau_cantares-01203a",4,"Si en tu casa no me quieren,\ná ti tampoco en la mía;\nnos iremos á una cueva,\ncomo Santa Rosalía.",4,0,-1,69,"",0,4,"ia",0,0,-1,0,141,141,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01203b",4,"¿De qué le sirve á tu madre\nmachacar en hierro frío,\nsi ha de tener á su lado\nlo que tiene aborrecido?",4,0,-1,69,"",0,4,"io",-1,0,-1,0,141,141,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01204",4,"Te quise en la creencia\nde que tu pecho\nde tórtola tenía\nlos sentimientos;\npero ya miro\nque era tu amor el llanto\ndel cocodrilo.",4,0,-1,69,"",4,7,"io",-1,0,-1,0,141,141,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01205",4,"Se pone tu madre y dice\nque se alegra de mi mal;\nsi la lengua se le balda,\nyo también me he de alegrar.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01206",4,"Mal haya quien me dió á mí\ntanto amor para quererte,\ny ahora para olvidarte\nson mis penillas de muerte.",4,0,-1,69,"",0,4,"ee",134,0,-1,0,141,141,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01207",4,"Tu gente no está gustosa\nde que me quieras á mí;\nno es ninguna penitencia\nque se tenga de cumplir.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,141,141,"","",1,"","","",3,0,0,[],""],["palau_cantares-01208",4,"Toma, niño, estos dos cuartos\ny dile á aquella mujer\nque quiero darla un consejo,\nporque la he querido bien.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,141,141,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01209",4,"Cada cual siente su pena,\nyo siento la mía doble:\nno me quieren en tu casa,\nporque dicen que soy pobre.",4,0,-1,69,"",0,4,"oe",-1,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01210",4,"Si en adelante no quieres\nhacer más caso de mí,\nla vida que me has robado\nme debes restituir.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,141,141,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01211",4,"A la mar tengo de irme\ná llorar mi sentimiento,\npues que puse mi querer\nen un molino de viento.",4,0,-1,69,"",0,4,"eo",94,0,-1,0,141,141,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01212",4,"Aunque ahora me desprecias,\nen algún tiempo fuí bueno;\ncalla tú y callaré yo,\ny así los dos callaremos.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,141,141,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01213a",4,"Ya yo he caído en desgracia.\n¡Paciencia!, ¡cómo ha de ser!\nAunque yo santos pintara,\ndiablos te han de parecer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,142,142,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01213b",4,"Otras veces era yo\nen tu casa el más querido,\ny ahora por mi desgracia\nsoy el más aborrecido.",4,0,-1,69,"",0,4,"io",101,0,-1,0,142,142,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01213c",4,"Ayer me dijiste que hoy,\nhoy me dices que mañana,\ny mañana me dirás:\n«Ya se me quitó la gana.»",4,0,-1,69,"",0,4,"aa",4,0,-1,0,142,142,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-01213d",4,"Estoy, como San Alejo,\ndebajo de la escalera\nesperando la ocasión,\ny la ocasión nunca llega.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,142,142,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01213e",4,"Yo le he preguntado al Tiempo,\ny el Tiempo me contestó:\n- Ya vendrá tiempo en que tengas\ntiempo, lugar y ocasión.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,142,142,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01213f",4,"- Dame un besito. - No quiero.\n- Dame un abrazo. - Tampoco.\n- Dame una puñaladita,\ndámela poquito á poco.",4,0,-1,69,"",0,4,"oo",152,0,-1,0,142,142,"","",1,"","","",2,0,0,[],""],["palau_cantares-01213g",4,"Siempre me echabas achaques\npara no salirme á hablar;\nlo que es tiempo te sobraba,\nte faltaba voluntad.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,142,142,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01213h",4,"Tres veces me quisiste,\ntres me negaste:\notro San Pedro fuiste,\nmas no lloraste.\nLlegará ocasión\nque quizá cante el gallo\nde nuestra pasión.",4,0,-1,69,"",4,7,"o",31,0,-1,0,142,142,"","",1,"","","",2,0,0,[],""],["palau_cantares-01213i",4,"Acuérdate, falsa, ingrata,\ndel tiempo de cuando entonces\nbajabas descalza á abrirme,\n¡y ahora no me conoces!",4,0,-1,69,"",0,4,"oe",-1,0,-1,0,142,142,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01214",4,"Eres hermosa en extremo,\npero tienes una falta:\nque en el campo hay varias flores,\ny tú también eres varia.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,142,142,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01214-e2",4,"Si querrá Dios que concibas\nel desdén con que me tratas:\ncon tus ojos me cautivas\ny con tus obras me matas.",4,0,-1,69,"",1,4,"aa",328,0,-1,0,142,142,"","",1,"","","",1,0,0,[],""],["palau_cantares-01214-e3",4,"Las sombras que me dices\nque te desvelan,\nserán de tus mudanzas\nlas consecuencias:\nporque es muy propio\nen todos los culpados\nfingir enojos.",4,0,-1,69,"",4,7,"oo",-1,0,-1,0,142,142,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01214-e4",4,"Me han dicho que tú has dicho\nque soy mudable:\nsi yo soy la veleta,\ntú eres el aire:\nque la veleta,\nsi el aire no la mueve,\nsiempre está quieta.",4,0,-1,69,"",4,7,"ea",200,0,-1,0,142,142,"","",1,"","","",2,0,0,[],""],["palau_cantares-01214-e5",4,"Me llamas á la reja\npara decirme\nque la mujer es varia\ny el hombre firme;\npor el contrario,\nla mujer es muy firme\ny el hombre vario.",4,0,-1,69,"",4,7,"ao",25,0,-1,0,142,142,"","",1,"","","",1,0,0,[],""],["palau_cantares-01214-e6",4,"Es tu baile tan lindo,\nque me embelesa:\nsi esto hacen las mudanzas,\n¿qué harán firmezas?\nMas no te admire,\nque sólo en las mudanzas\neres tú firme.",4,0,-1,69,"",4,7,"ie",-1,0,-1,0,142,142,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01214-e7",4,"Hazme, mi bien, desdenes,\nque todo el tiempo\nque se tarda la dicha\nvive el deseo,\ny en mi amor noble\nsuponen esperanzas\nmás que favores.",4,0,-1,69,"",4,7,"oe",-1,0,-1,0,142,142,"","",1,"rm_t2, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01215",4,"Algún día era yo rey\ny ahora soy un mal vasallo;\npudiendo yo gobernar,\nme están á mí gobernando.",4,0,-1,69,"",3,4,"ao",-1,0,-1,0,143,143,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01216",4,"Dueño mío, no jures,\nque te condenas:\nsi tienes otra dama,\n¿por qué lo niegas?",4,0,-1,69,"",6,4,"ea",-1,0,-1,0,143,143,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01217",4,"Me has dicho que me quieres,\ndueño del alma;\ndímelo con las obras,\nno con palabras.",4,0,-1,69,"",6,4,"aa",-1,0,-1,0,143,143,"","",1,"","","",1,0,0,[],""],["palau_cantares-01218",4,"A tu querer lo comparo\ncon la torre de Babel,\nque subió más de cien millas\ny al fin se vino á caer.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,143,143,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01219",4,"Como la lejía turbia\nes, mozuela, tu amistad,\nque nunca puede salir\ná puerto de claridad.",4,0,-1,69,"",0,4,"a",16,0,-1,0,143,143,"","",1,"","","",2,0,0,[],""],["palau_cantares-01219-e3",4,"Tienes cara de buen mozo,\ncuerpo de corregidor;\npero tienes una falta:\nque eres falso en el amor.",4,0,-1,69,"",0,4,"o",72,0,-1,0,143,143,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01219-e4",4,"Me dijistes «¡agua va!»\nal tiempo que me la echaste:\nanda con Dios, picarona,\nque bien que me remojaste.",4,0,-1,69,"",0,4,"ae",212,0,-1,0,143,143,"","",1,"","","",3,0,0,[],""],["palau_cantares-01219-e5",4,"Al principio de quererte,\nquien te conoce me dijo\nque de ti no me fiara,\nque eres falsa en el cariño.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,143,143,"","",1,"","","",3,0,0,[],""],["palau_cantares-01219-e7",4,"Soy más leal que el caballo,\nmás humilde que la tierra,\nmás carnicero que el lobo:\ntrátame, pues, con cautela.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,143,143,"","",1,"","","",2,0,0,[],""],["palau_cantares-01219-e8",4,"Mi corazón es leal\npara la persona tuya;\nel tuyo para mí no,\nque siempre va con segundas.",4,0,-1,69,"",0,4,"ua",-1,0,-1,0,143,143,"","",1,"","","",3,0,0,[],""],["palau_cantares-01220",4,"Se parece tu cariño,\nmuchacha, á la golondrina:\nviene por la primavera\ny al invierno se retira.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,143,143,"","",1,"","","",1,0,0,[],""],["palau_cantares-01220-e3",4,"Yo soy aquel que murió\ny he vuelto á resucitar,\ny en el cementerio supe\nquién me quiso bien y mal.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,143,143,"","",1,"","","",1,0,0,[],""],["palau_cantares-01220-e5",4,"Yo estaba queriendo á un hombre\nun punto menos que á Dios:\nhizo una mala partida,\nde juro que no hace dos.",4,0,-1,69,"",0,4,"o",87,0,-1,0,143,143,"","",1,"","","",1,0,0,[],""],["palau_cantares-01220-e6",4,"Este querer que te tengo\nes una locura grande:\nyo de ti no saco nada,\nlo que saco es condenarme.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,143,143,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01222",4,"Ven acá, falsa y refalsa,\nfalsa, te vuelvo á decir:\nel día que me vendiste\n¿cuánto te dieron por mí?",4,0,-1,69,"",0,4,"i",-1,0,-1,0,144,144,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01223",4,"Te enojas cuando te miro;\nsi no te miro, te ofendes:\nde parte de Dios te digo\nque me digas lo que quieres.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,144,144,"","",1,"","","",2,0,0,[],""],["palau_cantares-01224",4,"El que te quiero soy yo,\ny el que te lleva en el pecho;\npero no quiero que quieras\ná ese que yo me sospecho.",4,0,-1,69,"",0,4,"eo",60,0,-1,0,144,144,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01225",4,"Yo te estoy queriendo á ti\ncon el más grande silencio,\ny tú me vas pregonando\ncomo aquel que vende lienzo.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,144,144,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01226",4,"En tu casa y con idea\nentra y sale cierto amigo:\n¿cómo quieres que yo crea\nque nada tiene contigo?",4,0,-1,69,"",1,4,"io",106,0,-1,0,144,144,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01227",4,"No te afanes, compañera,\npor sacar fruto de mí,\nque al árbol que no se riega\nse le seca la raíz.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,144,144,"","",1,"","","",2,0,0,[],""],["palau_cantares-01228",4,"¿Qué tenías ayer tarde,\nque en la ventana llorabas?\n¿Te había dicho que no\naquel que en la esquina estaba?",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,144,144,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01229",4,"Como los torillos bravos\ntienes, gitana, el arranque:\nsólo te acuerdas de mí\ncuando me tienes delante.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,144,144,"","",1,"","","",2,0,0,[],""],["palau_cantares-01229-e3",4,"El sereno de mi calle\nme quiere quitar la novia;\nya se lo diré esta noche\ncon el chuzo y las pistolas.",4,0,-1,69,"",0,4,"oa",-1,0,-1,0,144,144,"","",1,"","","",4,0,0,[],""],["palau_cantares-01229-e4",4,"Serrana, si tú me quieres\ny me tienes voluntad,\nal gachón que te camele\ndile que no vuelva más.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,144,144,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01229-e5",4,"Si quieres que yo te quiera,\nhas de olvidar á quien amas;\nque sopitas añadidas\nlas como de mala gana.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,144,144,"","",1,"rm_t3, lafuente_madrid","","",23,0,0,[],""],["palau_cantares-01229-e6",4,"Por Dios te pido, bien mío,\nque cuando con otra estés,\nno le hagas los cariños\nque á mí me sueles hacer.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,144,144,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01230a",4,"No siento haber perdido\ntanto una alhaja,\ncomo que ya no brille\ncomo brillaba:\nque en otra mano\nel color de sus perlas\nestá empañado.",4,0,-1,69,"",4,7,"ao",-1,0,-1,0,144,144,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01230b",4,"Si á otro, cuando me quieres,\nla mano das,\ncuando ya no me quieras,\n¿qué le darás?\nMas no lo digas,\nque yo estaba creyendo\nque eras más fina.",4,0,-1,69,"",4,7,"ia",-1,0,-1,0,144,144,"","",1,"","","",2,0,0,[],""],["palau_cantares-01231a",4,"Todas mis esperanzas\nse me han frustrado,\npues te he visto esta tarde\ncon otro al lado:\nyo te observaba,\npero tú no atendías\ná mis miradas.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,144,144,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01231b",4,"Todas cuantas finezas\nhaces conmigo\nson prolijos ensayos\nde otro cariño;\ny yo no quiero\nvestirme con alhaja\nque es de otro dueño.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,144,144,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01232",4,"Si supiera ó entendiera\nque á otro quieres más que á mí,\nde puñaladas le diera\ny al rey me fuera á servir.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,145,145,"","",1,"rm_t3","","",11,0,0,[],""],["palau_cantares-01233",4,"No serás tú el primer hombre,\nni yo la primer mujer,\nque se quieran y se olviden\ny se vuelvan á querer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,145,145,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01234",4,"Lloro entre los halagos\nde una esperanza,\ny como es hembra, tengo\ndesconfianza:\npues en las hembras\nse encuentran más mudanzas\nque en las estrellas.",4,0,-1,69,"",4,7,"ea",-1,0,-1,0,145,145,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01235",4,"Piedra fuí, perdí mi centro,\ny me tiraron al mar;\nmas con la fuerza del tiempo\nmi centro volví á buscar.",4,0,-1,69,"",0,4,"a",21,0,-1,0,145,145,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01236",4,"He de hacer un castillo\ncon cuatro torres:\nesperanza, firmeza,\ncelos y amores;\ny por remate\nhe de poner la estatua\nde un firme amante.",4,0,-1,69,"",4,7,"ae",-1,0,-1,0,145,145,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01237a",4,"Está mi amor tan gachón,\nque lo tengo comparado\ncon los niños en la escuela,\nque siempre están enojados.",4,0,-1,69,"",0,4,"ao",-1,0,-1,0,145,145,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01237b",4,"Dime, ¿no eres tú mi bien?,\n¿no eres tú mi cielecito?\nDime, ¿qué te he hecho yo,\nque estás tan enojadito?",4,0,-1,69,"",0,4,"io",119,0,-1,0,145,145,"","",1,"","","",1,0,0,[],""],["palau_cantares-01238",4,"Ven acá, mala gitana,\n¿qué es lo que quieres de mí,\nsi ando pidiendo limosna\nporque no te falte á ti?",4,0,-1,69,"",0,4,"i",23,0,-1,0,145,145,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01239",4,"Por Dios te pido, mi bien,\nque no me propongas medio:\nó mátame de una vez,\nó haz por mudar ese genio.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,145,145,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01240",4,"Si tienes quejas de mí,\nmátame, si te parece;\npero no vuelvas la cara\ncuando en la calle me encuentres.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,145,145,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01241",4,"Si mi corazón pudiera\nhablar con tu corazón,\nen breve rato te diera\nde todo satisfacción.",4,0,-1,69,"",1,4,"o",31,0,-1,0,145,145,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01242",4,"—Tienes, niña, una mañita,\nque te la vengo á reñir:\nque te quitas de la puerta\nen cuanto me ves venir.",4,0,-1,69,"",0,4,"i",157,0,-1,0,145,145,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01243",4,"Tú y yo nos parecemos\nmucho á la nieve,\ntú en lo blanca y lo fría,\nyo en deshacerme.",4,0,-1,69,"",6,4,"ee",-1,0,-1,0,145,145,"","",1,"rm_t3, frenk_t2, suspiros_amor","","",4,0,0,[],""],["palau_cantares-01244",4,"—Si has notado que me quito,\nyo no me quito por ti,\nsino por tus amiguitos,\nque no tengan qué decir.",4,0,-1,69,"",0,4,"i",-1,0,-1,0,145,145,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01245",4,"El jardín de mis gustos\nse ha marchitado\ncon la fuerza del hielo\nque tú has sembrado.",4,0,-1,69,"",6,4,"ao",14,0,-1,0,145,145,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01246",4,"—Ya mis amigos lo saben\nque yo adoro tu persona;\nque tú te estés en la puerta\nes para mí una corona.",4,0,-1,69,"",0,4,"oa",7,0,-1,0,145,145,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01247",4,"Corazones partidos\nyo no los quiero,\nque cuando doy el mío,\nlo doy entero.",4,0,-1,69,"",6,4,"eo",38,0,-1,0,145,145,"","",1,"rm_t3, isaacs_colombia, leonesas_diez","","",7,0,0,[],""],["palau_cantares-01248",4,"Olvidé padre y madre\npor ir contigo,\ny me dejaste sola\npor el camino.",4,0,-1,69,"",6,4,"io",-1,0,-1,0,145,145,"","",1,"","","",2,0,0,[],""],["palau_cantares-01249",4,"Corazón de leona\ntienes á veces:\naunque me ves que lloro,\nno te enterneces.",4,0,-1,69,"",6,4,"ee",196,0,-1,0,145,145,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01250",4,"¿Qué haré yo con contarte\ntodas mis penas,\nsi aunque tú las escuches,\nno las remedias?",4,0,-1,69,"",6,4,"ea",-1,0,-1,0,146,146,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01251",4,"Tan fácil es ver un hombre\nque tenga buenas partidas,\ncomo el hacer un bautizo\nen tierra de morería.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,146,146,"","",1,"","","",2,0,0,[],""],["palau_cantares-01252",4,"Cuando te veo con pena,\nte digo: «Bien empleado;\nque no has querido tomar\nlos consejos que te he dado.»",4,0,-1,69,"",0,4,"ao",14,0,-1,0,146,146,"","",1,"rm_t3, lafuente_madrid","","",8,0,0,[],""],["palau_cantares-01253",4,"De tu ventana á la mía\nme tirastes un limón:\nel limón cayó en el suelo,\nel agrio en mi corazón.",4,0,-1,69,"",0,4,"o",31,0,-1,0,146,146,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-01254",4,"Anda, vete, pero advierte\nque si para mí hay castigo,\ntambién para ti le habrá\nmás riguroso que el mío.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,146,146,"","",1,"","","",3,0,0,[],""],["palau_cantares-01255",4,"Dentro de mi pecho tengo\ndos escaleras de vidrio;\npor una baja el amor,\npor otra sube el olvido.",4,0,-1,69,"",0,4,"io",-1,0,-1,0,146,146,"","",1,"lafuente_madrid","","",32,0,0,[],""],["palau_cantares-01256",4,"Si te adoro, me olvidas;\nsi hablo, te enojas;\nsi callo, te entristeces;\nsi me voy, lloras.\n¡Oh amor supremo,\ntodo eres tú distancias,\ntodo tú extremos!",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,146,146,"","",1,"","","",2,0,0,[],""],["palau_cantares-01257",4,"En medio de mis fatigas\nuna maldición te eché:\n- La sal no te llegue al agua,\nsi olvidas á tu querer.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,146,146,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01258",4,"Si te busco, te ausentas;\nsi te hallo, riñes;\nsi te riño, te alegras;\nsi bailo, gimes.\n¡Terribles ansias!\n¿Quién hallará firmezas\ndonde hay mudanzas?",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,146,146,"","",1,"","","",2,0,0,[],""],["palau_cantares-01258-e2",4,"Si soy fino, tú ingrata;\nsi amante, esquiva;\nsi rendido, soberbia;\nsi humilde, altiva;\nsi fiel, tú falsa;\nsi soy tierno, tú dura;\nsi firme, varia.",4,0,-1,69,"",4,7,"aa",-1,0,-1,0,146,146,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01258-e3",4,"Tus ojos y los míos\nse miran y hablan,\npero los corazones\nno se declaran;\nmas te prevengo\nque si tú no te explicas,\n- yo no te entiendo.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,146,146,"","",1,"rm_t2, murciano_antiguo","","",7,0,0,[],""],["palau_cantares-01258-e4",4,"Yo soy serranita buena\npor todos cuatro costados:\nsi tengo malas partidas,\nde ti se me habrán pegado.",4,0,-1,69,"",0,4,"ao",-1,0,-1,0,146,146,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01259a",4,"No me seas retrechera,\nque te habré de comparar\ncon el reloj de Pamplona,\nque apunta, pero no da.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,146,146,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01259b",4,"Si me pagas con desdenes,\nseré como el ruiseñor,\nque me pondré entre las hojas\ná llorar mi perdición.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,146,146,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01259c",4,"Permita Dios de los cielos\nque como me matas mueras,\ny que te vean mis ojos\nquerer sin que á ti te quieran.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,146,146,"","",1,"lafuente_madrid, preciso_coleccion","","",6,0,0,[],""],["palau_cantares-01259d",4,"Dime ya si me quieres\nó si me engañas,\nporque no me alimento\ncon esperanzas:\nmaduran tarde,\ny entretanto yo puedo\nmorirme de hambre.",4,0,-1,69,"",4,7,"ae",-1,0,-1,0,146,146,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01259e",4,"Vivo con la esperanza\nde un desengaño,\npero el tiempo se pasa\ny aún no le hallo;\ny si esto dura,\naún peor que la herida\nserá la cura.",4,0,-1,69,"",4,7,"ua",17,0,-1,0,146,146,"","",1,"preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01260",4,"Se ha marchitado el árbol\nde mi esperanza:\nun traidor le ha cortado\nsus verdes ramas;\npero él no advierte\nque, mudando terreno,\nmejor florece.",4,0,-1,69,"",4,7,"ee",-1,0,-1,0,147,147,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01261",4,"Te has hecho, vida mía,\ntan miserable,\nque niegas que te quiero\npor no pagarme;\npero esta deuda\nte perdono gustoso\ncomo me quieras.",4,0,-1,69,"",4,7,"ea",-1,0,-1,0,147,147,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01262",4,"Si mi amante fuera amante\nque me supiera estimar,\ntengo yo para mi amante\nun corazón muy leal.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,147,147,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01263",4,"¿Cómo quieres que te tenga\nuna firme voluntad,\nsi eres venta de camino,\nque á todos posada das?",4,0,-1,69,"",0,4,"a",-1,0,-1,0,147,147,"","",1,"","","",2,0,0,[],""],["palau_cantares-01264",4,"La hierbabuena se cría\nen la corriente del agua.\n¿Para qué me quieres hoy,\nsi me has de olvidar mañana?",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,147,147,"","",1,"","","",1,0,0,[],""],["palau_cantares-01265",4,"Compadécete de mí,\nque tienes el corazón\nmás duro que las columnas\ndel templo de Salomón.",4,0,-1,69,"",0,4,"o",31,0,-1,0,147,147,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01266",4,"Si me has de olvidar mañana,\nolvídame luego al punto,\nporque yo quiero que sea\nel llanto sobre el difunto.",4,0,-1,69,"",0,4,"uo",36,0,-1,0,147,147,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01267",4,"Tengo pasadas por ti\nmás penas y más fatigas\nque pasan los marineros\nen el Callao de Lima.",4,0,-1,69,"",0,4,"ia",-1,0,-1,0,147,147,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01268",4,"No sé cómo tienes manos\npara lavarte la cara\nni peinarte los cabellos,\nsabiendo lo que me pasa.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,147,147,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01269",4,"Por ti no tengo sosiego,\npor ti no duermo ni como,\ny aunque ves que estoy muriendo,\nte desentiendes de todo.",4,0,-1,69,"",0,4,"oo",-1,0,-1,0,147,147,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01270",4,"Que quiera el que disfruta\nno es cosa nueva;\nel quererte sin verte\nsí que es fineza;\nporque hoy en día\nla mudanza en ausentes\nes ley precisa.",4,0,-1,69,"",4,7,"ia",-1,0,-1,0,147,147,"","",1,"","","",2,0,0,[],""],["palau_cantares-01271",4,"La guitarra y la escopeta\nlas acabo de vender;\nde todo tiene la culpa\nel querer á esa mujer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,147,147,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01272a",4,"A la luna parece,\nLaura, tu afecto,\nque tiene mil mudanzas\ny mil aspectos;\nsé luna llena,\ny deja los menguantes,\nporque te afean.",4,0,-1,69,"",4,7,"ea",-1,0,-1,0,147,147,"","",1,"","","",2,0,0,[],""],["palau_cantares-01272b",4,"Anda, ve y dile al maestro,\nal que te enseñó á querer,\nque te vuelva tu dinero,\nporque no te enseñó bien.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,147,147,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01273a",4,"No me mates quejosa,\nmátame bella,\nque, armada de hermosura,\nsobra la queja;\ny es suficiente\npara que tú me mates\nsólo yo verte.",4,0,-1,69,"",4,7,"ee",-1,0,-1,0,147,147,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01273b",4,"De los cuatro elementos\ntres me acompañan:\nardo, suspiro, lloro...,\ntierra me falta.\n¡Ay, dueño ingrato,\nla tierra que me falta\nvas preparando!",4,0,-1,69,"",4,7,"ao",-1,0,-1,0,147,147,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01274a",4,"Agua tengo en los ojos,\nsangre en los labios,\ny el corazón herido\nde tus agravios;\npero la cura\nha de ser á tu costa,\nsi este mal dura.",4,0,-1,69,"",4,7,"ua",17,0,-1,0,148,148,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01274b",4,"Siempre al tercero día\nvienes á verme:\ndime si son tercianas\nlo que padeces;\npues manifiestos\nlos males, ya se curan\ncon más acierto.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,148,148,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01274c",4,"A mí no me gustan plantas,\nmozo bueno, escuche usted:\nlo que me gustan son obras.\ny esas no las tiene usté.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,148,148,"","",1,"","","",4,0,0,[],""],["palau_cantares-01275",4,"Si me quieres de balde,\ntoda soy tuya,\npero por el dinero,\ncosa ninguna.",4,0,-1,69,"",6,4,"ua",-1,0,-1,0,148,148,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01275-e2",4,"El amor todo lo puede,\ndice un refrán, y es así;\ntú me dices que no puedes,\nluego no hay amor en ti.",4,0,-1,69,"",0,4,"i",23,0,-1,0,148,148,"","",1,"rm_t3, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01275-e3",4,"Si estás en la puerta, cierras;\nsi en la ventana, te escondes;\ndime qué te he hecho yo,\nque tan mal me correspondes.",4,0,-1,69,"",0,4,"oe",209,0,-1,0,148,148,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01275-e4",4,"Toda la noche me tienes\nen conversaciones varias,\ny luego al amanecer,\ncon un suspiro me engañas.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,148,148,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01276",4,"Una palabra me diste\nque nunca me cumplirás;\nyo sí cumpliré la mía\nde no olvidarte jamás.",4,0,-1,69,"",0,4,"a",51,0,-1,0,148,148,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01277",4,"La guitarra sin prima\nsuena quejosa,\ncomo estoy yo contigo\npor cierta cosa.",4,0,-1,69,"",6,4,"oa",63,0,-1,0,148,148,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01278",4,"Aunque en una cruz te pongas\nvestido de Nazareno\ny las tres caídas des,\nen tus palabras no creo.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,148,148,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01279",4,"El alma tengo llena\nde confusiones\ndesde que me dijiste\nciertas razones.",4,0,-1,69,"",6,4,"oe",34,0,-1,0,148,148,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01280",4,"La palabra que me diste\ná la orilla de la fuente,\ncomo fué cerca del agua\nse la llevó la corriente.",4,0,-1,69,"",0,4,"ee",15,0,-1,0,148,148,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01281",4,"Por entre espinas y abrojos\ndescalzo me atrevo á entrar\nsólo por quitarte enojos\ny volver á tu amistad.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,148,148,"","",1,"","","",2,0,0,[],""],["palau_cantares-01282",4,"La vara de San José\ntodos los años florece:\nla palabra de los hombres\nen nada se le parece.",4,0,-1,69,"",0,4,"ee",64,0,-1,0,148,148,"","",1,"","","",5,0,0,[],""],["palau_cantares-01283",4,"Hasta los árboles sienten\nque se les caiga la hoja:\n¿cómo quieres que no sienta,\nmorena, cuando te enojas?",4,0,-1,69,"",0,4,"oa",-1,0,-1,0,148,148,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01284",4,"Algún día, algún día\nfuí yo tu amante,\ny ahora me voy quedando\nde sobrestante.",4,0,-1,69,"",3,4,"ae",47,0,-1,0,148,148,"","",1,"","","",2,0,0,[],""],["palau_cantares-01285",4,"Por aquella cruz bendita\nque hay en aquel campanario,\nque me vuelvas á querer,\nque con otra no me apaño.",4,0,-1,69,"",0,4,"ao",-1,0,-1,0,148,148,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01286",4,"¡Mal haya el gitanillo\nque culpa tiene\nde no ser yo la reina\nde las mujeres!",4,0,-1,69,"",6,4,"ee",-1,0,-1,0,148,148,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01287",4,"Hasta el corazón me duele\nde rogarte con la paz;\npero tú quieres la guerra,\ny luego te ha de pesar.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,148,148,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01288",4,"Yo no sé lo que tú tienes,\nni si te han dado consejos;\nque no encuentro tu querer\ncomo estaba de primero.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,149,149,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01289",4,"En busca de firmezas\nmi amor andaba,\ny encontró un desengaño\nque no buscaba.",4,0,-1,69,"",6,4,"aa",28,0,-1,0,149,149,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01290",4,"Del cielo caiga una piedra\nque pese cien mil quintales\ny le rompa la cabeza\ná quien quiebra voluntades.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,149,149,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01291",4,"Eres mujer, y fueras\nmateria rara,\nsi firmeza en tu pecho\nmi fe encontrara.",4,0,-1,69,"",6,4,"aa",57,0,-1,0,149,149,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01292",4,"Ya vienen las aguas turbias,\nmañana se aclararán:\nel amor que ha sido firme\ná su tiempo volverá.",4,0,-1,69,"",0,4,"a",-1,0,-1,0,149,149,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01293",4,"Si compras el sombrero,\ncómpralo fino,\ny ponle galón falso,\ncomo tú has sido.",4,0,-1,69,"",6,4,"io",-1,0,-1,0,149,149,"","",1,"","","",1,0,0,[],""],["palau_cantares-01294",4,"Dicen que la mar es grande\ny caben muchos navios,\n¡y en ese pecho no puede\ncaber un recuerdo mío!",4,0,-1,69,"",0,4,"io",-1,0,-1,0,149,149,"","",1,"","","",2,0,0,[],""],["palau_cantares-01295",4,"Si quieres que te quiera,\ndame fianza,\npues de ti no me fío,\nque eres muy falsa.",4,0,-1,69,"",6,4,"aa",-1,0,-1,0,149,149,"","",1,"rm_t3, fernan_caballero","","",17,0,0,[],""],["palau_cantares-01296",4,"Válganme las tres Marías\ny el Cristo del Gran Poder:\n¡tanto como me querías,\ny ya no me puedes ver!",4,0,-1,69,"",1,4,"e",20,0,-1,0,149,149,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01297",4,"Si quieres que te quiera,\ndame primero\nfianzas con que pueda\npedirte luego.",4,0,-1,69,"",6,4,"eo",-1,0,-1,0,149,149,"","",1,"rm_t3","","",17,0,0,[],""],["palau_cantares-01298",4,"Quise bien y aborrecí,\nque no es delito en quien ama;\nque cuando yo aborrecí,\nmás que aborrecido estaba.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,149,149,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01299",4,"Muchachos, apedreadme;\nsalid, perros, y mordedme,\nque una niña de esta calle\nme ha dicho que no me quiere.",4,0,-1,69,"",0,4,"ee",-1,0,-1,0,149,149,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01300",4,"Cuando hables de mi persona,\nno digas que me has querido;\ndi que fué un capricho sólo\nque los dos hemos tenido.",4,0,-1,69,"",0,4,"io",101,0,-1,0,149,149,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01301",4,"A todos les da claveles\nla morena de la plaza,\ná todos les da claveles,\ny á mí me da calabazas.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,149,149,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01302",4,"Compañerilla del alma,\npor la salud de tu madre,\nlo que pasó entre los dos\nno se lo cuentes á nadie.",4,0,-1,69,"",0,4,"ae",-1,0,-1,0,149,149,"","",1,"lafuente_madrid","","",10,0,0,[],""],["palau_cantares-01303",4,"La flor de la calabaza\nes una maldita flor\nque se la dan á los hombres\ná la mejor ocasión.",4,0,-1,69,"",0,4,"o",-1,0,-1,0,149,149,"","",1,"","","",3,0,0,[],""],["palau_cantares-01304",4,"No me mires, que me matas,\ncon esos ojos tan tristes,\nporque se me representa\nel mal pago que me diste.",4,0,-1,69,"",0,4,"ie",-1,0,-1,0,149,149,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01305",4,"Las calabazas de mayo\ndicen que son las tempranas,\ny yo se las di á mi amante\nen abril una mañana.",4,0,-1,69,"",0,4,"aa",-1,0,-1,0,149,149,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01306",4,"Como la memoria es frágil,\nno recuerdo si te quise;\npero recuerdo, serrana,\nel mal pago que me diste.",4,0,-1,69,"",0,4,"ie",-1,0,-1,0,149,149,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01307",4,"Si me diste calabazas,\nme las comí con pan tierno;\nmás quiero las calabazas\nque una mujer sin gobierno.",4,0,-1,69,"",1,4,"eo",225,0,-1,0,149,149,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01308a",4,"Por la calle venden juicio;\ndi á tu madre que te compre,\nporque más falta te hace\nque á una ventana los goznes.",4,0,-1,69,"",0,4,"oe",-1,0,-1,0,150,150,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01308b",4,"Mi padre y mi madre son\nlos dueños de mi persona;\nsi te he dado calabazas,\namante mío, perdona.",4,0,-1,69,"",0,4,"oa",7,0,-1,0,150,150,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01308c",4,"Porque anoche no vine,\nte has ofendido;\nya no siento yo tanto\nno haber venido:\npues satisfecho\nde que tú lo sentiste,\nmenos lo siento.",4,0,-1,69,"",4,7,"eo",-1,0,-1,0,150,150,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01308d",4,"No dupliques los males\ná mis fatigas,\nque está de más la muerte\ndonde no hay vida.",4,0,-1,69,"",6,4,"ia",-1,0,-1,0,150,150,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01309a",4,"No me mires de lado,\nque es de traidores;\nmírame cara á cara,\nque es de señores.",4,0,-1,69,"",6,4,"oe",5,0,-1,0,150,150,"","",1,"rm_t2, barcenas_marinera, huambachano","","",4,0,0,[],""],["palau_cantares-01309b",4,"Me puse á ahondar un pozo\ncon mucho gusto y placer:\nsalióme amarguilla el agua,\nle eché tierra y lo cegué.",4,0,-1,69,"",0,4,"e",-1,0,-1,0,150,150,"","",1,"","","",1,0,0,[],""],["palau_cantares-01309c",4,"Si oyes doblar las campanas,\nno preguntes quien ha muerto,\nque á ti te lo ha de decir\ntu propio remordimiento.",4,0,-1,69,"",0,4,"eo",-1,0,-1,0,150,150,"","",1,"","","",1,0,0,[],""],["palau_cantares-01309d",4,"Por consejos que me han dado\nno me han podido vencer,\ny tú con uno tan sólo\nte apartas de mi querer.",4,0,-1,69,"",0,4,"e",20,0,-1,0,150,150,"","",1,"","","",1,0,0,[],""],["palau_cantares-01309e",4,"Si supieras mi dolor,\nmi sentimiento y mi pena,\ntú me pusieras cariño\npor muy ingrata que fueras.",4,0,-1,69,"",0,4,"ea",-1,0,-1,0,150,150,"","",1,"","","",2,0,0,[],""],["palau_cantares-01310a",4,"Todas las mañanas voy\ná misa á San Agustín,\ná darle gracias al santo\nque me ha librado de ti.",4,0,-1,7,"",0,4,"i",-1,0,-1,0,151,151,"","",1,"rm_t3, lafuente_madrid","","",12,0,0,[],""],["palau_cantares-01310b",4,"La muerte pediré á voces\nsi á curarme vienes tú:\nde ti no quiero la gloria,\ncuanto menos la salud.",4,0,-1,7,"",0,4,"u",-1,0,-1,0,151,151,"","",1,"","","",1,0,0,[],""],["palau_cantares-01310c",4,"Tú vienes de mala rama,\nno lo puedes remediar,\nnacida en malos pañales,\nhecha en pecado mortal.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,151,151,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01310d",4,"No tengo nada tuyo:\nsi lo tuviera,\ná la lumbre lo echara\npara que ardiera.",4,0,-1,7,"",6,4,"ea",44,0,-1,0,151,151,"","",1,"","","",2,0,0,[],""],["palau_cantares-01310f",4,"Permita Dios que te veas\nen un calabozo obscuro,\ny que pase por mis manos\ntodo el alimento tuyo.",4,0,-1,7,"",0,4,"uo",-1,0,-1,0,151,151,"","",1,"","","",4,0,0,[],""],["palau_cantares-01312b",4,"Permita Dios de los cielos\nque, cuando vuelva á quererte,\nse me salten los ojillos\nde un dolor de clavo fuerte.",4,0,-1,7,"",0,4,"ee",134,0,-1,0,151,151,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01312c",4,"Satisfacciones me pides,\nyo no te las quiero dar;\nque darte satisfacciones\nes volver á la amistad.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,151,151,"","",1,"lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01312d",4,"Si piensas darme pesares\ncon decir que tienes otra,\nyo tengo para ganarte\ncaballo, malilla y sota.",4,0,-1,7,"",0,4,"oa",-1,0,-1,0,151,151,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01312e",4,"Si piensas que con halagos\nme derrito como cera,\nsoy yo de tal calidad\nque el mismo fuego me hiela.",4,0,-1,7,"",0,4,"ea",-1,0,-1,0,151,151,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01313a",4,"Tus ojos para soles\nson muy pequeños;\npara estrellas son grandes,\nserán luceros.\n¡Ay, que te quise!\nComo no fué de veras,\nno te lo dije.",4,0,-1,7,"",4,7,"ie",-1,0,-1,0,152,152,"","",1,"","","",2,0,0,[],""],["palau_cantares-01313b",4,"Mi madre me aconseja\nque yo te ame,\ny yo, que no me gustas\ndigo á mi madre;\nque es fuerte empeño\nel querer que yo quiera\nlo que no quiero.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,152,152,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01313c",4,"Nada de cuanto digas\nquiero creerte,\nque una vez engañado,\nlo seré siempre:\nllama á otra puerta,\nporque la de mi casa\ncerrada queda.",4,0,-1,7,"",4,7,"ea",-1,0,-1,0,152,152,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01314",4,"Anda, que ya no te quiero,\nque ya se me fué el amor;\nya te barrí con la escoba\ndentro de mi corazón.",4,0,-1,7,"",0,4,"o",-1,0,-1,0,152,152,"","",1,"rm_t3, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01314-e2",4,"Dices que no me quieres\nporque soy sordo;\nyo tampoco te quiero\npor lo que oigo:\nporque soy ciego;\npues tampoco me gustas\npor lo que veo.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,152,152,"","",1,"","","",15,0,0,[],""],["palau_cantares-01314-e3",4,"Llámame como quieras,\nllámame ingrato,\npero déjame libre\nde tus enfados;\npues lo que quiero\nes no volver á verte\nni aun desde lejos.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,152,152,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01315",4,"Tienes el amor trompero,\ncomo se suele decir;\ncuantas veo, tantas quiero...\nNo me engañarás á mí.",4,0,-1,7,"",0,4,"i",-1,0,-1,0,152,152,"","",1,"","","",2,0,0,[],""],["palau_cantares-01316",4,"Tu genio impertinente\nse me resiste;\nyo no sé quién aguante\nsiempre á una chinche;\nporque mi genio\nprefiere á lluvias mansas\nun aguacero.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,152,152,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01317",4,"Eres como el gallo inglés,\nque á todos les haces cara,\ny á mí no me la has de hacer,\nporque te conozco, pava.",4,0,-1,7,"",0,4,"aa",-1,0,-1,0,152,152,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01318",4,"Ya no me queman á mí\nlas llamas de tu candela,\nque lo que ha sido y no es,\ncomo si en la vida fuera.",4,0,-1,7,"",0,4,"ea",-1,0,-1,0,152,152,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01319",4,"Poco me importan á mí\ntu amor ó tu malquerencia;\nporque el que está sin pecado,\nno teme la penitencia.",4,0,-1,7,"",0,4,"ea",46,0,-1,0,152,152,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01320",4,"Ya no quiero más pan tuyo,\nque me amarga la corteza;\nni conversación contigo:\nla que he tenido me pesa.",4,0,-1,7,"",0,4,"ea",201,0,-1,0,152,152,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01321",4,"Haz cuenta que me morí\ny estuvistes en mi entierro,\nque me vistes enterrar\ny asististes á mi duelo.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,152,152,"","",1,"","","",2,0,0,[],""],["palau_cantares-01322",4,"Ya te he dicho, compañera,\nno vengas en busca mía,\nque va mucha diferencia\nde tu persona á la mía.",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,152,152,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01323",4,"Anda, vete, que no quiero\npasar por ti más fatigas;\nsi digo que no te quiero,\n¿qué más quieres que te diga?",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,152,152,"","",1,"","","",5,0,0,[],""],["palau_cantares-01324",4,"Acaba de partir nueces\ny echa las piedras al río:\nlo que ha sido y ya no es,\ncomo si no hubiera sido.",4,0,-1,7,"",0,4,"io",-1,0,-1,0,152,152,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01325",4,"Quítate de mi presencia,\nque no te quiero mirar,\nque te tengo aborrecido\ncomo al pecado mortal.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,153,153,"","",1,"rm_t3, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01326",4,"Gitanilla como yo\nno la tienes de encontrar\naunque gitana se vuelva\ntodita la cristiandad.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,153,153,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01327",4,"Algún día lloraba\ntus esquiveces,\nhoy de que otros las lloren\nestoy alegre:\nque en este mundo\nsuelen llorar los otros,\nsi ríen unos.",4,0,-1,7,"",4,7,"uo",-1,0,-1,0,153,153,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01328",4,"¡Cuántas veces pasarás\npor donde yo esté enterrado,\ny ni siquiera dirás:\n¡que Dios te haya perdonado!",4,0,-1,7,"",1,4,"ao",14,0,-1,0,153,153,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01329a",4,"El amor que tú me diste\nlo metí en un agujero,\ny lo tapé con estopa,\ny luego le pegué fuego.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,153,153,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01329b",4,"Coge la rama de un roble\ny tírala á mi tejado;\ncuando la rama eche flores,\nte daré entonces la mano.",4,0,-1,7,"",0,4,"ao",-1,0,-1,0,153,153,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01329c",4,"Una silla en mi casa\nno te la niego;\npero te desengaño\nque no te quiero.",4,0,-1,7,"",6,4,"eo",-1,0,-1,0,153,153,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-01329d",4,"Algún día te quise\nporque no supe\ndel pie que cojeabas,\nni tus embustes;\nmas ya te entiendo;\nno serás tú la maula\nque me dé celos.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,153,153,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01330",4,"Recuerdo que fui tu novia,\nte casaste y no conmigo:\nsiempre que me encuentras, lloras;\nsiempre que te encuentro, río.",4,0,-1,7,"",0,4,"io",-1,0,-1,0,153,153,"","",1,"","","",2,0,0,[],""],["palau_cantares-01331",4,"Los amores se me han ido,\nla causa yo no la sé;\npiensan que me han agraviado,\ny me han hecho gran merced.",4,0,-1,7,"",0,4,"e",-1,0,-1,0,153,153,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01332",4,"Tú pensarás que me has hecho\nagravio con enojarte;\ny me has hecho un beneficio\nque no sé con qué pagarte.",4,0,-1,7,"",0,4,"ae",8,0,-1,0,153,153,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01333",4,"Cuando me dieron la nueva\nde que tú no me querías,\nse me quedó el corazón...\nlo mismo que lo tenía.",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,153,153,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01334",4,"¿Fuiste tú la que dijiste\nayer en el lavadero\nque te casabas conmigo?\nEso será si yo quiero.",4,0,-1,7,"",0,4,"eo",38,0,-1,0,153,153,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01335",4,"Cuando me dieron la nueva\nde que tú no me querías,\nhasta el gato de mi casa\nme miraba y se reía.",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,153,153,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01336",4,"Dueño mío, este es mi genio,\nyo no me muero por ti.\nque en otro papel más fino\nme enseñaron á escribir.",4,0,-1,7,"",0,4,"i",-1,0,-1,0,153,153,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01337a",4,"Parece que me miras:\n¿quieres comprarme?\nNo tienes tú dinero\npara pagarme.",4,0,-1,7,"",6,4,"ae",35,0,-1,0,154,154,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01337b",4,"Si piensas que te quiero,\nmal has pensado;\nporque tengo yo un gusto\nmuy delicado.",4,0,-1,7,"",6,4,"ao",14,0,-1,0,154,154,"","",1,"","","",3,0,0,[],""],["palau_cantares-01338",4,"¿Qué cuidado le da al rey\nde que se muera un soldado?\nLo mismo que me da á mí\nde que me hayas olvidado.",4,0,-1,7,"",0,4,"ao",14,0,-1,0,154,154,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01338-e2",4,"Anda diciendo tu madre\nque te mereces la reina;\nanda, ve y dile á ese trapo\nque vaya á Madrid por ella.",4,0,-1,7,"",0,4,"ea",-1,0,-1,0,154,154,"","",1,"lafuente_madrid","","",23,0,0,[],""],["palau_cantares-01339",4,"Si piensas que en ti pienso,\nmal has pensado;\ntengo mi pensamiento\npor otro lado.",4,0,-1,7,"",6,4,"ao",14,0,-1,0,154,154,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01340",4,"Niña de los veinte novios,\nque con ninguno te casas,\nsi te guardas para un rey,\ncuatro tiene la baraja.",4,0,-1,7,"",0,4,"aa",-1,0,-1,0,154,154,"","",1,"rm_t3, lafuente_madrid","","",11,0,0,[],""],["palau_cantares-01341",4,"Tan ofendida me tienes\ncon obras y con palabras,\nque aunque difunto te viera,\nni agua bendita te echara.",4,0,-1,7,"",0,4,"aa",-1,0,-1,0,154,154,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01342",4,"Oyendo falsedades\nvine á quererte,\npero has dado, amiguita,\ncon quien te entiende.\n¡Ay que no es nada!,\n¡con lo que se nos viene\nla buena maula!",4,0,-1,7,"",4,7,"aa",-1,0,-1,0,154,154,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01343a",4,"Tantas hojas como tiene\nla alameda de Genil,\ntantos demonios te lleven\ncuando te acuerdes de mí.",4,0,-1,7,"",0,4,"i",-1,0,-1,0,154,154,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01343b",4,"Dicen que usted no me quiere,\nse me dan tres caracoles;\nmás arriba ó más abajo,\nme están queriendo á montones.",4,0,-1,7,"",0,4,"oe",-1,0,-1,0,154,154,"","",1,"","","",3,0,0,[],""],["palau_cantares-01343c",4,"Dicen que usted no me quiere;\ná mí no me da cuidado;\nmañana me pongo luto\nde tafetán encarnado.",4,0,-1,7,"",0,4,"ao",14,0,-1,0,154,154,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-01343d",4,"Pensaba la muy tontona,\npensaba que lloraría:\nno sabe que en la taberna\nvenden cañas de alegría.",4,0,-1,7,"",0,4,"ia",0,0,-1,0,154,154,"","",1,"","","",2,0,0,[],""],["palau_cantares-01343e",4,"Tienes de caballero\ntan sólo el nombre,\npues no lo manifiestas\nen tus acciones:\ny es vana cosa\ntener buenos dictados\ny malas obras.",4,0,-1,7,"",4,7,"oa",-1,0,-1,0,154,154,"","",1,"","","",1,0,0,[],""],["palau_cantares-01344a",4,"Si no me correspondes,\nno correspondo;\nmala cara me pones,\nmala te pongo;\ncon tal despejo,\nque si tú me la pegas,\nyo te la pego.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,154,154,"","",1,"","","",2,0,0,[],""],["palau_cantares-01344b",4,"Si, porque yo te quiero,\ntú te imaginas\nque has de jugar conmigo...,\nnaranjas chinas:\nno hay que dudarlo,\nporque tú muy bien sabes\nque soy naranjo.",4,0,-1,7,"",4,7,"ao",-1,0,-1,0,154,154,"","",1,"","","",1,0,0,[],""],["palau_cantares-01344c",4,"Yo tengo sal, aunque poca,\npero has de saber, y escucha,\nque la gasto con quien quiero,\ncon personas que me gustan.",4,0,-1,7,"",0,4,"ua",-1,0,-1,0,154,154,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01344d",4,"Deja de escandalizar\nla calle con tus paseos,\nque los suspiros que das\nni los oigo, ni los creo.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,154,154,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01345",4,"Me quisiste, me olvidaste\ny me volviste á querer:\nzapato que yo desecho,\nno me lo vuelvo á poner.",4,0,-1,7,"",0,4,"e",20,0,-1,0,155,155,"","",1,"isaacs_colombia, lafuente_madrid","","",8,0,0,[],""],["palau_cantares-01346",4,"Si piensas que yo te quiero\nporque te miro y me río,\nsoy un poquillo burlona,\ny tú no lo has conocido.",4,0,-1,7,"",0,4,"io",-1,0,-1,0,155,155,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01347",4,"Zapato que yo desecho\ny lo tiro al muladar,\nque otro venga y se lo ponga\n¿qué cuidado se me da?",4,0,-1,7,"",0,4,"a",-1,0,-1,0,155,155,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01348",4,"Si piensas que yo te quiero,\nporque te miro á la cara,\nes como el que va á la feria\ná ver y no comprar nada.",4,0,-1,7,"",0,4,"aa",-1,0,-1,0,155,155,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01350",4,"Si piensas que en tu ausencia\nme pongo triste,\npara suplir tu falta\ntengo yo quince.",4,0,-1,7,"",6,4,"ie",-1,0,-1,0,155,155,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01350-e2",4,"Supuesto que no quieres\nnada conmigo,\ncuando te pareciere\ntoma el camino.",4,0,-1,7,"",6,4,"io",-1,0,-1,0,155,155,"","",1,"rm_t3, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01350-e3",4,"Que tienes muchos majos\ndicen que dices;\nmira, cuando reclames,\nno halles perdices.",4,0,-1,7,"",6,4,"ie",113,0,-1,0,155,155,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01350-e4",4,"Anda y dile á tu madre\nque te empapele,\nque_ la que te quería\nya no te quiere.",4,0,-1,7,"",6,4,"ee",-1,0,-1,0,155,155,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01350-e5",4,"Cuando paso por tu puerta\ncompro pan y voy comiendo, '\nporque no diga tu madre\nque de verte me mantengo.",4,0,-1,7,"",5,4,"eo",-1,0,-1,0,155,155,"","",1,"murciano_antiguo","","",17,0,0,[],""],["palau_cantares-01350-e6",4,"Anda diciendo tu madre\nque yo á ti te he entretenido,\ny te tengo yo apuntada\nen el libro del olvido.",4,0,-1,7,"",0,4,"io",101,0,-1,0,155,155,"","",1,"lafuente_madrid","","",23,0,0,[],""],["palau_cantares-01350-e7",4,"Acuerdóme de un tiempo\nque en ti vivía,\ny por ti hago memoria\nque me moría:\nno hay bien estable;\nsépase que no hay cosa\nque no se pase.",4,0,-1,7,"",4,7,"ae",-1,0,-1,0,155,155,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01351",4,"De las dichas que hallaba\nmi cautiverio,\nahora que estoy libre\nya no me acuerdo;\nque aquellas dichas,\npor ser hijas de un ciego,\nno tienen vista.",4,0,-1,7,"",4,7,"ia",-1,0,-1,0,156,156,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01351-e2",4,"Del templo de Cupido\nfui yo devota,\ny el santo que adoraba\nse fué con otra:\nno me da pena,\nque ya tengo otro santo\nque más me quiera.",4,0,-1,7,"",4,7,"ea",-1,0,-1,0,156,156,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01351-e3",4,"Hoy que ya sin cadenas\nlibre respiro,\nla libertad disfruto\nde mi albedrío;\ny estoy contento\nde verme tan distante\ndel cautiverio.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,156,156,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01351-e4",4,"A la sierra me he de ir\ná buscar una morena,\nque las chicas de mi pueblo\nninguna me da ya pena.",4,0,-1,7,"",0,4,"ea",59,0,-1,0,156,156,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01351-e5",4,"Eres avellana vana,\neres almendro sin flor,\neres rosa sin capullo,\neres clavel sin olor.",4,0,-1,7,"",0,4,"o",72,0,-1,0,156,156,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01351-e6",4,"Debajo de tu ventana\nme encontré un pañuelo azul\ncon un letrero que dice:\n¡qué poco me gustas tú!",4,0,-1,7,"",0,4,"u",-1,0,-1,0,156,156,"","",1,"lafuente_madrid","","",29,0,0,[],""],["palau_cantares-01352",4,"Que tenga la boca grande,\nó tenga la boca chica,\n¿si no has de ser mi marido,\ná qué me tomas medida?",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,156,156,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01352-e2",4,"Pensabas que te quería,\ny era por entretenerme;\nmientras otro me salía,\nme servías de juguete.",4,0,-1,7,"",0,4,"ee",-1,0,-1,0,156,156,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01352-e3",4,"¡Qué bien te habrás divertido'\nen el tiempo de mi ausencia!\nYo también hice lo mismo\npor descargar tu conciencia.",4,0,-1,7,"",0,4,"ea",46,0,-1,0,156,156,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01352-e4",4,"Échale trigo á la era\ny conmigo no platiques,\nque tengo yo quien me quiera\ndesde el día que te fuiste.",4,0,-1,7,"",0,4,"ie",-1,0,-1,0,156,156,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01352-e5",4,"Dígale usted al mozo\nque está en la esquina,\nsi tiene calentura,\nque tome quina.",4,0,-1,7,"",6,4,"ia",11,0,-1,0,156,156,"","",1,"fernan_caballero","","",2,0,0,[],""],["palau_cantares-01352-e6",4,"Dicen que no me quieres,\nya me has querido:\nvayase lo ganado\npor lo perdido.",4,0,-1,7,"",6,4,"io",101,0,-1,0,156,156,"","",1,"rm_t3, huambachano","","",18,0,0,[],""],["palau_cantares-01352-e7",4,"Es cierto que te he querido,\nque te he querido y te quiero.\npero casarme contigo,\nno lo permitan los cielos.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,156,156,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01352-e8",4,"Otros más altos que tú,\npajarillos de más cuenta,\nme están mirando á la cara\npara ver si estoy contenta;",4,0,-1,7,"",0,4,"ea",229,0,-1,0,156,156,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01353",4,"Me llamaste «mi blanca»\npor hacer burla;\nmorenita soy, majo,\npero no tuya.",4,0,-1,7,"",6,4,"ua",-1,0,-1,0,156,156,"","",1,"","","",1,0,0,[],""],["palau_cantares-01354",4,"Por mirarte, algún día\nsuspiros daba,\ny ahora por no verte\nvuelvo la cara.",4,0,-1,7,"",6,4,"aa",-1,0,-1,0,156,156,"","",1,"","","",2,0,0,[],""],["palau_cantares-01355",4,"Si piensas que por ti son\nlos colores que me salen,\nen mi vida me enamoro\nde un hombre que poco vale.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,156,156,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01356",4,"Ya se acabó aquel tiempo\n(¡todo se acaba!)\nque sólo con mirarte\nme alimentaba.",4,0,-1,7,"",6,4,"aa",-1,0,-1,0,156,156,"","",1,"rm_t3, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01357",4,"Se pensaba el mozo vano\nque yo por él me moría;\ndesde que no hablo con él,\nse me ha alargado la vida.",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,159,159,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01358",4,"Si la ocasión se presenta\nde verte en alguna parte,\nte he de volver las espaldas,\nme he de marchar sin hablarte.",4,0,-1,7,"",0,4,"ae",8,0,-1,0,159,159,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01359",4,"¿Qué cuidado me da á mí\nque pases y no me hables,\nsi sabes que yo no como\ncon buenos días de nadie?",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,159,159,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01360",4,"Si te mueres, lloraré\npor la falta que me haces,\ny otro en tu lugar pondré,\nque todo lo nuevo place.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,159,159,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01361",4,"Yo como y bebo sin ti,\ntu querer no me hace falta;\nni el mundo se encierra en ti,\nni los hombres se rematan.",4,0,-1,7,"",0,4,"aa",-1,0,-1,0,159,159,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01362",4,"Si piensas que han de volver\nlas nueces al cantarillo,\ná ti se te fué el amor,\ná mí el amor y el cariño.",4,0,-1,7,"",0,4,"io",-1,0,-1,0,159,159,"","",1,"","","",3,0,0,[],""],["palau_cantares-01363",4,"Anda con Dios, bien te logres,\nno te quiero mal ninguno:\nhora de salud no tengas\nmientras vivas en el mundo.",4,0,-1,7,"",0,4,"uo",-1,0,-1,0,159,159,"","",1,"","","",4,0,0,[],""],["palau_cantares-01364",4,"Si me quieren, sé querer;\nsi me olvidan, olvidar;\nsi me desprecian, desprecio,\nporque este es mi natural.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,159,159,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01365",4,"Una caña de pescar\ntengo para mi consuelo:\nsi un amante se me va,\notro queda en el anzuelo.",4,0,-1,7,"",0,4,"eo",10,0,-1,0,159,159,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01366",4,"Si vienes, bien te recibo,\ny si no, no me haces falta:\nhas de saber, dueño mío,\nque yo no contemplo gaitas.",4,0,-1,7,"",0,4,"aa",-1,0,-1,0,159,159,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01367",4,"Toda la calle á lo largo\nla he sembrado de melones:\nme han salido calabazas\npara darlas á los hombres.",4,0,-1,7,"",0,4,"oe",-1,0,-1,0,159,159,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01368",4,"Te pones por todas partes\ná publicar que te quiero,\ny hasta al santo de tu nombre\naborrecido lo tengo.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,159,159,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01369",4,"Piensas que me vuelven loca\ntus patillas y cuchillo,\ny yo no quiero galanes\nque escupen por el colmillo.",4,0,-1,7,"",0,4,"io",228,0,-1,0,159,159,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01370",4,"Aunque en una cruz te pongas,\npara mí acabaste ya\npor haber querido á un tiempo\ncon dos barajas jugar.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,159,159,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01371",4,"Como no tengo fines\nparticulares,\nno siento que te enojes,\nni que te enfades.",4,0,-1,7,"",6,4,"ae",-1,0,-1,0,159,159,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01372",4,"El querer que puse en ti\nun cuervo se lo llevó,\ny en medio de aquellos mares\nabrió el pico y lo soltó.",4,0,-1,7,"",0,4,"o",2,0,-1,0,159,159,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01373",4,"El amor que te tengo\ny el que me tienes,\npuestos en la balanza,\nni van ni vienen.",4,0,-1,7,"",6,4,"ee",-1,0,-1,0,159,159,"","",1,"rm_t3","","",10,0,0,[],""],["palau_cantares-01374",4,"El querer que te tenía\nera poco y se me fué;\ny como vino San Juan,\ná otra parte lo mudé.",4,0,-1,7,"",0,4,"e",77,0,-1,0,159,159,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01375",4,"El amor que te tuve\nfué de bayeta;\nse le ha caído el pelo;\nya no calienta.",4,0,-1,7,"",6,4,"ea",-1,0,-1,0,159,159,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01376",4,"Algún día te quería\ny ahora ya no te quiero,\nporque he encontrado paloma\nque remonta más el vuelo.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,159,159,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01377",4,"Que te quise, cierto fué;\nque te olvidé, no es mentira:\nque en los árboles las hojas\nno duran toda la vida.",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,160,160,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01377-e2",4,"Una vez tuve una novia\ny ella pretendió dejarme,\ny yo tomé pan con tiempo\nantes que me diera hambre.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,160,160,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01377-e3",4,"Anda, vete, no te quiero,\nque ya me cansé de amarte,\nque eres farol encendido\nque alumbras á todas partes.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,160,160,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01377-e4",4,"Pensabas tú que tenías\nel pájaro de la cola,\ny luego que se te ha ido,\nte has quedado como boba.",4,0,-1,7,"",0,4,"oa",-1,0,-1,0,160,160,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01377-e5",4,"De San Juan quiero la palma,\nde Santiago la cruz:\nde tu cuerpo, compañera,\nno quiero ni la salud.",4,0,-1,7,"",0,4,"u",-1,0,-1,0,160,160,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01377-e6",4,"Cuando quise, no quisiste;\nahora que quieres, no quiero;\npasa tú la vida triste,\nque yo la pasé primero.",4,0,-1,7,"",1,4,"eo",38,0,-1,0,160,160,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-01377-e7",4,"Aunque tu padre me diera\nla muía y el carretón,\nno me casara contigo\npor tu mala condición.",4,0,-1,7,"",3,4,"o",31,0,-1,0,160,160,"","",1,"","","",7,0,0,[],""],["palau_cantares-01377-e8",4,"Tus malas intenciones\nbien las conozco:\ná un santo desnudaste\npor vestir otro;\npero te digo\nque el que tú desnudaste\nya está vestido.",4,0,-1,7,"",4,7,"io",-1,0,-1,0,160,160,"","",1,"","","",2,0,0,[],""],["palau_cantares-01377-e9",4,"Desde que usted se pasea\npor las calles del lugar,\nestá perdida la venta\nde las cañas de pescar.",4,0,-1,7,"",0,4,"a",21,0,-1,0,160,160,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01378",4,"Aunque seas buena moza,\nno te lo presumas tanto,\nque también las buenas mozas\nse suelen quedar en blanco.",4,0,-1,7,"",0,4,"ao",-1,0,-1,0,160,160,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01378-e2",4,"Compañerita del alma,\n¿por dónde la llevas tú?\nYo camino por la arena,\ny tú por el cielo azul.",4,0,-1,7,"",0,4,"u",-1,0,-1,0,160,160,"","",1,"rm_t3, lafuente_madrid","","",20,0,0,[],""],["palau_cantares-01378-e3",4,"El zapato tengo roto,\n¿con qué lo remendaré?\nCon picos de malas lenguas\nque dicen lo que no es.",4,0,-1,7,"",0,4,"e",-1,0,-1,0,160,160,"","",1,"","","",2,0,0,[],""],["palau_cantares-01378-e5",4,"Siendo tan buena moza,\nno te has casado;\nalgún pero en el arca\ntendrás guardado;\npero que es pero,\npero que no es de Ronda,\nyo no lo quiero.",4,0,-1,7,"",4,7,"eo",38,0,-1,0,160,160,"","",1,"","","",1,0,0,[],""],["palau_cantares-01378-e6",4,"Al balcón del despreciosola me asomo,\nal ver lo bien que pago\nlo mal que cobro:\nque si cobrara,\nal balcón del desprecio\nno me asomara.",4,0,-1,7,"",9,6,"aa",57,0,-1,0,160,160,"","",1,"","","",1,0,0,[],""],["palau_cantares-01378-e7",4,"Como el rostro disfrazas\ncon mil colores,\nmis ojos al mirarte\nte desconocen;\nvuelve á tu tono,\ny deja á la vergüenza\nsalir al rostro.",4,0,-1,7,"",4,7,"oo",-1,0,-1,0,160,160,"","",1,"","","",1,0,0,[],""],["palau_cantares-01378-e8",4,"Anda diciendo tu madre\nque yo contigo no igualo:\nesto será en el dinero,\nporque en la sangre te gano.",4,0,-1,7,"",0,4,"ao",-1,0,-1,0,160,160,"","",1,"","","",23,0,0,[],""],["palau_cantares-01379",4,"Me han dicho que estás mala,\nDios te levante...\nde la cama á la caja\npara enterrarte.",4,0,-1,7,"",6,4,"ae",-1,0,-1,0,161,161,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01380",4,"Si tu madre tiene usía,\nanda y ve y dile á tu madre\nque yo me llamo Rosquillas\ny me estoy muriendo de hambre.",4,0,-1,7,"",3,4,"ae",-1,0,-1,0,161,161,"","",1,"","","",1,0,0,[],""],["palau_cantares-01381",4,"Cuervos te saquen los ojos,\ny águilas el corazón,\ny serpientes las entrañas,\npor tu mala condición.",4,0,-1,7,"",0,4,"o",31,0,-1,0,161,161,"","",1,"","","",1,0,0,[],""],["palau_cantares-01384",4,"A qué tienes esos ojos\nsiempre á la tierra mirando:\nsi eres capaz de sacarle\nlos dientes á un ahorcado.",4,0,-1,7,"",0,4,"ao",-1,0,-1,0,161,161,"","",1,"","","",1,0,0,[],""],["palau_cantares-01385",4,"Permita Dios que te veas\naborrecida y queriendo,\ny que las penas te roan\nlas entrañas de tu cuerpo.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,161,161,"","",1,"","","",4,0,0,[],""],["palau_cantares-01385-e2",4,"La maldita lengua\nque de mí murmura,\nyo la cogiera por en medio, en medio,\nla dejara muda.",4,0,-1,7,"",3,4,"ua",-1,0,-1,0,161,161,"","",1,"","","",1,0,0,[],""],["palau_cantares-01385-e3",4,"Escuche usted, buena moza,\nno me gaste fantesía,\nque el carro de la basura\ntambién gasta campanillas.",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,161,161,"","",1,"","","",1,0,0,[],""],["palau_cantares-01385-e4",4,"No te pongas tan alta,\nque no eres reina;\nyo me atrevo á alcanzarte\nsin escalera.",4,0,-1,7,"",6,4,"ea",-1,0,-1,0,161,161,"","",1,"rm_t3, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01385-e5",4,"Anda y dile á quien te quiere\nque por mí esté descuidado,\npero que tenga la pena\nde comer de mi sobrado.",4,0,-1,7,"",0,4,"ao",14,0,-1,0,161,161,"","",1,"","","",2,0,0,[],""],["palau_cantares-01385-e6",4,"Como mi amor desprecias,\nyo marcho en posta\ná dar estas noticias\ná doña Otra;\nque es el remedio\ncon que presto se curan\ntales desprecios.",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,161,161,"","",1,"","","",2,0,0,[],""],["palau_cantares-01386a",4,"Ayer tarde vi vender\nen la plazuela Real\nla palabrilla de un hombre:\n¡nadie la quiso comprar!",4,0,-1,7,"",0,4,"a",-1,0,-1,0,161,161,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01386b",4,"San Juan con una concha\nbautizó á Cristo;\nyo, con las que tú tienes,\nme desbautizo:\nsigue tu trama,\nque si tú tienes conchas,\nyo tengo escamas.",4,0,-1,7,"",4,7,"aa",-1,0,-1,0,161,161,"","",1,"","","",1,0,0,[],""],["palau_cantares-01386c",4,"Tienes tanto atractivo,\ntanta hermosura,\nque para no quererte\nno hallo disculpa;\nmas me detiene\nel temor de llevarme\ngato por liebre.",4,0,-1,7,"",4,7,"ee",-1,0,-1,0,161,161,"","",1,"","","",1,0,0,[],""],["palau_cantares-01386d",4,"¿Qué importa que yo queme\nen tus altares\nmás incienso que llanto\ndan mis pesares,\nsi allá en tu templo\nel último que llega\nquema el incienso?",4,0,-1,7,"",4,7,"eo",-1,0,-1,0,161,161,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01386e",4,"San Antonio me perdone\npor lo que voy á decir:\nque ninguno de su nombre\nnunca me ha gustado á mí.",4,0,-1,7,"",0,4,"i",-1,0,-1,0,161,161,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01387",4,"Sentido vienen vendiendo,\ntu madre que te lo compre,\nporque te hace mucha falta,\ncomo á una puerta los goznes.",4,0,-1,7,"",0,4,"oe",-1,0,-1,0,162,162,"","",1,"","","",1,0,0,[],""],["palau_cantares-01388",4,"Gastas mucha jantesía\ny te tienes de quedar\nseñalando con el dedo\ncomo se quedó San Juan.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,162,162,"","",1,"","","",1,0,0,[],""],["palau_cantares-01389",4,"Si me diste calabazas,\nme las comí con pan tierno:\nmejor quiero calabazas\nque una mujer sin gobierno.",4,0,-1,7,"",1,4,"eo",225,0,-1,0,162,162,"","",1,"","","",3,0,0,[],""],["palau_cantares-01390",4,"Quisiera ser basilisco,\npor horas y por momentos,\nmatar á quien yo quisiera,\ny descansara mi cuerpo.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,162,162,"","",1,"rm_t3, frenk_t4","","",3,0,0,[],""],["palau_cantares-01391",4,"Al principio de quererte\nestaba ciego y no vía:\nya se me quitó la venda\nque en los ojillos tenía.",4,0,-1,7,"",0,4,"ia",0,0,-1,0,162,162,"","",1,"","","",3,0,0,[],""],["palau_cantares-01392",4,"A aquel que tuvo la culpa,\nmadre, de mi perdición,\ná cachitos se le caigan\nlas alas del corazón.",4,0,-1,7,"",0,4,"o",31,0,-1,0,162,162,"","",1,"","","",1,0,0,[],""],["palau_cantares-01393",4,"Me llamaste «mi cuñada,»\npensando que ya lo era:\nno me siento yo en tablado\nde tan endeble madera.",4,0,-1,7,"",0,4,"ea",44,0,-1,0,162,162,"","",1,"","","",1,0,0,[],""],["palau_cantares-01394",4,"Tierra, ¿por qué no te abres\ny te sales de tu centro\ny tragas á esa mujer\nde tan malos sentimientos?",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,162,162,"","",1,"","","",2,0,0,[],""],["palau_cantares-01395",4,"Por dondequiera que voy\nme dicen que yo soy tuyo:\n¿qué cadena me has echado\nque me tienes tan seguro?",4,0,-1,7,"",0,4,"uo",-1,0,-1,0,162,162,"","",1,"","","",3,0,0,[],""],["palau_cantares-01396",4,"Dicen que por el pelo\ntienes amores:\necha el pelo en la olla,\nverás qué comes.",4,0,-1,7,"",6,4,"oe",-1,0,-1,0,162,162,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01397",4,"El quererte yo á ti, sí;\ny el tomar, cuanto me dieres:\npero casarme contigo,\ncréelo cuando lo vieres.",4,0,-1,7,"",0,4,"ee",55,0,-1,0,162,162,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01398",4,"En medio del corazón\nun navajazo te dieron:\nmira si lo tienes duro\ncuando rechazó el acero.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,162,162,"","",1,"","","",1,0,0,[],""],["palau_cantares-01399a",4,"Tonta tú, tonta tu madre,\ntontas tu abuela y tu tía:\n¿cómo quieres que te quiera\nsi eres de la Tontería?",4,0,-1,7,"",0,4,"ia",0,0,-1,0,162,162,"","",1,"","","",1,0,0,[],""],["palau_cantares-01400b",4,"No te extiendas, verdolaga,\narrecógete un poquito,\nque no es la huerta tan grande,\nni el hortelano tan rico.",4,0,-1,7,"",0,4,"io",-1,0,-1,0,162,162,"","",1,"","","",1,0,0,[],""],["palau_cantares-01402",4,"Vestida de negro luto\nte he de ver por esas calles,\ny te has de hincar de rodillas\npara que me ponga á hablarte.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,162,162,"","",1,"","","",2,0,0,[],""],["palau_cantares-01403",4,"Me han dicho que estás sembrando\ncalabazas para mí:\nyo las tengo ya con flores,\nadelante te cogí.",4,0,-1,7,"",0,4,"i",23,0,-1,0,162,162,"","",1,"","","",2,0,0,[],""],["palau_cantares-01404",4,"Al barquillo que en la mar\nestá pegando vaivenes\ntengo yo comparadita\nla voluntad que me tienes.",4,0,-1,7,"",0,4,"ee",120,0,-1,0,162,162,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01405",4,"Te he comparado, niña,\ncon un pimiento,\nque nadie ve las pipas\nsi no está abierto.",4,0,-1,7,"",6,4,"eo",-1,0,-1,0,163,163,"","",1,"","","",2,0,0,[],""],["palau_cantares-01406",4,"Un día, por verte,\ndinero yo daba;\ncompañerita, ahora por no verte\nvuelvo yo la cara.",4,0,-1,7,"",3,4,"aa",-1,0,-1,0,163,163,"","",1,"","","",1,0,0,[],""],["palau_cantares-01408",4,"Lo mismito que los perros\nque andan sueltos por la calle\nbuscando huesos que tiran,\nhas de andar tú por buscarme.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,163,163,"","",1,"","","",1,0,0,[],""],["palau_cantares-01409",4,"No quiero comer contigo\ngallinas ni pavos reales;\nquiero pan de munición\ncon persona que me agrade.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,163,163,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01410",4,"Eres como el atambor,\nque mete mucho ruido,\ny si se mira por dentro,\nse encuentra que está vacío.",4,0,-1,7,"",0,4,"io",-1,0,-1,0,163,163,"","",1,"","","",1,0,0,[],""],["palau_cantares-01411",4,"No quiero que tú me quieras,\nque yo quien me quiera tengo,\ny de tu vida y milagros\nmuy largas noticias tengo.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,163,163,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01412",4,"Del clavel que me distes\nanacarado,\ntoma tú las cenizas,\nque lo he quemado.",4,0,-1,7,"",6,4,"ao",14,0,-1,0,163,163,"","",1,"","","",2,0,0,[],""],["palau_cantares-01413",4,"Aunque me ves tan chiquita,\nhuérfana de padre y madre,\nno se cría esta lechuga\npara tan flojo vinagre.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,163,163,"","",1,"","","",2,0,0,[],""],["palau_cantares-01414",4,"Si esta mujer no me quiere,\n¿qué hago yo con afligirme?\n¡A mí no me ha de faltar\notra con quien divertirme!",4,0,-1,7,"",0,4,"ie",184,0,-1,0,163,163,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01415",4,"Yo me enamoré de noche\ny la luna me engañó:\notra vez que me enamore,\nserá de día y con sol.",4,0,-1,7,"",0,4,"o",-1,0,-1,0,163,163,"","",1,"rm_t3, frenk_t2, fernan_caballero","","",9,0,0,[],""],["palau_cantares-01416",4,"Anda, vete enhoramala,\ny en tu cara te lo digo:\nque eres tú muy poca cosa\npara casarte conmigo.",4,0,-1,7,"",0,4,"io",106,0,-1,0,163,163,"","",1,"","","",2,0,0,[],""],["palau_cantares-01417",4,"Dicen que tú no me quieres,\nporque no tengo qué dar;\ncásate con el reloj,\nque á todas las horas da.",4,0,-1,7,"",0,4,"a",-1,0,-1,0,163,163,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-01418",4,"Se puso tu madre y dijo\nque la reina para ti:\nanda, ve y dile á tu madre\nque la reina está en Madrid.",4,0,-1,7,"",0,4,"i",-1,0,-1,0,163,163,"","",1,"lafuente_madrid","","",8,0,0,[],""],["palau_cantares-01419",4,"El amor y el interés\nsalieron al campo un día;\npudo más el interés\nque el amor que me tenías.",4,0,-1,7,"",0,4,"ia",-1,0,-1,0,163,163,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01420",4,"Dueño mío, este es mi genio:\nyo no me muero por nadie:\nsi vienes, bien te recibo;\ny si te vas, buen viaje.",4,0,-1,7,"",0,4,"ae",-1,0,-1,0,163,163,"","",1,"rm_t3","","",5,0,0,[],""],["palau_cantares-01421",4,"Por interés del dinero\nte fuiste de la cabeza;\ndijiste que eras gitana,\nte volviste montañesa.",4,0,-1,7,"",0,4,"ea",201,0,-1,0,163,163,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01422",4,"Me han dicho que tienes, niña,\ncatorce novios contados:\nconmigo no cuentes ya,\nque tengo el hato aviado.",4,0,-1,7,"",0,4,"ao",-1,0,-1,0,163,163,"","",1,"","","",1,0,0,[],""],["palau_cantares-01423",4,"Aunque me ves tan bajito\ny tú tan alta te ves,\nno pienses que soy escoba\nque conmigo has de barrer.",4,0,-1,7,"",0,4,"e",-1,0,-1,0,163,163,"","",1,"","","",1,0,0,[],""],["palau_cantares-01424",4,"¡De qué te sirve tener\nbastón de quiquiricaña,\nsi te dicen las mozuelas:\n- Buen mozo, pero no apaña!",4,0,-1,7,"",0,4,"aa",213,0,-1,0,163,163,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01425",4,"Se puso tu madre y dijo\nque eras tú mejor que yo.\n¿En qué libro lo ha leído\nó en qué sueño lo ensoñó?",4,0,-1,7,"",0,4,"o",2,0,-1,0,164,164,"","",1,"","","",8,0,0,[],""],["palau_cantares-01426",4,"Eres alta como un huevo,\nderecha como una hoz,\nblanca como el azabache:\n¡buenas noches nos dé Dios!",4,0,-1,7,"",0,4,"o",87,0,-1,0,164,164,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01427",4,"La primer vez que te vi\nme pareciste muy guapa;\nmas luego me pareciste\nun saco lleno de paja.",4,0,-1,7,"",0,4,"aa",-1,0,-1,0,164,164,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01428",4,"Eres alta como un sapo\ny rubia como un caldero;\nojos de garza pelada\ny escapada del infierno.",4,0,-1,7,"",0,4,"eo",-1,0,-1,0,164,164,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01429a",4,"Las sábanas de mi cama\ntodas las noches las lavo\ncon lágrimas de mis ojos,\nal ver que me has olvidado.",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,165,165,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01429b",4,"El viento barre las nubes\ny vuelve la claridad:\nel nublado de mis penas\ncon ningún viento se va.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,165,165,"","",1,"","","",1,0,0,[],""],["palau_cantares-01429c",4,"Yo no soy, no, quien he sido,\nno soy quien solía ser:\nsoy un cuadro de tristeza,\narrimado á una pared.",4,0,-1,70,"",0,4,"e",-1,0,-1,0,165,165,"","",1,"","","",1,0,0,[],""],["palau_cantares-01429d",4,"Ya no hacen las golondrinas\nsus nidos en mi portal:\n¡era preciso que fuese\ncompleta mi soledad!",4,0,-1,70,"",0,4,"a",-1,0,-1,0,165,165,"","",1,"","","",1,0,0,[],""],["palau_cantares-01429e",4,"Si las piedras de tu calle\ntuvieran conocimiento,\nsólo de verme pasar\nlloraran de sentimiento.",4,0,-1,70,"",0,4,"eo",94,0,-1,0,165,165,"","",1,"","","",6,0,0,[],""],["palau_cantares-01430a",4,"Desde que te conocí\nestoy sufriendo trabajo,\nque me ha puesto tu querer\ncomo vela boca abajo.",4,0,-1,70,"",0,4,"ao",168,0,-1,0,165,165,"","",1,"","","",11,0,0,[],""],["palau_cantares-01430b",4,"Ven que te diga el oído\nlas cosas que me suceden:\nestoy enfermo del alma\ny el médico no lo entiende.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,165,165,"","",1,"","","",1,0,0,[],""],["palau_cantares-01430c",4,"Ni en el sueño halla reposo\neste pobrecito cuerpo,\nque la pena que le roe\nno descansa ni un momento.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,165,165,"","",1,"","","",1,0,0,[],""],["palau_cantares-01431",4,"Una tórtola te traigo,\nde su nido la cogí:\npor ella llora su madre\ncomo yo lloro por ti.",4,0,-1,70,"",0,4,"i",23,0,-1,0,165,165,"","",1,"","","",3,0,0,[],""],["palau_cantares-01432",4,"Ya se acabó aquel tiempo,\ntriste corazón,\nque esperabas la noche\npara ver el sol.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,165,165,"","",1,"","","",4,0,0,[],""],["palau_cantares-01433",4,"¡Cuándo querrán Dios del cielo\ny la Vigen del Pilar\nque tu ropita y la mía\nvayan juntas á lavar!",4,0,-1,70,"",0,4,"a",21,0,-1,0,165,165,"","",1,"","","",1,0,0,[],""],["palau_cantares-01434",4,"Cualesquiera que me vea\ndirá que no tengo pena,\ny tengo mi corazón\ncomo una bayeta negra.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,165,165,"","",1,"","","",1,0,0,[],""],["palau_cantares-01435a",4,"En medio de mis fatigas,\npor querer, quise dormirme;\nque el que vive como yo\ncuando duerme es cuando vive.",4,0,-1,70,"",0,4,"ie",-1,0,-1,0,166,166,"","",1,"","","",5,0,0,[],""],["palau_cantares-01435b",4,"Al pie del almendro estuve\ny no le cogí la flor,\ny así que me retiré,\notro llegó y la cogió.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,166,166,"","",1,"","","",1,0,0,[],""],["palau_cantares-01435c",4,"¡Ay soledad, soledad,\nsoledad en la cañada!\nLa mujer es la que pierde,\nque el hombre no pierde nada.",4,0,-1,70,"",0,4,"aa",49,0,-1,0,166,166,"","",1,"","","",18,0,0,[],""],["palau_cantares-01435d",4,"Si piensas que duermo, velo\ny me suelo despertar;\nsobre la cama me siento\ny te comienzo á llamar.",4,0,-1,70,"",0,4,"a",21,0,-1,0,166,166,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01435e",4,"Pájaro que vas volando\ny en el pico llevas hilo,\ndámelo para coser\nmi corazón, que está herido.",4,0,-1,70,"",0,4,"io",-1,0,-1,0,166,166,"","",1,"rm_t3, lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01435f",4,"Me dicen que soy hermosa;\nmas me retiro del mundo,\nque tengo mi corazón\ndentro del pecho difunto.",4,0,-1,70,"",0,4,"uo",-1,0,-1,0,166,166,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01435g",4,"Más quisiera que al principio\nme hubieras aborrecido,\nque no verme aprisionado\nde un bien que lloro perdido.",4,0,-1,70,"",0,4,"io",101,0,-1,0,166,166,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01435h",4,"Es un fuego de alquitrán\neste en que me estoy ardiendo,\nque más se aviva la llama\nmientras más lágrimas vierto.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,166,166,"","",1,"lafuente_madrid, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01436a",4,"Rosa me puso mi madre\npara ser más desgraciada,\nque no hay rosa en el rosal\nque no muera deshojada.",4,0,-1,70,"",0,4,"aa",49,0,-1,0,166,166,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01436b",4,"«Si no me quieres, me mato,»\ndicen unos ojos negros;\ny dicen unos azules:\n«Si no me quieres, me muero.»",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,166,166,"","",1,"","","",1,0,0,[],""],["palau_cantares-01436c",4,"Aguarda, caminante,\ndetén el paso,\ny enjuga de mis ojos\nel triste llanto:\nporque aquí yace\nla fúnebre esperanza\nde un triste amante.",4,0,-1,70,"",4,7,"ae",-1,0,-1,0,166,166,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01436d",4,"Corazón desdichado,\ntú no estás bueno,\nque suspiras, te agitas\ny tienes miedo:\nsé más constante,\nque el mal que estás sufriendo\nno es incurable.",4,0,-1,70,"",4,7,"ae",-1,0,-1,0,166,166,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01436e",4,"Porque quiero, bien mío,\nde amores muero,\nmas las ansias que sufro\nno es porque quiero:\nque entre mis penas,\nsi quisiera yo esto,\n¿qué más quisiera?",4,0,-1,70,"",4,7,"ea",-1,0,-1,0,166,166,"","",1,"","","",1,0,0,[],""],["palau_cantares-01436f",4,"¡Oh cruël, rigurosa\nfortuna mía!,\n¿cuándo de ser humana\nllegará el día?\n¿Cuándo tu rueda\nparará la inconstancia\nde su carrera?",4,0,-1,70,"",4,7,"ea",-1,0,-1,0,166,166,"","",1,"","","",1,0,0,[],""],["palau_cantares-01437",4,"¡Válgame Dios de los cielos,\nqué desgraciado nací!\nEn la pila del bautismo\nfaltó la sal para mí.",4,0,-1,70,"",0,4,"i",23,0,-1,0,166,166,"","",1,"","","",33,0,0,[],""],["palau_cantares-01438",4,"A la mar fuera y me echara,\npero ¿qué dirá la gente?\nQue vivo desesperado\ny ando buscando la muerte.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,166,166,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01439",4,"¡Válgame Dios de los cielos,\nqué grande es la pena mía!\nQue me he caído en un pozo\ny no encuentro la salida.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,166,166,"","",1,"lafuente_madrid, murciano_antiguo","","",33,0,0,[],""],["palau_cantares-01440",4,"El sueño tengo perdido\ny no sé dónde buscarlo;\nlo buscaré en el olvido...,\ny el olvido ¿dónde hallarlo?",4,0,-1,70,"",1,4,"ao",236,0,-1,0,166,166,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01441a",4,"Vámonos de aquí, que corre\nla mala fortuna nuestra:\nayer se cayó la torre,\nmañana caerá la iglesia.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,167,167,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01441b",4,"Tengo una pena conmigo\ny una congoja mortal:\nme encuentro con dos caminos,\nsin saber por cuál tomar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,167,167,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01441d",4,"De la raíz del querer\nsalió mi madre gitana;\ny yo, como soy su hijo,\nsalí de la misma rama.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,167,167,"","",1,"","","",1,0,0,[],""],["palau_cantares-01441f",4,"¡Qué amarillita que estás\ny qué llenita de ojeras!\nYo te volveré á querer,\nque no quiero que te mueras.",4,0,-1,70,"",0,4,"ea",103,0,-1,0,167,167,"","",1,"","","",1,0,0,[],""],["palau_cantares-01441g",4,"Del Padre Santo de Roma\nespero la excomunión,\nporque sabe que yo he dicho\nque te quiero más que á Dios.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,167,167,"","",1,"","","",1,0,0,[],""],["palau_cantares-01442c",4,"Cada día me parece\nque no puedo sufrir más,\ny cada día me trae\nun aumento de pesar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,167,167,"","",1,"","","",2,0,0,[],""],["palau_cantares-01442e",4,"¡Ay de mí, que triste estoy\ny triste siempre estaré!\n¡Yo nací para estar triste,\ny triste me moriré!",4,0,-1,70,"",0,4,"e",77,0,-1,0,167,167,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01442f",4,"Con el dolor que yo vivo\nes imposible vivir;\nsi el mundo no da otra vuelta,\ndará de mi vida fin.",4,0,-1,70,"",0,4,"i",-1,0,-1,0,167,167,"","",1,"rm_t3, lafuente_madrid, preciso_coleccion","","",5,0,0,[],""],["palau_cantares-01442g",4,"Siempre que miro al cangrejo,\nme pongo á considerar\nque se parece á mis dichas,\nque caminan hacia atrás.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,167,167,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01442h",4,"Dicen que tras la alegría\nsuele venir el dolor;\nyo conozco los dolores,\npero la alegría no.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,167,167,"","",1,"rm_t3, carrizo_salta, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01444",4,"De dolor y sentimiento\ndicen que no muere nadie.\nYo me tengo de morir\npor ver si se muere alguien.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,167,167,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01445",4,"¡Desgraciado el arbolito\nque solo en el campo nace!\nTodas las aves del mundo\ncontra sus ramas combaten.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,167,167,"","",1,"","","",3,0,0,[],""],["palau_cantares-01446",4,"Siempre que miro hacia el cielo\nlas lágrimas se me saltan:\nno sé de qué ni por qué...,\npero lloro con el alma.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,167,167,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01447",4,"Le dije al carrero,\ncon mucho dolor,\nque me la arropara la mi compañera\ncon un cobertor.",4,0,-1,70,"",3,4,"o",72,0,-1,0,167,167,"","",1,"","","",1,0,0,[],""],["palau_cantares-01448",4,"Todo el día estoy tranquilo,\ny en llegando la oración,\nuna piedra de molino\nparece mi corazón.",4,0,-1,70,"",0,4,"o",31,0,-1,0,167,167,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01449",4,"Voy á la fuente y bebo,\nno la aminoro,\nque aumenta su corriente\ncon lo que lloro.",4,0,-1,70,"",6,4,"oo",85,0,-1,0,168,168,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-01450",4,"La piedra, con ser la piedra,\nal golpe del eslabón\necha lágrimas de fuego:\n¡qué será mi corazón!",4,0,-1,70,"",0,4,"o",31,0,-1,0,168,168,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01451",4,"En un pozo muy profundo\nde penas estoy nadando,\ny yo solo me confundo\nde ver lo que estoy pasando.",4,0,-1,70,"",1,4,"ao",33,0,-1,0,168,168,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01452",4,"A un Santo Cristo de acero\nle hice yo que llorara;\ncuando de acero lloró,\n¿qué fuera de carne humana?",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,168,168,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01453",4,"Más valiera que mi madre,\nal punto que me parió,\nme hubiera dado la muerte,\ny no padeciera yo.",4,0,-1,70,"",0,4,"o",2,0,-1,0,168,168,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01453-e2",4,"Mil delicias amantes\nlogré algún tiempo,\ny ahora sólo pesares\nson los que tengo:\namor tirano,\nhazme otra vez presentes\ntiempos pasados.",4,0,-1,70,"",4,7,"ao",-1,0,-1,0,168,168,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01453-e3",4,"Cuando del bien no supe,\nviví contento;\nhoy que sé dónde mora,\npor él me muero;\ny en tal conflicto,\nvoluntad y memoria\nson mi cuchillo.",4,0,-1,70,"",4,7,"io",-1,0,-1,0,168,168,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01453-e4",4,"Amor, ya te conozco,\ndéjame quieta,\nque estoy desengañada\nde tus promesas:\nmarcha á otra parte,\nque acá ya conocemos\nlo que tú vales.",4,0,-1,70,"",4,7,"ae",-1,0,-1,0,168,168,"","",1,"","","",1,0,0,[],""],["palau_cantares-01453-e5",4,"Hoy se hacen las exequias\nde una esperanza\nque murió cuando menos\nella pensaba;\ny en este entierro\nsu mismo desengaño\nsirve de duelo.",4,0,-1,70,"",4,7,"eo",-1,0,-1,0,168,168,"","",1,"","","",2,0,0,[],""],["palau_cantares-01453-e6",4,"Aquel que tiene la culpa\nde que yo fatigas pase\nse vea en Argel cautivo\nsin tener ningún rescate.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,168,168,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01454",4,"¿A qué santo llamaré\npara aliviar esta pena\nque me ahoga la garganta\ncual si fuera una cadena?",4,0,-1,70,"",0,4,"ea",59,0,-1,0,168,168,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01454-e2",4,"Si las aves de Arabia\nviven eternas,\nviven porque no saben\nlo que son penas;\nque si penaran,\nya no habría en el mundo\naves de Arabia.",4,0,-1,70,"",4,7,"aa",-1,0,-1,0,168,168,"","",1,"","","",1,0,0,[],""],["palau_cantares-01454-e3",4,"Fueron mis esperanzas\nflores de almendro,\nque nacieron temprano,\nse helaron presto.",4,0,-1,70,"",6,4,"eo",-1,0,-1,0,168,168,"","",1,"","","",1,0,0,[],""],["palau_cantares-01454-e4",4,"Corazón, que tu alivio\npenando encuentras,\nsi en la pena descansas,\n¿de qué te quejas?",4,0,-1,70,"",6,4,"ea",-1,0,-1,0,168,168,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01454-e5",4,"Aunque me ves que canto,\ncanta la boca,\nque en mi corazón tengo\npena, y no poca.",4,0,-1,70,"",6,4,"oa",178,0,-1,0,168,168,"","",1,"","","",6,0,0,[],""],["palau_cantares-01454-e6",4,"¿Cómo quieres que tenga\ngusto y contento?\nTres días de casada,\nmi amante muerto.",4,0,-1,70,"",6,4,"eo",-1,0,-1,0,168,168,"","",1,"","","",14,0,0,[],""],["palau_cantares-01454-e7",4,"Penita sobre penita,\nsobre penita más pena:\nvengan, vengan sobre mí,\nque yo soy la madre de ellas.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,168,168,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01455",4,"Estoy tan hecho á la pena\nque me sirve de compaña,\nque el día que no la tengo\nme parece cosa extraña.",4,0,-1,70,"",0,4,"aa",213,0,-1,0,169,169,"","",1,"","","",5,0,0,[],""],["palau_cantares-01456",4,"No sé cómo no estoy loco\ncon esta pena que tengo,\nque me ha puesto tu querer\ntonto, sordo, mudo y ciego.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,169,169,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01457a",4,"Quien canta, su mal espanta,\ny aquel que llora lo aumenta:\nyo canto por divertir\nel dolor que me atormenta.",4,0,-1,70,"",0,4,"ea",229,0,-1,0,169,169,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01457b",4,"Triste estoy de verte triste:\nalégrate, vida mía;\nque algún día querrá Dios\nque tengamos alegría.",4,0,-1,70,"",0,4,"ia",0,0,-1,0,169,169,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01457c",4,"¡Ay de mí, que siendo niña,\nle dí palabra á un mancebo,\ny por temor á mi padre\ná cumplirla no me atrevo!",4,0,-1,70,"",0,4,"eo",240,0,-1,0,169,169,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01457d",4,"Empecemos, corazón,\ná padecer y penar,\npues adoro un imposible\nque no he de poder lograr.",4,0,-1,70,"",0,4,"a",21,0,-1,0,169,169,"","",1,"rm_t3, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01457e",4,"Un imposible me mata,\npor un imposible muero;\nimposible es alcanzar\nel imposible que quiero.",4,0,-1,70,"",0,4,"eo",38,0,-1,0,169,169,"","",1,"rm_t2, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01457f",4,"Compañerita del alma,\n¡qué penas que pasa aquel\nque tiene el agua en los labios\ny no la puede beber!",4,0,-1,70,"",0,4,"e",-1,0,-1,0,169,169,"","",1,"lafuente_madrid","","",20,0,0,[],""],["palau_cantares-01457g",4,"Soy pájaro que en el agua\ntengo el alimento mío;\nme estoy muriendo de sed,\nsiendo del agua nacido.",4,0,-1,70,"",0,4,"io",-1,0,-1,0,169,169,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01457h",4,"Dentro de mi pecho tengo\nuna penilla mortal,\nporque quiero á una rubita\ny no me la quieren dar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,169,169,"","",1,"","","",32,0,0,[],""],["palau_cantares-01458",4,"Aunque tengo mal color,\nno te pienses cosa mala;\nson penas del corazón,\nque me salen á la cara.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,169,169,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01459a",4,"No sé qué tienen las flores\nque están en el campo santo,\nque cuando las mueve el viento\nparece que están llorando.",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,169,169,"","",1,"","","",3,0,0,[],""],["palau_cantares-01459b",4,"¿Nohayquien me ayude á unapena\npagándole su jornal?\nComo mi pena es tan grande,\nnadie me quiere ayudar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,169,169,"","",1,"","","",1,0,0,[],""],["palau_cantares-01459c",4,"¿Qué saco yo de quererte,\nni vivir por ti penando,\nsi tú no puedes ser mía\ncomo Dios no haga un milagro?",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,169,169,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01460",4,"¿Qué importa que tú me quieras\ny que yo te quiera á ti,\nsi lo que yo solicito\nno lo puedo conseguir?",4,0,-1,70,"",0,4,"i",-1,0,-1,0,170,170,"","",1,"rm_t3, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01461",4,"A mi triste corazón\nlas fatiguillas le ahogan,\ny no tiene más descanso\nque el rato que por ti llora.",4,0,-1,70,"",0,4,"oa",-1,0,-1,0,170,170,"","",1,"","","",2,0,0,[],""],["palau_cantares-01462",4,"Deja de cantar, jilguero,\nque me estás atormentando;\nque es mucha pena en un triste\noir cantar y estar llorando.",4,0,-1,70,"",0,4,"ao",33,0,-1,0,170,170,"","",1,"","","",1,0,0,[],""],["palau_cantares-01463",4,"Cualesquiera que me mire,\ndirá que no tengo penas:\npor Jesús de los Milagros,\nque ya no puedo con ellas.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,170,170,"","",1,"","","",1,0,0,[],""],["palau_cantares-01464",4,"Estoy pasando más penas\npor tu cara morenita,\nque pasó aquel ermitaño\nque se le quemó la ermita.",4,0,-1,70,"",0,4,"ia",50,0,-1,0,170,170,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01465",4,"Todo el día estoy tranquilo,\ny en llegando á la oración,\nuna piedra de molino\nparece mi corazón.",4,0,-1,70,"",0,4,"o",31,0,-1,0,170,170,"","",1,"","","",3,0,0,[],""],["palau_cantares-01467",4,"Aquel que tenga penillas\nvenga á ajuntarse conmigo,\ná ver si llorando sangre\ntenemos algún alivio.",4,0,-1,70,"",0,4,"io",-1,0,-1,0,170,170,"","",1,"","","",1,0,0,[],""],["palau_cantares-01468",4,"Los ojillos de mi cara\nse han secado de llorar,\nporque el hombre que ellos quieren\nles ha pagado muy mal.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,170,170,"","",1,"","","",1,0,0,[],""],["palau_cantares-01469",4,"Cuando paso por tu puerta\ny no me dices «adiós,»\nni las ánimas benditas\npasan las penas que yo.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,170,170,"","",1,"","","",17,0,0,[],""],["palau_cantares-01470",4,"¿De qué te sirve llorar\nsi no tienes quién te oiga,\nsi el que te pudiera oir\nestá gozando la gloria?",4,0,-1,70,"",0,4,"oa",-1,0,-1,0,170,170,"","",1,"","","",6,0,0,[],""],["palau_cantares-01471",4,"Por dondequiera que voy,\nparece que te estoy viendo;\nson las sombras del querer,\nque me vienen persiguiendo.",4,0,-1,70,"",0,4,"eo",52,0,-1,0,170,170,"","",1,"","","",3,0,0,[],""],["palau_cantares-01473",4,"Alegría cuando vienes,\ntristeza cuando te vas,\nsiempre está mi corazón\nen un continuo penar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,170,170,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01474",4,"A aquella torre más alta\nme tengo de ir á llorar,\nporque escuche mis tormentos\naquel que en el cielo está.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,170,170,"","",1,"","","",1,0,0,[],""],["palau_cantares-01475",4,"Quien cante teniendo penas\ncomo las que tengo yo,\nbien es menester que tenga\ncerdas en el corazón.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,170,170,"","",1,"","","",1,0,0,[],""],["palau_cantares-01476",4,"Todo aquel que dice ¡ay!\nes seña que le ha dolido:\n¡ay!, ¡ay!, ¡cuántos ayes da\nel corazoncito mío!",4,0,-1,70,"",0,4,"io",-1,0,-1,0,170,170,"","",1,"","","",2,0,0,[],""],["palau_cantares-01477",4,"Tengo yo una queja\nde los altos cielos,\ncomo sin frío ni calenturita\nyo me estoy muriendo.",4,0,-1,70,"",3,4,"eo",-1,0,-1,0,170,170,"","",1,"","","",1,0,0,[],""],["palau_cantares-01478",4,"Tengo una pena, una pena,\nque si esta pena me dura,\nya me pueden disponer\nla caja y la sepultura.",4,0,-1,70,"",0,4,"ua",17,0,-1,0,170,170,"","",1,"","","",4,0,0,[],""],["palau_cantares-01479",4,"Tengo una pena, una pena,\nque casi puedo decir\nque yo no tengo la pena;\nla pena me tiene á mí.",4,0,-1,70,"",0,4,"i",-1,0,-1,0,170,170,"","",1,"","","",4,0,0,[],""],["palau_cantares-01480",4,"Sin querer pisé una flor\nque en su sepultura estaba,\ny de la flor salió un ¡ay!\nque se me clavó en el alma.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,171,171,"","",1,"","","",1,0,0,[],""],["palau_cantares-01481",4,"¡Ay de mí, que me han quitado\nuna rosa, siendo mía,\ny la veo en otras manos\nmarchita y descolorida!",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,171,171,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01482",4,"Estoy pasando por ti\nmás penas y más trabajos\nque pasó Aquel que está arriba\nel tiempo que estuvo abajo.",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,171,171,"","",1,"","","",3,0,0,[],""],["palau_cantares-01483",4,"Nacimos para querernos,\ncon mala estrella nacimos;\nni tú puedes olvidarme,\nni yo olvidarte consigo.",4,0,-1,70,"",0,4,"io",-1,0,-1,0,171,171,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01484",4,"Con mirar aquel sauce\nque está en el río,\ncomprenderás la pena\ndel pecho mío:\npues aquel sauce\nestá cerca y no goza\nde sus cristales.",4,0,-1,70,"",4,7,"ae",-1,0,-1,0,171,171,"","",1,"rm_t2","","",2,0,0,[],""],["palau_cantares-01484-e2",4,"¡Mal haya la ropa negra\ny el sastre que la cortó,\nque está mi niña de luto\nsin haberme muerto yo!",4,0,-1,70,"",0,4,"o",2,0,-1,0,171,171,"","",1,"rm_t3","","",5,0,0,[],""],["palau_cantares-01485a",4,"Quisiera verte y no verte,\nquisiera hablarte y no hablarte,\nquisiera no conocerte,\npara poder olvidarte.",4,0,-1,70,"",1,4,"ae",8,0,-1,0,171,171,"","",1,"rm_t3, carrizo_salta, lafuente_madrid","","",12,0,0,[],""],["palau_cantares-01485b",4,"Más quisiera haberme muerto\nque no haberte conocido,\ny no reinara la pena\nque está reinando conmigo.",4,0,-1,70,"",0,4,"io",-1,0,-1,0,171,171,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01485c",4,"Más valiera que mis ojos\nnunca te hubieran mirado,\ny con eso no viviera\nen sino tan desgraciado.",4,0,-1,70,"",0,4,"ao",14,0,-1,0,171,171,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01486",4,"Dicen que en tu sepultura\nha nacido un pensamiento;\nlo sembró mi desventura,\nnació con mi sentimiento\ny crece con mi amargura.",4,0,-1,70,"",7,5,"ua",17,0,-1,0,171,171,"","",1,"","","",1,0,0,[],""],["palau_cantares-01487",4,"¡Más quisiera haber nacido\nárbol silvestre en el campo,\nque no haberte conocido\npara sentir ahora tanto!",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,171,171,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01488",4,"Yo no sé por dónde\nni por dónde no,\nse me ha liado una soga al cuerpo\nsin saberlo yo.",4,0,-1,70,"",0,4,"o",2,0,-1,0,171,171,"","",1,"","","",1,0,0,[],""],["palau_cantares-01489",4,"No me digas que te olvide,\nque me lo dices llorando;\ntoma tú misma el consejo\ny podrás venir á darlo.",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,171,171,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01491",4,"Lo que me da más gusto\nme da más pena,\nde tormento me sirve\nlo que me alegra.",4,0,-1,70,"",6,4,"ea",-1,0,-1,0,171,171,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01492",4,"He estado en el Purgatorio\ny he visto lo que son penas,\ny sé que por querer bien\nningún alma se condena.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,171,171,"","",1,"","","",5,0,0,[],""],["palau_cantares-01493",4,"¿Quién ha visto en el mundo\nquerer un ciego\nla causa de su daño\npara remedio?",4,0,-1,70,"",6,4,"eo",-1,0,-1,0,171,171,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01494",4,"Navegaba viento en popa\nla nave de mi esperanza,\npero trocándose el aire,\ncon el desaire naufraga.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,171,171,"","",1,"","","",2,0,0,[],""],["palau_cantares-01495",4,"Por causa de malas lenguas\nque hablan lo que no es,\ntengo mi fama perdida:\n¡cuándo la recobraré!",4,0,-1,70,"",0,4,"e",-1,0,-1,0,171,171,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01496",4,"¡Puñaladas en mi puerta!\n¡Cielos!, ¡qué sucede aquí!\nDos hombres se están matando:\n¿madre, si será por mí?",4,0,-1,70,"",0,4,"i",23,0,-1,0,172,172,"","",1,"","","",4,0,0,[],""],["palau_cantares-01497",4,"De pura bayeta negra\nmi cuerpo se ha de vestir;\nque este es el propio vestido\nde aquel que sabe sentir.",4,0,-1,70,"",0,4,"i",157,0,-1,0,172,172,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01498",4,"El corazón dió un suspiro\ny el alma le dijo: - Cesa;\nno suspires, corazón,\nque nadie de ti se acuerda.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,172,172,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01499",4,"Soy el herido sin sangre,\nsoy el muerto sin acero,\nsoy el que penando vivo,\nsoy el que penando muero.",4,0,-1,70,"",0,4,"eo",38,0,-1,0,172,172,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01500",4,"¿Qué me importa que florezca\nel árbol de mi esperanza,\nsi se marchitan las flores\ny jamás el fruto cuaja?",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,172,172,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01501",4,"Tengo el corazón más duro\nque las piedras de la calle,\ny son tan grandes mis penas,\nque llora gotas de sangre.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,172,172,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01502",4,"¡En qué confusión me hallo,\ntriste, sin saber qué hacer!\nAborrecerlo..., no puedo;\namarlo..., no puede ser.",4,0,-1,70,"",0,4,"e",20,0,-1,0,172,172,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01503",4,"En lo profundo del mar\nvoy á sepultar mi pena,\nporque mi pena es tan grande\nque ya no cabe en la tierra.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,172,172,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01504",4,"Ya mi mal no tiene cura\ncomo del cielo no venga,\nque me ha puesto tu querer\nque me va á tragar la tierra.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,172,172,"","",1,"","","",2,0,0,[],""],["palau_cantares-01505",4,"Lágrimas pedí á una fuente\npara llorar mi tormento,\nporque es tan grande mi pena,\nque ya ni lágrimas tengo.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,172,172,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01506",4,"¿De qué sirve que yo quiera\ndisimular mi dolor,\nsi en los ojos y en la cara\nllevo escrita la pasión?",4,0,-1,70,"",0,4,"o",-1,0,-1,0,172,172,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01507",4,"Suspirando descansa\ncierto afligido,\ny el descanso le dura\nlo que el suspiro.",4,0,-1,70,"",6,4,"io",-1,0,-1,0,172,172,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01508",4,"Yo pensé que el querer bien\nera cosa de juguete;\ny se pasa pena negra\nqueriéndose firmemente.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,172,172,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01509",4,"Ya se siente mi pecho\ntan oprimido,\nque le falta el aliento\npara el suspiro.",4,0,-1,70,"",6,4,"io",-1,0,-1,0,172,172,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01510",4,"Yo pensé que un querer bien\nera fácil de olvidar;\ny es callejón tan estrecho\nque el que entra no sale más.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,172,172,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01511",4,"Dando tristes suspiros\nde sentimiento,\nanegada en mi llanto\nvivo muriendo.",4,0,-1,70,"",6,4,"eo",-1,0,-1,0,172,172,"","",1,"","","",2,0,0,[],""],["palau_cantares-01512",4,"Santa Teresa en la cueva\nde cilicios se vistió;\ny yo tengo que vestirme\nde los cilicios de amor.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,172,172,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01513",4,"Corazón, no suspires;\nalma, no sientas;\nmemoria, no te acuerdes\nde quien te acuerdas.",4,0,-1,70,"",6,4,"ea",-1,0,-1,0,172,172,"","",1,"fernan_caballero","","",4,0,0,[],""],["palau_cantares-01514",4,"Las penas que por ti paso\nno se pueden numerar;\ndame veneno en un vaso\ny acábame de matar.",4,0,-1,70,"",1,4,"a",21,0,-1,0,172,172,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01515",4,"Dicen que sueño es muerte,\nmas yo lo niego,\npues cuando duermo, vivo;\ncuando no, muero.",4,0,-1,70,"",6,4,"eo",-1,0,-1,0,172,172,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01516",4,"El corazón de mi amante\nlo van á sacramentar,\ny el mío se está muriendo\nde la misma enfermedad.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,173,173,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01517",4,"¡Cuántas y cuántas veces\nmi pensamiento\nsale á buscar alivio\ny halla tormento!",4,0,-1,70,"",6,4,"eo",94,0,-1,0,173,173,"","",1,"","","",2,0,0,[],""],["palau_cantares-01518",4,"El cenador de mi huerto\nlleno está de mustias flores:\nvenid, muchachas, y ved\nla imagen de mis amores.",4,0,-1,70,"",0,4,"oe",5,0,-1,0,173,173,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01519",4,"Si las penas mataran,\nya no existiera,\ny así vivo diciendo:\n- Me matan penas.",4,0,-1,70,"",6,4,"ea",-1,0,-1,0,173,173,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01520",4,"Yo soy una triste losa,\ntestigo de todo luto;\ntú serás juez de mi causa\ny de mi muerte verdugo.",4,0,-1,70,"",0,4,"uo",-1,0,-1,0,173,173,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01521",4,"¡Cómo quieres que el Guadiela\nen el invierno se seque!\n¡Cómo quieres que yo olvide\ná quien he querido siempre!",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,173,173,"","",1,"","","",1,0,0,[],""],["palau_cantares-01522",4,"Ya mi muerte decretada\nte dije con sentimiento;\nla súplica es excusada,\nporque me muero contento.",4,0,-1,70,"",1,4,"eo",94,0,-1,0,173,173,"","",1,"","","",2,0,0,[],""],["palau_cantares-01523",4,"Tuviste la mala sangre\nde llevarme al hospital:\nsi muero sin que te vea,\nun divé te cobrará.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,173,173,"","",1,"","","",1,0,0,[],""],["palau_cantares-01524",4,"Gitana, si oyes doblar,\nno preguntes quién ha muerto,\nque ha sido mi corazón\nde penilla y sentimiento.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,173,173,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01525",4,"Triste el corazón se queja\ny yo le pregunto triste:\n«Corazón, ¿por qué te has muerto?,»\ny él responde: «Porque quise.»",4,0,-1,70,"",0,4,"ie",-1,0,-1,0,173,173,"","",1,"rm_t3, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01526",4,"Dile al sacristán que doble\ny ponga negras cortinas,\nporque ya murió aquel hombre\nque rondaba tus esquinas.",4,0,-1,70,"",0,4,"ia",243,0,-1,0,173,173,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01527",4,"Una soledad deseo\npara aliviar mis fatigas,\ny allí regarán mis ojos\nplantas y flores marchitas.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,173,173,"","",1,"","","",3,0,0,[],""],["palau_cantares-01528",4,"Despierta y oirás el tiro,\nporque me van á matar;\nsiéntate luego en la cama\ny comiénzame á llorar.",4,0,-1,70,"",0,4,"a",21,0,-1,0,173,173,"","",1,"","","",1,0,0,[],""],["palau_cantares-01529",4,"Si quieres cambiar, cambiemos\ncorazones á llorar:\ndame el tuyo y toma el mío,\nveremos quién llora más.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,173,173,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01530",4,"¡Válgame San Sebastián,\npatrón de Villamartín!\nTodas las penas se acaban,\nla mía no tiene fin.",4,0,-1,70,"",0,4,"i",211,0,-1,0,173,173,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01531",4,"Anda, ve á Santa María\ny encomiéndate á un divé,\nque el que no pasa fatigas\nno sabe lo que es querer.",4,0,-1,70,"",0,4,"e",-1,0,-1,0,173,173,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01532",4,"Angustia, pena, pesar,\nun terrible sentimiento\nen mí reina sin parar,\ny ya me falta el aliento.",4,0,-1,70,"",1,4,"eo",94,0,-1,0,173,173,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01533",4,"Desde que paso tu calle\nenamorado de ti,\nestán llorando las piedras\nde verme llorar á mí.",4,0,-1,70,"",0,4,"i",23,0,-1,0,173,173,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01534",4,"Mi pensamiento al humo\nse le parece,\nporque al paso que sube\nse desvanece.",4,0,-1,70,"",6,4,"ee",64,0,-1,0,173,173,"","",1,"preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01535",4,"¡Desgraciado labrador\nque siembra y no coge trigo!\nMás desgraciado soy yo,\nque no puedo hablar contigo.",4,0,-1,70,"",0,4,"io",106,0,-1,0,173,173,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01536",4,"Tengo pasadas más penas\ndesde que te conocí,\nque pasó la Magdalena\ncuando se fué á convertir.",4,0,-1,70,"",0,4,"i",-1,0,-1,0,174,174,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01537",4,"Ya te he dicho, compañera,\nno me vengas á buscar;\ndéjame solo en mi casa\ncon mi bien ó con mi mal.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,174,174,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01538",4,"Este vivir no es vivir:\n¡verte y no poderte hablar!,\nesto, mi bien, es morir:\n¿para qué tanto penar?",4,0,-1,70,"",1,4,"a",21,0,-1,0,174,174,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01539",4,"Un corazón de madera\ntengo que mandar hacer,\nque ni sienta, ni padezca,\nni sepa lo que es querer.",4,0,-1,70,"",0,4,"e",20,0,-1,0,174,174,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01540",4,"¡Válgame Dios de los cielos,\nqué desgraciado he nacido:\npara todos sale el sol.\ny para mí no ha salido!",4,0,-1,70,"",0,4,"io",101,0,-1,0,174,174,"","",1,"rm_t3, lafuente_madrid","","",33,0,0,[],""],["palau_cantares-01541",4,"Tú penar y yo penar,\ntodo es penar, vida mía;\nlas penas se acabarán\ny tendremos alegría.",4,0,-1,70,"",0,4,"ia",0,0,-1,0,174,174,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01542",4,"De chiquita ya lloraba\ny de grande también lloro:\ncuando chiquita por teta,\ny ahora por el bien que adoro.",4,0,-1,70,"",3,4,"oo",85,0,-1,0,174,174,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01543",4,"Tengo una pena, una pena,\ntengo un dolor, un dolor,\ntengo un clavo remachado\nen mitad del corazón.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,174,174,"","",1,"","","",4,0,0,[],""],["palau_cantares-01544",4,"Retírate al campo y llora,\nque bien tienes que llorar;\nque eres muy niña y no sabes\nquién te quiere bien ó mal.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,174,174,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01545",4,"Más agua lloran mis ojos,\nque derrama una tormenta;\nlos suspiros no los digo\nporque he perdido la cuenta.",4,0,-1,70,"",0,4,"ea",229,0,-1,0,174,174,"","",1,"carrizo_salta","","",2,0,0,[],""],["palau_cantares-01546",4,"Sola soy, sola nací,\nsola me parió mi madre,\nsola tengo de morir,\n¡la Soledad me acompañe!",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,174,174,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01547",4,"Soñé que contigo estaba\nen la iglesia ante un altar,\ny el cura nos bendecía:\n¡esto sí que fué soñar!",4,0,-1,70,"",0,4,"a",21,0,-1,0,174,174,"","",1,"","","",1,0,0,[],""],["palau_cantares-01548",4,"Soy una pobre doncella\nque no me meto con nadie,\ny por una mala lengua\ntengo mi honor en el aire.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,174,174,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01549",4,"Ya has logrado, fortuna,\ntodo tu anhelo,\nabatiendo mis dichas\ndel cielo al suelo.",4,0,-1,70,"",6,4,"eo",10,0,-1,0,174,174,"","",1,"","","",2,0,0,[],""],["palau_cantares-01551",4,"A tal extremo he llegado,\nque estimo que me aborrezcas\npor ver si mi amor consigue\nsatisfacerse de penas.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,174,174,"","",1,"","","",1,0,0,[],""],["palau_cantares-01552",4,"La pena y la que no es pena,\ntodo es pena para mí:\nayer penaba por verte,\nhoy peno porque te vi.",4,0,-1,70,"",0,4,"i",23,0,-1,0,174,174,"","",1,"lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01553",4,"Tus lágrimas me aseguran,\ntus regalos me entretienen,\ntus favores me confían\ny tus celos me enloquecen.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,174,174,"","",1,"","","",1,0,0,[],""],["palau_cantares-01554",4,"Compañerita del alma,\n¿qué quieres que yo te diga?\nQue con penillas me acuesto,\nme levanto con penillas.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,174,174,"","",1,"rm_t3, lafuente_madrid","","",20,0,0,[],""],["palau_cantares-01555",4,"Engañado el pensamiento,\nmiento por ver si consigo:\nsigo aplicando remedios,\nmedios no los facilito.",4,0,-1,70,"",0,4,"io",-1,0,-1,0,174,174,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01556",4,"Por la Carmelita hermosa,\nque no me des qué sentir;\nque tu querer será causa\nde dar á mi cuerpo fin.",4,0,-1,70,"",0,4,"i",-1,0,-1,0,177,177,"","",1,"","","",2,0,0,[],""],["palau_cantares-01557",4,"A aquel que tiene fatigas\nse le conoce en la cara:\ná mí me están ahogando\ny no me conoces nada.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,177,177,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01558",4,"Niña mía, no más penas,\nmira que no soy de bronce;\nque una piedra se quebranta\ná fuerza de darle golpes.",4,0,-1,70,"",0,4,"oe",-1,0,-1,0,177,177,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01559",4,"En medio de mis fatigas\nel morirme estoy sintiendo\npor no dejar en el mundo\npersona que estoy queriendo.",4,0,-1,70,"",0,4,"eo",52,0,-1,0,177,177,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01560",4,"¿Hasta cuándo, vida mía,\ntengo de vivir penando?\nLas horitas de la noche\nme las paso suspirando.",4,0,-1,70,"",0,4,"ao",33,0,-1,0,177,177,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-01561",4,"Ya para mí las glorias\nen este mundo\nse volvieron pavesa,\nceniza y humo:\nsiendo tan cierto,\nque aumenta más mis penas\nel pensamiento.",4,0,-1,70,"",4,7,"eo",-1,0,-1,0,177,177,"","",1,"","","",2,0,0,[],""],["palau_cantares-01562a",4,"¿Dónde estás, prenda querida,\ncielo de mis pensamientos,\nen dónde estás, que no escuchas\nmis suspiros y lamentos?",4,0,-1,70,"",0,4,"eo",234,0,-1,0,177,177,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01562b",4,"Entre la hostia y el cáliz\ná mi Dios se lo pedí,\nque no te maten las penas\nque me están matando á mí.",4,0,-1,70,"",0,4,"i",23,0,-1,0,177,177,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01562c",4,"Si lágrimas fueran piedras,\nlas que por ti he derramado,\nun fuerte castillo hiciera\nen medio del mar salado.",4,0,-1,70,"",0,4,"ao",14,0,-1,0,177,177,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01562d",4,"Compañera de mi vida,\nya no me conocerás,\nque acaba más una pena\nque una larga enfermedad.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,177,177,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01563",4,"Tengo yo un cofre lleno\nde penas y ansias,\nde ocasiones perdidas,\ntiempo y palabras:\nque la fortuna\ntan sólo me enriquece\nde desventuras.",4,0,-1,70,"",4,7,"ua",-1,0,-1,0,177,177,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01563-e2",4,"La calle está regada:\ndicen que han sido\nlágrimas de un amante\nque han despedido;\ny él se consuela\ncon mirar las ventanas\nde su morena.",4,0,-1,70,"",4,7,"ea",-1,0,-1,0,177,177,"","",1,"","","",3,0,0,[],""],["palau_cantares-01564",4,"¡Oh mal haya, mal haya\nmi cobardía;\nque por ser yo cobarde\nno eres tú mía!",4,0,-1,70,"",6,4,"ia",0,0,-1,0,177,177,"","",1,"","","",1,0,0,[],""],["palau_cantares-01565",4,"Yo me enamoré, pensando\nque el amor era ligero:\nno vi carga más pesada\nni que más me quite el sueño.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,177,177,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01566",4,"No me mates, no me mates,\ndéjame que viva, viva;\ndéjame que pase, pase,\nen este mundo fatigas.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,177,177,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01567",4,"Yo me metí en el querer,\nmuchachito criatura;\ncuando vine á abrir los ojos\nme encontré en la sepultura.",4,0,-1,70,"",0,4,"ua",17,0,-1,0,177,177,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01568",4,"En tu maceta sembré\nla semilla del encanto:\ncon lágrimas la regué:\n¡mal haya quien quiere tanto!",4,0,-1,70,"",1,4,"ao",30,0,-1,0,177,177,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01569",4,"Mal haya el amor, mal haya,\ny quien me lo dió á entender;\nque habiendo nacido libre,\nyo mismo me cautivé.",4,0,-1,70,"",0,4,"e",-1,0,-1,0,177,177,"","",1,"rm_t3, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01570",4,"A mi corazón prendieron\ny á la cárcel lo llevaron,\ny sin delito ninguno\ná muerte lo sentenciaron.",4,0,-1,70,"",0,4,"ao",41,0,-1,0,178,178,"","",1,"","","",2,0,0,[],""],["palau_cantares-01571",4,"¡Virgen del Carmen, valedme,\nque yo me muero de pena;\nque perdí las esperanzas,\ncomo aquel que se condena!",4,0,-1,70,"",0,4,"ea",59,0,-1,0,178,178,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01572",4,"Corazón, ¿dónde me llevas\nque no te puedo seguir?\n¡Ten cuidado no te metas\ndonde no puedas salir!",4,0,-1,70,"",0,4,"i",157,0,-1,0,178,178,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01573",4,"Doblen, doblen las campanas\ny que toquen á silencio;\nvistan las flores de luto,\nque mi corazón ha muerto.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,178,178,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01574",4,"Mi corazón dió un suspiro,\ny el alma le preguntó:\n- Corazón, ¿por qué suspiras?\n- Alma, porque tengo amor.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,178,178,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01575",4,"La alegría en mí no reina,\nmuerto tengo el corazón:\n¡Madre mía del Amparo,\nvaledme en esta ocasión!",4,0,-1,70,"",0,4,"o",31,0,-1,0,178,178,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01576",4,"«¡Válgame Dios del cielo,\ndijo una niña,\nlo que descansa un alma\ncuando suspira!»",4,0,-1,70,"",6,4,"ia",-1,0,-1,0,178,178,"","",1,"rm_t3, murciano_antiguo","","",8,0,0,[],""],["palau_cantares-01577",4,"Si no fuera por las gentes,\nme vestiría de luto,\nporque tengo el corazón\ndentro del pecho difunto.",4,0,-1,70,"",0,4,"uo",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01578",4,"¡Válgame Dios de los cielos,\nqué penoso que es mi mal!\nSuspirando tengo alivio,\n¡y no puedo suspirar!",4,0,-1,70,"",0,4,"a",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",33,0,0,[],""],["palau_cantares-01579",4,"A orillas del mar me siento\ná recorrer mi memoria,\ny al acordarme de ti\nsangre mis ojitos lloran.",4,0,-1,70,"",0,4,"oa",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01580",4,"¿Cómo quieres que yo salga\nal campo de la alegría,\nsi se marchitan las flores\nal ver esta pena mía?",4,0,-1,70,"",0,4,"ia",0,0,-1,0,178,178,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01581",4,"De pena y de sentimiento\nno me trato con las gentes,\nen los rincones me meto\ny á voces llamo á la muerte.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01582",4,"¡Oh cristalina corriente,\nque vas á buscar tu centro!,\nllévate á un hombre infeliz\nque vive, pero muriendo.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01583",4,"Yo no sé lo que me pasa,\nni tampoco lo que quiero:\ndigo y no sé lo que digo,\nsiento y no sé lo que siento.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,178,178,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01584",4,"De llorar me quedé ciego\ncuando supe que era muerta:\n¡de qué me sirven los ojos\nsi no he de volver á verla!",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01585",4,"¿Qué importa que mis amigos\nme saquen á divertir,\nsi en volviendo yo á mi casa\nvuelvo de nuevo á sentir?",4,0,-1,70,"",0,4,"i",157,0,-1,0,178,178,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01586",4,"¡Anda con Dios, fortunilla,\nque por fin me la pegastes!\n¡A la mejor ocasión\nte fuistes y me dejastes!",4,0,-1,70,"",0,4,"ae",142,0,-1,0,178,178,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01587",4,"El día paso con pena\ny la noche con dolor;\nsuspirando me anochece,\nllorando me sale el sol.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01588",4,"Ya no vivo yo con gusto,\nya mi suerte se trocó;\nquien perdió lo que bien quiso,\ncuanto hay que perder perdió.",4,0,-1,70,"",0,4,"o",2,0,-1,0,178,178,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01589",4,"La soledad me acompaña,\nla música me entristece,\naborreciendo la vida,\napeteciendo la muerte.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,178,178,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01590",4,"Todas las penas del mundo\nno igualan con esta mía,\nque se me pasa llorando\ntoda la flor de mi vida.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,179,179,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01591",4,"Se acabará mi querer,\nse acabará mi llorar,\nse acabará mi tormento,\ny todo se acabará.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,179,179,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01592",4,"Las penas que estoy sufriendo\nme están tirando á ahogar,\nlas unas sobre las otras,\ncomo las olas del mar.",4,0,-1,70,"",0,4,"a",21,0,-1,0,179,179,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01593",4,"Me han dicho que estás malita\ny que te sangran mañana:\ná ti te sangran del pie\ny á mí me sangran del alma.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,179,179,"","",1,"rm_t3, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["palau_cantares-01594",4,"A aquel pajarito, madre,\nque canta en el limón verde,\nsu tiempo le ha de llegar,\nque él esté triste y yo alegre.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,179,179,"","",1,"","","",3,0,0,[],""],["palau_cantares-01595",4,"¿Quién ha sido el cirujano\nque te ha mandado sangrar?\n¿Siendo tú un ángel humano,\nqué sangre tienes de dar?",4,0,-1,70,"",1,4,"a",21,0,-1,0,179,179,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01596",4,"Yo me arrimé á un pino verde\npor ver si me consolaba,\ny el pino, como era verde,\nde verme llorar lloraba.",4,0,-1,70,"",1,4,"aa",28,0,-1,0,179,179,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01597",4,"En el carro de los muertos\nha pasado por aquí;\nllevaba la mano fuera...,\n¡por eso la conocí!",4,0,-1,70,"",0,4,"i",23,0,-1,0,179,179,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01598",4,"¿No hay quién me pegue un tirillo\nque me parta el corazón?\nQue estoy viviendo en el mundo\ncon muchísimo dolor.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,179,179,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01599",4,"Los pajarillos y yo\nnos levantamos á un tiempo,\nellos á cantar al alba,\nyo á llorar mi sentimiento.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,179,179,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01600",4,"Acaba, penita, acaba,\ndame muerte de una vez;\nque con la muerte se acaba\nla pena y el padecer.",4,0,-1,70,"",0,4,"e",-1,0,-1,0,179,179,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01601",4,"¿Qué importa que la calandria,\nel ruiseñor y el jilguero\ncanten para divertirme,\nsi en mí no cabe consuelo?",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,179,179,"","",1,"","","",3,0,0,[],""],["palau_cantares-01602",4,"Horitas tengo en el día\nde sentimiento y de pena;\nsi me viniera la muerte,\npor Dios que no lo sintiera.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,179,179,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01603",4,"Ni la tortolilla triste,\nni el canario más sonoro,\nni la fuente cristalina\nllorarán como yo lloro.",4,0,-1,70,"",0,4,"oo",85,0,-1,0,179,179,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01604",4,"¡Cuántas personillas grandes\nviene la muerte y se lleva,\ny á mí no quiere llevarme,\nque se lo pido de veras!",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,179,179,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01605",4,"Calla, ruiseñor, no cantes,\nacompaña mi dolor:\nque no es razón que tú cantes,\nestando tan triste yo.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,179,179,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01606",4,"Nadie se acerque á mi cama,\nque estoy malito de pena,\ny á quien muere de este mal\nhasta la ropa le quema.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,179,179,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01607",4,"Yo pensé que con el tiempo\nmis penas se acabarían,\ny se me van aumentando\ncomo las horas del día.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,179,179,"","",1,"rm_t3, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01608",4,"No te aflijas, corazón,\ny cese ya tu quebranto,\nque vendrá un tiempo mejor\ny se acabará tu llanto.",4,0,-1,70,"",0,4,"ao",30,0,-1,0,179,179,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01609",4,"En la soledad del campo\nme puse á llorar mis penas,\ny fué tan grande mi llanto,\nque florecieron las hierbas.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,179,179,"","",1,"","","",5,0,0,[],""],["palau_cantares-01610",4,"A una piedra de la calle\nle contaba mi dolor;\n¡mira lo que le diría,\nque la piedra se partió!",4,0,-1,70,"",0,4,"o",-1,0,-1,0,180,180,"","",1,"lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-01611",4,"A llorar mi triste suerte\nen la cama me senté,\nconsiderando tan lejos\nlo que tan cerca soñé.",4,0,-1,70,"",0,4,"e",77,0,-1,0,180,180,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01612",4,"Me puse á llorar mis penas\nen un monte de espesura,\ny se secaron las ramas,\nquedando las raíces puras.",4,0,-1,70,"",0,4,"ua",-1,0,-1,0,180,180,"","",1,"","","",3,0,0,[],""],["palau_cantares-01613",4,"Yo subí como la hiedra\nhasta el último elemento,\ny luego volví á bajar\ncomo la piedra á su centro.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,180,180,"","",1,"","","",1,0,0,[],""],["palau_cantares-01614",4,"Ayer tarde fui al campo\ná llorar por mi sentir,\ny á un árbol que me escuchaba\nse le secó la raíz.",4,0,-1,70,"",0,4,"i",-1,0,-1,0,180,180,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01615",4,"Tengo un vestido de penas\ncon mangas de sentimiento,\ny los faralares son\npenillas que trae el tiempo.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,180,180,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01616",4,"A orillas del mar me siento,\ná voces llamo á quien amo,\ny como no me responde,\nmuchas lágrimas derramo.",4,0,-1,70,"",0,4,"ao",100,0,-1,0,180,180,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01617",4,"Tengo una pena conmigo\nque á nadie se la diré,\nen el fondo de mi pecho\nsu sepulcro labraré.",4,0,-1,70,"",0,4,"e",77,0,-1,0,180,180,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01618",4,"¡Ay, pobrecito de mí,\nque echo suspiros al aire!\n¡Ay que se los lleva el viento\ny no me responde nadie!",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,180,180,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01619",4,"Dentro de mi pecho tengo\nuna arquita con dos llaves,\ny en ella tengo metidas\ncositas que nadie sabe.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,180,180,"","",1,"lafuente_madrid","","",32,0,0,[],""],["palau_cantares-01620",4,"Olvidé á Dios por quererte,\npor ti la gloria perdí...,\ny ahora me vengo á quedar\nsin Dios, sin gloria y sin ti.",4,0,-1,70,"",3,4,"i",23,0,-1,0,180,180,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01621",4,"No hay corazón como el mío,\nque calle y sienta su pena:\ncorazón que siente y calla,\nno se encuentra dondequiera.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,180,180,"","",1,"rm_t3","","",9,0,0,[],""],["palau_cantares-01622",4,"Suspiros, ¿por qué queréis\nsalir del corazón triste,\nsi sabéis que adonde vais\nnunca jamás os reciben?",4,0,-1,70,"",0,4,"ie",-1,0,-1,0,180,180,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01623",4,"«Canta, mi vida, canta,\nque con el eco\ndiviertes la memoria\ny el pensamiento:»\nesto decía\nun amante del alma\nque yo tenía.",4,0,-1,70,"",4,7,"ia",0,0,-1,0,180,180,"","",1,"rm_t3","","",4,0,0,[],""],["palau_cantares-01624a",4,"Quise bien, fuí aborrecido;\nadoré, fuí despreciado;\nme lamenté, no fuí oído;\nporfié, no fuí escuchado.",4,0,-1,70,"",1,4,"ao",14,0,-1,0,180,180,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01624b",4,"Entre fatigas y luchas\nmi alma es la que batalla:\ncomo son mis penas muchas,\nmi amor lo sufre y lo calla.",4,0,-1,70,"",1,4,"aa",249,0,-1,0,180,180,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01625",4,"Entre las sombras tristes\nde obscura noche\nbusca mi triste pecho\nquien le devore;\npero mi suerte,\npor no darme consuelo,\nno halla la muerte.",4,0,-1,70,"",4,7,"ee",134,0,-1,0,180,180,"","",1,"","","",2,0,0,[],""],["palau_cantares-01626",4,"Desde que aquella morena\nme dió penillas tan grandes,\nnadie quiero que me quiera,\nni quiero querer á nadie.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,180,180,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01627",4,"El corazón se me parte\nde dolor y sentimiento\nde ver que estás en el mundo\ny ya para mí te has muerto.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,180,180,"","",1,"lafuente_madrid","","",6,0,0,[],""],["palau_cantares-01628a",4,"Un suspiro me ofende\ny otro me alivia,\npero no es favorable\nla alternativa:\npues los que ofenden\nson más que los que alivian\nmi triste suerte.",4,0,-1,70,"",4,7,"ee",-1,0,-1,0,181,181,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01628b",4,"Dejadme, pensamientillos,\nno me estéis atormentando:\nsi la quise ó no la quise,\nno me lo estéis recordando.",4,0,-1,70,"",0,4,"ao",33,0,-1,0,181,181,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01628c",4,"Por Dios te lo pido, niña,\ny te lo pido llorando,\nque no le cuentes á nadie\nlo que á mí me está pasando.",4,0,-1,70,"",0,4,"ao",33,0,-1,0,181,181,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01628d",4,"Si mi corazón tuviera\nvidrieras de cristal,\nte asomaras, y lo vieras\ncon cuánta penilla está.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,181,181,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01628e",4,"¡Válgame Dios de los cielos,\nVirgen del mayor dolor!\n¡Como una bayeta negra\ntengo yo mi corazón!",4,0,-1,70,"",0,4,"o",-1,0,-1,0,181,181,"","",1,"rm_t3, lafuente_madrid","","",33,0,0,[],""],["palau_cantares-01628f",4,"Al infierno parecen\nmis pensamientos\nen el atormentarme\ny en ser eternos.",4,0,-1,70,"",6,4,"eo",-1,0,-1,0,181,181,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01628g",4,"Ven, muerte, tan escondida,\nque no te sienta venir,\nporque el placer de morir\nno me vuelva á dar la vida.",4,0,-1,70,"",11,4,"ia",37,0,-1,0,181,181,"","",1,"","","",7,0,0,[],""],["palau_cantares-01629",4,"Fuí jilguero desgraciado\nque, apenas salí del nido,\nme cogieron los muchachos:\npor dos cuartos fuí vendido.",4,0,-1,70,"",0,4,"io",101,0,-1,0,181,181,"","",1,"","","",1,0,0,[],""],["palau_cantares-01629-e2",4,"De mi ventana á la tuya\nhay una larga cadena,\ntoda llena de suspiros,\ntoda de suspiros llena.",4,0,-1,70,"",0,4,"ea",59,0,-1,0,181,181,"","",1,"","","",2,0,0,[],""],["palau_cantares-01629-e3",4,"¡Ay que la enterraron\ncon la mano fuera!\nComo era la pobre tan desgraciadita,\n*faltóle la tierra.",4,0,-1,70,"",3,4,"ea",-1,0,-1,0,181,181,"","",1,"","","",1,0,0,[],""],["palau_cantares-01629-e4",4,"Vivo sólito en el mundo\ny de mí nadie se acuerda;\nbusco en los árboles sombra,\ny los árboles se secan.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,181,181,"","",1,"rm_t3, barcenas_marinera","","",4,0,0,[],""],["palau_cantares-01629-e5",4,"Los ojitos de mi cara,\n¿quién me los quiere comprar?\nLos vendo por traicioneros,\nporque publican mi mal.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,181,181,"","",1,"rm_t3, carrizo_salta","","",13,0,0,[],""],["palau_cantares-01629-e6",4,"Llorad, llorad, ojos míos;\nllorad si tenéis por qué;\nque no es vergüenza en un hombre\nllorar por una mujer.",4,0,-1,70,"",0,4,"e",-1,0,-1,0,181,181,"","",1,"","","",2,0,0,[],""],["palau_cantares-01629-e7",4,"Yo conocí quien tenía\nun pajarito en la mano,\ny por querer tener otro,\nse le escaparon entrambos.",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,181,181,"","",1,"","","",1,0,0,[],""],["palau_cantares-01629-e8",4,"La que tiene un pajarito\nen la mano y se le va,\nsi le ha tomado cariño,\n¡qué triste se quedará!",4,0,-1,70,"",0,4,"a",9,0,-1,0,181,181,"","",1,"","","",1,0,0,[],""],["palau_cantares-01630",4,"No me digas que me vaya;\npor Dios no me digas «vete;»\nporque se me representan\nlas fatigas de la muerte.",4,0,-1,70,"",0,4,"ee",-1,0,-1,0,181,181,"","",1,"rm_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01631",4,"Cuando muera, por letrero\nme pondrás en el sepulcro:\n«Aquí yace un desdichado\nque de veras querer supo.»",4,0,-1,70,"",0,4,"uo",-1,0,-1,0,181,181,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01632",4,"El amor me persigue\ncon tal porfía,\nque á millones las penas\nme las envía.",4,0,-1,70,"",6,4,"ia",0,0,-1,0,181,181,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01633",4,"Si el campo santo visitas,\npronto me hallarás allí,\ny habrá en mi losa un letrero\nque sólo diga: «¡Ay de mí!»",4,0,-1,70,"",0,4,"i",23,0,-1,0,181,181,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01634a",4,"Si vas á mi sepultura,\npon un pie en la losa y di:\n«Aquí yace un desdichado\nque murió de amor por mí.»",4,0,-1,70,"",0,4,"i",23,0,-1,0,182,182,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01634b",4,"Ya se murió mi marido,\nya se murió mi consuelo,\nya no tengo quien me diga:\n«Ojillos de terciopelo.»",4,0,-1,70,"",0,4,"eo",10,0,-1,0,182,182,"","",1,"","","",3,0,0,[],""],["palau_cantares-01634c",4,"Sufro, siento, padezco,\nsuspiro y lloro,\ntengo amor, y con esto\nlo digo todo:\nporque el que adora\nsufre, siente, padece,\nsuspira y llora.",4,0,-1,70,"",4,7,"oa",107,0,-1,0,182,182,"","",1,"rm_t3","","",2,0,0,[],""],["palau_cantares-01634d",4,"Ojos míos, lloremos,\nque es el arbitrio\nque les queda á los tristes\npara su alivio:\nlloremos tanto,\nque se aneguen mis ansias\nen vuestro llanto.",4,0,-1,70,"",4,7,"ao",30,0,-1,0,182,182,"","",1,"rm_t3, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01634e",4,"En el duro tormento\nque te acongoja,\ntú lloras sin consuelo,\npero al fin lloras:\n¡ay desgraciado\ndel que llorar no puede\ny está penando!",4,0,-1,70,"",4,7,"ao",-1,0,-1,0,182,182,"","",1,"","","",1,0,0,[],""],["palau_cantares-01634f",4,"Un jilguerillo llora,\ny así le digo:\n«¿Tú también tienes penas?\nLlora conmigo:\nfiel compañero,\ntú al fin tendrás alivio,\nsi hallas tu dueño.»",4,0,-1,70,"",4,7,"eo",-1,0,-1,0,182,182,"","",1,"","","",1,0,0,[],""],["palau_cantares-01634g",4,"Es mi pena tan fuerte,\nmi mal tan grave,\nque acabaré la vida\nsin que esto acabe:\ncurar podría,\nsi no fuese veneno\nla medicina.",4,0,-1,70,"",4,7,"ia",-1,0,-1,0,182,182,"","",1,"","","",2,0,0,[],""],["palau_cantares-01635",4,"Para aliviar mis penas\nyo necesito,\ná cambio de memorias,\ncomprar olvidos:\nque la memoria\nno importa que se pierda,\ncuando no importa.",4,0,-1,70,"",4,7,"oa",-1,0,-1,0,182,182,"","",1,"rm_t3","","",3,0,0,[],""],["palau_cantares-01635-e2",4,"Yo pienso que las dichas\nse han escondido,\npor no dar en el caso\nde dar conmigo:\ncon las desdichas\ntropiezo á cada paso\ny á cada esquina.",4,0,-1,70,"",4,7,"ia",-1,0,-1,0,182,182,"","",1,"","","",2,0,0,[],""],["palau_cantares-01635-e3",4,"Los ojitos de mi cara,\n¿quién los compra, que los vendo?\nTan pobre me voy quedando\nque hasta los ojitos vendo.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,182,182,"","",1,"lafuente_madrid","","",13,0,0,[],""],["palau_cantares-01635-e4",4,"Cada vez que paso y miro\nla puerta del hospital,\nle digo á mi cuerpecito:\n- Aquí vendrás á parar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,182,182,"","",1,"rm_t3, lafuente_madrid","","",25,0,0,[],""],["palau_cantares-01635-e5",4,"Cada vez que paso y miro\nla puerta del campo santo,\nle digo á mi cuerpecillo:\n- Aquí tendrás tu descanso.",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,182,182,"","",1,"lafuente_madrid","","",25,0,0,[],""],["palau_cantares-01635-e6",4,"Yo no deseo la muerte,\nporque es pecado mortal;\npero sé que hasta que muera\ndescanso no he de encontrar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,182,182,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01635-e7",4,"Hasta la cama en que duermo\nse queja de mi dolor:\ncuando la cama lo siente,\n¡qué será mi corazón!",4,0,-1,70,"",0,4,"o",-1,0,-1,0,182,182,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01635-e8",4,"Sombra le pedí á una fuente,\nagua le pedí á un olivo;\nque me ha puesto tu querer\nque no sé lo que me digo.",4,0,-1,70,"",0,4,"io",-1,0,-1,0,182,182,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01635-e9",4,"Dicen que la mar divierte,\nque quita pena y fatiga;\nyo me arrimaré á una fuente\npor ver si el agua me anima.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,182,182,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01636",4,"Pienso, y no sé lo que pienso;\npienso, y no soy desgraciado:\npienso que siempre la soga\nquiebra por lo más delgado.",4,0,-1,70,"",0,4,"ao",14,0,-1,0,183,183,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01637",4,"Soñaba yo que tenía\ncontento mi corazón;\npero ¿es verdad, madre mía,\nque los sueños sueños son?",4,0,-1,70,"",1,4,"o",31,0,-1,0,183,183,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01639",4,"Por culpa de malas lenguas\nperdí la prenda que amaba:\nsi me la encuentro en la calle,\nni me mira ni me habla.",4,0,-1,70,"",0,4,"aa",-1,0,-1,0,183,183,"","",1,"","","",3,0,0,[],""],["palau_cantares-01640-e2",4,"Cualquiera que me mirase,\ndirá que no tengo penas,\ny tengo mi corazón\ncomo una bayeta negra.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,183,183,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01640-e3",4,"Como una morcilla negra\ntengo yo mi corazón:\nserranilla, si lo vieras,\nte había de dar dolor.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,183,183,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01640-e4",4,"Comunícame tu pena,\nyo te diré mi dolor,\nque penas comunicadas,\npenas con alivio son.",4,0,-1,70,"",0,4,"o",-1,0,-1,0,183,183,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01640-e5",4,"Dentro de mi corazón\ntengo yo una llaga viva\nque me ha hecho tu querer\nde pasar puras fatigas.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,183,183,"","",1,"rm_t3","","",7,0,0,[],""],["palau_cantares-01640-e6",4,"Te pido por los cordeles\nque tiene mi Dios al cuello,\nque no me des más penillas,\nque ya no tiene remedio.",4,0,-1,70,"",0,4,"eo",-1,0,-1,0,183,183,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01640-e7",4,"Por aquella cruz bendita\nque en Capuchinos está,\nque no me des más penitas,\nque no las puedo llevar.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,183,183,"","",1,"rm_t3, lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01640-e8",4,"Soñé la dicha de hallarme\nen los brazos de mi dueño,\ny al despertar sin la dicha,\nhallé que la dicha es sueño.",4,0,-1,70,"",0,4,"eo",138,0,-1,0,183,183,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01641a",4,"Ya te he dicho, corazón,\nsegunda y tercera vez,\nque no llames á esa puerta,\nque no te han de responder.",4,0,-1,70,"",0,4,"e",-1,0,-1,0,183,183,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01641b",4,"Ya no tengo yo en mi pecho\npaciencia para sufrir;\nsiempre me estoy acordando\nde quien se olvida de mí.",4,0,-1,70,"",0,4,"i",-1,0,-1,0,183,183,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01641c",4,"Tres días ha que no como\nmás que lágrimas y pan:\nestos son los alimentos\nque tus amores me dan.",4,0,-1,70,"",0,4,"a",147,0,-1,0,183,183,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01641d",4,"Nadie se duela de mí,\nsolo mis tormentos pase;\nque el que busca el mal por sí,\ná nadie debe quejarse.",4,0,-1,70,"",0,4,"ae",-1,0,-1,0,183,183,"","",1,"rm_t3, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01641e",4,"Ya no me asomo á la reja\nque me solía asomar,\nque me asomo á una ventana\nque cae á la soledad.",4,0,-1,70,"",0,4,"a",-1,0,-1,0,183,183,"","",1,"","","",3,0,0,[],""],["palau_cantares-01641f",4,"Salí al campo y le conté\ná una rama mi sentir;\nde la pena que sintió\nse le secó la raíz.",4,0,-1,70,"",0,4,"i",-1,0,-1,0,183,183,"","",1,"","","",1,0,0,[],""],["palau_cantares-01641g",4,"Dos cosas en el mundo\nme harán perderte:\nsi vivo, el desengaño;\nsi no, la muerte.",4,0,-1,70,"",6,4,"ee",134,0,-1,0,183,183,"","",1,"","","",3,0,0,[],""],["palau_cantares-01642",4,"Ojitos míos, llorad;\nlágrimas, tened paciencia;\nque el que nace desgraciado,\ndesde pequeñito empieza.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,184,184,"","",1,"","","",1,0,0,[],""],["palau_cantares-01643",4,"Del pino que derribé\nla tarde que ella moría,\nhice la cruz de la tumba\ndonde reposa mi niña.",4,0,-1,70,"",0,4,"ia",-1,0,-1,0,184,184,"","",1,"","","",1,0,0,[],""],["palau_cantares-01644",4,"Andaba muy poco á poco\nmi pobrecito caballo\nporque le pesaban mucho\nlos pesares de su amo.",4,0,-1,70,"",0,4,"ao",-1,0,-1,0,184,184,"","",1,"","","",1,0,0,[],""],["palau_cantares-01645",4,"Alegrías no las quiero\nde esas que á todos alegran;\nyo quiero las alegrías\nque al mismo tiempo dan pena.",4,0,-1,70,"",0,4,"ea",-1,0,-1,0,184,184,"","",1,"","","",1,0,0,[],""],["palau_cantares-01646a",4,"No vayas á la tienda\ndel dios Cupido,\nque por cualquiera cosa\nlleva un sentido.\nNo entres en ella,\nque se te irán los ojos\ntras de sus prendas.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,185,185,"","",1,"","","",3,0,0,[],""],["palau_cantares-01646b",4,"Es amor una araña\nque, con cautela,\nen un rincón del alma\nforma su tela;\ncon tal sigilo,\nque ningún sabio pudo\ncortar el hilo.",4,0,-1,71,"",4,7,"io",247,0,-1,0,185,185,"","",1,"rm_t4, frenk_t2","","",3,0,0,[],""],["palau_cantares-01646c",4,"Hay quereres de despecho,\nhay quereres de ilusiones,\nhay quereres que se alquilan\ncomo las habitaciones.",4,0,-1,71,"",0,4,"oe",34,0,-1,0,185,185,"","",1,"frenk_t2","","",2,0,0,[],""],["palau_cantares-01646d",4,"Un corazón sin amor\nes una planta sin fruto:\nel infeliz que no quiere\n¡para qué vive en el mundo!",4,0,-1,71,"",0,4,"uo",-1,0,-1,0,185,185,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01646e",4,"El pimiento ha de ser verde\ny el tomate colorado,\nla berenjena espinosa,\ny los amores callados.",4,0,-1,71,"",0,4,"ao",-1,0,-1,0,185,185,"","",1,"","","",2,0,0,[],""],["palau_cantares-01647",4,"El amor es como un árbol\nque sólo tiene una rama,\nque para subir á él\nes menester que otro caiga.",4,0,-1,71,"",0,4,"aa",-1,0,-1,0,185,185,"","",1,"","","",1,0,0,[],""],["palau_cantares-01647-e3",4,"Hasta lá leña en el monte\ntiene su separación:\nuna sirve para santos\ny otra para hacer carbón.",4,0,-1,71,"",0,4,"o",31,0,-1,0,185,185,"","",1,"rm_t4, carrizo_salta","","",3,0,0,[],""],["palau_cantares-01647-e4",4,"Suerte negra, suerte perra\nla suerte de la mujer,\nque lo que el alma le pide\nse lo prohibe el deber.",4,0,-1,71,"",0,4,"e",20,0,-1,0,185,185,"","",1,"","","",2,0,0,[],""],["palau_cantares-01647-e5",4,"El amor de los hombres\nes como el vaso,\nque al menor movimiento\nse hace pedazos:\ny es evidente\nque el más fino se quiebra\nmás fácilmente.",4,0,-1,71,"",4,7,"ae",-1,0,-1,0,185,185,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01648",4,"Cuatro eses componen\namor perfecto:\nser solícito, sabio,\nsolo y secreto.",4,0,-1,71,"",6,4,"eo",-1,0,-1,0,186,186,"","",1,"","","",2,0,0,[],""],["palau_cantares-01648-e2",4,"Las mujeres y cuerdas\nde la guitarra\nes menester talento\npara templarlas:\nflojas no suenan,\ny suelen saltar muchas\nsi las aprietan.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,186,186,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01648-e3",4,"Las mujeres al mundo\nperdido tienen,\ny los hombres al mundo\ny á las mujeres:\ny de este modo,\nhombres, mujeres, mundo,\nperdido todo.",4,0,-1,71,"",4,7,"oo",261,0,-1,0,186,186,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01648-e4",4,"Es la mujer conjunto\nde malo y bueno,\nen su postrera obra\nDios echó el resto;\nnadie la gana\ncuando es la mujer buena,\nni cuando es mala.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,186,186,"","",1,"","","",2,0,0,[],""],["palau_cantares-01648-e5",4,"Es el amor, señores,\ncomo el cigarro:\nnadie lo deja, y todos\nquieren dejarlo;\ny el que lo deja,\nes para volver luego\ncon mayor fuerza.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,186,186,"","",1,"rm_t4","","",4,0,0,[],""],["palau_cantares-01648-e6",4,"Es amor un embuste\ntan bien dispuesto,\nque le hacen las mujeres\ntener por cierto;\ny con engaños\ntienen á muchos hombres\nembolismados.",4,0,-1,71,"",4,7,"ao",-1,0,-1,0,186,186,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01648-e7",4,"Lo mismo que las sombras\nson las mujeres:\nhuyen del que las sigue,\ny al que huye quieren.",4,0,-1,71,"",6,4,"ee",-1,0,-1,0,186,186,"","",1,"","","",1,0,0,[],""],["palau_cantares-01649",4,"Amores son monedas\nimaginarias,\nque aunque no las ve nadie\ntodos las pasan;\nde tal manera,\nque el comercio se hace\ncon ofrecerlas.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,186,186,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01649-e2",4,"De cera son las puertas\nde los amores,\ncuenta que á la salida\nya son de bronce;\ny que á la entrada\nsuelen estar abiertas,\ndespués cerradas.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,186,186,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01649-e3",4,"Nace amor de la vista,\ncrece del trato,\nse alimenta de celos,\nmuere de agravios:\nel que lo dude,\nque sufra lo que sufro,\nluego lo apure.",4,0,-1,71,"",4,7,"ue",-1,0,-1,0,186,186,"","",1,"","","",3,0,0,[],""],["palau_cantares-01649-e4",4,"No te cases con viejo\npor la moneda:\nla moneda se gasta\ny el viejo queda.",4,0,-1,71,"",6,4,"ea",266,0,-1,0,186,186,"","",1,"fernan_caballero","","",5,0,0,[],""],["palau_cantares-01649-e5",4,"¿Te quieres poner conmigo?,\nle dijo el tiempo al querer:\nesa soberbia que gastas\nyo te la castigaré.",4,0,-1,71,"",0,4,"e",-1,0,-1,0,186,186,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01649-e6",4,"De lo profundo del mar\nsuspiraba una ballena,\ny en el suspiro decía:\n«Quien tiene amor, tiene penas.»",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,186,186,"","",1,"","","",1,0,0,[],""],["palau_cantares-01649-e7",4,"La cadena del amor\nllévala contigo un año\ny verás qué peso tiene\nel que vive enamorado.",4,0,-1,71,"",0,4,"ao",-1,0,-1,0,186,186,"","",1,"rm_t4, lafuente_madrid","","",8,0,0,[],""],["palau_cantares-01649-e8",4,"La cadena del amor\ntiene fuertes eslabones,\ny aquel que en ella se mete\ntarde sale de prisiones.",4,0,-1,71,"",0,4,"oe",34,0,-1,0,186,186,"","",1,"lafuente_madrid, fernan_caballero","","",8,0,0,[],""],["palau_cantares-01650",4,"Es amor como el pleitista\ncuando dinero no tiene:\nni el escribano le escucha,\nni el abogado le atiende.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,187,187,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01651",4,"¡Qué gustosa va un alma\ncuando la llevan\ndesde las falsedades\ná las finezas!",4,0,-1,71,"",6,4,"ea",-1,0,-1,0,187,187,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01652",4,"Compañero, si te casas,\nbusca una mujer morena,\nque entre las blancas y rubias\nde ciento sale una buena.",4,0,-1,71,"",0,4,"ea",59,0,-1,0,187,187,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01653",4,"Querer por sólo querer,\nsin esperanza de premio,\nes un querer desdichado,\npero es querer verdadero.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,187,187,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01654",4,"Es el amor, señores,\nuna carcoma,\nque se va apoderando\nde la persona.",4,0,-1,71,"",6,4,"oa",-1,0,-1,0,187,187,"","",1,"rm_t4","","",4,0,0,[],""],["palau_cantares-01655",4,"Es de tal modo el amor\ny son sus efectos tales,\nque lo declaran los ojos\naunque la boca lo calle.",4,0,-1,71,"",0,4,"ae",-1,0,-1,0,187,187,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01656a",4,"No te fíes de ojos negros,\nque ojos negros son traidores:\nunos ojos negros fueron\ncausa de mis perdiciones.",4,0,-1,71,"",0,4,"oe",-1,0,-1,0,187,187,"","",1,"rm_t4, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01656b",4,"Ojos verdes son la mar,\nojos azules el cielo,\nojos garzos purgatorio,\nojos negros el infierno.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,187,187,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01656c",4,"Más la quiero pobre y fea\nque bonita y con dinero:\nla pobre me mira á mí,\ny la bonita al espejo.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,187,187,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01656d",4,"Lástima les tengo yo\ná toditas las mujeres:\ncuanto más bonitas son,\nmás mala fortuna tienen.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,187,187,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01656e",4,"Yo no sé quién se fía\nde la esperanza:\nbasta que sea hembra\npara ser falsa.",4,0,-1,71,"",6,4,"aa",-1,0,-1,0,187,187,"","",1,"","","",1,0,0,[],""],["palau_cantares-01656f",4,"Esperanza consuela,\nposesión cansa,\napetecer desvela,\nno lograr mata.",4,0,-1,71,"",6,4,"aa",-1,0,-1,0,187,187,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01656g",4,"Memoria que en el tiempo\nde los desvíos\nse acuerda de la dicha,\ndobla el martirio.",4,0,-1,71,"",6,4,"io",-1,0,-1,0,187,187,"","",1,"rm_t4, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01657a",4,"El dinero y los amores\nno pueden estar cubiertos:\nel dinero, porque suena;\nlos amores, por inquietos.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,187,187,"","",1,"rm_t4, machado_venezuela, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01657b",4,"Piensan los enamorados,\npiensan y no piensan bien,\npiensan que nadie los mira\ny todo el mundo los ve.",4,0,-1,71,"",0,4,"e",-1,0,-1,0,187,187,"","",1,"rm_t4, frenk_t2, andina_t2, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01657c",4,"Es una gloria el querer\ncuando es querer deseado,\ny en llegándose á perder,\nes un infierno abreviado.",4,0,-1,71,"",1,4,"ao",14,0,-1,0,187,187,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01657d",4,"Entre la tierra y el cielo\nse oyó una voz por el aire:\n«Quien quiera vivir tranquilo\nno ponga su amor en nadie.»",4,0,-1,71,"",0,4,"ae",-1,0,-1,0,187,187,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01657e",4,"El tiempo con el querer\nhicieron una contrata,\ny lo que el querer dispone\nel tiempo lo desbarata.",4,0,-1,71,"",0,4,"aa",74,0,-1,0,187,187,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01657f",4,"Es el amor un niño\nque, cuando nace,\ncon poquito que coma\nse satisface;\npero en creciendo,\ncuanto más le van dando,\nmás va queriendo.",4,0,-1,71,"",4,7,"eo",52,0,-1,0,187,187,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01658",4,"Yo me acerqué á una fragua,\ndije al herrero:\n«Hágame usté un amante\nde fino acero;»\ny él me responde:\n«¿Cómo puede ser fino\nsi ha de ser hombre?»",4,0,-1,71,"",4,7,"oe",-1,0,-1,0,188,188,"","",1,"","","",2,0,0,[],""],["palau_cantares-01659",4,"La que es fea es discreta,\nla necia hermosa,\ncada una sirve siempre\npara su cosa.\nGusto completo\nla fea dará al alma,\nla hermosa al cuerpo.",4,0,-1,71,"",4,7,"eo",-1,0,-1,0,188,188,"","",1,"","","",1,0,0,[],""],["palau_cantares-01660",4,"El amor ha de ser uno,\neso bien lo sabéis vos;\nno tiene amor con ninguno\nla mujer que quiere á dos.",4,0,-1,71,"",1,4,"o",87,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01661",4,"Quien ama correspondido\nno deje de recelarse,\nque son los días de gusto\nvísperas de los pesares.",4,0,-1,71,"",0,4,"ae",-1,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01662",4,"Nace la perla en el mar,\nen los jardines la flor,\nentre riscos el diamante,\nentre amantes el amor.",4,0,-1,71,"",0,4,"o",72,0,-1,0,188,188,"","",1,"frenk_t2, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01663",4,"Amor, no pongas amor\ndonde no hay correspondencia;\nmira que te quedarás\ná la luna de Valencia.",4,0,-1,71,"",0,4,"ea",46,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01664",4,"Las fatigas de la muerte\ngrandes fatiguillas son;\npero con las del querer\nno tienen comparación.",4,0,-1,71,"",0,4,"o",31,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01665",4,"¿Cuál será el dolor más fuerte\nó la pena más sensible,\nel batallar con la muerte\nó el querer un imposible?",4,0,-1,71,"",1,4,"ie",259,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01666",4,"No hay amor como el primero,\ny los demás son fingidos;\nel primer amor que tuve\nse llevó el corazón mío.",4,0,-1,71,"",0,4,"io",-1,0,-1,0,188,188,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01667",4,"En contiendas amorosas\naconseja cierto autor\nherrar ó quitar el banco;\ny yo sigo su opinión.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01668",4,"No hay amante sin amante,\nno hay amor sin pena fuerte,\nno hay firmeza sin amor,\nni vida sin tener muerte.",4,0,-1,71,"",0,4,"ee",134,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01669",4,"Quien diga que ha enamorado\nsin sufrir ni padecer,\nó siempre ha sido muy necio,\nó nunca ha querido bien.",4,0,-1,71,"",0,4,"e",-1,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01670",4,"Dícese que nos queremos;\nyo no sé si desearlo:\nla risa de amor es dulce,\npero su llanto es amargo.",4,0,-1,71,"",0,4,"ao",-1,0,-1,0,188,188,"","",1,"lafuente_madrid, fernan_caballero","","",3,0,0,[],""],["palau_cantares-01672",4,"Al amor lo pintan niño,\ny á la firmeza mujer;\nentre una mujer y un niño,\n¿qué amor firme puede haber?",4,0,-1,71,"",1,4,"e",20,0,-1,0,188,188,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01673",4,"Dicen algunos autores\nque la ausencia causa olvido;\neso lo dirán los necios\nque amores no hayan tenido.",4,0,-1,71,"",0,4,"io",101,0,-1,0,188,188,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01674",4,"Son las mujeres feas\npiedra en la calle,\ndonde muchos tropiezan,\nninguno cae.\nSi ella es bonita,\naunque el hombre sea firme,\nse precipita.",4,0,-1,71,"",4,7,"ia",50,0,-1,0,188,188,"","",1,"","","",1,0,0,[],""],["palau_cantares-01675",4,"Es lo esquivo en la dama\ncomo lo bello,\nuna espuela que aguija\nmás el deseo:\npues siempre han sido\nlos desdenes la causa\npara el cariño.",4,0,-1,71,"",4,7,"io",-1,0,-1,0,188,188,"","",1,"","","",1,0,0,[],""],["palau_cantares-01676",4,"Tiene, como el diamante,\nla dama bella\nvalor, brillo, hermosura,\nfondo y firmeza;\ny si es constante,\nno hay tesoro en el mundo\nque se le iguale.",4,0,-1,71,"",4,7,"ae",-1,0,-1,0,189,189,"","",1,"","","",1,0,0,[],""],["palau_cantares-01676-e2",4,"Á mujer que sale mala\nno reñirle, ni pegarle;\nla cabra que tira al monte\nno hay cabrero que la guarde.",4,0,-1,71,"",0,4,"ae",-1,0,-1,0,189,189,"","",1,"","","",1,0,0,[],""],["palau_cantares-01676-e3",4,"Dice el sabio Salomón\nque el que engaña á una doncella\nno tiene perdón de Dios\nsi no se casa con ella.",4,0,-1,71,"",0,4,"ea",6,0,-1,0,189,189,"","",1,"rm_t4, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01676-e4",4,"La mujer que á un hombre adora\npor su gusto solamente,\nlos intereses desprecia\naunque ricos la cortejen.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,189,189,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01676-e5",4,"En tu vida te enamores\nde mozo que no ha rondado,\nque el que no ronda de mozo,\nronda después de casado.",4,0,-1,71,"",0,4,"ao",14,0,-1,0,189,189,"","",1,"rm_t4, lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01676-e6",4,"En ningún hombre casado\npongas nunca tu querer,\nporque al fin y á la partida\nse lo lleva su mujer.",4,0,-1,71,"",0,4,"e",20,0,-1,0,189,189,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01676-e7",4,"Nace amor como planta\nen el corazón,\nel cariño la riega,\nla seca el rigor;\ny si se arraiga,\nse arranca, al apartarle,\nparte del alma.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,189,189,"","",1,"preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01676-e8",4,"En la cárcel del alma\namor se encierra,\ncausa cuidados preso,\ny al salir pena:\nporque quien ama\nda, siempre que olvida,\ntormento al alma.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,189,189,"","",1,"","","",3,0,0,[],""],["palau_cantares-01677",4,"Los síntomas que indican\ndolor tan grave\nson un fuego que hiela\ny un hielo que arde:\nmal que recrea,\ntormento que da gusto,\ngloria que es pena.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,189,189,"","",1,"","","",1,0,0,[],""],["palau_cantares-01677-e2",4,"Apetece tres cosas\nel amor ciego,\nque es el tener constancia,\nvalor y tiempo;\npero si falta\ncualquiera de estas cosas,\namor es rabia.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,189,189,"","",1,"","","",1,0,0,[],""],["palau_cantares-01677-e3",4,"No vayas solita al campo\ncuando sople el aire recio,\nporque las niñas son flores\nque hasta las deshoja el viento.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,189,189,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01677-e4",4,"No te enamores, mozuela,\nde pájaro volantón,\nque anda de olivo en olivo\nbuscando la mejor flor.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,189,189,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01677-e5",4,"Si los hombres se calaran\ncomo se cala el melón,\nmás de cuatro muchachitas\nno vivieran con dolor.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,189,189,"","",1,"rm_t4, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01677-e6",4,"Ninguna, por ser bonita,\ná ningún galán desprecie,\nque un cordón de oro torcido\nda una vuelta y se destuerce.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,189,189,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01677-e7",4,"No viváis, hermosuras,\ntan confiadas,\nque es la misma belleza\nquien más os daña;\nni en esquiveces\nos confiéis tampoco,\nque hay quien las vence.",4,0,-1,71,"",4,7,"ee",-1,0,-1,0,189,189,"","",1,"","","",1,0,0,[],""],["palau_cantares-01677-e8",4,"La dama, por esquiva,\nno hay que dejarla,\nque en el hierro más duro\nmás se machaca;\ny golpe á golpe\naun la piedra más dura\nblanda se pone.",4,0,-1,71,"",4,7,"oe",-1,0,-1,0,189,189,"","",1,"","","",3,0,0,[],""],["palau_cantares-01678",4,"Ya no hay Padre Santo en Roma,\nni en España cristiandad,\nni en las mujeres firmeza,\nni en los hombres lealtad.",4,0,-1,71,"",0,4,"a",16,0,-1,0,190,190,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01680",4,"Es la mujer en rigor\ncomo manjar con veneno,\nque lo dulce está por fuera\ny lo amargo está por dentro.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,190,190,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01681",4,"Comparadilla la tengo\nla mujer con la tormenta;\ndespués que pierden á un hombre\nluego le dan la contenta.",4,0,-1,71,"",0,4,"ea",229,0,-1,0,190,190,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01682",4,"Son las hembras arcas nuevas\ncon su cerraja y su llave;\npor fuera están muy bonitas,\ny por dentro... ¡Dios lo sabe!",4,0,-1,71,"",0,4,"ae",131,0,-1,0,190,190,"","",1,"","","",1,0,0,[],""],["palau_cantares-01683",4,"Como maestra en amores,\npondré un letrero en mi escuela:\n«Nadie se fíe de hombres,\nporque á lo mejor la pegan.»",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,190,190,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01684",4,"Si la mar fuera de tinta\ny el cielo fuera papel,\nno se pudiera escribir\nlo falsa que es la mujer.",4,0,-1,71,"",0,4,"e",-1,0,-1,0,190,190,"","",1,"lafuente_madrid","","",11,0,0,[],""],["palau_cantares-01685",4,"Si de mujeres te prendas,\ndarás fin á tu caudal;\nno hay cosa que valga menos,\nni cosa que cueste más.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,190,190,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01686",4,"Si la mar fuera de tinta\ny el cielo de papel doble,\nno se pudiera escribir\nlo falsos que son los hombres.",4,0,-1,71,"",0,4,"oe",-1,0,-1,0,190,190,"","",1,"rm_t4, lafuente_madrid","","",11,0,0,[],""],["palau_cantares-01687",4,"Cuando un hombre está queriendo,\nsolicita y galantea;\ny así que logra su intento,\naborrece, olvida y niega.",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,190,190,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01688",4,"La mujer que encuentre un hombre\nfino, constante y leal,\nllévelo por cosa rara\ná la Historia Natural.",4,0,-1,71,"",0,4,"a",1,0,-1,0,190,190,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01689",4,"Cuando intentan las mujeres\nconquistar algún galán,\nhumildes se manifiestan;\npero después... ¡Dios dirá!",4,0,-1,71,"",0,4,"a",-1,0,-1,0,190,190,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01690",4,"No te fíes de los hombres\naunque digan: «Bien te quiero;»\nque en volviendo las espaldas,\nsi te he visto, no me acuerdo.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,190,190,"","",1,"rm_t4","","",16,0,0,[],""],["palau_cantares-01691",4,"¡Qué triste que va la luna\ny el lucero en su compaña!\n¡Qué triste se queda un hombre\ncuando una mujer lo engaña!",4,0,-1,71,"",0,4,"aa",213,0,-1,0,190,190,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01692",4,"La mujer y la nave\nson parecidas\nen que con sólo el viento\nlas dos se guían:\ny si tropiezan,\ntambién son semejantes\nen que se estrellan.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,190,190,"","",1,"","","",1,0,0,[],""],["palau_cantares-01693",4,"De sepulcro en sepulcro\nvoy preguntando\ncuál es el primer hombre\nque murió amando.\nMe dijo uno:\n«Mujeres, á millares;\nhombre, ninguno.»",4,0,-1,71,"",4,7,"uo",230,0,-1,0,190,190,"","",1,"","","",5,0,0,[],""],["palau_cantares-01694",4,"Son los hombres tan vanos\ncomo las cañas,\ny se ponen tan huecos\ncuando los aman:\npor inconstantes\nceden, como las cañas,\ná cualquier aire.",4,0,-1,71,"",4,7,"ae",-1,0,-1,0,190,190,"","",1,"","","",1,0,0,[],""],["palau_cantares-01695",4,"Es la mujer lo mismo\nque leña verde:\nresiste, gime, llora\ny al fin se enciende.\nLuego, encendida,\nni resiste, ni llora:\nsólo suspira.",4,0,-1,71,"",4,7,"ia",-1,0,-1,0,190,190,"","",1,"","","",5,0,0,[],""],["palau_cantares-01696",4,"Como encuentres un hombre\nsin un defecto,\nven á darme el aviso,\nque aquí te espero;\npero me marcho,\nporque ya es obra larga\nla que te encargo.",4,0,-1,71,"",4,7,"ao",-1,0,-1,0,191,191,"","",1,"","","",2,0,0,[],""],["palau_cantares-01697",4,"¡Qué bien se aman los novios\ncuando hacen ambo!;\nmas cuando ya hacen terno\nles lleva el diablo:\n¡extraño juego,\ndonde con más guarismos\nse gana menos!",4,0,-1,71,"",4,7,"eo",-1,0,-1,0,191,191,"","",1,"","","",1,0,0,[],""],["palau_cantares-01698",4,"El que suspira piensa\nque así descansa,\ny si es de amor, aviva\nmejor la llama:\nse inflama el pecho,\ny cuanto más suspira,\ntoma más cuerpo.",4,0,-1,71,"",4,7,"eo",-1,0,-1,0,191,191,"","",1,"","","",2,0,0,[],""],["palau_cantares-01699",4,"Para olvidar amando\nno hay otro medio\nque nuevo amor, ó puesta\ntierra por medio:\nque estando ausente,\nse olvida lo pasado\npor lo presente.",4,0,-1,71,"",4,7,"ee",15,0,-1,0,191,191,"","",1,"","","",2,0,0,[],""],["palau_cantares-01700",4,"En suspiros no fíes,\nque no es prudente\nfiarse de una cosa\nque es aire leve;\nyo he conocido\namantes que han durado\nlo que el suspiro.",4,0,-1,71,"",4,7,"io",-1,0,-1,0,191,191,"","",1,"","","",1,0,0,[],""],["palau_cantares-01701",4,"Caminaba la ausencia\npor un camino,\ny el olvido seguía\nsus pasos mismos:\nque es consiguiente\nque el olvido á la ausencia\nla siga siempre.",4,0,-1,71,"",4,7,"ee",-1,0,-1,0,191,191,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01702",4,"Cuando el suspiro es aire\ny amor es fuego,\nlo reprimo en el alma\npor no encenderlo:\nporque esta llama,\nuna vez encendida,\ntarde se apaga.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,191,191,"","",1,"","","",1,0,0,[],""],["palau_cantares-01703",4,"Todo aquel que ama mucho\nvivirá poco;\npero aunque mucho viva,\nse le hará un soplo:\nfavorecido,\nlas horas son minutos,\nhoras los siglos.",4,0,-1,71,"",4,7,"io",-1,0,-1,0,191,191,"","",1,"","","",1,0,0,[],""],["palau_cantares-01704",4,"Si un afligido pecho\nno suspirara,\nel rigor de su pena\nlo devorara:\nque los suspiros\nno son la menor parte\npara el alivio.",4,0,-1,71,"",4,7,"io",-1,0,-1,0,191,191,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01705",4,"Todos dicen que aman,\ntodos que adoran,\npero todos olvidan\ncuando no logran;\ny, en tal mudanza,\nlos hombres y mujeres\ntodos se igualan.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,191,191,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01706",4,"Jugadores y amantes\nson gente rara,\npues nunca están contentos\ncon lo que ganan:\nriñen si pierden,\ny si alguna vez ganan,\nganar más quieren.",4,0,-1,71,"",4,7,"ee",-1,0,-1,0,191,191,"","",1,"","","",1,0,0,[],""],["palau_cantares-01707",4,"Quien desconfía agravia\nal dueño amado,\npero muchos se pierden\ndesconfiados.\nNo descuidarse,\nque tal vez el más listo\nsuele engañarse.",4,0,-1,71,"",4,7,"ae",250,0,-1,0,191,191,"","",1,"","","",2,0,0,[],""],["palau_cantares-01708",4,"Si la pasión te ciega,\nmira primero\ndónde pones los ojos,\nno llores luego:\nlos ojos abre,\nmira que cuando acuerdes\nya será tarde.",4,0,-1,71,"",4,7,"ae",-1,0,-1,0,192,192,"","",1,"","","",3,0,0,[],""],["palau_cantares-01709",4,"Como el amor te tome\nmuy de su cuenta,\ndespedirte ya puedes\nde la prudencia:\nporque es un loco,\ny en entrando en la casa\nlo enreda todo.",4,0,-1,71,"",4,7,"oo",-1,0,-1,0,192,192,"","",1,"","","",1,0,0,[],""],["palau_cantares-01710",4,"El que quisiere, amando,\nvivir sin pena,\ndebe tomar el tiempo\nconforme venga:\nquiera querido,\ny cuando le desprecien,\nhaga lo mismo.",4,0,-1,71,"",4,7,"io",-1,0,-1,0,192,192,"","",1,"","","",3,0,0,[],""],["palau_cantares-01711",4,"El carácter del hombre,\nsi bien se advierte,\nno es el que manifiesta\ncuando pretende:\nque, en tales casos,\nel soberbio es humilde\ny el necio sabio.",4,0,-1,71,"",4,7,"ao",-1,0,-1,0,192,192,"","",1,"","","",2,0,0,[],""],["palau_cantares-01712",4,"Si las mujeres tuvieran\nla libertad de los hombres,\ná los caminos salieran\ná robar los corazones.",4,0,-1,71,"",0,4,"oe",-1,0,-1,0,192,192,"","",1,"rm_t4, carrizo_salta, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01713",4,"Aunque me digan la fea,\nno me tengo de enfadar,\nporque siempre la más fea\nse lleva el mejor galán.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,192,192,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01714",4,"El amor que siente el hombre\nes como la leña verde,\nque llena la casa de humo\ny luego desaparece.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,192,192,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01715",4,"Todo el hombre que no cae\ná los primeros revuelos,\nen llegando á veinticinco\nnecesita lazo nuevo.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,192,192,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01716",4,"El amor de las mujeres\nes como día nublado,\nque tiene más pareceres\nque leyes un abogado.",4,0,-1,71,"",1,4,"ao",14,0,-1,0,192,192,"","",1,"lafuente_madrid","","",18,0,0,[],""],["palau_cantares-01717",4,"Todo el que quiere casarse\najusta la cuenta alegre;\nluego, después de casado,\nla repasa y no la entiende.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,192,192,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01718",4,"El amor de las mujeres\nsuele ser como el del perro,\nque aunque le sacudan palos,\nnunca desampara al dueño.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,192,192,"","",1,"rm_t4, lafuente_madrid","","",18,0,0,[],""],["palau_cantares-01719",4,"Perlita, cásate á gusto,\nque tus padres morirán;\nno vendrán del otro mundo\ná ver si lo pasas mal.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,192,192,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01720",4,"A la mujer la comparo\ncon el águila real;\nen acercándose á ella,\nella se remonta más.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,192,192,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-01721",4,"Cásate, bella madama,\ny te dirán parabienes,\ny luego irás á comer\ná tu casa, si la tienes.",4,0,-1,71,"",0,4,"ee",120,0,-1,0,192,192,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01722",4,"Las mujeres son ladronas\nque les quitan á los hombres\nla luz del entendimiento,\naunque la razón les sobre.",4,0,-1,71,"",0,4,"oe",-1,0,-1,0,192,192,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01723",4,"Cásate, Juan, en domingo,\nlunes estarás casado,\ny el martes preguntarás\ndónde dan el pan fiado.",4,0,-1,71,"",0,4,"ao",14,0,-1,0,192,192,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01724",4,"La palabra de los hombres\nes como la caña vana,\nque de lo que dicen hoy\nya no se acuerdan mañana.",4,0,-1,71,"",0,4,"aa",4,0,-1,0,192,192,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01725",4,"No quieras casa caída,\nni paredes derrumbadas,\nni casamiento á disgusto:\ndonde no hay gusto, no hay nada.",4,0,-1,71,"",0,4,"aa",-1,0,-1,0,192,192,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01726",4,"El hombre que se casa\npor el dinero\nno mira la cadena\nque se echa al cuello:\nque mujer rica\nes bruto que no sufre\nfreno ni brida.",4,0,-1,71,"",4,7,"ia",-1,0,-1,0,193,193,"","",1,"","","",5,0,0,[],""],["palau_cantares-01727",4,"La que hiciere almoneda\nde sus favores,\nmire que ha de fiarlos\nal que los compre:\nporque el secreto\nha de correr de cuenta\ndel pregonero.",4,0,-1,71,"",4,7,"eo",-1,0,-1,0,193,193,"","",1,"","","",1,0,0,[],""],["palau_cantares-01729",4,"Anoche soñé un ensueño,\nque yo tengo por verdad:\nen estando un hombre ausente,\notro ocupa su lugar.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,193,193,"","",1,"lafuente_madrid","","",7,0,0,[],""],["palau_cantares-01730",4,"Cuando dos quieren á una\ny los dos están presentes,\nel uno cierra los ojos\ny el otro aprieta los dientes.",4,0,-1,71,"",0,4,"ee",252,0,-1,0,193,193,"","",1,"rm_t4, frenk_t2, lafuente_madrid","","",8,0,0,[],""],["palau_cantares-01731",4,"El que se retira y vuelve\nno tiene ningún delito,\nque el águila se remonta\ny vuelve á su mismo sitio.",4,0,-1,71,"",0,4,"io",-1,0,-1,0,193,193,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01732",4,"Cuando uno quiere á una\ny esta una no le quiere,\nes lo mismo que si un calvo\nse encuentra en la calle un peine.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,193,193,"","",1,"","","",5,0,0,[],""],["palau_cantares-01733",4,"El amor que se va y vuelve\nlo tengo yo comparado\ncon los niños de la escuela,\nque siempre van disgustados.",4,0,-1,71,"",0,4,"ao",-1,0,-1,0,193,193,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01734",4,"Cuando en la calle se encuentran\npersonas que se han querido,\nó se les muda el color,\nse les quita el sentido.",4,0,-1,71,"",0,4,"io",101,0,-1,0,193,193,"","",1,"","","",3,0,0,[],""],["palau_cantares-01735",4,"¡Qué bien dijo aquel que dijo,\nquejándose de los celos:\n—No hay cosa para el olvido\nque otro amor, ó tierra en medio!",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,193,193,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01736",4,"¿Qué harán dos que amando se hallan\nheridos de una centella?\nElla de vergüenza calla,\ny él calla de temor de ella.",4,0,-1,71,"",0,4,"ea",6,0,-1,0,193,193,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01737",4,"Al que lo quieren de balde\nno venga pidiendo celos,\nque harto favor se le hace\ncon quererlo pelo á pelo.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,193,193,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01738a",4,"Amor resucitado\nyo no lo quiero,\nporque siempre á mortaja\nme estará oliendo;\ny yo me asusto\ncon las cosas que vienen\ndel otro mundo.",4,0,-1,71,"",4,7,"uo",-1,0,-1,0,194,194,"","",1,"","","",2,0,0,[],""],["palau_cantares-01738b",4,"Una me dijo que sí,\notra me dijo que no;\nla del sí quería ella,\nla del no quería yo.",4,0,-1,71,"",0,4,"o",2,0,-1,0,194,194,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01738c",4,"Cuando se ve que van juntos\nuna mujer con un hombre,\nles han de achacar aquello\nque cada cual se supone.",4,0,-1,71,"",0,4,"oe",-1,0,-1,0,194,194,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01738d",4,"Compadre que á su comadre\nno le dice adónde va,\nno es compadre ni es comadre,\nni se tienen voluntad.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,194,194,"","",1,"","","",2,0,0,[],""],["palau_cantares-01738e",4,"Una mujer fué la causa\nde la perdición primera:\nno hay perdición en el mundo\nque por mujeres no venga.",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,194,194,"","",1,"rm_t4, carrizo_salta, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01738f",4,"Quien se fíe de las hembras\ny en sus halagos creyere,\nsi no se ahorcase á sí mismo,\nserá porque ellas lo hicieren.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,194,194,"","",1,"lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01738g",4,"No te fíes de los hombres\naunque lloren á tus plantas,\nque son como los pepinos,\nque vienen á temporadas.",4,0,-1,71,"",0,4,"aa",-1,0,-1,0,194,194,"","",1,"rm_t4","","",16,0,0,[],""],["palau_cantares-01738h",4,"No te fíes de los hombres\nque tienen poca firmeza\ny se mudan la camisa\nlo mismo que las culebras",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,194,194,"","",1,"rm_t4, lafuente_madrid","","",16,0,0,[],""],["palau_cantares-01738i",4,"No te fíes de mujeres\naunque las veas llorar,\nque con sus lágrimas riegan\nlas calabazas que dan.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,194,194,"","",1,"rm_t4, carrizo_salta, lafuente_madrid, fernan_caballero","","",6,0,0,[],""],["palau_cantares-01739",4,"Al hombre falso y sin ley\ntrátalo con segundilla;\npor si acaso te echa el rey,\njuégale tú la malilla.",4,0,-1,71,"",1,4,"ia",162,0,-1,0,194,194,"","",1,"","","",2,0,0,[],""],["palau_cantares-01739-e10",4,"No fíes en amores,\nque es desvarío\ntener seguridades\nde otro albedrío.",4,0,-1,71,"",6,4,"io",3,0,-1,0,194,194,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01739-e2",4,"El que de una dama bella\nquisiera ser bien querido,\nque haga poco caso de ella,\nque yo lo tengo advertido.",4,0,-1,71,"",1,4,"io",101,0,-1,0,194,194,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01739-e3",4,"Más quisiera en una plaza\ná un toro bravo esperar,\nque no á una mujer que diga:\n¿qué cuidado se me da?",4,0,-1,71,"",0,4,"a",-1,0,-1,0,194,194,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01739-e4",4,"La que quiere ser amada\nsin tener correspondencia,\nquiere conservar el fuego\nsin la pensión de echar leña.",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,194,194,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01739-e5",4,"La niña que tiene uno\ny pretende tener dos,\nse quedará sin ninguno,\nque así lo dispone Dios.",4,0,-1,71,"",1,4,"o",87,0,-1,0,194,194,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01739-e6",4,"La dama que quiere á dos\nno es tonta, que es advertida:\nsi una vela se le apaga,\notra le queda encendida.",4,0,-1,71,"",0,4,"ia",37,0,-1,0,194,194,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01739-e7",4,"La mujer que se enamora\nde la ropa y no del hombre,\nno tiene vergüenza en cara,\nporque la ropa se rompe.",4,0,-1,71,"",0,4,"oe",-1,0,-1,0,194,194,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",5,0,0,[],""],["palau_cantares-01739-e8",4,"Si, á pesar de desdenes,\ndura el afecto,\npasión es incurable\ny amor perfecto.",4,0,-1,71,"",6,4,"eo",256,0,-1,0,194,194,"","",1,"","","",2,0,0,[],""],["palau_cantares-01739-e9",4,"Quien ama y no se explica,\nsin duda es muerto;\npues sabiendo la causa,\ncalla el remedio.",4,0,-1,71,"",6,4,"eo",-1,0,-1,0,194,194,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01740",4,"No por antecedentes\namor infieras,\nque suelen salir falsas\nlas consecuencias.",4,0,-1,71,"",6,4,"ea",-1,0,-1,0,195,195,"","",1,"preciso_coleccion","","",2,0,0,[],""],["palau_cantares-01740-e10",4,"El amor es un fuego\ncuya materia,\ncuanto más se consume,\nmás se fomenta.",4,0,-1,71,"",6,4,"ea",-1,0,-1,0,195,195,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01740-e2",4,"Si acaso saber quieres\nsi dos se aman,\nrepara si se miran\nmás que se hablan.",4,0,-1,71,"",6,4,"aa",-1,0,-1,0,195,195,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01740-e3",4,"No quiero amor con casada,\nque me ha dicho una viuda\nque á quien de ajeno se viste\nen la calle lo desnudan.",4,0,-1,71,"",0,4,"ua",-1,0,-1,0,195,195,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01740-e4",4,"No quiero más amistades,\nquiero seguir mi opinión,\nque de pasión con extremos\nresulta una perdición.",4,0,-1,71,"",0,4,"o",31,0,-1,0,195,195,"","",1,"lafuente_madrid, preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01740-e5",4,"Si se te apaga el cigarro,\nno lo vuelvas á encender;\nsi te despide la novia,\nno la vuelvas á querer.",4,0,-1,71,"",0,4,"e",20,0,-1,0,195,195,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01740-e6",4,"No te enamores, serrana,\nde niño de poca edad,\nque como le falta el tiempo,\nle falta la voluntad.",4,0,-1,71,"",0,4,"a",16,0,-1,0,195,195,"","",1,"rm_t4, carrizo_salta","","",5,0,0,[],""],["palau_cantares-01740-e7",4,"No te enamores, mi niña,\nde mocito forastero,\nque en volviendo las espaldas,\nsi te he visto, no me acuerdo.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,195,195,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01740-e8",4,"No elijas mujer ni tela\ná la luz artificial,\nporque la una y la otra\ngrandes chascos suelen dar.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,195,195,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01740-e9",4,"Es amor una senda\ntan sin camino,\nque el que va más derecho\nva más perdido.",4,0,-1,71,"",6,4,"io",-1,0,-1,0,195,195,"","",1,"rm_t4, carrizo_salta","","",3,0,0,[],""],["palau_cantares-01741",4,"A los hombres de ahora\nquererlos poco,\ny en ese poco tiempo\nvolverlos locos:\nporque los hombrés,\nen viéndose queridos,\nno corresponden.",4,0,-1,71,"",4,7,"oe",-1,0,-1,0,195,195,"","",1,"","","",5,0,0,[],""],["palau_cantares-01741-e2",4,"Nadie de amor se burle,\ny en mí escarmiente,\nporque el amor se burla\nde sus rebeldes;\nque yo me acuerdo\nque desprecié sus grillos\ny ahora los beso.",4,0,-1,71,"",4,7,"eo",-1,0,-1,0,195,195,"","",1,"preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01741-e3",4,"El más sabio se atribula;\nquien tiene razón, la pierde;\nprevarica del sentido\naquel que quiere y no puede.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,195,195,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01741-e4",4,"Es tanto lo que apasiona\nuna muchacha bonita,\nque al hombre de más valor\nel corazón le palpita.",4,0,-1,71,"",0,4,"ia",50,0,-1,0,195,195,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01741-e5",4,"No creas en ofertas\nde los amantes,\nque son como en borrasca\nlos navegantes;\ndan mil palabras,\ny las olvidan luego\nque desembarcan.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,195,195,"","",1,"","","",1,0,0,[],""],["palau_cantares-01741-e6",4,"Huye de amor, si quieres\ntener sosiego:\nmira que son pesados\ntodos sus juegos;\ny si te coge,\nnunca podrás librarte\nde sus prisiones.",4,0,-1,71,"",4,7,"oe",-1,0,-1,0,195,195,"","",1,"","","",1,0,0,[],""],["palau_cantares-01741-e7",4,"Llora, gime, suspira,\nsiente, y al cabo\nlo que logra un amante\nson desengaños:\nque al menor soplo\nse convierten en humo\nde amor los logros.",4,0,-1,71,"",4,7,"oo",-1,0,-1,0,195,195,"","",1,"","","",2,0,0,[],""],["palau_cantares-01742a",4,"Nadie se ponga á querer,\nque el querer quita el sentido:\nlo digo por experiencia,\nporque á mí me ha sucedido.",4,0,-1,71,"",0,4,"io",101,0,-1,0,196,196,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01742b",4,"Los amantes parecen\ná los ladrones,\nque buscan á escondidas\nlas ocasiones.",4,0,-1,71,"",6,4,"oe",34,0,-1,0,196,196,"","",1,"","","",1,0,0,[],""],["palau_cantares-01743",4,"Amor es una escuela\nde desengaños,\nque en ella siempre aprenden\naun los más sabios;\npero aunque aprendan,\nciegos en sus pasiones,\nnunca escarmientan.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,196,196,"","",1,"","","",3,0,0,[],""],["palau_cantares-01744",4,"Cuando dos se quieren bien,\ncon los ojos se saludan;\nque también los ojos hablan\ncuando la lengua está muda.",4,0,-1,71,"",0,4,"ua",-1,0,-1,0,196,196,"","",1,"rm_t4, lafuente_madrid, huambachano","","",9,0,0,[],""],["palau_cantares-01745",4,"«Amor es un enredo,»\ndicen los sabios;\npero yo veo á muchos\nmuy enredados:\nde lo que infiero\nque son muy dulces lazos\nlos de este enredo.",4,0,-1,71,"",4,7,"eo",-1,0,-1,0,196,196,"","",1,"preciso_coleccion","","",3,0,0,[],""],["palau_cantares-01746",4,"A toda mujer que vieres\namarilla y con ojeras,\nno le preguntes qué tiene,\nporque es que quiere de veras.",4,0,-1,71,"",0,4,"ea",103,0,-1,0,196,196,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01747",4,"Yo le he preguntado á un sabio\ncómo se olvida un querer;\nel sabio me ha contestado:\n«No hay cosa como no ver.»",4,0,-1,71,"",0,4,"e",20,0,-1,0,196,196,"","",1,"","","",5,0,0,[],""],["palau_cantares-01748",4,"A aquel que quiere de veras\nun tiro le habían de dar;\nni come, ni bebe á gusto,\nni lo dejan sosegar.",4,0,-1,71,"",0,4,"a",21,0,-1,0,196,196,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01749",4,"Las suelen llamar flacas\ná las mujeres;\nmás flacos son los hombres,\nque ellas los vencen:\ny á vencer una\nno bastan muchos hombres\nsi ella no gusta.",4,0,-1,71,"",4,7,"ua",-1,0,-1,0,196,196,"","",1,"","","",2,0,0,[],""],["palau_cantares-01750a",4,"Una vela se consume\ná fuerza de mucho arder;\nasí se consume un hombre\nal lado de una mujer.",4,0,-1,71,"",0,4,"e",20,0,-1,0,196,196,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",7,0,0,[],""],["palau_cantares-01750b",4,"Esperar y no venir,\nquerer y que no lo quieran,\nacostarse y no dormir,\n¿cuál será la mayor pena?",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,196,196,"","",1,"rm_t4, lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01750c",4,"A la luz de la razón\nhe venido á conocer\nque son fatigas de muerte\nel querer y no poder.",4,0,-1,71,"",0,4,"e",20,0,-1,0,196,196,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01750d",4,"Es amor una rueda\nque nunca para;\ná unos los sube mucho\ny á otros los baja.\nTengan cuidado,\nporque tiene esta rueda\nmuchos rodando.",4,0,-1,71,"",4,7,"ao",-1,0,-1,0,196,196,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01751",4,"La que fíe de un hombre\ndebe primero\nhacer de él experiencias\nun siglo entero:\ny aun puede al cabo\nque el que parezca bueno\nle salga malo.",4,0,-1,71,"",4,7,"ao",-1,0,-1,0,196,196,"","",1,"","","",1,0,0,[],""],["palau_cantares-01751-e2",4,"Que los tiempos se mudan,\ndicen, y mienten;\nlos tiempos no se mudan,\nque son las gentes:\ny esta sentencia\nles comprende á los hombres\nmás que á las hembras.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,196,196,"","",1,"","","",1,0,0,[],""],["palau_cantares-01751-e3",4,"Pedernal que no echa lumbre\ny cuchillo que no corta,\ny el amor que no es constante,\nque se pierdan poco importa.",4,0,-1,71,"",0,4,"oa",265,0,-1,0,196,196,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01752a",4,"Amor con amor se paga,\ny con otra cosa no;\nlo que no tuviere cuenta,\nolvidarlo es lo mejor.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,197,197,"","",1,"lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01752b",4,"Pasan las dichas del mundo,\npasa la vida y el tiempo;\nlo que no pasa jamás\nes el amor verdadero.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,197,197,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01752c",4,"Amores de largo tiempo\n¡qué malos de olvidar son,\nporque han echado raíces\nen medio del corazón!",4,0,-1,71,"",0,4,"o",31,0,-1,0,197,197,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01752d",4,"Una pena quita pena,\nun dolor quita dolor,\nun clavo saca otro clavo,\npero amor no quita amor.",4,0,-1,71,"",0,4,"o",72,0,-1,0,197,197,"","",1,"rm_t4, lafuente_madrid, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01752e",4,"No ama mucho quien lo dice,\nsino quien mucho padece,\nporque amor sin penas y obras\nde amor sólo el nombre tiene.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,197,197,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01752f",4,"Desde aquel primer instante\nque abre el corazón sus puertas,\naunque las burle un amante,\nlas suele tener abiertas.",4,0,-1,71,"",1,4,"ea",251,0,-1,0,197,197,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01752g",4,"Alza la voz, pregonero,\ny en el primer renglón di:\n«No hay plazo que no se cumpla,\nni amor que no tenga fin»",4,0,-1,71,"",0,4,"i",-1,0,-1,0,197,197,"","",1,"rm_t4, lafuente_madrid","","",9,0,0,[],""],["palau_cantares-01753",4,"Yo crié en mi rebaño\nmansa cordera,\nque de tanto mimarla\nse volvió fiera:\nque las mujeres,\ná fuerza de mimarlas,\nfieras se vuelven.",4,0,-1,71,"",4,7,"ee",-1,0,-1,0,197,197,"","",1,"","","",1,0,0,[],""],["palau_cantares-01753-e2",4,"Quien cariño en mujeres\npusiere loco,\npierde mujer, cariño,\nlo pierde todo:\nque las mujeres,\nmientras más las queremos,\nmenos nos quieren.",4,0,-1,71,"",4,7,"ee",-1,0,-1,0,197,197,"","",1,"","","",2,0,0,[],""],["palau_cantares-01753-e3",4,"Quien camina de prisa,\npoco adelanta,\nque nada se hace bueno\ncon prisa tanta:\npues se ha notado\nque el que va más de prisa,\nva más despacio.",4,0,-1,71,"",4,7,"ao",-1,0,-1,0,197,197,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01753-e4",4,"Si enfermedades llamas\ná mis consejos,\nla salud que tú tienes\ntener no quiero:\ncura tus males\ncon lo mismo que llamas\nenfermedades.",4,0,-1,71,"",4,7,"ae",-1,0,-1,0,197,197,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01753-e5",4,"Colíganse por plantar\nun ambicioso proyecto\nlas dos potencias mayores,\nvoluntad y entendimiento.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,197,197,"","",1,"","","",1,0,0,[],""],["palau_cantares-01754",4,"Aquel si viene ó no viene,\naquel si sale ó no sale,\nen los amores no tiene\ncontento que se le iguale.",4,0,-1,71,"",1,4,"ae",202,0,-1,0,197,197,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01755",4,"La naturaleza humana,\nsegún por sus hijos veo,\ncreó gigante el deseo\ny la posesión enana.",4,0,-1,71,"",11,4,"aa",4,0,-1,0,197,197,"","",1,"","","",2,0,0,[],""],["palau_cantares-01756",4,"Amantes que siempre riñen\ny que jamás escarmientan,\nen llegando á conformarse,\n¡Dios nos la depare buena!",4,0,-1,71,"",0,4,"ea",-1,0,-1,0,197,197,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01757",4,"La misma resistencia\nla mujer tiene\nque una gasa prendida\ncon alfileres.",4,0,-1,71,"",6,4,"ee",-1,0,-1,0,197,197,"","",1,"rm_t4, suspiros_amor","","",3,0,0,[],""],["palau_cantares-01758",4,"Los amantes y la luna\nson en todo semejantes:\nentran en cuarto creciente,\nsalen en cuarto menguante.",4,0,-1,71,"",0,4,"ae",-1,0,-1,0,197,197,"","",1,"","","",2,0,0,[],""],["palau_cantares-01759",4,"Píldoras y verdades,\ncuando no agradan,\nse doran; que con oro\ntodo se traga.",4,0,-1,71,"",6,4,"aa",-1,0,-1,0,197,197,"","",1,"","","",1,0,0,[],""],["palau_cantares-01760a",4,"Mañanita de San Juan\ncuajan la almendra y la nuez:\ntambién cuajan los amores\ncuando dos se quieren bien.",4,0,-1,71,"",0,4,"e",-1,0,-1,0,198,198,"","",1,"","","",4,0,0,[],""],["palau_cantares-01760b",4,"De los sabios de este mundo\naquel que supiere más\nmételo tú en el querer,\nlo verás prevaricar.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,198,198,"","",1,"","","",2,0,0,[],""],["palau_cantares-01761",4,"Es el amor pescado,\ny en su comida\nencuentran los amantes\nmuchas espinas;\npero las pasan\npor los dulces bocados\nque á veces hallan.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,198,198,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01762",4,"Conocí á un hombre de bien,\ntan cabal como el reloj,\nque se metió en el querer\ny en un hospital murió.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,198,198,"","",1,"","","",1,0,0,[],""],["palau_cantares-01763",4,"Ya no son los amores\ncomo eran antes,\nque eran adoraciones\nde los amantes:\nporque las damas\npasaron de divinas\ná ser humanas.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,198,198,"","",1,"","","",1,0,0,[],""],["palau_cantares-01764",4,"Las mujeres y el vino\nson semejantes:\ncon el aire solano\nsuelen picarse;\naunque se hallan\nmuchas que á todos aires\nestán picadas.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,198,198,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01765",4,"Es el amor un bicho\nque, cuando pica,\nno se encuentra remedio\nni en la botica;\nporque sus males,\nsi el cura no los cura,\nson incurables.",4,0,-1,71,"",4,7,"ae",-1,0,-1,0,198,198,"","",1,"","","",4,0,0,[],""],["palau_cantares-01766",4,"Si en los hombres no hubiera\nextravagancias,\nlas feas vivirían\nsin esperanza.",4,0,-1,71,"",6,4,"aa",-1,0,-1,0,198,198,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01766-e2",4,"Todo hombre que se casa\nse parece al caracol,\nque se echa la casa á cuestas\ncon más fatigas que Dios.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,198,198,"","",1,"","","",3,0,0,[],""],["palau_cantares-01766-e3",4,"Es amor un comercio\nde tantas quiebras,\nque en él aquel que gana\nperdido queda;\ny al fin y al cabo,\nsi hay alguna ganancia,\nla lleva el diablo.",4,0,-1,71,"",4,7,"ao",-1,0,-1,0,198,198,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01766-e4",4,"Aunque amor es oficio,\nno tiene examen,\nporque viejos y niños\ntodos lo saben;\ny en sus talleres\nlas mejores lecciones\ndan las mujeres.",4,0,-1,71,"",4,7,"ee",55,0,-1,0,198,198,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01767",4,"Es el amor un monte\nmuy elevado,\ny á la cumbre se sube\ncon gran trabajo;\ny estando arriba,\nes peligrosa y fácil\ncualquier caída.",4,0,-1,71,"",4,7,"ia",-1,0,-1,0,198,198,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01767-e2",4,"El amor es una cosa,\n¡Dios nos libre y Dios nos guarde!,\nque hace perder los sentidos\nal que los tiene cabales.",4,0,-1,71,"",0,4,"ae",-1,0,-1,0,198,198,"","",1,"rm_t4, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01767-e3",4,"El amor es un bichito\nque por los ojos se mete,\ny en llegando al corazón,\nda fatiguillas de muerte.",4,0,-1,71,"",0,4,"ee",-1,0,-1,0,198,198,"","",1,"rm_t4, lafuente_madrid","","",10,0,0,[],""],["palau_cantares-01767-e4",4,"El amor es como el niño,\nque se enoja y tira el pan,\ny en haciéndole cariños,\ncalla y lo vuelve á tomar.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,198,198,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01767-e5",4,"Entra el amor por los ojos,\nse deposita en el pecho,\nle alimentan los oídos\ny le matan los desprecios.",4,0,-1,71,"",0,4,"eo",-1,0,-1,0,198,198,"","",1,"lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01768",4,"Nace amor como una planta\nen amante corazón,\nlo alimenta la esperanza,\ndespués lo seca el rigor.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,201,201,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01769",4,"Los primeros amores\nno sé qué tienen;\nse meten en el alma,\nsalir no pueden.",4,0,-1,71,"",6,4,"ee",-1,0,-1,0,201,201,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01770",4,"Los primeros amores\nson los que privan,\naunque algunos autores\nlo contradigan.",4,0,-1,71,"",6,4,"ia",-1,0,-1,0,201,201,"","",1,"","","",3,0,0,[],""],["palau_cantares-01771",4,"La que con muchos trata\ny es retrechera,\nquedará para tía\naunque no quiera:\ncuadre ó no cuadre,\nsólo si fuera monja\nle dirán madre.",4,0,-1,71,"",4,7,"ae",166,0,-1,0,201,201,"","",1,"","","",2,0,0,[],""],["palau_cantares-01772a",4,"La pasión oprimida\nes como el rayo:\ncuanta más resistencia,\nmayor estrago.",4,0,-1,71,"",6,4,"ao",-1,0,-1,0,201,201,"","",1,"","","",3,0,0,[],""],["palau_cantares-01772b",4,"Amores escondidos\npor tiempo largo,\nsi en tragedia no acaban,\nserá milagro.",4,0,-1,71,"",6,4,"ao",-1,0,-1,0,201,201,"","",1,"rm_t4, carrizo_salta, preciso_coleccion","","",4,0,0,[],""],["palau_cantares-01772c",4,"Entre ceniza envuelta\nla lumbre vive:\ncuanto más retirado,\namor más firme.",4,0,-1,71,"",6,4,"ie",-1,0,-1,0,201,201,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01772d",4,"Carbón que ha sido lumbre\ntengo entendido\nque luego, á poco soplo,\nqueda encendido.",4,0,-1,71,"",6,4,"io",101,0,-1,0,201,201,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01772e",4,"¿De qué sirve la riña\nde dos amantes,\ncuando están reventando\npor hacer paces?",4,0,-1,71,"",6,4,"ae",-1,0,-1,0,201,201,"","",1,"","","",2,0,0,[],""],["palau_cantares-01773a",4,"El médico me receta,\nviendo que es mi mal de amor:\nonza y media de escarmiento,\ny de desengaño dos.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,201,201,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-01773b",4,"Yo le pregunté á un casado:\n- Casado, ¿cómo te va?\nY él me respondió: - Soltero,\ncásate tú y lo verás.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,201,201,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01773c",4,"Si fueres á buscar novia,\nque no sea en romería,\nsino en casa de su padre,\ncon ropita de aquel día.",4,0,-1,71,"",0,4,"ia",0,0,-1,0,201,201,"","",1,"lafuente_madrid, fernan_caballero","","",4,0,0,[],""],["palau_cantares-01773d",4,"¿Fuiste tú la que dijiste\nque no te casabas nunca?\nNo hay San Martín que no llegue,\nni plazo que no se cumpla.",4,0,-1,71,"",0,4,"ua",-1,0,-1,0,201,201,"","",1,"rm_t4","","",5,0,0,[],""],["palau_cantares-01774",4,"Las palabras amorosas\nson las cuentas de un collar:\nen saliendo la primera,\nsalen todas las demás.",4,0,-1,71,"",0,4,"a",-1,0,-1,0,201,201,"","",1,"frenk_t2","","",5,0,0,[],""],["palau_cantares-01775",4,"Cásate y tendrás mujer,\nsi es bonita, que guardar;\nsi es fea, que aborrecer;\nsi es rica, que contentar;\nsi es pobre, que mantener.",4,0,-1,71,"",7,5,"e",20,0,-1,0,201,201,"","",1,"rm_t4, lafuente_madrid","","",5,0,0,[],""],["palau_cantares-01776",4,"La mujer que sale mala,\nni reñirle ni pegarle;\nagarrarla de la mano\ny llevársela á su madre.",4,0,-1,71,"",0,4,"ae",-1,0,-1,0,201,201,"","",1,"rm_t4","","",7,0,0,[],""],["palau_cantares-01777",4,"Aprovecha el tiempo, niña,\ny no juegues con la suerte;\nque la vejez viene luego,\ny luego viene la muerte.",4,0,-1,71,"",0,4,"ee",134,0,-1,0,201,201,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01778",4,"A aquella mujer que quiere\nmandar más que su marido,\nSanto Cristo del garrote,\nleña del Verbo divino.",4,0,-1,71,"",0,4,"io",-1,0,-1,0,201,201,"","",1,"lafuente_madrid","","",2,0,0,[],""],["palau_cantares-01779",4,"Con su capa el torero\nmaneja el bicho,\ny la mujer al hombre\ncon su abanico",4,0,-1,71,"",6,4,"io",-1,0,-1,0,201,201,"","",1,"","","",2,0,0,[],""],["palau_cantares-01780",4,"Cupido, como niño,\nhizo diabluras,\ny ahora todos pagamos\nsus travesuras.",4,0,-1,71,"",3,4,"ua",238,0,-1,0,202,202,"","",1,"rm_t4","","",3,0,0,[],""],["palau_cantares-01781",4,"Se levanta el rey furioso,\ntoma la pluma y escribe,\ny en el primer renglón pone:\n«Quien tiene amores no vive.»",4,0,-1,71,"",0,4,"ie",190,0,-1,0,202,202,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01782",4,"No la busques bonita,\nporque á lo hermoso,\ncomo á la miel las moscas,\nrondan golosos;\ny algunas veces\npueden pegarse algunos\nque te la peguen.",4,0,-1,71,"",4,7,"ee",-1,0,-1,0,202,202,"","",1,"","","",1,0,0,[],""],["palau_cantares-01783",4,"Dejad llorar á las nubes,\ndejad alumbrar al sol,\ndejad al viejo quejarse\ny al mozo gozar su amor.",4,0,-1,71,"",0,4,"o",-1,0,-1,0,202,202,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01784",4,"No te cases, no te cases,\nmantente siempre mocita,\nque la rosa en el rosal\nsiempre está coloradita.",4,0,-1,71,"",0,4,"ia",50,0,-1,0,202,202,"","",1,"","","",4,0,0,[],""],["palau_cantares-01785a",4,"Todas las mañanas voy\ná preguntarle al romero\nsi el mal de amor tiene cura,\nporque yo de amores muero.",4,0,-1,71,"",0,4,"eo",38,0,-1,0,202,202,"","",1,"lafuente_madrid","","",12,0,0,[],""],["palau_cantares-01785b",4,"El mal de amor tiene cura\nen sabiéndolo curar,\nen queriendo ó no queriendo\nolvidar ó no olvidar.",4,0,-1,71,"",0,4,"a",21,0,-1,0,202,202,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01785c",4,"Al hombre que se enamora\ny tiene poca prudencia\nle vienen luego á dejar\ná la luna de Valencia.",4,0,-1,71,"",0,4,"ea",46,0,-1,0,202,202,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01785d",4,"Por más que reine el cariño,\nen llegándose á perder,\nno es fácil que se recobre\nsi Dios no pone el poder.",4,0,-1,71,"",0,4,"e",20,0,-1,0,202,202,"","",1,"rm_t4, lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01786",4,"No quiero que me dé nadie\nvalía de un alfiler,\nporque todo en este mundo\nse da por el interés.",4,0,-1,71,"",0,4,"e",-1,0,-1,0,202,202,"","",1,"rm_t4, lafuente_madrid","","",4,0,0,[],""],["palau_cantares-01787",4,"El amor es un pleito;\npero en su audiencia\nlas mujeres son parte,\ny ellas sentencian;\ny aunque lo ganen,\ncondenados en costas\nlos hombres salen.",4,0,-1,71,"",4,7,"ae",-1,0,-1,0,202,202,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01788",4,"Porfía, y conseguirás\ndel amor lo que quisieres;\nno son duros pedernales\nlos pechos de las mujeres.",4,0,-1,71,"",0,4,"ee",55,0,-1,0,202,202,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01790",4,"Quien ganar solicite\nde amor la palma,\ngaste poco cariño,\nbuenas palabras;\nporque las hembras,\nmás que cariño, quieren\npalabras buenas.",4,0,-1,71,"",4,7,"ea",-1,0,-1,0,202,202,"","",1,"","","",2,0,0,[],""],["palau_cantares-01791",4,"El amor que se oculta\nbajo el silencio,\nhace mayor estrago\ndentro del pecho;\nporque sus llamas,\ncomo no hallan salida,\nqueman el alma.",4,0,-1,71,"",4,7,"aa",-1,0,-1,0,202,202,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01792a",4,"Déjame rezar un Credo\nen aquesta losa fría\ndonde descansan los restos\nde la pobre madre mía.",4,0,-1,72,"",0,4,"ia",0,0,-1,0,203,203,"","",1,"","","",1,0,0,[],""],["palau_cantares-01792b",4,"Cuando murióse mi madre,\nyo los ojos le cerré,\ny la pobre, agradecida,\nlloró por última vez.",4,0,-1,72,"",0,4,"e",-1,0,-1,0,203,203,"","",1,"","","",1,0,0,[],""],["palau_cantares-01792c",4,"Tengo un bello pajarito\nque canta mejor que un ángel;\nes una cuna su jaula,\ny llama á mi esposa «madre.»",4,0,-1,72,"",0,4,"ae",-1,0,-1,0,203,203,"","",1,"","","",1,0,0,[],""],["palau_cantares-01793",4,"«No hay ninguna mujer buena,»\niba á decir ayer tarde:\nde pronto volví los ojos\ny vi venir á mi madre.",4,0,-1,72,"",0,4,"ae",-1,0,-1,0,203,203,"","",1,"","","",1,0,0,[],""],["palau_cantares-01794",4,"A los niños que duermen\nDios les bendice,\ny á aquellos que son malos\nles da lombrices.",4,0,-1,72,"",6,4,"ie",-1,0,-1,0,203,203,"","",1,"","","",2,0,0,[],""],["palau_cantares-01796",4,"Mi niño se va á dormir,\n¡ojalá fuera verdad\ny le durara el sueñito\ntres días como á San Juan.!",4,0,-1,72,"",0,4,"a",-1,0,-1,0,203,203,"","",1,"","","",1,0,0,[],""],["palau_cantares-01797",4,"El hombre que no se aflige\ncuando llora una mujer,\nni ha conocido á su madre,\nni sabe lo que es querer.",4,0,-1,72,"",0,4,"e",20,0,-1,0,203,203,"","",1,"","","",2,0,0,[],""],["palau_cantares-01798",4,"Duérmete, niño chiquito,\nduérmete y no llores más,\nque se irán los angelitos\npara no verte llorar.",4,0,-1,72,"",0,4,"a",-1,0,-1,0,203,203,"","",1,"fernan_caballero","","",3,0,0,[],""],["palau_cantares-01799",4,"¿Cómo quieres que tenga\ngusto y contento;?\nCasadita de un año,\nmi niño muerto.",4,0,-1,72,"",6,4,"eo",-1,0,-1,0,203,203,"","",1,"","","",14,0,0,[],""],["palau_cantares-01801",4,"La mano me duele\nde tanto llamar,\ny me ha respondido la madre del alma\ná la madrugá.",4,0,-1,72,"",3,4,"a",-1,0,-1,0,203,203,"","",1,"","","",2,0,0,[],""],["palau_cantares-01802a",4,"¡Ay soledad, soledad,\nsoledad triste de mí;\nno tengo padre ni madre,\nni quien se acuerde de mí!",4,0,-1,72,"",0,4,"i",-1,0,-1,0,204,204,"","",1,"","","",18,0,0,[],""],["palau_cantares-01803b",4,"Hay dos cosas en el mundo\nque no pueden olvidarse:\nel primer amor del alma\ny el cariño de una madre.",4,0,-1,72,"",0,4,"ae",-1,0,-1,0,204,204,"","",1,"rm_t4","","",2,0,0,[],""],["palau_cantares-01803c",4,"Dos besos tengo en el alma,\nque no se apartan de mí:\nel último de mi madre\ny el primero que te dí.",4,0,-1,72,"",0,4,"i",23,0,-1,0,204,204,"","",1,"machado_venezuela","","",2,0,0,[],""],["palau_cantares-01804a",4,"Salí al campo y le recé\ná la Soleá una salve,\ny luego la encomendé\npor el alma de mi madre.",4,0,-1,72,"",0,4,"ae",-1,0,-1,0,204,204,"","",1,"","","",1,0,0,[],""],["palau_cantares-01804b",4,"Si los muertos revivieran\ná fuerza de valentías,\nlevantara yo á mi padre\naunque perdiese la vida.",4,0,-1,72,"",0,4,"ia",-1,0,-1,0,204,204,"","",1,"","","",1,0,0,[],""],["palau_cantares-01805a",4,"El rosal cría la rosa,\nla clavellina el clavel,\nla madre cría á su hija\ny no sabe para quién.",4,0,-1,72,"",0,4,"e",-1,0,-1,0,204,204,"","",1,"","","",1,0,0,[],""],["palau_cantares-01805b",4,"Con sentimiento lloraba\nbuscando la madre mía:\n¿dónde volveré á encontrar\nmadre como la perdida?",4,0,-1,72,"",0,4,"ia",-1,0,-1,0,204,204,"","",1,"","","",1,0,0,[],""],["palau_cantares-01806",4,"Penas ti'e mi mare,\npenas tengo yo\nylas que más siento son las e miniare,\nque las mías no.",4,0,-1,72,"",3,4,"o",2,0,-1,0,204,204,"","",1,"","","",1,0,0,[],""],["palau_cantares-01806-e2",4,"Comparito mío,\ndiga usté á madre\nque por los ojitos que en la cara tiene\nno me desampare.",4,0,-1,72,"",3,4,"ae",-1,0,-1,0,204,204,"","",1,"","","",2,0,0,[],""],["palau_cantares-01808",4,"No tengo padre ni madre,\n¿á quién me arrimaré yo?\nMe arrimaré á un arbolito\nque eche fruto y no eche flor.",4,0,-1,72,"",0,4,"o",-1,0,-1,0,204,204,"","",1,"","","",4,0,0,[],""],["palau_cantares-01811",4,"Cuando te veo llorando,\nme dan ganas de reir:\nquien tiene madre y se queja\nno es hombre, que es un mandil.",4,0,-1,72,"",0,4,"i",-1,0,-1,0,204,204,"","",1,"","","",1,0,0,[],""],["palau_cantares-01812",4,"Tos los cementerios\nlos traigo yo andaos:\nla seportorita de mi pobre mare\nyo no la hejayao.",4,0,-1,72,"",3,4,"ao",-1,0,-1,0,204,204,"","",1,"","","",1,0,0,[],""],["palau_cantares-01813",4,"Murió mi madre, ¡ay de mí!\n¡Malhaya mi desventura!\nQue no hay quien pase trabajos\nmientras su madre le dura.",4,0,-1,72,"",0,4,"ua",17,0,-1,0,205,205,"","",1,"","","",1,0,0,[],""],["palau_cantares-01814",4,"Sí supiera er sitio\naonde la enterraron,\nyo sacaría tos sus güesesitos\npara embalsamarlos.",4,0,-1,72,"",3,4,"ao",-1,0,-1,0,207,207,"","",1,"","","",2,0,0,[],""],["palau_cantares-01814-e2",4,"En Puerta de Tierra,\nen aquel rincón\nestán los huesos de la madrecita.\nde mi corazón.",4,0,-1,72,"",3,4,"o",31,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01814-e3",4,"Maresita mía,\n¡qué buena gitana!,\nde un peasito de pan que tenía,\nla mitad me daba.",4,0,-1,72,"",3,4,"aa",-1,0,-1,0,207,207,"","",1,"","","",3,0,0,[],""],["palau_cantares-01814-e4",4,"Si cual tengo padre\ntuviera yo madre,\nno andarían esos hermanitos\nsin calor de nadie.",4,0,-1,72,"",3,4,"ae",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01814-e5",4,"Si la madrecita mía\nlevantara la cabeza,\nviera lo que estoy pasando\nde fatigas y de penas.",4,0,-1,72,"",0,4,"ea",-1,0,-1,0,207,207,"","",1,"","","",4,0,0,[],""],["palau_cantares-01814-e6",4,"Quien tiene madre y se queja,\nno debe escucharle nadie,\nque no hay pena sin consuelo\npara aquel que tiene madre.",4,0,-1,72,"",0,4,"ae",-1,0,-1,0,207,207,"","",1,"","","",2,0,0,[],""],["palau_cantares-01814-e7",4,"Dos cosas grandes tenemos,\ny fuera de ellas no hay más:\nuna madre aquí en la tierra\ny un Dios en la eternidad.",4,0,-1,72,"",0,4,"a",-1,0,-1,0,207,207,"","",1,"","","",2,0,0,[],""],["palau_cantares-01814-e8",4,"Ya murió la que yo amaba,\nya murió la madre mía:\nquien pierde el amor de madre,\npierde todo en esta vida.",4,0,-1,72,"",0,4,"ia",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01815-e2",4,"Lo pedí llorando,\n¡oh Virgen del Carmen!\nla salusita que á mí me sobra\ndádsela á mi padre.",4,0,-1,72,"",3,4,"ae",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01815-e3",4,"Diga usté á mi madre\nsi no echa de menos\naquel hijo suyo de las sus entrañas\ncuando está comiendo.",4,0,-1,72,"",3,4,"eo",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01815-e4",4,"El cielo vistió de luto,\nla tierra se echó á temblar,\nporque se ha muerto mi madre\ny no la vuelvo á ver más.",4,0,-1,72,"",0,4,"a",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01815-e5",4,"Deja que la bese,\ndéjamela ver\ná mi madrecita, madrecita mía,\npor última vez.",4,0,-1,72,"",3,4,"e",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01815-e6",4,"En el Hospital\nme dijo mi madre:\n«Ahite quedan dos hermanos chicos,\nno los desampares.»",4,0,-1,72,"",3,4,"ae",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01815-e7",4,"Jincarse e roíyas,\nque ya viene Dios:\nva á recibirlo la madre de mi alma,\nde mi corazón.",4,0,-1,72,"",3,4,"o",-1,0,-1,0,207,207,"","",1,"","","",2,0,0,[],""],["palau_cantares-01815-e8",4,"N ' el hospitalito\ná manita erecha\nayí tenía la madrita mía\nla camita_/?£•&&.",4,0,-1,72,"",3,4,"ia",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01817",4,"Me dijo mi mare\ncon los brazo ar cueyo:\n«Ahí te quean esos chorrecitos,\nque mires por eyos.»",4,0,-1,72,"",3,4,"eo",-1,0,-1,0,207,207,"","",1,"","","",2,0,0,[],""],["palau_cantares-01818",4,"Queditos los golpes,\nqueditos, por Dios,\nporque está mala la madre de mi alma,\nde mi corazón.",4,0,-1,72,"",3,4,"o",-1,0,-1,0,207,207,"","",1,"","","",1,0,0,[],""],["palau_cantares-01819",4,"Yo preso en la trena,\nmalita mi madre:\nel que hiciere caridad por ella,\nque Dios se lo pague.",4,0,-1,72,"",3,4,"ae",-1,0,-1,0,207,207,"","",1,"","","",2,0,0,[],""],["palau_cantares-01820-e3",4,"Aquel lucerito, madre,\nque va detrás de la luna,\nes el que á mí me acompaña\nla noche que voy de tuna.",4,0,-1,72,"",0,4,"ua",56,0,-1,0,208,208,"","",1,"lafuente_madrid","","",3,0,0,[],""],["palau_cantares-01820-e4",4,"En la tumba de una madre\nno hay una flor que seque\nmientras exista un buen hijo\nque con su llanto la riegue.",4,0,-1,72,"",0,4,"ee",-1,0,-1,0,208,208,"","",1,"","","",1,0,0,[],""],["palau_cantares-01820-e5",4,"Se alberga en mi calabozo\nuna mariposa blanca:\nes el alma de mi madre\nque viene á enjugar mis lágrimas.",4,0,-1,72,"",0,4,"aa",-1,0,-1,0,208,208,"","",1,"","","",1,0,0,[],""],["palau_cantares-01820-e6",4,"Ya no se acuerda mi madre\nde la vida que me dio,\nque me la encuentro en la calle\ny no me dice ni «adiós.»",4,0,-1,72,"",0,4,"o",-1,0,-1,0,208,208,"","",1,"","","",1,0,0,[],""]]);
